(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("demosthenes-orations-1-e", [{"sp": "HDR", "t": "Δημηγορίαι Αʹ–ΙΖʹ· Πρὸς Λεπτίνην"}, {"sp": "HDR", "t": "Ὀλυνθιακὸς Αʹ", "st": "1"}, {"sp": "N", "t": "ἀντὶ πολλῶν ἄν, ὦ ἄνδρες Ἀθηναῖοι, χρημάτων ὑμᾶς ἑλέσθαι νομίζω, εἰ φανερὸν γένοιτο τὸ μέλλον συνοίσειν τῇ πόλει περὶ ὧν νυνὶ σκοπεῖτε. ὅτε τοίνυν τοῦθ’ οὕτως ἔχει, προσήκει προθύμως ἐθέλειν ἀκούειν τῶν βουλομένων συμβουλεύειν· οὐ γὰρ μόνον εἴ τι χρήσιμον ἐσκεμμένος ἥκει τις, τοῦτ’ ἂν ἀκούσαντες λάβοιτε, ἀλλὰ καὶ τῆς ὑμετέρας τύχης ὑπολαμβάνω πολλὰ τῶν δεόντων ἐκ τοῦ παραχρῆμ’ ἐνίοις ἂν ἐπελθεῖν εἰπεῖν, ὥστ’ ἐξ ἁπάντων ῥᾳδίαν τὴν τοῦ συμφέροντος ὑμῖν αἵρεσιν γενέσθαι.", "st": "1.1"}, {"sp": "N", "t": "ὁ μὲν οὖν παρὼν καιρός, ὦ ἄνδρες Ἀθηναῖοι, μόνον οὐχὶ λέγει φωνὴν ἀφιεὶς ὅτι τῶν πραγμάτων ὑμῖν ἐκείνων αὐτοῖς ἀντιληπτέον ἐστίν, εἴπερ ὑπὲρ σωτηρίας αὐτῶν φροντίζετε· ἡμεῖς δ’ οὐκ οἶδ’ ὅντινά μοι δοκοῦμεν ἔχειν τρόπον πρὸς αὐτά. ἔστι δὴ τά γ’ ἐμοὶ δοκοῦντα, ψηφίσασθαι μὲν ἤδη τὴν βοήθειαν, καὶ παρασκευάσασθαι τὴν ταχίστην ὅπως ἐνθένδε βοηθήσετε (καὶ μὴ πάθητε ταὐτὸν ὅπερ καὶ πρότερον), πρεσβείαν δὲ πέμπειν, ἥτις ταῦτ’ ἐρεῖ καὶ παρέσται τοῖς πράγμασιν·", "st": "1.2"}, {"sp": "N", "t": "ὡς ἔστι μάλιστα τοῦτο δέος, μὴ πανοῦργος ὢν καὶ δεινὸς ἅνθρωπος πράγμασι χρῆσθαι, τὰ μὲν εἴκων, ἡνίκ’ ἂν τύχῃ, τὰ δ’ ἀπειλῶν (ἀξιόπιστος δ’ ἂν εἰκότως φαίνοιτο), τὰ δ’ ἡμᾶς διαβάλλων καὶ τὴν ἀπουσίαν τὴν ἡμετέραν, τρέψηται καὶ παρασπάσηταί τι τῶν ὅλων πραγμάτων.", "st": "1.3"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ ἐπιεικῶς, ὦ ἄνδρες Ἀθηναῖοι, τοῦθ’ ὃ δυσμαχώτατόν ἐστι τῶν Φιλίππου πραγμάτων, καὶ βέλτιστον ὑμῖν· τὸ γὰρ εἶναι πάντων ἐκεῖνον ἕν’ ὄντα κύριον καὶ ῥητῶν καὶ ἀπορρήτων καὶ ἅμα στρατηγὸν καὶ δεσπότην καὶ ταμίαν, καὶ πανταχοῦ αὐτὸν παρεῖναι τῷ στρατεύματι, πρὸς μὲν τὸ τὰ τοῦ πολέμου ταχὺ καὶ κατὰ καιρὸν πράττεσθαι πολλῷ προέχει, πρὸς δὲ τὰς καταλλαγάς, ἃς ἂν ἐκεῖνος ποιήσαιτ’ ἄσμενος πρὸς Ὀλυνθίους, ἐναντίως ἔχει.", "st": "1.4"}, {"sp": "N", "t": "δῆλον γάρ ἐστι τοῖς Ὀλυνθίοις ὅτι νῦν οὐ περὶ δόξης οὐδ’ ὑπὲρ μέρους χώρας πολεμοῦσιν, ἀλλ’ ἀναστάσεως καὶ ἀνδραποδισμοῦ τῆς πατρίδος, καὶ ἴσασιν ἅ τ’ Ἀμφιπολιτῶν ἐποίησε τοὺς παραδόντας αὐτῷ τὴν πόλιν καὶ Πυδναίων τοὺς ὑποδεξαμένους· καὶ ὅλως ἄπιστον, οἶμαι, ταῖς πολιτείαις ἡ τυραννίς, ἄλλως τε κἂν ὅμορον χώραν ἔχωσι.", "st": "1.5"}, {"sp": "N", "t": "ταῦτ’ οὖν ἐγνωκότας ὑμᾶς, ὦ ἄνδρες Ἀθηναῖοι, καὶ τἄλλ’ ἃ προσήκει πάντ’ ἐνθυμουμένους φημὶ δεῖν ἐθελῆσαι καὶ παροξυνθῆναι καὶ τῷ πολέμῳ προσέχειν εἴπερ ποτὲ καὶ νῦν, χρήματ’ εἰσφέροντας προθύμως καὶ αὐτοὺς ἐξιόντας καὶ μηδὲν ἐλλείποντας. οὐδὲ γὰρ λόγος οὐδὲ σκῆψις ἔθ’ ὑμῖν τοῦ μὴ τὰ δέοντα ποιεῖν ἐθέλειν ὑπολείπεται.", "st": "1.6"}, {"sp": "N", "t": "νυνὶ γάρ, ὃ πάντες ἐθρύλουν τέως, Ὀλυνθίους ἐκπολεμῶσαι δεῖν Φιλίππῳ, γέγονεν αὐτόματον, καὶ ταῦθ’ ὡς ἂν ὑμῖν μάλιστα συμφέροι. εἰ μὲν γὰρ ὑφ’ ὑμῶν πεισθέντες ἀνείλοντο τὸν πόλεμον, σφαλεροὶ σύμμαχοι καὶ μέχρι του ταῦτ’ ἂν ἐγνωκότες ἦσαν ἴσως· ἐπειδὴ δ’ ἐκ τῶν πρὸς αὑτοὺς ἐγκλημάτων μισοῦσι, βεβαίαν εἰκὸς τὴν ἔχθραν αὐτοὺς ὑπὲρ ὧν φοβοῦνται καὶ πεπόνθασιν ἔχειν.", "st": "1.7"}, {"sp": "N", "t": "οὐ δεῖ δὴ τοιοῦτον, ὦ ἄνδρες Ἀθηναῖοι, παραπεπτωκότα καιρὸν ἀφεῖναι, οὐδὲ παθεῖν ταὐτὸν ὅπερ ἤδη πολλάκις πρότερον πεπόνθατε. εἰ γάρ, ὅθ’ ἥκομεν Εὐβοεῦσιν βεβοηθηκότες καὶ παρῆσαν Ἀμφιπολιτῶν Ἱέραξ καὶ Στρατοκλῆς ἐπὶ τουτὶ τὸ βῆμα, κελεύοντες ἡμᾶς πλεῖν καὶ παραλαμβάνειν τὴν πόλιν, τὴν αὐτὴν παρειχόμεθ’ ἡμεῖς ὑπὲρ ἡμῶν αὐτῶν προθυμίαν ἥνπερ ὑπὲρ τῆς Εὐβοέων σωτηρίας, εἴχετ’ ἂν Ἀμφίπολιν τότε καὶ πάντων τῶν μετὰ ταῦτ’ ἂν ἦτ’ ἀπηλλαγμένοι πραγμάτων.", "st": "1.8"}, {"sp": "N", "t": "καὶ πάλιν ἡνίκα Πύδνα, Ποτείδαια, Μεθώνη, Παγασαί, τἄλλα, ἵνα μὴ καθ’ ἕκαστα λέγων διατρίβω, πολιορκούμεν’ ἀπηγγέλλετο, εἰ τότε τούτων ἑνὶ τῷ πρώτῳ προθύμως καὶ ὡς προσῆκεν ἐβοηθήσαμεν αὐτοί, ῥᾴονι καὶ πολὺ ταπεινοτέρῳ νῦν ἂν ἐχρώμεθα τῷ Φιλίππῳ. νῦν δὲ τὸ μὲν παρὸν ἀεὶ προϊέμενοι, τὰ δὲ μέλλοντ’ αὐτόματ’ οἰόμενοι σχήσειν καλῶς, ηὐξήσαμεν, ὦ ἄνδρες Ἀθηναῖοι, Φίλιππον ἡμεῖς καὶ κατεστήσαμεν τηλικοῦτον ἡλίκος οὐδείς πω βασιλεὺς γέγονεν Μακεδονίας. νυνὶ δὴ καιρὸς ἥκει τις, οὗτος ὁ τῶν Ὀλυνθίων, αὐτόματος τῇ πόλει, ὃς οὐδενός ἐστιν ἐλάττων τῶν προτέρων ἐκείνων.", "st": "1.9"}, {"sp": "N", "t": "καὶ ἔμοιγε δοκεῖ τις ἄν, ὦ ἄνδρες Ἀθηναῖοι, δίκαιος λογιστὴς τῶν παρὰ τῶν θεῶν ἡμῖν ὑπηργμένων καταστάς, καίπερ οὐκ ἐχόντων ὡς δεῖ πολλῶν, ὅμως μεγάλην ἂν ἔχειν αὐτοῖς χάριν, εἰκότως· τὸ μὲν γὰρ πόλλ’ ἀπολωλεκέναι κατὰ τὸν πόλεμον τῆς ἡμετέρας ἀμελείας ἄν τις θείη δικαίως, τὸ δὲ μήτε πάλαι τοῦτο πεπονθέναι πεφηνέναι τέ τιν’ ἡμῖν συμμαχίαν τούτων ἀντίρροπον, ἂν βουλώμεθα χρῆσθαι, τῆς παρ’ ἐκείνων εὐνοίας εὐεργέτημ’ ἂν ἔγωγε θείην.", "st": "1.10"}, {"sp": "N", "t": "ἀλλ’, οἶμαι, παρόμοιόν ἐστιν ὅπερ καὶ περὶ τῆς τῶν χρημάτων κτήσεως· ἂν μὲν γάρ, ὅσ’ ἄν τις λάβῃ, καὶ σῴσῃ, μεγάλην ἔχει τῇ τύχῃ τὴν χάριν, ἂν δ’ ἀναλώσας λάθῃ, συνανήλωσε καὶ τὸ μεμνῆσθαι [τὴν χάριν]. καὶ περὶ τῶν πραγμάτων οὕτως οἱ μὴ χρησάμενοι τοῖς καιροῖς ὀρθῶς, οὐδ’ εἰ συνέβη τι παρὰ τῶν θεῶν χρηστὸν μνημονεύουσι· πρὸς γὰρ τὸ τελευταῖον ἐκβὰν ἕκαστον τῶν πρὶν ὑπαρξάντων κρίνεται. διὸ καὶ σφόδρα δεῖ τῶν λοιπῶν ὑμᾶς, ὦ ἄνδρες Ἀθηναῖοι, φροντίσαι, ἵνα ταῦτ’ ἐπανορθωσάμενοι τὴν ἐπὶ τοῖς πεπραγμένοις ἀδοξίαν ἀποτριψώμεθα.", "st": "1.11"}, {"sp": "N", "t": "εἰ δὲ προησόμεθ’, ὦ ἄνδρες Ἀθηναῖοι, καὶ τούτους τοὺς ἀνθρώπους, εἶτ’ Ὄλυνθον ἐκεῖνος καταστρέψεται, φρασάτω τις ἐμοὶ τί τὸ κωλῦον ἔτ’ αὐτὸν ἔσται βαδίζειν ὅποι βούλεται. ἆρα λογίζεταί τις ὑμῶν, ὦ ἄνδρες Ἀθηναῖοι, καὶ θεωρεῖ τὸν τρόπον δι’ ὃν μέγας γέγονεν ἀσθενὴς ὢν τὸ κατ’ ἀρχὰς Φίλιππος; τὸ πρῶτον Ἀμφίπολιν λαβών, μετὰ ταῦτα Πύδναν, πάλιν Ποτείδαιαν, Μεθώνην αὖθις, εἶτα Θετταλίας ἐπέβη·", "st": "1.12"}, {"sp": "N", "t": "μετὰ ταῦτα Φεράς, Παγασάς, Μαγνησίαν, πάνθ’ ὃν ἐβούλετ’ εὐτρεπίσας τρόπον ᾤχετ’ εἰς Θρᾴκην· εἶτ’ ἐκεῖ τοὺς μὲν ἐκβαλὼν τοὺς δὲ καταστήσας τῶν βασιλέων ἠσθένησε· πάλιν ῥᾴσας οὐκ ἐπὶ τὸ ῥᾳθυμεῖν ἀπέκλινεν, ἀλλ’ εὐθὺς Ὀλυνθίοις ἐπεχείρησεν. τὰς δ’ ἐπ’ Ἰλλυριοὺς καὶ Παίονας αὐτοῦ καὶ πρὸς Ἀρύββαν καὶ ὅποι τις ἂν εἴποι παραλείπω στρατείας.", "st": "1.13"}, {"sp": "N", "t": "τί οὖν, ἄν τις εἴποι, ταῦτα λέγεις ἡμῖν νῦν; ἵνα γνῶτ’, ὦ ἄνδρες Ἀθηναῖοι, καὶ αἴσθησθ’ ἀμφότερα, καὶ τὸ προΐεσθαι καθ’ ἕκαστον ἀεί τι τῶν πραγμάτων ὡς ἀλυσιτελές, καὶ τὴν φιλοπραγμοσύνην ᾗ χρῆται καὶ συζῇ Φίλιππος, ὑφ’ ἧς οὐκ ἔστιν ὅπως ἀγαπήσας τοῖς πεπραγμένοις ἡσυχίαν σχήσει. εἰ δ’ ὁ μὲν ὡς ἀεί τι μεῖζον τῶν ὑπαρχόντων δεῖ πράττειν ἐγνωκὼς ἔσται, ἡμεῖς δ’ ὡς οὐδενὸς ἀντιληπτέον ἐρρωμένως τῶν πραγμάτων, σκοπεῖσθ’ εἰς τί ποτ’ ἐλπὶς ταῦτα τελευτῆσαι.", "st": "1.14"}, {"sp": "N", "t": "πρὸς θεῶν, τίς οὕτως εὐήθης ἐστὶν ὑμῶν ὅστις ἀγνοεῖ τὸν ἐκεῖθεν πόλεμον δεῦρ’ ἥξοντα, ἂν ἀμελήσωμεν; ἀλλὰ μήν, εἰ τοῦτο γενήσεται, δέδοικ’, ὦ ἄνδρες Ἀθηναῖοι, μὴ τὸν αὐτὸν τρόπον ὥσπερ οἱ δανειζόμενοι ῥᾳδίως ἐπὶ τοῖς μεγάλοις [τόκοις] μικρὸν εὐπορήσαντες χρόνον ὕστερον καὶ τῶν ἀρχαίων ἀπέστησαν, οὕτω καὶ ἡμεῖς [ἂν] ἐπὶ πολλῷ φανῶμεν ἐρρᾳθυμηκότες, καὶ ἅπαντα πρὸς ἡδονὴν ζητοῦντες πολλὰ καὶ χαλεπὰ ὧν οὐκ ἐβουλόμεθ’ ὕστερον εἰς ἀνάγκην ἔλθωμεν ποιεῖν, καὶ κινδυνεύσωμεν περὶ τῶν ἐν αὐτῇ τῇ χώρᾳ.", "st": "1.15"}, {"sp": "N", "t": "τὸ μὲν οὖν ἐπιτιμᾶν ἴσως φήσαι τις ἂν ῥᾴδιον καὶ παντὸς εἶναι, τὸ δ’ ὑπὲρ τῶν παρόντων ὅ τι δεῖ πράττειν ἀποφαίνεσθαι, τοῦτ’ εἶναι συμβούλου. ἐγὼ δ’ οὐκ ἀγνοῶ μέν, ὦ ἄνδρες Ἀθηναῖοι, τοῦθ’ ὅτι πολλάκις ὑμεῖς οὐ τοὺς αἰτίους, ἀλλὰ τοὺς ὑστάτους περὶ τῶν πραγμάτων εἰπόντας ἐν ὀργῇ ποιεῖσθε, ἄν τι μὴ κατὰ γνώμην ἐκβῇ· οὐ μὴν οἶμαι δεῖν τὴν ἰδίαν ἀσφάλειαν σκοποῦνθ’ ὑποστείλασθαι περὶ ὧν ὑμῖν συμφέρειν ἡγοῦμαι.", "st": "1.16"}, {"sp": "N", "t": "φημὶ δὴ διχῇ βοηθητέον εἶναι τοῖς πράγμασιν ὑμῖν, τῷ τε τὰς πόλεις τοῖς Ὀλυνθίοις σῴζειν καὶ τοὺς τοῦτο ποιήσοντας στρατιώτας ἐκπέμπειν, καὶ τῷ τὴν ἐκείνου χώραν κακῶς ποιεῖν καὶ τριήρεσι καὶ στρατιώταις ἑτέροις·", "st": "1.17"}, {"sp": "N", "t": "εἰ δὲ θατέρου τούτων ὀλιγωρήσετε, ὀκνῶ μὴ μάταιος ἡμῖν ἡ στρατεία γένηται. εἴτε γὰρ ὑμῶν τὴν ἐκείνου κακῶς ποιούντων, ὑπομείνας τοῦτ’ Ὄλυνθον παραστήσεται, ῥᾳδίως ἐπὶ τὴν οἰκείαν ἐλθὼν ἀμυνεῖται· εἴτε βοηθησάντων μόνον ὑμῶν εἰς Ὄλυνθον, ἀκινδύνως ὁρῶν ἔχοντα τὰ οἴκοι, προσκαθεδεῖται καὶ προσεδρεύσει τοῖς πράγμασι, περιέσται τῷ χρόνῳ τῶν πολιορκουμένων. δεῖ δὴ πολλὴν καὶ διχῇ τὴν βοήθειαν εἶναι.", "st": "1.18"}, {"sp": "N", "t": "καὶ περὶ μὲν τῆς βοηθείας ταῦτα γιγνώσκω· περὶ δὲ χρημάτων πόρου, ἔστιν, ὦ ἄνδρες Ἀθηναῖοι, χρήμαθ’ ὑμῖν, ἔστιν ὅσ’ οὐδενὶ τῶν ἄλλων ἀνθρώπων [στρατιωτικά]· ταῦτα δ’ ὑμεῖς οὕτως ὡς βούλεσθε λαμβάνετε. εἰ μὲν οὖν ταῦτα τοῖς στρατευομένοις ἀποδώσετε, οὐδενὸς ὑμῖν προσδεῖ πόρου, εἰ δὲ μή, προσδεῖ, μᾶλλον δ’ ἅπαντος ἐνδεῖ τοῦ πόρου. “τί οὖν;” ἄν τις εἴποι, “σὺ γράφεις ταῦτ’ εἶναι στρατιωτικά;” μὰ Δί’ οὐκ ἔγωγε.", "st": "1.19"}, {"sp": "N", "t": "ἐγὼ μὲν γὰρ ἡγοῦμαι στρατιώτας δεῖν κατασκευασθῆναι [καὶ ταῦτ’ εἶναι στρατιωτικὰ] καὶ μίαν σύνταξιν εἶναι τὴν αὐτὴν τοῦ τε λαμβάνειν καὶ τοῦ ποιεῖν τὰ δέοντα, ὑμεῖς δ’ οὕτω πως ἄνευ πραγμάτων λαμβάνειν εἰς τὰς ἑορτάς. ἔστι δὴ λοιπόν, οἶμαι, πάντας εἰσφέρειν, ἂν πολλῶν δέῃ, πολλά, ἂν ὀλίγων, ὀλίγα. δεῖ δὲ χρημάτων, καὶ ἄνευ τούτων οὐδὲν ἔστι γενέσθαι τῶν δεόντων. λέγουσι δὲ καὶ ἄλλους τινὰς ἄλλοι πόρους, ὧν ἕλεσθ’ ὅστις ὑμῖν συμφέρειν δοκεῖ· καὶ ἕως ἐστὶ καιρός, ἀντιλάβεσθε τῶν πραγμάτων.", "st": "1.20"}, {"sp": "N", "t": "ἄξιον δ’ ἐνθυμηθῆναι καὶ λογίσασθαι τὰ πράγματ’ ἐν ᾧ καθέστηκε νυνὶ τὰ Φιλίππου. οὔτε γάρ, ὡς δοκεῖ καὶ φήσειέ τις ἂν μὴ σκοπῶν ἀκριβῶς, εὐτρεπῶς οὐδ’ ὡς ἂν κάλλιστ’ αὐτῷ τὰ παρόντ’ ἔχει, οὔτ’ ἂν ἐξήνεγκε τὸν πόλεμόν ποτε τοῦτον ἐκεῖνος, εἰ πολεμεῖν ᾠήθη δεήσειν αὐτόν, ἀλλ’ ὡς ἐπιὼν ἅπαντα τότ’ ἤλπιζε τὰ πράγματ’ ἀναιρήσεσθαι, κᾆτα διέψευσται. τοῦτο δὴ πρῶτον αὐτὸν ταράττει παρὰ γνώμην γεγονὸς καὶ πολλὴν ἀθυμίαν αὐτῷ παρέχει, εἶτα τὰ τῶν Θετταλῶν.", "st": "1.21"}, {"sp": "N", "t": "ταῦτα γὰρ ἄπιστα μὲν ἦν δήπου φύσει καὶ ἀεὶ πᾶσιν ἀνθρώποις, κομιδῇ δ’, ὥσπερ ἦν, καὶ ἔστι νῦν τούτῳ. καὶ γὰρ Παγασὰς ἀπαιτεῖν αὐτόν εἰσιν ἐψηφισμένοι, καὶ Μαγνησίαν κεκωλύκασι τειχίζειν. ἤκουον δ’ ἔγωγέ τινων, ὡς οὐδὲ τοὺς λιμένας καὶ τὰς ἀγορὰς ἔτι δώσοιεν αὐτῷ καρποῦσθαι· τὰ γὰρ κοινὰ τὰ Θετταλῶν ἀπὸ τούτων δέοι διοικεῖν, οὐ Φίλιππον λαμβάνειν. εἰ δὲ τούτων ἀποστερήσεται τῶν χρημάτων, εἰς στενὸν κομιδῇ τὰ τῆς τροφῆς τοῖς ξένοις αὐτῷ καταστήσεται.", "st": "1.22"}, {"sp": "N", "t": "ἀλλὰ μὴν τόν γε Παίονα καὶ τὸν Ἰλλυριὸν καὶ ἁπλῶς τούτους ἅπαντας ἡγεῖσθαι χρὴ αὐτονόμους ἥδιον ἂν καὶ ἐλευθέρους ἢ δούλους εἶναι· καὶ γὰρ ἀήθεις τοῦ κατακούειν τινός εἰσι, καὶ ἅνθρωπος ὑβριστής, ὥς φασιν. καὶ μὰ Δί’ οὐδὲν ἄπιστον ἴσως· τὸ γὰρ εὖ πράττειν παρὰ τὴν ἀξίαν ἀφορμὴ τοῦ κακῶς φρονεῖν τοῖς ἀνοήτοις γίγνεται· διόπερ πολλάκις δοκεῖ τὸ φυλάξαι τἀγαθὰ τοῦ κτήσασθαι χαλεπώτερον εἶναι.", "st": "1.23"}, {"sp": "N", "t": "δεῖ τοίνυν ὑμᾶς, ὦ ἄνδρες Ἀθηναῖοι, τὴν ἀκαιρίαν τὴν ἐκείνου καιρὸν ὑμέτερον νομίσαντας ἑτοίμως συνάρασθαι τὰ πράγματα, καὶ πρεσβευομένους ἐφ’ ἃ δεῖ καὶ στρατευομένους αὐτοὺς καὶ παροξύνοντας τοὺς ἄλλους ἅπαντας, λογιζομένους, εἰ Φίλιππος λάβοι καθ’ ἡμῶν τοιοῦτον καιρὸν καὶ πόλεμος γένοιτο πρὸς τῇ χώρᾳ, πῶς ἂν αὐτὸν οἴεσθ’ ἑτοίμως ἐφ’ ὑμᾶς ἐλθεῖν; εἶτ’ οὐκ αἰσχύνεσθε, εἰ μηδ’ ἃ πάθοιτ’ ἄν, εἰ δύναιτ’ ἐκεῖνος, ταῦτα ποιῆσαι καιρὸν ἔχοντες οὐ τολμήσετε;", "st": "1.24"}, {"sp": "N", "t": "ἔτι τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, μηδὲ τοῦθ’ ὑμᾶς λανθανέτω, ὅτι νῦν αἵρεσίς ἐστιν ὑμῖν πότερ’ ὑμᾶς ἐκεῖ χρὴ πολεμεῖν ἢ παρ’ ὑμῖν ἐκεῖνον. ἐὰν μὲν γὰρ ἀντέχῃ τὰ τῶν Ὀλυνθίων, ὑμεῖς ἐκεῖ πολεμήσετε καὶ τὴν ἐκείνου κακῶς ποιήσετε, τὴν ὑπάρχουσαν καὶ τὴν οἰκείαν ταύτην ἀδεῶς καρπούμενοι· ἂν δ’ ἐκεῖνα Φίλιππος λάβῃ, τίς αὐτὸν κωλύσει δεῦρο βαδίζειν; Θηβαῖοι;", "st": "1.25"}, {"sp": "N", "t": "μὴ λίαν πικρὸν εἰπεῖν ᾖ— καὶ συνεισβαλοῦσιν ἑτοίμως. ἀλλὰ Φωκεῖς; οἱ τὴν οἰκείαν οὐχ οἷοί τε ὄντες φυλάττειν, ἐὰν μὴ βοηθήσηθ’ ὑμεῖς. ἢ ἄλλος τις; ἀλλ’, ὦ τᾶν, οὐχὶ βουλήσεται. τῶν ἀτοπωτάτων μέντἂν εἴη, εἰ ἃ νῦν ἄνοιαν ὀφλισκάνων ὅμως ἐκλαλεῖ, ταῦτα δυνηθεὶς μὴ πράξει.", "st": "1.26"}, {"sp": "N", "t": "ἀλλὰ μὴν ἡλίκα γ’ ἐστὶν τὰ διάφορ’ ἐνθάδ’ ἢ ἐκεῖ πολεμεῖν, οὐδὲ λόγου προσδεῖν ἡγοῦμαι. εἰ γὰρ ὑμᾶς δεήσειεν αὐτοὺς τριάκονθ’ ἡμέρας μόνας ἔξω γενέσθαι, καὶ ὅσ’ ἀνάγκη στρατοπέδῳ χρωμένους τῶν ἐκ τῆς χώρας λαμβάνειν, μηδενὸς ὄντος ἐν αὐτῇ πολεμίου λέγω, πλείον’ ἂν οἶμαι ζημιωθῆναι τοὺς γεωργοῦντας ὑμῶν ἢ ὅσ’ εἰς ἅπαντα τὸν πρὸ τοῦ πόλεμον δεδαπάνησθε. εἰ δὲ δὴ πόλεμός τις ἥξει, πόσα χρὴ νομίσαι ζημιώσεσθαι; καὶ πρόσεσθ’ ἡ ὕβρις καὶ ἔθ’ ἡ τῶν πραγμάτων αἰσχύνη, οὐδεμιᾶς ἐλάττων ζημίας τοῖς γε σώφροσιν.", "st": "1.27"}, {"sp": "N", "t": "πάντα δὴ ταῦτα δεῖ συνιδόντας ἅπαντας βοηθεῖν καὶ ἀπωθεῖν ἐκεῖσε τὸν πόλεμον, τοὺς μὲν εὐπόρους, ἵν’ ὑπὲρ τῶν πολλῶν ὧν καλῶς ποιοῦντες ἔχουσι μίκρ’ ἀναλίσκοντες τὰ λοιπὰ καρπῶνται ἀδεῶς, τοὺς δ’ ἐν ἡλικίᾳ, ἵνα τὴν τοῦ πολεμεῖν ἐμπειρίαν ἐν τῇ Φιλίππου χώρᾳ κτησάμενοι φοβεροὶ φύλακες τῆς οἰκείας ἀκεραίου γένωνται, τοὺς δὲ λέγοντας, ἵν’ αἱ τῶν πεπολιτευμένων αὐτοῖς εὔθυναι ῥᾴδιαι γένωνται, ὡς ὁποῖ’ ἄττ’ ἂν ὑμᾶς περιστῇ τὰ πράγματα, τοιοῦτοι κριταὶ καὶ τῶν πεπραγμένων αὐτοῖς ἔσεσθε. χρηστὰ δ’ εἴη παντὸς εἵνεκα.", "st": "1.28"}, {"sp": "HDR", "t": "Ὀλυνθιακὸς Βʹ", "st": "2"}, {"sp": "N", "t": "ἐπὶ πολλῶν μὲν ἄν τις ἰδεῖν, ὦ ἄνδρες Ἀθηναῖοι, δοκεῖ μοι τὴν παρὰ τῶν θεῶν εὔνοιαν φανερὰν γιγνομένην τῇ πόλει, οὐχ ἥκιστα δ’ ἐν τοῖς παροῦσι πράγμασι· τὸ γὰρ τοὺς πολεμήσοντας Φιλίππῳ γεγενῆσθαι καὶ χώραν ὅμορον καὶ δύναμίν τινα κεκτημένους, καὶ τὸ μέγιστον ἁπάντων, τὴν ὑπὲρ τοῦ πολέμου γνώμην τοιαύτην ἔχοντας ὥστε τὰς πρὸς ἐκεῖνον διαλλαγὰς πρῶτον μὲν ἀπίστους, εἶτα τῆς ἑαυτῶν πατρίδος νομίζειν ἀνάστασιν, δαιμονίᾳ τινὶ καὶ θείᾳ παντάπασιν ἔοικεν εὐεργεσίᾳ.", "st": "2.1"}, {"sp": "N", "t": "δεῖ τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, τοῦτ’ ἤδη σκοπεῖν αὐτούς, ὅπως μὴ χείρους περὶ ἡμᾶς αὐτοὺς εἶναι δόξομεν τῶν ὑπαρχόντων, ὡς ἔστι τῶν αἰσχρῶν, μᾶλλον δὲ τῶν αἰσχίστων, μὴ μόνον πόλεων καὶ τόπων ὧν ἦμέν ποτε κύριοι φαίνεσθαι προϊεμένους, ἀλλὰ καὶ τῶν ὑπὸ τῆς τύχης παρασκευασθέντων συμμάχων καὶ καιρῶν.", "st": "2.2"}, {"sp": "N", "t": "τὸ μὲν οὖν, ὦ ἄνδρες Ἀθηναῖοι, τὴν Φιλίππου ῥώμην διεξιέναι καὶ διὰ τούτων τῶν λόγων προτρέπειν τὰ δέοντα ποιεῖν ὑμᾶς, οὐχὶ καλῶς ἔχειν ἡγοῦμαι. διὰ τί; ὅτι μοι δοκεῖ πάνθ’ ὅσ’ ἂν εἴποι τις ὑπὲρ τούτων, ἐκείνῳ μὲν ἔχειν φιλοτιμίαν, ἡμῖν δ’ οὐχὶ καλῶς πεπρᾶχθαι. ὁ μὲν γὰρ ὅσῳ πλείον’ ὑπὲρ τὴν ἀξίαν πεποίηκε τὴν αὑτοῦ, τοσούτῳ θαυμαστότερος παρὰ πᾶσι νομίζεται· ὑμεῖς δ’ ὅσῳ χεῖρον ἢ προσῆκε κέχρησθε τοῖς πράγμασι, τοσούτῳ πλείον’ αἰσχύνην ὠφλήκατε.", "st": "2.3"}, {"sp": "N", "t": "ταῦτα μὲν οὖν παραλείψω. καὶ γὰρ εἰ μετ’ ἀληθείας τις, ὦ ἄνδρες Ἀθηναῖοι, σκοποῖτο, ἐνθένδ’ ἂν αὐτὸν ἴδοι μέγαν γεγενημένον, οὐχὶ παρ’ αὑτοῦ. ὧν οὖν ἐκεῖνος μὲν ὀφείλει τοῖς ὑπὲρ αὐτοῦ πεπολιτευμένοις χάριν, ὑμῖν δὲ δίκην προσήκει λαβεῖν, τούτων οὐχὶ νῦν ὁρῶ τὸν καιρὸν τοῦ λέγειν· ἃ δὲ καὶ χωρὶς τούτων ἔνι, καὶ βέλτιόν ἐστιν ἀκηκοέναι πάντας ὑμᾶς, καὶ μεγάλ’, ὦ ἄνδρες Ἀθηναῖοι, κατ’ ἐκείνου φαίνοιτ’ ἂν ὀνείδη βουλομένοις ὀρθῶς δοκιμάζειν, ταῦτ’ εἰπεῖν πειράσομαι.", "st": "2.4"}, {"sp": "N", "t": "τὸ μὲν οὖν ἐπίορκον κἄπιστον καλεῖν ἄνευ τοῦ τὰ πεπραγμένα δεικνύναι λοιδορίαν εἶναί τις ἂν φήσειε κενὴν δικαίως· τὸ δὲ πάνθ’ ὅσα πώποτ’ ἔπραξε διεξιόντα ἐφ’ ἅπασι τούτοις ἐλέγχειν, καὶ βραχέος λόγου συμβαίνει δεῖσθαι, καὶ δυοῖν ἕνεχ’ ἡγοῦμαι συμφέρειν εἰρῆσθαι, τοῦ τ’ ἐκεῖνον, ὅπερ καὶ ἀληθὲς ὑπάρχει, φαῦλον φαίνεσθαι, καὶ τοὺς ὑπερεκπεπληγμένους ὡς ἄμαχόν τινα τὸν Φίλιππον ἰδεῖν ὅτι πάντα διεξελήλυθεν οἷς πρότερον παρακρουόμενος μέγας ηὐξήθη, καὶ πρὸς αὐτὴν ἥκει τὴν τελευτὴν τὰ πράγματ’ αὐτῷ.", "st": "2.5"}, {"sp": "N", "t": "ἐγὼ γάρ, ὦ ἄνδρες Ἀθηναῖοι, σφόδρ’ ἂν ἡγούμην καὶ αὐτὸς φοβερὸν τὸν Φίλιππον καὶ θαυμαστόν, εἰ τὰ δίκαια πράττονθ’ ἑώρων ηὐξημένον· νῦν δὲ θεωρῶν καὶ σκοπῶν εὑρίσκω τὴν μὲν ἡμετέραν εὐήθειαν τὸ κατ’ ἀρχάς, ὅτ’ Ὀλυνθίους ἀπήλαυνόν τινες ἐνθένδε βουλομένους ὑμῖν διαλεχθῆναι, τῷ τὴν Ἀμφίπολιν φάσκειν παραδώσειν καὶ τὸ θρυλούμενόν ποτ’ ἀπόρρητον ἐκεῖνο κατασκευάσαι,", "st": "2.6"}, {"sp": "N", "t": "τούτῳ προσαγαγόμενον, τὴν δ’ Ὀλυνθίων φιλίαν μετὰ ταῦτα τῷ Ποτείδαιαν οὖσαν ὑμετέραν ἐξελεῖν καὶ τοὺς μὲν πρότερον συμμάχους [ὑμᾶς] ἀδικῆσαι, παραδοῦναι δ’ ἐκείνοις, Θετταλοὺς δὲ νῦν τὰ τελευταῖα τῷ Μαγνησίαν παραδώσειν ὑποσχέσθαι καὶ τὸν Φωκικὸν πόλεμον πολεμήσειν ὑπὲρ αὐτῶν ἀναδέξασθαι. ὅλως δ’ οὐδεὶς ἔστιν ὅντιν’ οὐ πεφενάκικ’ ἐκεῖνος τῶν αὐτῷ χρησαμένων· τὴν γὰρ ἑκάστων ἄνοιαν ἀεὶ τῶν ἀγνοούντων αὐτὸν ἐξαπατῶν καὶ προσλαμβάνων οὕτως ηὐξήθη.", "st": "2.7"}, {"sp": "N", "t": "ὥσπερ οὖν διὰ τούτων ἤρθη μέγας, ἡνίχ’ ἕκαστοι συμφέρον αὐτὸν ἑαυτοῖς ᾤοντό τι πράξειν, οὕτως ὀφείλει διὰ τῶν αὐτῶν τούτων καὶ καθαιρεθῆναι πάλιν, ἐπειδὴ πάνθ’ εἵνεχ’ ἑαυτοῦ ποιῶν ἐξελήλεγκται. καιροῦ μὲν δή, ὦ ἄνδρες Ἀθηναῖοι, πρὸς τοῦτο πάρεστι Φιλίππῳ τὰ πράγματα· ἢ παρελθών τις ἐμοί, μᾶλλον δ’ ὑμῖν δειξάτω, ἢ ὡς οὐκ ἀληθῆ ταῦτ’ ἐγὼ λέγω, ἢ ὡς οἱ τὰ πρῶτ’ ἐξηπατημένοι τὰ λοιπὰ πιστεύσουσιν, ἢ ὡς οἱ παρὰ τὴν αὑτῶν ἀξίαν δεδουλωμένοι [Θετταλοὶ] νῦν οὐκ ἂν ἐλεύθεροι γένοιντ’ ἄσμενοι.", "st": "2.8"}, {"sp": "N", "t": "καὶ μὴν εἴ τις ὑμῶν ταῦτα μὲν οὕτως ἔχειν ἡγεῖται, οἴεται δὲ βίᾳ καθέξειν αὐτὸν τὰ πράγματα τῷ τὰ χωρία καὶ λιμένας καὶ τὰ τοιαῦτα προειληφέναι, οὐκ ὀρθῶς οἴεται. ὅταν μὲν γὰρ ὑπ’ εὐνοίας τὰ πράγματα συστῇ καὶ πᾶσι ταὐτὰ συμφέρῃ τοῖς μετέχουσι τοῦ πολέμου, καὶ συμπονεῖν καὶ φέρειν τὰς συμφορὰς καὶ μένειν ἐθέλουσιν ἅνθρωποι· ὅταν δ’ ἐκ πλεονεξίας καὶ πονηρίας τις ὥσπερ οὗτος ἰσχύσῃ, ἡ πρώτη πρόφασις καὶ μικρὸν πταῖσμα ἅπαντ’ ἀνεχαίτισε καὶ διέλυσεν.", "st": "2.9"}, {"sp": "N", "t": "οὐ γὰρ ἔστιν, οὐκ ἔστιν, ὦ ἄνδρες Ἀθηναῖοι, ἀδικοῦντα κἀπιορκοῦντα καὶ ψευδόμενον δύναμιν βεβαίαν κτήσασθαι, ἀλλὰ τὰ τοιαῦτ’ εἰς μὲν ἅπαξ καὶ βραχὺν χρόνον ἀντέχει, καὶ σφόδρα γ’ ἤνθησ’ ἐπὶ ταῖς ἐλπίσιν, ἂν τύχῃ, τῷ χρόνῳ δὲ φωρᾶται καὶ περὶ αὑτὰ καταρρεῖ. ὥσπερ γὰρ οἰκίας, οἶμαι, καὶ πλοίου καὶ τῶν ἄλλων τῶν τοιούτων τὰ κάτωθεν ἰσχυρότατ’ εἶναι δεῖ, οὕτω καὶ τῶν πράξεων τὰς ἀρχὰς καὶ τὰς ὑποθέσεις ἀληθεῖς καὶ δικαίας εἶναι προσήκει. τοῦτο δ’ οὐκ ἔνι νῦν ἐν τοῖς πεπραγμένοις Φιλίππῳ.", "st": "2.10"}, {"sp": "N", "t": "φημὶ δὴ δεῖν ἡμᾶς τοῖς μὲν Ὀλυνθίοις βοηθεῖν, καὶ ὅπως τις λέγει κάλλιστα καὶ τάχιστα, οὕτως ἀρέσκει μοι· πρὸς δὲ Θετταλοὺς πρεσβείαν πέμπειν, ἣ τοὺς μὲν διδάξει ταῦτα, τοὺς δὲ παροξυνεῖ· καὶ γὰρ νῦν εἰσιν ἐψηφισμένοι Παγασὰς ἀπαιτεῖν καὶ περὶ Μαγνησίας λόγους ποιεῖσθαι.", "st": "2.11"}, {"sp": "N", "t": "σκοπεῖσθε μέντοι τοῦτ’, ὦ ἄνδρες Ἀθηναῖοι, ὅπως μὴ λόγους ἐροῦσιν μόνον οἱ παρ’ ἡμῶν πρέσβεις, ἀλλὰ καὶ ἔργον τι δεικνύειν ἕξουσιν ἐξεληλυθότων ὑμῶν ἀξίως τῆς πόλεως καὶ ὄντων ἐπὶ τοῖς πράγμασιν, ὡς ἅπας μὲν λόγος, ἂν ἀπῇ τὰ πράγματα, μάταιόν τι φαίνεται καὶ κενόν, μάλιστα δ’ ὁ παρὰ τῆς ἡμετέρας πόλεως· ὅσῳ γὰρ ἑτοιμότατ’ αὐτῷ δοκοῦμεν χρῆσθαι, τοσούτῳ μᾶλλον ἀπιστοῦσι πάντες αὐτῷ.", "st": "2.12"}, {"sp": "N", "t": "πολλὴν δὴ τὴν μετάστασιν καὶ μεγάλην δεικτέον τὴν μεταβολήν, εἰσφέροντας, ἐξιόντας, ἅπαντα ποιοῦντας ἑτοίμως, εἴπερ τις ὑμῖν προσέξει τὸν νοῦν. κἂν ταῦτ’ ἐθελήσηθ’ ὡς προσήκει καὶ δὴ περαίνειν, οὐ μόνον, ὦ ἄνδρες Ἀθηναῖοι, τὰ συμμαχικὰ ἀσθενῶς καὶ ἀπίστως ἔχοντα φανήσεται Φιλίππῳ, ἀλλὰ καὶ τὰ τῆς οἰκείας ἀρχῆς καὶ δυνάμεως κακῶς ἔχοντ’ ἐξελεγχθήσεται.", "st": "2.13"}, {"sp": "N", "t": "ὅλως μὲν γὰρ ἡ Μακεδονικὴ δύναμις καὶ ἀρχὴ ἐν μὲν προσθήκῃ μερίς ἐστί τις οὐ μικρά, οἷον ὑπῆρξέ ποθ’ ὑμῖν ἐπὶ Τιμοθέου πρὸς Ὀλυνθίους· πάλιν αὖ πρὸς Ποτείδαιαν Ὀλυνθίοις ἐφάνη τι τοῦτο συναμφότερον· νυνὶ δὲ Θετταλοῖς νοσοῦσι καὶ τεταραγμένοις ἐπὶ τὴν τυραννικὴν οἰκίαν ἐβοήθησεν· καὶ ὅποι τις ἄν, οἶμαι, προσθῇ κἂν μικρὰν δύναμιν, πάντ’ ὠφελεῖ· αὐτὴ δὲ καθ’ αὑτὴν ἀσθενὴς καὶ πολλῶν κακῶν ἐστι μεστή.", "st": "2.14"}, {"sp": "N", "t": "καὶ γὰρ οὗτος ἅπασι τούτοις, οἷς ἄν τις μέγαν αὐτὸν ἡγήσαιτο, τοῖς πολέμοις καὶ ταῖς στρατείαις, ἔτ’ ἐπισφαλεστέραν ἢ ὑπῆρχε φύσει κατεσκεύακεν αὑτῷ. μὴ γὰρ οἴεσθ’, ὦ ἄνδρες Ἀθηναῖοι, τοῖς αὐτοῖς Φίλιππόν τε χαίρειν καὶ τοὺς ἀρχομένους, ἀλλ’ ὁ μὲν δόξης ἐπιθυμεῖ καὶ τοῦτ’ ἐζήλωκε, καὶ προῄρηται πράττων καὶ κινδυνεύων, ἂν συμβῇ τι, παθεῖν, τὴν τοῦ διαπράξασθαι ταῦθ’ ἃ μηδεὶς πώποτ’ ἄλλος Μακεδόνων βασιλεὺς δόξαν ἀντὶ τοῦ ζῆν ἀσφαλῶς ᾑρημένος·", "st": "2.15"}, {"sp": "N", "t": "τοῖς δὲ τῆς μὲν φιλοτιμίας τῆς ἀπὸ τούτων οὐ μέτεστι, κοπτόμενοι δ’ ἀεὶ ταῖς στρατείαις ταύταις ταῖς ἄνω κάτω λυποῦνται καὶ συνεχῶς ταλαιπωροῦσιν, οὔτ’ ἐπὶ τοῖς ἔργοις οὔτ’ ἐπὶ τοῖς αὑτῶν ἰδίοις ἐώμενοι διατρίβειν, οὔθ’ ὅσ’ ἂν ποιήσωσιν οὕτως ὅπως ἂν δύνωνται, ταῦτ’ ἔχοντες διαθέσθαι κεκλειμένων τῶν ἐμπορίων τῶν ἐν τῇ χώρᾳ διὰ τὸν πόλεμον.", "st": "2.16"}, {"sp": "N", "t": "οἱ μὲν οὖν πολλοὶ Μακεδόνων πῶς ἔχουσι Φιλίππῳ, ἐκ τούτων ἄν τις σκέψαιτ’ οὐ χαλεπῶς· οἱ δὲ δὴ περὶ αὐτὸν ὄντες ξένοι καὶ πεζέταιροι δόξαν μὲν ἔχουσιν ὡς εἰσὶ θαυμαστοὶ καὶ συγκεκροτημένοι τὰ τοῦ πολέμου, ὡς δ’ ἐγὼ τῶν ἐν αὐτῇ τῇ χώρᾳ γεγενημένων τινὸς ἤκουον, ἀνδρὸς οὐδαμῶς οἵου τε ψεύδεσθαι, οὐδένων εἰσὶν βελτίους.", "st": "2.17"}, {"sp": "N", "t": "εἰ μὲν γάρ τις ἀνήρ ἐστιν ἐν αὐτοῖς οἷος ἔμπειρος πολέμου καὶ ἀγώνων, τούτους μὲν φιλοτιμίᾳ πάντας ἀπωθεῖν αὐτὸν ἔφη, βουλόμενον πάνθ’ αὑτοῦ δοκεῖν εἶναι τἄργα (πρὸς γὰρ αὖ τοῖς ἄλλοις καὶ τὴν φιλοτιμίαν ἀνυπέρβλητον εἶναι)· εἰ δέ τις σώφρων ἢ δίκαιος ἄλλως, τὴν καθ’ ἡμέραν ἀκρασίαν τοῦ βίου καὶ μέθην καὶ κορδακισμοὺς οὐ δυνάμενος φέρειν, παρεῶσθαι καὶ ἐν οὐδενὸς εἶναι μέρει τὸν τοιοῦτον.", "st": "2.18"}, {"sp": "N", "t": "λοιποὺς δὴ περὶ αὐτὸν εἶναι λῃστὰς καὶ κόλακας καὶ τοιούτους ἀνθρώπους οἵους μεθυσθέντας ὀρχεῖσθαι τοιαῦθ’ οἷ’ ἐγὼ νῦν ὀκνῶ πρὸς ὑμᾶς ὀνομάσαι. δῆλον δ’ ὅτι ταῦτ’ ἐστὶν ἀληθῆ· καὶ γὰρ οὓς ἐνθένδε πάντες ἀπήλαυνον ὡς πολὺ τῶν θαυματοποιῶν ἀσελγεστέρους ὄντας, Καλλίαν ἐκεῖνον τὸν δημόσιον καὶ τοιούτους ἀνθρώπους, μίμους γελοίων καὶ ποιητὰς αἰσχρῶν ᾀσμάτων, ὧν εἰς τοὺς συνόντας ποιοῦσιν εἵνεκα τοῦ γελασθῆναι, τούτους ἀγαπᾷ καὶ περὶ αὑτὸν ἔχει.", "st": "2.19"}, {"sp": "N", "t": "καίτοι ταῦτα, καὶ εἰ μικρά τις ἡγεῖται, μεγάλ’, ὦ ἄνδρες Ἀθηναῖοι, δείγματα τῆς ἐκείνου γνώμης καὶ κακοδαιμονίας ἐστὶ τοῖς εὖ φρονοῦσιν. ἀλλ’, οἶμαι, νῦν μὲν ἐπισκοτεῖ τούτοις τὸ κατορθοῦν· αἱ γὰρ εὐπραξίαι δειναὶ συγκρύψαι τὰ τοιαῦτ’ ὀνείδη· εἰ δέ τι πταίσει, τότ’ ἀκριβῶς αὐτοῦ ταῦτ’ ἐξετασθήσεται. δοκεῖ δ’ ἔμοιγ’, ὦ ἄνδρες Ἀθηναῖοι, δείξειν οὐκ εἰς μακράν, ἂν οἵ τε θεοὶ θέλωσι καὶ ὑμεῖς βούλησθε.", "st": "2.20"}, {"sp": "N", "t": "ὥσπερ γὰρ ἐν τοῖς σώμασιν, τέως μὲν ἂν ἐρρωμένος ᾖ τις, οὐδὲν ἐπαισθάνεται, ἐπὰν δ’ ἀρρώστημά τι συμβῇ, πάντα κινεῖται, κἂν ῥῆγμα κἂν στρέμμα κἂν ἄλλο τι τῶν ὑπαρχόντων σαθρὸν ᾖ, οὕτω καὶ τῶν πόλεων καὶ τῶν τυράννων, ἕως μὲν ἂν ἔξω πολεμῶσιν, ἀφανῆ τὰ κακὰ τοῖς πολλοῖς ἐστιν, ἐπειδὰν δ’ ὅμορος πόλεμος συμπλακῇ, πάντ’ ἐποίησεν ἔκδηλα.", "st": "2.21"}, {"sp": "N", "t": "εἰ δέ τις ὑμῶν, ὦ ἄνδρες Ἀθηναῖοι, τὸν Φίλιππον εὐτυχοῦνθ’ ὁρῶν ταύτῃ φοβερὸν προσπολεμῆσαι νομίζει, σώφρονος μὲν ἀνθρώπου λογισμῷ χρῆται· μεγάλη γὰρ ῥοπή, μᾶλλον δὲ τὸ ὅλον ἡ τύχη παρὰ πάντ’ ἐστὶ τὰ τῶν ἀνθρώπων πράγματα· οὐ μὴν ἀλλ’ ἔγωγε, εἴ τις αἵρεσίν μοι δοίη, τὴν τῆς ἡμετέρας πόλεως τύχην ἂν ἑλοίμην, ἐθελόντων ἃ προσήκει ποιεῖν ὑμῶν αὐτῶν καὶ κατὰ μικρόν, ἢ τὴν ἐκείνου· πολὺ γὰρ πλείους ἀφορμὰς εἰς τὸ τὴν παρὰ τῶν θεῶν εὔνοιαν ἔχειν ὁρῶ ὑμῖν ἐνούσας ἢ ’κείνῳ.", "st": "2.22"}, {"sp": "N", "t": "ἀλλ’, οἶμαι, καθήμεθ’ οὐδὲν ποιοῦντες· οὐκ ἔνι δ’ αὐτὸν ἀργοῦντ’ οὐδὲ τοῖς φίλοις ἐπιτάττειν ὑπὲρ αὑτοῦ τι ποιεῖν, μή τί γε δὴ τοῖς θεοῖς. οὐ δὴ θαυμαστόν ἐστιν, εἰ στρατευόμενος καὶ πονῶν ἐκεῖνος αὐτὸς καὶ παρὼν ἐφ’ ἅπασι καὶ μήτε καιρὸν μήθ’ ὥραν παραλείπων ἡμῶν μελλόντων καὶ ψηφιζομένων καὶ πυνθανομένων περιγίγνεται. οὐδὲ θαυμάζω τοῦτ’ ἐγώ· τοὐναντίον γὰρ ἂν ἦν θαυμαστόν, εἰ μηδὲν ποιοῦντες ἡμεῖς ὧν τοῖς πολεμοῦσι προσήκει τοῦ πάντα ποιοῦντος περιῆμεν.", "st": "2.23"}, {"sp": "N", "t": "ἀλλ’ ἐκεῖνο θαυμάζω, εἰ Λακεδαιμονίοις μέν ποτ’, ὦ ἄνδρες Ἀθηναῖοι, ὑπὲρ τῶν Ἑλληνικῶν δικαίων ἀντήρατε, καὶ πόλλ’ ἰδίᾳ πλεονεκτῆσαι πολλάκις ὑμῖν ἐξὸν οὐκ ἠθελήσατε, ἀλλ’ ἵν’ οἱ ἄλλοι τύχωσι τῶν δικαίων, τὰ ὑμέτερ’ αὐτῶν ἀνηλίσκετ’ εἰσφέροντες καὶ προυκινδυνεύετε στρατευόμενοι, νυνὶ δ’ ὀκνεῖτ’ ἐξιέναι καὶ μέλλετ’ εἰσφέρειν ὑπὲρ τῶν ὑμετέρων αὐτῶν κτημάτων, καὶ τοὺς μὲν ἄλλους σεσώκατε πολλάκις πάντας καὶ καθ’ ἕν’ αὐτῶν ἐν μέρει, τὰ δ’ ὑμέτερ’ αὐτῶν ἀπολωλεκότες κάθησθε.", "st": "2.24"}, {"sp": "N", "t": "ταῦτα θαυμάζω, κἄτι πρὸς τούτοις, εἰ μηδεὶς ὑμῶν, ὦ ἄνδρες Ἀθηναῖοι, δύναται λογίσασθαι πόσον πολεμεῖτε χρόνον Φιλίππῳ, καὶ τί ποιούντων ὑμῶν ὁ χρόνος διελήλυθεν οὗτος. ἴστε γὰρ δήπου τοῦθ’, ὅτι μελλόντων αὐτῶν, ἑτέρους τινὰς ἐλπιζόντων πράξειν, αἰτιωμένων ἀλλήλους, κρινόντων, πάλιν ἐλπιζόντων, σχεδὸν ταὔθ’ ἅπερ νυνὶ ποιούντων, ἅπας ὁ χρόνος διελήλυθεν.", "st": "2.25"}, {"sp": "N", "t": "εἶθ’ οὕτως ἀγνωμόνως ἔχετ’, ὦ ἄνδρες Ἀθηναῖοι, ὥστε δι’ ὧν ἐκ χρηστῶν φαῦλα τὰ πράγματα τῆς πόλεως γέγονεν, διὰ τούτων ἐλπίζετε τῶν αὐτῶν πράξεων ἐκ φαύλων αὐτὰ χρηστὰ γενήσεσθαι; ἀλλ’ οὔτ’ εὔλογον οὔτ’ ἔχον ἐστὶ φύσιν τοῦτό γε· πολὺ γὰρ ῥᾷον ἔχοντας φυλάττειν ἢ κτήσασθαι πάντα πέφυκεν. νῦν δ’ ὅ τι μὲν φυλάξομεν, οὐδέν ἐσθ’ ὑπὸ τοῦ πολέμου λοιπὸν τῶν πρότερον, κτήσασθαι δὲ δεῖ. αὐτῶν οὖν ἡμῶν ἔργον τοῦτ’ ἤδη.", "st": "2.26"}, {"sp": "N", "t": "φημὶ δὴ δεῖν εἰσφέρειν χρήματα, αὐτοὺς ἐξιέναι προθύμως, μηδέν’ αἰτιᾶσθαι πρὶν ἂν τῶν πραγμάτων κρατήσητε, τηνικαῦτα δ’ ἀπ’ αὐτῶν τῶν ἔργων κρίναντας τοὺς μὲν ἀξίους ἐπαίνου τιμᾶν, τοὺς δ’ ἀδικοῦντας κολάζειν, τὰς προφάσεις δ’ ἀφελεῖν καὶ τὰ καθ’ ὑμᾶς ἐλλείμματα· οὐ γὰρ ἔστι πικρῶς ἐξετάσαι τί πέπρακται τοῖς ἄλλοις, ἂν μὴ παρ’ ὑμῶν αὐτῶν πρῶτον ὑπάρξῃ τὰ δέοντα.", "st": "2.27"}, {"sp": "N", "t": "τίνος γὰρ εἵνεκ’, ὦ ἄνδρες Ἀθηναῖοι, νομίζετε τοῦτον μὲν φεύγειν τὸν πόλεμον πάντας ὅσους ἂν ἐκπέμψητε στρατηγούς, ἰδίους δ’ εὑρίσκειν πολέμους, εἰ δεῖ τι τῶν ὄντων καὶ περὶ τῶν στρατηγῶν εἰπεῖν; ὅτι ἐνταῦθα μέν ἐστι τἆθλ’ ὑπὲρ ὧν ἐστιν ὁ πόλεμος ὑμέτερα (Ἀμφίπολίς γ’ ἂν ληφθῇ, παραχρῆμ’ ὑμεῖς κομιεῖσθε), οἱ δὲ κίνδυνοι τῶν ἐφεστηκότων ἴδιοι, μισθὸς δ’ οὐκ ἔστιν· ἐκεῖ δὲ κίνδυνοι μὲν ἐλάττους, τὰ δὲ λήμματα τῶν ἐφεστηκότων καὶ τῶν στρατιωτῶν, Λάμψακος, Σίγειον, τὰ πλοῖ’ ἃ συλῶσιν. ἐπ’ οὖν τὸ λυσιτελοῦν αὑτοῖς ἕκαστοι χωροῦσιν.", "st": "2.28"}, {"sp": "N", "t": "ὑμεῖς δ’, ὅταν μὲν εἰς τὰ πράγματ’ ἀποβλέψητε φαύλως ἔχοντα, τοὺς ἐφεστηκότας κρίνετε, ὅταν δὲ δόντες λόγον τὰς ἀνάγκας ἀκούσητε ταύτας, ἀφίετε. περίεστι τοίνυν ὑμῖν ἀλλήλοις ἐρίζειν καὶ διεστάναι, τοῖς μὲν ταῦτα πεπεισμένοις, τοῖς δὲ ταῦτα, τὰ κοινὰ δ’ ἔχειν φαύλως. πρότερον μὲν γάρ, ὦ ἄνδρες Ἀθηναῖοι, κατὰ συμμορίας εἰσεφέρετε, νυνὶ δὲ πολιτεύεσθε κατὰ συμμορίας. ῥήτωρ ἡγεμὼν ἑκατέρων, καὶ στρατηγὸς ὑπὸ τούτῳ καὶ οἱ βοησόμενοι, οἱ τριακόσιοι· οἱ δ’ ἄλλοι προσνενέμησθε οἱ μὲν ὡς τούτους, οἱ δ’ ὡς ἐκείνους.", "st": "2.29"}, {"sp": "N", "t": "δεῖ δὴ ταῦτ’ ἐπανέντας καὶ ὑμῶν αὐτῶν ἔτι καὶ νῦν γενομένους κοινὸν καὶ τὸ βουλεύεσθαι καὶ τὸ λέγειν καὶ τὸ πράττειν ποιῆσαι. εἰ δὲ τοῖς μὲν ὥσπερ ἐκ τυραννίδος ὑμῶν ἐπιτάττειν ἀποδώσετε, τοῖς δ’ ἀναγκάζεσθαι τριηραρχεῖν, εἰσφέρειν, στρατεύεσθαι, τοῖς δὲ ψηφίζεσθαι κατὰ τούτων μόνον, ἄλλο δὲ μηδ’ ὁτιοῦν συμπονεῖν, οὐχὶ γενήσεται τῶν δεόντων ἡμῖν οὐδὲν ἐν καιρῷ· τὸ γὰρ ἠδικημένον ἀεὶ μέρος ἐλλείψει, εἶθ’ ὑμῖν τούτους κολάζειν ἀντὶ τῶν ἐχθρῶν ἐξέσται.", "st": "2.30"}, {"sp": "N", "t": "λέγω δὴ κεφάλαιον, πάντας εἰσφέρειν ἀφ’ ὅσων ἕκαστος ἔχει τὸ ἴσον· πάντας ἐξιέναι κατὰ μέρος, ἕως ἂν ἅπαντες στρατεύσησθε· πᾶσι τοῖς παριοῦσι λόγον διδόναι, καὶ τὰ βέλτισθ’ ὧν ἂν ἀκούσηθ’ αἱρεῖσθαι, μὴ ἃν ὁ δεῖν’ ἢ ὁ δεῖν’ εἴπῃ. κἂν ταῦτα ποιῆτε, οὐ τὸν εἰπόντα μόνον παραχρῆμ’ ἐπαινέσεσθε, ἀλλὰ καὶ ὑμᾶς αὐτοὺς ὕστερον, βέλτιον τῶν ὅλων πραγμάτων ὑμῖν ἐχόντων.", "st": "2.31"}, {"sp": "HDR", "t": "Ὀλυνθιακὸς Γʹ", "st": "3"}, {"sp": "N", "t": "οὐχὶ ταὐτὰ παρίσταταί μοι γιγνώσκειν, ὦ ἄνδρες Ἀθηναῖοι, ὅταν τ’ εἰς τὰ πράγματ’ ἀποβλέψω καὶ ὅταν πρὸς τοὺς λόγους οὓς ἀκούω· τοὺς μὲν γὰρ λόγους περὶ τοῦ τιμωρήσασθαι Φίλιππον ὁρῶ γιγνομένους, τὰ δὲ πράγματ’ εἰς τοῦτο προήκοντα, ὥσθ’ ὅπως μὴ πεισόμεθ’ αὐτοὶ πρότερον κακῶς σκέψασθαι δέον. οὐδὲν οὖν ἄλλο μοι δοκοῦσιν οἱ τὰ τοιαῦτα λέγοντες ἢ τὴν ὑπόθεσιν, περὶ ἧς βουλεύεσθε, οὐχὶ τὴν οὖσαν παριστάντες ὑμῖν ἁμαρτάνειν.", "st": "3.1"}, {"sp": "N", "t": "ἐγὼ δέ, ὅτι μέν ποτ’ ἐξῆν τῇ πόλει καὶ τὰ αὑτῆς ἔχειν ἀσφαλῶς καὶ Φίλιππον τιμωρήσασθαι, καὶ μάλ’ ἀκριβῶς οἶδα· ἐπ’ ἐμοῦ γάρ, οὐ πάλαι γέγονεν ταῦτ’ ἀμφότερα· νῦν μέντοι πέπεισμαι τοῦθ’ ἱκανὸν προλαβεῖν ἡμῖν εἶναι τὴν πρώτην, ὅπως τοὺς συμμάχους σώσομεν. ἐὰν γὰρ τοῦτο βεβαίως ὑπάρξῃ, τότε καὶ περὶ τοῦ τίνα τιμωρήσεταί τις καὶ ὃν τρόπον ἐξέσται σκοπεῖν· πρὶν δὲ τὴν ἀρχὴν ὀρθῶς ὑποθέσθαι, μάταιον ἡγοῦμαι περὶ τῆς τελευτῆς ὁντινοῦν ποιεῖσθαι λόγον.", "st": "3.2"}, {"sp": "N", "t": "ὁ μὲν οὖν παρὼν καιρός, εἴπερ ποτέ, πολλῆς φροντίδος καὶ βουλῆς δεῖται· ἐγὼ δ’ οὐχ ὅ τι χρὴ περὶ τῶν παρόντων συμβουλεῦσαι χαλεπώτατον ἡγοῦμαι, ἀλλ’ ἐκεῖν’ ἀπορῶ, τίνα χρὴ τρόπον, ὦ ἄνδρες Ἀθηναῖοι, πρὸς ὑμᾶς περὶ αὐτῶν εἰπεῖν. πέπεισμαι γὰρ ἐξ ὧν παρὼν καὶ ἀκούων σύνοιδα, τὰ πλείω τῶν πραγμάτων ἡμᾶς ἐκπεφευγέναι τῷ μὴ βούλεσθαι τὰ δέοντα ποιεῖν ἢ τῷ μὴ συνιέναι. ἀξιῶ δ’ ὑμᾶς, ἂν μετὰ παρρησίας ποιῶμαι τοὺς λόγους, ὑπομένειν, τοῦτο θεωροῦντας, εἰ τἀληθῆ λέγω, καὶ διὰ τοῦτο, ἵνα τὰ λοιπὰ βελτίω γένηται· ὁρᾶτε γὰρ ὡς ἐκ τοῦ πρὸς χάριν δημηγορεῖν ἐνίους εἰς πᾶν προελήλυθε μοχθηρίας τὰ παρόντα.", "st": "3.3"}, {"sp": "N", "t": "ἀναγκαῖον δ’ ὑπολαμβάνω μικρὰ τῶν γεγενημένων πρῶτον ὑμᾶς ὑπομνῆσαι. μέμνησθ’, ὦ ἄνδρες Ἀθηναῖοι, ὅτ’ ἀπηγγέλθη Φίλιππος ὑμῖν ἐν Θρᾴκῃ τρίτον ἢ τέταρτον ἔτος τουτὶ Ἡραῖον τεῖχος πολιορκῶν. τότε τοίνυν μὴν μὲν ἦν μαιμακτηριών· πολλῶν δὲ λόγων καὶ θορύβου γιγνομένου παρ’ ὑμῖν ἐψηφίσασθε τετταράκοντα τριήρεις καθέλκειν καὶ τοὺς μέχρι πέντε καὶ τετταράκοντ’ ἐτῶν αὐτοὺς ἐμβαίνειν καὶ τάλανθ’ ἑξήκοντ’ εἰσφέρειν.", "st": "3.4"}, {"sp": "N", "t": "καὶ μετὰ ταῦτα διελθόντος τοῦ ἐνιαυτοῦ τούτου ἑκατομβαιών, μεταγειτνιών, βοηδρομιών· τούτου τοῦ μηνὸς μόγις μετὰ τὰ μυστήρια δέκα ναῦς ἀπεστείλατ’ ἔχοντα κενὰς Χαρίδημον καὶ πέντε τάλαντ’ ἀργυρίου. ὡς γὰρ ἠγγέλθη Φίλιππος ἀσθενῶν ἢ τεθνεώς (ἦλθε γὰρ ἀμφότερα), οὐκέτι καιρὸν οὐδένα τοῦ βοηθεῖν νομίσαντες ἀφεῖτ’, ὦ ἄνδρες Ἀθηναῖοι, τὸν ἀπόστολον. ἦν δ’ οὗτος ὁ καιρὸς αὐτός· εἰ γὰρ τότ’ ἐκεῖσ’ ἐβοηθήσαμεν, ὥσπερ ἐψηφισάμεθα, προθύμως, οὐκ ἂν ἠνώχλει νῦν ἡμῖν ὁ Φίλιππος σωθείς.", "st": "3.5"}, {"sp": "N", "t": "τὰ μὲν δὴ τότε πραχθέντ’ οὐκ ἂν ἄλλως ἔχοι· νῦν δ’ ἑτέρου πολέμου καιρὸς ἥκει τις, δι’ ὃν καὶ περὶ τούτων ἐμνήσθην, ἵνα μὴ ταὐτὰ πάθητε. τί δὴ χρησόμεθ’, ὦ ἄνδρες Ἀθηναῖοι, τούτῳ; εἰ γὰρ μὴ βοηθήσετε παντὶ σθένει κατὰ τὸ δυνατόν, θεάσασθ’ ὃν τρόπον ὑμεῖς ἐστρατηγηκότες πάντ’ ἔσεσθ’ ὑπὲρ Φιλίππου.", "st": "3.6"}, {"sp": "N", "t": "ὑπῆρχον Ὀλύνθιοι δύναμίν τινα κεκτημένοι, καὶ διέκειθ’ οὕτω τὰ πράγματα· οὔτε Φίλιππος ἐθάρρει τούτους οὔθ’ οὗτοι Φίλιππον. ἐπράξαμεν ἡμεῖς κἀκεῖνοι πρὸς ἡμᾶς εἰρήνην· ἦν τοῦθ’ ὥσπερ ἐμπόδισμά τι τῷ Φιλίππῳ καὶ δυσχερές, πόλιν μεγάλην ἐφορμεῖν τοῖς ἑαυτοῦ καιροῖς διηλλαγμένην πρὸς ἡμᾶς. ἐκπολεμῶσαι δεῖν ᾠόμεθα τοὺς ἀνθρώπους ἐκ παντὸς τρόπου, καὶ ὃ πάντες ἐθρύλουν, πέπρακται νυνὶ τοῦθ’ ὁπωσδήποτε.", "st": "3.7"}, {"sp": "N", "t": "τί οὖν ὑπόλοιπον, ὦ ἄνδρες Ἀθηναῖοι, πλὴν βοηθεῖν ἐρρωμένως καὶ προθύμως; ἐγὼ μὲν οὐχ ὁρῶ· χωρὶς γὰρ τῆς περιστάσης ἂν ἡμᾶς αἰσχύνης, εἰ καθυφείμεθά τι τῶν πραγμάτων, οὐδὲ τὸν φόβον, ὦ ἄνδρες Ἀθηναῖοι, μικρὸν ὁρῶ τὸν τῶν μετὰ ταῦτα, ἐχόντων μὲν ὡς ἔχουσι Θηβαίων ἡμῖν, ἀπειρηκότων δὲ χρήμασι Φωκέων, μηδενὸς δ’ ἐμποδὼν ὄντος Φιλίππῳ τὰ παρόντα καταστρεψαμένῳ πρὸς ταῦτ’ ἐπικλῖναι τὰ πράγματα.", "st": "3.8"}, {"sp": "N", "t": "ἀλλὰ μὴν εἴ τις ὑμῶν εἰς τοῦτ’ ἀναβάλλεται ποιήσειν τὰ δέοντα, ἰδεῖν ἐγγύθεν βούλεται τὰ δεινά, ἐξὸν ἀκούειν ἄλλοθι γιγνόμενα, καὶ βοηθοὺς ἑαυτῷ ζητεῖν, ἐξὸν νῦν ἑτέροις αὐτὸν βοηθεῖν· ὅτι γὰρ εἰς τοῦτο περιστήσεται τὰ πράγματα, ἐὰν τὰ παρόντα προώμεθα, σχεδὸν ἴσμεν ἅπαντες δήπου.", "st": "3.9"}, {"sp": "N", "t": "ἀλλ’ ὅτι μὲν δὴ δεῖ βοηθεῖν, εἴποι τις ἄν, πάντες ἐγνώκαμεν, καὶ βοηθήσομεν· τὸ δ’ ὅπως, τοῦτο λέγε. μὴ τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, θαυμάσητε, ἂν παράδοξον εἴπω τι τοῖς πολλοῖς. νομοθέτας καθίσατε. ἐν δὲ τούτοις τοῖς νομοθέταις μὴ θῆσθε νόμον μηδένα (εἰσὶ γὰρ ὑμῖν ἱκανοί), ἀλλὰ τοὺς εἰς τὸ παρὸν βλάπτοντας ὑμᾶς λύσατε.", "st": "3.10"}, {"sp": "N", "t": "λέγω τοὺς περὶ τῶν θεωρικῶν, σαφῶς οὑτωσί, καὶ τοὺς περὶ τῶν στρατευομένων ἐνίους, ὧν οἱ μὲν τὰ στρατιωτικὰ τοῖς οἴκοι μένουσι διανέμουσι θεωρικά, οἱ δὲ τοὺς ἀτακτοῦντας ἀθῴους καθιστᾶσιν, εἶτα καὶ τοὺς τὰ δέοντα ποιεῖν βουλομένους ἀθυμοτέρους ποιοῦσιν. ἐπειδὰν δὲ ταῦτα λύσητε καὶ τὴν τοῦ τὰ βέλτιστα λέγειν ὁδὸν παράσχητ’ ἀσφαλῆ, τηνικαῦτα τὸν γράψονθ’ ἃ πάντες ἴσθ’ ὅτι συμφέρει ζητεῖτε.", "st": "3.11"}, {"sp": "N", "t": "πρὶν δὲ ταῦτα πρᾶξαι, μὴ σκοπεῖτε τίς εἰπὼν τὰ βέλτισθ’ ὑπὲρ ὑμῶν ὑφ’ ὑμῶν ἀπολέσθαι βουλήσεται· οὐ γὰρ εὑρήσετε, ἄλλως τε καὶ τούτου μόνου περιγίγνεσθαι μέλλοντος, παθεῖν ἀδίκως τι κακὸν τὸν ταῦτ’ εἰπόντα καὶ γράψαντα, μηδὲν δ’ ὠφελῆσαι τὰ πράγματα, ἀλλὰ καὶ εἰς τὸ λοιπὸν μᾶλλον ἔτ’ ἢ νῦν τὸ τὰ βέλτιστα λέγειν φοβερώτερον ποιῆσαι. καὶ λύειν γ’, ὦ ἄνδρες Ἀθηναῖοι, τοὺς νόμους δεῖ τούτους τοὺς αὐτοὺς ἀξιοῦν οἵπερ καὶ τεθήκασιν·", "st": "3.12"}, {"sp": "N", "t": "οὐ γάρ ἐστι δίκαιον, τὴν μὲν χάριν, ἣ πᾶσαν ἔβλαπτε τὴν πόλιν, τοῖς τότε θεῖσιν ὑπάρχειν, τὴν δ’ ἀπέχθειαν, δι’ ἧς ἂν ἅπαντες ἄμεινον πράξαιμεν, τῷ νῦν τὰ βέλτιστ’ εἰπόντι ζημίαν γενέσθαι. πρὶν δὲ ταῦτ’ εὐτρεπίσαι, μηδαμῶς, ὦ ἄνδρες Ἀθηναῖοι, μηδέν’ ἀξιοῦτε τηλικοῦτον εἶναι παρ’ ὑμῖν ὥστε τοὺς νόμους τούτους παραβάντα μὴ δοῦναι δίκην, μηδ’ οὕτως ἀνόητον ὥστ’ εἰς προῦπτον κακὸν αὑτὸν ἐμβαλεῖν.", "st": "3.13"}, {"sp": "N", "t": "οὐ μὴν οὐδ’ ἐκεῖνό γ’ ὑμᾶς ἀγνοεῖν δεῖ, ὦ ἄνδρες Ἀθηναῖοι, ὅτι ψήφισμ’ οὐδενὸς ἄξιόν ἐστιν, ἂν μὴ προσγένηται τὸ ποιεῖν ἐθέλειν τά γε δόξαντα προθύμως [ὑμᾶς]. εἰ γὰρ αὐτάρκη τὰ ψηφίσματ’ ἦν ἢ ὑμᾶς ἀναγκάζειν ἃ προσήκει πράττειν ἢ περὶ ὧν γραφείη διαπράξασθαι, οὔτ’ ἂν ὑμεῖς πολλὰ ψηφιζόμενοι μικρά, μᾶλλον δ’ οὐδὲν ἐπράττετε τούτων, οὔτε Φίλιππος τοσοῦτον ὑβρίκει χρόνον· πάλαι γὰρ ἂν εἵνεκά γε ψηφισμάτων ἐδεδώκει δίκην.", "st": "3.14"}, {"sp": "N", "t": "ἀλλ’ οὐχ οὕτω ταῦτ’ ἔχει· τὸ γὰρ πράττειν τοῦ λέγειν καὶ χειροτονεῖν ὕστερον ὂν τῇ τάξει, πρότερον τῇ δυνάμει καὶ κρεῖττόν ἐστιν. τοῦτ’ οὖν δεῖ προσεῖναι, τὰ δ’ ἄλλ’ ὑπάρχει· καὶ γὰρ εἰπεῖν τὰ δέοντα παρ’ ὑμῖν εἰσιν, ὦ ἄνδρες Ἀθηναῖοι, δυνάμενοι, καὶ γνῶναι πάντων ὑμεῖς ὀξύτατοι τὰ ῥηθέντα, καὶ πρᾶξαι δὲ δυνήσεσθε νῦν, ἐὰν ὀρθῶς ποιῆτε.", "st": "3.15"}, {"sp": "N", "t": "τίνα γὰρ χρόνον ἢ τίνα καιρόν, ὦ ἄνδρες Ἀθηναῖοι, τοῦ παρόντος βελτίω ζητεῖτε; ἢ πόθ’ ἃ δεῖ πράξετ’, εἰ μὴ νῦν; οὐχ ἅπαντα μὲν ἡμῶν προείληφε τὰ χωρί’ ἅνθρωπος, εἰ δὲ καὶ ταύτης κύριος τῆς χώρας γενήσεται, πάντων αἴσχιστα πεισόμεθα; οὐχ οὕς, εἰ πολεμήσαιεν, ἑτοίμως σώσειν ὑπισχνούμεθα, οὗτοι νῦν πολεμοῦσιν;", "st": "3.16"}, {"sp": "N", "t": "οὐκ ἐχθρός; οὐκ ἔχων τὰ ἡμέτερα; οὐ βάρβαρος; οὐχ ὅ τι ἂν εἴποι τις; ἀλλὰ πρὸς θεῶν πάντ’ ἐάσαντες καὶ μόνον οὐχὶ συγκατασκευάσαντες αὐτῷ, τότε τοὺς αἰτίους οἵτινες τούτων ζητήσομεν; οὐ γὰρ αὐτοί γ’ αἴτιοι φήσομεν εἶναι, σαφῶς οἶδα τοῦτ’ ἐγώ. οὐδὲ γὰρ ἐν τοῖς τοῦ πολέμου κινδύνοις τῶν φυγόντων οὐδεὶς ἑαυτοῦ κατηγορεῖ, ἀλλὰ τοῦ στρατηγοῦ καὶ τῶν πλησίον καὶ πάντων μᾶλλον, ἥττηνται δ’ ὅμως διὰ πάντας τοὺς φυγόντας δήπου· μένειν γὰρ ἐξῆν τῷ κατηγοροῦντι τῶν ἄλλων, εἰ δὲ τοῦτ’ ἐποίει ἕκαστος, ἐνίκων ἄν.", "st": "3.17"}, {"sp": "N", "t": "καὶ νῦν, οὐ λέγει τις τὰ βέλτιστα· ἀναστὰς ἄλλος εἰπάτω, μὴ τοῦτον αἰτιάσθω. ἕτερος λέγει τις βελτίω· ταῦτα ποιεῖτ’ ἀγαθῇ τύχῃ. ἀλλ’ οὐχ ἡδέα ταῦτα· οὐκέτι τοῦθ’ ὁ λέγων ἀδικεῖ—πλὴν εἰ δέον εὔξασθαι παραλείπει. εὔξασθαι μὲν γάρ, ὦ ἄνδρες Ἀθηναῖοι, ῥᾴδιον, εἰς ταὐτὸ πάνθ’ ὅσα βούλεταί τις ἁθροίσαντ’ ἐν ὀλίγῳ· ἑλέσθαι δ’, ὅταν περὶ πραγμάτων προτεθῇ σκοπεῖν, οὐκέθ’ ὁμοίως εὔπορον, ἀλλὰ δεῖ τὰ βέλτιστ’ ἀντὶ τῶν ἡδέων, ἂν μὴ συναμφότερ’ ἐξῇ, λαμβάνειν.", "st": "3.18"}, {"sp": "N", "t": "εἰ δέ τις ἡμῖν ἔχει καὶ τὰ θεωρικὰ ἐᾶν καὶ πόρους ἑτέρους λέγειν στρατιωτικούς, οὐχ οὗτος κρείττων; εἴποι τις ἄν. φήμ’ ἔγωγε, εἴπερ ἔστιν, ὦ ἄνδρες Ἀθηναῖοι· ἀλλὰ θαυμάζω εἴ τῴ ποτ’ ἀνθρώπων ἢ γέγονεν ἢ γενήσεται, ἂν τὰ παρόντ’ ἀναλώσῃ πρὸς ἃ μὴ δεῖ, τῶν ἀπόντων εὐπορῆσαι πρὸς ἃ δεῖ. ἀλλ’, οἶμαι, μέγα τοῖς τοιούτοις ὑπάρχει λόγοις ἡ παρ’ ἑκάστου βούλησις, διόπερ ῥᾷστον ἁπάντων ἐστὶν αὑτὸν ἐξαπατῆσαι· ὃ γὰρ βούλεται, τοῦθ’ ἕκαστος καὶ οἴεται, τὰ δὲ πράγματα πολλάκις οὐχ οὕτω πέφυκεν.", "st": "3.19"}, {"sp": "N", "t": "ὁρᾶτ’ οὖν, ὦ ἄνδρες Ἀθηναῖοι, ταῦθ’ οὕτως, ὅπως καὶ τὰ πράγματ’ ἐνδέχεται καὶ δυνήσεσθ’ ἐξιέναι καὶ μισθὸν ἕξετε. οὔ τοι σωφρόνων οὐδὲ γενναίων ἐστὶν ἀνθρώπων, ἐλλείποντάς τι δι’ ἔνδειαν χρημάτων τῶν τοῦ πολέμου εὐχερῶς τὰ τοιαῦτ’ ὀνείδη φέρειν, οὐδ’ ἐπὶ μὲν Κορινθίους καὶ Μεγαρέας ἁρπάσαντας τὰ ὅπλα πορεύεσθαι, Φίλιππον δ’ ἐᾶν πόλεις Ἑλληνίδας ἀνδραποδίζεσθαι δι’ ἀπορίαν ἐφοδίων τοῖς στρατευομένοις.", "st": "3.20"}, {"sp": "N", "t": "καὶ ταῦτ’ οὐχ ἵν’ ἀπέχθωμαί τισιν ὑμῶν, τὴν ἄλλως προῄρημαι λέγειν· οὐ γὰρ οὕτως ἄφρων οὐδ’ ἀτυχής εἰμ’ ἐγὼ ὥστ’ ἀπεχθάνεσθαι βούλεσθαι μηδὲν ὠφελεῖν νομίζων· ἀλλὰ δικαίου πολίτου κρίνω τὴν τῶν πραγμάτων σωτηρίαν ἀντὶ τῆς ἐν τῷ λέγειν χάριτος αἱρεῖσθαι. καὶ γὰρ τοὺς ἐπὶ τῶν προγόνων ἡμῶν λέγοντας ἀκούω, ὥσπερ ἴσως καὶ ὑμεῖς, οὓς ἐπαινοῦσι μὲν οἱ παριόντες ἅπαντες, μιμοῦνται δ’ οὐ πάνυ, τούτῳ τῷ ἔθει καὶ τῷ τρόπῳ τῆς πολιτείας χρῆσθαι, τὸν Ἀριστείδην ἐκεῖνον, τὸν Νικίαν, τὸν ὁμώνυμον ἐμαυτῷ, τὸν Περικλέα.", "st": "3.21"}, {"sp": "N", "t": "ἐξ οὗ δ’ οἱ διερωτῶντες ὑμᾶς οὗτοι πεφήνασι ῥήτορες “τί βούλεσθε; τί γράψω; τί ὑμῖν χαρίσωμαι;” προπέποται τῆς παραυτίκα χάριτος τὰ τῆς πόλεως πράγματα, καὶ τοιαυτὶ συμβαίνει, καὶ τὰ μὲν τούτων πάντα καλῶς ἔχει, τὰ δ’ ὑμέτερ’ αἰσχρῶς.", "st": "3.22"}, {"sp": "N", "t": "καίτοι σκέψασθ’, ὦ ἄνδρες Ἀθηναῖοι, ἅ τις ἂν κεφάλαι’ εἰπεῖν ἔχοι τῶν τ’ ἐπὶ τῶν προγόνων ἔργων καὶ τῶν ἐφ’ ὑμῶν. ἔσται δὲ βραχὺς καὶ γνώριμος ὑμῖν ὁ λόγος· οὐ γὰρ ἀλλοτρίοις ὑμῖν χρωμένοις παραδείγμασιν, ἀλλ’ οἰκείοις, ὦ ἄνδρες Ἀθηναῖοι, εὐδαίμοσιν ἔξεστι γενέσθαι.", "st": "3.23"}, {"sp": "N", "t": "ἐκεῖνοι τοίνυν, οἷς οὐκ ἐχαρίζονθ’ οἱ λέγοντες οὐδ’ ἐφίλουν αὐτοὺς ὥσπερ ὑμᾶς οὗτοι νῦν, πέντε μὲν καὶ τετταράκοντ’ ἔτη τῶν Ἑλλήνων ἦρξαν ἑκόντων, πλείω δ’ ἢ μύρια τάλαντ’ εἰς τὴν ἀκρόπολιν ἀνήγαγον, ὑπήκουε δ’ ὁ ταύτην τὴν χώραν ἔχων αὐτοῖς βασιλεύς, ὥσπερ ἐστὶ προσῆκον βάρβαρον Ἕλλησι, πολλὰ δὲ καὶ καλὰ καὶ πεζῇ καὶ ναυμαχοῦντες ἔστησαν τρόπαι’ αὐτοὶ στρατευόμενοι, μόνοι δ’ ἀνθρώπων κρείττω τὴν ἐπὶ τοῖς ἔργοις δόξαν τῶν φθονούντων κατέλιπον.", "st": "3.24"}, {"sp": "N", "t": "ἐπὶ μὲν δὴ τῶν Ἑλληνικῶν ἦσαν τοιοῦτοι· ἐν δὲ τοῖς κατὰ τὴν πόλιν αὐτὴν θεάσασθ’ ὁποῖοι, ἔν τε τοῖς κοινοῖς κἀν τοῖς ἰδίοις. δημοσίᾳ μὲν τοίνυν οἰκοδομήματα καὶ κάλλη τοιαῦτα καὶ τοσαῦτα κατεσκεύασαν ἡμῖν ἱερῶν καὶ τῶν ἐν τούτοις ἀναθημάτων, ὥστε μηδενὶ τῶν ἐπιγιγνομένων ὑπερβολὴν λελεῖφθαι· ἰδίᾳ δ’ οὕτω σώφρονες ἦσαν καὶ σφόδρ’ ἐν τῷ τῆς πολιτείας ἤθει μένοντες,", "st": "3.25"}, {"sp": "N", "t": "ὥστε τὴν Ἀριστείδου καὶ τὴν Μιλτιάδου καὶ τῶν τότε λαμπρῶν οἰκίαν εἴ τις ἄρ’ οἶδεν ὑμῶν ὁποία ποτ’ ἐστίν, ὁρᾷ τῆς τοῦ γείτονος οὐδὲν σεμνοτέραν οὖσαν· οὐ γὰρ εἰς περιουσίαν ἐπράττετ’ αὐτοῖς τὰ τῆς πόλεως, ἀλλὰ τὸ κοινὸν αὔξειν ἕκαστος ᾤετο δεῖν. ἐκ δὲ τοῦ τὰ μὲν Ἑλληνικὰ πιστῶς, τὰ δὲ πρὸς τοὺς θεοὺς εὐσεβῶς, τὰ δ’ ἐν αὑτοῖς ἴσως διοικεῖν μεγάλην εἰκότως ἐκτήσαντ’ εὐδαιμονίαν.", "st": "3.26"}, {"sp": "N", "t": "τότε μὲν δὴ τοῦτον τὸν τρόπον εἶχε τὰ πράγματ’ ἐκείνοις, χρωμένοις οἷς εἶπον προστάταις· νυνὶ δὲ πῶς ἡμῖν ὑπὸ τῶν χρηστῶν τούτων τὰ πράγματ’ ἔχει; ἆρά γ’ ὁμοίως ἢ παραπλησίως; οἷς —τὰ μὲν ἄλλα σιωπῶ, πόλλ’ ἂν ἔχων εἰπεῖν, ἀλλ’ ὅσης ἅπαντες ὁρᾶτ’ ἐρημίας ἐπειλημμένοι, [καὶ] Λακεδαιμονίων μὲν ἀπολωλότων, Θηβαίων δ’ ἀσχόλων ὄντων, τῶν δ’ ἄλλων οὐδενὸς ὄντος ἀξιόχρεω περὶ τῶν πρωτείων ἡμῖν ἀντιτάξασθαι, ἐξὸν δ’ ἡμῖν καὶ τὰ ἡμέτερ’ αὐτῶν ἀσφαλῶς ἔχειν καὶ τὰ τῶν ἄλλων δίκαια βραβεύειν,", "st": "3.27"}, {"sp": "N", "t": "ἀπεστερήμεθα μὲν χώρας οἰκείας, πλείω δ’ ἢ χίλια καὶ πεντακόσια τάλαντ’ ἀνηλώκαμεν εἰς οὐδὲν δέον, οὓς δ’ ἐν τῷ πολέμῳ συμμάχους ἐκτησάμεθα, εἰρήνης οὔσης ἀπολωλέκασιν οὗτοι, ἐχθρὸν δ’ ἐφ’ ἡμᾶς αὐτοὺς τηλικοῦτον ἠσκήκαμεν. ἢ φρασάτω τις ἐμοὶ παρελθών, πόθεν ἄλλοθεν ἰσχυρὸς γέγονεν ἢ παρ’ ἡμῶν αὐτῶν Φίλιππος.", "st": "3.28"}, {"sp": "N", "t": "ἀλλ’, ὦ τᾶν, εἰ ταῦτα φαύλως, τά γ’ ἐν αὐτῇ τῇ πόλει νῦν ἄμεινον ἔχει. καὶ τί ἂν εἰπεῖν τις ἔχοι; τὰς ἐπάλξεις ἃς κονιῶμεν, καὶ τὰς ὁδοὺς ἃς ἐπισκευάζομεν, καὶ κρήνας, καὶ λήρους; ἀποβλέψατε δὴ πρὸς τοὺς ταῦτα πολιτευομένους, ὧν οἱ μὲν ἐκ πτωχῶν πλούσιοι γεγόνασιν, οἱ δ’ ἐξ ἀδόξων ἔντιμοι, ἔνιοι δὲ τὰς ἰδίας οἰκίας τῶν δημοσίων οἰκοδομημάτων σεμνοτέρας εἰσὶ κατεσκευασμένοι, ὅσῳ δὲ τὰ τῆς πόλεως ἐλάττω γέγονεν, τοσούτῳ τὰ τούτων ηὔξηται.", "st": "3.29"}, {"sp": "N", "t": "τί δὴ τὸ πάντων αἴτιον τούτων, καὶ τί δή ποθ’ ἅπαντ’ εἶχε καλῶς τότε, καὶ νῦν οὐκ ὀρθῶς; ὅτι τότε μὲν πράττειν καὶ στρατεύεσθαι τολμῶν αὐτὸς ὁ δῆμος δεσπότης τῶν πολιτευομένων ἦν καὶ κύριος αὐτὸς ἁπάντων τῶν ἀγαθῶν, καὶ ἀγαπητὸν ἦν παρὰ τοῦ δήμου τῶν ἄλλων ἑκάστῳ καὶ τιμῆς καὶ ἀρχῆς καὶ ἀγαθοῦ τινος μεταλαβεῖν·", "st": "3.30"}, {"sp": "N", "t": "νῦν δὲ τοὐναντίον κύριοι μὲν οἱ πολιτευόμενοι τῶν ἀγαθῶν, καὶ διὰ τούτων ἅπαντα πράττεται, ὑμεῖς δ’ ὁ δῆμος, ἐκνενευρισμένοι καὶ περιῃρημένοι χρήματα, συμμάχους, ἐν ὑπηρέτου καὶ προσθήκης μέρει γεγένησθε, ἀγαπῶντες ἐὰν μεταδιδῶσι θεωρικῶν ὑμῖν ἢ Βοηδρόμια πέμψωσιν οὗτοι, καὶ τὸ πάντων ἀνδρειότατον, τῶν ὑμετέρων αὐτῶν χάριν προσοφείλετε. οἱ δ’ ἐν αὐτῇ τῇ πόλει καθείρξαντες ὑμᾶς ἐπάγουσ’ ἐπὶ ταῦτα καὶ τιθασεύουσι χειροήθεις αὑτοῖς ποιοῦντες.", "st": "3.31"}, {"sp": "N", "t": "ἔστι δ’ οὐδέποτ’, οἶμαι, μέγα καὶ νεανικὸν φρόνημα λαβεῖν μικρὰ καὶ φαῦλα πράττοντας· ὁποῖ’ ἄττα γὰρ ἂν τἀπιτηδεύματα τῶν ἀνθρώπων ᾖ, τοιοῦτον ἀνάγκη καὶ τὸ φρόνημ’ ἔχειν. ταῦτα μὰ τὴν Δήμητρ’ οὐκ ἂν θαυμάσαιμ’ εἰ μείζων εἰπόντι ἐμοὶ γένοιτο παρ’ ὑμῶν βλάβη τῶν πεποιηκότων αὐτὰ γενέσθαι· οὐδὲ γὰρ παρρησία περὶ πάντων ἀεὶ παρ’ ὑμῖν ἐστιν, ἀλλ’ ἔγωγ’ ὅτι καὶ νῦν γέγονεν θαυμάζω.", "st": "3.32"}, {"sp": "N", "t": "ἐὰν οὖν ἀλλὰ νῦν γ’ ἔτι ἀπαλλαγέντες τούτων τῶν ἐθῶν ἐθελήσητε στρατεύεσθαί τε καὶ πράττειν ἀξίως ὑμῶν αὐτῶν, καὶ ταῖς περιουσίαις ταῖς οἴκοι ταύταις ἀφορμαῖς ἐπὶ τὰ ἔξω τῶν ἀγαθῶν χρῆσθαι, ἴσως ἄν, ἴσως, ὦ ἄνδρες Ἀθηναῖοι, τέλειόν τι καὶ μέγα κτήσαισθ’ ἀγαθὸν καὶ τῶν τοιούτων λημμάτων ἀπαλλαγείητε, ἃ τοῖς [ἀσθενοῦσι] παρὰ τῶν ἰατρῶν σιτίοις [διδομένοις] ἔοικε. καὶ γὰρ ἐκεῖν’ οὔτ’ ἰσχὺν ἐντίθησιν οὔτ’ ἀποθνῄσκειν ἐᾷ· καὶ ταῦθ’ ἃ νέμεσθε νῦν ὑμεῖς, οὔτε τοσαῦτ’ ἐστὶν ὥστ’ ὠφέλειαν ἔχειν τινὰ διαρκῆ, οὔτ’ ἀπογνόντας ἄλλο τι πράττειν ἐᾷ, ἀλλ’ ἔστι ταῦτα τὴν ἑκάστου ῥᾳθυμίαν ὑμῶν ἐπαυξάνοντα.", "st": "3.33"}, {"sp": "N", "t": "οὐκοῦν σὺ μισθοφορὰν λέγεις; φήσει τις. καὶ παραχρῆμά γε τὴν αὐτὴν σύνταξιν ἁπάντων, ὦ ἄνδρες Ἀθηναῖοι, ἵνα τῶν κοινῶν ἕκαστος τὸ μέρος λαμβάνων, ὅτου δέοιθ’ ἡ πόλις, τοῦθ’ ὑπάρχοι. ἔξεστιν ἄγειν ἡσυχίαν· οἴκοι μένων βελτίων, τοῦ δι’ ἔνδειαν ἀνάγκῃ τι ποιεῖν αἰσχρὸν ἀπηλλαγμένος. συμβαίνει τι τοιοῦτον οἷον καὶ τὰ νῦν· στρατιώτης αὐτὸς ὑπάρχων ἀπὸ τῶν αὐτῶν τούτων λημμάτων, ὥσπερ ἐστὶ δίκαιον ὑπὲρ τῆς πατρίδος. ἔστι τις ἔξω τῆς ἡλικίας ὑμῶν· ὅσ’ οὗτος ἀτάκτως νῦν λαμβάνων οὐκ ὠφελεῖ, ταῦτ’ ἐν ἴσῃ τάξει λαμβάνων πάντ’ ἐφορῶν καὶ διοικῶν ἃ χρὴ πράττεσθαι.", "st": "3.34"}, {"sp": "N", "t": "ὅλως δ’ οὔτ’ ἀφελὼν οὔτε προσθείς, πλὴν μικρῶν, τὴν ἀταξίαν ἀνελὼν εἰς τάξιν ἤγαγον τὴν πόλιν, τὴν αὐτὴν τοῦ λαβεῖν, τοῦ στρατεύεσθαι, τοῦ δικάζειν, τοῦ ποιεῖν τοῦθ’ ὅ τι καθ’ ἡλικίαν ἕκαστος ἔχοι καὶ ὅτου καιρὸς εἴη, τάξιν ποιήσας. οὐκ ἔστιν ὅπου μηδὲν ἐγὼ ποιοῦσι τὰ τῶν ποιούντων εἶπον ὡς δεῖ νέμειν, οὐδ’ αὐτοὺς μὲν ἀργεῖν καὶ σχολάζειν καὶ ἀπορεῖν, ὅτι δ’ οἱ τοῦ δεῖνος νικῶσι ξένοι, ταῦτα πυνθάνεσθαι· ταῦτα γὰρ νυνὶ γίγνεται.", "st": "3.35"}, {"sp": "N", "t": "καὶ οὐχὶ μέμφομαι τὸν ποιοῦντά τι τῶν δεόντων ὑπὲρ ὑμῶν, ἀλλὰ καὶ ὑμᾶς ὑπὲρ ὑμῶν αὐτῶν ἀξιῶ πράττειν ταῦτ’ ἐφ’ οἷς ἑτέρους τιμᾶτε, καὶ μὴ παραχωρεῖν, ὦ ἄνδρες Ἀθηναῖοι, τῆς τάξεως, ἣν ὑμῖν οἱ πρόγονοι τῆς ἀρετῆς μετὰ πολλῶν καὶ καλῶν κινδύνων κτησάμενοι κατέλιπον.", "st": "3.36"}, {"sp": "N", "t": "σχεδὸν εἴρηχ’ ἃ νομίζω συμφέρειν· ὑμεῖς δ’ ἕλοισθ’ ὅ τι καὶ τῇ πόλει καὶ ἅπασι συνοίσειν ὑμῖν μέλλει.", "st": "3.36"}, {"sp": "HDR", "t": "Κατὰ Φιλίππου Αʹ", "st": "4"}, {"sp": "N", "t": "εἰ μὲν περὶ καινοῦ τινος πράγματος προυτίθετ’, ὦ ἄνδρες Ἀθηναῖοι, λέγειν, ἐπισχὼν ἂν ἕως οἱ πλεῖστοι τῶν εἰωθότων γνώμην ἀπεφήναντο, εἰ μὲν ἤρεσκέ τί μοι τῶν ὑπὸ τούτων ῥηθέντων, ἡσυχίαν ἂν ἦγον, εἰ δὲ μή, τότ’ ἂν καὐτὸς ἐπειρώμην ἃ γιγνώσκω λέγειν· ἐπειδὴ δ’ ὑπὲρ ὧν πολλάκις εἰρήκασιν οὗτοι πρότερον συμβαίνει καὶ νυνὶ σκοπεῖν, ἡγοῦμαι καὶ πρῶτος ἀναστὰς εἰκότως ἂν συγγνώμης τυγχάνειν. εἰ γὰρ ἐκ τοῦ παρεληλυθότος χρόνου τὰ δέονθ’ οὗτοι συνεβούλευσαν, οὐδὲν ἂν ὑμᾶς νῦν ἔδει βουλεύεσθαι.", "st": "4.1"}, {"sp": "N", "t": "πρῶτον μὲν οὖν οὐκ ἀθυμητέον, ὦ ἄνδρες Ἀθηναῖοι, τοῖς παροῦσι πράγμασιν, οὐδ’ εἰ πάνυ φαύλως ἔχειν δοκεῖ. ὃ γάρ ἐστι χείριστον αὐτῶν ἐκ τοῦ παρεληλυθότος χρόνου, τοῦτο πρὸς τὰ μέλλοντα βέλτιστον ὑπάρχει. τί οὖν ἐστι τοῦτο; ὅτι οὐδέν, ὦ ἄνδρες Ἀθηναῖοι, τῶν δεόντων ποιούντων ὑμῶν κακῶς τὰ πράγματ’ ἔχει· ἐπεί τοι, εἰ πάνθ’ ἃ προσῆκε πραττόντων οὕτως εἶχεν, οὐδ’ ἂν ἐλπὶς ἦν αὐτὰ βελτίω γενέσθαι.", "st": "4.2"}, {"sp": "N", "t": "ἔπειτ’ ἐνθυμητέον καὶ παρ’ ἄλλων ἀκούουσι καὶ τοῖς εἰδόσιν αὐτοῖς ἀναμιμνῃσκομένοις, ἡλίκην ποτ’ ἐχόντων δύναμιν Λακεδαιμονίων, ἐξ οὗ χρόνος οὐ πολύς, ὡς καλῶς καὶ προσηκόντως οὐδὲν ἀνάξιον ὑμεῖς ἐπράξατε τῆς πόλεως, ἀλλ’ ὑπεμείναθ’ ὑπὲρ τῶν δικαίων τὸν πρὸς ἐκείνους πόλεμον. τίνος οὖν εἵνεκα ταῦτα λέγω; ἵν’ ἴδητ’, ὦ ἄνδρες Ἀθηναῖοι, καὶ θεάσησθε, ὅτι οὐδὲν οὔτε φυλαττομένοις ὑμῖν ἐστιν φοβερόν, οὔτ’, ἂν ὀλιγωρῆτε, τοιοῦτον οἷον ἂν ὑμεῖς βούλοισθε, παραδείγμασι χρώμενοι τῇ τότε ῥώμῃ τῶν Λακεδαιμονίων, ἧς ἐκρατεῖτ’ ἐκ τοῦ προσέχειν τοῖς πράγμασι τὸν νοῦν, καὶ τῇ νῦν ὕβρει τούτου, δι’ ἣν ταραττόμεθ’ ἐκ τοῦ μηδὲν φροντίζειν ὧν ἐχρῆν.", "st": "4.3"}, {"sp": "N", "t": "εἰ δέ τις ὑμῶν, ὦ ἄνδρες Ἀθηναῖοι, δυσπολέμητον οἴεται τὸν Φίλιππον εἶναι, σκοπῶν τό τε πλῆθος τῆς ὑπαρχούσης αὐτῷ δυνάμεως καὶ τὸ τὰ χωρία πάντ’ ἀπολωλέναι τῇ πόλει, ὀρθῶς μὲν οἴεται, λογισάσθω μέντοι τοῦθ’, ὅτι εἴχομέν ποθ’ ἡμεῖς, ὦ ἄνδρες Ἀθηναῖοι, Πύδναν καὶ Ποτείδαιαν καὶ Μεθώνην καὶ πάντα τὸν τόπον τοῦτον οἰκεῖον κύκλῳ, καὶ πολλὰ τῶν μετ’ ἐκείνου νῦν ὄντων ἐθνῶν αὐτονομούμενα κἀλεύθερ’ ὑπῆρχε, καὶ μᾶλλον ἡμῖν ἐβούλετ’ ἔχειν οἰκείως ἢ ’κείνῳ.", "st": "4.4"}, {"sp": "N", "t": "εἰ τοίνυν ὁ Φίλιππος τότε ταύτην ἔσχε τὴν γνώμην, ὡς χαλεπὸν πολεμεῖν ἐστιν Ἀθηναίοις ἔχουσι τοσαῦτ’ ἐπιτειχίσματα τῆς αὑτοῦ χώρας ἔρημον ὄντα συμμάχων, οὐδὲν ἂν ὧν νυνὶ πεποίηκεν ἔπραξεν οὐδὲ τοσαύτην ἐκτήσατ’ ἂν δύναμιν. ἀλλ’ εἶδεν, ὦ ἄνδρες Ἀθηναῖοι, τοῦτο καλῶς ἐκεῖνος, ὅτι ταῦτα μέν ἐστιν ἅπαντα τὰ χωρί’ ἆθλα τοῦ πολέμου κείμεν’ ἐν μέσῳ, φύσει δ’ ὑπάρχει τοῖς παροῦσι τὰ τῶν ἀπόντων, καὶ τοῖς ἐθέλουσι πονεῖν καὶ κινδυνεύειν τὰ τῶν ἀμελούντων.", "st": "4.5"}, {"sp": "N", "t": "καὶ γάρ τοι ταύτῃ χρησάμενος τῇ γνώμῃ πάντα κατέστραπται καὶ ἔχει, τὰ μὲν ὡς ἂν ἑλών τις ἔχοι πολέμῳ, τὰ δὲ σύμμαχα καὶ φίλα ποιησάμενος· καὶ γὰρ συμμαχεῖν καὶ προσέχειν τὸν νοῦν τούτοις ἐθέλουσιν ἅπαντες, οὓς ἂν ὁρῶσι παρεσκευασμένους καὶ πράττειν ἐθέλοντας ἃ χρή.", "st": "4.6"}, {"sp": "N", "t": "ἂν τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, καὶ ὑμεῖς ἐπὶ τῆς τοιαύτης ἐθελήσητε γενέσθαι γνώμης νῦν, ἐπειδήπερ οὐ πρότερον, καὶ ἕκαστος ὑμῶν, οὗ δεῖ καὶ δύναιτ’ ἂν παρασχεῖν αὑτὸν χρήσιμον τῇ πόλει, πᾶσαν ἀφεὶς τὴν εἰρωνείαν ἕτοιμος πράττειν ὑπάρξῃ, ὁ μὲν χρήματ’ ἔχων εἰσφέρειν, ὁ δ’ ἐν ἡλικίᾳ στρατεύεσθαι, — συνελόντι δ’ ἁπλῶς ἂν ὑμῶν αὐτῶν ἐθελήσητε γενέσθαι, καὶ παύσησθ’ αὐτὸς μὲν οὐδὲν ἕκαστος ποιήσειν ἐλπίζων, τὸν δὲ πλησίον πάνθ’ ὑπὲρ αὐτοῦ πράξειν, καὶ τὰ ὑμέτερ’ αὐτῶν κομιεῖσθ’, ἂν θεὸς θέλῃ, καὶ τὰ κατερρᾳθυμημένα πάλιν ἀναλήψεσθε, κἀκεῖνον τιμωρήσεσθε.", "st": "4.7"}, {"sp": "N", "t": "μὴ γὰρ ὡς θεῷ νομίζετ’ ἐκείνῳ τὰ παρόντα πεπηγέναι πράγματ’ ἀθάνατα, ἀλλὰ καὶ μισεῖ τις ἐκεῖνον καὶ δέδιεν, ὦ ἄνδρες Ἀθηναῖοι, καὶ φθονεῖ, καὶ τῶν πάνυ νῦν δοκούντων οἰκείως ἔχειν· καὶ ἅπανθ’ ὅσα περ κἀν ἄλλοις τισὶν ἀνθρώποις ἔνι, ταῦτα κἀν τοῖς μετ’ ἐκείνου χρὴ νομίζειν ἐνεῖναι. κατέπτηχε μέντοι πάντα ταῦτα νῦν, οὐκ ἔχοντ’ ἀποστροφὴν διὰ τὴν ὑμετέραν βραδυτῆτα καὶ ῥᾳθυμίαν· ἣν ἀποθέσθαι φημὶ δεῖν ἤδη.", "st": "4.8"}, {"sp": "N", "t": "ὁρᾶτε γάρ, ὦ ἄνδρες Ἀθηναῖοι, τὸ πρᾶγμα, οἷ προελήλυθ’ ἀσελγείας ἅνθρωπος, ὃς οὐδ’ αἵρεσιν ὑμῖν δίδωσι τοῦ πράττειν ἢ ἄγειν ἡσυχίαν, ἀλλ’ ἀπειλεῖ καὶ λόγους ὑπερηφάνους, ὥς φασι, λέγει, καὶ οὐχ οἷός ἐστιν ἔχων ἃ κατέστραπται μένειν ἐπὶ τούτων, ἀλλ’ ἀεί τι προσπεριβάλλεται καὶ κύκλῳ πανταχῇ μέλλοντας ἡμᾶς καὶ καθημένους περιστοιχίζεται.", "st": "4.9"}, {"sp": "N", "t": "πότ’ οὖν, ὦ ἄνδρες Ἀθηναῖοι, πόθ’ ἃ χρὴ πράξετε; ἐπειδὰν τί γένηται; ἐπειδὰν νὴ Δί’ ἀνάγκη τις ᾖ. νῦν δὲ τί χρὴ τὰ γιγνόμεν’ ἡγεῖσθαι; ἐγὼ μὲν γὰρ οἴομαι τοῖς ἐλευθέροις μεγίστην ἀνάγκην τὴν ὑπὲρ τῶν πραγμάτων αἰσχύνην εἶναι. ἢ βούλεσθ’, εἰπέ μοι, περιιόντες αὑτῶν πυνθάνεσθαι, “λέγεταί τι καινόν;” γένοιτο γὰρ ἄν τι καινότερον ἢ Μακεδὼν ἀνὴρ Ἀθηναίους καταπολεμῶν καὶ τὰ τῶν Ἑλλήνων διοικῶν; “τέθνηκε Φίλιππος;” “οὐ μὰ Δί’, ἀλλ’ ἀσθενεῖ.”", "st": "4.10"}, {"sp": "N", "t": "τί δ’ ὑμῖν διαφέρει; καὶ γὰρ ἂν οὗτός τι πάθῃ, ταχέως ὑμεῖς ἕτερον Φίλιππον ποιήσετε, ἄνπερ οὕτω προσέχητε τοῖς πράγμασι τὸν νοῦν· οὐδὲ γὰρ οὗτος παρὰ τὴν αὑτοῦ ῥώμην τοσοῦτον ἐπηύξηται ὅσον παρὰ τὴν ἡμετέραν ἀμέλειαν.", "st": "4.11"}, {"sp": "N", "t": "καίτοι καὶ τοῦτο· εἴ τι πάθοι καὶ τὰ τῆς τύχης ἡμῖν, ἥπερ ἀεὶ βέλτιον ἢ ἡμεῖς ἡμῶν αὐτῶν ἐπιμελούμεθα, καὶ τοῦτ’ ἐξεργάσαιτο, ἴσθ’ ὅτι πλησίον μὲν ὄντες, ἅπασιν ἂν τοῖς πράγμασιν τεταραγμένοις ἐπιστάντες ὅπως βούλεσθε διοικήσαισθε, ὡς δὲ νῦν ἔχετε, οὐδὲ διδόντων τῶν καιρῶν Ἀμφίπολιν δέξασθαι δύναισθ’ ἄν, ἀπηρτημένοι καὶ ταῖς παρασκευαῖς καὶ ταῖς γνώμαις.", "st": "4.12"}, {"sp": "N", "t": "ὡς μὲν οὖν δεῖ τὰ προσήκοντα ποιεῖν ἐθέλοντας ὑπάρχειν ἅπαντας ἑτοίμως, ὡς ἐγνωκότων ὑμῶν καὶ πεπεισμένων, παύομαι λέγων· τὸν δὲ τρόπον τῆς παρασκευῆς ἣν ἀπαλλάξαι ἂν τῶν τοιούτων πραγμάτων ὑμᾶς οἴομαι, καὶ τὸ πλῆθος ὅσον, καὶ πόρους οὕστινας χρημάτων, καὶ τἄλλ’ ὡς ἄν μοι βέλτιστα καὶ τάχιστα δοκεῖ παρασκευασθῆναι, καὶ δὴ πειράσομαι λέγειν, δεηθεὶς ὑμῶν, ὦ ἄνδρες Ἀθηναῖοι, τοσοῦτον.", "st": "4.13"}, {"sp": "N", "t": "ἐπειδὰν ἅπαντ’ ἀκούσητε κρίνατε, μὴ πρότερον προλαμβάνετε· μηδ’ ἂν ἐξ ἀρχῆς δοκῶ τινι καινὴν παρασκευὴν λέγειν, ἀναβάλλειν με τὰ πράγμαθ’ ἡγείσθω. οὐ γὰρ οἱ “ταχὺ” καὶ “τήμερον” εἰπόντες μάλιστ’ εἰς δέον λέγουσιν (οὐ γὰρ ἂν τά γ’ ἤδη γεγενημένα τῇ νυνὶ βοηθείᾳ κωλῦσαι δυνηθεῖμεν),", "st": "4.14"}, {"sp": "N", "t": "ἀλλ’ ὃς ἂν δείξῃ τίς πορισθεῖσα παρασκευὴ καὶ πόση καὶ πόθεν διαμεῖναι δυνήσεται, ἕως ἂν ἢ διαλυσώμεθα πεισθέντες τὸν πόλεμον ἢ περιγενώμεθα τῶν ἐχθρῶν· οὕτω γὰρ οὐκέτι τοῦ λοιποῦ πάσχοιμεν ἂν κακῶς. οἶμαι τοίνυν ἐγὼ ταῦτα λέγειν ἔχειν, μὴ κωλύων εἴ τις ἄλλος ἐπαγγέλλεταί τι. ἡ μὲν οὖν ὑπόσχεσις οὕτω μεγάλη, τὸ δὲ πρᾶγμ’ ἤδη τὸν ἔλεγχον δώσει· κριταὶ δ’ ὑμεῖς ἔσεσθε.", "st": "4.15"}, {"sp": "N", "t": "πρῶτον μὲν τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, τριήρεις πεντήκοντα παρασκευάσασθαι φημὶ δεῖν, εἶτ’ αὐτοὺς οὕτω τὰς γνώμας ἔχειν ὡς, ἐάν τι δέῃ, πλευστέον εἰς ταύτας αὐτοῖς ἐμβᾶσιν. πρὸς δὲ τούτοις τοῖς ἡμίσεσιν τῶν ἱππέων ἱππαγωγοὺς τριήρεις καὶ πλοῖ’ ἱκανὰ εὐτρεπίσαι κελεύω.", "st": "4.16"}, {"sp": "N", "t": "ταῦτα μὲν οἶμαι δεῖν ὑπάρχειν ἐπὶ τὰς ἐξαίφνης ταύτας ἀπὸ τῆς οἰκείας χώρας αὐτοῦ στρατείας εἰς Πύλας καὶ Χερρόνησον καὶ Ὄλυνθον καὶ ὅποι βούλεται· δεῖ γὰρ ἐκείνῳ τοῦτ’ ἐν τῇ γνώμῃ παραστῆσαι, ὡς ὑμεῖς ἐκ τῆς ἀμελείας ταύτης τῆς ἄγαν, ὥσπερ εἰς Εὔβοιαν καὶ πρότερόν ποτέ φασιν εἰς Ἁλίαρτον καὶ τὰ τελευταῖα πρώην εἰς Πύλας, ἴσως ἂν ὁρμήσαιτε—", "st": "4.17"}, {"sp": "N", "t": "οὔτοι παντελῶς, οὐδ’ εἰ μὴ ποιήσαιτ’ ἂν τοῦτο, ὡς ἔγωγέ φημι δεῖν, εὐκαταφρόνητόν ἐστιν—ἵν’ ἢ διὰ τὸν φόβον εἰδὼς εὐτρεπεῖς ὑμᾶς (εἴσεται γὰρ ἀκριβῶς· εἰσὶ γάρ, εἰσὶν οἱ πάντ’ ἐξαγγέλλοντες ἐκείνῳ παρ’ ἡμῶν αὐτῶν πλείους τοῦ δέοντος) ἡσυχίαν ἔχῃ, ἢ παριδὼν ταῦτ’ ἀφύλακτος ληφθῇ, μηδενὸς ὄντος ἐμποδὼν πλεῖν ἐπὶ τὴν ἐκείνου χώραν ὑμῖν, ἂν ἐνδῷ καιρόν.", "st": "4.18"}, {"sp": "N", "t": "ταῦτα μέν ἐστιν ἃ πᾶσι δεδόχθαι φημὶ δεῖν καὶ παρεσκευάσθαι προσήκειν οἴομαι· πρὸ δὲ τούτων δύναμίν τιν’, ὦ ἄνδρες Ἀθηναῖοι, φημὶ προχειρίσασθαι δεῖν ὑμᾶς, ἣ συνεχῶς πολεμήσει καὶ κακῶς ἐκεῖνον ποιήσει. μή μοι μυρίους μηδὲ δισμυρίους ξένους, μηδὲ τὰς ἐπιστολιμαίους ταύτας δυνάμεις, ἀλλ’ ἣ τῆς πόλεως ἔσται, κἂν ὑμεῖς ἕνα κἂν πλείους κἂν τὸν δεῖνα κἂν ὁντινοῦν χειροτονήσητε στρατηγόν, τούτῳ πείσεται καὶ ἀκολουθήσει.", "st": "4.19"}, {"sp": "N", "t": "καὶ τροφὴν ταύτῃ πορίσαι κελεύω. ἔσται δ’ αὕτη τίς ἡ δύναμις καὶ πόση, καὶ πόθεν τὴν τροφὴν ἕξει, καὶ πῶς ταῦτ’ ἐθελήσει ποιεῖν; ἐγὼ φράσω, καθ’ ἕκαστον τούτων διεξιὼν χωρίς. ξένους μὲν λέγω—καὶ ὅπως μὴ ποιήσεθ’ ὃ πολλάκις ὑμᾶς ἔβλαψεν· πάντ’ ἐλάττω νομίζοντες εἶναι τοῦ δέοντος, καὶ τὰ μέγιστ’ ἐν τοῖς ψηφίσμασιν αἱρούμενοι, ἐπὶ τῷ πράττειν οὐδὲ τὰ μικρὰ ποιεῖτε· ἀλλὰ τὰ μικρὰ ποιήσαντες καὶ πορίσαντες τούτοις προστίθετε, ἂν ἐλάττω φαίνηται.", "st": "4.20"}, {"sp": "N", "t": "λέγω δὴ τοὺς πάντας στρατιώτας δισχιλίους, τούτων δ’ Ἀθηναίους φημὶ δεῖν εἶναι πεντακοσίους, ἐξ ἧς ἄν τινος ὑμῖν ἡλικίας καλῶς ἔχειν δοκῇ, χρόνον τακτὸν στρατευομένους, μὴ μακρὸν τοῦτον, ἀλλ’ ὅσον ἂν δοκῇ καλῶς ἔχειν, ἐκ διαδοχῆς ἀλλήλοις· τοὺς δ’ ἄλλους ξένους εἶναι κελεύω. καὶ μετὰ τούτων ἱππέας διακοσίους, καὶ τούτων πεντήκοντ’ Ἀθηναίους τοὐλάχιστον, ὥσπερ τοὺς πεζούς, τὸν αὐτὸν τρόπον στρατευομένους· καὶ ἱππαγωγοὺς τούτοις.", "st": "4.21"}, {"sp": "N", "t": "εἶεν· τί πρὸς τούτοις ἔτι; ταχείας τριήρεις δέκα· δεῖ γάρ, ἔχοντος ἐκείνου ναυτικόν, καὶ ταχειῶν τριήρων ἡμῖν, ὅπως ἀσφαλῶς ἡ δύναμις πλέῃ. πόθεν δὴ τούτοις ἡ τροφὴ γενήσεται; ἐγὼ καὶ τοῦτο φράσω καὶ δείξω, ἐπειδάν, διότι τηλικαύτην ἀποχρῆν οἶμαι τὴν δύναμιν καὶ πολίτας τοὺς στρατευομένους εἶναι κελεύω, διδάξω.", "st": "4.22"}, {"sp": "N", "t": "τοσαύτην μέν, ὦ ἄνδρες Ἀθηναῖοι, διὰ ταῦτα, ὅτι οὐκ ἔνι νῦν ἡμῖν πορίσασθαι δύναμιν τὴν ἐκείνῳ παραταξομένην, ἀλλὰ λῃστεύειν ἀνάγκη καὶ τούτῳ τῷ τρόπῳ τοῦ πολέμου χρῆσθαι τὴν πρώτην· οὐ τοίνυν ὑπέρογκον αὐτήν (οὐ γὰρ ἔστι μισθὸς οὐδὲ τροφή), οὐδὲ παντελῶς ταπεινὴν εἶναι δεῖ.", "st": "4.23"}, {"sp": "N", "t": "πολίτας δὲ παρεῖναι καὶ συμπλεῖν διὰ ταῦτα κελεύω, ὅτι καὶ πρότερόν ποτ’ ἀκούω ξενικὸν τρέφειν ἐν Κορίνθῳ τὴν πόλιν, οὗ Πολύστρατος ἡγεῖτο καὶ Ἰφικράτης καὶ Χαβρίας καὶ ἄλλοι τινές, καὶ αὐτοὺς ὑμᾶς συστρατεύεσθαι· καὶ οἶδ’ ἀκούων ὅτι Λακεδαιμονίους παραταττόμενοι μεθ’ ὑμῶν ἐνίκων οὗτοι οἱ ξένοι καὶ ὑμεῖς μετ’ ἐκείνων. ἐξ οὗ δ’ αὐτὰ καθ’ αὑτὰ τὰ ξενικὰ ὑμῖν στρατεύεται, τοὺς φίλους νικᾷ καὶ τοὺς συμμάχους, οἱ δ’ ἐχθροὶ μείζους τοῦ δέοντος γεγόνασιν. καὶ παρακύψαντ’ ἐπὶ τὸν τῆς πόλεως πόλεμον, πρὸς Ἀρτάβαζον καὶ πανταχοῖ μᾶλλον οἴχεται πλέοντα, ὁ δὲ στρατηγὸς ἀκολουθεῖ, εἰκότως· οὐ γὰρ ἔστιν ἄρχειν μὴ διδόντα μισθόν.", "st": "4.24"}, {"sp": "N", "t": "τί οὖν κελεύω; τὰς προφάσεις ἀφελεῖν καὶ τοῦ στρατηγοῦ καὶ τῶν στρατιωτῶν, μισθὸν πορίσαντας καὶ στρατιώτας οἰκείους ὥσπερ ἐπόπτας τῶν στρατηγουμένων παρακαταστήσαντας· ἐπεὶ νῦν γε γέλως ἔσθ’ ὡς χρώμεθα τοῖς πράγμασιν. εἰ γὰρ ἔροιτό τις ὑμᾶς, “εἰρήνην ἄγετ’, ὦ ἄνδρες Ἀθηναῖοι;” “μὰ Δί’ οὐχ ἡμεῖς γ’,” εἴποιτ’ ἄν, “ἀλλὰ Φιλίππῳ πολεμοῦμεν.”", "st": "4.25"}, {"sp": "N", "t": "οὐκ ἐχειροτονεῖτε δ’ ἐξ ὑμῶν αὐτῶν δέκα ταξιάρχους καὶ στρατηγοὺς καὶ φυλάρχους καὶ ἱππάρχους δύο; τί οὖν οὗτοι ποιοῦσιν; πλὴν ἑνὸς ἀνδρός, ὃν ἂν ἐκπέμψητ’ ἐπὶ τὸν πόλεμον, οἱ λοιποὶ τὰς πομπὰς πέμπουσιν ὑμῖν μετὰ τῶν ἱεροποιῶν· ὥσπερ γὰρ οἱ πλάττοντες τοὺς πηλίνους, εἰς τὴν ἀγορὰν χειροτονεῖτε τοὺς ταξιάρχους καὶ τοὺς φυλάρχους, οὐκ ἐπὶ τὸν πόλεμον.", "st": "4.26"}, {"sp": "N", "t": "οὐ γὰρ ἐχρῆν, ὦ ἄνδρες Ἀθηναῖοι, ταξιάρχους παρ’ ὑμῶν, ἵππαρχον παρ’ ὑμῶν, ἄρχοντας οἰκείους εἶναι, ἵν’ ἦν ὡς ἀληθῶς τῆς πόλεως ἡ δύναμις; ἀλλ’ εἰς μὲν Λῆμνον τὸν παρ’ ὑμῶν ἵππαρχον δεῖ πλεῖν, τῶν δ’ ὑπὲρ τῶν τῆς πόλεως κτημάτων ἀγωνιζομένων Μενέλαον ἱππαρχεῖν. καὶ οὐ τὸν ἄνδρα μεμφόμενος ταῦτα λέγω, ἀλλ’ ὑφ’ ὑμῶν ἔδει κεχειροτονημένον εἶναι τοῦτον, ὅστις ἂν ᾖ.", "st": "4.27"}, {"sp": "N", "t": "ἴσως δὲ ταῦτα μὲν ὀρθῶς ἡγεῖσθε λέγεσθαι, τὸ δὲ τῶν χρημάτων, πόσα καὶ πόθεν ἔσται, μάλιστα ποθεῖτ’ ἀκοῦσαι. τοῦτο δὴ καὶ περαίνω. χρήματα τοίνυν· ἔστι μὲν ἡ τροφή, σιτηρέσιον μόνον, τῇ δυνάμει ταύτῃ τάλαντ’ ἐνενήκοντα καὶ μικρόν τι πρός, δέκα μὲν ναυσὶ ταχείαις τετταράκοντα τάλαντα, εἴκοσιν εἰς τὴν ναῦν μναῖ τοῦ μηνὸς ἑκάστου, στρατιώταις δὲ δισχιλίοις τοσαῦθ’ ἕτερα, ἵνα δέκα τοῦ μηνὸς ὁ στρατιώτης δραχμὰς σιτηρέσιον λαμβάνῃ, τοῖς δ’ ἱππεῦσι διακοσίοις οὖσιν, ἐὰν τριάκοντα δραχμὰς ἕκαστος λαμβάνῃ τοῦ μηνός, δώδεκα τάλαντα.", "st": "4.28"}, {"sp": "N", "t": "εἰ δέ τις οἴεται μικρὰν ἀφορμὴν εἶναι, σιτηρέσιον τοῖς στρατευομένοις ὑπάρχειν, οὐκ ὀρθῶς ἔγνωκεν· ἐγὼ γὰρ οἶδα σαφῶς ὅτι, τοῦτ’ ἂν γένηται, προσποριεῖ τὰ λοιπὰ αὐτὸ τὸ στράτευμ’ ἀπὸ τοῦ πολέμου, οὐδένα τῶν Ἑλλήνων ἀδικοῦν οὐδὲ τῶν συμμάχων, ὥστ’ ἔχειν μισθὸν ἐντελῆ. ἐγὼ συμπλέων ἐθελοντὴς πάσχειν ὁτιοῦν ἕτοιμος, ἐὰν μὴ ταῦθ’ οὕτως ἔχῃ. πόθεν οὖν ὁ πόρος τῶν χρημάτων, ἃ παρ’ ὑμῶν κελεύω γενέσθαι; τοῦτ’ ἤδη λέξω.", "st": "4.29"}, {"sp": "N", "t": "ΠΟΡΟΥ ΑΠΟΔΕΙΞΙΣ.", "st": "4.30"}, {"sp": "N", "t": "ἃ μὲν ἡμεῖς, ὦ ἄνδρες Ἀθηναῖοι, δεδυνήμεθ’ εὑρεῖν ταῦτ’ ἐστίν· ἐπειδὰν δ’ ἐπιχειροτονῆτε τὰς γνώμας, ἂν ὑμῖν ἀρέσκῃ, χειροτονήσετε, ἵνα μὴ μόνον ἐν τοῖς ψηφίσμασι καὶ ταῖς ἐπιστολαῖς πολεμῆτε Φιλίππῳ, ἀλλὰ καὶ τοῖς ἔργοις.", "st": "4.30"}, {"sp": "N", "t": "δοκεῖτε δέ μοι πολὺ βέλτιον ἂν περὶ τοῦ πολέμου καὶ ὅλης τῆς παρασκευῆς βουλεύσασθαι, εἰ τὸν τόπον, ὦ ἄνδρες Ἀθηναῖοι, τῆς χώρας, πρὸς ἣν πολεμεῖτε, ἐνθυμηθείητε, καὶ λογίσαισθ’ ὅτι τοῖς πνεύμασιν καὶ ταῖς ὥραις τοῦ ἔτους τὰ πολλὰ προλαμβάνων διαπράττεται Φίλιππος, καὶ φυλάξας τοὺς ἐτησίας ἢ τὸν χειμῶν’ ἐπιχειρεῖ, ἡνίκ’ ἂν ἡμεῖς μὴ δυναίμεθ’ ἐκεῖσ’ ἀφικέσθαι.", "st": "4.31"}, {"sp": "N", "t": "δεῖ τοίνυν ταῦτ’ ἐνθυμουμένους μὴ βοηθείαις πολεμεῖν (ὑστεριοῦμεν γὰρ ἁπάντων), ἀλλὰ παρασκευῇ συνεχεῖ καὶ δυνάμει. ὑπάρχει δ’ ὑμῖν χειμαδίῳ μὲν χρῆσθαι τῇ δυνάμει Λήμνῳ καὶ Θάσῳ καὶ Σκιάθῳ καὶ ταῖς ἐν τούτῳ τῷ τόπῳ νήσοις, ἐν αἷς καὶ λιμένες καὶ σῖτος καὶ ἃ χρὴ στρατεύματι πάνθ’ ὑπάρχει· τὴν δ’ ὥραν τοῦ ἔτους, ὅτε καὶ πρὸς τῇ γῇ γενέσθαι ῥᾴδιον καὶ τὸ τῶν πνευμάτων ἀσφαλές, πρὸς αὐτῇ τῇ χώρᾳ καὶ πρὸς τοῖς τῶν ἐμπορίων στόμασιν ῥᾳδίως ἔσται.", "st": "4.32"}, {"sp": "N", "t": "ἃ μὲν οὖν χρήσεται καὶ πότε τῇ δυνάμει, παρὰ τὸν καιρὸν ὁ τούτων κύριος καταστὰς ὑφ’ ὑμῶν βουλεύσεται· ἃ δ’ ὑπάρξαι δεῖ παρ’ ὑμῶν, ταῦτ’ ἐστὶν ἁγὼ γέγραφα. ἂν ταῦτ’, ὦ ἄνδρες Ἀθηναῖοι, πορίσητε, τὰ χρήματα πρῶτον ἃ λέγω, εἶτα καὶ τἄλλα παρασκευάσαντες, τοὺς στρατιώτας, τὰς τριήρεις, τοὺς ἱππέας, ἐντελῆ πᾶσαν τὴν δύναμιν νόμῳ κατακλείσητ’ ἐπὶ τῷ πολέμῳ μένειν, τῶν μὲν χρημάτων αὐτοὶ ταμίαι καὶ πορισταὶ γιγνόμενοι, τῶν δὲ πράξεων παρὰ τοῦ στρατηγοῦ τὸν λόγον ζητοῦντες, παύσεσθ’ ἀεὶ περὶ τῶν αὐτῶν βουλευόμενοι καὶ πλέον οὐδὲν ποιοῦντες,", "st": "4.33"}, {"sp": "N", "t": "καὶ ἔτι πρὸς τούτῳ πρῶτον μέν, ὦ ἄνδρες Ἀθηναῖοι, τὸν μέγιστον τῶν ἐκείνου πόρων ἀφαιρήσεσθε. ἔστι δ’ οὗτος τίς; ἀπὸ τῶν ὑμετέρων ὑμῖν πολεμεῖ συμμάχων, ἄγων καὶ φέρων τοὺς πλέοντας τὴν θάλατταν. ἔπειτα τί πρὸς τούτῳ; τοῦ πάσχειν αὐτοὶ κακῶς ἔξω γενήσεσθε, οὐχ ὥσπερ τὸν παρελθόντα χρόνον εἰς Λῆμνον καὶ Ἴμβρον ἐμβαλὼν αἰχμαλώτους πολίτας ὑμετέρους ᾤχετ’ ἔχων, πρὸς τῷ Γεραιστῷ τὰ πλοῖα συλλαβὼν ἀμύθητα χρήματ’ ἐξέλεξε, τὰ τελευταῖ’ εἰς Μαραθῶν’ ἀπέβη καὶ τὴν ἱερὰν ἀπὸ τῆς χώρας ᾤχετ’ ἔχων τριήρη, ὑμεῖς δ’ οὔτε ταῦτα δύνασθε κωλύειν οὔτ’ εἰς τοὺς χρόνους, οὓς ἂν προθῆσθε, βοηθεῖν.", "st": "4.34"}, {"sp": "N", "t": "καίτοι τί δήποτ’, ὦ ἄνδρες Ἀθηναῖοι, νομίζετε τὴν μὲν τῶν Παναθηναίων ἑορτὴν καὶ τὴν τῶν Διονυσίων ἀεὶ τοῦ καθήκοντος χρόνου γίγνεσθαι, ἄν τε δεινοὶ λάχωσιν ἄν τ’ ἰδιῶται οἱ τούτων ἑκατέρων ἐπιμελούμενοι, εἰς ἃ τοσαῦτ’ ἀναλίσκεται χρήματα, ὅσ’ οὐδ’ εἰς ἕνα τῶν ἀποστόλων, καὶ τοσοῦτον ὄχλον καὶ παρασκευὴν ὅσην οὐκ οἶδ’ εἴ τι τῶν ἁπάντων ἔχει, τοὺς δ’ ἀποστόλους πάντας ὑμῖν ὑστερίζειν τῶν καιρῶν, τὸν εἰς Μεθώνην, τὸν εἰς Παγασάς, τὸν εἰς Ποτείδαιαν;", "st": "4.35"}, {"sp": "N", "t": "ὅτι ἐκεῖνα μὲν ἅπαντα νόμῳ τέτακται, καὶ πρόοιδεν ἕκαστος ὑμῶν ἐκ πολλοῦ τίς χορηγὸς ἢ γυμνασίαρχος τῆς φυλῆς, πότε καὶ παρὰ τοῦ καὶ τί λαβόντα τί δεῖ ποιεῖν, οὐδὲν ἀνεξέταστον οὐδ’ ἀόριστον ἐν τούτοις ἠμέληται· ἐν δὲ τοῖς περὶ τοῦ πολέμου καὶ τῇ τούτου παρασκευῇ ἄτακτα, ἀδιόρθωτα, ἀόρισθ’ ἅπαντα. τοιγαροῦν ἅμ’ ἀκηκόαμέν τι καὶ τριηράρχους καθίσταμεν καὶ τούτοις ἀντιδόσεις ποιούμεθα καὶ περὶ χρημάτων πόρου σκοποῦμεν, καὶ μετὰ ταῦτ’ ἐμβαίνειν τοὺς μετοίκους ἔδοξε καὶ τοὺς χωρὶς οἰκοῦντας,", "st": "4.36"}, {"sp": "N", "t": "εἶτ’ αὐτοὺς πάλιν, εἶτ’ ἀντεμβιβάζειν, εἶτ’ ἐν ὅσῳ ταῦτα μέλλεται, προαπόλωλεν τὸ ἐφ’ ὃ ἂν ἐκπλέωμεν· τὸν γὰρ τοῦ πράττειν χρόνον εἰς τὸ παρασκευάζεσθαι ἀναλίσκομεν, οἱ δὲ τῶν πραγμάτων οὐ μένουσι καιροὶ τὴν ἡμετέραν βραδυτῆτα καὶ εἰρωνείαν. ἃς δὲ τὸν μεταξὺ χρόνον δυνάμεις οἰόμεθ’ ἡμῖν ὑπάρχειν, οὐδὲν οἷαί τ’ οὖσαι ποιεῖν ἐπ’ αὐτῶν τῶν καιρῶν ἐξελέγχονται. ὁ δ’ εἰς τοῦθ’ ὕβρεως ἐλήλυθεν ὥστ’ ἐπιστέλλειν Εὐβοεῦσιν ἤδη τοιαύτας ἐπιστολάς.", "st": "4.37"}, {"sp": "N", "t": "ΕΠΙΣΤΟΛΗΣ ΑΝΑΓΝΩΣΙΣ.", "st": "4.38"}, {"sp": "N", "t": "τούτων, ὦ ἄνδρες Ἀθηναῖοι, τῶν ἀνεγνωσμένων ἀληθῆ μέν ἐστι τὰ πολλά, ὡς οὐκ ἔδει, οὐ μὴν ἀλλ’ ἴσως οὐχ ἡδέ’ ἀκούειν. ἀλλ’ εἰ μέν, ὅσ’ ἄν τις ὑπερβῇ τῷ λόγῳ, ἵνα μὴ λυπήσῃ, καὶ τὰ πράγμαθ’ ὑπερβήσεται, δεῖ πρὸς ἡδονὴν δημηγορεῖν· εἰ δ’ ἡ τῶν λόγων χάρις, ἂν ᾖ μὴ προσήκουσα, ἔργῳ ζημία γίγνεται, αἰσχρόν ἐστι φενακίζειν ἑαυτούς, καὶ ἅπαντ’ ἀναβαλλομένους ἃν ᾖ δυσχερῆ πάντων ὑστερεῖν τῶν ἔργων,", "st": "4.38"}, {"sp": "N", "t": "καὶ μηδὲ τοῦτο δύνασθαι μαθεῖν, ὅτι δεῖ τοὺς ὀρθῶς πολέμῳ χρωμένους οὐκ ἀκολουθεῖν τοῖς πράγμασιν, ἀλλ’ αὐτοὺς ἔμπροσθεν εἶναι τῶν πραγμάτων, καὶ τὸν αὐτὸν τρόπον ὥσπερ τῶν στρατευμάτων ἀξιώσειέ τις ἂν τὸν στρατηγὸν ἡγεῖσθαι, οὕτω καὶ τῶν πραγμάτων τοὺς βουλευομένους, ἵν’ ἃν ἐκείνοις δοκῇ, ταῦτα πράττηται καὶ μὴ τὰ συμβάντ’ ἀναγκάζωνται διώκειν.", "st": "4.39"}, {"sp": "N", "t": "ὑμεῖς δ’, ὦ ἄνδρες Ἀθηναῖοι, πλείστην δύναμιν ἁπάντων ἔχοντες, τριήρεις, ὁπλίτας, ἱππέας, χρημάτων πρόσοδον, τούτων μὲν μέχρι τῆς τήμερον ἡμέρας οὐδενὶ πώποτ’ εἰς δέον τι κέχρησθε, οὐδὲν δ’ ἀπολείπετε, ὥσπερ οἱ βάρβαροι πυκτεύουσιν, οὕτω πολεμεῖν Φιλίππῳ. καὶ γὰρ ἐκείνων ὁ πληγεὶς ἀεὶ τῆς πληγῆς ἔχεται, κἂν ἑτέρωσε πατάξῃ τις, ἐκεῖσ’ εἰσὶν αἱ χεῖρες· προβάλλεσθαι δ’ ἢ βλέπειν ἐναντίον οὔτ’ οἶδεν οὔτ’ ἐθέλει.", "st": "4.40"}, {"sp": "N", "t": "καὶ ὑμεῖς, ἂν ἐν Χερρονήσῳ πύθησθε Φίλιππον, ἐκεῖσε βοηθεῖν ψηφίζεσθε, ἂν ἐν Πύλαις, ἐκεῖσε, ἂν ἄλλοθί που, συμπαραθεῖτ’ ἄνω κάτω, καὶ στρατηγεῖσθ’ ὑπ’ ἐκείνου, βεβούλευσθε δ’ οὐδὲν αὐτοὶ συμφέρον περὶ τοῦ πολέμου, οὐδὲ πρὸ τῶν πραγμάτων προορᾶτ’ οὐδέν, πρὶν ἂν ἢ γεγενημένον ἢ γιγνόμενόν τι πύθησθε. ταῦτα δ’ ἴσως πρότερον μὲν ἐνῆν· νῦν δ’ ἐπ’ αὐτὴν ἥκει τὴν ἀκμήν, ὥστ’ οὐκέτ’ ἐγχωρεῖ.", "st": "4.41"}, {"sp": "N", "t": "δοκεῖ δέ μοι θεῶν τις, ὦ ἄνδρες Ἀθηναῖοι, τοῖς γιγνομένοις ὑπὲρ τῆς πόλεως αἰσχυνόμενος τὴν φιλοπραγμοσύνην ταύτην ἐμβαλεῖν Φιλίππῳ. εἰ γὰρ ἔχων ἃ κατέστραπται καὶ προείληφεν ἡσυχίαν ἔχειν ἤθελε καὶ μηδὲν ἔπραττεν ἔτι, ἀποχρῆν ἐνίοις ὑμῶν ἄν μοι δοκεῖ, ἐξ ὧν αἰσχύνην καὶ ἀνανδρίαν καὶ πάντα τὰ αἴσχιστ’ ὠφληκότες ἂν ἦμεν δημοσίᾳ· νῦν δ’ ἐπιχειρῶν ἀεί τινι καὶ τοῦ πλείονος ὀρεγόμενος ἴσως ἂν ἐκκαλέσαιθ’ ὑμᾶς, εἴπερ μὴ παντάπασιν ἀπεγνώκατε.", "st": "4.42"}, {"sp": "N", "t": "θαυμάζω δ’ ἔγωγε, εἰ μηδεὶς ὑμῶν μήτ’ ἐνθυμεῖται μήτ’ ὀργίζεται, ὁρῶν, ὦ ἄνδρες Ἀθηναῖοι, τὴν μὲν ἀρχὴν τοῦ πολέμου γεγενημένην περὶ τοῦ τιμωρήσασθαι Φίλιππον, τὴν δὲ τελευτὴν οὖσαν ἤδη ὑπὲρ τοῦ μὴ παθεῖν κακῶς ὑπὸ Φιλίππου. ἀλλὰ μὴν ὅτι γ’ οὐ στήσεται, δῆλον, εἰ μή τις κωλύσει. εἶτα τοῦτ’ ἀναμενοῦμεν; καὶ τριήρεις κενὰς καὶ τὰς παρὰ τοῦ δεῖνος ἐλπίδας ἂν ἀποστείλητε, πάντ’ ἔχειν οἴεσθε καλῶς;", "st": "4.43"}, {"sp": "N", "t": "οὐκ ἐμβησόμεθα; οὐκ ἔξιμεν αὐτοὶ μέρει γέ τινι στρατιωτῶν οἰκείων νῦν, εἰ καὶ μὴ πρότερον; οὐκ ἐπὶ τὴν ἐκείνου πλευσόμεθα; ποῖ οὖν προσορμιούμεθ’; ἤρετό τις. εὑρήσει τὰ σαθρά, ὦ ἄνδρες Ἀθηναῖοι, τῶν ἐκείνου πραγμάτων αὐτὸς ὁ πόλεμος, ἂν ἐπιχειρῶμεν· ἂν μέντοι καθώμεθ’ οἴκοι, λοιδορουμένων ἀκούοντες καὶ αἰτιωμένων ἀλλήλους τῶν λεγόντων, οὐδέποτ’ οὐδὲν ἡμῖν μὴ γένηται τῶν δεόντων.", "st": "4.44"}, {"sp": "N", "t": "ὅποι μὲν γὰρ ἄν, οἶμαι, μέρος τι τῆς πόλεως συναποσταλῇ, κἂν μὴ πᾶσα, καὶ τὸ τῶν θεῶν εὐμενὲς καὶ τὸ τῆς τύχης συναγωνίζεται· ὅποι δ’ ἂν στρατηγὸν καὶ ψήφισμα κενὸν καὶ τὰς ἀπὸ τοῦ βήματος ἐλπίδας ἐκπέμψητε, οὐδὲν ὑμῖν τῶν δεόντων γίγνεται, ἀλλ’ οἱ μὲν ἐχθροὶ καταγελῶσιν, οἱ δὲ σύμμαχοι τεθνᾶσι τῷ δέει τοὺς τοιούτους ἀποστόλους.", "st": "4.45"}, {"sp": "N", "t": "οὐ γὰρ ἔστιν, οὐκ ἔστιν ἕν’ ἄνδρα δυνηθῆναί ποτε ταῦθ’ ὑμῖν πρᾶξαι πάνθ’ ὅσα βούλεσθε· ὑποσχέσθαι μέντοι καὶ φῆσαι καὶ τὸν δεῖν’ αἰτιάσασθαι καὶ τὸν δεῖν’ ἔστι, τὰ δὲ πράγματ’ ἐκ τούτων ἀπόλωλεν· ὅταν γὰρ ἡγῆται μὲν ὁ στρατηγὸς ἀθλίων ἀπομίσθων ξένων, οἱ δ’ ὑπὲρ ὧν ἂν ἐκεῖνος πράξῃ πρὸς ὑμᾶς ψευδόμενοι ῥᾳδίως ἐνθάδ’ ὦσιν, ὑμεῖς δ’ ἐξ ὧν ἂν ἀκούσηθ’ ὅ τι ἂν τύχητε ψηφίζησθε, τί καὶ χρὴ προσδοκᾶν;", "st": "4.46"}, {"sp": "N", "t": "πῶς οὖν ταῦτα παύσεται; ὅταν ὑμεῖς, ὦ ἄνδρες Ἀθηναῖοι, τοὺς αὐτοὺς ἀποδείξητε στρατιώτας καὶ μάρτυρας τῶν στρατηγουμένων καὶ δικαστὰς οἴκαδ’ ἐλθόντας τῶν εὐθυνῶν, ὥστε μὴ ἀκούειν μόνον ὑμᾶς τὰ ὑμέτερ’ αὐτῶν, ἀλλὰ καὶ παρόντας ὁρᾶν. νῦν δ’ εἰς τοῦθ’ ἥκει τὰ πράγματ’ αἰσχύνης ὥστε τῶν στρατηγῶν ἕκαστος δὶς καὶ τρὶς κρίνεται παρ’ ὑμῖν περὶ θανάτου, πρὸς δὲ τοὺς ἐχθροὺς οὐδεὶς οὐδ’ ἅπαξ αὐτῶν ἀγωνίσασθαι περὶ θανάτου τολμᾷ, ἀλλὰ τὸν τῶν ἀνδραποδιστῶν καὶ λωποδυτῶν θάνατον μᾶλλον αἱροῦνται τοῦ προσήκοντος· κακούργου μὲν γάρ ἐστι κριθέντ’ ἀποθανεῖν, στρατηγοῦ δὲ μαχόμενον τοῖς πολεμίοις.", "st": "4.47"}, {"sp": "N", "t": "ἡμῶν δ’ οἱ μὲν περιιόντες μετὰ Λακεδαιμονίων φασὶ Φίλιππον πράττειν τὴν Θηβαίων κατάλυσιν καὶ τὰς πολιτείας διασπᾶν, οἱ δ’ ὡς πρέσβεις πέπομφεν ὡς βασιλέα, οἱ δ’ ἐν Ἰλλυριοῖς πόλεις τειχίζειν, οἱ δὲ λόγους πλάττοντες ἕκαστος περιερχόμεθα.", "st": "4.48"}, {"sp": "N", "t": "ἐγὼ δ’ οἶμαι μέν, ὦ ἄνδρες Ἀθηναῖοι, νὴ τοὺς θεοὺς ἐκεῖνον μεθύειν τῷ μεγέθει τῶν πεπραγμένων καὶ πολλὰ τοιαῦτ’ ὀνειροπολεῖν ἐν τῇ γνώμῃ, τήν τ’ ἐρημίαν τῶν κωλυσόντων ὁρῶντα καὶ τοῖς πεπραγμένοις ἐπῃρμένον, οὐ μέντοι μὰ Δί’ οὕτω γε προαιρεῖσθαι πράττειν ὥστε τοὺς ἀνοητοτάτους τῶν παρ’ ἡμῖν εἰδέναι τί μέλλει ποιεῖν ἐκεῖνος· ἀνοητότατοι γάρ εἰσιν οἱ λογοποιοῦντες.", "st": "4.49"}, {"sp": "N", "t": "ἀλλ’ ἂν ἀφέντες ταῦτ’ ἐκεῖν’ εἰδῶμεν, ὅτι ἐχθρὸς ἅνθρωπος καὶ τὰ ἡμέτερ’ ἡμᾶς ἀποστερεῖ καὶ χρόνον πολὺν ὕβρικε, καὶ ἅπανθ’ ὅσα πώποτ’ ἠλπίσαμέν τινα πράξειν ὑπὲρ ἡμῶν καθ’ ἡμῶν εὕρηται, καὶ τὰ λοιπὰ ἐν αὐτοῖς ἡμῖν ἐστί, κἂν μὴ νῦν ἐθέλωμεν ἐκεῖ πολεμεῖν αὐτῷ, ἐνθάδ’ ἴσως ἀναγκασθησόμεθα τοῦτο ποιεῖν, ἂν ταῦτ’ εἰδῶμεν, καὶ τὰ δέοντ’ ἐσόμεθ’ ἐγνωκότες καὶ λόγων ματαίων ἀπηλλαγμένοι· οὐ γὰρ ἅττα ποτ’ ἔσται δεῖ σκοπεῖν, ἀλλ’ ὅτι φαῦλα, ἂν μὴ προσέχητε τὸν νοῦν καὶ τὰ προσήκοντα ποιεῖν ἐθέλητε, εὖ εἰδέναι.", "st": "4.50"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν οὔτ’ ἄλλοτε πώποτε πρὸς χάριν εἱλόμην λέγειν ὅ τι ἂν μὴ καὶ συνοίσειν πεπεισμένος ὦ, νῦν θ’ ἃ γιγνώσκω πάνθ’ ἁπλῶς, οὐδὲν ὑποστειλάμενος, πεπαρρησίασμαι. ἐβουλόμην δ’ ἄν, ὥσπερ ὅτι ὑμῖν συμφέρει τὰ βέλτιστ’ ἀκούειν οἶδα, οὕτως εἰδέναι συνοῖσον καὶ τῷ τὰ βέλτιστ’ εἰπόντι· πολλῷ γὰρ ἂν ἥδιον εἶχον. νῦν δ’ ἐπ’ ἀδήλοις οὖσι τοῖς ἀπὸ τούτων ἐμαυτῷ γενησομένοις, ὅμως ἐπὶ τῷ συνοίσειν ὑμῖν, ἂν πράξητε, ταῦτα πεπεῖσθαι λέγειν αἱροῦμαι. νικῴη δ’ ὅ τι πᾶσιν μέλλει συνοίσειν.", "st": "4.51"}, {"sp": "HDR", "t": "Περὶ τῆς εἰρήνης", "st": "5"}, {"sp": "N", "t": "ὁρῶ μέν, ὦ ἄνδρες Ἀθηναῖοι, τὰ παρόντα πράγματα πολλὴν δυσκολίαν ἔχοντα καὶ ταραχὴν οὐ μόνον τῷ πολλὰ προεῖσθαι καὶ μηδὲν εἶναι προὔργου περὶ αὐτῶν εὖ λέγειν, ἀλλὰ καὶ περὶ τῶν ὑπολοίπων κατὰ ταὐτὰ μηδὲ καθ’ ἓν τὸ συμφέρον πάντας ἡγεῖσθαι, ἀλλὰ τοῖς μὲν ὡδί, τοῖς δ’ ἑτέρως δοκεῖν.", "st": "5.1"}, {"sp": "N", "t": "δυσκόλου δ’ ὄντος φύσει καὶ χαλεποῦ τοῦ βουλεύεσθαι, ἔτι πολλῷ χαλεπώτερον ὑμεῖς αὐτὸ πεποιήκατ’, ὦ ἄνδρες Ἀθηναῖοι· οἱ μὲν γὰρ ἄλλοι πάντες ἄνθρωποι πρὸ τῶν πραγμάτων εἰώθασι χρῆσθαι τῷ βουλεύεσθαι, ὑμεῖς δὲ μετὰ τὰ πράγματα. ἐκ δὲ τούτου συμβαίνει παρὰ πάντα τὸν χρόνον ὃν οἶδ’ ἐγώ, τὸν μὲν οἷς ἂν ἁμάρτητ’ ἐπιτιμῶντα εὐδοκιμεῖν καὶ δοκεῖν εὖ λέγειν, τὰ δὲ πράγματα καὶ περὶ ὧν βουλεύεσθ’ ἐκφεύγειν ὑμᾶς.", "st": "5.2"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ καίπερ τούτων οὕτως ἐχόντων οἴομαι καὶ πεπεικὼς ἐμαυτὸν ἀνέστηκα, ἂν ἐθελήσητε τοῦ θορυβεῖν καὶ φιλονικεῖν ἀποστάντες ἀκούειν, ὡς ὑπὲρ πόλεως βουλευομένοις καὶ τηλικούτων πραγμάτων προσήκει, ἕξειν καὶ λέγειν καὶ συμβουλεύειν δι’ ὧν καὶ τὰ παρόντ’ ἔσται βελτίω καὶ τὰ προειμένα σωθήσεται.", "st": "5.3"}, {"sp": "N", "t": "ἀκριβῶς δ’ εἰδώς, ὦ ἄνδρες Ἀθηναῖοι, τὸ λέγειν περὶ ὧν αὐτὸς εἶπέ τις καὶ περὶ αὑτοῦ παρ’ ὑμῖν ἀεὶ τῶν πάνυ λυσιτελούντων τοῖς τολμῶσιν ὄν, οὕτως ἡγοῦμαι φορτικὸν καὶ ἐπαχθὲς ὥστε ἀνάγκην οὖσαν ὁρῶν ὅμως ἀποκνῶ. νομίζω δ’ ἄμεινον ἂν ὑμᾶς περὶ ὧν νῦν ἐρῶ κρῖναι, μικρὰ τῶν πρότερόν ποτε ῥηθέντων ὑπ’ ἐμοῦ μνημονεύσαντες.", "st": "5.4"}, {"sp": "N", "t": "ἐγὼ γάρ, ὦ ἄνδρες Ἀθηναῖοι, πρῶτον μέν, ἡνίκ’ ἔπειθόν τινες ὑμᾶς, τῶν ἐν Εὐβοίᾳ πραγμάτων ταραττομένων, βοηθεῖν Πλουτάρχῳ καὶ πόλεμον ἄδοξον καὶ δαπανηρὸν ἄρασθαι, πρῶτος καὶ μόνος παρελθὼν ἀντεῖπον, καὶ μόνον οὐ διεσπάσθην ὑπὸ τῶν ἐπὶ μικροῖς λήμμασιν πολλὰ καὶ μεγάλ’ ὑμᾶς ἁμαρτάνειν πεισάντων· καὶ χρόνου βραχέος διελθόντος, μετὰ τοῦ προσοφλεῖν αἰσχύνην καὶ παθεῖν οἷα τῶν ὄντων ἀνθρώπων οὐδένες πώποτε πεπόνθασ’ ὑπὸ τούτων οἷς ἐβοήθησαν, πάντες ὑμεῖς ἔγνωτε τήν τε τῶν τότε ταῦτα πεισάντων κακίαν καὶ τὰ βέλτιστ’ εἰρηκότ’ ἐμέ.", "st": "5.5"}, {"sp": "N", "t": "πάλιν τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, κατιδὼν Νεοπτόλεμον τὸν ὑποκριτὴν τῷ μὲν τῆς τέχνης προσχήματι τυγχάνοντ’ ἀδείας, κακὰ δ’ ἐργαζόμενον τὰ μέγιστα τὴν πόλιν καὶ τὰ παρ’ ὑμῶν διοικοῦντα Φιλίππῳ καὶ πρυτανεύοντα, παρελθὼν εἶπον εἰς ὑμᾶς, οὐδεμιᾶς ἰδίας οὔτ’ ἔχθρας οὔτε συκοφαντίας ἕνεκα, ὡς ἐκ τῶν μετὰ ταῦτ’ ἔργων γέγονεν δῆλον.", "st": "5.6"}, {"sp": "N", "t": "καὶ οὐκέτ’ ἐν τούτοις αἰτιάσομαι τοὺς ὑπὲρ Νεοπτολέμου λέγοντας (οὐδὲ εἷς γὰρ ἦν), ἀλλ’ αὐτοὺς ὑμᾶς· εἰ γὰρ ἐν Διονύσου τραγῳδοὺς ἐθεᾶσθε, ἀλλὰ μὴ περὶ σωτηρίας καὶ κοινῶν πραγμάτων ἦν ὁ λόγος, οὐκ ἂν οὕτως οὔτ’ ἐκείνου πρὸς χάριν οὔτ’ ἐμοῦ πρὸς ἀπέχθειαν ἠκούσατε.", "st": "5.7"}, {"sp": "N", "t": "καίτοι τοῦτό γ’ ὑμᾶς οἶμαι νῦν ἅπαντας ᾐσθῆσθαι, ὅτι τὴν τότ’ ἄφιξιν εἰς τοὺς πολεμίους ποιησάμενος ὑπὲρ τοῦ τἀκεῖ χρήματ’ ὀφειλόμεν’, ὡς ἔφη, κομίσας δεῦρο λῃτουργεῖν, καὶ τούτῳ τῷ λόγῳ πλείστῳ χρησάμενος, ὡς δεινὸν εἴ τις ἐγκαλεῖ τοῖς ἐκεῖθεν ἐνθάδε τὰς εὐπορίας ἄγουσιν, ἐπειδὴ διὰ τὴν εἰρήνην ἀδείας ἔτυχεν, ἣν ἐνθάδ’ ἐκέκτητ’ οὐσίαν φανεράν, ταύτην ἐξαργυρίσας πρὸς ἐκεῖνον ἀπάγων οἴχεται.", "st": "5.8"}, {"sp": "N", "t": "δύο μὲν δὴ ταῦθ’ ὧν προεῖπον ἐγὼ μαρτυρεῖ τοῖς γεγενημένοις λόγοις ὀρθῶς καὶ δικαίως, οἷά περ ἦν, ἀποφανθένθ’ ὑπ’ ἐμοῦ· τὸ τρίτον δ’, ὦ ἄνδρες Ἀθηναῖοι, (καὶ μόνον ἓν τοῦτ’ εἰπὼν ἔτι καὶ δὴ περὶ ὧν παρελήλυθ’ ἐρῶ,) ἡνίκα τοὺς ὅρκους τοὺς περὶ τῆς εἰρήνης ἀπειληφότες ἥκομεν οἱ πρέσβεις,", "st": "5.9"}, {"sp": "N", "t": "τότε Θεσπιάς τινων καὶ Πλαταιὰς ὑπισχνουμένων οἰκισθήσεσθαι, καὶ τοὺς μὲν Φωκέας τὸν Φίλιππον, ἂν γένηται κύριος, σώσειν, τὴν δὲ Θηβαίων πόλιν διοικιεῖν, καὶ τὸν Ὠρωπὸν ὑμῖν ὑπάρξειν, καὶ τὴν Εὔβοιαν ἀντ’ Ἀμφιπόλεως ἀποδοθήσεσθαι, καὶ τοιαύτας ἐλπίδας καὶ φενακισμούς, οἷς ὑπαχθέντες ὑμεῖς οὔτε συμφόρως οὔτ’ ἴσως καλῶς προεῖσθε Φωκέας, οὐδὲν τούτων οὔτ’ ἐξαπατήσας οὔτε σιγήσας ἐγὼ φανήσομαι, ἀλλὰ προειπὼν ὑμῖν, ὡς οἶδ’ ὅτι μνημονεύετε, ὅτι ταῦτ’ οὔτ’ οἶδα οὔτε προσδοκῶ, νομίζω δὲ τὸν λέγοντα ληρεῖν.", "st": "5.10"}, {"sp": "N", "t": "ταῦτα τοίνυν ἅπανθ’, ὅσα φαίνομαι βέλτιον τῶν ἄλλων προορῶν, οὐδ’ εἰς μίαν, ὦ ἄνδρες Ἀθηναῖοι, οὔτε δεινότητ’ οὔτ’ ἀλαζονείαν ἐπανοίσω, οὐδὲ προσποιήσομαι δι’ οὐδὲν ἄλλο γιγνώσκειν καὶ προαισθάνεσθαι πλὴν δι’ ἃν ὑμῖν εἴπω, δύο· ἓν μέν, ὦ ἄνδρες Ἀθηναῖοι, δι’ εὐτυχίαν, ἣν συμπάσης ἐγὼ τῆς ἐν ἀνθρώποις οὔσης δεινότητος καὶ σοφίας ὁρῶ κρατοῦσαν·", "st": "5.11"}, {"sp": "N", "t": "ἕτερον δέ, προῖκα τὰ πράγματα κρίνω καὶ λογίζομαι, καὶ οὐδὲν λῆμμ’ ἂν οὐδεὶς ἔχοι πρὸς οἷς ἐγὼ πεπολίτευμαι καὶ λέγω δεῖξαι προσηρτημένον. ὀρθὸν οὖν, ὅ τι ἄν ποτ’ ἀπ’ αὐτῶν ὑπάρχῃ τῶν πραγμάτων, τὸ συμφέρον φαίνεταί μοι. ὅταν δ’ ἐπὶ θάτερ’ ὥσπερ εἰς τρυτάνην ἀργύριον προσενέγκῃς, οἴχεται φέρον καὶ καθείλκυκε τὸν λογισμὸν ἐφ’ αὑτό, καὶ οὐκ ἂν ἔτ’ ὀρθῶς οὐδ’ ὑγιῶς ὁ τοῦτο ποιήσας περὶ οὐδενὸς λογίσαιτο.", "st": "5.12"}, {"sp": "N", "t": "ἓν μὲν οὖν ἔγωγε πρῶτον ὑπάρχειν φημὶ δεῖν, ὅπως, εἴτε συμμάχους εἴτε σύνταξιν εἴτ’ ἄλλο τι βούλεταί τις κατασκευάζειν τῇ πόλει, τὴν ὑπάρχουσαν εἰρήνην μὴ λύων τοῦτο ποιήσει, οὐχ ὡς θαυμαστὴν οὐδ’ ὡς ἀξίαν οὖσαν ὑμῶν· ἀλλ’ ὁποία τίς ποτ’ ἐστὶν αὕτη, μὴ γενέσθαι μᾶλλον εἶχε τοῖς πράγμασι καιρὸν ἢ γεγενημένη νῦν δι’ ἡμᾶς λυθῆναι· πολλὰ γὰρ προείμεθα, ὧν ὑπαρχόντων τότ’ ἂν ἢ νῦν ἀσφαλέστερος καὶ ῥᾴων ἦν ἡμῖν ὁ πόλεμος.", "st": "5.13"}, {"sp": "N", "t": "δεύτερον δ’, ὁρᾶν ὅπως μὴ προαξόμεθ’, ὦ ἄνδρες Ἀθηναῖοι, τοὺς συνεληλυθότας τούτους καὶ φάσκοντας Ἀμφικτύονας νῦν εἶναι εἰς ἀνάγκην καὶ πρόφασιν κοινοῦ πολέμου πρὸς ἡμᾶς. ἐγὼ γάρ, εἰ γένοιθ’ ἡμῖν πρὸς Φίλιππον πάλιν πόλεμος δι’ Ἀμφίπολιν ἤ τι τοιοῦτον ἔγκλημ’ ἴδιον, οὗ μὴ μετέχουσι Θετταλοὶ μηδ’ Ἀργεῖοι μηδὲ Θηβαῖοι, οὐκ ἂν ἡμῖν οἴομαι τούτων οὐδένας πολεμῆσαι,", "st": "5.14"}, {"sp": "N", "t": "καὶ πάντων ἥκιστα (καί μοι μὴ θορυβήσῃ μηδεὶς πρὶν ἀκοῦσαι) Θηβαίους, οὐχ ὡς ἡδέως ἔχουσιν ἡμῖν, οὐδ’ ὡς οὐκ ἂν χαρίζοιντο Φιλίππῳ, ἀλλ’ ἴσασιν ἀκριβῶς, εἰ καὶ πάνυ φησί τις αὐτοὺς ἀναισθήτους εἶναι, ὅτι, εἰ γενήσεται πόλεμος πρὸς ὑμᾶς αὐτοῖς, τὰ μὲν κακὰ πάνθ’ ἕξουσιν αὐτοί, τοῖς δ’ ἀγαθοῖς ἐφεδρεύων ἕτερος καθεδεῖται. οὔκουν προοῖντ’ ἂν αὑτοὺς εἰς τοῦτο, μὴ κοινῆς τῆς ἀρχῆς καὶ τῆς αἰτίας οὔσης τοῦ πολέμου.", "st": "5.15"}, {"sp": "N", "t": "οὐδέ γ’ εἰ πάλιν πρὸς τοὺς Θηβαίους πολεμήσαιμεν δι’ Ὠρωπὸν ἤ τι τῶν ἰδίων, οὐδὲν ἂν ἡμᾶς παθεῖν ἡγοῦμαι· καὶ γὰρ ἡμῖν κἀκείνοις τοὺς βοηθοῦντας ἂν οἶμαι, εἰς τὴν οἰκείαν εἴ τις ἐμβάλοι, βοηθεῖν, οὐ συνεπιστρατεύσειν οὐδετέροις. καὶ γὰρ αἱ συμμαχίαι τοῦτον ἔχουσι τὸν τρόπον, ὧν καὶ φροντίσειεν ἄν τις, καὶ τὸ πρᾶγμα φύσει τοιοῦτόν ἐστιν·", "st": "5.16"}, {"sp": "N", "t": "οὐκ ἄχρι τῆς ἴσης ἕκαστός ἐστιν εὔνους οὔθ’ ἡμῖν οὔτε Θηβαίοις, σῶς τ’ εἶναι καὶ κρατεῖν τῶν ἄλλων, ἀλλὰ σῶς μὲν εἶναι πάντες ἂν βούλοινθ’ ἕνεχ’ αὑτῶν, κρατήσαντας δὲ τοὺς ἑτέρους δεσπότας ὑπάρχειν αὑτῶν οὐδὲ εἷς. τί οὖν ἡγοῦμαι φοβερὸν καὶ τί φυλάξασθαι δεῖν ἡμᾶς; μὴ κοινὴν πρόφασιν καὶ κοινὸν ἔγκλημ’ ὁ μέλλων πόλεμος πρὸς ἅπαντας λάβῃ.", "st": "5.17"}, {"sp": "N", "t": "εἰ γὰρ Ἀργεῖοι μὲν καὶ Μεσσήνιοι καὶ Μεγαλοπολῖται καί τινες τῶν λοιπῶν Πελοποννησίων, ὅσοι ταὐτὰ τούτοις φρονοῦσι, διὰ τὴν πρὸς Λακεδαιμονίους ἡμῖν ἐπικηρυκείαν ἐχθρῶς σχήσουσι καὶ τὸ δοκεῖν ἐκδέχεσθαί τι τῶν ἐκείνοις πεπραγμένων, Θηβαῖοι δ’ ἔχουσι μέν, ὡς λέγουσιν, ἀπεχθῶς, ἔτι δ’ ἐχθροτέρως σχήσουσιν, ὅτι τοὺς παρ’ ἐκείνων φεύγοντας σῴζομεν καὶ πάντα τρόπον τὴν δυσμένειαν ἐνδεικνύμεθ’ αὐτοῖς,", "st": "5.18"}, {"sp": "N", "t": "Θετταλοὶ δ’, ὅτι τοὺς Φωκέων φυγάδας σῴζομεν, Φίλιππος δ’, ὅτι κωλύομεν αὐτὸν κοινωνεῖν τῆς ἀμφικτυονίας, φοβοῦμαι μὴ πάντες περὶ τῶν ἰδίων ἕκαστος ὀργιζόμενος κοινὸν ἐφ’ ἡμᾶς ἀγάγωσι τὸν πόλεμον, τὰ τῶν Ἀμφικτυόνων δόγματα προστησάμενοι, εἶτ’ ἐπισπασθῶσιν ἕκαστοι πέρα τοῦ συμφέροντος ἑαυτοῖς [ἡμῖν πολεμῆσαι], ὥσπερ καὶ περὶ Φωκέας.", "st": "5.19"}, {"sp": "N", "t": "ἴστε γὰρ δήπου τοῦθ’ ὅτι νῦν Θηβαῖοι καὶ Φίλιππος καὶ Θετταλοί, οὐχὶ ταὔθ’ ἕκαστοι μάλιστ’ ἐσπουδακότες, ταὐτὰ πάντες ἔπραξαν· οἷον Θηβαῖοι τὸν μὲν Φίλιππον παρελθεῖν καὶ λαβεῖν τὰς παρόδους οὐκ ἐδύναντο κωλῦσαι, οὐδέ γε τῶν αὑτοῖς πεπονημένων ὕστατον ἐλθόντα τὴν δόξαν ἔχειν·", "st": "5.20"}, {"sp": "N", "t": "νυνὶ γὰρ Θηβαίοις πρὸς μὲν τὸ τὴν χώραν κεκομίσθαι πέπρακταί τι, πρὸς δὲ τιμὴν καὶ δόξαν αἴσχιστα· εἰ γὰρ μὴ παρῆλθε Φίλιππος, οὐδὲν ἂν αὐτοῖς κέρδος εἶναι. ταῦτα δ’ οὐκ ἐβούλοντο, ἀλλὰ τῷ τὸν Ὀρχομενὸν καὶ τὴν Κορώνειαν λαβεῖν ἐπιθυμεῖν, μὴ δύνασθαι δέ, πάντα ταῦθ’ ὑπέμειναν.", "st": "5.21"}, {"sp": "N", "t": "Φίλιππον τοίνυν τινὲς μὲν δήπου τολμῶσι λέγειν ὡς οὐδ’ ἐβούλετο Θηβαίοις Ὀρχομενὸν καὶ Κορώνειαν παραδοῦναι, ἀλλ’ ἠναγκάσθη· ἐγὼ δὲ τούτοις μὲν ἐρρῶσθαι λέγω, ἐκεῖνο δ’ οἶδ’, ὅτι οὐ μᾶλλόν γε ταῦτ’ ἔμελ’ αὐτῷ ἢ τὰς παρόδους λαβεῖν ἐβούλετο καὶ τὴν δόξαν τοῦ πολέμου τοῦ δοκεῖν δι’ αὑτὸν κρίσιν εἰληφέναι, καὶ τὰ Πύθια θεῖναι δι’ αὑτοῦ, καὶ ταῦτ’ ἦν ὧν μάλιστ’ ἐγλίχετο.", "st": "5.22"}, {"sp": "N", "t": "Θετταλοὶ δέ γ’ οὐδέτερ’ ἐβούλοντο τούτων, οὔτε Θηβαίους οὔτε τὸν Φίλιππον μέγαν γίγνεσθαι (ταῦτα γὰρ πάντ’ ἐφ’ ἑαυτοὺς ἡγοῦντο), τῆς πυλαίας δ’ ἐπεθύμουν καὶ τῶν ἐν Δελφοῖς, πλεονεκτημάτων δυοῖν, κύριοι γενέσθαι· τῷ δὲ τούτων γλίχεσθαι τάδε συγκατέπραξαν. τῶν τοίνυν ἰδίων ἕνεχ’ εὑρήσεθ’ ἕκαστον πολλὰ προηγμένον ὧν οὐδὲν ἐβούλετο πρᾶξαι. τοῦτο μέντοι, τοῦτ’ ἔστιν φυλακτέον ἡμῖν.", "st": "5.23"}, {"sp": "N", "t": "τὰ κελευόμεν’ ἡμᾶς ἄρα δεῖ ποιεῖν ταῦτα φοβουμένους; καὶ σὺ ταῦτα κελεύεις; πολλοῦ γε καὶ δέω. ἀλλ’ ὡς οὔτε πράξομεν οὐδὲν ἀνάξιον ἡμῶν αὐτῶν οὔτ’ ἔσται πόλεμος, νοῦν δὲ δόξομεν πᾶσιν ἔχειν καὶ τὰ δίκαια λέγειν, τοῦτ’ οἶμαι δεῖν ποιεῖν. πρὸς δὲ τοὺς θρασέως ὁτιοῦν οἰομένους ὑπομεῖναι δεῖν καὶ μὴ προορωμένους τὸν πόλεμον, ἐκεῖνα βούλομαι λογίσασθαι. ἡμεῖς Θηβαίους ἐῶμεν ἔχειν Ὠρωπόν· καὶ εἴ τις ἔροιθ’ ἡμᾶς, κελεύσας εἰπεῖν τἀληθῆ, διὰ τί; ἵνα μὴ πολεμῶμεν, φαῖμεν ἄν.", "st": "5.24"}, {"sp": "N", "t": "καὶ Φιλίππῳ νυνὶ κατὰ τὰς συνθήκας Ἀμφιπόλεως παρακεχωρήκαμεν, καὶ Καρδιανοὺς ἐῶμεν ἔξω Χερρονησιτῶν τῶν ἄλλων τετάχθαι, καὶ τὸν Κᾶρα τὰς νήσους καταλαμβάνειν, Χίον καὶ Κῶν καὶ Ῥόδον, καὶ Βυζαντίους κατάγειν τὰ πλοῖα, δῆλον ὅτι τὴν ἀπὸ τῆς εἰρήνης ἡσυχίαν πλειόνων ἀγαθῶν αἰτίαν εἶναι νομίζοντες ἢ τὸ προσκρούειν καὶ φιλονικεῖν περὶ τούτων. οὐκοῦν εὔηθες καὶ κομιδῇ σχέτλιον, πρὸς ἑκάστους καθ’ ἕν’ οὕτω προσενηνεγμένους περὶ τῶν οἰκείων καὶ ἀναγκαιοτάτων, πρὸς πάντας περὶ τῆς ἐν Δελφοῖς σκιᾶς νυνὶ πολεμῆσαι.", "st": "5.25"}, {"sp": "HDR", "t": "Κατὰ Φιλίππου Βʹ", "st": "6"}, {"sp": "N", "t": "ὅταν, ὦ ἄνδρες Ἀθηναῖοι, λόγοι γίγνωνται περὶ ὧν Φίλιππος πράττει καὶ βιάζεται παρὰ τὴν εἰρήνην, ἀεὶ τοὺς ὑπὲρ ἡμῶν λόγους καὶ δικαίους καὶ φιλανθρώπους ὁρῶ φαινομένους, καὶ λέγειν μὲν ἅπαντας ἀεὶ τὰ δέοντα δοκοῦντας τοὺς κατηγοροῦντας Φιλίππου, γιγνόμενον δ’ οὐδὲν ὡς ἔπος εἰπεῖν τῶν δεόντων, οὐδ’ ὧν εἵνεκα ταῦτ’ ἀκούειν ἄξιον·", "st": "6.1"}, {"sp": "N", "t": "ἀλλ’ εἰς τοῦτ’ ἤδη προηγμένα τυγχάνει πάντα τὰ πράγματα τῇ πόλει, ὥσθ’ ὅσῳ τις ἂν μᾶλλον καὶ φανερώτερον ἐξελέγχῃ Φίλιππον καὶ τὴν πρὸς ὑμᾶς εἰρήνην παραβαίνοντα καὶ πᾶσι τοῖς Ἕλλησιν ἐπιβουλεύοντα, τοσούτῳ τὸ τί χρὴ ποιεῖν συμβουλεῦσαι χαλεπώτερον.", "st": "6.2"}, {"sp": "N", "t": "αἴτιον δὲ τούτων, ὅτι πάντες, ὦ ἄνδρες Ἀθηναῖοι, τοὺς πλεονεκτεῖν ζητοῦντας ἔργῳ κωλύειν καὶ πράξεσιν, οὐχὶ λόγοις δέον, πρῶτον μὲν ἡμεῖς οἱ παριόντες τούτων μὲν ἀφέσταμεν καὶ γράφειν καὶ συμβουλεύειν, τὴν πρὸς ὑμᾶς ἀπέχθειαν ὀκνοῦντες, οἷα ποιεῖ δ’, ὡς δεινά, καὶ τοιαῦτα διεξερχόμεθα· ἔπειθ’ ὑμεῖς οἱ καθήμενοι, ὡς μὲν ἂν εἴποιτε δικαίους λόγους καὶ λέγοντος ἄλλου συνείητε, ἄμεινον Φιλίππου παρεσκεύασθε, ὡς δὲ κωλύσαιτ’ ἂν ἐκεῖνον πράττειν ταῦτ’ ἐφ’ ὧν ἐστι νῦν, παντελῶς ἀργῶς ἔχετε.", "st": "6.3"}, {"sp": "N", "t": "συμβαίνει δὴ πρᾶγμ’ ἀναγκαῖον, οἶμαι, καὶ ἴσως εἰκός· ἐν οἷς ἑκάτεροι διατρίβετε καὶ περὶ ἃ σπουδάζετε, ταῦτ’ ἄμεινον ἑκατέροις ἔχει, ἐκείνῳ μὲν αἱ πράξεις, ὑμῖν δ’ οἱ λόγοι. εἰ μὲν οὖν καὶ νῦν λέγειν δικαιότερ’ ὑμῖν ἐξαρκεῖ, ῥᾴδιον, καὶ πόνος οὐδεὶς πρόσεστι τῷ πράγματι·", "st": "6.4"}, {"sp": "N", "t": "εἰ δ’ ὅπως τὰ παρόντ’ ἐπανορθωθήσεται δεῖ σκοπεῖν καὶ μὴ προελθόντ’ ἔτι πορρωτέρω λήσει πάνθ’ ἡμᾶς, μηδ’ ἐπιστήσεται μέγεθος δυνάμεως πρὸς ἣν οὐδ’ ἀντᾶραι δυνησόμεθα, οὐχ ὁ αὐτὸς τρόπος ὅσπερ πρότερον τοῦ βουλεύεσθαι, ἀλλὰ καὶ τοῖς λέγουσιν ἅπασι καὶ τοῖς ἀκούουσιν ὑμῖν τὰ βέλτιστα καὶ τὰ σώσοντα τῶν ῥᾴστων καὶ τῶν ἡδίστων προαιρετέον.", "st": "6.5"}, {"sp": "N", "t": "πρῶτον μέν, εἴ τις, ὦ ἄνδρες Ἀθηναῖοι, θαρρεῖ, ὁρῶν ἡλίκος ἤδη καὶ ὅσων κύριός ἐστι Φίλιππος, καὶ μηδέν’ οἴεται κίνδυνον φέρειν τοῦτο τῇ πόλει μηδ’ ἐφ’ ὑμᾶς πάντα παρασκευάζεσθαι, θαυμάζω, καὶ δεηθῆναι πάντων ὁμοίως ὑμῶν βούλομαι τοὺς λογισμοὺς ἀκοῦσαί μου διὰ βραχέων, δι’ οὓς τἀναντί’ ἐμοὶ παρέστηκε προσδοκᾶν καὶ δι’ ὧν ἐχθρὸν ἡγοῦμαι Φίλιππον· ἵν’, ἐὰν μὲν ἐγὼ δοκῶ βέλτιον προορᾶν, ἐμοὶ πεισθῆτε, ἂν δ’ οἱ θαρροῦντες καὶ πεπιστευκότες αὐτῷ, τούτοις προσθῆσθε.", "st": "6.6"}, {"sp": "N", "t": "ἐγὼ τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, λογίζομαι· τίνων ὁ Φίλιππος κύριος πρῶτον μετὰ τὴν εἰρήνην κατέστη; πυλῶν καὶ τῶν ἐν Φωκεῦσι πραγμάτων. τί οὖν; πῶς τούτοις ἐχρήσατο; ἃ Θηβαίοις συμφέρει καὶ οὐχ ἃ τῇ πόλει, πράττειν προείλετο. τί δήποτε; ὅτι πρὸς πλεονεξίαν, οἶμαι, καὶ τὸ πάνθ’ ὑφ’ αὑτῷ ποιήσασθαι τοὺς λογισμοὺς ἐξετάζων, καὶ οὐχὶ πρὸς εἰρήνην οὐδ’ ἡσυχίαν οὐδὲ δίκαιον οὐδέν,", "st": "6.7"}, {"sp": "N", "t": "εἶδε τοῦτ’ ὀρθῶς, ὅτι τῇ μὲν ἡμετέρᾳ πόλει καὶ τοῖς ἤθεσι τοῖς ἡμετέροις οὐδὲν ἂν ἐνδείξαιτο τοσοῦτον οὐδὲ ποιήσειεν, ὑφ’ οὗ πεισθέντες ὑμεῖς τῆς ἰδίας ἕνεκ’ ὠφελείας τῶν ἄλλων τινὰς Ἑλλήνων ἐκείνῳ προοῖσθε, ἀλλὰ καὶ τοῦ δικαίου λόγον ποιούμενοι, καὶ τὴν προσοῦσαν ἀδοξίαν τῷ πράγματι φεύγοντες, καὶ πάνθ’ ἃ προσήκει προορώμενοι, ὁμοίως ἐναντιώσεσθε, ἄν τι τοιοῦτ’ ἐπιχειρῇ πράττειν, ὥσπερ ἂν εἰ πολεμοῦντες τύχοιτε.", "st": "6.8"}, {"sp": "N", "t": "τοὺς δὲ Θηβαίους ἡγεῖτο, ὅπερ συνέβη, ἀντὶ τῶν ἑαυτοῖς γιγνομένων τὰ λοιπὰ ἐάσειν ὅπως βούλεται πράττειν ἑαυτόν, καὶ οὐχ ὅπως ἀντιπράξειν καὶ διακωλύσειν, ἀλλὰ καὶ συστρατεύσειν, ἂν αὐτοὺς κελεύῃ. καὶ νῦν τοὺς Μεσσηνίους καὶ τοὺς Ἀργείους ταὔθ’ ὑπειληφὼς εὖ ποιεῖ. ὃ καὶ μέγιστόν ἐστι καθ’ ὑμῶν ἐγκώμιον, ὦ ἄνδρες Ἀθηναῖοι·", "st": "6.9"}, {"sp": "N", "t": "κέκρισθε γὰρ ἐκ τούτων τῶν ἔργων μόνοι τῶν πάντων μηδενὸς ἂν κέρδους τὰ κοινὰ δίκαια τῶν Ἑλλήνων προέσθαι, μηδ’ ἀνταλλάξασθαι μηδεμιᾶς χάριτος μηδ’ ὠφελείας τὴν εἰς τοὺς Ἕλληνας εὔνοιαν. καὶ ταῦτ’ εἰκότως καὶ περὶ ὑμῶν οὕτως ὑπείληφε καὶ κατ’ Ἀργείων καὶ Θηβαίων ὡς ἑτέρως, οὐ μόνον εἰς τὰ παρόνθ’ ὁρῶν, ἀλλὰ καὶ τὰ πρὸ τούτων λογιζόμενος.", "st": "6.10"}, {"sp": "N", "t": "εὑρίσκει γάρ, οἶμαι, καὶ ἀκούει τοὺς μὲν ὑμετέρους προγόνους, ἐξὸν αὐτοῖς τῶν λοιπῶν ἄρχειν Ἑλλήνων ὥστ’ αὐτοὺς ὑπακούειν βασιλεῖ, οὐ μόνον οὐκ ἀνασχομένους τὸν λόγον τοῦτον, ἡνίκ’ ἦλθεν Ἀλέξανδρος ὁ τούτων πρόγονος περὶ τούτων κῆρυξ, ἀλλὰ καὶ τὴν χώραν ἐκλιπεῖν προελομένους καὶ παθεῖν ὁτιοῦν ὑπομείναντας, καὶ μετὰ ταῦτα πράξαντας ταῦθ’ ἃ πάντες ἀεὶ γλίχονται λέγειν, ἀξίως δ’ οὐδεὶς εἰπεῖν δεδύνηται, διόπερ κἀγὼ παραλείψω, δικαίως (ἔστι γὰρ μείζω τἀκείνων ἔργα ἢ ὡς τῷ λόγῳ τις ἂν εἴποι), τοὺς δὲ Θηβαίων καὶ Ἀργείων προγόνους τοὺς μὲν συστρατεύσαντας τῷ βαρβάρῳ, τοὺς δ’ οὐκ ἐναντιωθέντας.", "st": "6.11"}, {"sp": "N", "t": "οἶδεν οὖν ἀμφοτέρους ἰδίᾳ τὸ λυσιτελοῦν ἀγαπήσοντας, οὐχ ὅ τι συνοίσει κοινῇ τοῖς Ἕλλησι σκεψομένους. ἡγεῖτ’ οὖν, εἰ μὲν ὑμᾶς ἕλοιτο, φίλους ἐπὶ τοῖς δικαίοις αἱρήσεσθαι, εἰ δ’ ἐκείνοις προσθεῖτο, συνεργοὺς ἕξειν τῆς αὑτοῦ πλεονεξίας. διὰ ταῦτ’ ἐκείνους ἀνθ’ ὑμῶν καὶ τότε καὶ νῦν αἱρεῖται. οὐ γὰρ δὴ τριήρεις γ’ ὁρᾷ πλείους αὐτοῖς ἢ ὑμῖν οὔσας· οὐδ’ ἐν τῇ μεσογείᾳ τιν’ ἀρχὴν εὕρηκε, τῆς δ’ ἐπὶ τῇ θαλάττῃ καὶ τῶν ἐμπορίων ἀφέστηκεν· οὐδ’ ἀμνημονεῖ τοὺς λόγους οὐδὲ τὰς ὑποσχέσεις, ἐφ’ αἷς τῆς εἰρήνης ἔτυχεν.", "st": "6.12"}, {"sp": "N", "t": "ἀλλὰ νὴ Δί’, εἴποι τις ἂν ὡς πάντα ταῦτ’ εἰδώς, οὐ πλεονεξίας ἕνεκ’ οὐδ’ ὧν ἐγὼ κατηγορῶ τότε ταῦτ’ ἔπραξεν, ἀλλὰ τῷ δικαιότερα τοὺς Θηβαίους ἢ ὑμᾶς ἀξιοῦν. ἀλλὰ τοῦτον καὶ μόνον πάντων τῶν λόγων οὐκ ἔνεστιν αὐτῷ νῦν εἰπεῖν· ὁ γὰρ Μεσσήνην Λακεδαιμονίους ἀφιέναι κελεύων, πῶς ἂν Ὀρχομενὸν καὶ Κορώνειαν τότε Θηβαίοις παραδοὺς τῷ δίκαια νομίζειν ταῦτ’ εἶναι πεποιηκέναι σκήψαιτο;", "st": "6.13"}, {"sp": "N", "t": "ἀλλ’ ἐβιάσθη νὴ Δία (ταῦτα γάρ ἐσθ’ ὑπόλοιπον) καὶ παρὰ γνώμην, τῶν Θετταλῶν ἱππέων καὶ τῶν Θηβαίων ὁπλιτῶν ἐν μέσῳ ληφθείς, συνεχώρησε ταῦτα. καλῶς. οὐκοῦν φασὶ μὲν μέλλειν πρὸς τοὺς Θηβαίους αὐτὸν ὑπόπτως ἔχειν, καὶ λογοποιοῦσιν περιιόντες τινὲς ὡς Ἐλάτειαν τειχιεῖ.", "st": "6.14"}, {"sp": "N", "t": "ὁ δὲ ταῦτα μὲν μέλλει καὶ μελλήσει γ’, ὡς ἐγὼ κρίνω, τοῖς Μεσσηνίοις δὲ καὶ τοῖς Ἀργείοις ἐπὶ τοὺς Λακεδαιμονίους συλλαμβάνειν οὐ μέλλει, ἀλλὰ καὶ ξένους εἰσπέμπει καὶ χρήματ’ ἀποστέλλει καὶ δύναμιν μεγάλην ἔχων αὐτός ἐστι προσδόκιμος. τοὺς μὲν ὄντας ἐχθροὺς Θηβαίων Λακεδαιμονίους ἀναιρεῖ, οὓς δ’ ἀπώλεσεν αὐτὸς πρότερον Φωκέας νῦν σῴζει; καὶ τίς ἂν ταῦτα πιστεύσειεν;", "st": "6.15"}, {"sp": "N", "t": "ἐγὼ μὲν γὰρ οὐκ ἂν ἡγοῦμαι Φίλιππον, οὔτ’ εἰ τὰ πρῶτα βιασθεὶς ἄκων ἔπραξεν, οὔτ’ ἂν εἰ νῦν ἀπεγίγνωσκε Θηβαίους, τοῖς ἐκείνων ἐχθροῖς συνεχῶς ἐναντιοῦσθαι, ἀλλ’ ἀφ’ ὧν νῦν ποιεῖ, κἀκεῖν’ ἐκ προαιρέσεως δῆλός ἐστι ποιήσας, ἐκ πάντων δ’, ἄν τις ὀρθῶς θεωρῇ, πάνθ’ ἃ πραγματεύεται κατὰ τῆς πόλεως συντάττων.", "st": "6.16"}, {"sp": "N", "t": "καὶ τοῦτ’ ἐξ ἀνάγκης τρόπον τιν’ αὐτῷ νῦν γε δὴ συμβαίνει. λογίζεσθε γάρ. ἄρχειν βούλεται, τούτου δ’ ἀνταγωνιστὰς μόνους ὑπείληφεν ὑμᾶς. ἀδικεῖ πολὺν ἤδη χρόνον, καὶ τοῦτ’ αὐτὸς ἄριστα σύνοιδεν αὑτῷ· οἷς γὰρ οὖσιν ὑμετέροις ἔχει, τούτοις πάντα τἄλλ’ ἀσφαλῶς κέκτηται· εἰ γὰρ Ἀμφίπολιν καὶ Ποτείδαιαν προεῖτο, οὐδ’ ἂν οἴκοι μένειν βεβαίως ἡγεῖται.", "st": "6.17"}, {"sp": "N", "t": "ἀμφότερ’ οὖν οἶδε, καὶ αὑτὸν ὑμῖν ἐπιβουλεύοντα καὶ ὑμᾶς αἰσθανομένους· εὖ φρονεῖν δ’ ὑμᾶς ὑπολαμβάνων, δικαίως αὑτὸν μισεῖν νομίζει, καὶ παρώξυνται, πείσεσθαί τι προσδοκῶν, ἂν καιρὸν λάβητε, ἂν μὴ φθάσῃ ποιήσας πρότερος.", "st": "6.18"}, {"sp": "N", "t": "διὰ ταῦτ’ ἐγρήγορεν, ἐφέστηκεν, ἐπὶ τῇ πόλει θεραπεύει τινάς, Θηβαίους καὶ Πελοποννησίων τοὺς ταὐτὰ βουλομένους τούτοις, οὓς διὰ μὲν πλεονεξίαν τὰ παρόντ’ ἀγαπήσειν οἴεται, διὰ δὲ σκαιότητα τρόπων τῶν μετὰ ταῦτ’ οὐδὲν προόψεσθαι. καίτοι σωφρονοῦσί γε καὶ μετρίως ἐναργῆ παραδείγματ’ ἔστιν ἰδεῖν, ἃ καὶ πρὸς Μεσσηνίους καὶ πρὸς Ἀργείους ἔμοιγ’ εἰπεῖν συνέβη, βέλτιον δ’ ἴσως καὶ πρὸς ὑμᾶς ἐστιν εἰρῆσθαι.", "st": "6.19"}, {"sp": "N", "t": "“πῶς γὰρ οἴεσθ’,” ἔφην, “ὦ ἄνδρες Μεσσήνιοι, δυσχερῶς ἀκούειν Ὀλυνθίους, εἴ τίς τι λέγοι κατὰ Φιλίππου κατ’ ἐκείνους τοὺς χρόνους, ὅτ’ Ἀνθεμοῦντα μὲν αὐτοῖς ἀφίει, ἧς πάντες οἱ πρότερον Μακεδονίας βασιλεῖς ἀντεποιοῦντο, Ποτείδαιαν δ’ ἐδίδου τοὺς Ἀθηναίων ἀποίκους ἐκβάλλων, καὶ τὴν μὲν ἔχθραν τὴν πρὸς ἡμᾶς αὐτὸς ἀνῄρητο, τὴν χώραν δ’ ἐκείνοις ἐδεδώκει καρποῦσθαι; ἆρα προσδοκᾶν αὐτοὺς τοιαῦτα πείσεσθαι, ἢ λέγοντος ἄν τινος πιστεῦσαι οἴεσθε;”", "st": "6.20"}, {"sp": "N", "t": "“ἀλλ’ ὅμως,” ἔφην ἐγώ, “μικρὸν χρόνον τὴν ἀλλοτρίαν καρπωσάμενοι πολὺν τῆς αὑτῶν ὑπ’ ἐκείνου στέρονται, αἰσχρῶς ἐκπεσόντες, οὐ κρατηθέντες μόνον, ἀλλὰ καὶ προδοθέντες ὑπ’ ἀλλήλων καὶ πραθέντες· οὐ γὰρ ἀσφαλεῖς ταῖς πολιτείαις αἱ πρὸς τοὺς τυράννους αὗται λίαν ὁμιλίαι.”", "st": "6.21"}, {"sp": "N", "t": "“τί δ’ οἱ Θετταλοί; ἆρ’ οἴεσθ’,” ἔφην, “ὅτ’ αὐτοῖς τοὺς τυράννους ἐξέβαλλε καὶ πάλιν Νίκαιαν καὶ Μαγνησίαν ἐδίδου, προσδοκᾶν τὴν καθεστῶσαν νῦν δεκαδαρχίαν ἔσεσθαι παρ’ αὐτοῖς; ἢ τὸν τὴν πυλαίαν ἀποδόντα, τοῦτον τὰς ἰδίας αὐτῶν προσόδους παραιρήσεσθαι; οὐκ ἔστι ταῦτα. ἀλλὰ μὴν γέγονεν ταῦτα καὶ πᾶσιν ἔστιν εἰδέναι·”", "st": "6.22"}, {"sp": "N", "t": "“ὑμεῖς δ’,” ἔφην ἐγώ, “διδόντα μὲν καὶ ὑπισχνούμενον θεωρεῖτε Φίλιππον, ἐξηπατηκότα δ’ ἤδη καὶ παρακεκρουμένον ἀπεύχεσθε, εἰ σωφρονεῖτε δή, ἰδεῖν. ἔστι τοίνυν νὴ Δί’,” ἔφην ἐγώ, “παντοδαπὰ εὑρημένα ταῖς πόλεσιν πρὸς φυλακὴν καὶ σωτηρίαν, οἷον χαρακώματα καὶ τείχη καὶ τάφροι καὶ τἄλλ’ ὅσα τοιαῦτα.”", "st": "6.23"}, {"sp": "N", "t": "“καὶ ταῦτα μέν ἐστιν ἅπαντα χειροποίητα καὶ δαπάνης προσδεῖται· ἓν δέ τι κοινὸν ἡ φύσις τῶν εὖ φρονούντων ἐν αὑτῇ κέκτηται φυλακτήριον, ὃ πᾶσι μέν ἐστ’ ἀγαθὸν καὶ σωτήριον, μάλιστα δὲ τοῖς πλήθεσι πρὸς τοὺς τυράννους. τί οὖν ἐστι τοῦτο; ἀπιστία. ταύτην φυλάττετε, ταύτης ἀντέχεσθε· ἂν ταύτην σῴζητε, οὐδὲν μὴ δεινὸν πάθητε. τί ζητεῖτ’;” ἔφην.", "st": "6.24"}, {"sp": "N", "t": "“ἐλευθερίαν; εἶτ’ οὐχ ὁρᾶτε Φίλιππον ἀλλοτριωτάτας ταύτῃ καὶ τὰς προσηγορίας ἔχοντα; βασιλεὺς γὰρ καὶ τύραννος ἅπας ἐχθρὸς ἐλευθερίᾳ καὶ νόμοις ἐναντίος. οὐ φυλάξεσθ’ ὅπως,” ἔφην, “μὴ πολέμου ζητοῦντες ἀπαλλαγῆναι δεσπότην εὕρητε;”", "st": "6.25"}, {"sp": "N", "t": "ταῦτ’ ἀκούσαντες ἐκεῖνοι, καὶ θορυβοῦντες ὡς ὀρθῶς λέγεται, καὶ πολλοὺς ἑτέρους λόγους παρὰ τῶν πρέσβεων καὶ παρόντος ἐμοῦ καὶ πάλιν ὕστερον, ὡς ἔοικεν, οὐδὲν μᾶλλον ἀποσχήσονται τῆς Φιλίππου φιλίας οὐδ’ ὧν ἐπαγγέλλεται.", "st": "6.26"}, {"sp": "N", "t": "καὶ οὐ τοῦτ’ ἔστ’ ἄτοπον, εἰ Μεσσήνιοι καὶ Πελοποννησίων τινὲς παρ’ ἃ τῷ λογισμῷ βέλτισθ’ ὁρῶσί τι πράξουσιν, ἀλλ’ ὑμεῖς οἱ καὶ συνιέντες αὐτοὶ καὶ τῶν λεγόντων ἀκούοντες ἡμῶν, ὡς ἐπιβουλεύεσθε, ὡς περιστοιχίζεσθε, ἐκ τοῦ μηδὲν ἤδη ποιῆσαι λήσεθ’, ὡς ἐμοὶ δοκεῖ, πάνθ’ ὑπομείναντες· οὕτως ἡ παραυτίχ’ ἡδονὴ καὶ ῥᾳστώνη μεῖζον ἰσχύει τοῦ ποθ’ ὕστερον συνοίσειν μέλλοντος.", "st": "6.27"}, {"sp": "N", "t": "περὶ μὲν δὴ τῶν ἡμῖν πρακτέων καθ’ ὑμᾶς αὐτοὺς ὕστερον βουλεύσεσθε, ἂν σωφρονῆτε· ἃ δὲ νῦν ἀποκρινάμενοι τὰ δέοντ’ ἂν εἴητ’ ἐψηφισμένοι, ταῦτ’ ἤδη λέξω.", "st": "6.28"}, {"sp": "N", "t": "⟨ΑΠΟΚΡΙΣΙΣ.⟩", "st": "6.28"}, {"sp": "N", "t": "ἦν μὲν οὖν δίκαιον, ὦ ἄνδρες Ἀθηναῖοι, τοὺς ἐνεγκόντας τὰς ὑποσχέσεις, ἐφ’ αἷς ἐπείσθητε ποιήσασθαι τὴν εἰρήνην, καλεῖν·", "st": "6.28"}, {"sp": "N", "t": "οὔτε γὰρ αὐτὸς ἄν ποθ’ ὑπέμεινα πρεσβεύειν, οὔτ’ ἂν ὑμεῖς οἶδ’ ὅτι ἐπαύσασθε πολεμοῦντες, εἰ τοιαῦτα πράξειν τυχόντ’ εἰρήνης Φίλιππον ᾤεσθε· ἀλλ’ ἦν πολὺ τούτων ἀφεστηκότα τὰ τότε λεγόμενα. καὶ πάλιν γ’ ἑτέρους καλεῖν. τίνας; τοὺς ὅτ’ ἐγὼ γεγονυίας ἤδη τῆς εἰρήνης ἀπὸ τῆς ὑστέρας ἥκων πρεσβείας τῆς ἐπὶ τοὺς ὅρκους, αἰσθόμενος φενακιζομένην τὴν πόλιν, προὔλεγον καὶ διεμαρτυρόμην καὶ οὐκ εἴων προέσθαι Πύλας οὐδὲ Φωκέας,", "st": "6.29"}, {"sp": "N", "t": "λέγοντας ὡς ἐγὼ μὲν ὕδωρ πίνων εἰκότως δύστροπος καὶ δύσκολός εἰμί τις ἄνθρωπος, Φίλιππος δ’, ἅπερ εὔξαισθ’ ἂν ὑμεῖς, ἂν παρέλθῃ, πράξει, καὶ Θεσπιὰς μὲν καὶ Πλαταιὰς τειχιεῖ, Θηβαίους δὲ παύσει τῆς ὕβρεως, Χερρόνησον δὲ τοῖς αὑτοῦ τέλεσιν διορύξει, Εὔβοιαν δὲ καὶ τὸν Ὠρωπὸν ἀντ’ Ἀμφιπόλεως ὑμῖν ἀποδώσει· ταῦτα γὰρ ἅπαντ’ ἐπὶ τοῦ βήματος ἐνταῦθα μνημονεύετ’ οἶδ’ ὅτι ῥηθέντα, καίπερ ὄντες οὐ δεινοὶ τοὺς ἀδικοῦντας μεμνῆσθαι.", "st": "6.30"}, {"sp": "N", "t": "καὶ τὸ πάντων αἴσχιστον, καὶ τοῖς ἐκγόνοις πρὸς τὰς ἐλπίδας τὴν αὐτὴν εἰρήνην εἶναι ταύτην ἐψηφίσασθε· οὕτω τελέως ὑπήχθητε. τί δὴ ταῦτα νῦν λέγω καὶ καλεῖν φημὶ δεῖν τούτους; ἐγὼ νὴ τοὺς θεοὺς τἀληθῆ μετὰ παρρησίας ἐρῶ πρὸς ὑμᾶς καὶ οὐκ ἀποκρύψομαι·", "st": "6.31"}, {"sp": "N", "t": "οὐχ ἵν’ εἰς λοιδορίαν ἐμπεσὼν ἐμαυτῷ μὲν ἐξ ἴσου λόγον παρ’ ὑμῖν ποιήσω, τοῖς δ’ ἐμοὶ προσκρούσασιν ἐξ ἀρχῆς καὶ νῦν παράσχω πρόφασιν τοῦ πάλιν τι λαβεῖν παρὰ Φιλίππου, οὐδ’ ἵν’ ὡς ἄλλως ἀδολεσχῶ· ἀλλ’ οἴομαί ποθ’ ὑμᾶς λυπήσειν ἃ Φίλιππος πράττει μᾶλλον ἢ τὰ νυνί·", "st": "6.32"}, {"sp": "N", "t": "τὸ γὰρ πρᾶγμ’ ὁρῶ προβαῖνον, καὶ οὐχὶ βουλοίμην ἂν εἰκάζειν ὀρθῶς, φοβοῦμαι δὲ μὴ λίαν ἐγγὺς ᾖ τοῦτ’ ἤδη. ὅταν οὖν μηκέθ’ ὑμῖν ἀμελεῖν ἐξουσία γίγνηται τῶν συμβαινόντων, μηδ’ ἀκούηθ’ ὅτι ταῦτ’ ἐφ’ ὑμᾶς ἐστιν ἐμοῦ μηδὲ τοῦ δεῖνος, ἀλλ’ αὐτοὶ πάντες ὁρᾶτε καὶ εὖ εἰδῆτε, ὀργίλους καὶ τραχεῖς ὑμᾶς ἔσεσθαι νομίζω.", "st": "6.33"}, {"sp": "N", "t": "φοβοῦμαι δὴ μή, τῶν πρέσβεων σεσιωπηκότων ἐφ’ οἷς αὑτοῖς συνίσασι δεδωροδοκηκότες, τοῖς ἐπανορθοῦν τι πειρωμένοις τῶν διὰ τούτους ἀπολωλότων τῇ παρ’ ὑμῶν ὀργῇ περιπεσεῖν συμβῇ· ὁρῶ γὰρ ὡς τὰ πόλλ’ ἐνίους οὐκ εἰς τοὺς αἰτίους, ἀλλ’ εἰς τοὺς ὑπὸ χεῖρα μάλιστα τὴν ὀργὴν ἀφιέντας.", "st": "6.34"}, {"sp": "N", "t": "ἕως οὖν ἔτι μέλλει καὶ συνίσταται τὰ πράγματα καὶ κατακούομεν ἀλλήλων, ἕκαστον ὑμῶν καίπερ ἀκριβῶς εἰδόθ’ ὅμως ἐπαναμνῆσαι βούλομαι, τίς ὁ Φωκέας πείσας καὶ Πύλας προέσθαι, ὧν καταστὰς ἐκεῖνος κύριος τῆς ἐπὶ τὴν Ἀττικὴν ὁδοῦ καὶ τῆς εἰς Πελοπόννησον κύριος γέγονεν, καὶ πεποίηχ’ ὑμῖν μὴ περὶ τῶν δικαίων μηδ’ ὑπὲρ τῶν ἔξω πραγμάτων εἶναι τὴν βουλήν, ἀλλ’ ὑπὲρ τῶν ἐν τῇ χώρᾳ καὶ τοῦ πρὸς τὴν Ἀττικὴν πολέμου, ὃς λυπήσει μὲν ἕκαστον, ἐπειδὰν παρῇ, γέγονεν δ’ ἐν ἐκείνῃ τῇ ἡμέρᾳ.", "st": "6.35"}, {"sp": "N", "t": "εἰ γὰρ μὴ παρεκρούσθητε τόθ’ ὑμεῖς, οὐδὲν ἂν ἦν τῇ πόλει πρᾶγμα· οὔτε γὰρ ναυσὶ δήπου κρατήσας εἰς τὴν Ἀττικὴν ἦλθεν ἄν ποτε στόλῳ Φίλιππος, οὔτε πεζῇ βαδίζων ὑπὲρ τὰς Πύλας καὶ Φωκέας, ἀλλ’ ἢ τὰ δίκαι’ ἂν ἐποίει καὶ τὴν εἰρήνην ἄγων ἡσυχίαν εἶχεν, ἢ παραχρῆμ’ ἂν ἦν ἐν ὁμοίῳ πολέμῳ δι’ ὃν τότε τῆς εἰρήνης ἐπεθύμησεν.", "st": "6.36"}, {"sp": "N", "t": "ταῦτ’ οὖν, ὡς μὲν ὑπομνῆσαι, νῦν ἱκανῶς εἴρηται, ὡς δ’ ἂν ἐξετασθείη μάλιστ’ ἀκριβῶς, μὴ γένοιτ’, ὦ πάντες θεοί· οὐδένα γὰρ βουλοίμην ἔγωγ’ ἄν, οὐδ’ εἰ δίκαιός ἐστ’ ἀπολωλέναι, μετὰ τοῦ πάντων κινδύνου καὶ τῆς ζημίας δίκην ὑποσχεῖν.", "st": "6.37"}, {"sp": "HDR", "t": "Περὶ Ἀλοννήσου", "st": "7"}, {"sp": "N", "t": "ὦ ἄνδρες Ἀθηναῖοι, οὐκ ἔστιν ὅπως αἱ αἰτίαι, ἃς Φίλιππος αἰτιᾶται τοὺς ὑπὲρ τῶν δικαίων πρὸς ὑμᾶς λέγοντας, κωλύσουσι συμβούλους ἡμᾶς γίγνεσθαι ὑπὲρ τῶν ὑμῖν συμφερόντων· δεινὸν γὰρ ἂν εἴη, εἰ τὴν ἐπὶ τοῦ βήματος παρρησίαν αἱ παρ’ ἐκείνου πεμπόμεναι ἐπιστολαὶ ἀνέλοιεν. ἐγὼ δ’ ὑμῖν, ὦ ἄνδρες Ἀθηναῖοι, βούλομαι πρῶτον μὲν περὶ ὧν Φίλιππος ἐπέσταλκε, περὶ τούτων διεξελθεῖν· ὕστερον δέ, περὶ ὧν οἱ πρέσβεις λέγουσι, καὶ ἡμεῖς λέξομεν.", "st": "7.1"}, {"sp": "N", "t": "Φίλιππος γὰρ ἄρχεται μὲν περὶ Ἁλοννήσου λέγων ὡς ὑμῖν δίδωσιν ἑαυτοῦ οὖσαν, ὑμᾶς δὲ οὔ φησι δικαίως αὐτὸν ἀπαιτεῖν· οὐ γὰρ ὑμετέραν οὖσαν οὔτε λαβεῖν οὔτε νῦν ἔχειν. ἔλεγε δὲ καὶ πρὸς ἡμᾶς τοιούτους λόγους, ὅτε πρὸς αὐτὸν ἐπρεσβεύσαμεν, ὡς λῃστὰς ἀφελόμενος ταύτην τὴν νῆσον κτήσαιτο, καὶ προσήκειν αὐτὴν ἑαυτοῦ εἶναι.", "st": "7.2"}, {"sp": "N", "t": "τοῦτον δὲ τὸν λόγον, ὡς οὐκ ἔστι δίκαιος, οὐ χαλεπόν ἐστιν αὐτοῦ ἀφελέσθαι. ἅπαντες γὰρ οἱ λῃσταὶ τοὺς ἀλλοτρίους τόπους καταλαμβάνοντες καὶ τούτους ἐχυροὺς ποιούμενοι, ἐντεῦθεν τοὺς ἄλλους κακῶς ποιοῦσιν. ὁ δὴ τοὺς λῃστὰς τιμωρησάμενος καὶ κρατήσας οὐκ ἂν δήπου εἰκότα λέγοι, εἰ φαίη, ἃ ἐκεῖνοι ἀδίκως καὶ ἀλλότρια εἶχον, ταῦθ’ ἑαυτοῦ γίγνεσθαι.", "st": "7.3"}, {"sp": "N", "t": "εἰ γὰρ ταῦτα συγχωρήσετε, τί κωλύει, καὶ εἴ τινα τῆς Ἀττικῆς λῃσταὶ τόπον καταλάβοιεν ἢ Λήμνου ἢ Ἴμβρου ἢ Σκύρου, καί τινες τούτους τοὺς λῃστὰς ἐκκόψαιεν, εὐθὺς καὶ τὸν τόπον τοῦτον, οὗ ἦσαν οἱ λῃσταί, τὸν ὄντα ἡμέτερον, τῶν τιμωρησαμένων τοὺς λῃστὰς γίγνεσθαι;", "st": "7.4"}, {"sp": "N", "t": "Φίλιππος δ’ οὐκ ἀγνοεῖ ταῦτ’ οὐ δίκαια λέγων, ἀλλ’ εἰ καί τις ἄλλος ἐπιστάμενος παρακρουσθῆναι ἂν ὑμᾶς οἴεται ὑπὸ τῶν τἀνταῦθα διοικήσειν, ὡς ἂν αὐτὸς ἐκεῖνος βούληται, καὶ πρὶν ὑπεσχημένων, καὶ νῦν δὲ πραττόντων. ἀλλὰ μὴν οὐδ’ ἐκεῖνό γε λανθάνει αὐτόν, ὅτι δι’ ἀμφοτέρων τῶν ὀνομάτων, ὁποτέρῳ ἂν χρῆσθε, ὑμεῖς ἕξετε τὴν νῆσον, ἄν τε λάβητε ἄν τ’ ἀπολάβητε.", "st": "7.5"}, {"sp": "N", "t": "τί οὖν αὐτῷ διαφέρει, μὴ τῷ δικαίῳ ὀνόματι χρησάμενον ἀποδοῦναι ὑμῖν, ἀλλὰ δωρεὰν δεδωκέναι, τῷ ἀδίκῳ; οὐχ ἵν’ εὐεργέτημά τι καταλογίσηται πρὸς ὑμᾶς (γελοῖον γὰρ ἂν εἴη τοῦτο τὸ εὐεργέτημα), ἀλλ’ ἵν’ ἐνδείξηται ἅπασι τοῖς Ἕλλησιν ὅτι Ἀθηναῖοι τὰ ἐν τῇ θαλάττῃ χωρία ἀγαπῶσι παρὰ τοῦ Μακεδόνος λαμβάνοντες. τοῦτο δ’ ὑμῖν οὐ ποιητέον ἐστίν, ὦ ἄνδρες Ἀθηναῖοι.", "st": "7.6"}, {"sp": "N", "t": "ὅταν δὲ λέγῃ περὶ τούτων ὡς ἐθέλει διαδικάσασθαι, οὐδὲν ἀλλ’ ἢ χλευάζει ὑμᾶς, πρῶτον μὲν ἀξιῶν Ἀθηναίους ὄντας πρὸς τὸν ἐκ Πέλλης ὁρμώμενον περὶ τῶν νήσων διαδικάζεσθαι, πότερ’ ὑμέτεραι ἢ ἐκείνου εἰσίν. ὁπότε γὰρ ἡ μὲν δύναμις ἡ ὑμετέρα, ἡ ἐλευθερώσασα τοὺς Ἕλληνας, μὴ δύναται ὑμῖν τὰ ἐν τῇ θαλάττῃ χωρία σῴζειν, οἱ δὲ δικασταί, οἷς ἂν ἐπιτρέψητε, οἱ κύριοι τῆς ψήφου, οὗτοι ὑμῖν σώσουσιν, ἐὰν μὴ Φίλιππος αὐτοὺς πρίηται,", "st": "7.7"}, {"sp": "N", "t": "πῶς ὑμεῖς οὐχ ὁμολογουμένως, ὅταν ταῦτα διαπράττησθε, τῶν ἐν τῇ ἠπείρῳ ἁπάντων ἀφεστήκατε, καὶ ἐπιδείκνυτε ἅπασιν ἀνθρώποις ὅτι οὐδὲ περὶ ἑνὸς αὐτῷ διαγωνιεῖσθε, εἴγε περὶ τῶν ἐν τῇ θαλάττῃ, οὗ φατὲ ἰσχύειν, μὴ διαγωνιεῖσθε, ἀλλὰ δικάσεσθε;", "st": "7.8"}, {"sp": "N", "t": "ἔτι περὶ συμβόλων φησὶ πεπομφέναι πρὸς ὑμᾶς τοὺς ποιησομένους, ταῦτα δὲ κύρια ἔσεσθαι, οὐκ ἐπειδὰν ἐν τῷ δικαστηρίῳ τῷ παρ’ ὑμῖν κυρωθῇ, ὥσπερ ὁ νόμος κελεύει, ἀλλ’ ἐπειδὰν ὡς ἑαυτὸν ἐπανενεχθῇ, ἐφέσιμον τὴν παρ’ ὑμῶν γενομένην γνῶσιν ὡς ἑαυτὸν ποιούμενος. βούλεται γὰρ ὑμῶν τοῦτο προλαβεῖν καὶ ὁμολογούμενον ἐν τοῖς συμβόλοις καταστῆσαι, ὅτι τῶν περὶ Ποτείδαιαν γεγενημένων ἀδικημάτων οὐδὲν ἐγκαλεῖτε αὐτῷ ὡς ἀδικούμενοι, ἀλλὰ βεβαιοῦτε δικαίως αὐτὴν ἐκεῖνον καὶ λαβεῖν καὶ κεκτῆσθαι.", "st": "7.9"}, {"sp": "N", "t": "καίτοι Ἀθηναίων οἱ ἐν Ποτειδαίᾳ κατοικοῦντες, οὐκ ὄντος αὐτοῖς πολέμου πρὸς Φίλιππον, ἀλλὰ συμμαχίας, καὶ ὅρκων ὀμωμοσμένων, οὓς Φίλιππος τοῖς οἰκοῦσιν ἐν Ποτειδαίᾳ ὤμοσεν, ἀφῃρέθησαν ὑπ’ αὐτοῦ τὰ κτήματα. ταῦτα δὴ βούλεται τἀδικήματα πανταχῶς παρ’ ὑμῖν βεβαιώσασθαι, ὅτι οὔτ’ ἐγκαλεῖτε οὔθ’ ἡγεῖσθε ἀδικεῖσθαι·", "st": "7.10"}, {"sp": "N", "t": "ἐπεὶ ὅτι γε συμβόλων οὐδὲν δέονται Μακεδόνες πρὸς Ἀθηναίους, ὁ παρεληλυθὼς ὑμῖν χρόνος τεκμήριον γενέσθω· οὔτε γὰρ Ἀμύντας ὁ πατὴρ ὁ Φιλίππου οὔθ’ οἱ ἄλλοι βασιλεῖς οὐδεπώποτε σύμβολα ἐποιήσαντο πρὸς τὴν πόλιν τὴν ἡμετέραν.", "st": "7.11"}, {"sp": "N", "t": "καίτοι πλείους γε ἦσαν αἱ ἐπιμειξίαι τότε πρὸς ἀλλήλους ἢ νῦν εἰσίν· ὑφ’ ἡμῖν γὰρ ἦν ἡ Μακεδονία καὶ φόρους ἡμῖν ἔφερον, καὶ τοῖς ἐμπορίοις τότε μᾶλλον ἢ νῦν ἡμεῖς τε τοῖς ἐκεῖ κἀκεῖνοι τοῖς παρ’ ἡμῖν ἐχρῶντο, καὶ ἐμπορικαὶ δίκαι οὐκ ἦσαν, ὥσπερ νῦν, ἀκριβεῖς, αἱ κατὰ μῆνα, ποιοῦσαι μηδὲν δεῖσθαι συμβόλων τοὺς τοσοῦτον ἀλλήλων ἀπέχοντας.", "st": "7.12"}, {"sp": "N", "t": "ἀλλ’ ὅμως οὐδενὸς τοιούτου ὄντος τότε, οὐκ ἐλυσιτέλει σύμβολα ποιησαμένους οὔτ’ ἐκ Μακεδονίας πλεῖν Ἀθήναζε δίκας ληψομένους, οὔθ’ ἡμῖν εἰς Μακεδονίαν, ἀλλ’ ἡμεῖς τε τοῖς ἐκεῖ νομίμοις ἐκεῖνοί τε τοῖς παρ’ ἡμῖν τὰς δίκας ἐλάμβανον. μὴ οὖν ἀγνοεῖτε ὅτι τὰ σύμβολα ταῦτα γίγνεται εἰς ὑποδοχὴν τοῦ μηδ’ ἀμφισβητῆσαι εὐλόγως ὑμᾶς ἔτι Ποτειδαίας.", "st": "7.13"}, {"sp": "N", "t": "περὶ δὲ τῶν λῃστῶν δίκαιόν φησιν εἶναι κοινῇ φυλάττειν τοὺς ἐν τῇ θαλάττῃ κακουργοῦντας ὑμᾶς τε καὶ αὑτόν, οὐδὲν ἀλλ’ ἢ τοῦτ’ ἀξιῶν, ὑφ’ ὑμῶν εἰς τὴν θάλατταν κατασταθῆναι, καὶ ὁμολογῆσαι ὑμᾶς ὡς ἄνευ Φιλίππου οὐδὲ τὴν ἐν τῇ θαλάττῃ φυλακὴν δυνατοί ἐστε φυλάττειν,", "st": "7.14"}, {"sp": "N", "t": "ἔτι δὲ καὶ δοθῆναι αὐτῷ ταύτην τὴν ἄδειαν, περιπλέοντι καὶ ὁρμιζομένῳ εἰς τὰς νήσους ἐπὶ προφάσει τῇ τῶν λῃστῶν φυλακῇ διαφθείρειν τοὺς νησιώτας καὶ ἀφιστάναι ὑμῶν, καὶ μὴ μόνον τοὺς φυγάδας τοὺς παρ’ ἑαυτοῦ εἰς Θάσον κεκομικέναι διὰ τῶν ὑμετέρων στρατηγῶν, ἀλλὰ καὶ τὰς ἄλλας νήσους οἰκειώσασθαι, συμπέμπων τοὺς συμπλευσομένους μετὰ τῶν στρατηγῶν τῶν ὑμετέρων ὡς κοινωνήσοντας τῆς κατὰ θάλατταν φυλακῆς.", "st": "7.15"}, {"sp": "N", "t": "καίτοι οὔ φασί τινες αὐτὸν προσδεῖσθαι τῆς θαλάττης. ὁ δ’ οὐδὲν δεόμενος τριήρεις κατασκευάζεται, καὶ νεωσοίκους οἰκοδομεῖται, καὶ ἀποστόλους ἀποστέλλειν βούλεται, καὶ δαπάνας οὐ μικρὰς δαπανᾶν εἰς τοὺς κατὰ θάλατταν κινδύνους, ὧν οὐδὲν προτιμᾷ.", "st": "7.16"}, {"sp": "N", "t": "ταῦτ’ οἴεσθ’ ἄν, ὦ ἄνδρες Ἀθηναῖοι, Φίλιππον ἀξιῶσαι ὑμᾶς συγχωρῆσαι αὐτῷ, εἰ μὴ ὑμῶν μὲν κατεφρόνει, οὓς δ’ ἐνθάδε προῄρηται φίλους κεκτῆσθαι, τούτοις διεπίστευεν; οἳ οὐκ αἰσχύνονται Φιλίππῳ ζῶντες καὶ οὐ τῇ αὑτῶν πατρίδι, καὶ τὰς παρ’ ἐκείνου δωρειὰς λαμβάνοντες οἴονται οἴκαδε λαμβάνειν, τὰ οἴκοι πωλοῦντες.", "st": "7.17"}, {"sp": "N", "t": "περὶ δὲ τῆς ἐπανορθώσεως τῆς εἰρήνης, ἣν ἔδοσαν ἡμῖν οἱ πρέσβεις οἱ παρ’ ἐκείνου πεμφθέντες ἐπανορθώσασθαι, ὅτι ἐπηνωρθωσάμεθα, ὃ παρὰ πᾶσιν ἀνθρώποις ὁμολογεῖται δίκαιον εἶναι, ἑκατέρους ἔχειν τὰ ἑαυτῶν, ἀμφισβητεῖ μὴ δεδωκέναι μηδὲ τοὺς πρέσβεις ταῦτ’ εἰρηκέναι πρὸς ὑμᾶς, οὐδὲν ἀλλ’ ἢ πεπεισμένος ὑπὸ τούτων, οἷς χρῆται φίλοις, ὡς ὑμεῖς οὐ μνημονεύετε τὰ ἐν τῷ δήμῳ εἰρημένα.", "st": "7.18"}, {"sp": "N", "t": "μόνον δὲ τοῦτο οὐχ οἷόν τε ὑμῖν ἐστιν ἀμνημονῆσαι· ἐν γὰρ τῇ αὐτῇ ἐκκλησίᾳ καὶ οἱ πρέσβεις ὑμῖν οἱ παρ’ ἐκείνου ἥκοντες διελέγοντο καὶ τὸ ψήφισμα ἐγράφη. ὥστ’ οὐχ οἷόν τε, παραχρῆμα τῶν λόγων εἰρημένων καὶ εὐθὺς τοῦ ψηφίσματος ἐπαναγιγνωσκομένου, τὴν καταψευδομένην γνώμην τῶν πρέσβεων, ταύτην ὑμᾶς χειροτονῆσαι· ὥστε τοῦτο μὲν οὐ κατ’ ἐμοῦ, ἀλλὰ καθ’ ὑμῶν ἐπέσταλκεν, ὡς ὑμεῖς περὶ ὧν οὐκ ἠκούσατε, περὶ τούτων ἀποκρινάμενοι τὴν γνώμην ἀπεστείλατε.", "st": "7.19"}, {"sp": "N", "t": "καὶ οἱ μὲν πρέσβεις αὐτοί, ὧν κατεψεύδετο τὸ ψήφισμα, ὅτ’ ἀπεκρίνεσθε αὐτοῖς ἀναγιγνώσκοντες καὶ ἐπὶ ξένια αὐτοὺς ἐκαλεῖτε, οὐκ ἐτόλμησαν παρελθεῖν, οὐδ’ εἰπεῖν ὅτι “καταψεύδεσθε ἡμῶν, ὦ ἄνδρες Ἀθηναῖοι, καὶ φατὲ ἡμᾶς εἰρηκέναι ἃ οὐκ εἰρήκαμεν,” ἀλλὰ σιωπῇ ἀπιόντες ᾤχοντο. βούλομαι δ’ ὑμᾶς, ὦ ἄνδρες Ἀθηναῖοι (καὶ γὰρ ηὐδοκίμησεν ὁ Πύθων παρ’ ὑμῖν ἐν τῇ δημηγορίᾳ, ὁ τότε πρεσβεύων), αὐτοὺς τοὺς λόγους οὓς ἔλεγεν ὑπομνῆσαι· οἶδα γὰρ ὅτι μέμνησθε.", "st": "7.20"}, {"sp": "N", "t": "παραπλήσιοι δ’ ἦσαν οἷς καὶ νῦν ἐπέσταλκε Φίλιππος· ἐγκαλῶν γὰρ ἡμῖν τοῖς διαβάλλουσι τὸν Φίλιππον, καὶ ὑμῖν ἐμέμφετο ὅτι ὡρμηκότος αὐτοῦ εὖ ποιεῖν ὑμᾶς καὶ προῃρημένου μάλιστα τῶν Ἑλλήνων φίλους κεκτῆσθαι αὐτοὶ κωλύετε, ἀποδεχόμενοι τοὺς λόγους τῶν συκοφαντούντων καὶ χρήματα ἐκεῖνον αἰτούντων καὶ διαβαλλόντων· τοὺς γὰρ τοιούτους λόγους, ὅταν ἀπαγγελλόντων ἀκούῃ, ὅτι κακῶς ἤκουεν, ὑμεῖς δ’ ἀπεδέχεσθε, μεταβάλλειν αὐτοῦ τὴν γνώμην, ὅταν ἄπιστος φαίνηται τούτοις ὧν προῄρηται εὐεργέτης εἶναι.", "st": "7.21"}, {"sp": "N", "t": "ἐκέλευεν οὖν τοὺς λέγοντας ἐν τῷ δήμῳ τῇ μὲν εἰρήνῃ μὴ ἐπιτιμᾶν· οὐ γὰρ ἄξιον εἶναι εἰρήνην λύειν· εἰ δέ τι μὴ καλῶς γέγραπται ἐν τῇ εἰρήνῃ, τοῦτ’ ἐπανορθώσασθαι, ὡς ἅπαντα Φίλιππον ποιήσοντα ὅσ’ ἂν ὑμεῖς ψηφίσησθε. ἂν δὲ διαβάλλωσι μέν, αὐτοὶ δὲ μηδὲν γράφωσι δι’ οὗ ἡ μὲν εἰρήνη ἔσται, παύσεται δ’ ἀπιστούμενος ὁ Φίλιππος, μὴ προσέχειν τὸν νοῦν τοῖς τοιούτοις ἀνθρώποις.", "st": "7.22"}, {"sp": "N", "t": "καὶ τούτους τοὺς λόγους ὑμεῖς ἀκούοντες ἀπεδέχεσθε, καὶ δίκαια ἔφατε τὸν Πύθωνα λέγειν· καὶ ἦν δίκαια. ἔλεγε δὲ τούτους τοὺς λόγους, οὐχ ὅπως λυθείη ἐκ τῆς εἰρήνης ἃ ἦν ἐκείνῳ συμφέροντα καὶ ὧν πολλὰ χρήματα ἀνηλώκει ὥστε γενέσθαι, ἀλλ’ ὑπὸ τῶν ἐνθάδε διδασκάλων προδεδιδαγμένος, οἳ οὐκ ᾤοντο εἶναι τὸν γράψοντα ἐναντία τῷ Φιλοκράτους ψηφίσματι, τῷ ἀπολλύντι Ἀμφίπολιν.", "st": "7.23"}, {"sp": "N", "t": "ἐγὼ δ’, ὦ ἄνδρες Ἀθηναῖοι, παράνομον μὲν οὐδὲν ἐτόλμησα γράψαι, τῷ δὲ Φιλοκράτους ψηφίσματι οὐκ ἦν παράνομον τἀναντία γράφειν, ὡς ἐγὼ ἐπιδείξω· τὸ γὰρ ψήφισμα τὸ Φιλοκράτους, καθ’ ὃ ὑμεῖς ἀπώλλυτε Ἀμφίπολιν, ἐναντίον ἦν τοῖς προτέροις ψηφίσμασι, καθ’ ἃ ὑμεῖς ἐκτήσασθε ταύτην τὴν χώραν.", "st": "7.24"}, {"sp": "N", "t": "τοῦτο μὲν οὖν παράνομον ἦν τὸ ψήφισμα, τὸ τοῦ Φιλοκράτους, καὶ οὐχ οἷόν τ’ ἦν τὸν τὰ ἔννομα γράφοντα ταὐτὰ τῷ παρανόμῳ ψηφίσματι γράφειν. ἐκείνοις δὲ τοῖς προτέροις ψηφίσμασι, τοῖς οὖσιν ἐννόμοις καὶ σῴζουσι τὴν ὑμετέραν χώραν, ταὐτὰ γράφων ἔννομά τ’ ἔγραψα καὶ ἐξήλεγχον τὸν Φίλιππον, ὅτι ἐξηπάτα ὑμᾶς καὶ οὐκ ἐπανορθώσασθαι ἐβούλετο τὴν εἰρήνην, ἀλλὰ τοὺς ὑπὲρ ὑμῶν λέγοντας ἀπίστους καταστῆσαι.", "st": "7.25"}, {"sp": "N", "t": "καὶ ὅτι μὲν δοὺς τὴν ἐπανόρθωσιν νῦν ἔξαρνός ἐστιν, ἅπαντες ἴστε. φησὶ δ’ Ἀμφίπολιν ἑαυτοῦ εἶναι· ὑμᾶς γὰρ ψηφίσασθαι ἐκείνου εἶναι, ὅτ’ ἐψηφίζεσθε ἔχειν αὐτὸν ἃ εἶχεν. ὑμεῖς δὲ τὸ μὲν ψήφισμα τοῦτ’ ἐψηφίσασθε, οὐ μέντοι γ’ ἐκείνου εἶναι Ἀμφίπολιν· ἔστι γὰρ ἔχειν καὶ τἀλλότρια, καὶ οὐχ ἅπαντες οἱ ἔχοντες τὰ αὑτῶν ἔχουσιν, ἀλλὰ πολλοὶ καὶ ἀλλότρια κέκτηνται· ὥστε τοῦτό γε τὸ σοφὸν αὐτῷ ἠλίθιόν ἐστιν.", "st": "7.26"}, {"sp": "N", "t": "καὶ τοῦ μὲν Φιλοκράτους ψηφίσματος μέμνηται, τῆς δ’ ἐπιστολῆς, ἣν πρὸς ὑμᾶς ἔπεμψεν ὅτ’ Ἀμφίπολιν ἐπολιόρκει, ἐπιλέλησται, ἐν ᾗ ὡμολόγει τὴν Ἀμφίπολιν ὑμετέραν εἶναι· ἔφη γὰρ ἐκπολιορκήσας ὑμῖν ἀποδώσειν, ὡς οὖσαν ὑμετέραν καὶ οὐ τῶν ἐχόντων.", "st": "7.27"}, {"sp": "N", "t": "κἀκεῖνοι μέν, ὡς ἔοικεν, οἱ πρότερον ἐν Ἀμφιπόλει οἰκοῦντες πρὶν Φίλιππον λαβεῖν, τὴν Ἀθηναίων χώραν εἶχον, ἐπειδὴ δὲ Φίλιππος αὐτὴν εἴληφεν, οὐ τὴν Ἀθηναίων χώραν ἀλλὰ τὴν ἑαυτοῦ ἔχει· οὐδ’ Ὄλυνθόν γε οὐδ’ Ἀπολλωνίαν οὐδὲ Παλλήνην, οὐκ ἀλλοτρίας ἀλλὰ τὰς ἑαυτοῦ χώρας κέκτηται.", "st": "7.28"}, {"sp": "N", "t": "ἆρ’ ὑμῖν δοκεῖ πεφυλαγμένως ἅπαντα πρὸς ὑμᾶς ἐπιστέλλειν, ὅπως ἂν φαίνηται καὶ λέγων καὶ πράττων ἃ παρὰ πᾶσιν ἀνθρώποις ὁμολογεῖται δίκαια εἶναι, ἀλλ’ οὐ σφόδρα καταπεφρονηκέναι, ὃς τὴν χώραν, ἣν οἱ Ἕλληνες καὶ βασιλεὺς ὁ Περσῶν ἐψηφίσαντο καὶ ὡμολογήκασιν ὑμετέραν εἶναι, ταύτην φησὶν ἑαυτοῦ καὶ οὐχ ὑμετέραν εἶναι;", "st": "7.29"}, {"sp": "N", "t": "περὶ δὲ τοῦ ἑτέρου ἐπανορθώματος, ὃ ὑμεῖς ἐν τῇ εἰρήνῃ ἐπανορθοῦσθε, τοὺς ἄλλους Ἕλληνας, ὅσοι μὴ κοινωνοῦσι τῆς εἰρήνης, ἐλευθέρους καὶ αὐτονόμους εἶναι, καὶ ἐάν τις ἐπ’ αὐτοὺς στρατεύῃ, βοηθεῖν τοὺς κοινωνοῦντας τῆς εἰρήνης,", "st": "7.30"}, {"sp": "N", "t": "ἡγούμενοι καὶ δίκαιον τοῦτο καὶ φιλάνθρωπον, μὴ μόνον ἡμᾶς καὶ τοὺς συμμάχους τοὺς ἡμετέρους καὶ Φίλιππον καὶ τοὺς συμμάχους τοὺς ἐκείνου ἄγειν τὴν εἰρήνην, τοὺς δὲ μήθ’ ἡμετέρους ὄντας μήτε Φιλίππου συμμάχους ἐν μέσῳ κεῖσθαι καὶ ὑπὸ τῶν κρειττόνων ἀπόλλυσθαι, ἀλλὰ καὶ τούτοις διὰ τὴν ὑμετέραν εἰρήνην ὑπάρχειν σωτηρίαν, καὶ τῷ ὄντι εἰρήνην ἄγειν ἡμᾶς καταθεμένους τὰ ὅπλα,", "st": "7.31"}, {"sp": "N", "t": "τοῦτο δὲ τὸ ἐπανόρθωμα ὁμολογῶν ἐν τῇ ἐπιστολῇ, ὡς ἀκούετε, δίκαιόν τ’ εἶναι καὶ δέχεσθαι, Φεραίων μὲν ἀφῄρηται τὴν πόλιν καὶ φρουρὰν ἐν τῇ ἀκροπόλει κατέστησεν, ἵνα δὴ αὐτόνομοι ὦσιν, ἐπὶ δ’ Ἀμβρακίαν στρατεύεται, τὰς δ’ ἐν Κασσωπίᾳ τρεῖς πόλεις, Πανδοσίαν καὶ Βούχετα καὶ Ἐλάτειαν, Ἠλείων ἀποικίας, κατακαύσας τὴν χώραν καὶ εἰς τὰς πόλεις βιασάμενος παρέδωκεν Ἀλεξάνδρῳ τῷ κηδεστῇ τῷ ἑαυτοῦ δουλεύειν. σφόδρα γε βούλεται τοὺς Ἕλληνας ἐλευθέρους εἶναι καὶ αὐτονόμους, ὡς δηλοῖ τὰ ἔργα.", "st": "7.32"}, {"sp": "N", "t": "περὶ δὲ τῶν ὑποσχέσεων ὧν ὑμῖν διατελεῖ ὑπισχνούμενος ὡς μεγάλα ὑμᾶς εὐεργετήσων, καταψεύδεσθαί μέ φησιν αὐτοῦ διαβάλλοντα πρὸς τοὺς Ἕλληνας· οὐδὲν γὰρ ὑμῖν πώποτέ φησιν ὑπεσχῆσθαι. οὕτως ἀναιδής ἐστιν ὁ ἐν ἐπιστολῇ γεγραφώς, ἥ ἐστι νῦν ἐν τῷ βουλευτηρίῳ, ὅσ’ ἐπιστομιεῖν ἡμᾶς, ἔφη, τοὺς αὐτῷ ἀντιλέγοντας, ἐὰν ἡ εἰρήνη γένηται, τοσαῦτα ὑμᾶς ἀγαθὰ ποιήσειν· ἃ γράφειν ἂν ἤδη, εἰ ᾔδει τὴν εἰρήνην ἐσομένην, δῆλον ὡς προκεχειρισμένων καὶ ἑτοίμων ὄντων τῶν ἀγαθῶν, ἃ ἐμέλλομεν πείσεσθαι τῆς εἰρήνης γενομένης.", "st": "7.33"}, {"sp": "N", "t": "γενομένης δὲ τῆς εἰρήνης, ἃ μὲν ἡμεῖς ἐμέλλομεν ἀγαθὰ πείσεσθαι, ἐκποδών ἐστι, φθορὰ δὲ τῶν Ἑλλήνων τοσαύτη γέγονεν ὅσην ὑμεῖς ἴστε. ὑμῖν δ’ ἐν τῇ νῦν ἐπιστολῇ ὑπισχνεῖται, ἐὰν τοῖς μὲν αὑτοῦ φίλοις καὶ ὑπὲρ αὐτοῦ λέγουσι πιστεύητε, ἡμᾶς δὲ τοὺς διαβάλλοντας αὐτὸν πρὸς ὑμᾶς τιμωρήσησθε, ὡς μεγάλα εὐεργετήσει.", "st": "7.34"}, {"sp": "N", "t": "τὰ μέντοι εὐεργετήματα τοιαῦτα ἔσται· οὔτε τὰ ὑμέτερα ὑμῖν ἀποδώσει (αὑτοῦ γάρ φησιν εἶναι), οὔτ’ ἐν τῇ οἰκουμένῃ αἱ δωρειαὶ ἔσονται, ἵνα μὴ διαβληθῇ πρὸς τοὺς Ἕλληνας, ἀλλ’ ἄλλη τις χώρα καὶ ἄλλος, ὡς ἔοικε, τόπος φανήσεται, οὗ ὑμῖν αἱ δωρειαὶ δοθήσονται.", "st": "7.35"}, {"sp": "N", "t": "περὶ δ’ ὧν ἐν τῇ εἰρήνῃ εἴληφε χωρίων, ὑμῶν ἐχόντων, παρασπονδῶν καὶ λύων τὴν εἰρήνην, ἐπειδὴ οὐκ ἔχει ὅ τι εἴπῃ, ἀλλ’ ἀδικῶν φανερῶς ἐξελέγχεται, ἐπιτρέπειν φησὶ περὶ τούτων ἕτοιμος εἶναι ἴσῳ καὶ κοινῷ δικαστηρίῳ· περὶ ὧν μόνων οὐδὲν δεῖ ἐπιτροπῆς, ἀλλ’ ἀριθμὸς ἡμερῶν ἐστιν ὁ κρίνων. ἅπαντες γὰρ ἴσμεν τίνι μηνὶ καὶ τίνι ἡμέρᾳ ἡ εἰρήνη ἐγένετο.", "st": "7.36"}, {"sp": "N", "t": "ὥσπερ δὲ ταῦτα ἴσμεν, κἀκεῖνα ἴσμεν, τίνι μηνὶ καὶ τίνι ἡμέρᾳ Σέρρειον τεῖχος καὶ Ἐργίσκη καὶ Ἱερὸν ὄρος ἑάλω. οὐ δὴ ἀφανῆ ἐστι τὰ οὕτω πραχθέντα, οὐδὲ κρίσεως δεόμενα, ἀλλὰ πᾶσι γνώριμα πότερος πρότερος ὁ μήν ἐστιν, ἐν ᾧ ἡ εἰρήνη ἐγένετο ἢ ἐν ᾧ τὰ χωρία ἑάλω.", "st": "7.37"}, {"sp": "N", "t": "φησὶ δὲ καὶ τοὺς αἰχμαλώτους ἡμῶν, ὅσοι ἐν τῷ πολέμῳ ἑάλωσαν, ἀποδεδωκέναι· ὃς τὸν μὲν Καρύστιον, τὸν πρόξενον τῆς ἡμετέρας πόλεως, ὑπὲρ οὗ ὑμεῖς τρεῖς πρέσβεις ἐπέμψατε ἀπαιτοῦντες, τοῦτον τὸν ἄνδρα ἐκεῖνος οὕτω σφόδρα ὑμῖν ἐβούλετο χαρίσασθαι, ὥστ’ ἀπέκτεινε καὶ οὐδ’ ἀναίρεσιν ἔδωκεν, ἵνα ταφῇ.", "st": "7.38"}, {"sp": "N", "t": "περὶ δὲ Χερρονήσου, ἅ τ’ ἐπιστέλλει πρὸς ὑμᾶς ἄξιόν ἐστιν ἐξετάσαι, ἔτι δὲ καὶ ἃ πράττει, καὶ ταῦτ’ εἰδέναι. τὸν μὲν γὰρ τόπον ἅπαντα τὸν ἔξω Ἀγορᾶς ὡς ἑαυτοῦ ὄντα καὶ ὑμῖν οὐδὲν προσήκοντα δέδωκε καρποῦσθαι Ἀπολλωνίδῃ τῷ Καρδιανῷ. καίτοι Χερρονήσου οἱ ὅροι εἰσίν, οὐκ Ἀγορά, ἀλλὰ βωμὸς τοῦ Διὸς τοῦ ὁρίου, ὅς ἐστι μεταξὺ Πτελεοῦ καὶ Λευκῆς ἀκτῆς, ᾗ ἡ διορυχὴ ἔμελλε Χερρονήσου ἔσεσθαι,", "st": "7.39"}, {"sp": "N", "t": "ὥς γε τὸ ἐπίγραμμα τὸ ἐπὶ τοῦ βωμοῦ τοῦ Διὸς τοῦ ὁρίου δηλοῖ. ἔστι δὲ τουτί·", "st": "7.40"}, {"sp": "N", "t": "τόνδε καθιδρύσαντο θεῷ περικαλλέα βωμὸν<br>λευκῆς καὶ Πτελεοῦ μέσσον ὅρον θέμενοι<br>ἐνναέται, χώρης σημήϊον· ἀμμορίης δὲ<br>αὐτὸς ἄναξ μακάρων ἐστὶ μέσος Κρονίδης.", "st": "7.40"}, {"sp": "N", "t": "ταύτην μέντοι τὴν χώραν, τοσαύτην οὖσαν ὅσην οἱ πολλοὶ ὑμῶν ἴσασιν, ὡς ἑαυτοῦ οὖσαν τὴν μὲν αὐτὸς καρποῦται, τὴν δ’ ἄλλοις δωρειὰν δέδωκε, καὶ ἅπαντα τὰ κτήματα τὰ ὑμέτερα ὑφ’ αὑτῷ ποιεῖται. καὶ οὐ μόνον τὴν ἔξω Ἀγορᾶς χώραν σφετερίζεται, ἀλλὰ καὶ πρὸς Καρδιανούς, οἳ οἰκοῦσιν εἴσω Ἀγορᾶς, ἐπιστέλλει ἐν τῇ νῦν ἐπιστολῇ ὡς δεῖ ὑμᾶς διαδικάζεσθαι—πρὸς Καρδιανοὺς τοὺς κατοικοῦντας ἐν τῇ ὑμετέρᾳ—εἴ τι πρὸς αὐτοὺς διαφέρεσθε.", "st": "7.41"}, {"sp": "N", "t": "διαφέρονται δὲ πρὸς ὑμᾶς, σκέψασθε εἰ περὶ μικροῦ. ἑαυτῶν φασι τὴν χώραν οὖσαν οἰκεῖν καὶ οὐχ ὑμετέραν, καὶ τὰ μὲν ὑμέτερα εἶναι ἐγκτήματα ὡς ἐν ἀλλοτρίᾳ, τὰ δὲ ἑαυτῶν κτήμαθ’ ὡς ἐν οἰκείᾳ, καὶ ταῦθ’ ὑμέτερον πολίτην γράψαι ἐν ψηφίσματι, Κάλλιππον Παιανιέα.", "st": "7.42"}, {"sp": "N", "t": "καὶ τοῦτό γ’ ἀληθῆ λέγουσιν· ἔγραψε γάρ, καὶ ἐμοῦ γ’ αὐτὸν γραψαμένου παρανόμων γραφὴν ὑμεῖς ἀπεψηφίσασθε· τοιγάρτοι ἀμφισβητήσιμον ὑμῖν τὴν χώραν κατεσκεύακεν. ὁπότε δὲ περὶ τούτου τολμήσετε πρὸς Καρδιανοὺς διαδικάζεσθαι, εἴθ’ ὑμετέρα ἐστὶν εἴτ’ ἐκείνων ἡ χώρα, διὰ τί οὐ καὶ πρὸς τοὺς ἄλλους Χερρονησίτας τὸ αὐτὸ δίκαιον ἔσται;", "st": "7.43"}, {"sp": "N", "t": "καὶ οὕτως ὑβριστικῶς ὑμῖν κέχρηται ὥστε φήσιν, ἂν μὴ θέλωσι διαδικάζεσθαι οἱ Καρδιανοί, αὐτὸς ἀναγκάσειν, ὡς ὑμῶν γ’ οὐκ ἂν δυναμένων οὐδὲν ἀναγκάσαι Καρδιανοὺς ὑμῖν ποιῆσαι· ἐπειδὴ δ’ ὑμεῖς οὐ δύνασθε, αὐτός φησι τοῦτ’ ἀναγκάσειν αὐτοὺς ποιῆσαι. ἆρ’ οὐ μεγάλα φαίνεται ὑμᾶς εὐεργετῶν;", "st": "7.44"}, {"sp": "N", "t": "καὶ ταύτην τὴν ἐπιστολήν τινες εὖ ἔφασαν γεγράφθαι, οἳ πολὺ ἂν δικαιότερον ὑφ’ ὑμῶν ἢ Φίλιππος μισοῖντο. ἐκεῖνος μέν γ’ ἑαυτῷ κτώμενος δόξαν καὶ μεγάλ’ ἀγαθὰ ἅπαντα καθ’ ὑμῶν πράττει· ὅσοι δ’ Ἀθηναῖοι ὄντες μὴ τῇ πατρίδι, ἀλλὰ Φιλίππῳ εὔνοιαν ἐνδείκνυνται, προσήκει αὐτοὺς ὑφ’ ὑμῶν κακοὺς κακῶς ἀπολωλέναι, εἴπερ ὑμεῖς τὸν ἐγκέφαλον ἐν τοῖς κροτάφοις καὶ μὴ ἐν ταῖς πτέρναις καταπεπατημένον φορεῖτε.", "st": "7.45"}, {"sp": "N", "t": "ὑπόλοιπόν μοί ἐστιν ἔτι πρὸς ταύτην τὴν ἐπιστολὴν τὴν εὖ ἔχουσαν καὶ τοὺς λόγους τῶν πρέσβεων γράψαι τὴν ἀπόκρισιν, ἣν ἡγοῦμαι δικαίαν τ’ εἶναι καὶ συμφέρουσαν ὑμῖν.", "st": "7.46"}, {"sp": "HDR", "t": "Περὶ τῶν ἐν Χερρονήσῳ", "st": "8"}, {"sp": "N", "t": "ἔδει μέν, ὦ ἄνδρες Ἀθηναῖοι, τοὺς λέγοντας ἅπαντας μήτε πρὸς ἔχθραν ποιεῖσθαι λόγον μηδένα μήτε πρὸς χάριν, ἀλλ’ ὃ βέλτιστον ἕκαστος ἡγεῖτο, τοῦτ’ ἀποφαίνεσθαι, ἄλλως τε καὶ περὶ κοινῶν πραγμάτων καὶ μεγάλων ὑμῶν βουλευομένων· ἐπεὶ δ’ ἔνιοι τὰ μὲν φιλονικίᾳ, τὰ δ’ ᾑτινιδήποτ’ αἰτίᾳ προάγονται λέγειν, ὑμᾶς, ὦ ἄνδρες Ἀθηναῖοι, τοὺς πολλοὺς δεῖ πάντα τἄλλ’ ἀφελόντας, ἃ τῇ πόλει νομίζετε συμφέρειν, ταῦτα καὶ ψηφίζεσθαι καὶ πράττειν.", "st": "8.1"}, {"sp": "N", "t": "ἡ μὲν οὖν σπουδὴ περὶ τῶν ἐν Χερρονήσῳ πραγμάτων ἐστὶ καὶ τῆς στρατείας, ἣν ἑνδέκατον μῆνα τουτονὶ Φίλιππος ἐν Θρᾴκῃ ποιεῖται· τῶν δὲ λόγων οἱ πλεῖστοι περὶ ὧν Διοπείθης πράττει καὶ μέλλει ποιεῖν εἴρηνται. ἐγὼ δ’ ὅσα μέν τις αἰτιᾶταί τινα τούτων, οὓς κατὰ τοὺς νόμους ἐφ’ ὑμῖν ἐστιν, ὅταν βούλησθε, κολάζειν, κἂν ἤδη δοκῇ κἂν ἐπισχοῦσιν περὶ αὐτῶν σκοπεῖν ἐγχωρεῖν ἡγοῦμαι, καὶ οὐ πάνυ δεῖ περὶ τούτων οὔτ’ ἔμ’ οὔτ’ ἄλλον οὐδέν’ ἰσχυρίζεσθαι·", "st": "8.2"}, {"sp": "N", "t": "ὅσα δ’ ἐχθρὸς ὑπάρχων τῇ πόλει καὶ δυνάμει πολλῇ περὶ Ἑλλήσποντον ὢν πειρᾶται προλαβεῖν, κἂν ἅπαξ ὑστερήσωμεν, οὐκέθ’ ἕξομεν σῶσαι, περὶ τούτων δ’ οἴομαι τὴν ταχίστην συμφέρειν καὶ βεβουλεῦσθαι καὶ παρεσκευάσθαι, καὶ μὴ τοῖς περὶ τῶν ἄλλων θορύβοις καὶ ταῖς κατηγορίαις ἀπὸ τούτων ἀποδρᾶναι.", "st": "8.3"}, {"sp": "N", "t": "πολλὰ δὲ θαυμάζων τῶν εἰωθότων λέγεσθαι παρ’ ὑμῖν, οὐδενὸς ἧττον, ὦ ἄνδρες Ἀθηναῖοι, τεθαύμακα, ὃ καὶ πρώην τινὸς ἤκουσ’ εἰπόντος ἐν τῇ βουλῇ, ὡς ἄρα δεῖ τὸν συμβουλεύοντα ἢ πολεμεῖν ἁπλῶς ἢ τὴν εἰρήνην ἄγειν συμβουλεύειν.", "st": "8.4"}, {"sp": "N", "t": "ἔστι δέ, εἰ μὲν ἡσυχίαν Φίλιππος ἄγει καὶ μήτε τῶν ἡμετέρων ἔχει παρὰ τὴν εἰρήνην μηδὲν μήτε συσκευάζεται πάντας ἀνθρώπους ἐφ’ ἡμᾶς, οὐκέτι δεῖ λέγειν, ἀλλ’ ἁπλῶς εἰρήνην ἀκτέον, καὶ τά γ’ ἀφ’ ὑμῶν ἕτοιμ’ ὑπάρχονθ’ ὁρῶ· εἰ δ’ ἃ μὲν ὠμόσαμεν καὶ ἐφ’ οἷς τὴν εἰρήνην ἐποιησάμεθα,", "st": "8.5"}, {"sp": "N", "t": "ἔστιν ἰδεῖν καὶ γεγραμμένα κεῖται, φαίνεται δ’ ἀπ’ ἀρχῆς ὁ Φίλιππος, πρὶν Διοπείθην ἐκπλεῦσαι καὶ τοὺς κληρούχους, οὓς νῦν αἰτιῶνται πεποιηκέναι τὸν πόλεμον, πολλὰ μὲν τῶν ἡμετέρων ἀδίκως εἰληφώς, ὑπὲρ ὧν ψηφίσμαθ’ ὑμέτερ’ ἐγκαλοῦντα κύρια ταυτί, πάντα δὲ τὸν χρόνον συνεχῶς τὰ τῶν ἄλλων Ἑλλήνων καὶ βαρβάρων λαμβάνων καὶ ἐφ’ ἡμᾶς συσκευαζόμενος, τί τοῦτο λέγουσιν, ὡς πολεμεῖν ἢ ἄγειν εἰρήνην δεῖ;", "st": "8.6"}, {"sp": "N", "t": "οὐ γὰρ αἵρεσίς ἐστιν ἡμῖν τοῦ πράγματος, ἀλλ’ ὑπολείπεται τὸ δικαιότατον καὶ ἀναγκαιότατον τῶν ἔργων, ὃ ὑπερβαίνουσιν ἑκόντες οὗτοι. τί οὖν ἐστι τοῦτο; ἀμύνεσθαι τὸν πρότερον πολεμοῦνθ’ ἡμῖν. πλὴν εἰ τοῦτο λέγουσι νὴ Δί’, ὡς, ἂν ἀπέχηται τῆς Ἀττικῆς καὶ τοῦ Πειραιῶς Φίλιππος, οὔτ’ ἀδικεῖ τὴν πόλιν οὔτε ποιεῖ πόλεμον.", "st": "8.7"}, {"sp": "N", "t": "εἰ δ’ ἐκ τούτων τὰ δίκαια τίθενται καὶ τὴν εἰρήνην ταύτην ὁρίζονται, ὅτι μὲν δήπουθεν οὔθ’ ὅσι’ οὔτ’ ἀνεκτὰ λέγουσιν οὔθ’ ὑμῖν ἀσφαλῆ, δῆλόν ἐστιν ἅπασιν, οὐ μὴν ἀλλ’ ἐναντία συμβαίνει ταῖς κατηγορίαις ἃς Διοπείθους κατηγοροῦσι καὶ αὐτὰ ταῦτα λέγειν αὐτούς. τί γὰρ δήποτε τῷ μὲν Φιλίππῳ πάντα τἄλλα ποιεῖν ἐξουσίαν δώσομεν, ἂν τῆς Ἀττικῆς ἀπέχηται, τῷ Διοπείθει δ’ οὐδὲ βοηθεῖν τοῖς Θρᾳξὶν ἐξέσται, ἢ πόλεμον ποιεῖν αὐτὸν φήσομεν;", "st": "8.8"}, {"sp": "N", "t": "ἀλλὰ νὴ Δία, ταῦτα μὲν ἐξελέγχονται, δεινὰ ποιοῦσι δ’ οἱ ξένοι περικόπτοντες τὰ ἐν Ἑλλησπόντῳ, καὶ Διοπείθης ἀδικεῖ κατάγων τὰ πλοῖα, καὶ δεῖ μὴ ἐπιτρέπειν αὐτῷ. ἔστω, γιγνέσθω ταῦτα, οὐδὲν ἀντιλέγω. οἶμαι μέντοι δεῖν, εἴπερ ὡς ἀληθῶς ἐπὶ πᾶσι δικαίοις ταῦτα συμβουλεύουσιν,", "st": "8.9"}, {"sp": "N", "t": "ὥσπερ τὴν ὑπάρχουσαν τῇ πόλει δύναμιν καταλῦσαι ζητοῦσι, τὸν ἐφεστηκότα καὶ πορίζοντα χρήματα ταύτῃ διαβάλλοντες ἐν ὑμῖν, οὕτω τὴν Φιλίππου δύναμιν δεῖξαι διαλυθησομένην, ἂν ὑμεῖς ταῦτα πεισθῆτε. εἰ δὲ μή, σκοπεῖθ’ ὅτι οὐδὲν ἄλλο ποιοῦσιν ἢ καθιστᾶσι τὴν πόλιν εἰς τὸν αὐτὸν τρόπον δι’ οὗ τὰ [παρόντα] πράγμαθ’ ἅπαντ’ ἀπολώλεκεν.", "st": "8.10"}, {"sp": "N", "t": "ἴστε γὰρ δήπου τοῦθ’ ὅτι οὐδενὶ τῶν πάντων πλέον κεκράτηκε Φίλιππος, ἢ τῷ πρότερος πρὸς τοῖς πράγμασι γίγνεσθαι. ὁ μὲν γὰρ ἔχων δύναμιν συνεστηκυῖαν ἀεὶ περὶ αὑτὸν καὶ προειδὼς ἃ βούλεται πρᾶξαι, ἐξαίφνης ἐφ’ οὓς ἂν αὐτῷ δόξῃ πάρεστιν· ἡμεῖς δ’ ἐπειδὰν πυθώμεθά τι γιγνόμενον, τηνικαῦτα θορυβούμεθα καὶ παρασκευαζόμεθα.", "st": "8.11"}, {"sp": "N", "t": "εἶτ’, οἶμαι, συμβαίνει τῷ μὲν ἐφ’ ἃν ἔλθῃ, ταῦτ’ ἔχειν κατὰ πολλὴν ἡσυχίαν, ἡμῖν δ’ ὑστερίζειν, καὶ ὅσ’ ἂν δαπανήσωμεν, ἅπαντα μάτην ἀνηλωκέναι, καὶ τὴν μὲν ἔχθραν καὶ τὸ βούλεσθαι κωλύειν ἐνδεδεῖχθαι, ὑστερίζοντας δὲ τῶν ἔργων αἰσχύνην προσοφλισκάνειν.", "st": "8.12"}, {"sp": "N", "t": "μὴ τοίνυν ἀγνοεῖτ’, ὦ ἄνδρες Ἀθηναῖοι, ὅτι καὶ τὰ νῦν τἄλλα μέν ἐστι λόγοι ταῦτα καὶ προφάσεις, πράττεται δὲ καὶ κατασκευάζεται τοῦτο, ὅπως ὑμῶν μὲν οἴκοι μενόντων, ἔξω δὲ μηδεμιᾶς οὔσης τῇ πόλει δυνάμεως, μετὰ πλείστης ἡσυχίας ἅπανθ’ ὅσα βούλεται Φίλιππος διοικήσεται. θεωρεῖτε γὰρ τὸ παρὸν πρῶτον, ὃ γίγνεται.", "st": "8.13"}, {"sp": "N", "t": "νυνὶ δύναμιν μεγάλην ἐκεῖνος ἔχων ἐν Θρᾴκῃ διατρίβει, καὶ μεταπέμπεται πολλήν, ὥς φασιν οἱ παρόντες, ἀπὸ Μακεδονίας καὶ Θετταλίας. ἐὰν οὖν περιμείνας τοὺς ἐτησίας ἐπὶ Βυζάντιον ἐλθὼν πολιορκῇ, πρῶτον μὲν οἴεσθε τοὺς Βυζαντίους μενεῖν ἐπὶ τῆς ἀνοίας τῆς αὐτῆς ὥσπερ νῦν, καὶ οὔτε παρακαλεῖν ὑμᾶς οὔτε βοηθεῖν αὑτοῖς ἀξιώσειν;", "st": "8.14"}, {"sp": "N", "t": "ἐγὼ μὲν οὐκ οἴομαι, ἀλλὰ καὶ εἴ τισι μᾶλλον ἀπιστοῦσιν ἢ ἡμῖν, καὶ τούτους εἰσφρήσεσθαι μᾶλλον ἢ ’κείνῳ παραδώσειν τὴν πόλιν, ἄν περ μὴ φθάσῃ λαβὼν αὐτούς. οὐκοῦν ἡμῶν μὲν μὴ δυναμένων ἐνθένδ’ ἀναπλεῦσαι, ἐκεῖ δὲ μηδεμιᾶς ὑπαρχούσης ἑτοίμου βοηθείας, οὐδὲν αὐτοὺς ἀπολωλέναι κωλύσει.", "st": "8.15"}, {"sp": "N", "t": "νὴ Δία, κακοδαιμονῶσι γὰρ ἅνθρωποι καὶ ὑπερβάλλουσιν ἀνοίᾳ. πάνυ γε, ἀλλ’ ὅμως αὐτοὺς δεῖ σῶς εἶναι· συμφέρει γὰρ τῇ πόλει. καὶ μὴν οὐδ’ ἐκεῖνό γε δῆλόν ἐστιν ἡμῖν, ὡς ἐπὶ Χερρόνησον οὐχ ἥξει· ἀλλ’ εἴγ’ ἐκ τῆς ἐπιστολῆς δεῖ σκοπεῖν ἧς ἔπεμψε πρὸς ὑμᾶς, ἀμυνεῖσθαί φησι τοὺς ἐν Χερρονήσῳ.", "st": "8.16"}, {"sp": "N", "t": "ἂν μὲν τοίνυν ᾖ τὸ συνεστηκὸς στράτευμα, καὶ τῇ χώρᾳ βοηθῆσαι δυνήσεται καὶ τῶν ἐκείνου τι κακῶς ποιῆσαι· εἰ δ’ ἅπαξ διαλυθήσεται, τί ποιήσομεν, ἂν ἐπὶ Χερρόνησον ἴῃ; “κρινοῦμεν Διοπείθη νὴ Δία.” καὶ τί τὰ πράγματ’ ἔσται βελτίω; “ἀλλ’ ἐνθένδ’ ἂν βοηθήσαιμεν αὐτοί.” ἂν δ’ ὑπὸ τῶν πνευμάτων μὴ δυνώμεθα; “ἀλλὰ μὰ Δί’ οὐχ ἥξει.”", "st": "8.17"}, {"sp": "N", "t": "καὶ τίς ἐγγυητής ἐστι τούτου; ἆρ’ ὁρᾶτε καὶ λογίζεσθ’, ὦ ἄνδρες Ἀθηναῖοι, τὴν ἐπιοῦσαν ὥραν τοῦ ἔτους, εἰς ἣν ἔρημόν τινες οἴονται δεῖν τὸν Ἑλλήσποντον ὑμῶν ποιῆσαι καὶ παραδοῦναι Φιλίππῳ; τί δ’, ἂν ἀπελθὼν ἐκ Θρᾴκης καὶ μηδὲ προσελθὼν Χερρονήσῳ μηδὲ Βυζαντίῳ (καὶ γὰρ ταῦτα λογίζεσθε) ἐπὶ Χαλκίδα καὶ Μέγαρ’ ἥκῃ τὸν αὐτὸν τρόπον ὅνπερ ἐπ’ Ὠρεὸν πρώην, πότερον κρεῖττον ἐνθάδ’ αὐτὸν ἀμύνεσθαι καὶ προσελθεῖν τὸν πόλεμον πρὸς τὴν Ἀττικὴν ἐᾶσαι, ἢ κατασκευάζειν ἐκεῖ τιν’ ἀσχολίαν αὐτῷ; ἐγὼ μὲν οἴομαι τοῦτο.", "st": "8.18"}, {"sp": "N", "t": "ταῦτα τοίνυν ἅπαντας εἰδότας καὶ λογιζομένους χρή, οὐ μὰ Δί’ οὐχ ἣν Διοπείθης πειρᾶται τῇ πόλει δύναμιν παρασκευάζειν, ταύτην βασκαίνειν καὶ διαλῦσαι πειρᾶσθαι, ἀλλ’ ἑτέραν αὐτοὺς προσπαρασκευάζειν καὶ συνευποροῦντας ἐκείνῳ χρημάτων καὶ τἄλλ’ οἰκείως συναγωνιζομένους.", "st": "8.19"}, {"sp": "N", "t": "εἰ γάρ τις ἔροιτο Φίλιππον, “εἰπέ μοι, πότερ’ ἂν βούλοιο τούτους τοὺς στρατιώτας οὓς Διοπείθης νῦν ἔχει, τοὺς ὁποιουστινασοῦν (οὐδὲν γὰρ ἀντιλέγω) εὐθενεῖν καὶ παρ’ Ἀθηναίοις εὐδοξεῖν καὶ πλείους γίγνεσθαι τῆς πόλεως συναγωνιζομένης, ἢ διαβαλλόντων τινῶν καὶ κατηγορούντων διασπασθῆναι καὶ διαφθαρῆναι;” ταῦτ’ ἂν οἶμαι φήσειεν. εἶθ’ ἃ Φίλιππος ἂν εὔξαιτο τοῖς θεοῖς, ταῦθ’ ἡμῶν τινες ἐνθάδε πράττουσιν; εἶτ’ ἔτι ζητεῖτε πόθεν τὰ τῆς πόλεως ἀπόλωλεν ἅπαντα;", "st": "8.20"}, {"sp": "N", "t": "βούλομαι τοίνυν [ὑμᾶς] μετὰ παρρησίας ἐξετάσαι τὰ παρόντα πράγματα τῇ πόλει, καὶ σκέψασθαι τί ποιοῦμεν αὐτοὶ νῦν καὶ ὅπως χρώμεθ’ αὐτοῖς. ἡμεῖς οὔτε χρήματ’ εἰσφέρειν βουλόμεθα, οὔτ’ αὐτοὶ στρατεύεσθαι, οὔτε τῶν κοινῶν ἀπέχεσθαι δυνάμεθα, οὔτε τὰς συντάξεις Διοπείθει δίδομεν, οὔθ’ ὅσ’ ἂν αὐτὸς αὑτῷ πορίσηται ἐπαινοῦμεν,", "st": "8.21"}, {"sp": "N", "t": "ἀλλὰ βασκαίνομεν καὶ σκοποῦμεν πόθεν, καὶ τί μέλλει ποιεῖν, καὶ πάντα τὰ τοιαυτί, οὔτ’, ἐπειδήπερ οὕτως ἔχομεν, τὰ ἡμέτερ’ αὐτῶν πράττειν ἐθέλομεν, ἀλλ’ ἐν μὲν τοῖς λόγοις τοὺς τῆς πόλεως λέγοντας ἄξι’ ἐπαινοῦμεν, ἐν δὲ τοῖς ἔργοις τοῖς ἐναντιουμένοις τούτοις συναγωνιζόμεθα.", "st": "8.22"}, {"sp": "N", "t": "ὑμεῖς μὲν τοίνυν εἰώθαθ’ ἑκάστοτε τὸν παριόντ’ ἐρωτᾶν, τί οὖν χρὴ ποιεῖν; ἐγὼ δ’ ὑμᾶς ἐρωτῆσαι βούλομαι, τί οὖν χρὴ λέγειν; εἰ γὰρ μήτ’ εἰσοίσετε, μήτ’ αὐτοὶ στρατεύσεσθε, μήτε τῶν κοινῶν ἀφέξεσθε, μήτε τὰς συντάξεις δώσετε, μήθ’ ὅσ’ ἂν αὐτὸς αὑτῷ πορίσηται ἐάσετε, μήτε τὰ ὑμέτερ’ αὐτῶν πράττειν ἐθελήσετε, οὐκ ἔχω τί λέγω. οἱ γὰρ ἤδη τοσαύτην ἐξουσίαν τοῖς αἰτιᾶσθαι καὶ διαβάλλειν βουλομένοις διδόντες, ὥστε καὶ περὶ ὧν φασι μέλλειν αὐτὸν ποιεῖν, καὶ περὶ τούτων προκατηγορούντων ἀκροᾶσθαι, —τί ἄν τις λέγοι;", "st": "8.23"}, {"sp": "N", "t": "ὅ τι τοίνυν δύναται ταῦτα ποιεῖν, ἐνίους μαθεῖν ὑμῶν δεῖ. λέξω δὲ μετὰ παρρησίας· καὶ γὰρ οὐδ’ ἂν ἄλλως δυναίμην. πάντες ὅσοι πώποτ’ ἐκπεπλεύκασι παρ’ ὑμῶν στρατηγοί (ἢ ’γὼ πάσχειν ὁτιοῦν τιμῶμαι) καὶ παρὰ Χίων καὶ παρ’ Ἐρυθραίων καὶ παρ’ ὧν ἂν ἕκαστοι δύνωνται, τούτων τῶν τὴν Ἀσίαν οἰκούντων λέγω, χρήματα λαμβάνουσιν.", "st": "8.24"}, {"sp": "N", "t": "λαμβάνουσι δ’ οἱ μὲν ἔχοντες μίαν ἢ δύο ναῦς ἐλάττονα, οἱ δὲ μείζω δύναμιν πλείονα. καὶ διδόασιν οἱ διδόντες οὔτε τὰ μικρὰ οὔτε τὰ πολλὰ ἀντ’ οὐδενός (οὐ γὰρ οὕτω μαίνονται), ἀλλ’ ὠνούμενοι μὴ ἀδικεῖσθαι τοὺς παρ’ αὑτῶν ἐκπλέοντας ἐμπόρους, μὴ συλᾶσθαι, παραπέμπεσθαι τὰ πλοῖα τὰ αὑτῶν, τὰ τοιαῦτα· φασὶ δ’ εὐνοίας διδόναι, καὶ τοῦτο τοὔνομ’ ἔχει τὰ λήμματα ταῦτα.", "st": "8.25"}, {"sp": "N", "t": "καὶ δὴ καὶ νῦν τῷ Διοπείθει στράτευμ’ ἔχοντι σαφῶς ἐστι τοῦτο δῆλον ὅτι δώσουσι χρήματα πάντες οὗτοι· πόθεν γὰρ οἴεσθ’ ἄλλοθεν τὸν μήτε λαβόντα παρ’ ὑμῶν μηδὲν μήτ’ αὐτὸν ἔχονθ’ ὁπόθεν μισθοδοτήσει, στρατιώτας τρέφειν; ἐκ τοῦ οὐρανοῦ; οὐκ ἔστι ταῦτα, ἀλλ’ ἀφ’ ὧν ἀγείρει καὶ προσαιτεῖ καὶ δανείζεται, ἀπὸ τούτων διάγει.", "st": "8.26"}, {"sp": "N", "t": "οὐδὲν οὖν ἄλλο ποιοῦσιν οἱ κατηγοροῦντες ἐν ὑμῖν ἢ προλέγουσιν ἅπασι μηδ’ ὁτιοῦν ἐκείνῳ διδόναι, ὡς καὶ τοῦ μελλῆσαι δώσοντι δίκην, μή τι ποιήσαντί γ’ ἢ καταπραξαμένῳ. τοῦτ’ εἰσὶν οἱ λόγοι· “μέλλει πολιορκεῖν,” “τοὺς Ἕλληνας ἐκδίδωσιν.” μέλει γάρ τινι τούτων τῶν τὴν Ἀσίαν οἰκούντων Ἑλλήνων; ἀμείνους μέντἂν εἶεν τῶν ἄλλων ἢ τῆς πατρίδος κήδεσθαι.", "st": "8.27"}, {"sp": "N", "t": "καὶ τό γ’ εἰς τὸν Ἑλλήσποντον εἰσπέμπειν ἕτερον στρατηγὸν τοῦτ’ ἐστίν. εἰ γὰρ δεινὰ ποιεῖ Διοπείθης καὶ κατάγει τὰ πλοῖα, μικρόν, ὦ ἄνδρες Ἀθηναῖοι, μικρὸν πινάκιον ταῦτα πάντα κωλῦσαι δύναιτ’ ἄν, καὶ λέγουσιν οἱ νόμοι, ταῦτα τοὺς ἀδικοῦντας εἰσαγγέλλειν, οὐ μὰ Δί’ οὐ δαπάναις καὶ τριήρεσιν τοσαύταις ἡμᾶς αὐτοὺς φυλάττειν, ἐπεὶ τοῦτό γ’ ἐστὶν ὑπερβολὴ μανίας·", "st": "8.28"}, {"sp": "N", "t": "ἀλλ’ ἐπὶ μὲν τοὺς ἐχθρούς, οὓς οὐκ ἔστι λαβεῖν ὑπὸ τοῖς νόμοις, καὶ στρατιώτας τρέφειν καὶ τριήρεις ἐκπέμπειν καὶ χρήματ’ εἰσφέρειν δεῖ καὶ ἀναγκαῖόν ἐστιν, ἐπὶ δ’ ἡμᾶς αὐτοὺς ψήφισμα, εἰσαγγελία, πάραλος ταῦτ’ ἔστιν. ταῦτ’ ἦν εὖ φρονούντων ἀνθρώπων, ἐπηρεαζόντων δὲ καὶ διαφθειρόντων τὰ πράγμαθ’ ἃ νῦν οὗτοι ποιοῦσιν.", "st": "8.29"}, {"sp": "N", "t": "καὶ τὸ μὲν τούτων τινὰς εἶναι τοιούτους, δεινὸν ὂν οὐ δεινόν ἐστιν· ἀλλ’ ὑμεῖς οἱ καθήμενοι οὕτως ἤδη διάκεισθε, ὥστ’, ἂν μέν τις εἴπῃ παρελθὼν ὅτι Διοπείθης ἐστὶ τῶν κακῶν πάντων αἴτιος, ἢ Χάρης ἢ Ἀριστοφῶν ἢ ὃν ἂν τῶν πολιτῶν εἴπῃ τις, εὐθέως φατὲ καὶ θορυβεῖθ’ ὡς ὀρθῶς λέγει·", "st": "8.30"}, {"sp": "N", "t": "ἂν δὲ παρελθὼν λέγῃ τις τἀληθῆ, ὅτι “ληρεῖτ’, Ἀθηναῖοι· πάντων τῶν κακῶν καὶ τῶν πραγμάτων τούτων Φίλιππός ἐστ’ αἴτιος· εἰ γὰρ ἐκεῖνος ἦγεν ἡσυχίαν, οὐδὲν ἂν ἦν πρᾶγμα τῇ πόλει,” ὡς μὲν οὐκ ἀληθῆ ταῦτ’ ἐστὶν οὐκ ἔχετ’ ἀντιλέγειν, ἄχθεσθαι δέ μοι δοκεῖτε καὶ ὥσπερ ἀπολλύναι τι νομίζειν.", "st": "8.31"}, {"sp": "N", "t": "αἴτιον δὲ τούτων (καί μοι πρὸς θεῶν, ὅταν εἵνεκα τοῦ βελτίστου λέγω, ἔστω παρρησία)· παρεσκευάκασιν ὑμᾶς τῶν πολιτευομένων ἔνιοι ἐν μὲν ταῖς ἐκκλησίαις φοβεροὺς καὶ χαλεπούς, ἐν δὲ ταῖς παρασκευαῖς ταῖς τοῦ πολέμου ῥᾳθύμους καὶ εὐκαταφρονήτους. ἂν μὲν οὖν τὸν αἴτιον εἴπῃ τις ὃν ἴσθ’ ὅτι λήψεσθε παρ’ ὑμῖν αὐτοῖς, φατὲ καὶ βούλεσθε· ἂν δὲ τοιοῦτον λέγῃ τις, ὃν κρατήσαντας τοῖς ὅπλοις, ἄλλως δ’ οὐκ ἔστιν κολάσαι, οὐκ ἔχετ’, οἶμαι, τί ποιήσετε, ἐξελεγχόμενοι δ’ ἄχθεσθε.", "st": "8.32"}, {"sp": "N", "t": "ἐχρῆν γάρ, ὦ ἄνδρες Ἀθηναῖοι, τοὐναντίον ἢ νῦν ἅπαντας τοὺς πολιτευομένους ἐν μὲν ταῖς ἐκκλησίαις πράους καὶ φιλανθρώπους ὑμᾶς ἐθίζειν εἶναι (πρὸς γὰρ ὑμᾶς αὐτοὺς καὶ τοὺς συμμάχους ἐν ταύταις ἐστὶ τὰ δίκαια), ἐν δὲ ταῖς παρασκευαῖς ταῖς τοῦ πολέμου φοβεροὺς καὶ χαλεποὺς ἐπιδεικνύναι· πρὸς γὰρ τοὺς ἐχθροὺς καὶ τοὺς ἀντιπάλους ἐκεῖνός ἐσθ’ ἁγών.", "st": "8.33"}, {"sp": "N", "t": "νῦν δὲ δημαγωγοῦντες ὑμᾶς καὶ χαριζόμενοι καθ’ ὑπερβολὴν οὕτω διατεθήκασιν, ὥστ’ ἐν μὲν ταῖς ἐκκλησίαις τρυφᾶν καὶ κολακεύεσθαι πάντα πρὸς ἡδονὴν ἀκούοντας, ἐν δὲ τοῖς πράγμασι καὶ τοῖς γιγνομένοις περὶ τῶν ἐσχάτων ἤδη κινδυνεύειν. φέρε γὰρ πρὸς Διός, εἰ λόγον ὑμᾶς ἀπαιτήσειαν οἱ Ἕλληνες ὧν νυνὶ παρείκατε καιρῶν διὰ ῥᾳθυμίαν,", "st": "8.34"}, {"sp": "N", "t": "καὶ ἔροινθ’ ὑμᾶς, “ἄνδρες Ἀθηναῖοι, πέμπεθ’ ὡς ἡμᾶς ἑκάστοτε πρέσβεις, καὶ λέγεθ’ ὡς ἐπιβουλεύει Φίλιππος ἡμῖν καὶ πᾶσι τοῖς Ἕλλησι, καὶ ὡς φυλάττεσθαι δεῖ τὸν ἄνθρωπον, καὶ πάντα τὰ τοιαυτί;” ἀνάγκη φάσκειν καὶ ὁμολογεῖν· ποιοῦμεν γὰρ ταῦτα. “εἶτ’, ὦ πάντων ἀνθρώπων φαυλότατοι, δέκα μῆνας ἀπογενομένου τἀνθρώπου καὶ νόσῳ καὶ χειμῶνι καὶ πολέμοις ἀποληφθέντος ὥστε μὴ ἂν δύνασθαι ἐπανελθεῖν οἴκαδε,”", "st": "8.35"}, {"sp": "N", "t": "“οὔτε τὴν Εὔβοιαν ἠλευθερώσατε, οὔτε τῶν ὑμετέρων αὐτῶν οὐδὲν ἐκομίσασθε, ἀλλ’ ἐκεῖνος μὲν ὑμῶν οἴκοι μενόντων, σχολὴν ἀγόντων, ὑγιαινόντων (εἰ δὴ τοὺς τὰ τοιαῦτα ποιοῦντας ὑγιαίνειν φήσαιμεν), δύ’ ἐν Εὐβοίᾳ κατέστησε τυράννους, τὸν μὲν ἀπαντικρὺ τῆς Ἀττικῆς ἐπιτειχίσας, τὸν δ’ ἐπὶ Σκίαθον,”", "st": "8.36"}, {"sp": "N", "t": "“ὑμεῖς δ’ οὐδὲ ταῦτ’ ἀπελύσασθε, εἰ μηδὲν ἄλλ’ ἐβούλεσθε, ἀλλ’ εἰάκατε; ἀφέστατε δῆλον ὅτι αὐτῷ, καὶ φανερὸν πεποιήκατε ὅτι οὐδ’ ἂν δεκάκις ἀποθάνῃ, οὐδὲν μᾶλλον κινήσεσθε. τί οὖν πρεσβεύετε καὶ κατηγορεῖτε καὶ πράγμαθ’ ἡμῖν παρέχετε;” ἂν ταῦτα λέγωσι, τί ἐροῦμεν ἢ τί φήσομεν, Ἀθηναῖοι; ἐγὼ μὲν γὰρ οὐχ ὁρῶ.", "st": "8.37"}, {"sp": "N", "t": "εἰσὶ τοίνυν τινὲς οἳ τότ’ ἐξελέγχειν τὸν παριόντ’ οἴονται, ἐπειδὰν ἐρωτήσωσι “τί οὖν χρὴ ποιεῖν;” οἷς ἐγὼ μὲν τὸ δικαιότατον καὶ ἀληθέστατον τοῦτ’ ἀποκρινοῦμαι, ταῦτα μὴ ποιεῖν ἃ νυνὶ ποιεῖτε, οὐ μὴν ἀλλὰ καὶ καθ’ ἕκαστον ἀκριβῶς ἐρῶ. καὶ ὅπως, ὥσπερ ἐρωτῶσι προθύμως, οὕτω καὶ ποιεῖν ἐθελήσουσιν.", "st": "8.38"}, {"sp": "N", "t": "πρῶτον μέν, ὦ ἄνδρες Ἀθηναῖοι, τοῦτο παρ’ ὑμῖν αὐτοῖς βεβαίως γνῶναι, ὅτι τῇ πόλει Φίλιππος πολεμεῖ καὶ τὴν εἰρήνην λέλυκεν (καὶ παύσασθε περὶ τούτου κατηγοροῦντες ἀλλήλων) καὶ κακόνους μέν ἐστι καὶ ἐχθρὸς ὅλῃ τῇ πόλει καὶ τῷ τῆς πόλεως ἐδάφει,", "st": "8.39"}, {"sp": "N", "t": "προσθήσω δὲ καὶ τοῖς ἐν τῇ πόλει πᾶσιν ἀνθρώποις, καὶ τοῖς μάλιστ’ οἰομένοις αὐτῷ χαρίζεσθαι (εἰ δὲ μή, σκεψάσθων Εὐθυκράτη καὶ Λασθένη τοὺς Ὀλυνθίους, οἳ δοκοῦντες οἰκειότατ’ αὐτῷ διακεῖσθαι, ἐπειδὴ τὴν πόλιν προὔδοσαν, πάντων κάκιστ’ ἀπολώλασιν), οὐδενὶ μέντοι μᾶλλον ἢ τῇ πολιτείᾳ πολεμεῖ οὐδ’ ἐπιβουλεύει, καὶ σκοπεῖ μᾶλλον οὐδὲ ἓν τῶν πάντων, ἢ πῶς ταύτην καταλύσει.", "st": "8.40"}, {"sp": "N", "t": "καὶ τοῦτ’ εἰκότως τρόπον τινὰ πράττει· οἶδεν γὰρ ἀκριβῶς ὅτι οὐδ’ ἂν πάντων τῶν ἄλλων γένηται κύριος, οὐδὲν ἔστ’ αὐτῷ βεβαίως ἔχειν, ἕως ἂν ὑμεῖς δημοκρατῆσθε, ἀλλ’ ἐάν ποτε συμβῇ τι πταῖσμα, ἃ πολλὰ γένοιτ’ ἂν ἀνθρώπῳ, ἥξει πάντα τὰ νῦν συμβεβιασμένα καὶ καταφεύξεται πρὸς ὑμᾶς·", "st": "8.41"}, {"sp": "N", "t": "ἐστὲ γὰρ ὑμεῖς οὐκ αὐτοὶ πλεονεκτῆσαι καὶ κατασχεῖν ἀρχὴν εὖ πεφυκότες, ἀλλ’ ἕτερον λαβεῖν κωλῦσαι καὶ ἔχοντ’ ἀφελέσθαι δεινοί, καὶ ὅλως ἐνοχλῆσαι τοῖς ἄρχειν βουλομένοις καὶ πάντας ἀνθρώπους εἰς ἐλευθερίαν ἐξελέσθαι ἕτοιμοι. οὔκουν βούλεται τοῖς ἑαυτοῦ καιροῖς τὴν παρ’ ὑμῶν ἐλευθερίαν ἐφεδρεύειν, οὐδὲ πολλοῦ δεῖ, οὐ κακῶς οὐδ’ ἀργῶς ταῦτα λογιζόμενος.", "st": "8.42"}, {"sp": "N", "t": "πρῶτον μὲν δὴ τοῦτο δεῖ, ἐχθρὸν ὑπειληφέναι τῆς πολιτείας καὶ τῆς δημοκρατίας ἀδιάλλακτον ἐκεῖνον· εἰ γὰρ μὴ τοῦτο πεισθήσεσθε ταῖς ψυχαῖς, οὐκ ἐθελήσεθ’ ὑπὲρ τῶν πραγμάτων σπουδάζειν· δεύτερον δ’ εἰδέναι σαφῶς ὅτι πάνθ’ ὅσα πραγματεύεται καὶ κατασκευάζεται νῦν, ἐπὶ τὴν ἡμετέραν πόλιν παρασκευάζεται, καὶ ὅπου τις ἐκεῖνον ἀμύνεται, ἐνταῦθ’ ὑπὲρ ἡμῶν ἀμύνεται.", "st": "8.43"}, {"sp": "N", "t": "οὐ γὰρ οὕτω γ’ εὐήθης οὐδεὶς ὃς ὑπολαμβάνει τὸν Φίλιππον τῶν μὲν ἐν Θρᾴκῃ κακῶν (τί γὰρ ἂν ἄλλο τις εἴποι Δρογγίλον καὶ Καβύλην καὶ Μάστειραν καὶ ἃ νῦν ἐξαιρεῖ [καὶ κατασκευάζεται];) τούτων μὲν ἐπιθυμεῖν καὶ ὑπὲρ τοῦ ταῦτα λαβεῖν καὶ πόνους καὶ χειμῶνας καὶ τοὺς ἐσχάτους κινδύνους ὑπομένειν,", "st": "8.44"}, {"sp": "N", "t": "τῶν δ’ Ἀθηναίων λιμένων καὶ νεωρίων καὶ τριήρων καὶ τῶν ἔργων τῶν ἀργυρείων καὶ τοσούτων προσόδων οὐκ ἐπιθυμεῖν, ἀλλὰ ταῦτα μὲν ὑμᾶς ἐάσειν ἔχειν, ὑπὲρ δὲ τῶν μελινῶν καὶ τῶν ὀλυρῶν τῶν ἐν τοῖς Θρᾳκίοις σιροῖς ἐν τῷ βαράθρῳ χειμάζειν. οὐκ ἔστι ταῦτα, ἀλλὰ κἀκεῖν’ ὑπὲρ τοῦ τούτων γενέσθαι κύριος καὶ τἄλλα πάντα πραγματεύεται.", "st": "8.45"}, {"sp": "N", "t": "τί οὖν εὖ φρονούντων ἀνθρώπων ἐστίν; εἰδότας ταῦτα καὶ ἐγνωκότας τὴν μὲν ὑπερβάλλουσαν καὶ ἀνήκεστον ταύτην ῥᾳθυμίαν ἀποθέσθαι, χρήματα δ’ εἰσφέρειν καὶ τοὺς συμμάχους ἀξιοῦν, καὶ ὅπως τὸ συνεστηκὸς τοῦτο συμμενεῖ στράτευμ’ ὁρᾶν καὶ πράττειν, ἵν’ ὥσπερ ἐκεῖνος ἕτοιμον ἔχει δύναμιν τὴν ἀδικήσουσαν καὶ καταδουλωσομένην ἅπαντας τοὺς Ἕλληνας, οὕτω τὴν σώσουσαν ὑμεῖς καὶ βοηθήσουσαν ἅπασιν ἕτοιμον ἔχητε.", "st": "8.46"}, {"sp": "N", "t": "οὐ γὰρ ἔστι βοηθείαις χρωμένους οὐδέποτ’ οὐδὲν τῶν δεόντων πρᾶξαι, ἀλλὰ κατασκευάσαντας δεῖ δύναμιν, καὶ τροφὴν ταύτῃ πορίσαντας καὶ ταμίας καὶ δημοσίους, καὶ ὅπως ἔνι τὴν τῶν χρημάτων φυλακὴν ἀκριβεστάτην γενέσθαι, οὕτω ποιήσαντας, τὸν μὲν τῶν χρημάτων λόγον παρὰ τούτων λαμβάνειν, τὸν δὲ τῶν ἔργων παρὰ τοῦ στρατηγοῦ. κἂν οὕτω ποιήσητε καὶ ταῦτ’ ἐθελήσηθ’ ὡς ἀληθῶς, ἄγειν εἰρήνην δικαίαν καὶ μένειν ἐπὶ τῆς αὑτοῦ Φίλιππον ἀναγκάσετε, οὗ μεῖζον οὐδὲν ἂν γένοιτ’ ἀγαθόν, ἢ πολεμήσετ’ ἐξ ἴσου.", "st": "8.47"}, {"sp": "N", "t": "εἰ δέ τῳ δοκεῖ ταῦτα καὶ δαπάνης μεγάλης καὶ πόνων πολλῶν καὶ πραγματείας εἶναι, καὶ μάλ’ ὀρθῶς δοκεῖ· ἀλλ’ ἐὰν λογίσηται τὰ τῇ πόλει μετὰ ταῦτα γενησόμενα, ἂν ταῦτα μὴ ’θέλῃ, εὑρήσει λυσιτελοῦν τὸ ἑκόντας ποιεῖν τὰ δέοντα.", "st": "8.48"}, {"sp": "N", "t": "εἰ μὲν γάρ ἐστί τις ἐγγυητὴς θεῶν (οὐ γὰρ ἀνθρώπων γ’ οὐδεὶς ἂν γένοιτ’ ἀξιόχρεως τηλικούτου πράγματος) ὡς, ἐὰν ἄγηθ’ ἡσυχίαν καὶ ἅπαντα προῆσθε, οὐκ ἐπ’ αὐτοὺς ὑμᾶς τελευτῶν ἐκεῖνος ἥξει, αἰσχρὸν μὲν νὴ τὸν Δία καὶ πάντας θεοὺς καὶ ἀνάξιον ὑμῶν καὶ τῶν ὑπαρχόντων τῇ πόλει καὶ πεπραγμένων τοῖς προγόνοις, τῆς ἰδίας ἕνεκα ῥᾳθυμίας τοὺς ἄλλους πάντας Ἕλληνας εἰς δουλείαν προέσθαι, καὶ ἔγωγ’ αὐτὸς μὲν τεθνάναι μᾶλλον ἂν ἢ ταῦτ’ εἰρηκέναι βουλοίμην· οὐ μὴν ἀλλ’ εἴ τις ἄλλος λέγει καὶ ὑμᾶς πείθει, ἔστω, μὴ ἀμύνεσθε, ἅπαντα πρόεσθε.", "st": "8.49"}, {"sp": "N", "t": "εἰ δὲ μηδενὶ τοῦτο δοκεῖ, τοὐναντίον δὲ πρόϊσμεν ἅπαντες, ὅτι ὅσῳ ἂν πλειόνων ἐάσωμεν ἐκεῖνον γενέσθαι κύριον, τοσούτῳ χαλεπωτέρῳ καὶ ἰσχυροτέρῳ χρησόμεθ’ ἐχθρῷ, ποῖ ἀναδυόμεθα; ἢ τί μέλλομεν; ἢ πότ’, ὦ ἄνδρες Ἀθηναῖοι, τὰ δέοντα ποιεῖν ἐθελήσομεν;", "st": "8.50"}, {"sp": "N", "t": "ὅταν νὴ Δί’ ἀναγκαῖον ᾖ. ἀλλ’ ἣν μὲν ἄν τις ἐλευθέρων ἀνθρώπων ἀνάγκην εἴποι, οὐ μόνον ἤδη πάρεστιν, ἀλλὰ καὶ πάλαι παρελήλυθε, τὴν δὲ τῶν δούλων ἀπεύχεσθαι δήπου μὴ γενέσθαι δεῖ. διαφέρει δὲ τί; ὅτι ἐστὶν ἐλευθέρῳ μὲν ἀνθρώπῳ μεγίστη ἀνάγκη ἡ ὑπὲρ τῶν γιγνομένων αἰσχύνη, καὶ μείζω ταύτης οὐκ οἶδ’ ἥντιν’ ἂν εἴποιμεν· δούλῳ δὲ πληγαὶ καὶ ὁ τοῦ σώματος αἰκισμός, ἃ μήτε γένοιτο οὔτε λέγειν ἄξιον.", "st": "8.51"}, {"sp": "N", "t": "πάντα τοίνυν τἄλλ’ εἰπὼν ἂν ἡδέως, καὶ δείξας ὃν τρόπον ὑμᾶς ἔνιοι καταπολιτεύονται, τὰ μὲν ἄλλ’ ἐάσω· ἀλλ’ ἐπειδάν τι τῶν πρὸς Φίλιππον ἐμπέσῃ, εὐθὺς ἀναστάς τις λέγει τὸ τὴν εἰρήνην ἄγειν ὡς ἀγαθὸν καὶ τὸ τρέφειν δύναμιν μεγάλην ὡς χαλεπόν, καὶ “διαρπάζειν τινὲς τὰ χρήματα βούλονται,” καὶ τοιούτους λόγους, ἐξ ὧν ἀναβάλλουσι μὲν ὑμᾶς, ἡσυχίαν δὲ ποιοῦσιν ἐκείνῳ πράττειν ὅ τι βούλεται.", "st": "8.52"}, {"sp": "N", "t": "ἐκ δὲ τούτων περιγίγνεται, ὑμῖν μὲν ἡ σχολὴ καὶ τὸ μηδὲν ἤδη ποιεῖν, ἃ δέδοιχ’ ὅπως μήποθ’ ἡγήσεσθ’ ἐπὶ πολλῷ γεγενῆσθαι, τούτοις δ’ αἱ χάριτες καὶ ὁ μισθὸς ὁ τούτων. ἐγὼ δ’ οἴομαι τὴν μὲν εἰρήνην ἄγειν οὐχ ὑμᾶς δεῖν πείθειν, οἳ πεπεισμένοι κάθησθε, ἀλλὰ τὸν τὰ τοῦ πολέμου πράττοντα· ἂν γὰρ ἐκεῖνος πεισθῇ, τά γ’ ἀφ’ ὑμῶν ὑπάρχει·", "st": "8.53"}, {"sp": "N", "t": "νομίζειν δ’ εἶναι χαλεπὰ οὐχ ὅσ’ ἂν εἰς σωτηρίαν δαπανῶμεν, ἀλλ’ ἃ πεισόμεθα, ἂν ταῦτα μὴ ’θέλωμεν ποιεῖν· καὶ τὸ “διαρπασθήσεται τὰ χρήματα” τῷ φυλακὴν εἰπεῖν δι’ ἧς σωθήσεται κωλύειν, οὐχὶ τῷ τοῦ συμφέροντος ἀφεστάναι.", "st": "8.54"}, {"sp": "N", "t": "καίτοι ἔγωγ’ ἀγανακτῶ καὶ αὐτὸ τοῦτ’, ὦ ἄνδρες Ἀθηναῖοι, εἰ τὰ μὲν χρήματα λυπεῖ τινὰς ὑμῶν εἰ διαρπασθήσεται, ἃ καὶ φυλάττειν καὶ κολάζειν τοὺς ἀδικοῦντας ἐφ’ ὑμῖν ἐστι, τὴν δ’ Ἑλλάδα πᾶσαν οὑτωσὶ Φίλιππος ἐφεξῆς ἁρπάζων οὐ λυπεῖ, καὶ ταῦτ’ ἐφ’ ὑμᾶς ἁρπάζων.", "st": "8.55"}, {"sp": "N", "t": "τί ποτ’ οὖν ἐστι τὸ αἴτιον, ὦ ἄνδρες Ἀθηναῖοι, τὸ τὸν μὲν οὕτω φανερῶς στρατεύοντα, ἀδικοῦντα, πόλεις καταλαμβάνοντα, μηδένα τούτων πώποτ’ εἰπεῖν ὡς πόλεμον ποιεῖ, τοὺς δὲ μὴ ἐπιτρέπειν μηδὲ προΐεσθαι ταῦτα συμβουλεύοντας, τούτους τὸν πόλεμον ποιήσειν αἰτιᾶσθαι;", "st": "8.56"}, {"sp": "N", "t": "ἐγὼ διδάξω· ὅτι τὴν ὀργὴν ἣν εἰκός ἐστι γενέσθαι παρ’ ὑμῶν, ἄν τι λυπῆσθε τῷ πολέμῳ, εἰς τοὺς ὑπὲρ ὑμῶν λέγοντας τὰ βέλτιστα τρέψαι βούλονται, ἵνα τούτους κρίνητε, μὴ Φίλιππον ἀμύνησθε, καὶ κατηγορῶσιν αὐτοί, μὴ δίκην δῶσιν ὧν ποιοῦσι νῦν. τοῦτ’ αὐτοῖς δύναται τὸ λέγειν ὡς ἄρα βούλονται πόλεμόν τινες ποιῆσαι παρ’ ὑμῖν, καὶ περὶ τούτου ἡ διαδικασία αὕτη ἐστίν.", "st": "8.57"}, {"sp": "N", "t": "ἐγὼ δ’ οἶδ’ ἀκριβῶς ὅτι οὐ γράψαντος Ἀθηναίων οὐδενός πω πόλεμον, καὶ ἄλλα πολλὰ Φίλιππος ἔχει τῶν τῆς πόλεως καὶ νῦν εἰς Καρδίαν πέπομφε βοήθειαν. εἰ μέντοι βουλόμεθ’ ἡμεῖς μὴ προσποιεῖσθαι πολεμεῖν αὐτὸν ἡμῖν, ἀνοητότατος πάντων ἂν εἴη τῶν ὄντων ἀνθρώπων, εἰ τοῦτ’ ἐξελέγχοι.", "st": "8.58"}, {"sp": "N", "t": "ἀλλ’ ἐπειδὰν ἐπ’ αὐτοὺς ἡμᾶς ἴῃ, τί φήσομεν; ἐκεῖνος μὲν γὰρ οὐ πολεμεῖν, ὥσπερ οὐδ’ Ὠρείταις, τῶν στρατιωτῶν ὄντων ἐν τῇ χώρᾳ, οὐδὲ Φεραίοις πρότερον, πρὸς τὰ τείχη προσβάλλων αὐτῶν, οὐδ’ Ὀλυνθίοις ἐξ ἀρχῆς, ἕως ἐν αὐτῇ τῇ χώρᾳ τὸ στράτευμα παρῆν ἔχων. ἢ καὶ τότε τοὺς ἀμύνεσθαι κελεύοντας πόλεμον ποιεῖν φήσομεν; οὐκοῦν ὑπόλοιπον δουλεύειν· οὐ γὰρ ἄλλο γ’ οὐδέν ἐστι μεταξὺ τοῦ μήτ’ ἀμύνεσθαι μήτ’ ἄγειν ἡσυχίαν ἐᾶσθαι.", "st": "8.59"}, {"sp": "N", "t": "καὶ μὴν οὐχ ὑπὲρ τῶν ἴσων ὑμῖν καὶ τοῖς ἄλλοις ἔσθ’ ὁ κίνδυνος· οὐ γὰρ ὑφ’ αὑτῷ τὴν πόλιν ποιήσασθαι βούλεται Φίλιππος, ἀλλ’ ὅλως ἀνελεῖν. οἶδεν γὰρ ἀκριβῶς ὅτι δουλεύειν μὲν ὑμεῖς οὔτ’ ἐθελήσετε, οὔτ’, ἂν ἐθελήσητε, ἐπιστήσεσθε (ἄρχειν γὰρ εἰώθατε), πράγματα δ’ αὐτῷ παρασχεῖν, ἂν καιρὸν λάβητε, πλείω τῶν ἄλλων ἀνθρώπων ἁπάντων δυνήσεσθε.", "st": "8.60"}, {"sp": "N", "t": "ὡς οὖν ὑπὲρ τῶν ἐσχάτων ὄντος τοῦ ἀγῶνος, οὕτω προσήκει γιγνώσκειν, καὶ τοὺς πεπρακότας αὑτοὺς ἐκείνῳ μισεῖν κἀποτυμπανίσαι· οὐ γὰρ ἔστιν, οὐκ ἔστι τῶν ἔξω τῆς πόλεως ἐχθρῶν κρατῆσαι, πρὶν ἂν τοὺς ἐν αὐτῇ τῇ πόλει κολάσητ’ ἐχθρούς.", "st": "8.61"}, {"sp": "N", "t": "πόθεν οἴεσθε νῦν αὐτὸν ὑβρίζειν ὑμᾶς (οὐδὲν γὰρ ἄλλ’ ἔμοιγε δοκεῖ ποιεῖν ἢ τοῦτο) καὶ τοὺς μὲν ἄλλους εὖ ποιοῦντα, εἰ μηδὲν ἄλλο, ἐξαπατᾶν, ὑμῖν δ’ ἀπειλεῖν ἤδη; οἷον Θετταλοὺς πολλὰ δοὺς ὑπηγάγετ’ εἰς τὴν νῦν παροῦσαν δουλείαν· οὐδ’ ἂν εἰπεῖν δύναιτ’ οὐδεὶς ὅσα τοὺς ταλαιπώρους Ὀλυνθίους πρότερον δοὺς Ποτείδαιαν ἐξηπάτησε καὶ πόλλ’ ἕτερα·", "st": "8.62"}, {"sp": "N", "t": "Θηβαίους νῦν ὑπάγει τὴν Βοιωτίαν αὐτοῖς παραδοὺς καὶ ἀπαλλάξας πολέμου πολλοῦ καὶ χαλεποῦ· ὥστε καρπωσάμενοί τιν’ ἕκαστοι τούτων πλεονεξίαν οἱ μὲν ἤδη πεπόνθασιν ἃ δὴ πάντες ἴσασιν, οἱ δ’ ὅταν ποτὲ συμβῇ πείσονται. ὑμεῖς δ’ ὧν μὲν ἀπεστέρησθε, σιωπῶ· ἀλλ’ ἐν αὐτῷ τῷ τὴν εἰρήνην ποιήσασθαι, πόσ’ ἐξηπάτησθε, πόσων ἀπεστέρησθε.", "st": "8.63"}, {"sp": "N", "t": "οὐχὶ Φωκέας, οὐ Πύλας, οὐχὶ τἀπὶ Θρᾴκης, Δορίσκον, Σέρριον, τὸν Κερσοβλέπτην αὐτόν; οὐ νῦν τὴν πόλιν τὴν Καρδιανῶν ἔχει καὶ ὁμολογεῖ; τί ποτ’ οὖν ἐκείνως τοῖς ἄλλοις καὶ οὐ τὸν αὐτὸν τρόπον ὑμῖν προσφέρεται; ὅτι ἐν μόνῃ τῶν πασῶν πόλεων τῇ ὑμετέρᾳ ἄδει’ ὑπὲρ τῶν ἐχθρῶν λέγειν δέδοται, καὶ λαβόντα χρήματ’ αὐτὸν ἀσφαλές ἐστι λέγειν παρ’ ὑμῖν, κἂν ἀφῃρημένοι τὰ ὑμέτερ’ αὐτῶν ἦτε. οὐκ ἦν ἀσφαλὲς λέγειν ἐν Ὀλύνθῳ τὰ Φιλίππου μὴ σὺν εὖ πεπονθότων τῶν πολλῶν Ὀλυνθίων τῷ Ποτείδαιαν καρποῦσθαι·", "st": "8.64"}, {"sp": "N", "t": "οὐκ ἦν ἀσφαλὲς λέγειν ἐν Θετταλίᾳ τὰ Φιλίππου μὴ σὺν εὖ πεπονθότος τοῦ πλήθους τοῦ Θετταλῶν τῷ τοὺς τυράννους ἐκβαλεῖν Φίλιππον αὐτοῖς καὶ τὴν Πυλαίαν ἀποδοῦναι· οὐκ ἦν ἐν Θήβαις ἀσφαλές, πρὶν τὴν Βοιωτίαν ἀπέδωκε καὶ τοὺς Φωκέας ἀνεῖλεν.", "st": "8.65"}, {"sp": "N", "t": "ἀλλ’ Ἀθήνησιν, οὐ μόνον Ἀμφίπολιν καὶ τὴν Καρδιανῶν χώραν ἀπεστερηκότος Φιλίππου, ἀλλὰ καὶ κατασκευάζοντος ὑμῖν ἐπιτείχισμα τὴν Εὔβοιαν καὶ νῦν ἐπὶ Βυζάντιον παριόντος, ἀσφαλές ἐστι λέγειν ὑπὲρ Φιλίππου. καὶ γάρ τοι τούτων μὲν ἐκ πτωχῶν ἔνιοι ταχὺ πλούσιοι γίγνονται, καὶ ἐξ ἀνωνύμων καὶ ἀδόξων ἔνδοξοι καὶ γνώριμοι, ὑμεῖς δὲ τοὐναντίον ἐκ μὲν ἐνδόξων ἄδοξοι, ἐκ δ’ εὐπόρων ἄποροι· πόλεως γὰρ ἔγωγε πλοῦτον ἡγοῦμαι συμμάχους, πίστιν, εὔνοιαν, ὧν πάντων ἔσθ’ ὑμεῖς ἄποροι.", "st": "8.66"}, {"sp": "N", "t": "ἐκ δὲ τοῦ τούτων ὀλιγώρως ἔχειν καὶ ἐᾶν ταῦτα φέρεσθαι ὁ μὲν εὐδαίμων καὶ μέγας καὶ φοβερὸς πᾶσιν Ἕλλησι καὶ βαρβάροις, ὑμεῖς δ’ ἔρημοι καὶ ταπεινοί, τῇ τῶν ὠνίων ἀφθονίᾳ λαμπροί, τῇ δ’ ὧν προσῆκε παρασκευῇ καταγέλαστοι. οὐ τὸν αὐτὸν δὲ τρόπον περί θ’ ὑμῶν καὶ περὶ αὑτῶν ἐνίους τῶν λεγόντων ὁρῶ βουλευομένους· ὑμᾶς μὲν γὰρ ἡσυχίαν ἄγειν φασὶ δεῖν, κἄν τις ὑμᾶς ἀδικῇ, αὐτοὶ δ’ οὐ δύνανται παρ’ ὑμῖν ἡσυχίαν ἄγειν οὐδενὸς αὐτοὺς ἀδικοῦντος.", "st": "8.67"}, {"sp": "N", "t": "εἶτα φησὶν ὃς ἂν τύχῃ παρελθών “οὐ γὰρ ἐθέλεις γράφειν, οὐδὲ κινδυνεύειν, ἀλλ’ ἄτολμος εἶ καὶ μαλακός.” ἐγὼ δὲ θρασὺς μὲν καὶ βδελυρὸς καὶ ἀναιδὴς οὔτ’ εἰμὶ μήτε γενοίμην, ἀνδρειότερον μέντοι πολλῶν πάνυ τῶν ἰταμῶς πολιτευομένων παρ’ ὑμῖν ἐμαυτὸν ἡγοῦμαι.", "st": "8.68"}, {"sp": "N", "t": "ὅστις μὲν γάρ, ὦ ἄνδρες Ἀθηναῖοι, παριδὼν ἃ συνοίσει τῇ πόλει, κρίνει, δημεύει, δίδωσι, κατηγορεῖ, οὐδεμιᾷ ταῦτ’ ἀνδρείᾳ ποιεῖ, ἀλλ’ ἔχων ἐνέχυρον τῆς αὑτοῦ σωτηρίας τὸ πρὸς χάριν ὑμῖν λέγειν καὶ πολιτεύεσθαι, ἀσφαλῶς θρασύς ἐστιν· ὅστις δ’ ὑπὲρ τοῦ βελτίστου πολλὰ τοῖς ὑμετέροις ἐναντιοῦται βουλήμασι, καὶ μηδὲν λέγει πρὸς χάριν ἀλλὰ τὸ βέλτιστον ἀεί, καὶ τὴν τοιαύτην πολιτείαν προαιρεῖται ἐν ᾗ πλειόνων ἡ τύχη κυρία γίγνεται ἢ οἱ λογισμοί, τούτων δ’ ἀμφοτέρων ἑαυτὸν ὑπεύθυνον ὑμῖν παρέχει, οὗτός ἐστ’ ἀνδρεῖος,", "st": "8.69"}, {"sp": "N", "t": "καὶ χρήσιμός γε πολίτης ὁ τοιοῦτός ἐστιν, οὐχ οἱ τῆς παρ’ ἡμέραν χάριτος τὰ μέγιστα τῆς πόλεως ἀπολωλεκότες, οὓς ἐγὼ τοσούτου δέω ζηλοῦν ἢ νομίζειν ἀξίους πολίτας τῆς πόλεως εἶναι, ὥστ’ εἴ τις ἔροιτό με, “εἰπέ μοι, σὺ δὲ δὴ τί τὴν πόλιν ἡμῖν ἀγαθὸν πεποίηκας;” ἔχων, ὦ ἄνδρες Ἀθηναῖοι, καὶ τριηραρχίας εἰπεῖν καὶ χορηγίας καὶ χρημάτων εἰσφορὰς καὶ λύσεις αἰχμαλώτων καὶ τοιαύτας ἄλλας φιλανθρωπίας,", "st": "8.70"}, {"sp": "N", "t": "οὐδὲν ἂν τούτων εἴποιμι, ἀλλ’ ὅτι τῶν τοιούτων πολιτευμάτων οὐδὲν πολιτεύομαι, ἀλλὰ δυνάμενος ἂν ἴσως, ὥσπερ καὶ ἕτεροι, καὶ κατηγορεῖν καὶ χαρίζεσθαι καὶ δημεύειν καὶ τἄλλ’ ἃ ποιοῦσιν οὗτοι ποιεῖν, οὐδ’ ἐφ’ ἓν τούτων πώποτ’ ἐμαυτὸν ἔταξα, οὐδὲ προήχθην οὔθ’ ὑπὸ κέρδους οὔθ’ ὑπὸ φιλοτιμίας, ἀλλὰ διαμένω λέγων ἐξ ὧν ἐγὼ μὲν πολλῶν ἐλάττων εἰμὶ παρ’ ὑμῖν, ὑμεῖς δ’, εἰ πείσεσθέ μοι, μείζους ἂν εἴητε· οὕτω γὰρ ἴσως ἀνεπίφθονον εἰπεῖν.", "st": "8.71"}, {"sp": "N", "t": "οὐδ’ ἔμοιγε δοκεῖ δικαίου τοῦτ’ εἶναι πολίτου, τοιαῦτα πολιτεύμαθ’ εὑρίσκειν ἐξ ὧν ἐγὼ μὲν πρῶτος ὑμῶν ἔσομαι εὐθέως, ὑμεῖς δὲ τῶν ἄλλων ὕστατοι· ἀλλὰ συναυξάνεσθαι δεῖ τὴν πόλιν τοῖς τῶν ἀγαθῶν πολιτῶν πολιτεύμασι, καὶ τὸ βέλτιστον ἀεί, μὴ τὸ ῥᾷστον ἅπαντας λέγειν· ἐπ’ ἐκεῖνο μὲν γὰρ ἡ φύσις αὐτὴ βαδιεῖται, ἐπὶ τοῦτο δὲ τῷ λόγῳ δεῖ προάγεσθαι διδάσκοντα τὸν ἀγαθὸν πολίτην.", "st": "8.72"}, {"sp": "N", "t": "ἤδη τοίνυν τινὸς ἤκουσα τοιοῦτόν τι λέγοντος, ὡς ἄρ’ ἐγὼ λέγω μὲν ἀεὶ τὰ βέλτιστα, ἔστιν δ’ οὐδὲν ἀλλ’ ἢ λόγοι τὰ παρ’ ἐμοῦ, δεῖ δ’ ἔργων τῇ πόλει καὶ πράξεώς τινος. ἐγὼ δ’ ὡς ἔχω περὶ τούτων, λέξω πρὸς ὑμᾶς καὶ οὐκ ἀποκρύψομαι. οὐδ’ εἶναι νομίζω τοῦ συμβουλεύοντος ὑμῖν ἔργον οὐδὲν πλὴν εἰπεῖν τὰ βέλτιστα. καὶ τοῦθ’ ὅτι τοῦτον ἔχει τὸν τρόπον ῥᾳδίως οἶμαι δείξειν.", "st": "8.73"}, {"sp": "N", "t": "ἴστε γὰρ δήπου τοῦθ’ ὅτι Τιμόθεός ποτ’ ἐκεῖνος ἐν ὑμῖν ἐδημηγόρησεν ὡς δεῖ βοηθεῖν καὶ τοὺς Εὐβοέας σῴζειν, ὅτε Θηβαῖοι κατεδουλοῦντ’ αὐτούς, καὶ λέγων εἶπεν οὕτω πως· “εἰπέ μοι, βουλεύεσθε,” ἔφη, “Θηβαίους ἔχοντες ἐν νήσῳ, τί χρήσεσθε καὶ τί δεῖ ποιεῖν; οὐκ ἐμπλήσετε τὴν θάλατταν, ὦ ἄνδρες Ἀθηναῖοι, τριήρων; οὐκ ἀναστάντες ἤδη πορεύσεσθ’ εἰς τὸν Πειραιᾶ;”", "st": "8.74"}, {"sp": "N", "t": "“οὐ καθέλξετε τὰς ναῦς;” οὐκοῦν εἶπε μὲν ταῦθ’ ὁ Τιμόθεος, ἐποιήσατε δ’ ὑμεῖς· ἐκ δὲ τούτων ἀμφοτέρων τὸ πρᾶγμ’ ἐπράχθη. εἰ δ’ ὁ μὲν εἶπεν ὡς οἷόν τε [τὰ] ἄριστα, ὥσπερ εἶπεν, ὑμεῖς δ’ ἀπερρᾳθυμήσατε καὶ μηδὲν ὑπηκούσατε, ἆρ’ ἂν ἦν γεγονός τι τῶν τότε συμβάντων τῇ πόλει; οὐχ οἷόν τε. οὕτω τοίνυν καὶ περὶ ὧν ἂν ἐγὼ λέγω καὶ περὶ ὧν ἂν ὁ δεῖν’ εἴπῃ, τὰ μὲν ἔργα παρ’ ὑμῶν αὐτῶν ζητεῖτε, τὰ δὲ βέλτιστα ἐπιστήμῃ λέγειν παρὰ τοῦ παριόντος.", "st": "8.75"}, {"sp": "N", "t": "ἐν κεφαλαίῳ δ’ ἃ λέγω φράσας καταβῆναι βούλομαι. χρήματ’ εἰσφέρειν φημὶ δεῖν· τὴν ὑπάρχουσαν δύναμιν συνέχειν, ἐπανορθοῦντας εἴ τι δοκεῖ μὴ καλῶς ἔχειν, μὴ ὅσοις ἄν τις αἰτιάσηται τὸ ὅλον καταλύοντας· πρέσβεις ἐκπέμπειν πανταχοῖ τοὺς διδάξοντας, νουθετήσοντας, πράξοντας· παρὰ πάντα ταῦτα τοὺς ἐπὶ τοῖς πράγμασι δωροδοκοῦντας κολάζειν καὶ μισεῖν πανταχοῦ, ἵν’ οἱ μέτριοι καὶ δικαίους αὑτοὺς παρέχοντες εὖ βεβουλεῦσθαι δοκῶσι καὶ τοῖς ἄλλοις καὶ ἑαυτοῖς.", "st": "8.76"}, {"sp": "N", "t": "ἂν οὕτω τοῖς πράγμασι χρῆσθε καὶ παύσησθ’ ὀλιγωροῦντες ἁπάντων, ἴσως ἄν, ἴσως καὶ νῦν ἔτι βελτίω γένοιτο. εἰ μέντοι καθεδεῖσθε, ἄχρι τοῦ θορυβῆσαι καὶ ἐπαινέσαι σπουδάζοντες, ἐὰν δὲ δέῃ τι ποιεῖν ἀναδυόμενοι, οὐχ ὁρῶ λόγον ὅστις ἄνευ τοῦ ποιεῖν ὑμᾶς ἃ προσήκει δυνήσεται τὴν πόλιν σῶσαι.", "st": "8.77"}, {"sp": "HDR", "t": "Κατὰ Φιλίππου Γʹ", "st": "9"}, {"sp": "N", "t": "πολλῶν, ὦ ἄνδρες Ἀθηναῖοι, λόγων γιγνομένων ὀλίγου δεῖν καθ’ ἑκάστην ἐκκλησίαν περὶ ὧν Φίλιππος, ἀφ’ οὗ τὴν εἰρήνην ἐποιήσατο, οὐ μόνον ὑμᾶς, ἀλλὰ καὶ τοὺς ἄλλους ἀδικεῖ, καὶ πάντων οἶδ’ ὅτι φησάντων γ’ ἄν, εἰ καὶ μὴ ποιοῦσι τοῦτο, καὶ λέγειν δεῖν καὶ πράττειν ὅπως ἐκεῖνος παύσεται τῆς ὕβρεως καὶ δίκην δώσει, εἰς τοῦθ’ ὑπηγμένα πάντα τὰ πράγματα καὶ προειμέν’ ὁρῶ, ὥστε δέδοικα μὴ βλάσφημον μὲν εἰπεῖν, ἀληθὲς δ’ ᾖ· εἰ καὶ λέγειν ἅπαντες ἐβούλονθ’ οἱ παριόντες καὶ χειροτονεῖν ὑμεῖς ἐξ ὧν ὡς φαυλότατ’ ἔμελλε τὰ πράγμαθ’ ἕξειν, οὐκ ἂν ἡγοῦμαι δύνασθαι χεῖρον ἢ νῦν διατεθῆναι.", "st": "9.1"}, {"sp": "N", "t": "πολλὰ μὲν οὖν ἴσως ἐστὶν αἴτια τούτων, καὶ οὐ παρ’ ἓν οὐδὲ δύ’ εἰς τοῦτο τὰ πράγματ’ ἀφῖκται, μάλιστα δ’, ἄνπερ ἐξετάζητ’ ὀρθῶς, εὑρήσετε διὰ τοὺς χαρίζεσθαι μᾶλλον ἢ τὰ βέλτιστα λέγειν προαιρουμένους, ὧν τινες μέν, ὦ ἄνδρες Ἀθηναῖοι, ἐν οἷς εὐδοκιμοῦσιν αὐτοὶ καὶ δύνανται, ταῦτα φυλάττοντες οὐδεμίαν περὶ τῶν μελλόντων πρόνοιαν ἔχουσιν, οὐκοῦν οὐδ’ ὑμᾶς οἴονται δεῖν ἔχειν, ἕτεροι δὲ τοὺς ἐπὶ τοῖς πράγμασιν ὄντας αἰτιώμενοι καὶ διαβάλλοντες οὐδὲν ἄλλο ποιοῦσιν ἢ ὅπως ἡ μὲν πόλις αὐτὴ παρ’ αὑτῆς δίκην λήψεται καὶ περὶ τοῦτ’ ἔσται, Φιλίππῳ δ’ ἐξέσται καὶ λέγειν καὶ πράττειν ὅ τι βούλεται.", "st": "9.2"}, {"sp": "N", "t": "αἱ δὲ τοιαῦται πολιτεῖαι συνήθεις μέν εἰσιν ὑμῖν, αἴτιαι δὲ τῶν κακῶν. ἀξιῶ δ’, ὦ ἄνδρες Ἀθηναῖοι, ἄν τι τῶν ἀληθῶν μετὰ παρρησίας λέγω, μηδεμίαν μοι διὰ τοῦτο παρ’ ὑμῶν ὀργὴν γενέσθαι. σκοπεῖτε γὰρ ὡδί. ὑμεῖς τὴν παρρησίαν ἐπὶ μὲν τῶν ἄλλων οὕτω κοινὴν οἴεσθε δεῖν εἶναι πᾶσι τοῖς ἐν τῇ πόλει, ὥστε καὶ τοῖς ξένοις καὶ τοῖς δούλοις αὐτῆς μεταδεδώκατε, καὶ πολλοὺς ἄν τις οἰκέτας ἴδοι παρ’ ἡμῖν μετὰ πλείονος ἐξουσίας ὅ τι βούλονται λέγοντας ἢ πολίτας ἐν ἐνίαις τῶν ἄλλων πόλεων, ἐκ δὲ τοῦ συμβουλεύειν παντάπασιν ἐξεληλάκατε.", "st": "9.3"}, {"sp": "N", "t": "εἶθ’ ὑμῖν συμβέβηκεν ἐκ τούτου ἐν μὲν ταῖς ἐκκλησίαις τρυφᾶν καὶ κολακεύεσθαι πάντα πρὸς ἡδονὴν ἀκούουσιν, ἐν δὲ τοῖς πράγμασι καὶ τοῖς γιγνομένοις περὶ τῶν ἐσχάτων ἤδη κινδυνεύειν. εἰ μὲν οὖν καὶ νῦν οὕτω διάκεισθε, οὐκ ἔχω τί λέγω· εἰ δ’ ἃ συμφέρει χωρὶς κολακείας ἐθελήσετ’ ἀκούειν, ἕτοιμος λέγειν. καὶ γὰρ εἰ πάνυ φαύλως τὰ πράγματ’ ἔχει καὶ πολλὰ προεῖται, ὅμως ἔστιν, ἐὰν ὑμεῖς τὰ δέοντα ποιεῖν βούλησθε, ἔτι πάντα ταῦτ’ ἐπανορθώσασθαι.", "st": "9.4"}, {"sp": "N", "t": "καὶ παράδοξον μὲν ἴσως ἐστὶν ὃ μέλλω λέγειν, ἀληθὲς δέ· τὸ χείριστον ἐν τοῖς παρεληλυθόσι, τοῦτο πρὸς τὰ μέλλοντα βέλτιστον ὑπάρχει. τί οὖν ἐστι τοῦτο; ὅτι οὔτε μικρὸν οὔτε μέγ’ οὐδὲν τῶν δεόντων ποιούντων ὑμῶν κακῶς τὰ πράγματ’ ἔχει, ἐπεί τοι, εἰ πάνθ’ ἃ προσῆκε πραττόντων οὕτως διέκειτο, οὐδ’ ἂν ἐλπὶς ἦν αὐτὰ γενέσθαι βελτίω. νῦν δὲ τῆς ῥᾳθυμίας τῆς ὑμετέρας καὶ τῆς ἀμελίας κεκράτηκε Φίλιππος, τῆς πόλεως δ’ οὐ κεκράτηκεν· οὐδ’ ἥττησθ’ ὑμεῖς, ἀλλ’ οὐδὲ κεκίνησθε.", "st": "9.5"}, {"sp": "N", "t": "εἰ μὲν οὖν ἅπαντες ὡμολογοῦμεν Φίλιππον τῇ πόλει πολεμεῖν καὶ τὴν εἰρήνην παραβαίνειν, οὐδὲν ἄλλ’ ἔδει τὸν παριόντα λέγειν καὶ συμβουλεύειν ἢ ὅπως ἀσφαλέστατα καὶ ῥᾷστ’ αὐτὸν ἀμυνούμεθα· ἐπειδὴ δ’ οὕτως ἀτόπως ἔνιοι διάκεινται, ὥστε πόλεις καταλαμβάνοντος ἐκείνου καὶ πολλὰ τῶν ὑμετέρων ἔχοντος καὶ πάντας ἀνθρώπους ἀδικοῦντος ἀνέχεσθαί τινων ἐν ταῖς ἐκκλησίαις λεγόντων πολλάκις ὡς ἡμῶν τινές εἰσιν οἱ ποιοῦντες τὸν πόλεμον, ἀνάγκη φυλάττεσθαι καὶ διορθοῦσθαι περὶ τούτου·", "st": "9.6"}, {"sp": "N", "t": "ἔστι γὰρ δέος μήποθ’ ὡς ἀμυνούμεθα γράψας τις καὶ συμβουλεύσας εἰς τὴν αἰτίαν ἐμπέσῃ τοῦ πεποιηκέναι τὸν πόλεμον. [ἐγὼ δὴ τοῦτο πρῶτον ἁπάντων λέγω καὶ διορίζομαι· εἰ ἐφ’ ἡμῖν ἐστι τὸ βουλεύεσθαι περὶ τοῦ πότερον εἰρήνην ἄγειν ἢ πολεμεῖν δεῖ …].", "st": "9.7"}, {"sp": "N", "t": "εἰ μὲν οὖν ἔξεστιν εἰρήνην ἄγειν τῇ πόλει καὶ ἐφ’ ἡμῖν ἐστι τοῦτο, ἵν’ ἐντεῦθεν ἄρξωμαι, φήμ’ ἔγωγ’ ἄγειν ἡμᾶς δεῖν, καὶ τὸν ταῦτα λέγοντα γράφειν καὶ πράττειν καὶ μὴ φενακίζειν ἀξιῶ· εἰ δ’ ἕτερος τὰ ὅπλ’ ἐν ταῖς χερσὶν ἔχων καὶ δύναμιν πολλὴν περὶ αὑτὸν τοὔνομα μὲν τὸ τῆς εἰρήνης ὑμῖν προβάλλει, τοῖς δ’ ἔργοις αὐτὸς τοῖς τοῦ πολέμου χρῆται, τί λοιπὸν ἄλλο πλὴν ἀμύνεσθαι; φάσκειν δ’ εἰρήνην ἄγειν εἰ βούλεσθε, ὥσπερ ἐκεῖνος, οὐ διαφέρομαι.", "st": "9.8"}, {"sp": "N", "t": "εἰ δέ τις ταύτην εἰρήνην ὑπολαμβάνει, ἐξ ἧς ἐκεῖνος πάντα τἄλλα λαβὼν ἐφ’ ἡμᾶς ἥξει, πρῶτον μὲν μαίνεται, ἔπειτ’ ἐκείνῳ παρ’ ὑμῶν, οὐχ ὑμῖν παρ’ ἐκείνου τὴν εἰρήνην λέγει· τοῦτο δ’ ἐστὶν ὃ τῶν ἀναλισκομένων χρημάτων πάντων Φίλιππος ὠνεῖται, αὐτὸς μὲν πολεμεῖν ὑμῖν, ὑφ’ ὑμῶν δὲ μὴ πολεμεῖσθαι.", "st": "9.9"}, {"sp": "N", "t": "καὶ μὴν εἰ μέχρι τούτου περιμενοῦμεν, ἕως ἂν ἡμῖν ὁμολογήσῃ πολεμεῖν, πάντων ἐσμὲν εὐηθέστατοι· οὐδὲ γὰρ ἂν ἐπὶ τὴν Ἀττικὴν αὐτὴν βαδίζῃ καὶ τὸν Πειραιᾶ, τοῦτ’ ἐρεῖ, εἴπερ οἷς πρὸς τοὺς ἄλλους πεποίηκε δεῖ τεκμαίρεσθαι.", "st": "9.10"}, {"sp": "N", "t": "τοῦτο μὲν γὰρ Ὀλυνθίοις, τετταράκοντ’ ἀπέχων τῆς πόλεως στάδια, εἶπεν ὅτι δεῖ δυοῖν θάτερον, ἢ ἐκείνους ἐν Ὀλύνθῳ μὴ οἰκεῖν ἢ αὑτὸν ἐν Μακεδονίᾳ, πάντα τὸν ἄλλον χρόνον, εἴ τις αὐτὸν αἰτιάσαιτό τι τοιοῦτον, ἀγανακτῶν καὶ πρέσβεις πέμπων τοὺς ἀπολογησομένους· τοῦτο δ’ εἰς Φωκέας ὡς πρὸς συμμάχους ἐπορεύετο, καὶ πρέσβεις Φωκέων ἦσαν οἳ παρηκολούθουν αὐτῷ πορευομένῳ, καὶ παρ’ ἡμῖν ἤριζον οἱ πολλοὶ Θηβαίοις οὐ λυσιτελήσειν τὴν ἐκείνου πάροδον.", "st": "9.11"}, {"sp": "N", "t": "καὶ μὴν καὶ Φερὰς πρώην ὡς φίλος καὶ σύμμαχος εἰς Θετταλίαν ἐλθὼν ἔχει καταλαβών, καὶ τὰ τελευταῖα τοῖς ταλαιπώροις Ὠρείταις τουτοισὶ ἐπισκεψομένους ἔφη τοὺς στρατιώτας πεπομφέναι κατ’ εὔνοιαν· πυνθάνεσθαι γὰρ αὐτοὺς ὡς νοσοῦσι καὶ στασιάζουσιν, συμμάχων δ’ εἶναι καὶ φίλων ἀληθινῶν ἐν τοῖς τοιούτοις καιροῖς παρεῖναι.", "st": "9.12"}, {"sp": "N", "t": "εἶτ’ οἴεσθ’ αὐτόν, οἳ ἐποίησαν μὲν οὐδὲν ἂν κακόν, μὴ παθεῖν δ’ ἐφυλάξαντ’ ἂν ἴσως, τούτους μὲν ἐξαπατᾶν αἱρεῖσθαι μᾶλλον ἢ προλέγοντα βιάζεσθαι, ὑμῖν δ’ ἐκ προρρήσεως πολεμήσειν, καὶ ταῦθ’ ἕως ἂν ἑκόντες ἐξαπατᾶσθε;", "st": "9.13"}, {"sp": "N", "t": "οὐκ ἔστι ταῦτα· καὶ γὰρ ἂν ἀβελτερώτατος εἴη πάντων ἀνθρώπων, εἰ τῶν ἀδικουμένων ὑμῶν μηδὲν ἐγκαλούντων αὐτῷ, ἀλλ’ ὑμῶν αὐτῶν τινὰς αἰτιωμένων, ἐκεῖνος ἐκλύσας τὴν πρὸς ἀλλήλους ἔριν ὑμῶν καὶ φιλονικίαν ἐφ’ αὑτὸν προείποι τρέπεσθαι, καὶ τῶν παρ’ ἑαυτοῦ μισθοφορούντων τοὺς λόγους ἀφέλοιτο, οἷς ἀναβάλλουσιν ὑμᾶς, λέγοντες ὡς ἐκεῖνός γ’ οὐ πολεμεῖ τῇ πόλει.", "st": "9.14"}, {"sp": "N", "t": "ἀλλ’ ἔστιν, ὦ πρὸς τοῦ Διός, ὅστις εὖ φρονῶν ἐκ τῶν ὀνομάτων μᾶλλον ἢ τῶν πραγμάτων τὸν ἄγοντ’ εἰρήνην ἢ πολεμοῦνθ’ αὑτῷ σκέψαιτ’ ἄν; οὐδεὶς δήπου. ὁ τοίνυν Φίλιππος ἐξ ἀρχῆς, ἄρτι τῆς εἰρήνης γεγονυίας, οὔπω Διοπείθους στρατηγοῦντος οὐδὲ τῶν ὄντων ἐν Χερρονήσῳ νῦν ἀπεσταλμένων, Σέρριον καὶ Δορίσκον ἐλάμβανε καὶ τοὺς ἐκ Σερρείου τείχους καὶ Ἱεροῦ ὄρους στρατιώτας ἐξέβαλλεν, οὓς ὁ ὑμέτερος στρατηγὸς κατέστησεν.", "st": "9.15"}, {"sp": "N", "t": "καίτοι ταῦτα πράττων τί ἐποίει; εἰρήνην μὲν γὰρ ὠμωμόκει. καὶ μηδεὶς εἴπῃ, “τί δὲ ταῦτ’ ἐστίν, ἢ τί τούτων μέλει τῇ πόλει;” εἰ μὲν γὰρ μικρὰ ταῦτα, ἢ μηδὲν ὑμῖν αὐτῶν ἔμελεν, ἄλλος ἂν εἴη λόγος οὗτος· τὸ δ’ εὐσεβὲς καὶ τὸ δίκαιον, ἄν τ’ ἐπὶ μικροῦ τις ἄν τ’ ἐπὶ μείζονος παραβαίνῃ, τὴν αὐτὴν ἔχει δύναμιν. φέρε δὴ νῦν, ἡνίκ’ εἰς Χερρόνησον, ἣν βασιλεὺς καὶ πάντες οἱ Ἕλληνες ὑμετέραν ἐγνώκασιν εἶναι, ξένους εἰσπέμπει καὶ βοηθεῖν ὁμολογεῖ καὶ ἐπιστέλλει ταῦτα, τί ποιεῖ;", "st": "9.16"}, {"sp": "N", "t": "φησὶ μὲν γὰρ οὐ πολεμεῖν, ἐγὼ δὲ τοσούτου δέω ταῦτα ποιοῦντ’ ἐκεῖνον ἄγειν ὁμολογεῖν τὴν πρὸς ὑμᾶς εἰρήνην, ὥστε καὶ Μεγάρων ἁπτόμενον κἀν Εὐβοίᾳ τυραννίδα κατασκευάζοντα καὶ νῦν ἐπὶ Θρᾴκην παριόντα καὶ τἀν Πελοποννήσῳ σκευωρούμενον καὶ πάνθ’ ὅσα πράττει μετὰ τῆς δυνάμεως ποιοῦντα, λύειν φημὶ τὴν εἰρήνην καὶ πολεμεῖν ὑμῖν, εἰ μὴ καὶ τοὺς τὰ μηχανήματ’ ἐφιστάντας εἰρήνην ἄγειν φήσετε, ἕως ἂν αὐτὰ τοῖς τείχεσιν ἤδη προσαγάγωσιν. ἀλλ’ οὐ φήσετε· ὁ γὰρ οἷς ἂν ἐγὼ ληφθείην, ταῦτα πράττων καὶ κατασκευαζόμενος, οὗτος ἐμοὶ πολεμεῖ, κἂν μήπω βάλλῃ μηδὲ τοξεύῃ.", "st": "9.17"}, {"sp": "N", "t": "τίσιν οὖν ὑμεῖς κινδυνεύσαιτ’ ἄν, εἴ τι γένοιτο; τῷ τὸν Ἑλλήσποντον ἀλλοτριωθῆναι, τῷ Μεγάρων καὶ τῆς Εὐβοίας τὸν πολεμοῦνθ’ ὑμῖν γενέσθαι κύριον, τῷ Πελοποννησίους τἀκείνου φρονῆσαι. εἶτα τὸν τοῦτο τὸ μηχάνημ’ ἐπὶ τὴν πόλιν ἱστάντα, τοῦτον εἰρήνην ἄγειν ἐγὼ φῶ πρὸς ὑμᾶς;", "st": "9.18"}, {"sp": "N", "t": "πολλοῦ γε καὶ δεῖ, ἀλλ’ ἀφ’ ἧς ἡμέρας ἀνεῖλε Φωκέας, ἀπὸ ταύτης ἔγωγ’ αὐτὸν πολεμεῖν ὁρίζομαι. ὑμᾶς δ’, ἐὰν ἀμύνησθ’ ἤδη, σωφρονήσειν φημί, ἐὰν δ’ ἐάσητε, οὐδὲ τοῦθ’ ὅταν βούλησθε δυνήσεσθαι ποιῆσαι. καὶ τοσοῦτόν γ’ ἀφέστηκα τῶν ἄλλων, ὦ ἄνδρες Ἀθηναῖοι, τῶν συμβουλευόντων, ὥστ’ οὐδὲ δοκεῖ μοι περὶ Χερρονήσου νῦν σκοπεῖν οὐδὲ Βυζαντίου, ἀλλ’ ἐπαμῦναι μὲν τούτοις,", "st": "9.19"}, {"sp": "N", "t": "καὶ διατηρῆσαι μή τι πάθωσι, καὶ τοῖς οὖσιν ἐκεῖ νῦν στρατιώταις πάνθ’ ὅσων ἂν δέωνται ἀποστεῖλαι, βουλεύεσθαι μέντοι περὶ πάντων τῶν Ἑλλήνων ὡς ἐν κινδύνῳ μεγάλῳ καθεστώτων. βούλομαι δ’ εἰπεῖν πρὸς ὑμᾶς ἐξ ὧν ὑπὲρ τῶν πραγμάτων οὕτω φοβοῦμαι, ἵν’, εἰ μὲν ὀρθῶς λογίζομαι, μετάσχητε τῶν λογισμῶν καὶ πρόνοιάν τιν’ ὑμῶν γ’ αὐτῶν, εἰ μὴ καὶ τῶν ἄλλων ἄρα βούλεσθε, ποιήσησθε, ἂν δὲ ληρεῖν καὶ τετυφῶσθαι δοκῶ, μήτε νῦν μήτ’ αὖθις ὡς ὑγιαίνοντί μοι προσέχητε.", "st": "9.20"}, {"sp": "N", "t": "ὅτι μὲν δὴ μέγας ἐκ μικροῦ καὶ ταπεινοῦ τὸ κατ’ ἀρχὰς Φίλιππος ηὔξηται, καὶ ἀπίστως καὶ στασιαστικῶς ἔχουσι πρὸς αὑτοὺς οἱ Ἕλληνες, καὶ ὅτι πολλῷ παραδοξότερον ἦν τοσοῦτον αὐτὸν ἐξ ἐκείνου γενέσθαι ἢ νῦν, ὅθ’ οὕτω πολλὰ προείληφε, καὶ τὰ λοιπὰ ὑφ’ αὑτῷ ποιήσασθαι, καὶ πάνθ’ ὅσα τοιαῦτ’ ἂν ἔχοιμι διεξελθεῖν, παραλείψω.", "st": "9.21"}, {"sp": "N", "t": "ἀλλ’ ὁρῶ συγκεχωρηκότας ἅπαντας ἀνθρώπους, ἀφ’ ὑμῶν ἀρξαμένους, αὐτῷ, ὑπὲρ οὗ τὸν ἄλλον ἅπαντα χρόνον πάντες οἱ πόλεμοι γεγόνασιν οἱ Ἑλληνικοί. τί οὖν ἐστι τοῦτο; τὸ ποιεῖν ὅ τι βούλεται, καὶ καθ’ ἕν’ οὑτωσὶ περικόπτειν καὶ λωποδυτεῖν τῶν Ἑλλήνων, καὶ καταδουλοῦσθαι τὰς πόλεις ἐπιόντα.", "st": "9.22"}, {"sp": "N", "t": "καίτοι προστάται μὲν ὑμεῖς ἑβδομήκοντ’ ἔτη καὶ τρία τῶν Ἑλλήνων ἐγένεσθε, προστάται δὲ τριάκονθ’ ἑνὸς δέοντα Λακεδαιμόνιοι· ἴσχυσαν δέ τι καὶ Θηβαῖοι τουτουσὶ τοὺς τελευταίους χρόνους μετὰ τὴν ἐν Λεύκτροις μάχην. ἀλλ’ ὅμως οὔθ’ ὑμῖν οὔτε Θηβαίοις οὔτε Λακεδαιμονίοις οὐδεπώποτ’, ὦ ἄνδρες Ἀθηναῖοι, συνεχωρήθη τοῦθ’ ὑπὸ τῶν Ἑλλήνων, ποιεῖν ὅ τι βούλοισθε, οὐδὲ πολλοῦ δεῖ·", "st": "9.23"}, {"sp": "N", "t": "ἀλλὰ τοῦτο μὲν ὑμῖν, μᾶλλον δὲ τοῖς τότ’ οὖσιν Ἀθηναίοις, ἐπειδή τισιν οὐ μετρίως ἐδόκουν προσφέρεσθαι, πάντες ᾤοντο δεῖν, καὶ οἱ μηδὲν ἐγκαλεῖν ἔχοντες αὐτοῖς, μετὰ τῶν ἠδικημένων πολεμεῖν· καὶ πάλιν Λακεδαιμονίοις ἄρξασι καὶ παρελθοῦσιν εἰς τὴν αὐτὴν δυναστείαν ὑμῖν, ἐπειδὴ πλεονάζειν ἐπεχείρουν καὶ πέρα τοῦ μετρίου τὰ καθεστηκότ’ ἐκίνουν, πάντες εἰς πόλεμον κατέστησαν, καὶ οἱ μηδὲν ἐγκαλοῦντες αὐτοῖς.", "st": "9.24"}, {"sp": "N", "t": "καὶ τί δεῖ τοὺς ἄλλους λέγειν; ἀλλ’ ἡμεῖς αὐτοὶ καὶ Λακεδαιμόνιοι, οὐδὲν ἂν εἰπεῖν ἔχοντες ἐξ ἀρχῆς ὅ τι ἠδικούμεθ’ ὑπ’ ἀλλήλων, ὅμως ὑπὲρ ὧν τοὺς ἄλλους ἀδικουμένους ἑωρῶμεν, πολεμεῖν ᾠόμεθα δεῖν. καίτοι πάνθ’ ὅσ’ ἐξημάρτηται καὶ Λακεδαιμονίοις ἐν τοῖς τριάκοντ’ ἐκείνοις ἔτεσιν καὶ τοῖς ἡμετέροις προγόνοις ἐν τοῖς ἑβδομήκοντα, ἐλάττον’ ἐστίν, ὦ ἄνδρες Ἀθηναῖοι, ὧν Φίλιππος ἐν τρισὶ καὶ δέκ’ οὐχ ὅλοις ἔτεσιν, οἷς ἐπιπολάζει, ἠδίκηκε τοὺς Ἕλληνας, μᾶλλον δ’ οὐδὲ μέρος τούτων ἐκεῖνα.", "st": "9.25"}, {"sp": "N", "t": "καὶ τοῦτ’ ἐκ βραχέος λόγου ῥᾴδιον δεῖξαι. Ὄλυνθον μὲν δὴ καὶ Μεθώνην καὶ Ἀπολλωνίαν καὶ δύο καὶ τριάκοντα πόλεις ἐπὶ Θρᾴκης ἐῶ, ἃς ἁπάσας οὕτως ὠμῶς ἀνῄρηκεν ὥστε μηδ’ εἰ πώποτ’ ᾠκήθησαν προσελθόντ’ εἶναι ῥᾴδιον εἰπεῖν· καὶ τὸ Φωκέων ἔθνος τοσοῦτον ἀνῃρημένον σιωπῶ. ἀλλὰ Θετταλία πῶς ἔχει; οὐχὶ τὰς πολιτείας καὶ τὰς πόλεις αὐτῶν παρῄρηται καὶ τετραρχίας κατέστησεν, ἵνα μὴ μόνον κατὰ πόλεις ἀλλὰ καὶ κατ’ ἔθνη δουλεύωσιν;", "st": "9.26"}, {"sp": "N", "t": "αἱ δ’ ἐν Εὐβοίᾳ πόλεις οὐκ ἤδη τυραννοῦνται, καὶ ταῦτ’ ἐν νήσῳ πλησίον Θηβῶν καὶ Ἀθηνῶν; οὐ διαρρήδην εἰς τὰς ἐπιστολὰς γράφει “ἐμοὶ δ’ ἐστὶν εἰρήνη πρὸς τοὺς ἀκούειν ἐμοῦ βουλομένους”; καὶ οὐ γράφει μὲν ταῦτα, τοῖς δ’ ἔργοις οὐ ποιεῖ, ἀλλ’ ἐφ’ Ἑλλήσποντον οἴχεται, πρότερον ἧκεν ἐπ’ Ἀμβρακίαν, Ἦλιν ἔχει τηλικαύτην πόλιν ἐν Πελοποννήσῳ, Μεγάροις ἐπεβούλευσεν πρώην, οὔθ’ ἡ Ἑλλὰς οὔθ’ ἡ βάρβαρος τὴν πλεονεξίαν χωρεῖ τἀνθρώπου.", "st": "9.27"}, {"sp": "N", "t": "καὶ ταῦθ’ ὁρῶντες οἱ Ἕλληνες ἅπαντες καὶ ἀκούοντες οὐ πέμπομεν πρέσβεις περὶ τούτων πρὸς ἀλλήλους κἀγανακτοῦμεν, οὕτω δὲ κακῶς διακείμεθα καὶ διορωρύγμεθα κατὰ πόλεις ὥστ’ ἄχρι τῆς τήμερον ἡμέρας οὐδὲν οὔτε τῶν συμφερόντων οὔτε τῶν δεόντων πρᾶξαι δυνάμεθα, οὐδὲ συστῆναι, οὐδὲ κοινωνίαν βοηθείας καὶ φιλίας οὐδεμίαν ποιήσασθαι,", "st": "9.28"}, {"sp": "N", "t": "ἀλλὰ μείζω γιγνόμενον τὸν ἄνθρωπον περιορῶμεν, τὸν χρόνον κερδᾶναι τοῦτον ὃν ἄλλος ἀπόλλυται ἕκαστος ἐγνωκώς, ὥς γ’ ἐμοὶ δοκεῖ, οὐχ ὅπως σωθήσεται τὰ τῶν Ἑλλήνων σκοπῶν οὐδὲ πράττων, ἐπεί, ὅτι γ’ ὥσπερ περίοδος ἢ καταβολὴ πυρετοῦ ἢ ἄλλου τινὸς κακοῦ καὶ τῷ πάνυ πόρρω δοκοῦντι νῦν ἀφεστάναι προσέρχεται, οὐδεὶς ἀγνοεῖ.", "st": "9.29"}, {"sp": "N", "t": "καὶ μὴν κἀκεῖνό γ’ ἴστε, ὅτι ὅσα μὲν ὑπὸ Λακεδαιμονίων ἢ ὑφ’ ἡμῶν ἔπασχον οἱ Ἕλληνες, ἀλλ’ οὖν ὑπὸ γνησίων γ’ ὄντων τῆς Ἑλλάδος ἠδικοῦντο, καὶ τὸν αὐτὸν τρόπον ἄν τις ὑπέλαβεν τοῦτο, ὥσπερ ἂν εἰ υἱὸς ἐν οὐσίᾳ πολλῇ γεγονὼς γνήσιος διῴκει τι μὴ καλῶς μηδ’ ὀρθῶς, κατ’ αὐτὸ μὲν τοῦτ’ ἄξιον μέμψεως εἶναι καὶ κατηγορίας, ὡς δ’ οὐ προσήκων ἢ ὡς οὐ κληρονόμος τούτων ὢν ταῦτ’ ἐποίει, οὐκ ἐνεῖναι λέγειν.", "st": "9.30"}, {"sp": "N", "t": "εἰ δέ γε δοῦλος ἢ ὑποβολιμαῖος τὰ μὴ προσήκοντ’ ἀπώλλυε καὶ ἐλυμαίνετο, Ἡράκλεις ὅσῳ μᾶλλον δεινὸν καὶ ὀργῆς ἄξιον πάντες ἂν ἔφησαν εἶναι. ἀλλ’ οὐχ ὑπὲρ Φιλίππου καὶ ὧν ἐκεῖνος πράττει νῦν, οὐχ οὕτως ἔχουσιν, οὐ μόνον οὐχ Ἕλληνος ὄντος οὐδὲ προσήκοντος οὐδὲν τοῖς Ἕλλησιν, ἀλλ’ οὐδὲ βαρβάρου ἐντεῦθεν ὅθεν καλὸν εἰπεῖν, ἀλλ’ ὀλέθρου Μακεδόνος, ὅθεν οὐδ’ ἀνδράποδον σπουδαῖον οὐδὲν ἦν πρότερον πρίασθαι.", "st": "9.31"}, {"sp": "N", "t": "καίτοι τί τῆς ἐσχάτης ὕβρεως ἀπολείπει; οὐ πρὸς τῷ πόλεις ἀνῃρηκέναι τίθησι μὲν τὰ Πύθια, τὸν κοινὸν τῶν Ἑλλήνων ἀγῶνα, κἂν αὐτὸς μὴ παρῇ, τοὺς δούλους ἀγωνοθετήσοντας πέμπει; κύριος δὲ Πυλῶν καὶ τῶν ἐπὶ τοὺς Ἕλληνας παρόδων ἐστί, καὶ φρουραῖς καὶ ξένοις τοὺς τόπους τούτους κατέχει; ἔχει δὲ καὶ τὴν προμαντείαν τοῦ θεοῦ, παρώσας ἡμᾶς καὶ Θετταλοὺς καὶ Δωριέας καὶ τοὺς ἄλλους Ἀμφικτύονας, ἧς οὐδὲ τοῖς Ἕλλησιν ἅπασι μέτεστι;", "st": "9.32"}, {"sp": "N", "t": "γράφει δὲ Θετταλοῖς ὃν χρὴ τρόπον πολιτεύεσθαι; πέμπει δὲ ξένους τοὺς μὲν εἰς Πορθμόν, τὸν δῆμον ἐκβαλοῦντας τὸν Ἐρετριέων, τοὺς δ’ ἐπ’ Ὠρεόν, τύραννον Φιλιστίδην καταστήσοντας; ἀλλ’ ὅμως ταῦθ’ ὁρῶντες οἱ Ἕλληνες ἀνέχονται, καὶ τὸν αὐτὸν τρόπον ὥσπερ τὴν χάλαζαν ἔμοιγε δοκοῦσιν θεωρεῖν, εὐχόμενοι μὴ καθ’ ἑαυτοὺς ἕκαστοι γενέσθαι, κωλύειν δ’ οὐδεὶς ἐπιχειρῶν.", "st": "9.33"}, {"sp": "N", "t": "οὐ μόνον δ’ ἐφ’ οἷς ἡ Ἑλλὰς ὑβρίζεται ὑπ’ αὐτοῦ, οὐδεὶς ἀμύνεται, ἀλλ’ οὐδ’ ὑπὲρ ὧν αὐτὸς ἕκαστος ἀδικεῖται· τοῦτο γὰρ ἤδη τοὔσχατόν ἐστιν. οὐ Κορινθίων ἐπ’ Ἀμβρακίαν ἐλήλυθε καὶ Λευκάδα; οὐκ Ἀχαιῶν Ναύπακτον ὀμώμοκεν Αἰτωλοῖς παραδώσειν; οὐχὶ Θηβαίων Ἐχῖνον ἀφῄρηται, καὶ νῦν ἐπὶ Βυζαντίους πορεύεται συμμάχους ὄντας;", "st": "9.34"}, {"sp": "N", "t": "οὐχ ἡμῶν, ἐῶ τἄλλα, ἀλλὰ Χερρονήσου τὴν μεγίστην ἔχει πόλιν Καρδίαν; ταῦτα τοίνυν πάσχοντες ἅπαντες μέλλομεν καὶ μαλκίομεν καὶ πρὸς τοὺς πλησίον βλέπομεν, ἀπιστοῦντες ἀλλήλοις, οὐ τῷ πάντας ἡμᾶς ἀδικοῦντι. καίτοι τὸν ἅπασιν ἀσελγῶς οὕτω χρώμενον τί οἴεσθε, ἐπειδὰν καθ’ ἕν’ ἡμῶν ἑκάστου κύριος γένηται, τί ποιήσειν;", "st": "9.35"}, {"sp": "N", "t": "τί οὖν αἴτιον τουτωνί; οὐ γὰρ ἄνευ λόγου καὶ δικαίας αἰτίας οὔτε τόθ’ οὕτως εἶχον ἑτοίμως πρὸς ἐλευθερίαν οἱ Ἕλληνες οὔτε νῦν πρὸς τὸ δουλεύειν. ἦν τι τότ’, ἦν, ὦ ἄνδρες Ἀθηναῖοι, ἐν ταῖς τῶν πολλῶν διανοίαις, ὃ νῦν οὐκ ἔστιν, ὃ καὶ τοῦ Περσῶν ἐκράτησε πλούτου καὶ ἐλευθέραν ἦγε τὴν Ἑλλάδα καὶ οὔτε ναυμαχίας οὔτε πεζῆς μάχης οὐδεμιᾶς ἡττᾶτο, νῦν δ’ ἀπολωλὸς ἅπαντα λελύμανται καὶ ἄνω καὶ κάτω πεποίηκε τὰ τῶν Ἑλλήνων πράγματα.", "st": "9.36"}, {"sp": "N", "t": "τί οὖν ἦν τοῦτο; οὐδὲν ποικίλον οὐδὲ σοφόν, ἀλλ’ ὅτι τοὺς παρὰ τῶν ἄρχειν βουλομένων ἢ διαφθείρειν τὴν Ἑλλάδα χρήματα λαμβάνοντας ἅπαντες ἐμίσουν, καὶ χαλεπώτατον ἦν τὸ δωροδοκοῦντ’ ἐλεγχθῆναι, καὶ τιμωρίᾳ μεγίστῃ τοῦτον ἐκόλαζον, καὶ παραίτησις οὐδεμί’ ἦν οὐδὲ συγγνώμη.", "st": "9.37"}, {"sp": "N", "t": "τὸν οὖν καιρὸν ἑκάστου τῶν πραγμάτων, ὃν ἡ τύχη καὶ τοῖς ἀμελοῦσιν κατὰ τῶν προσεχόντων πολλάκις παρασκευάζει, οὐκ ἦν πρίασθαι παρὰ τῶν λεγόντων οὐδὲ τῶν στρατηγούντων, οὐδὲ τὴν πρὸς ἀλλήλους ὁμόνοιαν, οὐδὲ τὴν πρὸς τοὺς τυράννους καὶ τοὺς βαρβάρους ἀπιστίαν, οὐδ’ ὅλως τοιοῦτον οὐδέν.", "st": "9.38"}, {"sp": "N", "t": "νῦν δ’ ἅπανθ’ ὥσπερ ἐξ ἀγορᾶς ἐκπέπραται ταῦτα, ἀντεισῆκται δ’ ἀντὶ τούτων ὑφ’ ὧν ἀπόλωλε καὶ νενόσηκεν ἡ Ἑλλάς. ταῦτα δ’ ἐστὶ τί; ζῆλος, εἴ τις εἴληφέ τι· γέλως, ἂν ὁμολογῇ· συγγνώμη τοῖς ἐλεγχομένοις· μῖσος, ἂν τούτοις τις ἐπιτιμᾷ· τἄλλα πάνθ’ ὅσ’ ἐκ τοῦ δωροδοκεῖν ἤρτηται.", "st": "9.39"}, {"sp": "N", "t": "ἐπεὶ τριήρεις γε καὶ σωμάτων πλῆθος καὶ χρημάτων καὶ τῆς ἄλλης κατασκευῆς ἀφθονία, καὶ τἄλλ’ οἷς ἄν τις ἰσχύειν τὰς πόλεις κρίνοι, νῦν ἅπασι καὶ πλείω καὶ μείζω ἐστὶ τῶν τότε πολλῷ. ἀλλὰ ταῦτ’ ἄχρηστα, ἄπρακτα, ἀνόνητα ὑπὸ τῶν πωλούντων γίγνεται.", "st": "9.40"}, {"sp": "N", "t": "ὅτι δ’ οὕτω ταῦτ’ ἔχει τὰ μὲν νῦν ὁρᾶτε δήπου καὶ οὐδὲν ἐμοῦ προσδεῖσθε μάρτυρος· τὰ δ’ ἐν τοῖς ἄνωθεν χρόνοις ὅτι τἀναντί’ εἶχεν ἐγὼ δηλώσω, οὐ λόγους ἐμαυτοῦ λέγων, ἀλλὰ γράμματα τῶν προγόνων τῶν ὑμετέρων ἁκεῖνοι κατέθεντ’ εἰς στήλην χαλκῆν γράψαντες εἰς ἀκρόπολιν, οὐχ ἵν’ αὐτοῖς ᾖ χρήσιμα (καὶ γὰρ ἄνευ τούτων τῶν γραμμάτων τὰ δέοντ’ ἐφρόνουν), ἀλλ’ ἵν’ ὑμεῖς ἔχηθ’ ὑπομνήματα καὶ παραδείγματα ὡς ὑπὲρ τῶν τοιούτων σπουδάζειν προσήκει.", "st": "9.41"}, {"sp": "N", "t": "τί οὖν λέγει τὰ γράμματα; “Ἄρθμιος” φησὶ “Πυθώνακτος Ζελείτης ἄτιμος καὶ πολέμιος τοῦ δήμου τοῦ Ἀθηναίων καὶ τῶν συμμάχων αὐτὸς καὶ γένος.” εἶθ’ ἡ αἰτία γέγραπται, δι’ ἣν ταῦτ’ ἐγένετο· “ὅτι τὸν χρυσὸν τὸν ἐκ Μήδων εἰς Πελοπόννησον ἤγαγεν.” ταῦτ’ ἐστὶ τὰ γράμματα.", "st": "9.42"}, {"sp": "N", "t": "λογίζεσθε δὴ πρὸς θεῶν, τίς ἦν ποθ’ ἡ διάνοια τῶν Ἀθηναίων τῶν τότε, ταῦτα ποιούντων, ἢ τί τὸ ἀξίωμα. ἐκεῖνοι Ζελείτην τινά, Ἄρθμιον, δοῦλον βασιλέως (ἡ γὰρ Ζέλειά ἐστι τῆς Ἀσίας), ὅτι τῷ δεσπότῃ διακονῶν χρυσίον ἤγαγεν εἰς Πελοπόννησον, οὐκ Ἀθήναζε, ἐχθρὸν αὑτῶν ἀνέγραψαν καὶ τῶν συμμάχων αὐτὸν καὶ γένος, καὶ ἀτίμους.", "st": "9.43"}, {"sp": "N", "t": "τοῦτο δ’ ἐστὶν οὐχ ἣν οὑτωσί τις ἂν φήσειεν ἀτιμίαν· τί γὰρ τῷ Ζελείτῃ, τῶν Ἀθηναίων κοινῶν εἰ μὴ μεθέξειν ἔμελλεν; ἀλλ’ ἐν τοῖς φονικοῖς γέγραπται νόμοις, ὑπὲρ ὧν ἂν μὴ διδῷ φόνου δικάσασθαι, ἀλλ’ εὐαγὲς ᾖ τὸ ἀποκτεῖναι, “καὶ ἄτιμος” φησὶ “τεθνάτω.” τοῦτο δὴ λέγει, καθαρὸν τὸν τούτων τιν’ ἀποκτείναντ’ εἶναι.", "st": "9.44"}, {"sp": "N", "t": "οὐκοῦν ἐνόμιζον ἐκεῖνοι τῆς πάντων τῶν Ἑλλήνων σωτηρίας αὑτοῖς ἐπιμελητέον εἶναι· οὐ γὰρ ἂν αὐτοῖς ἔμελ’ εἴ τις ἐν Πελοποννήσῳ τινὰς ὠνεῖται καὶ διαφθείρει, μὴ τοῦθ’ ὑπολαμβάνουσιν· ἐκόλαζον δ’ οὕτω καὶ ἐτιμωροῦνθ’ οὓς αἴσθοιντο, ὥστε καὶ στηλίτας ποιεῖν. ἐκ δὲ τούτων εἰκότως τὰ τῶν Ἑλλήνων ἦν τῷ βαρβάρῳ φοβερά, οὐχ ὁ βάρβαρος τοῖς Ἕλλησιν. ἀλλ’ οὐ νῦν· οὐ γὰρ οὕτως ἔχεθ’ ὑμεῖς οὔτε πρὸς τὰ τοιαῦτ’ οὔτε πρὸς τἄλλα, ἀλλὰ πῶς;", "st": "9.45"}, {"sp": "N", "t": "ἴστ’ αὐτοί· τί γὰρ δεῖ περὶ πάντων ὑμῶν κατηγορεῖν; παραπλησίως δὲ καὶ οὐδὲν βέλτιον ὑμῶν ἅπαντες οἱ λοιποὶ Ἕλληνες· διόπερ φήμ’ ἔγωγε καὶ σπουδῆς πολλῆς καὶ βουλῆς ἀγαθῆς τὰ παρόντα πράγματα προσδεῖσθαι. τίνος; εἴπω κελεύετε; καὶ οὐκ ὀργιεῖσθε;", "st": "9.46"}, {"sp": "N", "t": "[ΕΚ ΤΟΥ ΓΡΑΜΜΑΤΕΙΟΥ ΑΝΑΓΙΓΝΩΣΚΕΙ.]", "st": "9.46"}, {"sp": "N", "t": "ἔστι τοίνυν τις εὐήθης λόγος παρὰ τῶν παραμυθεῖσθαι βουλομένων τὴν πόλιν, ὡς ἄρ’ οὔπω Φίλιππός ἐστιν οἷοί ποτ’ ἦσαν Λακεδαιμόνιοι, οἳ θαλάττης μὲν ἦρχον καὶ γῆς ἁπάσης, βασιλέα δὲ σύμμαχον εἶχον, ὑφίστατο δ’ οὐδὲν αὐτούς· ἀλλ’ ὅμως ἠμύνατο κἀκείνους ἡ πόλις καὶ οὐκ ἀνηρπάσθη. ἐγὼ δ’ ἁπάντων ὡς ἔπος εἰπεῖν πολλὴν εἰληφότων ἐπίδοσιν, καὶ οὐδὲν ὁμοίων ὄντων τῶν νῦν τοῖς πρότερον, οὐδὲν ἡγοῦμαι πλέον ἢ τὰ τοῦ πολέμου κεκινῆσθαι κἀπιδεδωκέναι.", "st": "9.47"}, {"sp": "N", "t": "πρῶτον μὲν γὰρ ἀκούω Λακεδαιμονίους τότε καὶ πάντας τοὺς ἄλλους, τέτταρας μῆνας ἢ πέντε, τὴν ὡραίαν αὐτήν, ἐμβαλόντας ἂν καὶ κακώσαντας τὴν χώραν ὁπλίταις καὶ πολιτικοῖς στρατεύμασιν ἀναχωρεῖν ἐπ’ οἴκου πάλιν· οὕτω δ’ ἀρχαίως εἶχον, μᾶλλον δὲ πολιτικῶς, ὥστ’ οὐδὲ χρημάτων ὠνεῖσθαι παρ’ οὐδενὸς οὐδέν, ἀλλ’ εἶναι νόμιμόν τινα καὶ προφανῆ τὸν πόλεμον.", "st": "9.48"}, {"sp": "N", "t": "νυνὶ δ’ ὁρᾶτε μὲν δήπου τὰ πλεῖστα τοὺς προδότας ἀπολωλεκότας, οὐδὲν δ’ ἐκ παρατάξεως οὐδὲ μάχης γιγνόμενον· ἀκούετε δὲ Φίλιππον οὐχὶ τῷ φάλαγγ’ ὁπλιτῶν ἄγειν βαδίζονθ’ ὅποι βούλεται, ἀλλὰ τῷ ψιλούς, ἱππέας, τοξότας, ξένους, τοιοῦτον ἐξηρτῆσθαι στρατόπεδον.", "st": "9.49"}, {"sp": "N", "t": "ἐπειδὰν δ’ ἐπὶ τούτοις πρὸς νοσοῦντας ἐν αὑτοῖς προσπέσῃ καὶ μηδεὶς ὑπὲρ τῆς χώρας δι’ ἀπιστίαν ἐξίῃ, μηχανήματ’ ἐπιστήσας πολιορκεῖ. καὶ σιωπῶ θέρος καὶ χειμῶνα, ὡς οὐδὲν διαφέρει, οὐδ’ ἐστὶν ἐξαίρετος ὥρα τις ἣν διαλείπει.", "st": "9.50"}, {"sp": "N", "t": "ταῦτα μέντοι πάντας εἰδότας καὶ λογιζομένους οὐ δεῖ προσέσθαι τὸν πόλεμον εἰς τὴν χώραν, οὐδ’ εἰς τὴν εὐήθειαν τὴν τοῦ τότε πρὸς Λακεδαιμονίους πολέμου βλέποντας ἐκτραχηλισθῆναι, ἀλλ’ ὡς ἐκ πλείστου φυλάττεσθαι τοῖς πράγμασι καὶ ταῖς παρασκευαῖς, ὅπως οἴκοθεν μὴ κινήσεται σκοποῦντας, οὐχὶ συμπλακέντας διαγωνίζεσθαι.", "st": "9.51"}, {"sp": "N", "t": "πρὸς μὲν γὰρ πόλεμον πολλὰ φύσει πλεονεκτήμαθ’ ἡμῖν ὑπάρχει, ἄν περ, ὦ ἄνδρες Ἀθηναῖοι, ποιεῖν ἐθέλωμεν ἃ δεῖ, ἡ φύσις τῆς ἐκείνου χώρας, ἧς ἄγειν καὶ φέρειν ἔστι πολλὴν καὶ κακῶς ποιεῖν, ἄλλα μυρία· εἰς δ’ ἀγῶνα ἄμεινον ἡμῶν ἐκεῖνος ἤσκηται.", "st": "9.52"}, {"sp": "N", "t": "οὐ μόνον δὲ δεῖ ταῦτα γιγνώσκειν, οὐδὲ τοῖς ἔργοις ἐκεῖνον ἀμύνεσθαι τοῖς τοῦ πολέμου, ἀλλὰ καὶ τῷ λογισμῷ καὶ τῇ διανοίᾳ τοὺς παρ’ ὑμῖν ὑπὲρ αὐτοῦ λέγοντας μισῆσαι, ἐνθυμουμένους ὅτι οὐκ ἔνεστι τῶν τῆς πόλεως ἐχθρῶν κρατῆσαι, πρὶν ἂν τοὺς ἐν αὐτῇ τῇ πόλει κολάσηθ’ ὑπηρετοῦντας ἐκείνοις.", "st": "9.53"}, {"sp": "N", "t": "ὃ μὰ τὸν Δία καὶ τοὺς ἄλλους θεοὺς οὐ δυνήσεσθ’ ὑμεῖς ποιῆσαι, ἀλλ’ εἰς τοῦτ’ ἀφῖχθε μωρίας ἢ παρανοίας ἢ οὐκ ἔχω τί λέγω (πολλάκις γὰρ ἔμοιγ’ ἐπελήλυθε καὶ τοῦτο φοβεῖσθαι, μή τι δαιμόνιον τὰ πράγματ’ ἐλαύνῃ), ὥστε λοιδορίας, φθόνου, σκώμματος, ἧστινος ἂν τύχηθ’ ἕνεκ’ αἰτίας ἀνθρώπους μισθωτούς, ὧν οὐδ’ ἂν ἀρνηθεῖεν ἔνιοι ὡς οὐκ εἰσὶ τοιοῦτοι, λέγειν κελεύετε, καὶ γελᾶτε, ἄν τισι λοιδορηθῶσιν.", "st": "9.54"}, {"sp": "N", "t": "καὶ οὐχί πω τοῦτο δεινόν, καίπερ ὂν δεινόν· ἀλλὰ καὶ μετὰ πλείονος ἀσφαλείας πολιτεύεσθαι δεδώκατε τούτοις ἢ τοῖς ὑπὲρ ὑμῶν λέγουσιν. καίτοι θεάσασθε ὅσας συμφορὰς παρασκευάζει τὸ τῶν τοιούτων ἐθέλειν ἀκροᾶσθαι. λέξω δ’ ἔργα ἃ πάντες εἴσεσθε.", "st": "9.55"}, {"sp": "N", "t": "ἦσαν ἐν Ὀλύνθῳ τῶν ἐν τοῖς πράγμασιν τινὲς μὲν Φιλίππου καὶ πάνθ’ ὑπηρετοῦντες ἐκείνῳ, τινὲς δὲ τοῦ βελτίστου καὶ ὅπως μὴ δουλεύσουσιν οἱ πολῖται πράττοντες. πότεροι δὴ τὴν πατρίδ’ ἐξώλεσαν; ἢ πότεροι τοὺς ἱππέας προὔδοσαν, ὧν προδοθέντων Ὄλυνθος ἀπώλετο; οἱ τὰ Φιλίππου φρονοῦντες, καὶ ὅτ’ ἦν ἡ πόλις τοὺς τὰ βέλτιστα λέγοντας συκοφαντοῦντες καὶ διαβάλλοντες οὕτως, ὥστε τόν γ’ Ἀπολλωνίδην καὶ ἐκβαλεῖν ὁ δῆμος ὁ τῶν Ὀλυνθίων ἐπείσθη.", "st": "9.56"}, {"sp": "N", "t": "οὐ τοίνυν παρὰ τούτοις μόνον τὸ ἔθος τοῦτο πάντα κάκ’ εἰργάσατο, ἄλλοθι δ’ οὐδαμοῦ· ἀλλ’ ἐν Ἐρετρίᾳ, ἐπειδὴ ἀπαλλαγέντος Πλουτάρχου καὶ τῶν ξένων ὁ δῆμος εἶχε τὴν πόλιν καὶ τὸν Πορθμόν, οἱ μὲν ἐφ’ ὑμᾶς ἦγον τὰ πράγματα, οἱ δ’ ἐπὶ Φίλιππον. ἀκούοντες δὲ τούτων τὰ πολλά, μᾶλλον δὲ τὰ πάνθ’ οἱ ταλαίπωροι καὶ δυστυχεῖς Ἐρετριεῖς, τελευτῶντες ἐπείσθησαν τοὺς ὑπὲρ αὑτῶν λέγοντας ἐκβαλεῖν.", "st": "9.57"}, {"sp": "N", "t": "καὶ γάρ τοι πέμψας Ἱππόνικον ὁ σύμμαχος αὐτοῖς Φίλιππος καὶ ξένους χιλίους, τὰ τείχη περιεῖλε τοῦ Πορθμοῦ καὶ τρεῖς κατέστησε τυράννους, Ἵππαρχον, Αὐτομέδοντα, Κλείταρχον· καὶ μετὰ ταῦτ’ ἐξελήλακεν ἐκ τῆς χώρας δὶς ἤδη βουλομένους σῴζεσθαι, τότε μὲν πέμψας τοὺς μετ’ Εὐρυλόχου ξένους, πάλιν δὲ τοὺς μετὰ Παρμενίωνος.", "st": "9.58"}, {"sp": "N", "t": "καὶ τί δεῖ τὰ πολλὰ λέγειν; ἀλλ’ ἐν Ὠρεῷ Φιλιστίδης μὲν ἔπραττε Φιλίππῳ καὶ Μένιππος καὶ Σωκράτης καὶ Θόας καὶ Ἀγαπαῖος, οἵπερ νῦν ἔχουσι τὴν πόλιν (καὶ ταῦτ’ ᾔδεσαν ἅπαντες), Εὐφραῖος δέ τις ἄνθρωπος καὶ παρ’ ἡμῖν ποτ’ ἐνθάδ’ οἰκήσας, ὅπως ἐλεύθεροι καὶ μηδενὸς δοῦλοι ἔσονται.", "st": "9.59"}, {"sp": "N", "t": "οὗτος τὰ μὲν ἄλλ’ ὡς ὑβρίζετο καὶ προυπηλακίζεθ’ ὑπὸ τοῦ δήμου, πόλλ’ ἂν εἴη λέγειν· ἐνιαυτῷ δὲ πρότερον τῆς ἁλώσεως ἐνέδειξεν ὡς προδότην τὸν Φιλιστίδην καὶ τοὺς μετ’ αὐτοῦ, αἰσθόμενος ἃ πράττουσιν. συστραφέντες δ’ ἄνθρωποι πολλοὶ καὶ χορηγὸν ἔχοντες Φίλιππον καὶ πρυτανευόμενοι ἀπάγουσι τὸν Εὐφραῖον εἰς τὸ δεσμωτήριον, ὡς συνταράττοντα τὴν πόλιν.", "st": "9.60"}, {"sp": "N", "t": "ὁρῶν δὲ ταῦθ’ ὁ δῆμος ὁ τῶν Ὠρειτῶν, ἀντὶ τοῦ τῷ μὲν βοηθεῖν, τοὺς δ’ ἀποτυμπανίσαι, τοῖς μὲν οὐκ ὠργίζετο, τὸν δ’ ἐπιτήδειον ταῦτα παθεῖν ἔφη καὶ ἐπέχαιρεν. μετὰ ταῦθ’ οἱ μὲν ἐπ’ ἐξουσίας ὁπόσης ἐβούλοντ’ ἔπραττον ὅπως ἡ πόλις ληφθήσεται, καὶ κατεσκευάζοντο τὴν πρᾶξιν· τῶν δὲ πολλῶν εἴ τις αἴσθοιτο, ἐσίγα καὶ κατεπέπληκτο, τὸν Εὐφραῖον οἷ’ ἔπαθεν μεμνημένοι. οὕτω δ’ ἀθλίως διέκειντο, ὥστ’ οὐ πρότερον ἐτόλμησεν οὐδεὶς τοιούτου κακοῦ προσιόντος ῥῆξαι φωνήν, πρὶν διασκευασάμενοι πρὸς τὰ τείχη προσῇσαν οἱ πολέμιοι· τηνικαῦτα δ’ οἱ μὲν ἠμύνοντο, οἱ δὲ προὐδίδοσαν.", "st": "9.61"}, {"sp": "N", "t": "τῆς πόλεως δ’ οὕτως ἁλούσης αἰσχρῶς καὶ κακῶς οἱ μὲν ἄρχουσι καὶ τυραννοῦσι, τοὺς τότε σῴζοντας ἑαυτοὺς καὶ τὸν Εὐφραῖον ἑτοίμους ὁτιοῦν ποιεῖν ὄντας τοὺς μὲν ἐκβαλόντες, τοὺς δ’ ἀποκτείναντες, ὁ δ’ Εὐφραῖος ἐκεῖνος ἀπέσφαξεν ἑαυτόν, ἔργῳ μαρτυρήσας ὅτι καὶ δικαίως καὶ καθαρῶς ὑπὲρ τῶν πολιτῶν ἀνθειστήκει Φιλίππῳ.", "st": "9.62"}, {"sp": "N", "t": "τί οὖν ποτ’ αἴτιον, θαυμάζετ’ ἴσως, τὸ καὶ τοὺς Ὀλυνθίους καὶ τοὺς Ἐρετριέας καὶ τοὺς Ὠρείτας ἥδιον πρὸς τοὺς ὑπὲρ Φιλίππου λέγοντας ἔχειν ἢ τοὺς ὑπὲρ αὑτῶν; ὅπερ καὶ παρ’ ὑμῖν, ὅτι τοῖς μὲν ὑπὲρ τοῦ βελτίστου λέγουσιν οὐδὲ βουλομένοις ἔνεστιν ἐνίοτε πρὸς χάριν οὐδὲν εἰπεῖν· τὰ γὰρ πράγματ’ ἀνάγκη σκοπεῖν ὅπως σωθήσεται· οἱ δ’ ἐν αὐτοῖς οἷς χαρίζονται Φιλίππῳ συμπράττουσιν.", "st": "9.63"}, {"sp": "N", "t": "εἰσφέρειν ἐκέλευον, οἱ δ’ οὐδὲν δεῖν ἔφασαν· πολεμεῖν καὶ μὴ πιστεύειν, οἱ δ’ ἄγειν εἰρήνην, ἕως ἐγκατελήφθησαν. τἄλλα τὸν αὐτὸν τρόπον οἶμαι πάνθ’, ἵνα μὴ καθ’ ἕκαστα λέγω· οἱ μὲν ἐφ’ οἷς χαριοῦνται, ταῦτ’ ἔλεγον, οἱ δ’ ἐξ ὧν ἔμελλον σωθήσεσθαι. πολλὰ δὲ καὶ τὰ τελευταῖα οὐχ οὕτως πρὸς χάριν οὐδὲ δι’ ἄγνοιαν οἱ πολλοὶ προσίεντο, ἀλλ’ ὑποκατακλινόμενοι, ἐπειδὴ τοῖς ὅλοις ἡττᾶσθαι ἐνόμιζον.", "st": "9.64"}, {"sp": "N", "t": "ὃ νὴ τὸν Δία καὶ τὸν Ἀπόλλω δέδοικ’ ἐγὼ μὴ πάθηθ’ ὑμεῖς, ἐπειδὰν εἰδῆτ’ ἐκλογιζόμενοι μηδὲν ἔθ’ ὑμῖν ἐνόν. καίτοι μὴ γένοιτο μέν, ὦ ἄνδρες Ἀθηναῖοι, τὰ πράγματ’ ἐν τούτῳ· τεθνάναι δὲ μυριάκις κρεῖττον ἢ κολακείᾳ τι ποιῆσαι Φιλίππου καὶ προέσθαι τῶν ὑπὲρ ὑμῶν λεγόντων τινάς. καλήν γ’ οἱ πολλοὶ νῦν ἀπειλήφασιν Ὠρειτῶν χάριν, ὅτι τοῖς Φιλίππου φίλοις ἐπέτρεψαν αὑτούς, τὸν δ’ Εὐφραῖον ἐώθουν·", "st": "9.65"}, {"sp": "N", "t": "καλήν γ’ ὁ δῆμος ὁ Ἐρετριέων, ὅτι τοὺς ὑμετέρους πρέσβεις ἀπήλασε, Κλειτάρχῳ δ’ ἐνέδωκεν αὑτόν· δουλεύουσί γε μαστιγούμενοι καὶ σφαττόμενοι. καλῶς Ὀλυνθίων ἐφείσατο τῶν τὸν μὲν Λασθένην ἵππαρχον χειροτονησάντων, τὸν δ’ Ἀπολλωνίδην ἐκβαλόντων.", "st": "9.66"}, {"sp": "N", "t": "μωρία καὶ κακία τὰ τοιαῦτ’ ἐλπίζειν, καὶ κακῶς βουλευομένους καὶ μηδὲν ὧν προσήκει ποιεῖν ἐθέλοντας, ἀλλὰ τῶν ὑπὲρ τῶν ἐχθρῶν λεγόντων ἀκροωμένους, τηλικαύτην ἡγεῖσθαι πόλιν οἰκεῖν τὸ μέγεθος ὥστε ⟨μηδέν⟩, μηδ’ ἂν ὁτιοῦν ᾖ, δεινὸν πείσεσθαι.", "st": "9.67"}, {"sp": "N", "t": "καὶ μὴν ἐκεῖνό γ’ αἰσχρόν, ὕστερόν ποτ’ εἰπεῖν “τίς γὰρ ἂν ᾠήθη ταῦτα γενέσθαι; νὴ τὸν Δί’, ἔδει γὰρ τὸ καὶ τὸ ποιῆσαι καὶ τὸ μὴ ποιῆσαι.” πόλλ’ ἂν εἰπεῖν ἔχοιεν Ὀλύνθιοι νῦν, ἃ τότ’ εἰ προείδοντο, οὐκ ἂν ἀπώλοντο· πόλλ’ ἂν Ὠρεῖται, πολλὰ Φωκεῖς, πολλὰ τῶν ἀπολωλότων ἕκαστοι.", "st": "9.68"}, {"sp": "N", "t": "ἀλλὰ τί τούτων ὄφελος αὐτοῖς; ἕως ἂν σῴζηται τὸ σκάφος, ἄν τε μεῖζον ἄν τ’ ἔλαττον ᾖ, τότε χρὴ καὶ ναύτην καὶ κυβερνήτην καὶ πάντ’ ἄνδρ’ ἑξῆς προθύμους εἶναι, καὶ ὅπως μήθ’ ἑκὼν μήτ’ ἄκων μηδεὶς ἀνατρέψει, τοῦτο σκοπεῖσθαι· ἐπειδὰν δ’ ἡ θάλαττα ὑπέρσχῃ, μάταιος ἡ σπουδή.", "st": "9.69"}, {"sp": "N", "t": "καὶ ἡμεῖς τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, ἕως ἐσμὲν σῷοι, πόλιν μεγίστην ἔχοντες, ἀφορμὰς πλείστας, ἀξίωμα κάλλιστον, τί ποιῶμεν; πάλαι τις ἡδέως ἂν ἴσως ἐρωτήσας κάθηται. ἐγὼ νὴ Δί’ ἐρῶ, καὶ γράψω δέ, ὥστ’ ἂν βούλησθε χειροτονήσετε. αὐτοὶ πρῶτον ἀμυνόμενοι καὶ παρασκευαζόμενοι, τριήρεσι καὶ χρήμασι καὶ στρατιώταις λέγω· καὶ γὰρ ἂν ἅπαντες δήπου δουλεύειν συγχωρήσωσιν οἱ ἄλλοι, ἡμῖν γ’ ὑπὲρ τῆς ἐλευθερίας ἀγωνιστέον·", "st": "9.70"}, {"sp": "N", "t": "ταῦτα δὴ πάντ’ αὐτοὶ παρεσκευασμένοι καὶ ποιήσαντες φανερὰ τοὺς ἄλλους ἤδη παρακαλῶμεν, καὶ τοὺς ταῦτα διδάξοντας ἐκπέμπωμεν πρέσβεις πανταχοῖ, εἰς Πελοπόννησον, εἰς Ῥόδον, εἰς Χίον, ὡς βασιλέα λέγω (οὐδὲ γὰρ τῶν ἐκείνῳ συμφερόντων ἀφέστηκε τὸ μὴ τοῦτον ἐᾶσαι πάντα καταστρέψασθαι), ἵν’ ἐὰν μὲν πείσητε, κοινωνοὺς ἔχητε καὶ τῶν κινδύνων καὶ τῶν ἀναλωμάτων, ἄν τι δέῃ, εἰ δὲ μή, χρόνους γ’ ἐμποιῆτε τοῖς πράγμασιν.", "st": "9.71"}, {"sp": "N", "t": "ἐπειδὴ γάρ ἐστι πρὸς ἄνδρα καὶ οὐχὶ συνεστώσης πόλεως ἰσχὺν ὁ πόλεμος, οὐδὲ τοῦτ’ ἄχρηστον, οὐδ’ αἱ πέρυσιν πρεσβεῖαι περὶ τὴν Πελοπόννησον ἐκεῖναι καὶ κατηγορίαι, ἃς ἐγὼ καὶ Πολύευκτος ὁ βέλτιστος ἐκεινοσὶ καὶ Ἡγήσιππος καὶ οἱ ἄλλοι πρέσβεις περιήλθομεν, καὶ ἐποιήσαμεν ἐπισχεῖν ἐκεῖνον καὶ μήτ’ ἐπ’ Ἀμβρακίαν ἐλθεῖν μήτ’ εἰς Πελοπόννησον ὁρμῆσαι.", "st": "9.72"}, {"sp": "N", "t": "οὐ μέντοι λέγω μηδὲν αὐτοὺς ὑπὲρ αὑτῶν ἀναγκαῖον ἐθέλοντας ποιεῖν, τοὺς ἄλλους παρακαλεῖν· καὶ γὰρ εὔηθες τὰ οἰκεῖ’ αὐτοὺς προϊεμένους τῶν ἀλλοτρίων φάσκειν κήδεσθαι, καὶ τὰ παρόντα περιορῶντας ὑπὲρ τῶν μελλόντων τοὺς ἄλλους φοβεῖν. οὐ λέγω ταῦτα, ἀλλὰ τοῖς μὲν ἐν Χερρονήσῳ χρήματ’ ἀποστέλλειν φημὶ δεῖν καὶ τἄλλ’ ὅσ’ ἀξιοῦσι ποιεῖν, αὐτοὺς δὲ παρασκευάζεσθαι, τοὺς δ’ ἄλλους Ἕλληνας συγκαλεῖν, συνάγειν, διδάσκειν, νουθετεῖν· ταῦτ’ ἐστὶν πόλεως ἀξίωμ’ ἐχούσης ἡλίκον ὑμῖν ὑπάρχει.", "st": "9.73"}, {"sp": "N", "t": "εἰ δ’ οἴεσθε Χαλκιδέας τὴν Ἑλλάδα σώσειν ἢ Μεγαρέας, ὑμεῖς δ’ ἀποδράσεσθαι τὰ πράγματα, οὐκ ὀρθῶς οἴεσθε· ἀγαπητὸν γὰρ ἐὰν αὐτοὶ σῴζωνται τούτων ἑκάστοις. ἀλλ’ ὑμῖν τοῦτο πρακτέον· ὑμῖν οἱ πρόγονοι τοῦτο τὸ γέρας ἐκτήσαντο καὶ κατέλιπον μετὰ πολλῶν καὶ μεγάλων κινδύνων.", "st": "9.74"}, {"sp": "N", "t": "εἰ δ’ ὃ βούλεται ζητῶν ἕκαστος καθεδεῖται, καὶ ὅπως μηδὲν αὐτὸς ποιήσει σκοπῶν, πρῶτον μὲν οὐδὲ μήποθ’ εὕρῃ τοὺς ποιήσοντας, ἔπειτα δέδοιχ’ ὅπως μὴ πάνθ’ ἅμ’ ὅσ’ οὐ βουλόμεθα ποιεῖν ἡμῖν ἀνάγκη γενήσεται.", "st": "9.75"}, {"sp": "N", "t": "ἐγὼ μὲν δὴ ταῦτα λέγω, ταῦτα γράφω· καὶ οἴομαι καὶ νῦν ἔτ’ ἐπανορθωθῆναι ἂν τὰ πράγματα τούτων γιγνομένων. εἰ δέ τις ἔχει τούτων τι βέλτιον, λεγέτω καὶ συμβουλευέτω. ὅ τι δ’ ὑμῖν δόξει, τοῦτ’, ὦ πάντες θεοί, συνενέγκοι.", "st": "9.76"}, {"sp": "HDR", "t": "Κατὰ Φιλίππου Δʹ", "st": "10"}, {"sp": "N", "t": "καὶ σπουδαῖα νομίζων, ὦ ἄνδρες Ἀθηναῖοι, περὶ ὧν βουλεύεσθε, καὶ ἀναγκαῖα τῇ πόλει, πειράσομαι περὶ αὐτῶν εἰπεῖν ἃ νομίζω συμφέρειν. οὐκ ὀλίγων δ’ ὄντων ἁμαρτημάτων οὐδ’ ἐκ μικροῦ χρόνου συνειλεγμένων, ἐξ ὧν φαύλως ταῦτ’ ἔχει, οὐδέν ἐστιν, ὦ ἄνδρες Ἀθηναῖοι, τῶν πάντων δυσκολώτερον εἰς τὸ παρὸν ἢ ὅτι ταῖς γνώμαις ὑμεῖς ἀφεστήκατε τῶν πραγμάτων, καὶ τοσοῦτον χρόνον σπουδάζεθ’ ὅσον ἂν κάθησθ’ ἀκούοντες ἢ προσαγγελθῇ τι νεώτερον, εἶτ’ ἀπελθὼν ἕκαστος ὑμῶν οὐ μόνον οὐδὲν φροντίζει περὶ αὐτῶν, ἀλλ’ οὐδὲ μέμνηται.", "st": "10.1"}, {"sp": "N", "t": "ἡ μὲν οὖν ἀσέλγεια καὶ πλεονεξία, ᾗ πρὸς ἅπαντας ἀνθρώπους Φίλιππος χρῆται, τοσαύτη τὸ πλῆθος ὅσην ἀκούετε· ὅτι δ’ οὐκ ἔνι ταύτης ἐκεῖνον ἐπισχεῖν ἐκ λόγου καὶ δημηγορίας οὐδεὶς ἀγνοεῖ δήπου. καὶ γὰρ εἰ μηδ’ ἀφ’ ἑνὸς τῶν ἄλλων τοῦτο μαθεῖν δύναταί τις, ὡδὶ λογισάσθω. ἡμεῖς οὐδαμοῦ πώποτε, ὅπου περὶ τῶν δικαίων εἰπεῖν ἐδέησεν, ἡττήθημεν οὐδ’ ἀδικεῖν ἐδόξαμεν, ἀλλὰ πάντων πανταχοῦ κρατοῦμεν καὶ περίεσμεν τῷ λόγῳ.", "st": "10.2"}, {"sp": "N", "t": "ἆρ’ οὖν διὰ τοῦτ’ ἐκείνῳ φαύλως ἔχει τὰ πράγματα, ἢ τῇ πόλει καλῶς; πολλοῦ γε καὶ δεῖ· ἐπειδὰν γὰρ ὁ μὲν λαβὼν μετὰ ταῦτα βαδίζῃ τὰ ὅπλα, πᾶσιν τοῖς οὖσιν ἑτοίμως κινδυνεύσων, ἡμεῖς δὲ καθώμεθ’ εἰρηκότες τὰ δίκαια, οἱ δ’ ἀκηκοότες, εἰκότως, οἶμαι, τοὺς λόγους τἄργα παρέρχεται, καὶ προσέχουσιν ἅπαντες οὐχ οἷς εἴπομέν ποθ’ ἡμεῖς δικαίοις ἢ νῦν ἂν εἴποιμεν, ἀλλ’ οἷς ποιοῦμεν. ἔστι δὲ ταῦτ’ οὐδένα τῶν ἀδικουμένων σῴζειν δυνάμενα· οὐδὲν γὰρ δεῖ πλείω περὶ αὐτῶν λέγειν.", "st": "10.3"}, {"sp": "N", "t": "τοιγάρτοι διεστηκότων εἰς δύο ταῦτα τῶν ἐν ταῖς πόλεσι, τῶν μὲν εἰς τὸ μήτ’ ἄρχειν βίᾳ βούλεσθαι μηδενὸς μήτε δουλεύειν ἄλλῳ, ἀλλ’ ἐν ἐλευθερίᾳ καὶ νόμοις ἐξ ἴσου πολιτεύεσθαι, τῶν δ’ εἰς τὸ ἄρχειν μὲν τῶν πολιτῶν ἐπιθυμεῖν, ἑτέρῳ δ’ ὑπακούειν, δι’ ὅτου ποτ’ ἂν οἴωνται τοῦτο δυνήσεσθαι ποιῆσαι, οἱ τῆς ἐκείνου προαιρέσεως, οἱ τυραννίδων καὶ δυναστειῶν ἐπιθυμοῦντες, κεκρατήκασι πανταχοῦ, καὶ πόλις δημοκρατουμένη βεβαίως οὐκ οἶδ’ εἴ τίς ἐστι τῶν πασῶν λοιπὴ πλὴν ἡ ἡμετέρα.", "st": "10.4"}, {"sp": "N", "t": "καὶ κεκρατήκασιν οἱ δι’ ἐκείνου τὰς πολιτείας ποιούμενοι πᾶσιν ὅσοις πράγματα πράττεται, πρώτῳ μὲν πάντων καὶ πλείστῳ τῷ τοῖς βουλομένοις χρήματα λαμβάνειν ἔχειν τὸν δώσονθ’ ὑπὲρ αὑτῶν, δευτέρῳ δὲ καὶ οὐδὲν ἐλάττονι τούτου τῷ δύναμιν τὴν καταστρεψομένην τοὺς ἐναντιουμένους αὐτοῖς ἐν οἷς ἂν αἰτήσωσι χρόνοις παρεῖναι.", "st": "10.5"}, {"sp": "N", "t": "ἡμεῖς δ’ οὐ μόνον τούτοις ὑπολειπόμεθ’, ὦ ἄνδρες Ἀθηναῖοι, ἀλλ’ οὐδ’ ἀνεγερθῆναι δυνάμεθα, ἀλλὰ μανδραγόραν πεπωκόσιν ἤ τι φάρμακον ἄλλο τοιοῦτον ἐοίκαμεν ἀνθρώποις· εἶτ’, οἶμαι, (δεῖ γάρ, ὡς ἐγὼ κρίνω, λέγειν τἀληθῆ) οὕτω διαβεβλήμεθα καὶ καταπεφρονήμεθ’ ἐκ τούτων ὥστε τῶν ἐν αὐτῷ τῷ κινδυνεύειν ὄντων οἱ μὲν ὑπὲρ τῆς ἡγεμονίας ἡμῖν ἀντιλέγουσιν, οἱ δ’ ὑπὲρ τοῦ ποῦ συνεδρεύσουσι, τινὲς δὲ καθ’ αὑτοὺς ἀμύνεσθαι μᾶλλον ἢ μεθ’ ἡμῶν ἐγνώκασιν.", "st": "10.6"}, {"sp": "N", "t": "τοῦ χάριν δὴ ταῦτα λέγω καὶ διεξέρχομαι; οὐ γὰρ ἀπεχθάνεσθαι μὰ τὸν Δία καὶ πάντας θεοὺς προαιροῦμαι. ἵν’ ὑμῶν ἕκαστος, ὦ ἄνδρες Ἀθηναῖοι, τοῦτο γνῷ καὶ εἰδῇ, ὅτι ἡ καθ’ ἡμέραν ῥᾳστώνη καὶ ῥᾳθυμία, ὥσπερ τοῖς ἰδίοις βίοις, οὕτω καὶ ταῖς πόλεσιν οὐκ ἐφ’ ἑκάστου τῶν ἀμελουμένων ποιεῖ τὴν αἴσθησιν εὐθέως, ἀλλ’ ἐπὶ τῷ κεφαλαίῳ τῶν πραγμάτων ἀπαντᾷ.", "st": "10.7"}, {"sp": "N", "t": "ὁρᾶτε Σέρριον καὶ Δορίσκον· ταῦτα γὰρ πρῶτον ὠλιγωρήθη μετὰ τὴν εἰρήνην, ἃ πολλοῖς ὑμῶν οὐδὲ γνώριμ’ ἐστὶν ἴσως. ταῦτα μέντοι τότ’ ἐαθέντα καὶ παροφθέντ’ ἀπώλεσε Θρᾴκην καὶ Κερσοβλέπτην, σύμμαχον ὄνθ’ ὑμῶν. πάλιν ταῦτ’ ἀμελούμεν’ ἰδὼν καὶ οὐδεμιᾶς βοηθείας τυγχάνοντα παρ’ ὑμῶν κατέσκαπτε Πορθμόν, καὶ τυραννίδ’ ἀπαντικρὺ τῆς Ἀττικῆς ἐπετείχισεν ὑμῖν ἐν τῇ Εὐβοίᾳ.", "st": "10.8"}, {"sp": "N", "t": "ταύτης ὀλιγωρουμένης, Μέγαρ’ ἑάλω παρὰ μικρόν. οὐδὲν ἐφροντίσατ’ οὐδ’ ἐπεστράφητ’ οὐδὲν τούτων, οὐδ’ ἐνεδείξασθε τοῦθ’ ὅτι οὐκ ἐπιτρέψετε τοῦτο ποιεῖν αὐτῷ· Ἀντρῶνας ἐπρίατο καὶ μετ’ οὐ πολὺν χρόνον τὰ ἐν Ὠρεῷ πράγματ’ εἰλήφει.", "st": "10.9"}, {"sp": "N", "t": "πολλὰ δὲ καὶ παραλείπω, Φεράς, τὴν ἐπ’ Ἀμβρακίαν ὁδόν, τὰς ἐν Ἤλιδι σφαγάς, ἄλλα μυρία· οὐ γὰρ ἵν’ ἐξαριθμήσωμαι τοὺς βεβιασμένους καὶ τοὺς ἠδικημένους ὑπὸ Φιλίππου, ταῦτα διεξῆλθον, ἀλλ’ ἵνα τοῦθ’ ὑμῖν δείξω, ὅτι οὐ στήσεται πάντας ἀνθρώπους ἀδικῶν, τὰ δ’ ὑφ’ αὑτῷ ποιούμενος Φίλιππος, εἰ μή τις αὐτὸν κωλύσει.", "st": "10.10"}, {"sp": "N", "t": "εἰσὶν δέ τινες οἳ πρὶν ἀκοῦσαι τοὺς ὑπὲρ τῶν πραγμάτων λόγους εὐθέως εἰώθασιν ἐρωτᾶν “τί οὖν χρὴ ποιεῖν;” οὐχ ἵν’ ἀκούσαντες ποιήσωσι (χρησιμώτατοι γὰρ ἂν ἦσαν ἁπάντων), ἀλλ’ ἵνα τοῦ λέγοντος ἀπαλλαγῶσιν. δεῖ δ’ ὅμως εἰπεῖν ὅ τι χρὴ ποιεῖν. πρῶτον μέν, ὦ ἄνδρες Ἀθηναῖοι, τοῦτο παρ’ ὑμῖν αὐτοῖς βεβαίως γνῶναι, ὅτι τῇ πόλει Φίλιππος πολεμεῖ καὶ τὴν εἰρήνην λέλυκεν, καὶ κακόνους μέν ἐστι καὶ ἐχθρὸς ὅλῃ τῇ πόλει καὶ τῷ τῆς πόλεως ἐδάφει, προσθήσω δὲ καὶ τοῖς ἐν τῇ πόλει θεοῖς, οἵπερ αὐτὸν ἐξολέσειαν, οὐδενὶ μέντοι μᾶλλον ἢ τῇ πολιτείᾳ πολεμεῖ οὐδ’ ἐπιβουλεύει, καὶ σκοπεῖ μᾶλλον οὐδὲν τῶν πάντων ἢ πῶς ταύτην καταλύσει.", "st": "10.11"}, {"sp": "N", "t": "καὶ τοῦτ’ ἐξ ἀνάγκης τρόπον τινὰ νῦν γε δὴ ποιεῖ. λογίζεσθε γάρ. ἄρχειν βούλεται, τούτου δ’ ἀνταγωνιστὰς μόνους ὑπείληφεν ὑμᾶς. ἀδικεῖ πολὺν χρόνον ἤδη, καὶ τοῦτ’ αὐτὸς ἄριστα σύνοιδεν αὑτῷ· οἷς γὰρ οὖσιν ὑμετέροις ἔχει [χρῆσθαι], τούτοις ἅπαντα τἄλλα βεβαίως κέκτηται· εἰ γὰρ Ἀμφίπολιν καὶ Ποτείδαιαν προεῖτο, οὐδ’ ἂν ἐν Μακεδονίᾳ μένειν ἀσφαλῶς ἐδύνατο.", "st": "10.12"}, {"sp": "N", "t": "ἀμφότερ’ οὖν οἶδε, καὶ αὑτὸν ὑμῖν ἐπιβουλεύοντα καὶ ὑμᾶς αἰσθανομένους· εὖ φρονεῖν δ’ ὑμᾶς ὑπολαμβάνων μισεῖν αὑτὸν ἡγεῖται. πρὸς δὲ τούτοις τοσούτοις οὖσιν οἶδεν ἀκριβῶς ὅτι, οὐδ’ ἂν ἁπάντων τῶν ἄλλων γένηται κύριος, οὐδὲν ἔστ’ αὐτῷ βεβαίως ἔχειν, ἕως ἂν ὑμεῖς δημοκρατῆσθε, ἀλλ’ ἄν ποτε συμβῇ τι πταῖσμα (πολλὰ δ’ ἂν γένοιτ’ ἀνθρώπῳ), ἥξει πάντα τὰ νῦν βεβιασμένα καὶ καταφεύξεται πρὸς ὑμᾶς.", "st": "10.13"}, {"sp": "N", "t": "ἐστὲ γὰρ ὑμεῖς οὐκ αὐτοὶ πλεονεκτῆσαι καὶ κατασχεῖν ἀρχὴν εὖ πεφυκότες, ἀλλ’ ἕτερον λαβεῖν κωλῦσαι καὶ ἔχοντ’ ἀφελέσθαι καὶ ὅλως ἐνοχλῆσαι τοῖς ἄρχειν βουλομένοις καὶ πάντας ἀνθρώπους εἰς ἐλευθερίαν ἐξελέσθαι δεινοί. οὔκουν βούλεται τοῖς αὑτοῦ καιροῖς τὴν παρ’ ὑμῶν ἐλευθερίαν ἐφεδρεύειν, οὐ κακῶς οὐδ’ ἀργῶς ταῦτα λογιζόμενος.", "st": "10.14"}, {"sp": "N", "t": "πρῶτον μὲν δὴ τοῦτο δεῖ, ἐχθρὸν ὑπειληφέναι τῆς πολιτείας καὶ τῆς δημοκρατίας ἀδιάλλακτον ἐκεῖνον, δεύτερον δ’ εἰδέναι σαφῶς ὅτι πάνθ’ ὅσα πραγματεύεται καὶ κατασκευάζεται νῦν, ἐπὶ τὴν ἡμετέραν πόλιν παρασκευάζεται. οὐ γὰρ οὕτως εὐήθης ὑμῶν ἐστὶν οὐδεὶς ὥσθ’ ὑπολαμβάνειν τὸν Φίλιππον τῶν μὲν ἐν Θρᾴκῃ κακῶν (τί γὰρ ἂν ἄλλο τις εἴποι Δρογγίλον καὶ Καβύλην καὶ Μάστειραν καὶ ἃ νῦν φασιν αὐτὸν ἔχειν;) τούτων μὲν ἐπιθυμεῖν καὶ ὑπὲρ τοῦ ταῦτα λαβεῖν καὶ πόνους καὶ χειμῶνας καὶ τοὺς ἐσχάτους κινδύνους ὑπομένειν,", "st": "10.15"}, {"sp": "N", "t": "τῶν δ’ Ἀθηναίων λιμένων καὶ νεωρίων καὶ τριήρων καὶ τόπου καὶ δόξης, ὧν μήτ’ ἐκείνῳ μήτ’ ἄλλῳ γένοιτο μηδενὶ χειρωσαμένῳ τὴν πόλιν τὴν ἡμετέραν κυριεῦσαι, οὐκ ἐπιθυμεῖν, ἀλλὰ ταῦτα μὲν ὑμᾶς ἐάσειν ἔχειν, ὑπὲρ δὲ τῶν μελινῶν καὶ τῶν ὀλυρῶν τῶν ἐν τοῖς Θρᾳκίοις σιροῖς ἐν τῷ βαράθρῳ χειμάζειν.", "st": "10.16"}, {"sp": "N", "t": "οὐκ ἔστι ταῦτα, ἀλλὰ κἀκεῖν’ ὑπὲρ τοῦ τούτων γίγνεσθαι κύριος καὶ τἄλλα πάντα πραγματεύεται. ταῦτα τοίνυν ἕκαστον εἰδότα καὶ γιγνώσκοντα παρ’ αὑτῷ δεῖ μὰ Δί’ οὐ γράψαι κελεύειν πόλεμον τὸν τὰ βέλτιστ’ ἐπὶ πᾶσι δικαίοις συμβουλεύοντα· τοῦτο μὲν γάρ ἐστι λαβεῖν ὅτῳ πολεμήσετε βουλομένων, οὐχ ἃ τῇ πόλει συμφέρει πράττειν.", "st": "10.17"}, {"sp": "N", "t": "ὁρᾶτε γάρ. εἰ δι’ ἃ πρῶτα παρεσπόνδησε Φίλιππος ἢ δεύτερ’ ἢ τρίτα (πολλὰ γάρ ἐστιν ἐφεξῆς) ἔγραψέ τις αὐτῷ πολεμεῖν, ὁ δ’ ὁμοίως ὥσπερ νῦν, οὐ γράφοντος οὐδενὸς ὑμῶν πόλεμον, Καρδιανοῖς ἐβοήθει, οὐκ ἂν ἀνηρπασμένος ἦν ὁ γράψας, καὶ διὰ τοῦτο πάντες ᾐτιῶντ’ ἂν αὐτὸν Καρδιανοῖς βεβοηθηκέναι;", "st": "10.18"}, {"sp": "N", "t": "μὴ τοίνυν ζητεῖθ’ ὅντιν’ ἀνθ’ ὧν Φίλιππος ἐξαμαρτάνει μισήσετε καὶ τοῖς παρ’ ἐκείνου μισθαρνοῦσι διασπάσασθαι παραβαλεῖτε· μηδ’ αὐτοὶ χειροτονήσαντες πόλεμον βούλεσθε παρ’ αὐτοῖς ὑμῖν ἐρίζειν, εἰ δέον ἢ μὴ δέον ὑμᾶς τοῦτο πεποιηκέναι· ἀλλ’ ὃν ἐκεῖνος πολεμεῖ τρόπον, τοῦτον μιμεῖσθε, τοῖς μὲν ἀμυνομένοις ἤδη χρήματα καὶ τἄλλ’ ὅσων δέονται διδόντες, αὐτοὶ δ’ εἰσφέροντες, ὦ ἄνδρες Ἀθηναῖοι, καὶ κατασκευαζόμενοι στράτευμα, τριήρεις ταχείας, ἵππους, ἱππαγωγούς, τἄλλ’ ὅσ’ εἰς πόλεμον·", "st": "10.19"}, {"sp": "N", "t": "ἐπεὶ νῦν γε γέλως ἔσθ’ ὡς χρώμεθα τοῖς πράγμασι, καὶ Φίλιππον δ’ αὐτὸν οὐδὲν ἂν ἄλλ’ οἶμαι μὰ τοὺς θεοὺς εὔξασθαι ποιεῖν τὴν πόλιν ἢ ταῦθ’ ἃ νῦν ποιεῖτε· ὑστερίζετε, ἀναλίσκετε· ὅτῳ παραδώσετε τὰ πράγματα ζητεῖτε, δυσχεραίνετε· ἀλλήλους αἰτιᾶσθε. ἀφ’ οὗ δὲ ταῦτα γίγνεται ἐγὼ διδάξω, καὶ ὅπως παύσεται λέξω.", "st": "10.20"}, {"sp": "N", "t": "οὐδὲν πώποτ’, ὦ ἄνδρες Ἀθηναῖοι, τῶν πραγμάτων ἐξ ἀρχῆς ἐνεστήσασθ’ οὐδὲ κατεσκευάσασθ’ ὀρθῶς, ἀλλὰ τὸ συμβαῖνον ἀεὶ διώκετε, εἶτ’ ἐπειδὰν ὑστερίσητε παύεσθε· ἕτερον πάλιν ἂν συμβῇ τι παρασκευάζεσθε καὶ θορυβεῖσθε.", "st": "10.21"}, {"sp": "N", "t": "τὸ δ’ οὐχ οὕτως ἔχει· οὐκ ἔνεστι βοηθείαις χρωμένους οὐδὲν τῶν δεόντων ποτὲ πρᾶξαι, ἀλλὰ κατασκευάσαντας δεῖ δύναμιν, καὶ τροφὴν ταύτῃ πορίσαντας καὶ ταμίας καὶ δημοσίους, καὶ ὅπως ἔνι τὴν τῶν χρημάτων φυλακὴν ἀκριβεστάτην γενέσθαι, οὕτω ποιήσαντας, τὸν μὲν τῶν χρημάτων λόγον παρὰ τούτων λαμβάνειν, τὸν δὲ τῶν ἔργων παρὰ τοῦ στρατηγοῦ, καὶ μηδεμίαν πρόφασιν τοῦ πλεῖν ἄλλοσε ἢ πράττειν ἄλλο τι τῷ στρατηγῷ καταλείπειν.", "st": "10.22"}, {"sp": "N", "t": "ἂν οὕτω ποιήσητε καὶ τοῦτ’ ἐθελήσηθ’ ὡς ἀληθῶς, ἄγειν εἰρήνην δικαίαν καὶ μένειν ἐπὶ τοῦ τόπου Φίλιππον ἀναγκάσετε, ἢ πολεμήσετ’ ἐξ ἴσου· καὶ ἴσως ἄν, ἴσως, ὥσπερ νῦν ὑμεῖς πυνθάνεσθε τί ποιεῖ Φίλιππος καὶ ποῖ πορεύεται, οὕτως ἂν ἐκεῖνος φροντίσαι ποῖ ποθ’ ἡ τῆς πόλεως ἀπῆρκεν δύναμις καὶ ποῦ φανήσεται.", "st": "10.23"}, {"sp": "N", "t": "εἰ δέ τῳ δοκεῖ ταῦτα καὶ δαπάνης πολλῆς καὶ πόνων πολλῶν καὶ πραγματείας εἶναι, καὶ μάλ’ ὀρθῶς δοκεῖ· ἀλλ’ ἐὰν λογίσηται τὰ τῇ πόλει μετὰ ταῦτα γενησόμενα, ἐὰν ταῦτα μὴ ἐθέλῃ ποιεῖν, εὑρήσει λυσιτελοῦν τὸ ἑκόντας ποιεῖν τὰ δέοντα. εἰ μὲν γάρ ἐστί τις ἐγγυητὴς ὑμῖν θεῶν (οὐ γὰρ ἀνθρώπων γ’ οὐδεὶς ἂν γένοιτ’ ἀξιόχρεως τηλικούτου πράγματος) ὡς, ἐὰν ἄγηθ’ ἡσυχίαν καὶ ἅπαντα προῆσθε, οὐκ ἐπ’ αὐτοὺς ὑμᾶς τελευτῶν ἐκεῖνος ἥξει,", "st": "10.24"}, {"sp": "N", "t": "αἰσχρὸν μὲν νὴ τὸν Δία καὶ πάντας θεοὺς καὶ ἀνάξιον ὑμῶν καὶ τῶν ὑπαρχόντων τῇ πόλει καὶ πεπραγμένων τοῖς προγόνοις, τῆς ἰδίας ῥᾳθυμίας ἕνεκα τοὺς ἄλλους ἅπαντας Ἕλληνας εἰς δουλείαν προέσθαι, καὶ ἔγωγε αὐτὸς μὲν τεθνάναι μᾶλλον ἂν ἢ ταῦτ’ εἰρηκέναι βουλοίμην·", "st": "10.25"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ εἴ τις ἄλλος λέγει καὶ ὑμᾶς πείθει, ἔστω, μὴ ἀμύνεσθε, ἅπαντα πρόεσθε. εἰ δὲ μηδενὶ τοῦτο δοκεῖ, τοὐναντίον δὲ πρόϊσμεν ἅπαντες ὅτι, ὅσῳ ἂν πλειόνων ἐάσωμεν ἐκεῖνον γενέσθαι κύριον, τοσούτῳ χαλεπωτέρῳ καὶ ἰσχυροτέρῳ χρησόμεθ’ ἐχθρῷ, ποῖ ἀναδυόμεθα, ἢ τί μέλλομεν; ἢ πότ’, ὦ ἄνδρες Ἀθηναῖοι, τὰ δέοντα ποιεῖν ἐθελήσομεν; ὅταν νὴ Δί’ ἀναγκαῖον ᾖ.", "st": "10.26"}, {"sp": "N", "t": "ἀλλ’ ἣν μὲν ἄν τις ἐλευθέρων ἀνθρώπων ἀνάγκην εἴποι, οὐ μόνον ἤδη πάρεστιν, ἀλλὰ καὶ πάλαι παρελήλυθε, τὴν δὲ τῶν δούλων ἀπεύχεσθαι δήπου μὴ γενέσθαι δεῖ. διαφέρει δὲ τί; ὅτι ἐστὶν ἐλευθέρῳ μὲν ἀνθρώπῳ μεγίστη ἀνάγκη ἡ ὑπὲρ τῶν γιγνομένων αἰσχύνη, καὶ μείζω ταύτης οὐκ οἶδ’ ἥντιν’ ἂν εἴποι τις· δούλῳ δὲ πληγαὶ χὠ τοῦ σώματος αἰκισμός, ὃ μήτε γένοιτο οὔτε λέγειν ἄξιον.", "st": "10.27"}, {"sp": "N", "t": "τὸ μὲν τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, πρὸς τὰ τοιαῦτ’ ὀκνηρῶς διακεῖσθαι, ἃ δεῖ τοῖς σώμασι καὶ ταῖς οὐσίαις λῃτουργῆσαι ἕκαστον, ἐστὶ μὲν οὐκ ὀρθῶς ἔχον, οὐδὲ πολλοῦ δεῖ, οὐ μὴν ἀλλ’ ἔχει τινὰ πρόφασιν ὅμως· τὸ δὲ μηδ’ ὅσ’ ἀκοῦσαι δεῖ μηδ’ ὅσα βουλεύσασθαι προσήκει, μηδὲ ταῦτ’ ἐθέλειν [ἀκούειν], τοῦτ’ ἤδη πᾶσαν ἐπιδέχεται κατηγορίαν.", "st": "10.28"}, {"sp": "N", "t": "ὑμεῖς τοίνυν οὐκ ἀκούειν, πρὶν ἂν ὥσπερ νῦν αὐτὰ παρῇ τὰ πράγματα, οὐχὶ βουλεύεσθαι περὶ οὐδενὸς εἰώθατ’ ἐφ’ ἡσυχίας, ἀλλ’ ὅταν μὲν ἐκεῖνος παρασκευάζηται, ἀμελήσαντες τοῦ ποιεῖν ταὐτὸ καὶ ἀντιπαρασκευάζεσθαι ῥᾳθυμεῖτε, καὶ ἄν τι λέγῃ τις, ἐκβάλλετε, ἐπειδὰν δ’ ἀπολωλὸς ἢ πολιορκούμενόν τι πύθησθε, ἀκροᾶσθε καὶ παρασκευάζεσθε·", "st": "10.29"}, {"sp": "N", "t": "ἦν δ’ ἀκηκοέναι μὲν καὶ βεβουλεῦσθαι τότε καιρός, ὅθ’ ὑμεῖς οὐκ ἠθέλετε, πράττειν δὲ καὶ χρῆσθαι τοῖς παρεσκευασμένοις νῦν, ἡνίκ’ ἀκούετε. τοιγαροῦν ἐκ τῶν τοιούτων ἐθῶν μόνοι τῶν πάντων ἀνθρώπων ὑμεῖς τοῖς ἄλλοις τοὐναντίον ποιεῖτε· οἱ μὲν γὰρ ἄλλοι πρὸ τῶν πραγμάτων εἰώθασι χρῆσθαι τῷ βουλεύεσθαι, ὑμεῖς δὲ μετὰ τὰ πράγματα.", "st": "10.30"}, {"sp": "N", "t": "ὃ δὴ λοιπόν ἐστι, καὶ πάλαι μὲν ἔδει, διαφεύγει δ’ οὐδὲ νῦν, τοῦτ’ ἐρῶ. οὐδενὸς τῶν πάντων οὕτως ὡς χρημάτων δεῖ τῇ πόλει πρὸς τὰ νῦν ἐπιόντα πράγματα. συμβέβηκε δ’ εὐτυχήματ’ ἀπὸ ταὐτομάτου, οἷς ἂν χρησώμεθ’ ὀρθῶς, ἴσως ἂν γένοιτο τὰ δέοντα. πρῶτον μὲν γὰρ οἷς βασιλεὺς πιστεύει καὶ εὐεργέτας ὑπείληφεν ἑαυτοῦ, οὗτοι μισοῦσι καὶ πολεμοῦσι Φίλιππον.", "st": "10.31"}, {"sp": "N", "t": "ἔπειθ’ ὁ πράττων καὶ συνειδὼς ἅπανθ’ ἃ Φιλλιππος κατὰ βασιλέως παρασκευάζεται, οὗτος ἀνάσπαστος γέγονε, καὶ πάσας τὰς πράξεις βασιλεὺς οὐχ ἡμῶν κατηγορούντων ἀκούσεται, οὓς ὑπὲρ τοῦ συμφέροντος ἂν ἡγήσαιτο τοῦ ἰδίου λέγειν, ἀλλὰ τοῦ πράξαντος αὐτοῦ καὶ διοικοῦντος, ὥστ’ εἶναι πιστάς, καὶ λοιπὸν λόγον εἶναι τοῖς παρ’ ὑμῶν πρέσβεσιν, ὃν βασιλεὺς ἥδιστ’ ἂν ἀκούσαι,", "st": "10.32"}, {"sp": "N", "t": "ὡς τὸν ἀμφοτέρους ἀδικοῦντα κοινῇ τιμωρήσασθαι δεῖ, καὶ ὅτι πολὺ τῷ βασιλεῖ φοβερώτερός ἐσθ’ ὁ Φίλιππος, ἂν προτέροις ἡμῖν ἐπιθῆται· εἰ γὰρ ἐγκαταλειπόμενοί τι πεισόμεθ’ ἡμεῖς, ἀδεῶς ἐπ’ ἐκεῖνον ἤδη πορεύσεται. ὑπὲρ δὴ τούτων ἁπάντων οἶμαι δεῖν ὑμᾶς πρεσβείαν ἐκπέμπειν, ἥτις τῷ βασιλεῖ διαλέξεται, καὶ τὴν ἀβελτερίαν ἀποθέσθαι, δι’ ἣν πολλάκις ἠλαττώθητε, “ὁ δὴ βάρβαρος, καὶ ὁ κοινὸς ἅπασιν ἐχθρός,” καὶ πάντα τὰ τοιαῦτα.", "st": "10.33"}, {"sp": "N", "t": "ἐγὼ γὰρ ὅταν τιν’ ἴδω τὸν μὲν ἐν Σούσοις καὶ Ἐγβατάνοις δεδοικότα καὶ κακόνουν εἶναι τῇ πόλει φάσκοντα, ὃς καὶ πρότερον συνεπηνώρθωσε τὰ τῆς πόλεως πράγματα καὶ νῦν ἐπηγγέλλετο (εἰ δὲ μὴ ἐδέχεσθ’ ὑμεῖς, ἀλλ’ ἀπεψηφίζεσθε, οὐ τἀκείνου αἴτια), ὑπὲρ δὲ τοῦ ἐπὶ ταῖς θύραις ἐγγὺς οὑτωσὶ ἐν μέσῃ τῇ Ἑλλάδι αὐξανομένου λῃστοῦ τῶν Ἑλλήνων ἄλλο τι λέγοντα, θαυμάζω, καὶ δέδοικα τοῦτον, ὅστις ἂν ᾖ ποτ’, ἔγωγε, ἐπειδὴ οὐχ οὗτος Φίλιππον.", "st": "10.34"}, {"sp": "N", "t": "ἔστι τοίνυν τι πρᾶγμα καὶ ἄλλο, ὃ λυμαίνεται τὴν πόλιν ὑπὸ βλασφημίας ἀδίκου καὶ λόγων οὐ προσηκόντων διαβεβλημένον, εἶτα τοῖς μηδὲν τῶν ἐν τῇ πολιτείᾳ δικαίων βουλομένοις ποιεῖν πρόφασιν παρέχει· καὶ πάντων, ὅσ’ ἐκλείπει, δέον παρά του γίγνεσθαι, ἐπὶ τοῦθ’ εὑρήσετε τὴν αἰτίαν ἀναφερομένην. περὶ οὗ πάνυ μὲν φοβοῦμαι, οὐ μὴν ἀλλ’ ἐρῶ·", "st": "10.35"}, {"sp": "N", "t": "οἶμαι γὰρ ἕξειν καὶ ὑπὲρ τῶν ἀπόρων τὰ δίκαι’ ἐπὶ τῷ συμφέροντι τῆς πόλεως εἰπεῖν πρὸς τοὺς εὐπόρους, καὶ ὑπὲρ τῶν κεκτημένων τὰς οὐσίας πρὸς τοὺς ἐπιδεεῖς. εἰ ἀνέλοιμεν ἐκ μέσου καὶ τὰς βλασφημίας ἃς ἐπὶ τῷ θεωρικῷ ποιοῦνταί τινες οὐχὶ δικαίως, καὶ τὸν φόβον, ὡς οὐ στήσεται τοῦτ’ ἄνευ μεγάλου τινὸς κακοῦ, οὐδὲν ἂν εἰς τὰ πράγματα μεῖζον εἰσενεγκαίμεθα, οὐδ’ ὅ τι κοινῇ μᾶλλον ἂν ὅλην ἐπιρρώσειε τὴν πόλιν.", "st": "10.36"}, {"sp": "N", "t": "οὑτωσὶ δὲ σκοπεῖτε· ἐρῶ δ’ ὑπὲρ τῶν ἐν χρείᾳ δοκούντων εἶναι πρότερον. ἦν ποτ’ οὐ πάλαι παρ’ ὑμῖν, ὅτ’ οὐ προσῄει τῇ πόλει τάλανθ’ ὑπὲρ τριάκοντα καὶ ἑκατόν· καὶ οὐδεὶς [ἐστι] τῶν τριηραρχεῖν δυναμένων οὐδὲ τῶν εἰσφέρειν ὅστις οὐκ ἠξίου τὰ καθήκοντ’ ἐφ’ ἑαυτὸν ποιεῖν, ὅτι χρήματ’ οὐ περιῆν, ἀλλὰ καὶ τριήρεις ἔπλεον καὶ χρήματ’ ἐγίγνετο καὶ πάντ’ ἐποιοῦμεν τὰ δέοντα.", "st": "10.37"}, {"sp": "N", "t": "μετὰ ταῦθ’ ἡ τύχη, καλῶς ποιοῦσα, πολλὰ πεποίηκε τὰ κοινά, καὶ τετρακόσι’ ἀντὶ τῶν ἑκατὸν ταλάντων προσέρχεται, οὐδενὸς οὐδὲν ζημιουμένου τῶν τὰς οὐσίας ἐχόντων, ἀλλὰ καὶ προσλαμβάνοντος· οἱ γὰρ εὔποροι πάντες ἔρχονται μεθέξοντες τούτου, καὶ καλῶς ποιοῦσιν.", "st": "10.38"}, {"sp": "N", "t": "τί οὖν μαθόντες τοῦτ’ ὀνειδίζομεν ἀλλήλοις καὶ προφάσει χρώμεθα τοῦ μηδὲν ποιεῖν, πλὴν εἰ τῇ παρὰ τῆς τύχης βοηθείᾳ γεγονυίᾳ τοῖς ἀπόροις φθονοῦμεν;", "st": "10.39"}, {"sp": "N", "t": "οὓς οὔτ’ ἂν αἰτιασαίμην ἔγωγε, οὔτ’ ἀξιῶ. οὐδὲ γὰρ ἐν ταῖς ἰδίαις οἰκίαις ὁρῶ τὸν ἐν ἡλικίᾳ πρὸς τοὺς πρεσβυτέρους οὕτω διακείμενον οὐδ’ οὕτως ἀγνώμον’ οὐδ’ ἄτοπον τῶν ὄντων οὐδένα, ὥστε, εἰ μὴ ποιήσουσιν ἅπαντες ὅσ’ ἂν αὐτός, οὐ φάσκοντα ποιήσειν οὐδὲν οὐδ’ αὐτόν· καὶ γὰρ ἂν τοῖς τῆς κακώσεως εἴη νόμοις οὕτω γ’ ἔνοχος· δεῖ γάρ, οἶμαι, τοῖς γονεῦσι τὸν ὡρισμένον ἐξ ἀμφοτέρων ἔρανον, καὶ παρὰ τῆς φύσεως καὶ παρὰ τοῦ νόμου, δικαίως φέρειν καὶ ἑκόνθ’ ὑποτελεῖν.", "st": "10.40"}, {"sp": "N", "t": "ὥσπερ τοίνυν ἑνὸς ἡμῶν ἑκάστου τίς ἐστι γονεύς, οὕτω συμπάσης τῆς πόλεως κοινοὺς δεῖ τοὺς γονέας σύμπαντας ἡγεῖσθαι, καὶ προσήκειν τούτους οὐχ ὅπως ὧν ἡ πόλις δίδωσ’ ἀφελέσθαι τι, ἀλλ’ εἰ καὶ μηδὲν ἦν τούτων, ἄλλοθεν σκοπεῖν ὅπως μηδενὸς ὄντες ἐνδεεῖς περιοφθήσονται.", "st": "10.41"}, {"sp": "N", "t": "τοὺς μὲν τοίνυν εὐπόρους ταύτῃ χρωμένους τῇ γνώμῃ οὐ μόνον ἡγοῦμαι τὰ δίκαι’ ἂν ποιεῖν, ἀλλὰ καὶ τὰ λυσιτελῆ· τὸ γὰρ τῶν ἀναγκαίων τιν’ ἀποστερεῖν κοινῇ κακόνους ἐστὶ ποιεῖν πολλοὺς ἀνθρώπους τοῖς πράγμασι· τοῖς δ’ ἐν ἐνδείᾳ, δι’ ὃ δυσχεραίνουσι τὸ πρᾶγμ’ οἱ τὰς οὐσίας ἔχοντες καὶ κατηγοροῦσι δικαίως, τοῦτ’ ἀφελεῖν ἂν συμβουλεύσαιμι.", "st": "10.42"}, {"sp": "N", "t": "δίειμι δέ, ὥσπερ ἄρτι, τὸν αὐτὸν τρόπον καὶ ὑπὲρ τῶν εὐπόρων, οὐ κατοκνήσας εἰπεῖν τἀληθῆ. ἐμοὶ γὰρ οὐδεὶς οὕτως ἄθλιος οὐδ’ ὠμὸς εἶναι δοκεῖ τὴν γνώμην, οὔκουν Ἀθηναίων γε, ὥστε λυπεῖσθαι ταῦτα λαμβάνοντας ὁρῶν τοὺς ἀπόρους καὶ τῶν ἀναγκαίων ἐνδεεῖς ὄντας.", "st": "10.43"}, {"sp": "N", "t": "ἀλλὰ ποῦ συντρίβεται τὸ πρᾶγμα καὶ ποῦ δυσχεραίνεται; ὅταν τὸ ἀπὸ τῶν κοινῶν ἔθος ἐπὶ τὰ ἴδια μεταβιβάζοντας ὁρῶσί τινας, καὶ μέγαν μὲν ὄντα παρ’ ὑμῖν εὐθέως τὸν λέγοντα, ἀθάνατον δ’ ἕνεκ’ ἀσφαλείας, ἑτέραν δὲ τὴν κρύβδην ψῆφον τοῦ φανερῶς θορύβου.", "st": "10.44"}, {"sp": "N", "t": "ταῦτ’ ἀπιστίαν, ταῦτ’ ὀργὴν ἔχει. δεῖ γάρ, ὦ ἄνδρες Ἀθηναῖοι, δικαίως ἀλλήλοις τῆς πολιτείας κοινωνεῖν, τοὺς μὲν εὐπόρους εἰς μὲν τὸν βίον τὰ ἑαυτῶν ἀσφαλῶς ἔχειν νομίζοντας καὶ ὑπὲρ τούτων μὴ δεδοικότας, εἰς δὲ τοὺς κινδύνους κοινὰ ὑπὲρ τῆς σωτηρίας τὰ ὄντα τῇ πατρίδι παρέχοντας, τοὺς δὲ λοιποὺς τὰ μὲν κοινὰ κοινὰ νομίζοντας καὶ μετέχοντας τὸ μέρος, τὰ δ’ ἑκάστου ἴδια τοῦ κεκτημένου. οὕτω καὶ μικρὰ μεγάλη πόλις γίγνεται καὶ μεγάλη σῴζεται. ὡς μὲν οὖν εἴποι τις ἄν, ἃ παρ’ ἑκατέρων εἶναι δεῖ, ταῦτ’ ἴσως ἐστίν· ὡς δὲ καὶ γένοιτ’ ἄν, [ἐν] νόμῳ διορθώσασθαι δεῖ.", "st": "10.45"}, {"sp": "N", "t": "τῶν δὲ παρόντων πραγμάτων καὶ τῆς ταραχῆς πολλὰ πόρρωθέν ἐστι τὰ αἴτια· ἃ εἰ βουλομένοις ὑμῖν ἀκούειν ἐστίν, ἐθέλω λέγειν. ἐξέστητ’, ὦ ἄνδρες Ἀθηναῖοι, τῆς ὑποθέσεως ἐφ’ ἧς ὑμᾶς οἱ πρόγονοι κατέλιπον, καὶ τὸ μὲν προΐστασθαι τῶν Ἑλλήνων καὶ δύναμιν συνεστηκυῖαν ἔχοντας πᾶσι τοῖς ἀδικουμένοις βοηθεῖν περίεργον ἐπείσθητ’ εἶναι καὶ μάταιον ἀνάλωμ’ ὑπὸ τῶν ταῦτα πολιτευομένων, τὸ δ’ ἐν ἡσυχίᾳ διάγειν καὶ μηδὲν τῶν δεόντων πράττειν, ἀλλὰ προϊεμένους καθ’ ἓν ἕκαστον πάνθ’ ἑτέρους ἐᾶσαι λαβεῖν, θαυμαστὴν εὐδαιμονίαν καὶ πολλὴν ἀσφάλειαν ἔχειν ᾤεσθε.", "st": "10.46"}, {"sp": "N", "t": "ἐκ δὲ τούτων παρελθὼν ἐπὶ τὴν τάξιν ἐφ’ ἧς ὑμῖν τετάχθαι προσῆκεν ἕτερος, οὗτος εὐδαίμων καὶ μέγας καὶ πολλῶν κύριος γέγονεν, εἰκότως· πρᾶγμα γὰρ ἔντιμον καὶ μέγα καὶ λαμπρόν, καὶ περὶ οὗ πάντα τὸν χρόνον αἱ μέγισται τῶν πόλεων πρὸς αὑτὰς διεφέροντο, Λακεδαιμονίων μὲν ἠτυχηκότων, Θηβαίων δ’ ἀσχόλων διὰ τὸν Φωκικὸν πόλεμον γενομένων, ἡμῶν δ’ ἀμελούντων, ἔρημον ἀνείλετο.", "st": "10.47"}, {"sp": "N", "t": "τοιγάρτοι τὸ μὲν φοβεῖσθαι τοῖς ἄλλοις, τὸ δὲ συμμάχους πολλοὺς ἔχειν καὶ δύναμιν μεγάλην ἐκείνῳ περιγέγονε, καὶ τοσαῦτα πράγματα καὶ τοιαῦτ’ ἤδη περιέστηκε τοὺς Ἕλληνας ἅπαντας, ὥστε μηδ’ ὅ τι χρὴ συμβουλεύειν εὔπορον εἶναι.", "st": "10.48"}, {"sp": "N", "t": "ὄντων δ’, ὦ ἄνδρες Ἀθηναῖοι, τῶν παρόντων πραγμάτων πᾶσιν, ὡς ἐγὼ κρίνω, φοβερῶν, οὐδένες ἐν μείζονι κινδύνῳ τῶν πάντων εἰσὶν ὑμῶν, οὐ μόνον τῷ μάλισθ’ ὑμῖν ἐπιβουλεύειν Φίλιππον, ἀλλὰ καὶ τῷ πάντων ἀργότατ’ αὐτοὶ διακεῖσθαι. εἰ τοίνυν τὸ τῶν ὠνίων πλῆθος ὁρῶντες καὶ τὴν εὐετηρίαν τὴν κατὰ τὴν ἀγοράν, τούτοις κεκήλησθ’ ὡς ἐν οὐδενὶ δεινῷ τῆς πόλεως οὔσης, οὔτε προσηκόντως οὔτ’ ὀρθῶς τὸ πρᾶγμα κρίνετε·", "st": "10.49"}, {"sp": "N", "t": "ἀγορὰν μὲν γὰρ ἄν τις καὶ πανήγυριν ἐκ τούτων ἢ φαύλως ἢ καλῶς παρεσκευάσθαι κρίνοι· πόλιν δ’ ἣν ὑπείληφεν, ὃς ἂν τῶν Ἑλλήνων ἄρχειν ἀεὶ βούληται, μόνην ἂν ἐναντιωθῆναι καὶ τῆς πάντων ἐλευθερίας προστῆναι, οὐ μὰ Δί’ ἐκ τῶν ὠνίων, εἰ καλῶς ἔχει, δοκιμάζειν δεῖ, ἀλλ’ εἰ συμμάχων εὐνοίᾳ πιστεύει, εἰ τοῖς ὅπλοις ἰσχύει, ταῦθ’ ὑπὲρ τῆς πόλεως δεῖ σκοπεῖν· ἃ σφαλερῶς ὑμῖν καὶ οὐδαμῶς ἅπαντ’ ἔχει.", "st": "10.50"}, {"sp": "N", "t": "γνοίητε δ’ ἄν, εἰ σκέψαισθ’ ἐκείνως. πότε μάλιστ’ ἐν ταραχῇ τὰ τῶν Ἑλλήνων γέγονε πράγματα; οὐδένα γὰρ χρόνον ἄλλον ἢ τὸν νυνὶ παρόντ’ οὐδ’ ἂν εἷς εἴποι. τὸν μὲν γὰρ ἄλλον ἅπαντ’ εἰς δύο ταῦτα διῄρητο τὰ τῶν Ἑλλήνων, Λακεδαιμονίους καὶ ἡμᾶς, τῶν δ’ ἄλλων [Ἑλλήνων] οἱ μὲν ἡμῖν, οἱ δ’ ἐκείνοις ὑπήκουον. βασιλεὺς δὲ καθ’ αὑτὸν μὲν ὁμοίως ἅπασιν ἄπιστος ἦν, τοὺς δὲ κρατουμένους τῷ πολέμῳ προσλαμβάνων, ἄχρι οὗ τοῖς ἑτέροις ἐξ ἴσου ποιήσαι, διεπιστεύετο, ἔπειτ’ οὐχ ἧττον αὐτὸν ἐμίσουν οὓς σώσειε τῶν ὑπαρχόντων ἐχθρῶν ἐξ ἀρχῆς.", "st": "10.51"}, {"sp": "N", "t": "νῦν δὲ πρῶτον μὲν ὁ βασιλεὺς ἅπασι τοῖς Ἕλλησιν οἰκείως ἔχει, καὶ πάντων ἥκιστα δὴ ἡμῖν, ἄν τι μὴ νῦν ἐπανορθωσώμεθα· ἔπειτα προστασίαι πολλαὶ καὶ πανταχόθεν γίγνονται, καὶ τοῦ πρωτεύειν ἀντιποιοῦνται μὲν πάντες, ἀφεστᾶσι δ’ ἔργῳ, καὶ φθονοῦσι καὶ ἀπιστοῦσιν αὑτοῖς, οὐχ οἷς ἔδει, καὶ γεγόνασι καθ’ αὑτοὺς ἕκαστοι, Ἀργεῖοι, Θηβαῖοι, Λακεδαιμόνιοι, Κορίνθιοι, Ἀρκάδες, ἡμεῖς.", "st": "10.52"}, {"sp": "N", "t": "ἀλλ’ ὅμως εἰς τοσαῦτα μέρη καὶ τοσαύτας δυναστείας διῃρημένων [τῶν Ἑλληνικῶν πραγμάτων], εἰ δεῖ τἀληθῆ μετὰ παρρησίας εἰπεῖν, τὰ παρ’ οὐδέσι τούτων ἀρχεῖα καὶ βουλευτήρι’ ἐρημότερ’ ἄν τις ἴδοι τῶν Ἑλληνικῶν πραγμάτων ἢ τὰ παρ’ ἡμῖν, εἰκότως· οὔτε γὰρ φιλῶν οὔτε πιστεύων οὔτε φοβούμενος οὐδεὶς ἡμῖν διαλέγεται.", "st": "10.53"}, {"sp": "N", "t": "αἴτιον δὲ τούτων οὐχ ἕν, ὦ ἄνδρες Ἀθηναῖοι, (ῥᾴδιον γὰρ ἂν ἦν ὑμῖν μεταθεῖναι), ἀλλὰ πολλὰ καὶ παντοδαπὰ ἐκ παντὸς ἡμαρτημένα τοῦ χρόνου, ὧν τὸ καθ’ ἕκαστον ἐάσας, εἰς ὃ πάντα τείνει λέξω, δεηθεὶς ὑμῶν, ἂν λέγω τἀληθῆ μετὰ παρρησίας, μηδὲν ἀχθεσθῆναί μοι. πέπραται τὰ συμφέροντ’ ἐφ’ ἑκάστου τῶν καιρῶν, καὶ μετειλήφαθ’ ὑμεῖς μὲν τὴν σχολὴν καὶ τὴν ἡσυχίαν, ὑφ’ ὧν κεκηλημένοι τοῖς ἀδικοῦσιν οὐ πικρῶς ἔχετε, ἕτεροι δὲ τὰς τιμὰς ἔχουσιν.", "st": "10.54"}, {"sp": "N", "t": "καὶ τὰ μὲν περὶ τἄλλ’ οὐκ ἄξιον ἐξετάσαι νῦν· ἀλλ’ ἐπειδάν τι τῶν πρὸς Φίλιππον ἐμπέσῃ, εὐθὺς ἀναστάς τις λέγει ὡς οὐ δεῖ ληρεῖν οὐδὲ γράφειν πόλεμον, παραθεὶς εὐθέως ἑξῆς τὸ τὴν εἰρήνην ἄγειν ὡς ἀγαθὸν καὶ τὸ τρέφειν μεγάλην δύναμιν ὡς χαλεπόν, καὶ “διαρπάζειν τινὲς τὰ χρήματα βούλονται,” καὶ ἄλλους λόγους ὡς οἷόν τ’ ἀληθεστάτους λέγουσιν.", "st": "10.55"}, {"sp": "N", "t": "ἀλλὰ δεῖ δήπου τὴν μὲν εἰρήνην ἄγειν οὐχ ὑμᾶς πείθειν, οἳ πεπεισμένοι κάθησθε, ἀλλὰ τὸν τὰ τοῦ πολέμου πράττοντα· ἂν γὰρ ἐκεῖνος πεισθῇ, τά γ’ ἀφ’ ὑμῶν ὑπάρχει· νομίζειν δ’ εἶναι χαλεπὰ οὐχ ὅσ’ ἂν εἰς σωτηρίαν δαπανῶμεν, ἀλλ’ ἃ πεισόμεθα, ἂν μὴ ταῦτ’ ἐθέλωμεν ποιεῖν, καὶ τὸ “διαρπασθήσεται τὰ χρήματα” τῷ φυλακὴν εὑρεῖν δι’ ἧς σωθήσεται κωλύειν, οὐχὶ τῷ τοῦ συμφέροντος ἀποστῆναι.", "st": "10.56"}, {"sp": "N", "t": "καίτοι ἔγωγ’ ἀγανακτῶ καὶ αὐτὸ τοῦτο, εἰ τὰ μὲν χρήματα λυπεῖ τινὰς ὑμῶν εἰ διαρπασθήσεται, ἃ καὶ φυλάττειν καὶ κολάζειν τοὺς ἀδικοῦντας ἐφ’ ὑμῖν ἐστι, τὴν δ’ Ἑλλάδα πᾶσαν ἐφεξῆς οὑτωσὶ Φίλιππος ἁρπάζων οὐ λυπεῖ, καὶ ταῦτ’ ἐφ’ ὑμᾶς ἁρπάζων.", "st": "10.57"}, {"sp": "N", "t": "τί ποτ’ οὖν, ὦ ἄνδρες Ἀθηναῖοι, τὸν μὲν οὕτω φανερῶς ἀδικοῦντα καὶ πόλεις καταλαμβάνοντα οὐδεὶς πώποτε τούτων εἶπεν ὡς ἀδικεῖ καὶ πόλεμον ποιεῖ, τοὺς δὲ μὴ ἐπιτρέπειν μηδὲ προΐεσθαι ταῦτα συμβουλεύοντας, τούτους πόλεμον ποιεῖν φασίν; ὅτι τὴν αἰτίαν τῶν ἐκ τοῦ πολέμου συμβησομένων δυσχερῶν (ἀνάγκη γάρ, ἀνάγκη πολλὰ λυπηρὰ ἐκ τοῦ πολέμου γίγνεσθαι) τοῖς ὑπὲρ ὑμῶν τὰ βέλτιστα λέγειν εἰθισμένοις ἀναθεῖναι βούλονται.", "st": "10.58"}, {"sp": "N", "t": "ἡγοῦνται γάρ, ἂν μὲν ὑμεῖς ὁμοθυμαδὸν ἐκ μιᾶς γνώμης Φίλιππον ἀμύνησθε, κἀκείνου κρατήσειν ὑμᾶς καὶ αὑτοῖς οὐκέτ’ ἔσεσθαι μισθαρνεῖν, ἂν δ’ ἀπὸ τῶν πρώτων θορύβων αἰτιασάμενοί τινας πρὸς τὸ κρίνειν τράπησθε, αὐτοὶ μὲν τούτων κατηγοροῦντες ἀμφότερ’ ἕξειν, καὶ παρ’ ὑμῖν εὐδοκιμήσειν καὶ παρ’ ἐκείνου χρήματα λήψεσθαι, ὑμᾶς δ’ ὑπὲρ ὧν δεῖ παρὰ τούτων δίκην λαβεῖν, παρὰ τῶν ὑπὲρ ὑμῶν εἰρηκότων λήψεσθαι.", "st": "10.59"}, {"sp": "N", "t": "αἱ μὲν ἐλπίδες αἱ τούτων αὗται καὶ τὸ κατασκεύασμα τὸ τῶν αἰτιῶν, ὡς ἄρα βούλονταί τινες πόλεμον ποιῆσαι. ἐγὼ δ’ οἶδ’ ἀκριβῶς ὅτι, οὐ γράψαντος Ἀθηναίων οὐδενὸς πόλεμον, πολλὰ Φίλιππος ἔχει τῶν τῆς πόλεως καὶ νῦν εἰς Καρδίαν πέπομφε βοήθειαν. εἰ μέντοι βουλόμεθ’ ἡμεῖς μὴ προσποιεῖσθαι πολεμεῖν ἡμῖν ἐκεῖνον, ἀνοητότατος πάντων ἂν εἴη, εἰ τοῦτ’ ἐξελέγχοι· ὅταν γὰρ οἱ ἀδικούμενοι ἀρνῶνται, τί τῷ ἀδικοῦντι προσήκει;", "st": "10.60"}, {"sp": "N", "t": "ἀλλ’ ἐπειδὰν ἐφ’ ἡμᾶς αὐτοὺς ἴῃ, τί φήσομεν τότε; ἐκεῖνος μὲν γὰρ οὐ πολεμεῖν, ὥσπερ οὐδ’ Ὠρείταις, τῶν στρατιωτῶν ὄντων ἐν τῇ χώρᾳ, οὐδὲ Φεραίοις πρότερον, πρὸς τὰ τείχη προσβάλλων, οὐδ’ Ὀλυνθίοις ἐξ ἀρχῆς, ἕως ἐν αὐτῇ τῇ χώρᾳ τὸ στράτευμα παρῆν ἔχων. ἢ καὶ τότε τοὺς ἀμύνεσθαι κελεύοντας πόλεμον ποιεῖν φήσομεν; οὐκοῦν ὑπόλοιπον δουλεύειν· οὐδὲ γὰρ ἄλλο γ’ οὐδὲν ἔνι.", "st": "10.61"}, {"sp": "N", "t": "καὶ μὴν οὐχ ὑπὲρ τῶν ἴσων ὑμῖν καὶ τοῖς ἄλλοις ἔσθ’ ὁ κίνδυνος· οὐ γὰρ ὑφ’ αὑτῷ ποιήσασθαι τὴν πόλιν βούλεται Φίλιππος ὑμῶν, οὔ, ἀλλ’ ὅλως ἀνελεῖν. οἶδε γὰρ ἀκριβῶς ὅτι δουλεύειν μὲν ὑμεῖς οὔτ’ ἐθελήσετε, οὔτ’, ἐὰν ἐθέλητε, ἐπιστήσεσθε (ἄρχειν γὰρ εἰώθατε), πράγματα δὲ παρασχεῖν αὐτῷ, ἂν καιρὸν λάβητε, πλείω τῶν ἄλλων ἀνθρώπων ἁπάντων δυνήσεσθε. διὰ ταῦθ’ ὑμῶν οὐχὶ φείσεται, εἴπερ ἐγκρατὴς γενήσεται.", "st": "10.62"}, {"sp": "N", "t": "ὡς οὖν ὑπὲρ τῶν ἐσχάτων ἐσομένου τοῦ ἀγῶνος, οὕτω προσήκει γιγνώσκειν, καὶ τοὺς πεπρακότας αὑτοὺς ἐκείνῳ φανερῶς ἀποτυμπανίσαι· οὐ γὰρ ἔστιν, οὐκ ἔστι τῶν ἔξω τῆς πόλεως ἐχθρῶν κρατῆσαι, πρὶν ἂν τοὺς ἐν αὐτῇ τῇ πόλει κολάσητ’ ἐχθρούς, ἀλλ’ ἀνάγκη τούτοις ὥσπερ προβόλοις προσπταίσαντας ὑστερίζειν ἐκείνων.", "st": "10.63"}, {"sp": "N", "t": "πόθεν οἴεσθε νῦν αὐτὸν ὑβρίζειν ὑμᾶς (οὐδὲν γὰρ ἄλλ’ ἔμοιγε δοκεῖ ποιεῖν ἢ τοῦτο) καὶ τοὺς μὲν ἄλλους εὖ ποιοῦντα, εἰ μηδὲν ἄλλο, ἐξαπατᾶν, ὑμῖν δ’ ἀπειλεῖν ἤδη; οἷον Θετταλοὺς πολλὰ δοὺς ὑπηγάγετ’ εἰς τὴν νῦν παροῦσαν δουλείαν· οὐδ’ ἂν εἰπεῖν δύναιτ’ οὐδεὶς ὅσα τοὺς ταλαιπώρους Ὀλυνθίους πρότερον δοὺς Ποτείδαιαν ἐξηπάτησε καὶ πόλλ’ ἕτερα· Θηβαίους τὰ νῦν ὑπάγει τὴν Βοιωτίαν αὐτοῖς παραδοὺς καὶ ἀπαλλάξας πολέμου πολλοῦ καὶ χαλεποῦ·", "st": "10.64"}, {"sp": "N", "t": "ὥστε καρπωσάμενοί τιν’ ἕκαστοι τούτων πλεονεξίαν, οἱ μὲν ἤδη πεπόνθασιν ἃ δὴ πεπόνθασιν, οἱ δ’ ὅταν ποτὲ συμβῇ πείσονται. ὑμεῖς δ’ ὧν μὲν ἀπεστέρησθε σιωπῶ· ἀλλ’ ἐν αὐτῷ τῷ τὴν εἰρήνην ποιήσασθαι, πόσ’ ἐξηπάτησθε, πόσων ἀπεστέρησθε. οὐχὶ Φωκέας, οὐ Πύλας, οὐχὶ τἀπὶ Θρᾴκης, Δορίσκον, Σέρριον, τὸν Κερσοβλέπτην αὐτόν; οὐ νῦν Καρδίαν ἔχει καὶ ὁμολογεῖ;", "st": "10.65"}, {"sp": "N", "t": "τί ποτ’ οὖν ἐκείνως τοῖς ἄλλοις, καὶ ὑμῖν οὐ τοῦτον τὸν τρόπον προσφέρεται; ὅτι ἐν μόνῃ τῶν πασῶν πόλεων τῇ ὑμετέρᾳ ἄδει’ ὑπὲρ τῶν ἐχθρῶν λέγειν δέδοται, καὶ λαβόντα χρήματ’ αὐτὸν ἀσφαλές ἐστι λέγειν παρ’ ὑμῖν, κἂν ἀφῃρημένοι τὰ ὑμέτερ’ αὐτῶν ἦτε.", "st": "10.66"}, {"sp": "N", "t": "οὐκ ἦν ἀσφαλὲς λέγειν ἐν Ὀλύνθῳ τὰ Φιλίππου μὴ σὺν εὖ πεπονθότων τῶν πολλῶν Ὀλυνθίων τῷ Ποτείδαιαν καρποῦσθαι· οὐκ ἦν ἀσφαλὲς λέγειν ἐν Θετταλίᾳ μὴ σὺν εὖ πεπονθότος τοῦ πλήθους τοῦ Θετταλῶν τῷ τοὺς τυράννους ἐκβαλεῖν Φίλιππον αὐτοῖς καὶ τὴν Πυλαίαν ἀποδοῦναι· οὐκ ἦν ἐν Θήβαις ἀσφαλές, πρὶν τὴν Βοιωτίαν ἀπέδωκε καὶ τοὺς Φωκέας ἀνεῖλεν.", "st": "10.67"}, {"sp": "N", "t": "ἀλλ’ Ἀθήνησιν, οὐ μόνον Ἀμφίπολιν καὶ τὴν Καρδιανῶν χώραν ἀπεστερηκότος Φιλίππου, ἀλλὰ καὶ κατασκευάζοντος ὑμῖν ἐπιτείχισμα τὴν Εὔβοιαν καὶ νῦν ἐπὶ Βυζάντιον παριόντος, ἀσφαλές ἐστι λέγειν ὑπὲρ Φιλίππου. καὶ γάρ τοι τούτων μὲν ἐκ πτωχῶν ἔνιοι ταχὺ πλούσιοι γίγνονται, καὶ ἐξ ἀνωνύμων καὶ ἀδόξων ἔνδοξοι καὶ γνώριμοι, ὑμεῖς δὲ τοὐναντίον ἐκ μὲν ἐνδόξων ἄδοξοι, ἐκ δ’ εὐπόρων ἄποροι·", "st": "10.68"}, {"sp": "N", "t": "πόλεως γὰρ ἔγωγε πλοῦτον ἡγοῦμαι συμμάχους, πίστιν, εὔνοιαν, ὧν πάντων ὑμεῖς ἔστ’ ἄποροι. ἐκ δὲ τοῦ τούτων ὀλιγώρως ὑμᾶς ἔχειν καὶ ἐᾶν τοῦτον τὸν τρόπον φέρεσθαι, ὁ μὲν εὐδαίμων καὶ μέγας καὶ φοβερὸς πᾶσιν Ἕλλησι καὶ βαρβάροις, ὑμεῖς δ’ ἔρημοι καὶ ταπεινοί, τῇ μὲν κατὰ τὴν ἀγορὰν εὐετηρίᾳ λαμπροί, τῇ δ’ ὧν προσῆκε παρασκευῇ καταγέλαστοι.", "st": "10.69"}, {"sp": "N", "t": "οὐ τὸν αὐτὸν δὲ τρόπον περί θ’ ὑμῶν καὶ περὶ αὑτῶν ἐνίους τῶν λεγόντων ὁρῶ βουλευομένους· ὑμᾶς μὲν γὰρ ἡσυχίαν ἄγειν φασὶ δεῖν, κἄν τις ὑμᾶς ἀδικῇ, αὐτοὶ δ’ οὐ δύνανται παρ’ ὑμῖν ἡσυχίαν ἄγειν οὐδενὸς αὐτοὺς ἀδικοῦντος. καίτοι λοιδορίας εἴ τις χωρὶς ἔροιτο “εἰπέ μοι, τί δὴ γιγνώσκων ἀκριβῶς, Ἀριστόμηδες, (οὐδεὶς γὰρ τὰ τοιαῦτ’ ἀγνοεῖ) τὸν μὲν τῶν ἰδιωτῶν βίον ἀσφαλῆ καὶ ἀπράγμονα καὶ ἀκίνδυνον ὄντα, τὸν δὲ τῶν πολιτευομένων φιλαίτιον καὶ σφαλερὸν καὶ καθ’ ἑκάστην ἡμέραν ἀγώνων καὶ κακῶν μεστόν, οὐ τὸν ἡσύχιον, ἀλλὰ τὸν ἐν τοῖς κινδύνοις αἱρεῖ;”", "st": "10.70"}, {"sp": "N", "t": "τί ἂν εἴποις; εἰ γὰρ ὃ βέλτιστον εἰπεῖν ἂν ἔχοις, τοῦτό σοι δοίημεν ἀληθὲς λέγειν, ὡς ὑπὲρ φιλοτιμίας καὶ δόξης ταῦτα πάντα ποιεῖς, θαυμάζω τί δήποτε σαυτῷ μὲν ὑπὲρ τούτων ἅπαντα ποιητέον εἶναι νομίζεις καὶ πονητέον καὶ κινδυνευτέον, τῇ πόλει δὲ προέσθαι ταῦτα μετὰ ῥᾳθυμίας συμβουλεύεις. οὐ γὰρ ἐκεῖνό γ’ ἂν εἴποις, ὡς σὲ μὲν ἐν τῇ πόλει δεῖ τινὰ φαίνεσθαι, τὴν πόλιν δ’ ἐν τοῖς Ἕλλησι μηδενὸς ἀξίαν εἶναι.", "st": "10.71"}, {"sp": "N", "t": "καὶ μὴν οὐδ’ ἐκεῖνό γ’ ὁρῶ, ὡς τῇ μὲν πόλει ἀσφαλὲς τὸ τὰ αὑτῆς πράττειν, σοὶ δὲ κίνδυνος, εἰ μηδὲν τῶν ἄλλων πλέον περιεργάσει, ἀλλὰ τοὐναντίον σοὶ μὲν ἐξ ὧν ἐργάζει καὶ περιεργάζει τοὺς ἐσχάτους ὄντας κινδύνους, τῇ πόλει δ’ ἐκ τῆς ἡσυχίας.", "st": "10.72"}, {"sp": "N", "t": "ἀλλὰ νὴ Δία παππῴα σοι καὶ πατρῴα δόξ’ ὑπάρχει, ἣν αἰσχρόν ἐστιν ἐν σοὶ καταλῦσαι· τῇ πόλει δ’ ὑπῆρξεν ἀνώνυμα καὶ φαῦλα τὰ τῶν προγόνων. ἀλλ’ οὐδὲ τοῦθ’ οὕτως ἔχει· σοὶ μὲν γὰρ ἦν κλέπτης ὁ πατήρ, εἴπερ ἦν ὅμοιος σοί, τῇ πόλει δ’ ἡμῶν οὓς πάντες ἴσασιν οἱ Ἕλληνες ἐκ τῶν μεγίστων κινδύνων σεσωσμένοι.", "st": "10.73"}, {"sp": "N", "t": "ἀλλὰ γὰρ οὐκ ἴσως οὐδὲ πολιτικῶς ἔνιοι τὰ καθ’ αὑτοὺς καὶ τὰ κατὰ τὴν πόλιν πολιτεύονται· πῶς γάρ ἐστιν ἴσον τούτων μέν τινας ἐκ τοῦ δεσμωτηρίου ἥκοντας ἑαυτοὺς ἀγνοεῖν, τὴν πόλιν δ’, ἣ προειστήκει τῶν Ἑλλήνων τέως καὶ τὸ πρωτεῖον εἶχε, νῦν ἐν ἀδοξίᾳ πάσῃ καὶ ταπεινότητι καθεστάναι;", "st": "10.74"}, {"sp": "N", "t": "πολλὰ τοίνυν ἔχων ἔτι καὶ περὶ πολλῶν εἰπεῖν παύσομαι· καὶ γὰρ οὐ λόγων ἐνδείᾳ μοι δοκεῖ τὰ πράγματ’ οὔτε νῦν οὔτ’ ἄλλοτε πώποτε φαύλως ἔχειν, ἀλλ’ ὅταν πάντ’ ἀκούσαντες ὑμεῖς τὰ δέοντα, καὶ ὁμογνώμονες ὡς ὀρθῶς λέγεται γενόμενοι, τῶν λυμαίνεσθαι καὶ διαστρέφειν ταῦτα βουλομένων ἐξ ἴσου κάθησθ’ ἀκροώμενοι, οὐκ ἀγνοοῦντες αὐτούς (ἴστε γὰρ εὐθὺς ἰδόντες ἀκριβῶς, τίς μισθοῦ λέγει καὶ [τίς] ὑπὲρ Φιλίππου πολιτεύεται, καὶ τίς ὡς ἀληθῶς ὑπὲρ τῶν βελτίστων), ἀλλ’ ἵν’ αἰτιασάμενοι τούτους καὶ τὸ πρᾶγμ’ εἰς γέλωτα καὶ λοιδορίαν ἐμβαλόντες μηδὲν αὐτοὶ τῶν δεόντων ποιῆτε.", "st": "10.75"}, {"sp": "N", "t": "ταῦτ’ ἐστὶ τἀληθῆ, μετὰ πάσης παρρησίας, ἁπλῶς εὐνοίᾳ τὰ βέλτιστ’ εἰρημένα, οὐ κολακείᾳ βλάβης καὶ ἀπάτης λόγος μεστός, ἀργύριον τῷ λέγοντι ποιήσων, τὰ δὲ πράγματα τῆς πόλεως τοῖς ἐχθροῖς ἐγχειριῶν. ἢ οὖν παυστέον τούτων τῶν ἐθῶν, ἢ μηδέν’ ἄλλον αἰτιατέον τοῦ πάντα φαύλως ἔχειν ἢ ὑμᾶς αὐτούς.", "st": "10.76"}, {"sp": "HDR", "t": "Πρὸς τὴν ἐπιστολήν τὴν Φιλίππου", "st": "11"}, {"sp": "N", "t": "ὅτι μέν, ὦ ἄνδρες Ἀθηναῖοι, Φίλιππος οὐκ ἐποιήσατο τὴν εἰρήνην πρὸς ὑμᾶς, ἀλλ’ ἀνεβάλετο τὸν πόλεμον, πᾶσιν ὑμῖν φανερὸν γέγονεν· ἐπειδὴ γὰρ Φαρσαλίοις Ἅλον παρέδωκε καὶ τὰ περὶ Φωκέας διῳκήσατο καὶ τὴν Θρᾴκην κατεστρέψατο πᾶσαν, αἰτίας οὐκ οὔσας πλασάμενος καὶ προφάσεις ἀδίκους ἐξευρὼν τῷ μὲν ἔργῳ πάλαι πολεμεῖ πρὸς τὴν πόλιν, τῷ δὲ λόγῳ νῦν ὁμολογεῖ διὰ τῆς ἐπιστολῆς ἧς ἔπεμψεν·", "st": "11.1"}, {"sp": "N", "t": "ὅτι δὲ χρὴ μήτ’ ὀρρωδεῖν ὑμᾶς τὴν ἐκείνου δύναμιν μήτ’ ἀγεννῶς ἀντιταχθῆναι πρὸς αὐτόν, ἀλλὰ καὶ σώμασι καὶ χρήμασι καὶ ναυσὶ καὶ πᾶσιν ὡς ἁπλῶς εἰπεῖν ἀφειδῶς ὁρμῆσαι πρὸς τὸν πόλεμον, ἐγὼ πειράσομαι διδάσκειν. πρῶτον μὲν γὰρ εἰκός, ὦ ἄνδρες Ἀθηναῖοι, τοὺς θεοὺς μεγίστους ὑμῖν ὑπάρχειν συμμάχους καὶ βοηθούς, ὧν ἐκεῖνος τὰς πίστεις ὑπεριδὼν καὶ τοὺς ὅρκους ὑπερβὰς λέλυκεν ἀδίκως τὴν εἰρήνην·", "st": "11.2"}, {"sp": "N", "t": "ἔπειθ’ οἷς πρότερον ηὐξήθη, φενακίζων ἀεί τινας καὶ μεγάλ’ ἐπαγγελλόμενος εὐεργετήσειν, ταῦτα πάντα διεξελήλυθεν ἤδη, καὶ γιγνώσκεται μὲν ὑπὸ τῶν Περινθίων καὶ Βυζαντίων καὶ τῶν ἐκείνοις συμμαχούντων ὡς ἐπιθυμεῖ προσενεχθῆναι τούτοις τὸν αὐτὸν τρόπον ὅνπερ Ὀλυνθίοις πρότερον,", "st": "11.3"}, {"sp": "N", "t": "οὐκ ἀγνοεῖται δ’ ὑπὸ Θετταλῶν δεσπόζειν, ἀλλ’ οὐχ ἡγεῖσθαι τῶν συμμάχων προαιρούμενος, ὑποπτεύεται δ’ ὑπὸ Θηβαίων Νίκαιαν μὲν φρουρᾷ κατέχων, εἰς δὲ τὴν ἀμφικτυονίαν εἰσδεδυκώς, τὰς δὲ πρεσβείας τὰς ἐκ Πελοποννήσου πρὸς αὑτὸν ἄγων καὶ τὴν ἐκείνων συμμαχίαν παραιρούμενος· ὥστε τῶν αὐτῷ πρὸ τοῦ φίλων ὄντων τοὺς μὲν νῦν πολεμεῖν ἀκαταλλάκτως, τοὺς δὲ μηκέτι προθύμους εἶναι συναγωνιστάς, ἅπαντας δ’ ὑφορᾶσθαι καὶ διαβεβλῆσθαι πρὸς αὐτόν.", "st": "11.4"}, {"sp": "N", "t": "ἔτι τοίνυν (οὐδὲ γὰρ τοῦτ’ ἔστι μικρόν) οἱ κατὰ τὴν Ἀσίαν σατράπαι καθεστῶτες ἔναγχος μὲν ξένους [μισθοφόρους] εἰσπέμψαντες ἐκώλυσαν ἐκπολιορκηθῆναι Πέρινθον, νῦν δὲ τῆς ἔχθρας αὐτοῖς ἐνεστώσης καὶ τοῦ κινδύνου πλησίον ὄντος, εἰ χειρωθήσεται Βυζάντιον,", "st": "11.5"}, {"sp": "N", "t": "οὐ μόνον αὐτοὶ προθύμως συμπολεμήσουσιν, ἀλλὰ καὶ βασιλέα [Περσῶν] χρήματα χορηγεῖν ἡμῖν προτρέψονται, ὃς τοσοῦτον μὲν κέκτηται πλοῦτον ὅσον οὐδ’ οἱ λοιποὶ πάντες, τηλικαύτην δ’ ἔχει ῥώμην πρὸς τὰς ἐνθάδε πράξεις ὥστε καὶ πρότερον, ἡνίκα Λακεδαιμονίοις ἐπολεμοῦμεν, ὁποτέροις πρόσθοιτο, τούτους ἐποίει κρατεῖν τῶν ἑτέρων, καὶ νῦν μεθ’ ἡμῶν γενόμενος ῥᾳδίως καταπολεμήσει τὴν Φιλίππου δύναμιν.", "st": "11.6"}, {"sp": "N", "t": "πρὸς τοίνυν τούτοις τηλικούτοις οὖσιν, οὐκ ἐρῶ μὲν ὡς οὐ διὰ τὴν εἰρήνην πολλὰ προείληφεν ἡμῶν χωρία καὶ λιμένας καὶ τοιαῦθ’ ἕτερα χρήσιμα πρὸς πόλεμον, ὁρῶ δ’ ὡς ὅταν μὲν ὑπ’ εὐνοίας τὰ πράγματα συνέχηται καὶ πᾶσι ταὐτὰ συμφέρῃ τοῖς μετέχουσι τῶν πολέμων, μένει τὰ συσταθέντα βεβαίως· ὅταν δ’ ἐξ ἐπιβουλῆς καὶ πλεονεξίας ἀπάτῃ καὶ βίᾳ κατέχηται, καθάπερ ὑπὸ τούτου νῦν, μικρὰ πρόφασις καὶ τὸ τυχὸν πταῖσμα ταχέως αὐτὰ διέσεισε καὶ κατέλυσεν.", "st": "11.7"}, {"sp": "N", "t": "καὶ πολλάκις εὑρίσκω λογιζόμενος οὐ μόνον, ὦ ἄνδρες Ἀθηναῖοι, τὰ συμμαχικὰ τῷ Φιλίππῳ πρὸς ὑποψίαν ἥκοντα καὶ δυσμένειαν, ἀλλὰ καὶ τὰ τῆς ἰδίας ἀρχῆς οὐ συνηρμοσμένα καλῶς οὐδ’ οἰκείως οὐδ’ ὡς οἴεταί τις. ὅλως μὲν γὰρ ἡ Μακεδονικὴ δύναμις ἐν μὲν προσθήκης μέρει ῥοπὴν ἔχει τινὰ καὶ χρῆσιν, αὐτὴ δὲ καθ’ αὑτὴν ἀσθενής ἐστι καὶ πρὸς τηλικοῦτον ὄγκον πραγμάτων εὐκαταφρόνητος.", "st": "11.8"}, {"sp": "N", "t": "ἔτι δ’ αὐτὴν οὗτος τοῖς πολέμοις καὶ ταῖς στρατείαις καὶ πᾶσιν οἷς ἄν τις αὐτὸν μέγαν εἶναι νομίσειε, σφαλερωτέραν αὑτῷ πεποίηκεν. μὴ γὰρ οἴεσθ’, ὦ ἄνδρες Ἀθηναῖοι, τοῖς αὐτοῖς χαίρειν Φίλιππόν τε καὶ τοὺς ἀρχομένους, ἀλλ’ ἐννοεῖσθ’ ὡς ὁ μὲν ἐπιθυμεῖ δόξης, οἱ δ’ ἀσφαλείας, καὶ αὐτῷ μὲν οὐκ ἔστι τυχεῖν ταύτης ἀκινδύνως, οἱ δ’ οὐδὲν δέονται, καταλείποντες οἴκοι τέκνα, γονεῖς, γυναῖκας, φθείρεσθαι καὶ καθ’ ἑκάστην ἡμέραν κινδυνεύειν ὑπὲρ αὐτοῦ.", "st": "11.9"}, {"sp": "N", "t": "ὥστε τοὺς μὲν πολλοὺς τῶν Μακεδόνων ἐκ τούτων ἄν τις ἴδοι πῶς διάκεινται πρὸς τὸν Φίλιππον· τοὺς δὲ περὶ αὐτὸν ὄντας ἑταίρους καὶ τοὺς τῶν ξένων ἡγεμόνας εὑρήσετε δόξαν μὲν ἔχοντας ἐπ’ ἀνδρείᾳ, περιδεῶς δὲ μᾶλλον τῶν ἀδόξων ζῶντας. τοῖς μὲν γὰρ ὁ πρὸς τοὺς πολεμίους μόνον ὑπάρχει κίνδυνος, οἱ δὲ τοὺς κόλακας καὶ τοὺς διαβάλλοντας αὐτοὺς μᾶλλον ἢ τὰς μάχας δεδίασι·", "st": "11.10"}, {"sp": "N", "t": "κἀκεῖνοι μὲν μετὰ πάντων ἀγωνίζονται πρὸς τοὺς ἀντιταχθέντας, τοῖς δὲ καὶ τῶν ἐν τοῖς πολέμοις κακῶν οὐκ ἐλάχιστον μέρος μέτεστιν, καὶ χωρὶς ἰδίᾳ τὸν τρόπον τὸν τοῦ βασιλέως φοβεῖσθαι συμβέβηκεν. ἔτι δὲ τῶν μὲν πολλῶν ἐὰν ἁμάρτῃ τις, ζημίας κατὰ τὴν ἀξίαν εἴληφεν· οἱ δ’ ὅταν μάλιστα κατορθώσωσι, τότε μάλιστα σκορακίζονται καὶ προπηλακίζονται παρὰ τὸ προσῆκον.", "st": "11.11"}, {"sp": "N", "t": "καὶ τούτοις οὐδ’ ἂν εἷς εὖ φρονῶν ἀπιστήσειεν· οὕτω γὰρ φιλότιμον αὐτὸν εἶναί φασιν οἱ συνδιατρίψαντες ὥστε βουλόμενον τὰ κάλλιστα τῶν ἔργων πάνθ’ αὑτοῦ δοκεῖν εἶναι μᾶλλον ἄχθεσθαι τῶν στρατηγῶν καὶ τῶν ἡγεμόνων τοῖς ἄξιον ἐπαίνου τι πράξασιν ἢ τοῖς ὅλως ἀποτυχοῦσι.", "st": "11.12"}, {"sp": "N", "t": "πῶς οὖν, εἴπερ ἐστὶ ταῦτα τοιαῦτα, πιστῶς ἤδη πολὺν χρόνον αὐτῷ παραμένουσιν; ὅτι νῦν μέν, ὦ ἄνδρες Ἀθηναῖοι, τὸ κατορθοῦν αὐτὸν ἐπισκοτεῖ πᾶσι τοῖς τοιούτοις· αἱ γὰρ εὐπραξίαι δειναὶ συγκρύψαι καὶ συσκιάσαι τὰς ἁμαρτίας τῶν ἀνθρώπων εἰσίν· εἰ δέ τι πταίσει, τότ’ ἀκριβῶς διακαλυφθήσεται ταῦτα πάντα. συμβαίνει γάρ, ὥσπερ ἐν τοῖς σώμασιν ἡμῶν·", "st": "11.13"}, {"sp": "N", "t": "ὅταν μὲν ἐρρωμένος ᾖ τις, οὐδὲν ἐπαισθάνεται τῶν καθ’ ἕκαστα σαθρῶν, ἐπὰν δ’ ἀρρωστήσῃ, πάντα κινεῖται, κἂν ῥῆγμα κἂν στρέμμα κἂν ἄλλο τι τῶν ὑπαρχόντων ᾖ μὴ τελέως ὑγιεινόν· οὕτω καὶ τῶν βασιλειῶν καὶ ἁπασῶν τῶν δυναστειῶν, ἕως μὲν ἂν ἐν τοῖς πολέμοις κατορθῶσιν, ἀφανῆ τὰ κακά ἐστι τοῖς πολλοῖς, ἐπὰν δέ τι πταίσωσιν, ὃ νῦν παθεῖν εἰκὸς ἐκεῖνον μεῖζον φορτίον ἢ καθ’ αὑτὸν αἰρόμενον, γίγνεται φανερὰ τὰ δυσχερῆ πάντα τοῖς ἅπασιν.", "st": "11.14"}, {"sp": "N", "t": "εἰ δέ τις ὑμῶν, ὦ ἄνδρες Ἀθηναῖοι, τὸν Φίλιππον ὁρῶν εὐτυχοῦντα φοβερὸν εἶναι νομίζει καὶ δυσπολέμητον, σώφρονος μὲν ἀνδρὸς χρῆται προνοίᾳ· μεγάλη γὰρ ῥοπή, μᾶλλον δὲ τὸ ὅλον ἡ τύχη ἐστὶ πρὸς ἅπαντα τὰ τῶν ἀνθρώπων πράγματα· κατὰ πολλοὺς μέντοι τρόπους ἕλοιτ’ ἄν τις οὐχ ἧττον τὴν ἡμετέραν εὐτυχίαν ἢ τὴν ἐκείνου.", "st": "11.15"}, {"sp": "N", "t": "παρά τε γὰρ τῶν προγόνων ἐκ πλείονος χρόνου παρειλήφαμεν τὴν εὐδαιμονίαν οὐ τούτου μόνον, ἀλλὰ συνελόντι φράσαι πάντων τῶν ἐν Μακεδονίᾳ βασιλευσάντων· κἀκεῖνοι μὲν Ἀθηναίοις φόρους ἤνεγκαν, ἡ δ’ ἡμετέρα πόλις οὐδενί πω τῶν ἁπάντων. ἔτι δὲ τοσούτῳ πλείους ἀφορμὰς αὐτοῦ πρὸς τὴν τῶν θεῶν εὔνοιαν ἔχομεν, ὅσῳ διατελοῦμεν εὐσεβέστερα καὶ δικαιότερα πράττοντες.", "st": "11.16"}, {"sp": "N", "t": "τί ποτ’ οὖν ἐκεῖνος ἐν τῷ προτέρῳ πολέμῳ πλείω κατώρθωσεν ἡμῶν; ὅτι, ὦ ἄνδρες Ἀθηναῖοι, (παρρησιάσομαι γὰρ πρὸς ὑμᾶς) ὁ μὲν αὐτὸς στρατεύεται καὶ ταλαιπωρεῖ καὶ τοῖς κινδύνοις πάρεστιν, οὔτε καιρὸν παριεὶς οὔθ’ ὥραν ἔτους παραλείπων οὐδεμίαν, ἡμεῖς δὲ (εἰρήσεται γὰρ τἀληθῆ) οὐδὲν ποιοῦντες ἐνθάδε καθήμεθα, μέλλοντες ἀεὶ καὶ ψηφιζόμενοι καὶ πυνθανόμενοι κατὰ τὴν ἀγορὰν εἴ τι λέγεται νεώτερον. καίτοι τί γένοιτ’ ἂν νεώτερον ἢ Μακεδὼν ἀνὴρ καταφρονῶν Ἀθηναίων καὶ τολμῶν ἐπιστολὰς πέμπειν τοιαύτας οἵας ἠκούσατε μικρῷ πρότερον;", "st": "11.17"}, {"sp": "N", "t": "καὶ τῷ μὲν ὑπάρχουσι μισθοφόροι στρατιῶται, καὶ νὴ Δία πρὸς τούτοις τῶν παρ’ ἡμῖν ῥητόρων τινές, οἳ τὰς παρ’ ἐκείνου δωρεὰς οἴκαδε λαμβάνειν νομίζοντες οὐκ αἰσχύνονται Φιλίππῳ ζῶντες, οὐδ’ αἰσθάνονται πάντα καὶ τὰ τῆς πόλεως καὶ τὰ σφῶν αὐτῶν μικροῦ λήμματος πωλοῦντες. ἡμεῖς δ’ οὔτε τῶν ἐκείνου πραγμάτων οὐδὲν στασιάζειν παρασκευάζομεν, οὔτε ξενοτροφεῖν ἐθέλομεν, οὔτε στρατεύεσθαι τολμῶμεν.", "st": "11.18"}, {"sp": "N", "t": "οὔκουν ἐστὶν οὐδὲν δεινόν, εἴ τι πεπλεονέκτηκεν ἡμῶν κατὰ τὸν πρότερον πόλεμον, ἀλλὰ μᾶλλον εἰ μηδὲν ποιοῦντες ἡμεῖς ὧν προσήκει τοὺς πολεμοῦντας, νομίζομεν κρατήσειν τοῦ πάντα πράττοντος· ἃ δεῖ τοὺς πλεονεκτήσειν μέλλοντας.", "st": "11.19"}, {"sp": "N", "t": "ὧν, ὦ ἄνδρες Ἀθηναῖοι, χρὴ λαβόντας ἔννοιαν, καὶ λογισαμένους ὡς οὐδ’ ἐφ’ ἡμῖν ἐστι τὸ φάσκειν ἄγειν εἰρήνην (ἤδη γὰρ ἐκεῖνος καὶ προηγόρευκε τὸν πόλεμον καὶ τοῖς ἔργοις ἐξενήνοχε) μηδενὸς μὲν φείδεσθαι μήτε τῶν δημοσίων μήτε τῶν ἰδίων, στρατεύεσθαι δέ, ἄν που καιρὸς ᾖ, προθύμως ἅπαντας, χρῆσθαι δὲ στρατηγοῖς ἀμείνοσιν ἢ πρότερον.", "st": "11.20"}, {"sp": "N", "t": "μὴ γὰρ ὑπολάβῃ τις ὑμῶν, δι’ ὧν ἐγένετο τὰ πράγματα χείρω τὰ τῆς πόλεως, διὰ τούτων αὐτὰ πάλιν ἀναλήψεσθαι καὶ γενήσεσθαι βελτίω· μηδὲ νομίσητε ῥᾳθυμούντων ὑμῶν, ὥσπερ πρότερον, ἑτέρους ὑπὲρ τῶν ὑμετέρων ἀγωνιεῖσθαι προθύμως· ἀλλ’ ἐννοεῖσθ’ ὡς αἰσχρόν ἐστι τοὺς μὲν πατέρας ὑμῶν πολλοὺς πόνους καὶ μεγάλους κινδύνους ὑποστῆναι Λακεδαιμονίοις πολεμοῦντας,", "st": "11.21"}, {"sp": "N", "t": "ὑμᾶς δὲ μηδ’ ὑπὲρ ὧν ἐκεῖνοι δικαίως κτησάμενοι παρέδοσαν ὑμῖν ἐθέλειν ἐρρωμένως ἀμύνεσθαι, ἀλλὰ τὸν μὲν ἐκ Μακεδονίας ὁρμώμενον οὕτως εἶναι φιλοκίνδυνον ὥσθ’ ὑπὲρ τοῦ μείζω ποιῆσαι τὴν ἀρχὴν κατατετρῶσθαι πᾶν τὸ σῶμα τοῖς πολεμίοις μαχόμενον, Ἀθηναίους δέ, οἷς πάτριόν ἐστι μηδενὸς ἀκούειν, ἁπάντων δὲ κρατεῖν ἐν τοῖς πολέμοις, τούτους διὰ ῥᾳθυμίαν ἢ μαλακίαν ἐγκαταλείπειν τά τε τῶν προγόνων ἔργα καὶ τὰ συμφέροντα τῆς πατρίδος.", "st": "11.22"}, {"sp": "N", "t": "ἵνα δὲ μὴ μακρολογῶ, φημὶ χρῆναι παρεσκευάσθαι μὲν πρὸς τὸν πόλεμον, παρακαλεῖν δὲ τοὺς Ἕλληνας, μὴ λόγοις, ἀλλὰ τοῖς ἔργοις πρὸς τὴν παρ’ ἡμῶν συμμαχίαν· ὡς ἅπας μέν ἐστι λόγος μάταιος πράξεων ἄμοιρος γενόμενος, τοσούτῳ δὲ μάλισθ’ ὁ παρὰ τῆς ἡμετέρας πόλεως, ὅσῳ δοκοῦμεν αὐτῷ προχειρότατα χρῆσθαι τῶν ἄλλων Ἑλλήνων.", "st": "11.23"}, {"sp": "HDR", "t": "Ἐπιστολή [Φιλίππου]", "st": "12"}, {"sp": "N", "t": "Φίλιππος Ἀθηναίων τῇ βουλῇ καὶ τῷ δήμῳ χαίρειν. ἐπειδὴ πολλάκις μου πρέσβεις ἀποστείλαντος, ἵν’ ἐμμείνωμεν τοῖς ὅρκοις καὶ ταῖς ὁμολογίαις, οὐδεμίαν ἐποιεῖσθ’ ἐπιστροφήν, ᾤμην δεῖν πέμψαι πρὸς ὑμᾶς ὑπὲρ ὧν ἀδικεῖσθαι νομίζω. μὴ θαυμάσητε δὲ τὸ μῆκος τῆς ἐπιστολῆς· πολλῶν γὰρ ὑπαρχόντων ἐγκλημάτων ἀναγκαῖόν ἐστιν ὑπὲρ ἁπάντων δηλῶσαι καθαρῶς.", "st": "12.1"}, {"sp": "N", "t": "πρῶτον μὲν γὰρ Νικίου τοῦ κήρυκος ἁρπασθέντος ἐκ τῆς χώρας τῆς ἐμῆς, οὐχ ὅτι τοῖς παρανομοῦσιν ἐπετιμήσατε τὴν δίκην, ἀλλὰ τὸν ἀδικούμενον εἵρξατε δέκα μῆνας· ἃς δ’ ἔφερε παρ’ ἡμῶν ἐπιστολάς, ἀνέγνωτ’ ἐπὶ τοῦ βήματος. ἔπειτα Θασίων ὑποδεχομένων τὰς Βυζαντίων τριήρεις καὶ τῶν λῃστῶν τοὺς βουλομένους οὐδὲν ἐφροντίζετε, τῶν συνθηκῶν διαρρήδην λεγουσῶν πολεμίους εἶναι τοὺς ταῦτα ποιοῦντας.", "st": "12.2"}, {"sp": "N", "t": "ἔτι τοίνυν περὶ τοὺς αὐτοὺς χρόνους Διοπείθης ἐμβαλὼν εἰς τὴν χώραν Κρωβύλην μὲν καὶ τὴν Τιρίστασιν ἐξηνδραποδίσατο, τὴν δὲ προσεχῆ Θρᾴκην ἐπόρθησε, τέλος δ’ εἰς τοῦτ’ ἦλθε παρανομίας ὥστ’ Ἀμφίλοχον ὑπὲρ τῶν αἰχμαλώτων ἐλθόντα πρεσβευτὴν συλλαβὼν καὶ τὰς ἐσχάτας ἀνάγκας ἐπιθεὶς ἀπελύτρωσε ταλάντων ἐννέα· καὶ ταῦτα τῷ δήμῳ συνδοκοῦντ’ ἐποίησεν.", "st": "12.3"}, {"sp": "N", "t": "καίτοι τὸ παρανομεῖν εἰς κήρυκα καὶ πρέσβεις τοῖς ἄλλοις τε πᾶσιν ἀσεβὲς εἶναι δοκεῖ καὶ μάλισθ’ ὑμῖν· Μεγαρέων γοῦν Ἀνθεμόκριτον ἀνελόντων εἰς τοῦτ’ ἐλήλυθεν ὁ δῆμος ὥστε μυστηρίων μὲν εἶργον αὐτούς, ὑπομνήματα δὲ τῆς ἀδικίας ἔστησαν ἀνδριάντα πρὸ τῶν πυλῶν. καίτοι πῶς οὐ δεινόν, ἐφ’ οἷς παθόντες οὕτως ἐμισήσατε τοὺς δράσαντας, νῦν αὐτοὺς φαίνεσθαι ποιοῦντας;", "st": "12.4"}, {"sp": "N", "t": "Καλλίας τοίνυν ὁ παρ’ ὑμῶν στρατηγὸς τὰς μὲν πόλεις τὰς ἐν τῷ Παγασίτῃ κόλπῳ κατοικουμένας ἔλαβεν ἁπάσας, ὑμῖν μὲν ἐνόρκους, ἐμοὶ δὲ συμμαχίδας οὔσας, τοὺς δ’ εἰς Μακεδονίαν πλέοντας ἐπώλει πάντας πολεμίους κρίνων· καὶ διὰ ταῦθ’ ὑμεῖς ἐπῃνεῖτ’ αὐτὸν ἐν τοῖς ψηφίσμασιν. ὥστ’ ἔγωγ’ ἀπορῶ τί ποτ’ ἔσται καινότερον, ἐὰν ὁμολογήσητέ μοι πολεμεῖν· καὶ γὰρ ὅτε φανερῶς διεφερόμεθα, λῃστὰς ἐξεπέμπετε καὶ τοὺς πλέοντας ὡς ἡμᾶς ἐπωλεῖτε, τοῖς ἐναντίοις ἐβοηθεῖτε, τὴν χώραν μου κακῶς ἐποιεῖτε.", "st": "12.5"}, {"sp": "N", "t": "χωρὶς τοίνυν εἰς τοῦτο παρανομίας ἀφῖχθε καὶ δυσμενείας ὥστε καὶ πρὸς τὸν Πέρσην πρέσβεις ἀπεστάλκατε πείσοντας αὐτὸν ἐμοὶ πολεμεῖν· ὃ μάλιστ’ ἄν τις θαυμάσειεν. πρὸ μὲν γὰρ τοῦ λαβεῖν αὐτὸν Αἴγυπτον καὶ Φοινίκην ἐψηφίσασθε, ἂν ἐκεῖνός τι νεωτερίζῃ, παρακαλεῖν ὁμοίως ἐμὲ καὶ τοὺς ἄλλους Ἕλληνας ἅπαντας ἐπ’ αὐτόν·", "st": "12.6"}, {"sp": "N", "t": "νῦν δὲ τοσοῦτον ὑμῖν περίεστι τοῦ πρὸς ἐμὲ μίσους ὥστε πρὸς ἐκεῖνον διαλέγεσθε περὶ τῆς ἐπιμαχίας. καίτοι τὸ παλαιὸν οἱ πατέρες ὑμῶν, ὡς ἐγὼ πυνθάνομαι, τοῖς Πεισιστρατίδαις ἐπετίμων ὡς ἐπάγουσι τὸν Πέρσην ἐπὶ τοὺς Ἕλληνας· ὑμεῖς δ’ οὐκ αἰσχύνεσθε ταῦτα ποιοῦντες ἃ διετελεῖτε τοῖς τυράννοις ἐγκαλοῦντες.", "st": "12.7"}, {"sp": "N", "t": "ἀλλὰ πρὸς τοῖς ἄλλοις καὶ γράφετ’ ἐν τοῖς ψηφίσμασιν ἐμοὶ προστάττοντες Τήρην καὶ Κερσοβλέπτην ἐᾶν Θρᾴκης ἄρχειν, ὡς ὄντας Ἀθηναίους. ἐγὼ δὲ τούτους οὔτε τῶν περὶ τῆς εἰρήνης συνθηκῶν οἶδα μετασχόντας ὑμῖν οὔτ’ ἐν ταῖς στήλαις ἀναγεγραμμένους οὔτ’ Ἀθηναίους ὄντας, ἀλλὰ Τήρην μὲν μετ’ ἐμοῦ στρατευόμενον ἐφ’ ὑμᾶς, Κερσοβλέπτην δὲ τοῖς παρ’ ἐμοῦ πρεσβευταῖς ἰδίᾳ μὲν τοὺς ὅρκους ὀμόσαι προθυμούμενον, κωλυθέντα δ’ ὑπὸ τῶν ὑμετέρων στρατηγῶν ἀποφαινόντων αὐτὸν Ἀθηναίων ἐχθρόν.", "st": "12.8"}, {"sp": "N", "t": "καίτοι πῶς ἐστὶ τοῦτ’ ἴσον ἢ δίκαιον, ὅταν μὲν ὑμῖν συμφέρῃ, πολέμιον εἶναι φάσκειν αὐτὸν τῆς πόλεως, ὅταν δ’ ἐμὲ συκοφαντεῖν βούλησθε, πολίτην ἀποδείκνυσθαι τὸν αὐτὸν ὑφ’ ὑμῶν· καὶ Σιτάλκου μὲν ἀποθανόντος, ᾧ μετέδοτε τῆς πολιτείας, εὐθὺς ποιήσασθαι πρὸς τὸν ἀποκτείναντα φιλίαν, ὑπὲρ δὲ Κερσοβλέπτου πόλεμον αἴρεσθαι πρὸς ἡμᾶς; καὶ ταῦτα σαφῶς εἰδότας ὅτι τῶν λαμβανόντων τὰς δωρεὰς τὰς τοιαύτας οὐδεὶς οὔτε τῶν νόμων οὔτε τῶν ψηφισμάτων οὐδὲν φροντίζει τῶν ὑμετέρων.", "st": "12.9"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ εἰ δεῖ πάντα τἄλλα παραλιπόντα συντόμως εἰπεῖν, ὑμεῖς ἔδοτε πολιτείαν Εὐαγόρᾳ τῷ Κυπρίῳ καὶ Διονυσίῳ τῷ Συρακοσίῳ καὶ τοῖς ἐκγόνοις τοῖς ἐκείνων. ἐὰν οὖν πείσητε τοὺς ἐκβαλόντας ἑκατέρους αὐτῶν ἀποδοῦναι πάλιν τὰς ἀρχὰς τοῖς ἐκπεσοῦσι, κομίζεσθε καὶ παρ’ ἐμοῦ τὴν Θρᾴκην, ὅσης Τήρης καὶ Κερσοβλέπτης ἦρχον. εἰ δὲ τοῖς μὲν ἐκείνων κρατήσασι μηδ’ ἐγκαλεῖν ἀξιοῦτε μηδέν, ἐμὲ δ’ ἐνοχλεῖτε, πῶς οὐ δικαίως ὑμᾶς ἀμυνοίμην ἄν;", "st": "12.10"}, {"sp": "N", "t": "περὶ μὲν οὖν τούτων πολλὰ λέγειν ἔχων ἔτι δίκαια, παραλιπεῖν προαιροῦμαι· Καρδιανοῖς δέ φημι βοηθεῖν, γεγονὼς αὐτοῖς πρὸ τῆς εἰρήνης σύμμαχος, οὐκ ἐθελόντων δ’ ὑμῶν ἐλθεῖν εἰς κρίσιν, πολλάκις μὲν ἐμοῦ δεηθέντος, οὐκ ὀλιγάκις δ’ ἐκείνων· ὥστε πῶς οὐκ ἂν εἴην πάντων φαυλότατος, εἰ καταλιπὼν τοὺς συμμάχους μᾶλλον ὑμῶν φροντίζοιμι τῶν πάντα μοι τρόπον ἐνοχλούντων ἢ τῶν βεβαίως μοι φίλων ἀεὶ μενόντων;", "st": "12.11"}, {"sp": "N", "t": "εἰ τοίνυν δεῖ μηδὲ τοῦτο παραλιπεῖν, εἰς τοσοῦτον ἐληλύθατε πλεονεξίας ὥστε πρότερον μὲν ἐνεκαλεῖτέ μοι τὰ προειρημένα μόνον, τὰ δ’ ὑπογυιότατα Πεπαρηθίων φασκόντων δεινὰ πεπονθέναι προσετάξατε τῷ στρατηγῷ δίκην παρ’ ἐμοῦ λαβεῖν ὑπὲρ ἐκείνων, οὓς ἐγὼ μὲν ἐτιμωρησάμην ἐνδεεστέρως ἢ προσῆκεν, ἐκεῖνοι δ’ εἰρήνης οὔσης καταλαβόντες Ἁλόννησον οὔτε τὸ χωρίον οὔτε τοὺς φρουροὺς ἀπεδίδοσαν πέμψαντος ὑπὲρ αὐτῶν ἐμοῦ πολλάκις.", "st": "12.12"}, {"sp": "N", "t": "ὑμεῖς δ’ ὧν μὲν ἠδίκησαν ἐμὲ Πεπαρήθιοι, τούτων μὲν οὐδὲν ἐπεσκέψασθε, τὴν δὲ τιμωρίαν, ἀκριβῶς εἰδότες. καίτοι τὴν νῆσον οὔτ’ ἐκείνους οὔθ’ ὑμᾶς ἀφειλόμην, ἀλλὰ τὸν λῃστὴν Σώστρατον. εἰ μὲν οὖν αὐτοί φατε παραδοῦναι Σωστράτῳ, λῃστὰς ὁμολογεῖτε καταπέμπειν· εἰ δ’ ἀκόντων ὑμῶν ἐκεῖνος ἐκράτει, τί δεινὸν πεπόνθατε λαβόντος ἐμοῦ καὶ τὸν τόπον τοῖς πλέουσιν ἀσφαλῆ παρέχοντος;", "st": "12.13"}, {"sp": "N", "t": "τοσαύτην δέ μου ποιουμένου πρόνοιαν τῆς ὑμετέρας πόλεως, καὶ διδόντος αὐτῇ τὴν νῆσον, οἱ ῥήτορες λαμβάνειν μὲν οὐκ εἴων, ἀπολαβεῖν δὲ συνεβούλευον, ὅπως ὑπομείνας μὲν τὸ προσταττόμενον τὴν ἀλλοτρίαν ἔχειν ὁμολογῶ, μὴ προέμενος δὲ τὸ χωρίον ὕποπτος γένωμαι τῷ πλήθει. γνοὺς ἐγὼ ταῦτα προὐκαλούμην κριθῆναι περὶ τούτων πρὸς ἡμᾶς, ἵν’ ἐὰν μὲν ἐμὴ γνωσθῇ, παρ’ ἐμοῦ δοθῇ τὸ χωρίον ὑμῖν, ἐὰν δ’ ὑμετέρα κριθῇ, τότ’ ἀποδῶ τῷ δήμῳ.", "st": "12.14"}, {"sp": "N", "t": "ταῦτα δ’ ἐμοῦ πολλάκις ἀξιοῦντος, ὑμεῖς μὲν οὐ προσείχετε, Πεπαρήθιοι δὲ τὴν νῆσον κατέλαβον. τί οὖν ἐχρῆν με ποιεῖν; οὐ δίκην λαβεῖν παρὰ τῶν ὑπερβεβηκότων τοὺς ὅρκους; οὐ τιμωρήσασθαι τοὺς οὕτως ὑπερηφάνως ἀσελγαίνοντας; καὶ γὰρ εἰ Πεπαρηθίων ἦν ἡ νῆσος, τί προσῆκεν ἀπαιτεῖν Ἀθηναίους; εἰ δ’ ὑμετέρα, πῶς οὐκ ἐκείνοις ὀργίζεσθε καταλαβοῦσι τὴν ἀλλοτρίαν;", "st": "12.15"}, {"sp": "N", "t": "εἰς τοῦτο δὲ προβεβήκαμεν ἔχθρας ὥστε βουλόμενος ταῖς ναυσὶν εἰς τὸν Ἑλλήσποντον παραβαλεῖν ἠναγκάσθην αὐτὰς παραπέμψαι διὰ Χερρονήσου τῇ στρατιᾷ, τῶν μὲν κληρούχων κατὰ τὸ Πολυκράτους δόγμα πολεμούντων ἡμῖν, ὑμῶν δὲ τοιαῦτα ψηφιζομένων, τοῦ δὲ στρατηγοῦ Βυζαντίους τε παρακαλοῦντος καὶ διαγγέλλοντος πρὸς ἅπαντας ὅτι πολεμεῖν αὐτῷ προστάττετε, ἂν καιρὸν λάβῃ. τοιαῦτα δὲ πάσχων ὅμως τῆς πόλεως καὶ τῶν τριήρων καὶ τῆς χώρας ἀπεσχόμην, ἱκανὸς ὢν τὰ πλεῖστα λαβεῖν ἢ πάντα, καὶ διατετέλεκα προκαλούμενος ὑμᾶς εἰς κρίσιν ἐλθεῖν ὑπὲρ ὧν αἰτιώμεθ’ ἀλλήλους.", "st": "12.16"}, {"sp": "N", "t": "καίτοι σκοπεῖσθε πότερον κάλλιόν ἐστιν ὅπλοις ἢ λόγοις διακρίνεσθαι, καὶ πότερον αὐτοὺς εἶναι βραβευτὰς ἢ πεῖσαί τινας ἑτέρους· καὶ λογίζεσθ’ ὡς ἄλογόν ἐστιν Ἀθηναίους Θασίους μὲν καὶ Μαρωνίτας ἀναγκάσαι περὶ Στρύμης διακριθῆναι λόγοις, αὐτοὺς δὲ πρὸς ἐμὲ μὴ διαλύσασθαι περὶ ὧν ἀμφισβητοῦμεν τὸν τρόπον τοῦτον, ἄλλως τε καὶ γιγνώσκοντας ὅτι νικηθέντες μὲν οὐδὲν ἀποβαλεῖτε, κρατήσαντες δὲ λήψεσθε τὰ νῦν ὑφ’ ἡμῖν ὄντα.", "st": "12.17"}, {"sp": "N", "t": "πάντων δέ μοι δοκεῖ παραλογώτατον εἶναι, διότι πέμψαντος ἐμοῦ πρέσβεις ἀπὸ τῆς συμμαχίας πάσης, ἵν’ ὦσι μάρτυρες, καὶ βουλομένου ποιήσασθαι πρὸς ὑμᾶς δικαίας ὁμολογίας ὑπὲρ τῶν Ἑλλήνων, οὐδὲ τοὺς περὶ τούτων λόγους ἐδέξασθε παρὰ τῶν πρεσβευόντων, ἐξὸν ὑμῖν ἢ τῶν κινδύνων ἀπαλλάξαι τοὺς δυσχερὲς ὑποπτεύοντάς τι καθ’ ἡμῶν, ἢ φανερῶς ἐξελέγξαι με φαυλότατον ὄντα τῶν ἁπάντων.", "st": "12.18"}, {"sp": "N", "t": "τῷ μὲν οὖν δήμῳ ταῦτα συνέφερε, τοῖς δὲ λέγουσιν οὐκ ἐλυσιτέλει. φασὶ γὰρ οἱ τῆς πολιτείας τῆς παρ’ ὑμῖν ἔμπειροι τὴν μὲν εἰρήνην πόλεμον αὐτοῖς εἶναι, τὸν δὲ πόλεμον εἰρήνην· ἢ γὰρ συναγωνιζομένους τοῖς στρατηγοῖς ἢ συκοφαντοῦντας ἀεί τι λαμβάνειν παρ’ αὐτῶν, ἔτι δὲ τῶν πολιτῶν τοῖς γνωριμωτάτοις καὶ τῶν ἔξωθεν τοῖς ἐνδοξοτάτοις λοιδορουμένους ἐπὶ τοῦ βήματος περιποιεῖσθαι παρὰ τοῦ πλήθους δόξαν ὡς εἰσὶ δημοτικοί.", "st": "12.19"}, {"sp": "N", "t": "ῥᾴδιον μὲν οὖν ἐστί μοι παῦσαι τῆς βλασφημίας αὐτοὺς μικρὰ πάνυ προεμένῳ, καὶ ποιῆσαι λέγειν ἐπαίνους ὑπὲρ ἡμῶν. ἀλλ’ αἰσχυνοίμην ἄν, εἰ τὴν πρὸς ὑμᾶς εὔνοιαν παρὰ τούτων φαινοίμην ὠνούμενος, οἳ πρὸς τοῖς ἄλλοις εἰς τοῦτο τόλμης ἥκουσιν ὥστε καὶ περὶ Ἀμφιπόλεως πρὸς ἡμᾶς ἀμφισβητεῖν ἐπιχειροῦσιν, ὑπὲρ ἧς τῶν ἀντιποιουμένων αὐτῆς οἶμαι πολὺ δικαιότερα λέγειν αὐτός.", "st": "12.20"}, {"sp": "N", "t": "εἴτε γὰρ τῶν ἐξ ἀρχῆς κρατησάντων γίγνεται, πῶς οὐ δικαίως ἡμεῖς αὐτὴν ἔχομεν, Ἀλεξάνδρου τοῦ προγόνου πρώτου κατασχόντος τὸν τόπον, ὅθεν καὶ τῶν αἰχμαλώτων Μήδων ἀπαρχὴν ἀνδριάντα χρυσοῦν ἀνέστησεν εἰς Δελφούς; εἴτε τούτων μὲν ἀμφισβητήσειέ τις, ἀξιοῖ δὲ γίγνεσθαι τῶν ὕστερον γενομένων κυρίων, ὑπάρχει μοι καὶ τοῦτο τὸ δίκαιον· ἐκπολιορκήσας γὰρ τοὺς ὑμᾶς μὲν ἐκβαλόντας, ὑπὸ Λακεδαιμονίων δὲ κατοικισθέντας, ἔλαβον τὸ χωρίον.", "st": "12.21"}, {"sp": "N", "t": "καίτοι πάντες οἰκοῦμεν τὰς πόλεις ἢ τῶν προγόνων παραδόντων ἢ κατὰ πόλεμον κύριοι καταστάντες. ὑμεῖς δ’ οὔτε πρῶτοι λαβόντες οὔτε νῦν ἔχοντες, ἐλάχιστον δὲ χρόνον ἐν τοῖς τόποις ἐμμείναντες, ἀντιποιεῖσθε τῆς πόλεως, καὶ ταῦτα πίστιν ὑπὲρ ἡμῶν αὐτοὶ βεβαιοτάτην ἐπιθέντες· πολλάκις γὰρ ἐμοῦ γράφοντος ἐν ταῖς ἐπιστολαῖς ὑπὲρ αὐτῆς, ἐγνώκατε δικαίως ἔχειν ἡμᾶς, τότε μὲν ποιησάμενοι τὴν εἰρήνην ἔχοντος ἐμοῦ τὴν πόλιν, κᾆτα συμμαχίαν ἐπὶ ταῖς αὐταῖς ὁμολογίαις.", "st": "12.22"}, {"sp": "N", "t": "καίτοι πῶς ἂν ἑτέρα γένοιτο βεβαιοτέρα ταύτης κτῆσις, τῆς τὸ μὲν ἐξ ἀρχῆς καταλειφθείσης ἡμῖν ὑπὸ τῶν προγόνων, πάλιν δὲ κατὰ πόλεμον ἐμῆς γεγενημένης, τρίτον δὲ συγχωρηθείσης ὑφ’ ὑμῶν τῶν εἰθισμένων ἀμφισβητεῖν καὶ τῶν οὐδὲν ὑμῖν προσηκόντων;", "st": "12.23"}, {"sp": "N", "t": "ἃ μὲν οὖν ἐγκαλῶ, ταῦτ’ ἐστίν· ὡς δὲ προϋπαρχόντων καὶ διὰ τὴν ἐμὴν εὐλάβειαν μᾶλλον ἤδη τοῖς πράγμασιν ἐπιτιθεμένων καὶ καθ’ ὅσον ἂν δύνησθε κακοποιούντων ὑμῶν, ἀμυνοῦμαι μετὰ τοῦ δικαίου, καὶ μάρτυρας τοὺς θεοὺς ποιησάμενος διαλήψομαι περὶ τῶν καθ’ ὑμᾶς.", "st": "12.23"}, {"sp": "HDR", "t": "Περὶ συντάξεως", "st": "13"}, {"sp": "N", "t": "περὶ μὲν τοῦ παρόντος ἀργυρίου καὶ ὧν ἕνεκα τὴν ἐκκλησίαν ποιεῖσθ’, ὦ ἄνδρες Ἀθηναῖοι, οὐδέτερόν μοι δοκεῖ τῶν χαλεπῶν εἶναι, οὔτ’ ἐπιτιμήσαντα τοῖς νέμουσι καὶ διδοῦσι τὰ κοινὰ εὐδοκιμῆσαι παρὰ τοῖς βλάπτεσθαι διὰ τούτων ἡγουμένοις τὴν πόλιν, οὔτε συνειπόντα καὶ παραινέσανθ’ ὡς δεῖ λαμβάνειν, χαρίσασθαι τοῖς σφόδρ’ ἐν χρείᾳ τοῦ λαβεῖν οὖσιν· οὐδέτεροι γὰρ πρὸς τὸ τῇ πόλει συμφέρον σκοποῦντες οὔτ’ ἐπαινοῦσιν οὔτε δυσχεραίνουσι τὸ πρᾶγμα, ἀλλ’ ὡς ἑκάτεροι χρείας καὶ περιουσίας ἔχουσιν.", "st": "13.1"}, {"sp": "N", "t": "ἐγὼ δὲ τοῦτο μὲν οὔτ’ ἂν εἰσηγησαίμην, οὔτ’ ἂν ἀντείποιμ’ ὡς οὐ δεῖ λαμβάνειν· παραινῶ μέντοι σκοπεῖν καὶ λογίζεσθαι πρὸς ὑμᾶς αὐτοὺς ὅτι τἀργύριον μέν ἐστι τοῦθ’, ὑπὲρ οὗ βουλεύεσθε, μικρόν, τὸ δ’ ἔθος μέγα, ὃ γίγνεται μετὰ τούτου. εἰ μὲν οὖν μετὰ τοῦ πράττειν ἃ προσήκει καὶ τὸ λαμβάνειν κατασκευάσεσθε, οὐ μόνον οὐ βλάψετε, ἀλλὰ καὶ τὰ μέγιστ’ ὠφελήσετε τὴν πόλιν καὶ ὑμᾶς αὐτούς· εἰ δὲ τοῦ μὲν λαμβάνειν καὶ ἑορτὴ καὶ πᾶσ’ ἀρκέσει πρόφασις, τοῦ δ’ ἃ πρὸς τούτοις δεῖ ποιεῖν μηδὲ τοὺς λόγους ἀκούειν ἐθελήσετε, ὁρᾶτε μήποθ’, ἃ νῦν ὀρθῶς ἡγεῖσθε πράττειν, σφόδρ’ ἡμαρτηκέναι νομίσητε.", "st": "13.2"}, {"sp": "N", "t": "ἐγὼ δέ φημι δεῖν (καί μοι μὴ θορυβήσητ’ ἐφ’ ᾧ μέλλω λέγειν, ἀλλ’ ἀκούσαντες κρίνατε), ὡς περὶ τοῦ λαβεῖν ἐκκλησίαν ἀπεδώκαμεν, οὕτω καὶ περὶ τοῦ συνταχθῆναι καὶ παρασκευασθῆναι τὰ πρὸς τὸν πόλεμον ἐκκλησίαν ἀποδοῦναι, καὶ παρασχεῖν ἕκαστον αὑτὸν μὴ μόνον ταῦτ’ ἀκούειν ἐθέλοντα, ἀλλὰ καὶ πράττειν βουλόμενον, ἵν’, ὦ ἄνδρες Ἀθηναῖοι, τῶν ἀγαθῶν τὰς ἐλπίδας δι’ ὑμῶν αὐτῶν ἔχητε, καὶ μὴ τὸν δεῖνα μηδὲ τὸν δεῖνα πυνθάνησθε τί πράττει.", "st": "13.3"}, {"sp": "N", "t": "καὶ τὰ μὲν προσιόντα τῇ πόλει πάντα, καὶ ἃ νῦν ἐκ τῶν ἰδίων παραναλίσκετ’ εἰς οὐδὲν δέον καὶ ὅσ’ ἐκ τῶν συμμάχων ὑπάρχει, λαμβάνειν ὑμᾶς φημὶ χρῆναι τὸ ἴσον ἕκαστον, τοὺς μὲν ἐν ἡλικίᾳ στρατιωτικόν, τοὺς δ’ ὑπὲρ τὸν κατάλογον ἐξεταστικὸν ἢ ὅπως ἄν τις ὀνομάσαι τοῦτο, στρατεύεσθαι δ’ αὐτοὺς καὶ μηδενὶ τούτου παραχωρεῖν,", "st": "13.4"}, {"sp": "N", "t": "ἀλλὰ τὴν δύναμιν τῆς πόλεως οἰκείαν εἶναι, κατεσκευασμένην ἀπὸ τούτων, ἵν’ ἅμ’ εὐπορῆτε καὶ τὰ δέοντα ποιῆτε, καὶ τὸν στρατηγὸν ἡγεῖσθαι ταύτης, ἵν’ ὑμῖν, ὦ ἄνδρες Ἀθηναῖοι, μὴ τοιαῦθ’ οἷάπερ νυνὶ συμβαίνῃ· τοὺς στρατηγοὺς κρίνετε, καὶ περίεσθ’ ὑμῖν ἐκ τῶν πραγμάτων “ὁ δεῖνα τοῦ δεῖνος τὸν δεῖν’ εἰσήγγειλεν,” ἄλλο δ’ οὐδέν.", "st": "13.5"}, {"sp": "N", "t": "ἀλλὰ τί ὑμῖν γένηται; πρῶτον μὲν οἱ σύμμαχοι μὴ φρουραῖς, ἀλλὰ τῷ ταὐτὰ συμφέρειν ὑμῖν κἀκείνοις ὦσιν οἰκεῖοι, ἔπειθ’ οἱ στρατηγοὶ μὴ ξένους ἔχοντες τοὺς μὲν συμμάχους ἄγωσι καὶ φέρωσι, τοὺς δὲ πολεμίους μηδ’ ὁρῶσιν, ἀφ’ ὧν αἱ μὲν ὠφέλειαι τούτων εἰσὶν ἴδιαι, τὰ δὲ μίση καὶ τὰ ἐγκλήματα ἐφ’ ὅλην ἔρχεται τὴν πόλιν, ἀλλὰ πολίτας τοὺς ἀκολουθοῦντας ἔχοντες τοὺς ἐχθρούς, ἃ νῦν τοὺς φίλους, ποιῶσιν.", "st": "13.6"}, {"sp": "N", "t": "χωρὶς δὲ τούτων πολλὰ τῶν πραγμάτων τὴν ὑμετέραν ποθεῖ παρουσίαν, καὶ ἄνευ τοῦ πρὸς τοὺς οἰκείους πολέμους οἰκείᾳ χρῆσθαι δυνάμει συμφέρειν, καὶ πρὸς τἄλλα πράγματ’ ἀναγκαῖόν ἐστιν. εἰ μὲν γὰρ ἡσυχίαν ἔχειν ὑμῖν ἀπέχρη καὶ μηδὲν τῶν Ἑλληνικῶν περιεργάζεσθαι ὅπως ἔχει, ἄλλος ἂν ἦν λόγος·", "st": "13.7"}, {"sp": "N", "t": "νῦν δὲ πρωτεύειν μὲν ὑμεῖς ἀξιοῦτε καὶ τὰ δίκαι’ ὁρίζειν τοῖς ἄλλοις, τὴν δὲ ταῦτ’ ἐφορεύσουσαν καὶ φυλάξουσαν δύναμιν οὔτε κατεσκεύασθ’ οὔτε κατασκευάζεσθε, ἀλλ’ ἐπὶ πολλῆς μὲν ἡσυχίας καὶ ἐρημίας ὑμῶν ὁ Μυτιληναίων δῆμος καταλέλυται, ἐπὶ πολλῆς δ’ ἡσυχίας ὁ Ῥοδίων, ἐχθρός γ’ ὢν ἡμῖν, φαίη τις ἄν· ἀλλὰ μείζω χρὴ νομίζειν, ὦ ἄνδρες Ἀθηναῖοι, τὴν πρὸς τὰς ὀλιγαρχίας ὑπὲρ αὐτῆς τῆς προαιρέσεως ἔχθραν, ἢ τὴν πρὸς τοὺς δήμους ὑπὲρ ὧν ποτ’ ἂν ᾖ.", "st": "13.8"}, {"sp": "N", "t": "ἀλλ’ ἵν’ ἐκεῖσ’ ἐπανέλθω, φημὶ δεῖν ὑμᾶς συντετάχθαι, καὶ τὴν αὐτὴν τοῦ τε λαβεῖν καὶ τοῦ ποιεῖν ἃ προσήκει σύνταξιν εἶναι. διελέχθην δ’ ὑμῖν περὶ τούτων καὶ πρότερον, καὶ διεξῆλθον ὡς ἂν συνταχθείητε, οἵ θ’ ὁπλῖται καὶ οἱ ἱππεῖς καὶ ὅσοι τούτων ἐκτός ἐστε, καὶ εὐπορία τις ἂν ἅπασι γένοιτο κοινή.", "st": "13.9"}, {"sp": "N", "t": "ὃ δέ μοι πλείστην ἀθυμίαν παρέσχεν ἁπάντων, ἐρῶ πρὸς ὑμᾶς καὶ οὐκ ἀποκρύψομαι, ὅτι πολλῶν καὶ μεγάλων καὶ καλῶν ὄντων τούτων ἁπάντων, τῶν μὲν ἄλλων οὐδενὸς οὐδεὶς μέμνηται, τοῖν δυοῖν δ’ ὀβολοῖν ἅπαντες. καίτοι τοὺς μὲν οὐκ ἔστι πλείονος ἢ δυοῖν ὀβολοῖν ἀξίους εἶναι, τἄλλα δὲ μετὰ τούτων ὧν εἶπον τῶν βασιλέως ἄξι’ ἐστὶ χρημάτων, πόλιν τοσούτους ὁπλίτας ἔχουσαν καὶ τριήρεις καὶ ἵππους καὶ χρημάτων πρόσοδον συντετάχθαι καὶ παρεσκευάσθαι.", "st": "13.10"}, {"sp": "N", "t": "τί οὖν ταῦτα νῦν [, φαίη τις ἄν,] λέγω; ὅτι φημὶ δεῖν ὑμᾶς, ἐπειδὴ τὸ μὲν πάντας μισθοφορεῖν δυσχεραίνουσί τινες, τὸ δὲ συνταχθῆναι καὶ παρασκευασθῆναι παρὰ πάντων χρήσιμον εἶναι δοκιμάζεται, ἐντεῦθεν ἄρξασθαι τοῦ πράγματος, καὶ προθεῖναι περὶ τούτων τῷ βουλομένῳ γνώμην ἀποφήνασθαι. ὡς οὕτως ἔχει· ἂν μὲν ὑμεῖς νῦν πεισθῆτε τούτων καιρὸν εἶναι, ὅταν αὐτῶν εἰς χρείαν ἔλθητε, ἕτοιμ’ ὑπάρξει· ἂν δ’ ἀκαιρίαν ἡγησάμενοι παρίδητε, ὅταν δέῃ χρῆσθαι, τότ’ ἀναγκασθήσεσθε παρασκευάζεσθαι.", "st": "13.11"}, {"sp": "N", "t": "ἤδη δέ τις εἶπεν ὦ ἄνδρες Ἀθηναῖοί που λέγων, οὐχ ὑμῶν τῶν πολλῶν, ἀλλὰ τῶν διαρρηγνυμένων εἰ ταῦτα γενήσεται, “τί δ’ ὑμῖν ἐκ τῶν Δημοσθένους λόγων ἀγαθὸν γέγονεν; παρελθὼν ὑμῶν, ὅταν αὐτῷ δόξῃ, ἐνέπλησε τὰ ὦτα λόγων, καὶ διέσυρε τὰ παρόντα, καὶ τοὺς προγόνους ἐπῄνεσεν, καὶ μετεωρίσας καὶ φυσήσας ὑμᾶς κατέβη.”", "st": "13.12"}, {"sp": "N", "t": "ἐγὼ δ’ εἰ μὲν ὑμᾶς δυναίμην ὧν λέγω τι πεῖσαι, τηλικαῦτ’ ἂν οἶμαι τὴν πόλιν πρᾶξαι ἀγαθὰ ὥστ’, εἰ νῦν εἰπεῖν ἐπιχειρήσαιμι, πολλοὺς ἂν ἀπιστῆσαι ὡς μείζοσιν ἢ δυνατοῖς· οὐ μὴν οὐδὲ τοῦτο μικρὸν ὠφελεῖν οἶμαι, εἰ τὰ βέλτιστ’ ἀκούειν ὑμᾶς συνεθίζω. δεῖ γάρ, ὦ ἄνδρες Ἀθηναῖοι, τὸν βουλόμενόν τι ποιῆσαι τὴν πόλιν ἡμῶν ἀγαθὸν τὰ ὦτα πρῶτον ὑμῶν ἰάσασθαι· διέφθαρται γάρ· οὕτω πολλὰ καὶ ψευδῆ καὶ πάντα μᾶλλον ἢ τὰ βέλτιστ’ ἀκούειν εἴθισθε.", "st": "13.13"}, {"sp": "N", "t": "οἷον (ὅπως δὲ μὴ θορυβήσει μοι μηδείς, πρὶν ἂν ἅπαντ’ εἴπω) ἀνέῳξαν δήπου πρώην τινὲς τὸν ὀπισθόδομον. οὐκοῦν οἱ παριόντες ἅπαντες τὸν δῆμον καταλελύσθαι, τοὺς νόμους οὐκέτ’ εἶναι, τοιαῦτ’ ἔλεγον. καίτοι, ὦ ἄνδρες Ἀθηναῖοι, (καὶ σκοπεῖτ’ ἂν ἀληθῆ λέγω) οἱ μὲν ταῦτα ποιοῦντες ἄξι’ ἐποίουν θανάτου, ὁ δῆμος δ’ οὐ διὰ τούτων καταλύεται. πάλιν κώπας τις ὑφείλετο· μαστιγοῦν, στρεβλοῦν πάντες οἱ λέγοντες, τὸν δῆμον καταλύεσθαι. ἐγὼ δὲ τί φημί; τὸν μὲν ὑφαιρούμενον θανάτου ποιεῖν ἄξια, ὥσπερ ἐκεῖνοι, τὸν δῆμον δ’ οὐ διὰ τούτων καταλύεσθαι.", "st": "13.14"}, {"sp": "N", "t": "ἀλλὰ πῶς καταλύεται, οὐδεὶς λέγει οὐδὲ παρρησιάζεται. ἐγὼ δὲ φράσω· ὅταν ὑμεῖς, ὦ ἄνδρες Ἀθηναῖοι, φαύλως ἠγμένοι, πολλοὶ καὶ ἄποροι καὶ ἄοπλοι καὶ ἀσύντακτοι καὶ μὴ ταὐτὰ γιγνώσκοντες ἦτε, καὶ μήτε στρατηγὸς μήτ’ ἄλλος μηδεὶς ὧν ἂν ὑμεῖς ψηφίσησθε φροντίζῃ, καὶ ταῦτα μηδεὶς λέγειν ἐθέλῃ μηδ’ ἐπανορθοῖ, μηδ’ ὅπως παύσεται τοιαῦτ’ ὄντα πράττῃ, ὃ νῦν ἀεὶ συμβαίνει.", "st": "13.15"}, {"sp": "N", "t": "καὶ νὴ Δί’, ὦ ἄνδρες Ἀθηναῖοι, ἕτεροί γε λόγοι παρερρυήκασι πρὸς ὑμᾶς ψευδεῖς, καὶ πολλὰ τὴν πολιτείαν βλάπτοντες, οἷον “ἐν τοῖς δικαστηρίοις ὑμῖν ἐστιν ἡ σωτηρία,” καὶ “δεῖ τῇ ψήφῳ τὴν πολιτείαν ὑμᾶς φυλάττειν.” ἐγὼ δ’ οἶδ’ ὅτι ταῦτα μὲν ὑμῖν [τὰ δικαστήρια] τῶν πρὸς ἀλλήλους δικαίων ἐστὶ κύρια, ἐν δὲ τοῖς ὅπλοις δεῖ κρατεῖν τῶν ἐχθρῶν, καὶ διὰ τούτων ἐστὶν ἡ σωτηρία τῆς πολιτείας.", "st": "13.16"}, {"sp": "N", "t": "οὐ γὰρ τὸ ψηφίσασθαι τοῖς ἐν τοῖς ὅπλοις ποιήσει τὸ νικᾶν, ἀλλ’ οἱ μετὰ τούτων κρατοῦντες τοὺς ἐχθροὺς καὶ ψηφίζεσθαι καὶ ἄλλ’ ὅ τι ἂν βούλησθε ποιεῖν ὑμῖν ἐξουσίαν καὶ ἄδειαν παρασκευάσουσι· δεῖ γὰρ ἐν μὲν τοῖς ὅπλοις φοβερούς, ἐν δὲ τοῖς δικαστηρίοις φιλανθρώπους εἶναι.", "st": "13.17"}, {"sp": "N", "t": "εἰ δέ τῳ δοκῶ μείζους ἢ κατ’ ἐμαυτὸν λέγειν λόγους, αὐτὸ τοῦτ’ ὀρθῶς αὐτῶν ἔχει· τὸν γὰρ ὑπὲρ τηλικαύτης πόλεως ῥηθησόμενον λόγον καὶ τοιούτων πραγμάτων παντὸς ἑνὸς τοῦ λέγοντος ἀεὶ μείζω φαίνεσθαι δεῖ, καὶ τῆς ἀξίας τῆς ὑμετέρας ἐγγὺς εἶναι, μὴ τῆς τοῦ λέγοντος. ὅτι δ’ οὐδεὶς τῶν ὑφ’ ὑμῶν τιμωμένων ταῦτα λέγει, τὰς προφάσεις ἐγὼ διέξειμ’ ὑμῖν.", "st": "13.18"}, {"sp": "N", "t": "οἱ μὲν πρὸς ἀρχαιρεσίας καὶ ταύτην τὴν τάξιν προσιόντες δοῦλοι τῆς ἐπὶ τῷ χειροτονεῖσθαι χάριτος περιέρχονται, τελεσθῆναι στρατηγὸς ἕκαστος σπουδάζων, οὐκ ἀνδρὸς ἔργον οὐδὲν πρᾶξαι. εἰ δέ τις καὶ τοιοῦτός ἐστιν οἷος ἐγχειρεῖν ἔργῳ τῳ, νῦν μὲν ἡγεῖται τὴν τῆς πόλεως δόξαν ἀφορμὴν ἔχων καὶ τοὔνομα, τῆς τῶν ἐναντιωσομένων ἐρημίας ἀπολαύων, τὰς ἐλπίδας ὑμῖν ὑποτείνων, ἄλλο δ’ οὐδὲ ἕν, κληρονομήσειν αὐτὸς τῶν ὑμετέρων ἀγαθῶν, ὅπερ ἐστίν, ἂν δ’ ὑμεῖς δι’ ὑμῶν αὐτῶν ἕκαστα πράττητε, τὸ ἴσον τοῖς ἄλλοις ὥσπερ τῶν ἔργων αὐτῶν, οὕτω καὶ τῶν ἐκ τούτων ἕξειν.", "st": "13.19"}, {"sp": "N", "t": "οἱ δὲ πολιτευόμενοι καὶ περὶ ταῦτ’ ὄντες, τὸ τὰ βέλτιστα σκοπεῖν ὑμῖν ἀφέντες, προσκεχωρήκασι πρὸς τούτους· καὶ πρότερον μὲν κατὰ συμμορίας εἰσεφέρετε, νυνὶ δὲ πολιτεύεσθε κατὰ συμμορίας. ῥήτωρ ἡγεμὼν καὶ στρατηγὸς ὑπὸ τούτῳ καὶ οἱ βοησόμενοι μεθ’ ἑκατέρων τριακόσιοι· οἱ δ’ ἄλλοι προσνενέμησθε οἱ μὲν ὡς τούτους, οἱ δ’ ὡς ἐκείνους. τοιγαροῦν ὑμῖν περίεστιν ἐκ τούτων ὁ δεῖνα χαλκοῦς καὶ ὁ δεῖν’ εὐδαίμων, εἷς ἢ δύο, ὑπὲρ τὴν πόλιν· οἱ δ’ ἄλλοι μάρτυρες τῆς τούτων εὐδαιμονίας κάθησθε, τῆς καθ’ ἡμέραν ῥᾳθυμίας πολλὴν καὶ μεγάλην ὑπάρχουσαν ὑμῖν εὐδαιμονίαν τούτοις προϊέμενοι.", "st": "13.20"}, {"sp": "N", "t": "καίτοι σκέψασθε πῶς ἐπὶ τῶν προγόνων ταῦτ’ εἶχεν· οὐ γὰρ ἀλλοτρίοις ὑμῖν παραδείγμασι χρησαμένοις, ἀλλ’ οἰκείοις ἔξεσθ’ ἃ προσήκει πράττειν εἰδέναι. ἐκεῖνοι Θεμιστοκλέα τὸν τὴν ἐν Σαλαμῖνι ναυμαχίαν στρατηγοῦντα καὶ Μιλτιάδην τὸν ἡγούμενον Μαραθῶνι καὶ πολλοὺς ἄλλους, οὐκ ἴσα τοῖς νῦν στρατηγοῖς ἀγάθ’ εἰργασμένους, μὰ Δί’ οὐ χαλκοῦς ἵστασαν, ἀλλ’ ὡς οὐδὲν αὑτῶν κρείττους ὄντας, οὕτως ἐτίμων.", "st": "13.21"}, {"sp": "N", "t": "καὶ γάρ τοι τῶν ἔργων οὐδενός, ὦ ἄνδρες Ἀθηναῖοι, τῶν τότ’ ἀπεστέρησαν αὑτούς, οὐδ’ ἔστ’ οὐδεὶς ὅστις ἂν εἴποι τὴν ἐν Σαλαμῖνι ναυμαχίαν Θεμιστοκλέους, ἀλλ’ Ἀθηναίων, οὐδὲ τὴν [ἐν] Μαραθῶνι μάχην Μιλτιάδου, ἀλλὰ τῆς πόλεως. νῦν δὲ πολλοὶ τοῦτο λέγουσιν, ὡς Κέρκυραν εἷλε Τιμόθεος καὶ τὴν μόραν κατέκοψεν Ἰφικράτης καὶ τὴν περὶ Νάξον ναυμαχίαν ἐνίκα Χαβρίας· δοκεῖτε γὰρ αὐτοὶ τῶν ἔργων τούτων παραχωρεῖν τῶν τιμῶν ταῖς ὑπερβολαῖς αἷς δεδώκατ’ ἐπ’ αὐτοῖς ἑκάστῳ τούτων.", "st": "13.22"}, {"sp": "N", "t": "τὰς μὲν δὴ πολιτικὰς δωρεὰς οὕτως ἐκεῖνοί τε καλῶς καὶ ὑμεῖς οὐκ ὀρθῶς· τὰς δὲ τῶν ξένων πῶς; ἐκεῖνοι Μένωνι τῷ Φαρσαλίῳ δώδεκα μὲν τάλαντ’ ἀργυρίου δόντι πρὸς τὸν ἐπ’ Ἠιόνι τῇ πρὸς Ἀμφιπόλει πόλεμον, διακοσίοις δ’ ἱππεῦσι πενέσταις ἰδίοις βοηθήσαντι, οὐκ ἐψηφίσαντο πολιτείαν, ἀλλ’ ἀτέλειαν ἔδωκαν μόνον.", "st": "13.23"}, {"sp": "N", "t": "καὶ πρότερον τούτου Περδίκκᾳ τῷ κατὰ τὴν τοῦ βαρβάρου ποτ’ ἐπιστρατείαν βασιλεύοντι Μακεδονίας, τοὺς ἀναχωροῦντας ἐκ Πλαταιῶν τῶν βαρβάρων ἀπὸ τῆς ἥττης διαφθείραντι καὶ τέλειον τἀτύχημα ποιήσαντι τῷ βασιλεῖ, οὐκ ἐψηφίσαντο πολιτείαν, ἀλλ’ ἀτέλειαν ἔδωκαν μόνον, μεγάλην καὶ τιμίαν, οἶμαι, καὶ σεμνὴν τὴν αὑτῶν πατρίδ’ ἡγούμενοι καὶ πάσης μείζον’ εὐεργεσίας. νῦν δ’, ὦ ἄνδρες Ἀθηναῖοι, φθόρους ἀνθρώπους οἰκοτρίβων οἰκότριβας, τιμὴν ὥσπερ ἄλλου του τῶν ὠνίων λαμβάνοντες, ποιεῖσθε πολίτας.", "st": "13.24"}, {"sp": "N", "t": "ταῦτα δ’ ὑμῖν ἐπελήλυθε πράττειν, οὐχ ὅτι τὰς φύσεις χείρους ἐστὲ τῶν προγόνων, ἀλλ’ ὅτι τοῖς μὲν ἐφ’ αὑτοῖς παρειστήκει μέγα φρονεῖν, ὑμῶν δ’, ὦ ἄνδρες Ἀθηναῖοι, περιῄρηται τοῦτο. ἔστι δ’ οὐδέποτ’, οἶμαι, δυνατὸν μικρὰ καὶ φαῦλα πράττοντας μέγα καὶ νεανικὸν φρόνημα λαβεῖν, ὥσπερ οὐδὲ λαμπρὰ καὶ καλὰ πράττοντας μικρὸν καὶ ταπεινὸν φρονεῖν· ὁποῖ’ ἄττα γὰρ ἂν τἀπιτηδεύματα τῶν ἀνθρώπων ᾖ, τοιοῦτον ἀνάγκη καὶ τὸ φρόνημ’ ἔχειν.", "st": "13.25"}, {"sp": "N", "t": "σκέψασθε δ’ ἅ τις κεφάλαι’ ἂν ἔχοι [τῶν πραγμάτων] εἰπεῖν τῶν τ’ ἐκείνοις πεπραγμένων καὶ τῶν ὑμῖν, ἂν ἄρ’ ὑμῶν αὐτῶν ἀλλ’ ἐκ τούτων γε δύνησθε γενέσθαι. πέντε μὲν καὶ τετταράκοντ’ ἔτη τῶν Ἑλλήνων ἦρξαν ἑκόντων ἐκεῖνοι, πλείω δ’ ἢ μύρια τάλαντ’ εἰς τὴν ἀκρόπολιν ἀνήγαγον, πολλὰ δὲ καὶ καλὰ καὶ πεζῇ καὶ ναυμαχοῦντες ἔστησαν τρόπαια, ἐφ’ οἷς ἔτι καὶ νῦν ἡμεῖς φιλοτιμούμεθα. καίτοι νομίζετ’ αὐτοὺς ταῦτα στῆσαι, οὐχ ἵνα θαυμάζωμεν ἡμεῖς θεωροῦντες αὐτά, ἀλλ’ ἵνα καὶ μιμώμεθα τὰς τῶν ἀναθέντων ἀρετάς.", "st": "13.26"}, {"sp": "N", "t": "ἐκεῖνοι μὲν δὴ ταῦτα· ἡμεῖς δ’, ὅσης ἅπαντες ὁρᾶτ’ ἐρημίας ἐπειλημμένοι, σκέψασθ’ εἰ παραπλήσια. οὐ πλείω μὲν ἢ χίλια καὶ πεντακόσια τάλαντ’ ἀνήλωται μάτην εἰς τοὺς τῶν Ἑλλήνων ἀπόρους, ἐξανήλωνται δ’ οἵ τ’ ἴδιοι πάντες οἶκοι καὶ τὰ κοινὰ τῇ πόλει καὶ τὰ παρὰ τῶν συμμάχων, οὓς δ’ ἐν τῷ πολέμῳ συμμάχους ἐκτησάμεθα, οὗτοι νῦν ἐν τῇ εἰρήνῃ ἀπολώλασιν;", "st": "13.27"}, {"sp": "N", "t": "ἀλλὰ νὴ Δία ταῦτα μόνον τότ’ εἶχε βέλτιον ἢ νῦν, τὰ δ’ ἄλλα χεῖρον. πολλοῦ γε καὶ δεῖ, ἀλλ’ ὅ τι βούλεσθ’ ἐξετάσωμεν. οἰκοδομήματα μέν γε καὶ κόσμον τῆς πόλεως, ἱερῶν καὶ λιμένων καὶ τῶν ἀκολούθων τούτοις, τοιοῦτον καὶ τοσοῦτον κατέλιπον ἐκεῖνοι ὥστε μηδενὶ τῶν ἐπιγιγνομένων ὑπερβολὴν λελεῖφθαι, προπύλαια ταῦτα, νεώσοικοι, στοαί, τἄλλα, οἷς ἐκεῖνοι κοσμήσαντες τὴν πόλιν ἡμῖν παρέδωκαν·", "st": "13.28"}, {"sp": "N", "t": "τὰς δ’ ἰδίας οἰκίας τῶν ἐν δυνάμει γενομένων οὕτω μετρίας καὶ τῷ τῆς πολιτείας ὀνόματι ἀκολούθους ὥστε τὴν Θεμιστοκλέους καὶ τὴν Κίμωνος καὶ τὴν Ἀριστείδου καὶ τῶν τότε λαμπρῶν οἰκίαν, εἴ τις ἄρ’ ὑμῶν οἶδεν ὁποία ποτ’ ἐστίν, ὁρᾷ τῆς τοῦ γείτονος οὐδὲν σεμνοτέραν οὖσαν.", "st": "13.29"}, {"sp": "N", "t": "νῦν δ’, ὦ ἄνδρες Ἀθηναῖοι, δημοσίᾳ μὲν ἡ πόλις ἡμῶν τὰς ὁδοὺς ἀγαπᾷ κατασκευάζουσα καὶ κρήνας καὶ κονιάματα καὶ λήρους (καὶ οὐ τοῖς εἰσηγησαμένοις ταῦτ’ ἐπιτιμῶ, πολλοῦ γε καὶ δέω, ἀλλ’ ὑμῖν, εἰ ταῦθ’ ἱκανὰ ὑμῖν αὐτοῖς ὑπολαμβάνετ’ εἶναι), ἰδίᾳ δ’ οἱ τῶν κοινῶν ἐπί τῳ γεγενημένοι οἱ μὲν τῶν δημοσίων οἰκοδομημάτων σεμνοτέρας τὰς ἰδίας οἰκίας κατεσκευάκασιν, οὐ μόνον τῶν πολλῶν ὑπερηφανωτέρας, οἱ δὲ γῆν συνεωνημένοι γεωργοῦσιν ὅσην οὐδ’ ὄναρ ἤλπισαν πώποτε.", "st": "13.30"}, {"sp": "N", "t": "τούτων δ’ αἴτιον ἁπάντων, ὅτι τότε μὲν ὁ δῆμος δεσπότης ἦν καὶ κύριος ἁπάντων, καὶ ἀγαπητὸν ἦν παρ’ ἐκείνου τῶν ἄλλων ἑκάστῳ καὶ τιμῆς καὶ ἀρχῆς καὶ ἀγαθοῦ τινὸς μεταλαμβάνειν, νῦν δὲ τοὐναντίον κύριοι μὲν τῶν ἀγαθῶν οὗτοι, καὶ διὰ τούτων ἅπαντα πράττεται, ὁ δὲ δῆμος ἐν ὑπηρέτου καὶ προσθήκης μέρει, καὶ ὑμεῖς ἀγαπᾶθ’ ἃν οὗτοι μεταδιδῶσι λαμβάνοντες.", "st": "13.31"}, {"sp": "N", "t": "τοιγαροῦν ἐκ τούτων τοιαῦτα τὰ πράγματα τῆς πόλεώς ἐστιν ὥστε, εἴ τις ἀναγνοίη τὰ ψηφίσμαθ’ ὑμῶν καὶ τὰς πράξεις ἐφεξῆς διέλθοι, οὐδ’ ἂν εἷς πιστεύσαι τῶν αὐτῶν εἶναι ταῦτα κἀκεῖνα. οἷον ἃ πρὸς τοὺς καταράτους Μεγαρέας ἐψηφίσασθ’ ἀποτεμνομένους τὴν ὀργάδα, ἐξιέναι, κωλύειν, μὴ ἐπιτρέπειν· ἃ πρὸς Φλειασίους, ὅτ’ ἐξέπεσον ἔναγχος, βοηθεῖν, μὴ ἐπιτρέπειν τοῖς σφαγεῦσι, τῶν ἐν Πελοποννήσῳ τοὺς βουλομένους παρακαλεῖν.", "st": "13.32"}, {"sp": "N", "t": "ἅπαντα καλά, ὦ ἄνδρες Ἀθηναῖοι, ταῦτα καὶ δίκαια καὶ τῆς πόλεως ἄξια· τὰ ἔργα δὲ τἀπὸ τούτων οὐδαμοῦ. οὐκοῦν τὴν μὲν ἀπέχθειαν διὰ τῶν ψηφισμάτων ἐκφέρεσθε, τῶν δ’ ἔργων οὐδενὸς κύριοι γίγνεσθε· τὰ μὲν γὰρ ψηφίσματα πρὸς τὸ τῆς πόλεως ἀξίωμα ψηφίζεσθε, τὴν δύναμιν δ’ οὐκ ἀκόλουθον ὧν ψηφίζεσθ’ ἔχετε.", "st": "13.33"}, {"sp": "N", "t": "ἐγὼ δὲ παραινέσαιμ’ ἂν ὑμῖν (καί μοι μηδὲν ὀργισθῆτε) ἔλαττον φρονεῖν καὶ τὰ ὑμέτερ’ αὐτῶν ἀγαπᾶν πράττοντας, ἢ μείζω δύναμιν παρασκευάζεσθαι. εἰ μὲν οὖν Σιφνίοις ἢ Κυθνίοις ἤ τισιν ἄλλοις τοιούτοις οὖσι συνῄδειν ὑμῖν, ἔλαττον φρονεῖν συνεβούλευον ἄν· ἐπειδὴ δ’ ἔστ’ Ἀθηναῖοι, τὸ τὴν δύναμιν παρασκευάσασθαι παραινῶ· αἰσχρὸν γάρ, ὦ ἄνδρες Ἀθηναῖοι, αἰσχρὸν λιπεῖν τὴν τοῦ φρονήματος τάξιν, ἣν ὑμῖν οἱ πρόγονοι παρέδωκαν.", "st": "13.34"}, {"sp": "N", "t": "πρὸς δὲ τούτοις οὐδ’ ἔστιν ἐφ’ ὑμῖν, οὐδ’ ἂν ἀποστῆναι τῶν Ἑλληνικῶν βούλησθε· πολλὰ γὰρ ὑμῖν ἐκ παντὸς τοῦ χρόνου πέπρακται, καὶ τοὺς μὲν φίλους τοὺς ὑπάρχοντας αἰσχρὸν προέσθαι, τοῖς δ’ οὖσιν ἐχθροῖς οὐκ ἔνι πιστεῦσαι καὶ μεγάλους ἐᾶσαι γενέσθαι. ὅλως δ’ ὅπερ οἱ πολιτευόμενοι πεπόνθασι πρὸς ὑμᾶς—οὐκ ἔνεστιν αὐτοῖς, ὅταν βούλωνται, παύσασθαι—τοῦτο καὶ ὑμῖν περιέστηκε· πεπολίτευσθε γὰρ ἐν τοῖς Ἕλλησιν.", "st": "13.35"}, {"sp": "N", "t": "ἔστι δ’, ὦ ἄνδρες Ἀθηναῖοι, κεφάλαιον ἁπάντων τῶν εἰρημένων· οὐδέποθ’ ὑμᾶς οἱ λέγοντες οὔτε πονηροὺς οὔτε χρηστοὺς ποιοῦσιν, ἀλλ’ ὑμεῖς τούτους, ὁπότερ’ ἂν βούλησθε· οὐ γὰρ ὑμεῖς ὧν οὗτοι βούλονται στοχάζεσθε, ἀλλ’ οὗτοι ὧν ἂν ὑμᾶς ἐπιθυμεῖν οἴωνται. ὑμᾶς οὖν ὑπάρξαι δεῖ χρηστὰ βουλομένους, καὶ πάνθ’ ἕξει καλῶς· ἢ γὰρ οὐδεὶς ἐρεῖ φλαῦρον οὐδέν, ἢ οὐδὲν αὐτῷ πλέον ἔσται μὴ ἔχοντι τοὺς πεισομένους.", "st": "13.36"}, {"sp": "HDR", "t": "Περὶ τῶν συμμοριῶν", "st": "14"}, {"sp": "N", "t": "οἱ μὲν ἐπαινοῦντες, ὦ ἄνδρες Ἀθηναῖοι, τοὺς προγόνους ὑμῶν λόγον εἰπεῖν μοι δοκοῦσι προαιρεῖσθαι κεχαρισμένον, οὐ μὴν συμφέροντά γ’ ἐκείνοις οὓς ἐγκωμιάζουσι ποιεῖν· περὶ γὰρ πραγμάτων ἐγχειροῦντες λέγειν ὧν οὐδ’ εἷς ἀξίως ἐφικέσθαι τῷ λόγῳ δύναιτο, αὐτοὶ μὲν τοῦ δοκεῖν δύνασθαι λέγειν δόξαν ἐκφέρονται, τὴν δ’ ἐκείνων ἀρετὴν ἐλάττω τῆς ὑπειλημμένης παρὰ τοῖς ἀκούουσιν φαίνεσθαι ποιοῦσιν. ἐγὼ δ’ ἐκείνων μὲν ἔπαινον τὸν χρόνον ἡγοῦμαι μέγιστον, οὗ πολλοῦ γεγενημένου μείζω τῶν ὑπ’ ἐκείνων πραχθέντων οὐδένες ἄλλοι παραδείξασθαι δεδύνηνται·", "st": "14.1"}, {"sp": "N", "t": "αὐτὸς δὲ πειράσομαι τὸν τρόπον εἰπεῖν ὃν ἄν μοι δοκεῖτε μάλιστα δύνασθαι παρασκευάσασθαι. καὶ γὰρ οὕτως ἔχει· εἰ μὲν ἡμεῖς ἅπαντες οἱ μέλλοντες λέγειν δεινοὶ φανείημεν ὄντες, οὐδὲν ἂν τὰ ὑμέτερ’ εὖ οἶδ’ ὅτι βέλτιον σχοίη· εἰ δὲ παρελθὼν εἷς ὁστισοῦν δύναιτο διδάξαι καὶ πεῖσαι, τίς παρασκευὴ καὶ πόση καὶ πόθεν πορισθεῖσα χρήσιμος ἔσται τῇ πόλει, πᾶς ὁ παρὼν φόβος λελύσεται. ἐγὼ δὲ τοῦτ’, ἂν ἄρ’ οἷός τ’ ὦ, πειράσομαι ποιῆσαι, μικρὰ προειπὼν ὑμῖν ὡς ἔχω γνώμης περὶ τῶν πρὸς τὸν βασιλέα.", "st": "14.2"}, {"sp": "N", "t": "ἐγὼ νομίζω κοινὸν ἐχθρὸν ἁπάντων τῶν Ἑλλήνων εἶναι βασιλέα, οὐ μὴν διὰ τοῦτο παραινέσαιμ’ ἂν μόνοις τῶν ἄλλων ὑμῖν πόλεμον πρὸς αὐτὸν ἄρασθαι· οὐδὲ γὰρ αὐτοὺς τοὺς Ἕλληνας ὁρῶ κοινοὺς ἀλλήλοις ὄντας φίλους, ἀλλ’ ἐνίους μᾶλλον ἐκείνῳ πιστεύοντας ἤ τισιν αὑτῶν. ἐκ δὴ τῶν τοιούτων νομίζω συμφέρειν ὑμῖν τὴν μὲν ἀρχὴν τοῦ πολέμου τηρεῖν ὅπως ἴση καὶ δικαία γενήσεται, παρασκευάζεσθαι δ’ ἃ προσήκει πάντα καὶ τοῦθ’ ὑποκεῖσθαι.", "st": "14.3"}, {"sp": "N", "t": "ἡγοῦμαι γάρ, ὦ ἄνδρες Ἀθηναῖοι, τοὺς Ἕλληνας, εἰ μὲν ἐναργὲς [τι] γένοιτο καὶ σαφὲς ὡς βασιλεὺς αὐτοῖς ἐπιχειρεῖ, κἂν συμμαχῆσαι καὶ χάριν μεγάλην ἔχειν τοῖς πρὸ αὐτῶν καὶ μετ’ αὐτῶν ἐκεῖνον ἀμυνομένοις· εἰ δ’ ἔτ’ ἀδήλου τούτου καθεστηκότος προαπεχθησόμεθ’ ἡμεῖς, δέδι’, ὦ ἄνδρες Ἀθηναῖοι, μὴ τούτοις μετ’ ἐκείνου πολεμεῖν ἀναγκασθῶμεν, ὑπὲρ ὧν προνοούμεθα.", "st": "14.4"}, {"sp": "N", "t": "ὁ μὲν γὰρ ἐπισχὼν ὧν ὥρμηκεν, εἰ ἄρ’ ἐγχειρεῖν ἔγνωκε τοῖς Ἕλλησι, χρήματα δώσει τισὶν αὐτῶν καὶ φιλίαν προτενεῖται, οἱ δὲ τοὺς ἰδίους πολέμους ἐπανορθῶσαι βουλόμενοι καὶ τοῦτον τὸν νοῦν ἔχοντες τὴν κοινὴν ἁπάντων σωτηρίαν παρόψονται. εἰς δὲ τὴν ταραχὴν ταύτην καὶ τὴν ἀγνωμοσύνην παραινῶ μὴ προκαθεῖναι τὴν πόλιν ἡμῶν.", "st": "14.5"}, {"sp": "N", "t": "οὐδὲ γὰρ οὐδ’ ἀπ’ ἴσης ὁρῶ τοῖς τ’ ἄλλοις Ἕλλησι καὶ ὑμῖν περὶ τῶν πρὸς τὸν βασιλέα τὴν βουλὴν οὖσαν, ἀλλ’ ἐκείνων μὲν πολλοῖς ἐνδέχεσθαί μοι δοκεῖ τῶν ἰδίᾳ τι συμφερόντων διοικουμένοις τῶν ἄλλων Ἑλλήνων ἀμελῆσαι, ὑμῖν δ’ οὐδ’ ἀδικουμένοις παρὰ τῶν ἀδικούντων καλόν ἐστιν λαβεῖν ταύτην τὴν δίκην, ἐᾶσαί τινας αὐτῶν ὑπὸ τῷ βαρβάρῳ γενέσθαι.", "st": "14.6"}, {"sp": "N", "t": "ὅτε δ’ οὕτω ταῦτ’ ἔχει, σκεπτέον ὅπως μήθ’ ἡμεῖς ἐν τῷ πολέμῳ γενησόμεθ’ οὐκ ἴσοι, μήτ’ ἐκεῖνος, ὃν ἡμεῖς ἐπιβουλεύειν ἡγούμεθα τοῖς Ἕλλησι, τὴν τοῦ φίλος αὐτοῖς δοκεῖν εἶναι πίστιν λήψεται. πῶς οὖν ταῦτ’ ἔσται; ἂν ἡ μὲν δύναμις τῆς πόλεως ἐξητασμένη καὶ παρεσκευασμένη πᾶσιν ᾖ φανερά, φαίνηται δὲ δίκαι’ ἐπὶ ταύτῃ φρονεῖν αἱρουμένη.", "st": "14.7"}, {"sp": "N", "t": "τοῖς δὲ θρασυνομένοις καὶ σφόδρ’ ἑτοίμως πολεμεῖν κελεύουσιν ἐκεῖνο λέγω, ὅτι οὐκ ἔστιν χαλεπὸν οὔθ’ ὅταν βουλεύεσθαι δέῃ, δόξαν ἀνδρείας λαβεῖν, οὔθ’ ὅταν κίνδυνός τις ἐγγὺς ᾖ, δεινὸν εἰπεῖν φανῆναι, ἀλλ’ ἐκεῖνο καὶ χαλεπὸν καὶ προσῆκον, ἐπὶ μὲν τῶν κινδύνων τὴν ἀνδρείαν ἐνδείκνυσθαι, ἐν δὲ τῷ συμβουλεύειν φρονιμώτερα τῶν ἄλλων εἰπεῖν ἔχειν.", "st": "14.8"}, {"sp": "N", "t": "ἐγὼ δ’, ὦ ἄνδρες Ἀθηναῖοι, νομίζω τὸν μὲν πόλεμον τὸν πρὸς βασιλέα χαλεπὸν τῇ πόλει, τὸν δ’ ἀγῶνα τὸν ἐκ τοῦ πολέμου ῥᾴδιον ἂν συμβῆναι. διὰ τί; ὅτι τοὺς μὲν πολέμους ἅπαντας ἀναγκαίως ἡγοῦμαι τριήρων καὶ χρημάτων καὶ τόπων δεῖσθαι, ταῦτα δὲ πάντ’ ἀφθονώτερ’ ἐκεῖνον ἔχονθ’ ἡμῶν εὑρίσκω· τοὺς δ’ ἀγῶνας οὐδενὸς οὕτω τῶν ἄλλων ὁρῶ δεομένους ὡς ἀνδρῶν ἀγαθῶν, τούτους δ’ ἡμῖν καὶ τοῖς μεθ’ ἡμῶν κινδυνεύουσι πλείους ὑπάρχειν νομίζω.", "st": "14.9"}, {"sp": "N", "t": "τὸν μὲν δὴ πόλεμον διὰ ταῦτα παραινῶ μηδ’ ἐξ ἑνὸς τρόπου προτέρους ἀνελέσθαι, ἐπὶ δὲ τὸν ἀγῶνα ὀρθῶς φημι παρεσκευασμένους ὑπάρχειν χρῆναι. εἰ μὲν οὖν ἕτερος μὲν ἦν τις τρόπος δυνάμεως ᾗ τοὺς βαρβάρους οἷόν τ’ ἦν ἀμύνασθαι, ἕτερος δέ τις ᾗ τοὺς Ἕλληνας, εἰκότως ἂν ἴσως φανεροὶ πρὸς ἐκεῖνον ἐγιγνόμεθ’ ἀντιταττόμενοι·", "st": "14.10"}, {"sp": "N", "t": "ἐπεὶ δὲ πάσης ἐστὶ παρασκευῆς ὁ αὐτὸς τρόπος καὶ δεῖ ταὔτ’ εἶναι κεφάλαια τῆς δυνάμεως, τοὺς ἐχθροὺς ἀμύνασθαι δύνασθαι, τοῖς οὖσι συμμάχοις βοηθεῖν, τὰ ὑπάρχοντ’ ἀγαθὰ σῴζειν, τί τοὺς ὁμολογουμένως ἐχθροὺς ἔχοντες ἑτέρους ζητοῦμεν; ἀλλὰ παρασκευασώμεθα μὲν πρὸς αὐτούς, ἀμυνούμεθα δὲ κἀκεῖνον, ἂν ἡμᾶς ἀδικεῖν ἐπιχειρῇ.", "st": "14.11"}, {"sp": "N", "t": "καὶ νῦν μὲν καλεῖτε πρὸς ὑμᾶς αὐτοὺς τοὺς Ἕλληνας· ἂν δ’ ἃ κελεύουσιν οὗτοι μὴ ποιῆτε, οὐχ ἡδέως ἐνίων ὑμῖν ἐχόντων, πῶς χρὴ προσδοκᾶν τιν’ ὑπακούσεσθαι; ὅτι νὴ Δί’ ἀκούσονται παρ’ ἡμῶν ὡς ἐπιβουλεύει βασιλεὺς αὐτοῖς. αὐτοὺς δ’ οὐ προορᾶν, ὦ πρὸς τοῦ Διός, οἴεσθε τοῦτο; ἐγὼ μὲν γὰρ οἶμαι. ἀλλ’ οὔπω μείζων ἔσθ’ ὁ φόβος τῶν πρὸς ὑμᾶς καὶ πρὸς ἀλλήλους ἐνίοις διαφορῶν. οὐδὲν οὖν ἀλλ’ ἢ ῥαψῳδήσουσιν οἱ πρέσβεις περιιόντες.", "st": "14.12"}, {"sp": "N", "t": "τότε δ’, ἂν ἄρ’ ἃ νῦν οἰόμεθ’ ἡμεῖς πράττηται, οὐδεὶς δήπου τῶν πάντων Ἑλλήνων τηλικοῦτον ἐφ’ αὑτῷ φρονεῖ, ὅστις ὁρῶν ὑμῖν χιλίους μὲν ἱππέας, ὁπλίτας δ’ ὅσους ἂν ἐθέλῃ τις, ναῦς δὲ τριακοσίας, οὐχ ἥξει καὶ δεήσεται, μετὰ τούτων ἀσφαλέστατ’ ἂν ἡγούμενος σωθῆναι. οὐκοῦν ἐκ μὲν τοῦ καλεῖν ἤδη τὸ δεῖσθαι κἂν μὴ τύχητ’ ἀφαμαρτεῖν, ἐκ δὲ τοῦ μετὰ τοῦ παρεσκευάσθαι τὰ ὑμέτερ’ αὐτῶν ἐπισχεῖν δεομένους σῴζειν καὶ εὖ εἰδέναι πάντας ἥξοντάς ἐστιν.", "st": "14.13"}, {"sp": "N", "t": "ἐγὼ τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, ταῦτά τε καὶ παραπλήσια τούτοις λογιζόμενος λόγον μὲν οὐδέν’ ἐβουλόμην θρασὺν οὐδ’ ἔχοντα μάταιον μῆκος εὑρεῖν· τὴν μέντοι παρασκευήν, ὅπως ὡς ἄριστα καὶ τάχιστα γενήσεται, πάνυ πολλὰ πράγματ’ ἔσχον σκοπῶν. οἴομαι δὴ δεῖν ἀκούσαντας ὑμᾶς αὐτήν, ἂν ὑμῖν ἀρέσκῃ, ψηφίσασθαι. ἔστι τοίνυν πρῶτον μὲν τῆς παρασκευῆς, ὦ ἄνδρες Ἀθηναῖοι, καὶ μέγιστον, οὕτω διακεῖσθαι τὰς γνώμας ὑμᾶς ὡς ἕκαστον ἑκόντα προθύμως ὅ τι ἂν δέῃ ποιήσοντα.", "st": "14.14"}, {"sp": "N", "t": "ὁρᾶτε γάρ, ὦ ἄνδρες Ἀθηναῖοι, ὅτι, ὅσα μὲν πώποθ’ ἅπαντες ἐβουλήθητε καὶ μετὰ ταῦτα τὸ πράττειν αὐτὸς ἕκαστος ἑαυτῷ προσήκειν ἡγήσατο, οὐδὲν πώποθ’ ὑμᾶς ἐξέφυγεν, ὅσα δ’ ἐβουλήθητε μέν, μετὰ ταῦτα δ’ ἀπεβλέψατ’ εἰς ἀλλήλους ὡς αὐτὸς μὲν ἕκαστος οὐ ποιήσων, τὸν δὲ πλησίον πράξοντα, οὐδὲν πώποθ’ ὑμῖν ἐγένετο.", "st": "14.15"}, {"sp": "N", "t": "ἐχόντων δ’ ὑμῶν οὕτω καὶ παρωξυμμένων, τοὺς διακοσίους καὶ χιλίους ἀναπληρῶσαί φημι χρῆναι καὶ ποιῆσαι δισχιλίους, ὀκτακοσίους αὐτοῖς προσνείμαντας· ἐὰν γὰρ τοῦτ’ ἀποδείξητε τὸ πλῆθος, ἡγοῦμαι, τῶν ἐπικλήρων καὶ τῶν ὀρφανῶν καὶ τῶν κληρουχικῶν καὶ τῶν κοινωνικῶν καὶ εἴ τις ἀδύνατος ἀφαιρεθέντων, ἔσεσθαι χίλια καὶ διακόσια ταῦθ’ ὑμῖν σώματα.", "st": "14.16"}, {"sp": "N", "t": "ἐκ τοίνυν τούτων οἶμαι δεῖν ποιῆσαι συμμορίας εἴκοσιν, ὥσπερ νῦν εἰσιν, ἑξήκοντα σώματ’ ἔχουσαν ἑκάστην. τούτων δὲ τῶν συμμοριῶν ἑκάστην διελεῖν κελεύω πέντε μέρη κατὰ δώδεκ’ ἄνδρας, ἀνταναπληροῦντας πρὸς τὸν εὐπορώτατον ἀεὶ τοὺς ἀπορωτάτους. καὶ τὰ μὲν σώμαθ’ οὕτω συντετάχθαι φημὶ δεῖν· δι’ ὃ δ’, εἴσεσθε, ἐπειδὰν ὅλον τὸν τρόπον τῆς συντάξεως ἀκούσητε.", "st": "14.17"}, {"sp": "N", "t": "τὰς δὲ τριήρεις πῶς; τὸν ἅπαντ’ ἀριθμὸν κελεύω τριακοσίας ἀποδείξαντας, κατὰ πεντεκαιδεκαναΐαν εἴκοσι ποιῆσαι μέρη, τῶν πρώτων ἑκατὸν πέντε, καὶ τῶν δευτέρων ἑκατὸν πέντε, καὶ τῶν τρίτων ἑκατὸν πένθ’ ἑκάστῳ μέρει διδόντας, εἶτα συγκληρῶσαι συμμορίᾳ σωμάτων ἑκάστῃ τὴν πεντεκαιδεκαναΐαν, τὴν δὲ συμμορίαν ἑκάστῳ τῷ μέρει σφῶν αὐτῶν τρεῖς ἀποδοῦναι τριήρεις.", "st": "14.18"}, {"sp": "N", "t": "ἐπειδὰν δὲ ταῦθ’ οὕτως ἔχονθ’ ὑπάρχῃ, κελεύω, ἐπειδὴ τὸ τίμημ’ ἐστὶ τῆς χώρας ἑξακισχιλίων ταλάντων, ἵν’ ὑμῖν καὶ τὰ χρήματ’ ᾖ συντεταγμένα, διελεῖν τοῦτο καὶ ποιῆσαι καθ’ ἑξήκοντα τάλανθ’ ἑκατὸν μέρη, εἶτα πένθ’ ἑξηκονταταλαντίας εἰς ἑκάστην τῶν μεγάλων τῶν εἴκοσι συμμοριῶν ἐπικληρῶσαι, τὴν δὲ συμμορίαν ἑκάστῳ τῶν μερῶν μίαν ἑξηκονταταλαντίαν ἀποδοῦναι,", "st": "14.19"}, {"sp": "N", "t": "ὅπως, ἂν μὲν ὑμῖν ἑκατὸν δέῃ τριήρων, τὴν μὲν δαπάνην ἑξήκοντα τάλαντα συντελῇ, τριήραρχοι δ’ ὦσι δώδεκα, ἂν δὲ διακοσίων, τριάκοντα μὲν ᾖ τάλαντα τὴν δαπάνην συντελοῦντα, ἓξ δὲ σώματα τριηραρχοῦντα, ἐὰν δὲ τριακοσίων, εἴκοσιν μὲν ᾖ τάλαντα τὴν δαπάνην διαλύοντα, τέτταρα δὲ σώματα τριηραρχοῦντα.", "st": "14.20"}, {"sp": "N", "t": "τὸν αὐτὸν δὲ τρόπον καὶ τὰ νῦν ὀφειλόμεν’, ὦ ἄνδρες Ἀθηναῖοι, τῶν σκευῶν ἐπὶ τὰς τριήρεις τιμήσαντας ἅπαντ’ ἐκ τοῦ διαγράμματος νεῖμαι κελεύω μέρη εἴκοσιν, ἔπειτα ταῖς μεγάλαις ἐπικληρῶσαι συμμορίαις μέρος ἓν χρήστων ἑκάστῃ, τὴν δὲ συμμορίαν ἑκάστην διανεῖμαι τῶν αὑτῆς μερῶν ἑκάστῳ τὸ ἴσον, τοὺς δὲ δώδεκα τοὺς ἐν ἑκάστῳ τῷ μέρει ταῦτ’ εἰσπράξαντας τὰς τριήρεις, ἃς ἂν ἕκαστοι λάχωσι, παρεσκευασμένας παρέχειν.", "st": "14.21"}, {"sp": "N", "t": "τὴν μὲν δαπάνην καὶ τὰ σκάφη καὶ τοὺς τριηράρχους καὶ τὴν τῶν σκευῶν εἴσπραξιν οὕτως ἂν ἄρισθ’ ἡγοῦμαι καὶ πορισθῆναι καὶ παρασκευασθῆναι· πλήρωσιν δ’, ἣ καὶ σαφὴς ἔσται καὶ ῥᾳδία, μετὰ ταῦτα λέγω. φημὶ τοὺς στρατηγοὺς δεῖν διανεῖμαι τόπους δέκα τῶν νεωρίων, σκεψαμένους ὅπως ὡς ἐγγύτατ’ ἀλλήλων κατὰ τριάκοντ’ ὦσι νεώσοικοι, ἐπειδὰν δὲ τοῦτο ποιήσωσι, δύο συμμορίας καὶ τριάκοντα τριήρεις τούτων ἑκάστῳ προσνεῖμαι τῶν τόπων, εἶτ’ ἐπικληρῶσαι τὰς φυλάς·", "st": "14.22"}, {"sp": "N", "t": "τὸν δὲ ταξίαρχον ἕκαστον, ὃν ἂν ἡ φυλὴ τόπον λάχῃ, διελεῖν τρίχα καὶ τὰς ναῦς ὡσαύτως, εἶτ’ ἐπικληρῶσαι τὰς τριττῦς, ὅπως ἂν τῶν μὲν ὅλων νεωρίων ἓν ἑκάστῃ μέρος ᾖ τῶν φυλῶν, τοῦ δὲ μέρους ἑκάστου τὸ τρίτον μέρος ἡ τριττὺς ἔχῃ, εἰδῆτε δ’, ἄν τι δέῃ, πρῶτον μὲν τὴν φυλήν, ὅπου τέτακται, μετὰ ταῦτα δὲ τὴν τριττύν, εἶτα τριήραρχοι τίνες καὶ τριήρεις ποῖαι[, καὶ τριάκοντα μὲν ἡ φυλή, δέκα δ’ ἡ τριττὺς ἑκάστη τριήρεις ἔχῃ]. ἐὰν γὰρ ταῦθ’ οὕτως εἰς ὁδὸν καταστῇ, εἴ τι καὶ παραλείπομεν νῦν (πάντα γὰρ ἴσως εὑρεῖν οὐ ῥᾴδιον), αὐτὸ τὸ πρᾶγμ’ ἑαυτῷ εὑρήσει, καὶ μία σύνταξις καὶ πασῶν τῶν νεῶν καὶ μέρους ἔσται.", "st": "14.23"}, {"sp": "N", "t": "ὑπὲρ δὲ χρημάτων καὶ πόρου φανεροῦ τινὸς ἤδη παράδοξον μὲν οἶδα λόγον ὃν μέλλω λέγειν, ὅμως δ’ εἰρήσεται· πιστεύω γάρ, ἐάν τις ὀρθῶς σκοπῇ, μόνος τἀληθῆ καὶ τὰ γενησόμεν’ εἰρηκὼς φανεῖσθαι. ἐγώ φημι χρῆναι μὴ λέγειν νυνὶ περὶ χρημάτων· εἶναι γὰρ πόρον, ἂν δέῃ, μέγαν καὶ καλὸν καὶ δίκαιον, ὃν ἂν μὲν ἤδη ζητῶμεν, οὐδ’ εἰς τόθ’ ὑπάρχειν ἡγησόμεθ’ ἡμῖν· οὕτω πολὺ τοῦ πορίσαι νῦν ἀποσχήσομεν· ἐὰν δ’ ἐῶμεν, ἔσται. τίς οὖν ἔσθ’ οὗτος ὁ νῦν μὲν οὐκ ὤν, ὑπάρξων δ’ εἰς τότε; αἰνίγματι γὰρ ὅμοιον τοῦτό γε.", "st": "14.24"}, {"sp": "N", "t": "ἐγὼ φράσω. ὁρᾶτε τὴν πόλιν, ὦ ἄνδρες Ἀθηναῖοι, πᾶσαν ταύτην. ἐν ταύτῃ χρήματ’ ἔνεστιν ὀλίγου δέω πρὸς ἁπάσας τὰς ἄλλας εἰπεῖν πόλεις. ταῦτα δ’ οἱ κεκτημένοι τοιοῦτον ἔχουσι νοῦν ὥστ’, εἰ πάντες οἱ λέγοντες φοβοῖεν ὡς ἥξει βασιλεύς, ὡς πάρεστιν, ὡς οὐδ’ οἷόν τε ταῦτ’ ἄλλως ἔχειν, καὶ μετὰ τῶν λεγόντων ἴσοι τὸ πλῆθος τούτοις χρησμῳδοῖεν, οὐ μόνον οὐκ ἂν εἰσενέγκαιεν, ἀλλ’ οὐδ’ ἂν δόξειαν [οὐδ’ ἂν ὁμολογήσαιεν] κεκτῆσθαι.", "st": "14.25"}, {"sp": "N", "t": "εἰ μέντοι τὰ νῦν διὰ τῶν λόγων φοβερὰ ἔργῳ πραττόμεν’ αἴσθοιντο, οὐδεὶς οὕτως ἠλίθιός ἐστιν ὅστις οὐχὶ κἂν δοίη καὶ πρῶτος εἰσενέγκαι· τίς γὰρ αἱρήσεται μᾶλλον αὐτὸς καὶ τὰ ὄντ’ ἀπολωλέναι ἢ μέρος τῶν ὄντων ὑπὲρ αὑτοῦ καὶ τῶν λοιπῶν εἰσενεγκεῖν; χρήματα μὲν δή φημ’ εἶναι τότε, ἂν ὡς ἀληθῶς δέῃ, πρότερον δ’ οὔ. διὸ μηδὲ ζητεῖν παραινῶ· ὅσα γὰρ νῦν πορίσαιτ’ ἄν, εἰ προέλοισθε πορίζειν, πλείων ἐστὶ γέλως τοῦ μηδενός.", "st": "14.26"}, {"sp": "N", "t": "φέρε γάρ, ἑκατοστήν τις εἰσφέρειν ἐρεῖ νῦν; οὐκοῦν ἑξήκοντα τάλαντα. ἀλλὰ πεντηκοστήν τις ἐρεῖ, τὸ διπλοῦν; οὐκοῦν ἑκατὸν καὶ εἴκοσι. καὶ τί τοῦτ’ ἔστι πρὸς διακοσίας καὶ χιλίας καμήλους, ἃς βασιλεῖ τὰ χρήματ’ ἄγειν φασὶν οὗτοι; ἀλλὰ θῶ βούλεσθε δωδεκάτην ἡμᾶς εἰσοίσειν, πεντακόσια τάλαντα; ἀλλ’ οὔτ’ ἂν ἀνάσχοισθε οὔτ’, εἰ καταθεῖτε, ἄξια τοῦ πολέμου τὰ χρήματα.", "st": "14.27"}, {"sp": "N", "t": "δεῖ τοίνυν ὑμᾶς τὰ μὲν ἄλλα παρασκευάσασθαι, τὰ δὲ χρήματα νῦν μὲν ἐᾶν τοὺς κεκτημένους ἔχειν (οὐδαμοῦ γὰρ ἂν ἐν καλλίονι σῴζοιτο τῇ πόλει), ἐὰν δέ ποθ’ οὗτος ὁ καιρὸς ἔλθῃ, τόθ’ ἑκόντων εἰσφερόντων αὐτῶν λαμβάνειν. ταῦτα δὲ καὶ δυνάτ’ ἐστίν, ὦ ἄνδρες Ἀθηναῖοι, καὶ πράττειν καλὰ καὶ συμφέροντα καὶ βασιλεῖ περὶ ὑμῶν ἐπιτήδει’ ἀπαγγελθῆναι, καὶ φόβος οὐκ ὀλίγος γένοιτ’ ἂν ἐκείνῳ διὰ τούτων.", "st": "14.28"}, {"sp": "N", "t": "οἶδε μέν γε διακοσίαις τριήρεσιν, ὧν ἑκατὸν παρεσχόμεθ’ ἡμεῖς, τοὺς προγόνους αὐτοῦ χιλίας ἀπολέσαντας ναῦς, ἀκούσεται δὲ τριακοσίας αὐτοὺς ὑμᾶς νῦν παρεσκευασμένους τριήρεις· ὥστε μὴ κομιδῇ, μηδ’ εἰ πάνυ μαίνοιτο, νομίσαι ῥᾴδιόν τι τὸ τὴν ἡμετέραν πόλιν ἐχθρὰν ποιήσασθαι. ἀλλὰ μὴν εἴ γ’ ἐπὶ χρήμασιν αὐτῷ μέγ’ ἐπέρχεται φρονεῖν, καὶ ταύτην ἀσθενεστέραν ἀφορμὴν τῆς ὑμετέρας εὑρήσει.", "st": "14.29"}, {"sp": "N", "t": "ὁ μέν γε χρυσίον, ὥς φασιν, ἄγει πολύ. τοῦτο δ’ ἂν διαδῷ ζητήσει· καὶ γὰρ τὰς κρήνας καὶ τὰ φρέατ’ ἐπιλείπειν πέφυκεν, ἄν τις ἀπ’ αὐτῶν ἁθρόα πολλὰ λαμβάνῃ. ἡμῖν δὲ τὸ τῆς χώρας τίμημ’ ὑπάρχον ἀφορμὴν [ἑξακισχίλια τάλαντα] ἀκούσεται, ὑπὲρ ἧς ὡς μὲν τοὺς ἐπιόντας ἐκείνων ἀμυνόμεθα, οἱ Μαραθῶνι τῶν προγόνων αὐτοῦ μάλιστ’ ἂν εἰδεῖεν, ἕως δ’ ἂν κρατῶμεν, οὐκ ἔνι δήπου χρήμαθ’ ἡμᾶς ἐπιλείπειν.", "st": "14.30"}, {"sp": "N", "t": "καὶ μὴν οὐδ’ ὅ τινες δεδίασι, μὴ ξενικὸν πολὺ συστήσηται χρήματ’ ἔχων, ἀληθὲς εἶναί μοι δοκεῖ. ἐγὼ γὰρ ἡγοῦμαι ἐπὶ μὲν Αἴγυπτον καὶ Ὀρόνταν καί τινας τῶν ἄλλων βαρβάρων πολλοὺς ἂν ἐθελῆσαι τῶν Ἑλλήνων μισθοφορεῖν παρ’ ἐκείνῳ, οὐχ ἵν’ ἐκεῖνος ἕλῃ τινὰ τούτων, ἀλλ’ ἵν’ εὐπορίαν τιν’ ἕκαστος ἑαυτῷ κτησάμενος ἀπαλλαγῇ τῆς ὑπαρχούσης πενίας· ἐπὶ δὲ τὴν Ἑλλάδα Ἕλλην’ οὐδέν’ ἂν ἐλθεῖν ἡγοῦμαι. ποῖ γὰρ αὐτὸς τρέψεται μετὰ ταῦτα;", "st": "14.31"}, {"sp": "N", "t": "εἰς Φρυγίαν ἐλθὼν δουλεύσει; οὐ γὰρ ὑπὲρ ἄλλου τινός ἐστιν ὁ πρὸς τὸν βάρβαρον πόλεμος ἢ περὶ χώρας καὶ βίου καὶ ἐθῶν καὶ ἐλευθερίας καὶ πάντων τῶν τοιούτων. τίς οὖν οὕτως δυστυχής ἐστιν ὅστις ἑαυτόν, γονέας, τάφους, πατρίδα εἵνεκα κέρδους βραχέος προέσθαι βουλήσεται; ἐγὼ μὲν οὐδέν’ ἡγοῦμαι. οὐ μὴν οὐδ’ ἐκείνῳ συμφέρει ξένοις κρατῆσαι τῶν Ἑλλήνων· οἱ γὰρ ἡμῶν κρατήσαντες ἐκείνου γε πάλαι κρείττους ὑπάρχουσιν· βούλεται δ’ ἐκεῖνος οὐκ ἀνελὼν ἡμᾶς ἐπ’ ἄλλοις εἶναι, ἀλλὰ μάλιστα μὲν πάντων, εἰ δὲ μή, τῶν γ’ ὑπαρχόντων δούλων ἑαυτῷ νῦν ἄρχειν.", "st": "14.32"}, {"sp": "N", "t": "εἰ τοίνυν τις οἴεται Θηβαίους ἔσεσθαι μετ’ ἐκείνου, ἔστι μὲν χαλεπὸς πρὸς ὑμᾶς ὁ περὶ τούτων λόγος· διὰ γὰρ τὸ μισεῖν αὐτοὺς οὐδ’ ἂν ἀληθὲς οὐδὲν ἡδέως ἀγαθὸν περὶ αὐτῶν ἀκούσαιτε· οὐ μὴν ἀλλὰ δεῖ τοὺς περὶ πραγμάτων μεγάλων σκοποῦντας μηδένα συμφέροντα λογισμὸν παραλιπεῖν διὰ μηδεμίαν πρόφασιν. ἐγὼ τοίνυν οἶμαι τοσοῦτ’ ἀπέχειν Θηβαίους τοῦ μετ’ ἐκείνου ποτ’ ἂν ἐλθεῖν ἐπὶ τοὺς Ἕλληνας, ὥστε πολλῶν ἂν χρημάτων, εἰ ἔχοιεν δοῦναι,", "st": "14.33"}, {"sp": "N", "t": "πρίασθαι γενέσθαι τιν’ αὐτοῖς καιρὸν δι’ οὗ τὰς προτέρας ἀναλύσονται πρὸς τοὺς Ἕλληνας ἁμαρτίας. εἰ δ’ ἄρα παντάπασί τις οὕτως οἴεται φύσει δυστυχεῖς Θηβαίους εἶναι, ἐκεῖνό γε δήπουθεν ἅπαντες ἐπίστασθε, ὅτι Θηβαίων τἀκείνου φρονούντων, ἀνάγκη τοὺς τούτων ἐχθροὺς τὰ τῶν Ἑλλήνων φρονεῖν.", "st": "14.34"}, {"sp": "N", "t": "ἡγοῦμαι τοίνυν ἐγὼ ταύτην τὴν τάξιν τοῦ δικαίου καὶ τοὺς μετ’ αὐτῆς ὄντας κρείττους τῶν προδοτῶν καὶ τοῦ βαρβάρου ἔσεσθαι πρὸς ἅπαντα. ὥστ’ οὔτε φοβεῖσθαί φημι δεῖν πέρα τοῦ μετρίου, οὔθ’ ὑπαχθῆναι προτέρους ἐκφέρειν τὸν πόλεμον. καὶ μὴν οὐδὲ τῶν ἄλλων οὐδέν’ ἂν εἰκότως Ἑλλήνων φοβηθέντα τὸν πόλεμον τοῦτον ὁρῶ.", "st": "14.35"}, {"sp": "N", "t": "τίς γὰρ οὐκ οἶδεν αὐτῶν ὅτι, τέως μὲν κοινὸν ἐχθρὸν ἐκεῖνον ὑπειληφότες ὡμονόουν ἀλλήλοις, πολλῶν ἀγαθῶν ἦσαν κύριοι, ἐπειδὴ δὲ φίλον αὐτὸν νομίσαντες αὑτοῖς ὑπάρχειν περὶ τῶν πρὸς ἑαυτοὺς διηνέχθησαν διαφόρων, ὅσ’ ἂν οὐδὲ καταρώμενος εὗρέ τις αὐτοῖς, τοσαῦτα πεπόνθασι κακά; εἶθ’ ὃν ἡ τύχη καὶ τὸ δαιμόνιον φίλον μὲν ἀλυσιτελῆ, συμφέροντα δ’ ἐχθρὸν ἐμφανίζει, τοῦτον ἡμεῖς φοβώμεθα; μηδαμῶς· ἀλλὰ μηδ’ ἀδικῶμεν, αὐτῶν ἡμῶν εἵνεκα καὶ τῆς τῶν ἄλλων Ἑλλήνων ταραχῆς καὶ ἀπιστίας·", "st": "14.36"}, {"sp": "N", "t": "ἐπεὶ εἴ γ’ ὁμοθυμαδὸν ἦν μετὰ πάντων ἐπιθέσθαι μόνῳ, οὐδ’ ἀδικεῖν ἡμᾶς ἐκεῖνον ἀδίκημ’ ἂν ἔθηκα. ἐπειδὴ δὲ τοῦτ’ οὐχ οὕτως ἔχει, φυλάττεσθαί φημι δεῖν μὴ πρόφασιν δῶμεν βασιλεῖ τοῦ τὰ δίκαι’ ὑπὲρ τῶν ἄλλων Ἑλλήνων ζητεῖν· ἡσυχίαν μὲν γὰρ ἐχόντων ὑμῶν ὕποπτος ἂν εἴη τοιοῦτόν τι πράττων, πόλεμον δὲ ποιησαμένων προτέρων εἰκότως ἂν δοκοίη διὰ τὴν πρὸς ὑμᾶς ἔχθραν τοῖς ἄλλοις φίλος εἶναι βούλεσθαι.", "st": "14.37"}, {"sp": "N", "t": "μὴ οὖν ἐξελέγξηθ’ ὡς κακῶς ἔχει τὰ Ἑλληνικά, συγκαλοῦντες ὅτ’ οὐ πείσονται, καὶ πολεμοῦντες ὅτ’ οὐ δυνήσεσθε· ἀλλ’ ἔχεθ’ ἡσυχίαν θαρροῦντες καὶ παρασκευαζόμενοι, καὶ βούλεσθ’ ἀπαγγέλλεσθαι μὲν περὶ ὑμῶν πρὸς βασιλέα, μὴ μὰ Δί’ ὡς ἀποροῦσιν ἢ φοβοῦνται ἢ θορυβοῦνται πάντες [οἱ Ἕλληνες καὶ Ἀθηναῖοι], πολλοῦ γε καὶ δεῖ·", "st": "14.38"}, {"sp": "N", "t": "ἀλλ’ ὅτι, εἰ μὲν μὴ τοῖς Ἕλλησιν ὁμοίως αἰσχρὸν ἦν τὸ ψεύδεσθαι καὶ ἐπιορκεῖν ὥσπερ ἐκείνῳ καλόν, πάλαι ἂν ἐπ’ αὐτὸν ὑμεῖς ἐπορεύεσθε, νῦν δὲ τοῦτο μὲν οὐκ ἂν ποιήσαιτε ὑμῶν ἕνεκ’ αὐτῶν, εὔχεσθε δὲ πᾶσι τοῖς θεοῖς τὴν αὐτὴν λαβεῖν παράνοιαν ἐκεῖνον ἥνπερ ποτὲ τοὺς προγόνους αὐτοῦ. καὶ ταῦτ’ ἂν ἐπίῃ σκοπεῖν αὐτῷ, οὐκ ὀλιγώρως ὑμᾶς βουλευομένους εὑρήσει.", "st": "14.39"}, {"sp": "N", "t": "ἐκ μέν γε τῶν πρὸς τοὺς ἑαυτοῦ προγόνους πολέμων σύνοιδε τὴν πόλιν εὐδαίμονα καὶ μεγάλην γεγενημένην, ἐκ δὲ τῆς ἡσυχίας ἧς ἦγέ ποτε, οὐδεμιᾶς τῶν Ἑλληνίδων πόλεων τοσοῦτον ὅσον νῦν ὑπεραίρουσαν. καὶ μὴν καὶ τοὺς Ἕλληνας ὁρᾷ δεομένους ἤτοι τινὸς ἑκουσίου ἢ ἀκουσίου διαλλακτοῦ, τοῦτον δ’ αὑτὸν ἂν οἶδε φανέντ’ αὐτοῖς, εἰ πόλεμον κινοίη. ὥστε καὶ γνώριμα καὶ πίστ’ αὐτῷ τῶν ἀπαγγελλόντων ἀκούειν ἔσται.", "st": "14.40"}, {"sp": "N", "t": "ἵνα δ’, ὦ ἄνδρες Ἀθηναῖοι, μὴ μακρὰ λίαν λέγων ἐνοχλῶ, τὰ κεφάλαι’ ὧν συμβουλεύω φράσας ἄπειμι. παρασκευάζεσθαι μὲν πρὸς τοὺς ὑπάρχοντας ἐχθροὺς κελεύω, ἀμύνεσθαι δὲ καὶ βασιλέα καὶ πάντας, ἂν ἀδικεῖν ἐπιχειρῶσι, ταύτῃ τῇ αὐτῇ δυνάμει φημὶ δεῖν, ἄρχειν δὲ μηδενὸς μήτε λόγου μήτ’ ἔργου ἀδίκου, τὰ δ’ ἔργ’ ἡμῶν ὅπως ἄξια τῶν προγόνων ἔσται σκοπεῖν, μὴ τοὺς ἐπὶ τοῦ βήματος λόγους. κἂν ταῦτα ποιῆτε, καὶ ὑμῖν αὐτοῖς καὶ τοῖς τἀναντία πείθουσι συμφέροντα πράξετε· οὐ γὰρ ὀργιεῖσθ’ αὐτοῖς ὕστερον, νῦν ἁμαρτόντες.", "st": "14.41"}, {"sp": "HDR", "t": "Ὑπὲρ τῆς Ῥοδίων ἐλευθερίας", "st": "15"}, {"sp": "N", "t": "οἶμαι δεῖν, ὦ ἄνδρες Ἀθηναῖοι, περὶ τηλικούτων βουλευομένους διδόναι παρρησίαν ἑκάστῳ τῶν συμβουλευόντων. ἐγὼ δ’ οὐδεπώποθ’ ἡγησάμην χαλεπὸν τὸ διδάξαι τὰ βέλτισθ’ ὑμᾶς (ὡς γὰρ εἰπεῖν ἁπλῶς, ἅπαντες ὑπάρχειν ἐγνωκότες μοι δοκεῖτε), ἀλλὰ τὸ πεῖσαι πράττειν ταῦτα· ἐπειδὰν γάρ τι δόξῃ καὶ ψηφισθῇ, τότ’ ἴσον τοῦ πραχθῆναι ἀπέχει ὅσονπερ πρὶν δόξαι.", "st": "15.1"}, {"sp": "N", "t": "ἔστι μὲν οὖν ἓν ὧν ἐγὼ νομίζω χάριν ὑμᾶς τοῖς θεοῖς ὀφείλειν, τὸ τοὺς διὰ τὴν αὑτῶν ὕβριν ὑμῖν πολεμήσαντας οὐ πάλαι νῦν ἐν ὑμῖν μόνοις τῆς αὑτῶν σωτηρίας ἔχειν τὰς ἐλπίδας. ἄξιον δ’ ἡσθῆναι τῷ παρόντι καιρῷ· συμβήσεται γὰρ ὑμῖν, ἐὰν ἃ χρὴ βουλεύσησθ’ ὑπὲρ αὐτοῦ, τὰς παρὰ τῶν διαβαλλόντων τὴν πόλιν ἡμῶν βλασφημίας ἔργῳ μετὰ δόξης καλῆς ἀπολύσασθαι.", "st": "15.2"}, {"sp": "N", "t": "ᾐτιάσαντο μὲν γὰρ ἡμᾶς ἐπιβουλεύειν αὑτοῖς Χῖοι καὶ Βυζάντιοι καὶ Ῥόδιοι, καὶ διὰ ταῦτα συνέστησαν ἐφ’ ἡμᾶς τὸν τελευταῖον τουτονὶ πόλεμον· φανήσεται δ’ ὁ μὲν πρυτανεύσας ταῦτα καὶ πείσας Μαύσωλος, φίλος εἶναι φάσκων Ῥοδίων, τὴν ἐλευθερίαν αὐτῶν ἀφῃρημένος, οἱ δ’ ἀποδείξαντες ἑαυτοὺς συμμάχους Χῖοι καὶ Βυζάντιοι τοῖς ἀτυχήμασιν αὐτῶν οὐ βεβοηθηκότες,", "st": "15.3"}, {"sp": "N", "t": "ὑμεῖς δ’, οὓς ἐφοβοῦντο, μόνοι τῶν πάντων τῆς σωτηρίας αὐτοῖς αἴτιοι. ἐκ δὲ τοῦ ταῦθ’ ὑφ’ ἁπάντων ὀφθῆναι ποιήσετε τοὺς πολλοὺς ἐν ἁπάσαις ταῖς πόλεσι τοῦτο ποιεῖσθαι σύμβολον τῆς αὑτῶν σωτηρίας, ἐὰν ὑμῖν ὦσι φίλοι· οὗ μεῖζον οὐδὲν ἂν ὑμῖν γένοιτ’ ἀγαθόν, ἢ παρὰ πάντων ἑκόντων ἀνυπόπτου τυχεῖν εὐνοίας.", "st": "15.4"}, {"sp": "N", "t": "θαυμάζω δ’ ὅτι τοὺς αὐτοὺς ὁρῶ ὑπὲρ μὲν Αἰγυπτίων τἀναντία πράττειν βασιλεῖ τὴν πόλιν πείθοντας, ὑπὲρ δὲ τοῦ Ῥοδίων δήμου φοβουμένους τὸν ἄνδρα τοῦτον. καίτοι τοὺς μὲν Ἕλληνας ὄντας ἅπαντες ἴσασι, τοὺς δ’ ἐν τῇ ἀρχῇ τῇ ’κείνου μεμερισμένους.", "st": "15.5"}, {"sp": "N", "t": "οἶμαι δ’ ὑμῶν μνημονεύειν ἐνίους, ὅτι ἡνίκ’ ἐβουλεύεσθ’ ὑπὲρ τῶν βασιλικῶν, παρελθὼν πρῶτος ἐγὼ παρῄνεσα, οἶμαι δὲ καὶ μόνος ἢ δεύτερος εἰπεῖν, ὅτι μοι σωφρονεῖν ἂν δοκεῖτε, εἰ τὴν πρόφασιν τῆς παρασκευῆς μὴ τὴν πρὸς ἐκεῖνον ἔχθραν ποιοῖσθε, ἀλλὰ παρασκευάζοισθε μὲν πρὸς τοὺς ὑπάρχοντας ἐχθρούς, ἀμύνοισθε δὲ κἀκεῖνον, ἐὰν ὑμᾶς ἀδικεῖν ἐπιχειρῇ. καὶ οὐκ ἐγὼ μὲν εἶπον ταῦτα, ὑμῖν δ’ οὐκ ἐδόκουν ὀρθῶς λέγειν, ἀλλὰ καὶ ὑμῖν ἤρεσκε ταῦτα.", "st": "15.6"}, {"sp": "N", "t": "ἀκόλουθος τοίνυν ὁ νῦν λόγος ἐστί μοι τῷ τότε ῥηθέντι. ἐγὼ γάρ, εἰ βασιλεὺς παρ’ αὑτὸν ὄντα με σύμβουλον ποιοῖτο, ταὔτ’ ἂν αὐτῷ παραινέσαιμ’ ἅπερ ὑμῖν, ὑπὲρ μὲν τῶν αὑτοῦ πολεμεῖν, ἐάν τις ἐναντιῶται τῶν Ἑλλήνων, ὧν δὲ μηδὲν αὐτῷ προσήκει, τούτων μηδ’ ἀντιποιεῖσθαι τὴν ἀρχήν.", "st": "15.7"}, {"sp": "N", "t": "εἰ μὲν οὖν ὅλως ἐγνώκατ’, ὦ ἄνδρες Ἀθηναῖοι, ὅσων ἂν βασιλεὺς ἐγκρατὴς γένηται φθάσας ἢ παρακρουσάμενός τινας τῶν ἐν ταῖς πόλεσι, παραχωρεῖν, οὐ καλῶς ἐγνώκατε, ὡς ἐγὼ κρίνω· εἰ δ’ ὑπὲρ τῶν δικαίων καὶ πολεμεῖν, ἂν τούτου δέῃ, καὶ πάσχειν ὁτιοῦν οἴεσθε χρῆναι, πρῶτον μὲν ὑμῖν ἧττον δεήσει τούτων, ὅσῳ ἂν μᾶλλον ἐγνωκότες ἦτε ταῦτα, ἔπειθ’ ἃ προσήκει φρονεῖν δόξετε.", "st": "15.8"}, {"sp": "N", "t": "ὅτι δ’ οὐδὲν καινὸν οὔτ’ ἐγὼ λέγω νῦν κελεύων Ῥοδίους ἐλευθεροῦν, οὔθ’ ὑμεῖς, ἂν πεισθῆτέ μοι, ποιήσετε, τῶν γεγενημένων ὑμᾶς τι καὶ συνενηνοχότων ὑπομνήσω. ὑμεῖς ἐξεπέμψατε Τιμόθεόν ποτ’, ὦ ἄνδρες Ἀθηναῖοι, βοηθήσοντ’ Ἀριοβαρζάνῃ, προσγράψαντες τῷ ψηφίσματι “μὴ λύοντα τὰς σπονδὰς τὰς πρὸς τὸν βασιλέα.” ἰδὼν δ’ ἐκεῖνος τὸν μὲν Ἀριοβαρζάνην φανερῶς ἀφεστῶτα βασιλέως, Σάμον δὲ φρουρουμένην ὑπὸ Κυπροθέμιδος, ὃν κατέστησε Τιγράνης ὁ βασιλέως ὕπαρχος, τῷ μὲν ἀπέγνω μὴ βοηθεῖν, τὴν δὲ προσκαθεζόμενος καὶ βοηθήσας ἠλευθέρωσε·", "st": "15.9"}, {"sp": "N", "t": "καὶ μέχρι τῆς τήμερον ἡμέρας οὐ γέγονεν πόλεμος διὰ ταῦθ’ ὑμῖν. οὐ γὰρ ὁμοίως οὐδεὶς ὑπέρ τε τοῦ πλεονεκτεῖν πολεμήσειεν ἂν καὶ τῶν ἑαυτοῦ, ἀλλ’ ὑπὲρ μὲν ὧν ἐλαττοῦνται μέχρι τοῦ δυνατοῦ πάντες πολεμοῦσιν, ὑπὲρ δὲ τοῦ πλεονεκτεῖν οὐχ οὕτως, ἀλλ’ ἐφίενται μέν, ἐάν τις ἐᾷ, ἐὰν δὲ κωλυθῶσιν, οὐδὲν ἠδικηκέναι τοὺς ἐναντιωθέντας αὐτοῖς ἡγοῦνται.", "st": "15.10"}, {"sp": "N", "t": "ὅτι δ’ οὐδ’ ἂν ἐναντιωθῆναί μοι δοκεῖ τῇ πράξει ταύτῃ νῦν Ἀρτεμισία τῆς πόλεως οὔσης ἐπὶ τῶν πραγμάτων, μίκρ’ ἀκούσαντες σκοπεῖτε εἴτ’ ὀρθῶς λογίζομαι ταῦτ’ εἴτε μή. ἐγὼ νομίζω, πράττοντος μὲν ἐν Αἰγύπτῳ πάνθ’ ὡς ὥρμηκε βασιλέως, σφόδρ’ ἂν Ἀρτεμισίαν πειραθῆναι περιποιῆσαι Ῥόδον αὐτῷ, οὐ τῇ βασιλέως εὐνοίᾳ, ἀλλὰ τῷ βούλεσθαι πλησίον αὐτῆς διατρίβοντος ἐκείνου μεγάλην εὐεργεσίαν καταθέσθαι πρὸς αὐτόν, ἵν’ ὡς οἰκειότατ’ αὐτὴν ἀποδέχηται·", "st": "15.11"}, {"sp": "N", "t": "πράττοντος δ’ ὡς λέγεται, καὶ διημαρτηκότος οἷς ἐπεχείρησεν, ἡγεῖσθαι τὴν νῆσον ταύτην, ὅπερ ἔστιν, ἄλλο μὲν οὐδὲν ἂν εἶναι βασιλεῖ χρησίμην ἐν τῷ παρόντι, τῆς δ’ αὑτῆς ἀρχῆς ἐπιτείχισμα πρὸς τὸ μηδ’ ὁτιοῦν παρακινεῖν. ὥστε μοι δοκεῖ μᾶλλον ἂν ὑμᾶς ἔχειν μὴ φανερῶς αὐτῆς ἐνδούσης, ἢ ’κεῖνον λαβεῖν βούλεσθαι. οἶμαι μὲν οὖν οὐδὲ βοηθήσειν αὐτήν, ἂν δ’ ἄρα τοῦτο ποιῇ, φαύλως καὶ κακῶς.", "st": "15.12"}, {"sp": "N", "t": "ἐπεὶ καὶ βασιλέα γε, ὅ τι μὲν ποιήσει μὰ Δί’ οὐκ ἂν εἴποιμ’ ἔγωγ’ ὡς οἶδα, ὅτι μέντοι συμφέρει τῇ πόλει δῆλον ἤδη γενέσθαι πότερ’ ἀντιποιήσεται τῆς πόλεως τῆς Ῥοδίων ἢ οὔ, τοῦτ’ ἂν ἰσχυρισαίμην· οὐ γὰρ ὑπὲρ Ῥοδίων βουλευτέον, ὅταν ἀντιποιῆται, μόνον, ἀλλ’ ὑπὲρ ἡμῶν αὐτῶν καὶ τῶν πάντων Ἑλλήνων.", "st": "15.13"}, {"sp": "N", "t": "οὐ μὴν οὐδ’ ἂν εἰ δι’ αὑτῶν εἶχον τὴν πόλιν οἱ νῦν ὄντες ἐν αὐτῇ Ῥόδιοι, παρῄνεσ’ ἂν ὑμῖν τούτους ἑλέσθαι, οὐδ’ εἰ πάνθ’ ὑπισχνοῦνθ’ ὑμῖν ποιήσειν. ὁρῶ γὰρ αὐτοὺς τὸ μὲν πρῶτον, ὅπως καταλύσωσι τὸν δῆμον, προσλαβόντας τινὰς τῶν πολιτῶν, ἐπειδὴ δὲ τοῦτ’ ἔπραξαν, πάλιν ἐκβαλόντας τούτους· τοὺς οὖν μηδετέροις πιστῶς κεχρημένους οὐδ’ ἂν ὑμῖν βεβαίους ἡγοῦμαι γενέσθαι συμμάχους.", "st": "15.14"}, {"sp": "N", "t": "καὶ ταῦτ’ οὐδεπώποτ’ εἶπον ἄν, εἰ τῷ Ῥοδίων δήμῳ μόνον ἡγούμην συμφέρειν· οὔτε γὰρ προξενῶ τῶν ἀνδρῶν οὔτ’ ἰδίᾳ ξένος αὐτῶν οὐδείς ἐστί μοι. οὐ μὴν οὐδ’ εἰ ταῦτ’ ἀμφότερ’ ἦν, εἰ μὴ συμφέρειν ὑμῖν ἡγούμην, εἶπον ἄν, ἐπεὶ Ῥοδίοις γε, εἰ οἷόν τε τοῦτ’ εἰπεῖν τῷ συναγορεύοντι τῇ σωτηρίᾳ αὐτῶν, συγχαίρω τῶν γεγενημένων. τοῦ κομίσασθαι γὰρ τὰ ὑμέτερ’ ὑμῖν φθονήσαντες τὴν ἑαυτῶν ἐλευθερίαν ἀπολωλέκασι, καὶ παρὸν αὐτοῖς Ἕλλησι καὶ βελτίοσιν αὐτῶν [ὑμῖν] ἐξ ἴσου συμμαχεῖν, βαρβάροις καὶ δούλοις, οὓς εἰς τὰς ἀκροπόλεις παρεῖνται, δουλεύουσιν.", "st": "15.15"}, {"sp": "N", "t": "ὀλίγου δὲ δέω λέγειν, ἐὰν αὐτοῖς ὑμεῖς ἐθελήσητε βοηθῆσαι, ὡς καὶ συνενήνοχε ταῦτ’ αὐτοῖς· εὖ μὲν γὰρ πράττοντες οὐκ οἶδ’ εἴ ποτ’ ἂν εὖ φρονῆσαι ἠθέλησαν, ὄντες Ῥόδιοι, ἔργῳ δὲ πειραθέντες καὶ διδαχθέντες ὅτι πολλῶν κακῶν ἡ ἄνοι’ αἰτία τοῖς πολλοῖς γίγνεται, τάχ’ ἄν, εἰ τύχοιεν, σωφρονέστεροι πρὸς τὸν λοιπὸν τοῦ χρόνου γένοιντο. τοῦτο δ’ οὐ μικρὰν ὠφέλειαν αὐτοῖς ἡγοῦμαι. φημὶ δὴ χρῆναι πειρᾶσθαι σῴζειν τοὺς ἄνδρας καὶ μὴ μνησικακεῖν, ἐνθυμουμένους ὅτι πολλὰ καὶ ὑμεῖς ὑπὸ τῶν ἐπιβουλευσάντων ἐξηπάτησθε, ὧν οὐδενὸς αὐτοὶ δοῦναι δίκην δίκαιον ἂν εἶναι φήσαιτε.", "st": "15.16"}, {"sp": "N", "t": "ὁρᾶτε δὲ κἀκεῖν’, ὦ ἄνδρες Ἀθηναῖοι, ὅτι πολλοὺς ὑμεῖς πολέμους πεπολεμήκατε καὶ πρὸς δημοκρατίας καὶ πρὸς ὀλιγαρχίας. καὶ τοῦτο μὲν ἴστε καὶ αὐτοί· ἀλλ’ ὑπὲρ ὧν πρὸς ἑκατέρους ἔσθ’ ὑμῖν ὁ πόλεμος, τοῦτ’ ἴσως ὑμῶν οὐδεὶς λογίζεται. ὑπὲρ τίνων οὖν ἐστίν; πρὸς μὲν τοὺς δήμους ἢ περὶ τῶν ἰδίων ἐγκλημάτων, οὐ δυνηθέντων δημοσίᾳ διαλύσασθαι ταῦτα, ἢ περὶ γῆς μέρους ἢ ὅρων ἢ φιλονικίας ἢ τῆς ἡγεμονίας· πρὸς δὲ τὰς ὀλιγαρχίας ὑπὲρ μὲν τούτων οὐδενός, ὑπὲρ δὲ τῆς πολιτείας καὶ τῆς ἐλευθερίας·", "st": "15.17"}, {"sp": "N", "t": "ὥστ’ ἔγωγ’ οὐκ ἂν ὀκνήσαιμ’ εἰπεῖν μᾶλλον ἡγεῖσθαι συμφέρειν δημοκρατουμένους τοὺς Ἕλληνας ἅπαντας πολεμεῖν ὑμῖν ἢ ὀλιγαρχουμένους φίλους εἶναι. πρὸς μὲν γὰρ ἐλευθέρους ὄντας οὐ χαλεπῶς ἂν εἰρήνην ὑμᾶς ποιήσασθαι νομίζω, ὁπότε βουληθείητε, πρὸς δ’ ὀλιγαρχουμένους οὐδὲ τὴν φιλίαν ἀσφαλῆ νομίζω· οὐ γὰρ ἔσθ’ ὅπως ὀλίγοι πολλοῖς καὶ ζητοῦντες ἄρχειν τοῖς μετ’ ἰσηγορίας ζῆν ᾑρημένοις εὖνοι γένοιντ’ ἄν.", "st": "15.18"}, {"sp": "N", "t": "θαυμάζω δ’ εἰ μηδεὶς ὑμῶν ἡγεῖται Χίων ὀλιγαρχουμένων καὶ Μυτιληναίων, καὶ νυνὶ Ῥοδίων καὶ πάντων ἀνθρώπων ὀλίγου δέω λέγειν εἰς ταύτην τὴν δουλείαν ὑπαγομένων, συγκινδυνεύειν τι τὴν παρ’ ἡμῖν πολιτείαν, μηδὲ λογίζεται τοῦθ’ ὅτι οὐκ ἔστιν ὅπως, εἰ δι’ ὀλιγαρχίας ἅπαντα συστήσεται, τὸν παρ’ ὑμῖν δῆμον ἐάσουσιν. ἴσασι γὰρ οὐδένας ἄλλους πάλιν εἰς ἐλευθερίαν ⟨ἂν⟩ τὰ πράγματ’ ἐξάγοντας· ὅθεν δὴ κακὸν αὑτοῖς ἄν τι γενέσθαι προσδοκῶσι, τοῦτ’ ἀνελεῖν βουλήσονται.", "st": "15.19"}, {"sp": "N", "t": "τοὺς μὲν οὖν ἄλλους τοὺς ἀδικοῦντάς τινας αὐτῶν τῶν κακῶς πεπονθότων ἐχθροὺς ἡγεῖσθαι χρή· τοὺς δὲ τὰς πολιτείας καταλύοντας καὶ μεθιστάντας εἰς ὀλιγαρχίαν κοινοὺς ἐχθροὺς παραινῶ νομίζειν ἁπάντων τῶν ἐλευθερίας ἐπιθυμούντων.", "st": "15.20"}, {"sp": "N", "t": "ἔπειτα καὶ δίκαιον, ὦ ἄνδρες Ἀθηναῖοι, δημοκρατουμένους αὐτοὺς τοιαῦτα φρονοῦντας φαίνεσθαι περὶ τῶν ἀτυχούντων δήμων, οἷάπερ ἂν τοὺς ἄλλους ἀξιώσαιτε φρονεῖν περὶ ὑμῶν, εἴ ποθ’, ὃ μὴ γένοιτο, τοιοῦτό τι συμβαίη. καὶ γὰρ εἰ δίκαιά τις φήσει Ῥοδίους πεπονθέναι, οὐκ ἐπιτήδειος ὁ καιρὸς ἐφησθῆναι· δεῖ γὰρ τοὺς εὐτυχοῦντας περὶ τῶν ἀτυχούντων ἀεὶ φαίνεσθαι τὰ βέλτιστα βουλευομένους, ἐπειδήπερ ἄδηλον τὸ μέλλον ἅπασιν ἀνθρώποις.", "st": "15.21"}, {"sp": "N", "t": "ἀκούω δ’ ἐγὼ πολλάκις ἐνταυθὶ παρ’ ὑμῖν τινῶν λεγόντων ὡς, ὅτ’ ἠτύχησεν ὁ δῆμος ἡμῶν, συνεβουλήθησάν τινες αὐτὸν σωθῆναι· ὧν ἐγὼ μόνων Ἀργείων ἐν τῷ παρόντι μνησθήσομαι βραχύ τι. οὐ γὰρ ἂν ὑμᾶς βουλοίμην, δόξαν ἔχοντας τοῦ σῴζειν τοὺς ἀτυχοῦντας ἀεί, χείρους Ἀργείων ἐν ταύτῃ τῇ πράξει φανῆναι, οἳ χώραν ὅμορον τῇ Λακεδαιμονίων οἰκοῦντες, ὁρῶντες ἐκείνους γῆς καὶ θαλάττης ἄρχοντας, οὐκ ἀπώκνησαν οὐδ’ ἐφοβήθησαν εὐνοϊκῶς ὑμῖν ἔχοντες φανῆναι, ἀλλὰ καὶ πρέσβεις ἐλθόντας ἐκ Λακεδαίμονος, ὥς φασιν, ἐξαιτήσοντάς τινας τῶν φυγάδων τῶν ὑμετέρων ἐψηφίσαντο, ἐὰν μὴ πρὸ ἡλίου δύντος ἀπαλλάττωνται, πολεμίους κρίνειν.", "st": "15.22"}, {"sp": "N", "t": "εἶτ’ οὐκ αἰσχρόν, ὦ ἄνδρες Ἀθηναῖοι, εἰ τὸ μὲν Ἀργείων πλῆθος οὐκ ἐφοβήθη τὴν Λακεδαιμονίων ἀρχὴν ἐν ἐκείνοις τοῖς καιροῖς οὐδὲ τὴν ῥώμην, ὑμεῖς δ’ ὄντες Ἀθηναῖοι βάρβαρον ἄνθρωπον, καὶ ταῦτα γυναῖκα, φοβήσεσθε; καὶ μὴν οἱ μὲν ἔχοιεν ἂν εἰπεῖν ὅτι πολλάκις ἥττηνται [ὑπὸ] Λακεδαιμονίων, ὑμεῖς δὲ νενικήκατε μὲν πολλάκις βασιλέα, ἥττησθε δ’ οὐδ’ ἅπαξ οὔτε τῶν δούλων τῶν βασιλέως οὔτ’ αὐτοῦ ’κείνου· εἰ γάρ τί που κεκράτηκε τῆς πόλεως βασιλεύς, ἢ τοὺς πονηροτάτους τῶν Ἑλλήνων καὶ προδότας αὐτῶν χρήμασι πείσας ἢ οὐδαμῶς ἄλλως κεκράτηκεν.", "st": "15.23"}, {"sp": "N", "t": "καὶ οὐδὲ τοῦτ’ αὐτῷ συνενήνοχεν, ἀλλ’ ἅμ’ εὑρήσετ’ αὐτὸν τήν τε πόλιν διὰ Λακεδαιμονίων ἀσθενῆ ποιήσαντα καὶ περὶ τῆς αὑτοῦ βασιλείας κινδυνεύσαντα πρὸς Κλέαρχον καὶ Κῦρον. οὔτ’ οὖν ἐκ φανεροῦ κεκράτηκεν οὔτ’ ἐπιβουλεῦσαι συνενήνοχεν αὐτῷ. ὁρῶ δ’ ὑμῶν ἐνίους Φιλίππου μὲν ὡς ἄρ’ οὐδενὸς ἀξίου πολλάκις ὀλιγωροῦντας, βασιλέα δ’ ὡς ἰσχυρὸν ἐχθρὸν οἷς ἂν προέληται φοβουμένους. εἰ δὲ τὸν μὲν ὡς φαῦλον οὐκ ἀμυνούμεθα, τῷ δ’ ὡς φοβερῷ πάνθ’ ὑπείξομεν, πρὸς τίνας, ὦ ἄνδρες Ἀθηναῖοι, παραταξόμεθα;", "st": "15.24"}, {"sp": "N", "t": "εἰσὶ δέ τινες, ὦ ἄνδρες Ἀθηναῖοι, παρ’ ὑμῖν δεινότατοι τὰ δίκαια λέγειν ὑπὲρ τῶν ἄλλων πρὸς ὑμᾶς, οἷς παραινέσαιμ’ ἂν ἔγωγε τοσοῦτον μόνον, ὑπὲρ ὑμῶν πρὸς τοὺς ἄλλους ζητεῖν τὰ δίκαια λέγειν, ἵν’ αὐτοὶ τὰ προσήκοντα πρῶτοι φαίνωνται ποιοῦντες· ὡς ἔστ’ ἄτοπον περὶ τῶν δικαίων ὑμᾶς διδάσκειν αὐτὸν οὐ δίκαια ποιοῦντα· οὐ γάρ ἐστι δίκαιον ὄντα πολίτην τοὺς καθ’ ὑμῶν λόγους, ἀλλὰ μὴ τοὺς ὑπὲρ ὑμῶν ἐσκέφθαι.", "st": "15.25"}, {"sp": "N", "t": "φέρε γὰρ πρὸς θεῶν σκοπεῖτε, τί δήποτ’ ἐν Βυζαντίῳ οὐδείς ἐσθ’ ὁ διδάξων ἐκείνους μὴ καταλαμβάνειν Χαλκηδόνα, ἣ βασιλέως μέν ἐστιν, εἴχετε δ’ αὐτὴν ὑμεῖς, ἐκείνοις δ’ οὐδαμόθεν προσῆκεν· μηδὲ Σηλυμβρίαν, πόλιν ὑμετέραν ποτὲ σύμμαχον οὖσαν, ὡς αὑτοὺς συντελῆ ποιεῖν καὶ Βυζαντίων ὁρίζειν τὴν τούτων χώραν παρὰ τοὺς ὅρκους καὶ τὰς συνθήκας, ἐν αἷς αὐτονόμους τὰς πόλεις εἶναι γέγραπται;", "st": "15.26"}, {"sp": "N", "t": "οὐδὲ Μαύσωλον ζῶντα, οὐδὲ τελευτήσαντος ἐκείνου τὴν Ἀρτεμισίαν οὐδείς ἐσθ’ ὁ διδάξων μὴ καταλαμβάνειν Κῶν καὶ Ῥόδον καὶ ἄλλας ἑτέρας πόλεις Ἑλληνίδας, ὧν βασιλεὺς ὁ ’κείνων δεσπότης ἐν ταῖς συνθήκαις ἀπέστη τοῖς Ἕλλησι, καὶ περὶ ὧν πολλοὺς κινδύνους καὶ καλοὺς ἀγῶνας οἱ κατ’ ἐκείνους τοὺς χρόνους Ἕλληνες ἐποιήσαντο. εἰ δ’ ἄρα καὶ λέγει τις ἀμφοτέροις αὐτοῖς, ἀλλ’ οἵ γε πεισόμενοι τούτοις, ὡς ἔοικεν, οὐκ εἰσίν.", "st": "15.27"}, {"sp": "N", "t": "ἐγὼ δὲ δίκαιον μὲν εἶναι νομίζω κατάγειν τὸν Ῥοδίων δῆμον· οὐ μὴν ἀλλὰ καὶ εἰ μὴ δίκαιον ἦν, ὅταν εἰς ἃ ποιοῦσιν οὗτοι βλέψω, προσήκειν οἶμαι παραινεῖν κατάγειν. διὰ τί; ὅτι πάντων μέν, ὦ ἄνδρες Ἀθηναῖοι, τὰ δίκαια ποιεῖν ὡρμηκότων, αἰσχρὸν ἡμᾶς μόνους μὴ ’θέλειν, ἁπάντων δὲ τῶν ἄλλων ὅπως ἀδικεῖν δυνήσονται παρασκευαζομένων μόνους ἡμᾶς τὰ δίκαια προτείνεσθαι, μηδενὸς ἀντιλαμβανομένους, οὐ δικαιοσύνην ἀλλ’ ἀνανδρίαν ἡγοῦμαι· ὁρῶ γὰρ ἅπαντας πρὸς τὴν παροῦσαν δύναμιν τῶν δικαίων ἀξιουμένους.", "st": "15.28"}, {"sp": "N", "t": "καὶ παράδειγμα λέγειν ἔχω τούτου πᾶσιν ὑμῖν γνώριμον. εἰσὶ συνθῆκαι τοῖς Ἕλλησι [διτταὶ] πρὸς βασιλέα, ἃς ἐποιήσαθ’ ἡ πόλις ἡ ἡμετέρα, ἃς ἅπαντες ἐγκωμιάζουσι, καὶ μετὰ ταῦθ’ ὕστερον Λακεδαιμόνιοι ταύτας ὧν δὴ κατηγοροῦσι· κἀν ταύταις οὐχὶ ταὐτὰ δίκαι’ ἀμφοτέραις ὥρισται. τῶν μὲν γὰρ ἰδίων δικαίων τῶν ἐν ταῖς πολιτείαις οἱ νόμοι κοινὴν τὴν μετουσίαν ἔδοσαν καὶ ἴσην καὶ τοῖς ἀσθενέσιν καὶ τοῖς ἰσχυροῖς· τῶν δ’ Ἑλληνικῶν δικαίων οἱ κρατοῦντες ὁρισταὶ τοῖς ἥττοσι γίγνονται.", "st": "15.29"}, {"sp": "N", "t": "ἐπειδὴ τοίνυν ὑμῖν ἐγνωκέναι τὰ δίκαια [ποιεῖν] ὑπάρχει, ὅπως καὶ πρᾶξαι ταῦτ’ ἐφ’ ὑμῖν ἔσται δεῖ σκοπεῖν. ἔστι δὲ ταῦτ’, ἐὰν ὑποληφθῆτε κοινοὶ προστάται τῆς πάντων ἐλευθερίας εἶναι. εἰκότως δέ μοι δοκεῖ χαλεπώτατον ὑμῖν εἶναι πρᾶξαι τὰ δέοντα. τοῖς μὲν γὰρ ἄλλοις ἅπασιν ἀνθρώποις εἷς ἀγών ἐστιν ὁ πρὸς τοὺς προδήλους ἐχθρούς, ὧν ἂν κρατήσωσιν, οὐδὲν ἐμποδὼν αὐτοῖς κυρίοις τῶν ἀγαθῶν εἶναι·", "st": "15.30"}, {"sp": "N", "t": "ὑμῖν δ’, ὦ ἄνδρες Ἀθηναῖοι, δύο, οὗτός θ’ ὁ καὶ τοῖς ἄλλοις καὶ πρόσεσθ’ ἕτερος τούτου πρότερος καὶ μείζων· δεῖ γὰρ ὑμᾶς βουλευομένους κρατῆσαι τῶν τἀναντία τῇ πόλει παρ’ ὑμῖν πράττειν προῃρημένων. ὅταν οὖν μηδὲν ᾖ διὰ τούτους ἀκονιτεὶ τῶν δεόντων γενέσθαι, πολλῶν διαμαρτάνειν ὑμᾶς εἰκότως συμβαίνει.", "st": "15.31"}, {"sp": "N", "t": "τοῦ μέντοι πολλοὺς ἀδεῶς ταύτην τὴν τάξιν αἱρεῖσθαι τῆς πολιτείας, ἴσως μὲν αἱ παρὰ τῶν μισθοδοτούντων αὐτοὺς ὠφέλειαι μάλιστ’ αἴτιαι, οὐ μὴν ἀλλὰ καὶ ὑμᾶς ἄν τις ἔχοι δικαίως αἰτιᾶσθαι. ἐχρῆν γάρ, ὦ ἄνδρες Ἀθηναῖοι, τὴν αὐτὴν ἔχειν διάνοιαν ὑμᾶς περὶ τῆς ἐν τῇ πολιτείᾳ τάξεως ἥνπερ περὶ τῆς ἐν ταῖς στρατείαις ἔχετε. τίς οὖν ἐστιν αὕτη; ὑμεῖς τὸν λιπόντα τὴν ὑπὸ τοῦ στρατηγοῦ τάξιν ταχθεῖσαν, ἄτιμον οἴεσθε προσήκειν εἶναι καὶ μηδενὸς τῶν κοινῶν μετέχειν.", "st": "15.32"}, {"sp": "N", "t": "χρῆν τοίνυν καὶ τοὺς τὴν ὑπὸ τῶν προγόνων τάξιν ἐν τῇ πολιτείᾳ παραδεδομένην λιπόντας καὶ πολιτευομένους ὀλιγαρχικῶς ἀτίμους τοῦ συμβουλεύειν ὑμῖν αὐτοῖς ποιεῖσθαι· νῦν δὲ τῶν μὲν συμμάχων τοὺς τὸν αὐτὸν ἐχθρὸν καὶ φίλον κρινεῖν ὀμωμοκότας νομίζετ’ εὐνουστάτους, τῶν δὲ πολιτευομένων οὓς ἴστε σαφῶς τοὺς τῆς πόλεως ἐχθροὺς ᾑρημένους, τούτους πιστοτάτους ἡγεῖσθε.", "st": "15.33"}, {"sp": "N", "t": "ἀλλὰ γὰρ οὐχ ὅ τι τις κατηγορήσει τούτων ἢ τοῖς ἄλλοις ὑμῖν ἐπιπλήξει χαλεπὸν εὑρεῖν, ἀλλ’ ἀφ’ ὁποίων λόγων ἢ πράξεως ποίας ἐπανορθώσεταί τις ἃ νῦν οὐκ ὀρθῶς ἔχει, τοῦτ’ ἔργον εὑρεῖν. ἴσως μὲν οὖν οὐδὲ τοῦ παρόντος καιροῦ περὶ πάντων λέγειν· ἀλλ’ ἐὰν ἃ προῄρησθε δυνηθῆτ’ ἐπικυρῶσαι συμφερούσῃ τινὶ πράξει, καὶ τἄλλ’ ἂν ἴσως καθ’ ἓν ἀεὶ βέλτιον σχοίη.", "st": "15.34"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν οἶμαι δεῖν ὑμᾶς ἀντιλαμβάνεσθαι τῶν πραγμάτων τούτων ἐρρωμένως, καὶ πράττειν ἄξια τῆς πόλεως, ἐνθυμουμένους ὅτι χαίρετ’ ἀκούοντες, ὅταν τις ἐπαινῇ τοὺς προγόνους ὑμῶν καὶ τὰ πεπραγμέν’ ἐκείνοις διεξίῃ καὶ τὰ τρόπαια λέγῃ. νομίζετε τοίνυν ταῦτ’ ἀναθεῖναι τοὺς προγόνους ὑμῶν οὐχ ἵνα θαυμάζητ’ αὐτὰ θεωροῦντες, ἀλλ’ ἵνα καὶ μιμῆσθε τὰς τῶν ἀναθέντων ἀρετάς.", "st": "15.35"}, {"sp": "HDR", "t": "Ὑπὲρ Μεγαλοπολιτῶν", "st": "16"}, {"sp": "N", "t": "ἀμφότεροί μοι δοκοῦσιν ἁμαρτάνειν, ὦ ἄνδρες Ἀθηναῖοι, καὶ οἱ τοῖς Ἀρκάσι καὶ οἱ τοῖς Λακεδαιμονίοις συνειρηκότες· ὥσπερ γὰρ ἀφ’ ἑκατέρων ἥκοντες, οὐχ ὑμῶν ὄντες [πολῖται], πρὸς οὓς ἀμφότεροι πρεσβεύουσι, κατηγοροῦσι καὶ διαβάλλουσιν ἀλλήλους. ἦν δὲ τοῦτο μὲν τῶν ἀφιγμένων ἔργον, τὸ δὲ κοινῶς ὑπὲρ τῶν πραγμάτων λέγειν καὶ τὰ βέλτισθ’ ὑπὲρ ὑμῶν σκοπεῖν ἄνευ φιλονικίας τῶν ἐνθάδε συμβουλεύειν ἀξιούντων.", "st": "16.1"}, {"sp": "N", "t": "νῦν δ’ ἔγωγε, εἴ τις αὐτῶν ἀφέλοι τὸ γιγνώσκεσθαι καὶ τὸ τῇ φωνῇ λέγειν Ἀττικιστί, πολλοὺς ἂν οἶμαι τοὺς μὲν Ἀρκάδας, τοὺς δὲ Λάκωνας αὐτῶν εἶναι νομίσαι. ἐγὼ δ’ ὁρῶ μὲν ὡς χαλεπὸν τὰ βέλτιστα λέγειν ἐστί· συνεξηπατημένων γὰρ ὑμῶν, καὶ τῶν μὲν ταυτί, τῶν δὲ ταυτὶ βουλομένων, ἂν τὰ μεταξύ τις ἐγχειρῇ λέγειν κᾆθ’ ὑμεῖς μὴ περιμένητε μαθεῖν, χαριεῖται μὲν οὐδετέροις, διαβεβλήσεται δὲ πρὸς ἀμφοτέρους·", "st": "16.2"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ αἱρήσομαι μᾶλλον αὐτός, ἂν ἄρα τοῦτο πάθω, δοκεῖν φλυαρεῖν, ἢ παρ’ ἃ βέλτιστα νομίζω τῇ πόλει, προέσθαι τισὶν ὑμᾶς ἐξαπατῆσαι. τὰ μὲν οὖν ἄλλ’ ὕστερον, ἂν ὑμῖν βουλομένοις ᾖ, λέξω· ἀπὸ δὲ τῶν ὁμολογουμένων ὑφ’ ἁπάντων ἄρξομαι, ἃ κράτιστα νομίζω διδάσκειν.", "st": "16.3"}, {"sp": "N", "t": "οὐκοῦν οὐδ’ ἂν εἷς ἀντείποι ὡς οὐ συμφέρει τῇ πόλει καὶ Λακεδαιμονίους ἀσθενεῖς εἶναι καὶ Θηβαίους τουτουσί. ἔστι τοίνυν ἔν τινι τοιούτῳ καιρῷ τὰ πράγματα νῦν, εἴ τι δεῖ τοῖς εἰρημένοις πολλάκις παρ’ ὑμῖν λόγοις τεκμήρασθαι, ὥστε Θηβαίους μὲν Ὀρχομενοῦ καὶ Θεσπιῶν καὶ Πλαταιῶν οἰκισθεισῶν ἀσθενεῖς γενέσθαι, Λακεδαιμονίους δ’, εἰ ποιήσονται τὴν Ἀρκαδίαν ὑφ’ ἑαυτοῖς καὶ Μεγάλην πόλιν ἀναιρήσουσι, πάλιν ἰσχυροὺς γενήσεσθαι.", "st": "16.4"}, {"sp": "N", "t": "σκεπτέον τοίνυν μὴ πρότερον τούσδε γενέσθαι φοβεροὺς καὶ μεγάλους ἐάσωμεν ἢ ’κεῖνοι μικροὶ γεγενήσονται, καὶ λάθωσιν ἡμᾶς πλείονι μείζους οἱ Λακεδαιμόνιοι γενόμενοι ἢ ὅσῳ τοὺς Θηβαίους ἐλάττους συμφέρει γενέσθαι. οὐ γὰρ ἐκεῖνό γ’ ἂν εἴποιμεν, ὡς ἀνταλλάξασθαι βουλοίμεθ’ ⟨ἂν⟩ ἀντιπάλους Λακεδαιμονίους ἀντὶ Θηβαίων, οὐδὲ τοῦτ’ ἔσθ’ ὃ σπουδάζομεν, ἀλλ’ ὅπως μηδέτεροι δυνήσονται μηδὲν ἡμᾶς ἀδικεῖν· οὕτω γὰρ ἂν ἡμεῖς μετὰ πλείστης ἀδείας εἴημεν.", "st": "16.5"}, {"sp": "N", "t": "ἀλλὰ νὴ Δία ταῦτα μὲν οὕτως δεῖν ἔχειν φήσομεν, δεινὸν δ’ εἰ, πρὸς οὓς παρεταττόμεθ’ ἐν Μαντινείᾳ, τούτους συμμάχους αἱρησόμεθα, εἶτα βοηθήσομεν τούτοις ἐναντί’ ἐκείνοις μεθ’ ὧν τότ’ ἐκινδυνεύομεν. κἀμοὶ ταῦτα δοκεῖ, προσδεῖσθαι δ’ ἔτι τοῦ “τὰ δίκαια ποιεῖν ἐθελόντων τῶν ἑτέρων.”", "st": "16.6"}, {"sp": "N", "t": "εἰ μὲν τοίνυν ἐθελήσουσιν εἰρήνην ἅπαντες ἄγειν, οὐ βοηθήσομεν τοῖς Μεγαλοπολίταις· οὐδὲν γὰρ δεήσει· ὥστ’ οὐδ’ ὁτιοῦν ὑπεναντίον ἡμῖν ἔσται πρὸς τοὺς συμπαραταξαμένους, σύμμαχοι δ’ ἡμῖν οἱ μὲν ὑπάρχουσιν, ὥς φασιν, οἱ δὲ προσγενήσονται νυνί.", "st": "16.7"}, {"sp": "N", "t": "καὶ τί ἂν ἄλλο βουλοίμεθα; ἐὰν δ’ ἀδικῶσι καὶ πολεμεῖν οἴωνται δεῖν, εἰ μὲν ὑπὲρ τούτου μόνον βουλευτέον, εἰ χρὴ Μεγάλην πόλιν ἡμᾶς προέσθαι Λακεδαιμονίοις ἢ μή, δίκαιον μὲν οὔ, συγχωρῶ δ’ ἔγωγ’ ἐᾶσαι καὶ μηδὲν ἐναντιωθῆναι τοῖς γε τῶν αὐτῶν μετασχοῦσι κινδύνων· εἰ δ’ ἅπαντες ἐπίστασθ’ ὅτι, ταύτην ἂν ἕλωσιν, ἴασ’ ἐπὶ Μεσσήνην, φρασάτω τις ἐμοὶ τῶν νῦν χαλεπῶν τοῖς Μεγαλοπολίταις, τί τόθ’ ἡμῖν συμβουλεύσει ποιεῖν.", "st": "16.8"}, {"sp": "N", "t": "ἀλλ’ οὐδεὶς ἐρεῖ. καὶ μὴν πάντες ἐπίστασθ’ ὡς, καὶ παραινούντων τούτων καὶ μή, βοηθητέον, καὶ διὰ τοὺς ὅρκους οὓς ὀμωμόκαμεν Μεσσηνίοις, καὶ διὰ τὸ συμφέρον εἶναι κατοικεῖσθαι ταύτην τὴν πόλιν. σκοπεῖσθε δὴ πρὸς ὑμᾶς αὐτοὺς ποτέραν τὴν ἀρχὴν καλλίονα καὶ φιλανθρωποτέραν ποιήσεσθε τοῦ μὴ ’πιτρέπειν ἀδικεῖν Λακεδαιμονίοις, τὴν ὑπὲρ Μεγάλης πόλεως ἢ τὴν ὑπὲρ Μεσσήνης.", "st": "16.9"}, {"sp": "N", "t": "νῦν μέν γε βοηθεῖν δόξετ’ Ἀρκάσι, καὶ τὴν εἰρήνην σπουδάζειν εἶναι βεβαίαν, ὑπὲρ ἧς ἐκινδυνεύσατε καὶ παρετάξασθε· τότε δ’ εὔδηλοι πᾶσιν ἔσεσθε οὐ τοῦ δικαίου μᾶλλον εἵνεκα Μεσσήνην εἶναι βουλόμενοι ἢ τοῦ πρὸς Λακεδαιμονίους φόβου. δεῖ δὲ σκοπεῖν μὲν καὶ πράττειν ἀεὶ τὰ δίκαια, συμπαρατηρεῖν δ’ ὅπως ἅμα καὶ συμφέροντ’ ἔσται ταῦτα.", "st": "16.10"}, {"sp": "N", "t": "ἔστι τοίνυν τοιοῦτός τις λόγος παρὰ τῶν ἀντιλεγόντων, ὡς κομίσασθαι τὸν Ὠρωπὸν ἡμᾶς ἐγχειρεῖν δεῖ, εἰ δὲ τοὺς βοηθήσαντας ἂν ἡμῖν νῦν ἐπ’ αὐτὸν ἐχθροὺς κτησόμεθα, οὐχ ἕξομεν συμμάχους. ἐγὼ δὲ τὸ μὲν κομίσασθαι Ὠρωπὸν πειρᾶσθαι δεῖν φημι καὶ αὐτός· τὸ δ’ ἐχθροὺς ἡμῖν Λακεδαιμονίους ἔσεσθαι νῦν, ἐὰν ποιώμεθα συμμάχους Ἀρκάδων τοὺς βουλομένους ἡμῖν εἶναι φίλους, μόνοις οὐδ’ εἰπεῖν ἐξεῖναι νομίζω τοῖς πείσασιν ὑμᾶς, ὅτ’ ἐκινδύνευον Λακεδαιμόνιοι, βοηθεῖν.", "st": "16.11"}, {"sp": "N", "t": "οὐ γὰρ ταῦτα λέγοντες ἔπεισαν ὑμᾶς, πάντων Πελοποννησίων ἐλθόντων ὡς ὑμᾶς καὶ μεθ’ ὑμῶν ἀξιούντων ἐπὶ τοὺς Λακεδαιμονίους ἰέναι, τοὺς μὲν μὴ προσδέξασθαι (καὶ διὰ τοῦθ’, ὅπερ ἦν ὑπόλοιπον αὐτοῖς, ἐπὶ Θηβαίους ἦλθον), ὑπὲρ δὲ τῆς Λακεδαιμονίων σωτηρίας καὶ χρήματ’ εἰσφέρειν καὶ τοῖς σώμασι κινδυνεύειν· οὐδ’ ἂν ὑμεῖς ἠθελήσατε δήπου σῴζειν αὐτούς, εἰ τοῦτο προὔλεγον ὑμῖν, ὅτι σωθέντες, ἐὰν μὴ ποιεῖν ὅ τι βούλονται πάλιν αὐτοὺς ἐᾶτε καὶ ἀδικεῖν, οὐδεμίαν ὑμῖν χάριν ἕξουσι τῆς σωτηρίας.", "st": "16.12"}, {"sp": "N", "t": "καὶ μὴν εἰ σφόδρ’ ἐναντίον ἐστὶ τοῖς Λακεδαιμονίων ἐπιχειρήμασιν τὸ τοὺς Ἀρκάδας ἡμᾶς συμμάχους ποιήσασθαι, προσήκει δήπου πλείω χάριν αὐτοὺς ἔχειν ὧν ἐσώθησαν ὑφ’ ἡμῶν εἰς τοὺς ἐσχάτους ἐλθόντες κινδύνους ἢ ὧν ἀδικεῖν κωλύονται νῦν ὀργίζεσθαι. ὥστε πῶς οὐ βοηθήσουσιν ἡμῖν ἐπ’ Ὠρωπόν, ἢ κάκιστοι πάντων ἀνθρώπων δόξουσιν εἶναι; μὰ τοὺς θεοὺς ἔγωγ’ οὐχ ὁρῶ.", "st": "16.13"}, {"sp": "N", "t": "θαυμάζω τοίνυν καὶ τῶν λεγόντων τοῦτον τὸν λόγον, ὡς εἰ συμμάχους ποιησόμεθ’ Ἀρκάδας καὶ ταῦτα πράξομεν, μεταβάλλεσθαι δόξει καὶ οὐδὲν ἔχειν πιστὸν ἡ πόλις. ἐμοὶ μὲν γὰρ δοκεῖ τοὐναντίον, ὦ ἄνδρες Ἀθηναῖοι. διὰ τί; ὅτι τῶν πάντων οὐδέν’ ἂν ἀντειπεῖν οἴομαι ὡς οὐ καὶ Λακεδαιμονίους καὶ πρότερον Θηβαίους καὶ τὸ τελευταῖον Εὐβοέας ἔσωσεν ἡ πόλις, καὶ μετὰ ταῦτα συμμάχους ἐποιήσατο, ἕν τι καὶ ταὔτ’ ἀεὶ βουλομένη πράττειν.", "st": "16.14"}, {"sp": "N", "t": "ἔστι δὲ τοῦτο τί; τοὺς ἀδικουμένους σῴζειν. εἰ τοίνυν ταῦθ’ οὕτως ἔχει, οὐκέτ’ ἂν ἡμεῖς εἴημεν οἱ μεταβαλλόμενοι, ἀλλ’ οἱ μὴ ’θέλοντες τοῖς δικαίοις ἐμμένειν, καὶ φανήσεται τὰ πράγματ’ ἀεὶ διὰ τοὺς πλεονεκτεῖν βουλομένους μεταβαλλόμενα, οὐχ ἡ πόλις ἡμῶν.", "st": "16.15"}, {"sp": "N", "t": "δοκοῦσι δέ μοι Λακεδαιμόνιοι μάλα δεινῶν ἔργον ἀνθρώπων ποιεῖν. νῦν γάρ φασιν ἐκεῖνοι δεῖν Ἠλείους μὲν τῆς Τριφυλίας τινὰ κομίσασθαι, Φλειασίους δὲ τὸ Τρικάρανον, ἄλλους δέ τινας τῶν Ἀρκάδων τὴν αὑτῶν, καὶ τὸν Ὠρωπὸν ἡμᾶς, οὐχ ἵν’ ἑκάστους ἡμῶν ἴδωσιν ἔχοντας τὰ αὑτῶν, οὐδ’ ὀλίγου δεῖ·", "st": "16.16"}, {"sp": "N", "t": "ὀψὲ γὰρ ἂν φιλάνθρωποι γεγονότες εἶεν· ἀλλ’ ἵνα πᾶσι δοκῶσι συμπράττειν ὅπως ἕκαστοι κομίσωνται ταῦθ’ ἅ φασιν αὑτῶν εἶναι, ἐπειδὰν δ’ ἴωσ’ ἐπὶ Μεσσήνην αὐτοί, συστρατεύωνται πάντες αὐτοῖς οὗτοι καὶ βοηθῶσι προθύμως, ἢ δοκῶσ’ ἀδικεῖν, περὶ ὧν ἔφασαν ἕκαστοι σφῶν αὐτῶν εἶναι συμψήφους λαβόντες ἐκείνους, μὴ τὴν ὁμοίαν αὐτοῖς [χάριν] ἀποδιδόντες.", "st": "16.17"}, {"sp": "N", "t": "ἐγὼ δὲ νομίζω τὴν πόλιν, πρῶτον μὲν καὶ χωρὶς τοῦ καθυφεῖναι Λακεδαιμονίοις τινὰς Ἀρκάδων, Ὠρωπὸν ἂν κομίσασθαι, καὶ μετ’ ἐκείνων, ἂν τὰ δίκαια ποιεῖν ἐθέλωσι, καὶ μετὰ τῶν ἄλλων τῶν οὐκ οἰομένων δεῖν Θηβαίους ἐᾶν ἔχειν τἀλλότρια. εἰ δ’ ἄρα τοῦτ’ εὔδηλον ἡμῖν γένοιτο, ὅτι μὴ Λακεδαιμονίους ἐῶντες τὴν Πελοπόννησον καταστρέψασθαι οὐχ οἷοί τ’ ἐσόμεθ’ Ὠρωπὸν λαβεῖν, αἱρετώτερον, εἰ οἷόν τ’ εἰπεῖν, ἡγοῦμαι τὸν Ὠρωπὸν ἐᾶν ἢ Λακεδαιμονίοις Μεσσήνην προέσθαι καὶ Πελοπόννησον. οὐ γὰρ ἂν ἡγοῦμαι περὶ τούτου μόνον ἡμῖν εἶναι τὸν λόγον πρὸς ἐκείνους, ἀλλ’—ἐάσω τό γ’ ἐπελθὸν εἰπεῖν μοι· περὶ πολλῶν δ’ ἂν οἶμαι κίνδυνον ἡμῖν γενέσθαι.", "st": "16.18"}, {"sp": "N", "t": "ἀλλὰ μὴν ἅ γέ φασιν πεπρᾶχθαι διὰ Θηβαίους τοῖς Μεγαλοπολίταις ὑπεναντία πρὸς ἡμᾶς, ἄτοπον νῦν [μὲν] ἐν κατηγορίας μέρει ποιεῖσθαι, βουλομένων δὲ γενέσθαι φίλων αὐτῶν, ἵνα τοὐναντίον εὖ ποιῶσιν ἡμᾶς, βασκαίνειν καὶ σκοπεῖν ἐξ ὅτου τρόπου μὴ γενήσονται, καὶ μὴ γιγνώσκειν ὅτι, ὅσῳ ἂν σπουδαιοτέρους τούτους περὶ Θηβαίους γεγενημένους ἀποδείξωσι, τοσούτῳ πλείονος ὀργῆς αὐτοὶ δικαίως ἂν τυγχάνοιεν, εἰ τοιούτων συμμάχων τὴν πόλιν, ὅτ’ ἐφ’ ὑμᾶς προτέρους ἦλθον ἢ Θηβαίους, ἀπεστέρησαν.", "st": "16.19"}, {"sp": "N", "t": "ἀλλ’, οἶμαι, ταῦτα μέν ἐστι δεύτερον ἀνθρώπων βουλομένων ἑτέρων ποιῆσαι τούτους συμμάχους. ἐγὼ δ’ οἶδα, ὅσ’ ἂν ἐκ λογισμοῦ σκοπῶν τις εἰκάσαι, καὶ τοὺς πολλοὺς οἶμαι ὑμῶν ἐμοὶ ταὐτὰ φήσειν, ὅτι εἰ λήψονται Μεγάλην πόλιν Λακεδαιμόνιοι, κινδυνεύσει Μεσσήνη· εἰ δὲ καὶ ταύτην λήψονται, φήμ’ ἡμᾶς ἔσεσθαι συμμάχους Θηβαίων.", "st": "16.20"}, {"sp": "N", "t": "πολὺ δὴ κάλλιον καὶ ἄμεινον τὴν μὲν Θηβαίων συμμαχίαν αὐτοὺς παραλαβεῖν, τῇ δὲ Λακεδαιμονίων πλεονεξίᾳ μὴ ’πιτρέψαι, ἢ νῦν ὀκνοῦντας μὴ τοὺς Θηβαίων σώσωμεν συμμάχους, τούτους μὲν προέσθαι, πάλιν δὲ σῴζειν αὐτοὺς τοὺς Θηβαίους, καὶ προσέτ’ ἐν φόβῳ καθεστάναι περὶ ἡμῶν αὐτῶν.", "st": "16.21"}, {"sp": "N", "t": "οὐ γὰρ ἔγωγ’ ἀδεὲς τοῦθ’ ὑπολαμβάνω τῇ πόλει, τὸ λαβεῖν Μεγάλην πόλιν Λακεδαιμονίους καὶ πάλιν γενέσθαι μεγάλους. ὁρῶ γὰρ αὐτοὺς καὶ νῦν οὐχ ὑπὲρ τοῦ μὴ παθεῖν τι κακὸν πολεμεῖν αἱρουμένους, ἀλλ’ ὑπὲρ τοῦ κομίσασθαι τὴν πρότερον οὖσαν αὑτοῖς δύναμιν· ὧν δ’, ὅτ’ ἐκείνην εἶχον, ὠρέγοντο, ταῦθ’ ὑμεῖς μᾶλλον ἴσως εἰδότες ἢ ’γὼ φοβοῖσθ’ ἂν εἰκότως.", "st": "16.22"}, {"sp": "N", "t": "ἡδέως δ’ ἂν πυθοίμην τῶν λεγόντων καὶ τοὺς Θηβαίους μισεῖν φασκόντων καὶ τοὺς Λακεδαιμονίους, πότερ’ ἑκάτεροι μισοῦσιν, οὓς δὴ μισοῦσιν, ὑπὲρ ὑμῶν καὶ τοῦ συμφέροντος ὑμῖν, ἢ ὑπὲρ Λακεδαιμονίων μὲν Θηβαίους, ὑπὲρ δὲ Θηβαίων Λακεδαιμονίους ἑκάτεροι. εἰ μὲν γὰρ ὑπὲρ ἐκείνων, οὐδετέροις ὡς μαινομένοις πείθεσθαι προσήκει· εἰ δ’ ὑπὲρ ὑμῶν φήσουσι, τί πέρα τοῦ καιροῦ τοὺς ἑτέρους ἐπαίρουσιν;", "st": "16.23"}, {"sp": "N", "t": "ἔστι γάρ, ἔστι Θηβαίους ταπεινοὺς ποιεῖν ἄνευ τοῦ Λακεδαιμονίους ἰσχυροὺς καθιστάναι, καὶ πολύ γε ῥᾷον· ὡς δ’, ἐγὼ πειράσομαι πρὸς ὑμᾶς εἰπεῖν. ἴσμεν ἅπαντες τοῦθ’ ὅτι τὰ μὲν δίκαια πάντες, ἐὰν καὶ μὴ βούλωνται, μέχρι τού γ’ αἰσχύνονται μὴ πράττειν, τοῖς δ’ ἀδίκοις ἐναντιοῦνται φανερῶς, ἄλλως τε κἄν τινες βλάπτωνται· καὶ τοῦτο λυμαινόμενον πάνθ’ εὑρήσομεν, καὶ ταύτην ἀρχὴν οὖσαν πάντων τῶν κακῶν, τὸ μὴ ’θέλειν τὰ δίκαια πράττειν ἁπλῶς.", "st": "16.24"}, {"sp": "N", "t": "ἵνα τοίνυν μὴ τοῦτ’ ἐμποδὼν γένηται τῷ Θηβαίους γενέσθαι μικρούς, τὰς μὲν Θεσπιὰς καὶ τὸν Ὀρχομενὸν καὶ τὰς Πλαταιὰς κατοικίζεσθαι φῶμεν δεῖν καὶ συμπράττωμεν αὐτοῖς καὶ τοὺς ἄλλους ἀξιῶμεν (ταῦτα γὰρ καὶ καλὰ καὶ δίκαια, μὴ περιορᾶν πόλεις ἀρχαίας ἐξανεστώσας), τὴν δὲ Μεγάλην πόλιν καὶ τὴν Μεσσήνην μὴ προώμεθα τοῖς ἀδικοῦσι, μηδ’ ἐπὶ τῇ προφάσει τῇ Πλαταιῶν καὶ Θεσπιῶν τὰς οὔσας καὶ κατοικουμένας πόλεις ἀναιρεθείσας περιίδωμεν.", "st": "16.25"}, {"sp": "N", "t": "κἂν ᾖ ταῦτα πρόδηλα, οὐδεὶς ὅστις οὐ βουλήσεται παύσασθαι Θηβαίους ἔχοντας τὴν ἀλλοτρίαν· εἰ δὲ μή, πρῶτον μὲν ἐναντίους ἕξομεν πρὸς ἐκεῖνα τούτους εἰκότως, ὅταν ἡγῶνται τὴν ἐκείνων κατοίκισιν αὑτοῖς ὄλεθρον φέρειν, εἶτ’ ἀνήνυτα πράγμαθ’ ἕξομεν αὐτοί· τί γὰρ ὡς ἀληθῶς ἔσται πέρας, ὅταν ἀεὶ τὰς μὲν οὔσας πόλεις ἐῶμεν ἀναιρεῖν, τὰς δ’ ἀνῃρημένας ἀξιῶμεν οἰκίζειν;", "st": "16.26"}, {"sp": "N", "t": "λέγουσι τοίνυν οἱ μάλιστα δοκοῦντες δίκαια λέγειν ὡς δεῖ τὰς στήλας καθελεῖν αὐτοὺς τὰς πρὸς Θηβαίους, εἴπερ ἡμέτεροι βεβαίως ἔσονται σύμμαχοι. οἱ δέ φασι μὲν αὑτοῖς οὐ[κ εἶναι] στήλας, ἀλλὰ τὸ συμφέρον εἶναι τὸ ποιοῦν τὴν φιλίαν, τοὺς δὲ βοηθοῦντας ἑαυτοῖς, τούτους νομίζειν εἶναι συμμάχους. ἐγὼ δ’, εἰ τὰ μάλιστ’ εἰσὶ τοιοῦτοι, ὡδί πως ἔχω. φημὶ δεῖν ἅμα τούτους ἀξιοῦν καθαιρεῖν τὰς στήλας καὶ Λακεδαιμονίους ἄγειν εἰρήνην, ἐὰν δὲ μὴ ’θέλωσι ποιεῖν ὁπότεροι ταῦτα, τότ’ ἤδη μετὰ τῶν ἐθελόντων ἡμᾶς γίγνεσθαι.", "st": "16.27"}, {"sp": "N", "t": "εἴτε γὰρ εἰρήνης γιγνομένης αὐτοῖς οἱ Μεγαλοπολῖται τῆς Θηβαίων συμμαχίας ἕξονται, φανεροὶ πᾶσιν ἔσονται τὴν πλεονεξίαν τὴν Θηβαίων, οὐ τὸ δίκαιον αἱρούμενοι· εἴτε συμμάχους ἡμᾶς ἀδόλως τῶν Μεγαλοπολιτῶν ποιουμένων μὴ ’θελήσουσιν ἄγειν εἰρήνην οἱ Λακεδαιμόνιοι, δῆλοι δήπου πᾶσιν ἔσονται, οὐχ ἵνα Θεσπιαὶ κατοικισθῶσι ποιούμενοι τὴν σπουδήν, ἀλλ’ ἵνα τοῦ πολέμου περιεστηκότος Θηβαίοις τὴν Πελοπόννησον ὑφ’ αὑτοῖς ποιήσωνται.", "st": "16.28"}, {"sp": "N", "t": "θαυμάζω δ’ ἐνίων, εἰ τὸ μὲν Θηβαίων συμμάχους εἶναι τοὺς Λακεδαιμονίων ἐχθροὺς φοβοῦνται, εἰ δὲ καταστρέψονται Λακεδαιμόνιοι τούτους, μηδὲν ἡγοῦνται φοβερόν, καὶ ταῦτ’ ἔργῳ πεῖραν ἡμῖν δεδωκότος τοῦ χρόνου ὅτι Θηβαῖοι μὲν τούτοις συμμάχοις ἐπὶ Λακεδαιμονίους ἀεὶ χρῶνται, Λακεδαιμόνιοι δ’ ὅτ’ εἶχον αὐτούς, ἐφ’ ἡμᾶς ἐχρῶντο.", "st": "16.29"}, {"sp": "N", "t": "οἶμαι τοίνυν ἔγωγε κἀκεῖν’ ἐνθυμεῖσθαι δεῖν, ὅτι μὴ προσδεξαμένων μὲν ὑμῶν τοὺς Μεγαλοπολίτας, ἐὰν μὲν ἀναιρεθῶσι καὶ διοικισθῶσιν, ἰσχυροῖς Λακεδαιμονίοις ἔστιν εὐθὺς εἶναι, ἐὰν δὲ σωθῶσιν ἄρα, ὡς ἤδη τι καὶ παρ’ ἐλπίδας ἐξέβη, βέβαιοι σύμμαχοι Θηβαίων δικαίως ἔσονται· ἂν δὲ προσδέξησθε, τούτοις μὲν ὑπάρξει ἤδη σωθῆναι δι’ ὑμᾶς, τὸ δὲ συμβησόμενον, τὸν τοῦ κινδύνου λογισμὸν μετενεγκόντες, σκοπῶμεν ἐπὶ Θηβαίων καὶ Λακεδαιμονίων.", "st": "16.30"}, {"sp": "N", "t": "ἂν μὲν τοίνυν καταπολεμηθῶσιν οἱ Θηβαῖοι, ὥσπερ αὐτοὺς δεῖ, οὐκ ἔσονται μείζους τοῦ δέοντος οἱ Λακεδαιμόνιοι, τούτους ἔχοντες ἀντιπάλους τοὺς Ἀρκάδας ἐγγὺς οἰκοῦντας· ἂν δ’ ἀνενέγκωσιν ἄρ’ οἱ Θηβαῖοι καὶ σωθῶσιν, ἀλλ’ οὖν ἀσθενέστεροί γ’ ἔσονται, ἡμῖν συμμάχων γεγενημένων τῶνδε καὶ δι’ ἡμᾶς σεσωμένων. ὥστε πανταχῇ συμφέρει μήτε προέσθαι τοὺς Ἀρκάδας μήτε δι’ αὑτούς, ἂν ἄρα σωθῶσι, περιγεγονέναι δοκεῖν, μηδὲ δι’ ἄλλους τινάς, ἀλλὰ δι’ ὑμᾶς.", "st": "16.31"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν, ὦ ἄνδρες Ἀθηναῖοι, μὰ τοὺς θεοὺς οὔτε φιλῶν οὐδετέρους οὔτε μισῶν ἰδίᾳ εἴρηκα, ἀλλ’ ἃ νομίζω συμφέρειν ὑμῖν· καὶ παραινῶ μὴ προέσθαι Μεγαλοπολίτας, μηδ’ ἄλλον ἁπλῶς μηδένα τῶν ἐλαττόνων τῷ μείζονι.", "st": "16.32"}, {"sp": "HDR", "t": "Περὶ τῶν πρὸς Ἀλέξανδρον συνθηκῶν", "st": "17"}, {"sp": "N", "t": "ἄξιον ἀποδέχεσθαι, ὦ ἄνδρες Ἀθηναῖοι, σφόδρα τῶν τοῖς ὅρκοις καὶ ταῖς συνθήκαις διακελευομένων ἐμμένειν, εἴπερ αὐτὸ πεπεισμένοι ποιοῦσιν· οἶμαι γὰρ οὐδὲν οὕτω τοῖς δημοκρατουμένοις πρέπειν ὡς περὶ τὸ ἴσον καὶ τὸ δίκαιον σπουδάζειν. δεῖ τοίνυν τοὺς λίαν ἐπ’ αὐτὰ παρακαλοῦντας μὴ τῷ μὲν λόγῳ καταχρωμένους ἐνοχλεῖν, πάντα δὲ μᾶλλον πράττειν, ἀλλ’ ὑπομείναντας νυνὶ τὸν ἐξετασμὸν ἢ καὶ τὸ λοιπὸν πειθομένους ὑμᾶς ἔχειν περὶ αὐτῶν, ἢ παραχωρήσαντας ἐᾶν συμβουλεύειν τοὺς ἀληθέστερα περὶ τῶν δικαίων ἀποφαινομένους,", "st": "17.1"}, {"sp": "N", "t": "ἵν’ ἢ ἑκόντες ἀδικούμενοι ἀνέχησθε καὶ αὐτὸ τοῦτο χαρίζησθε τῷ ἀδικοῦντι, ἢ προελόμενοι περὶ πλείστου ποιήσασθαι τὸ δίκαιον ἀνεγκλήτως πρὸς ἅπαντας χρῆσθε τῷ συμφέροντι μηκέτι μέλλοντες. ἐξ αὐτῶν δὲ τῶν συνθηκῶν καὶ τῶν ὅρκων σκεψαμένους τῶν περὶ τῆς κοινῆς εἰρήνης ἔξεστιν ἰδεῖν ἤδη, τίνες εἰσὶν οἱ παραβεβηκότες. ὡς δὲ περὶ μεγάλων συντόμως διδάξω.", "st": "17.2"}, {"sp": "N", "t": "εἰ δή τις ἐρωτήσειεν, ὦ ἄνδρες Ἀθηναῖοι, ἐπὶ τίνι ἂν μάλιστ’ ἀγανακτήσαιτ’ εἴ τις ἀναγκάζοι, οἶμαι ἄν, εἰ ἦσαν κατὰ τὸν νυνὶ χρόνον οἱ Πεισιστρατίδαι καί τις ἐβιάζετο κατάγειν αὐτοὺς δευρί, ἁρπάσαντας ἂν ὑμᾶς τὰ ὅπλα πάντα κίνδυνον ὑπομεῖναι ἀντὶ τοῦ παραδέξασθαι, ἢ πεισθέντας γε δουλεύειν ἀντὶ τῶν ἀργυρωνήτων, καὶ τοσούτῳ μᾶλλον, ὅσῳ τὸν μὲν οἰκέτην οὐδεὶς ἂν ἑκὼν ἀποκτείνειε, τοὺς δὲ τυραννουμένους ἀκρίτους ἔστιν ὁρᾶν ἀπολλυμένους ἅμα καὶ ὑβριζομένους εἰς παῖδας καὶ γυναῖκας.", "st": "17.3"}, {"sp": "N", "t": "παρὰ τοὺς ὅρκους τοίνυν καὶ τὰς συνθήκας τὰς ἐν τῇ κοινῇ εἰρήνῃ γεγραμμένας Ἀλέξανδρος εἰς Μεσσήνην καταγαγὼν τοὺς Φιλιάδου παῖδας, ὄντας τυράννους, ἆρ’ ἐφρόντισε τοῦ δικαίου, ἀλλ’ οὐκ ἐχρήσατο τῷ αὑτοῦ ἤθει τῷ τυραννικῷ, βραχὺ φροντίσας ὑμῶν καὶ τῆς κοινῆς ὁμολογίας;", "st": "17.4"}, {"sp": "N", "t": "οὐ δὴ δεῖ, εἰ μέν τις ὑμᾶς ταῦτα βιάζοιτο, μάλιστ’ ἀγανακτῆσαι, εἰ δ’ ἑτέρωθί που γέγονε παρὰ τοὺς πρὸς ὑμᾶς ὅρκους, μὴ φυλάξασθαι, καὶ ἡμῖν μὲν διακελεύεσθαί τινας ἐνταυθὶ ἐμμένειν τοῖς ὅρκοις, τοῖς δ’ αὐτοὺς οὕτω περιβοήτως ἀνῃρηκόσι καταλείπειν ταύτην τὴν ἐξουσίαν.", "st": "17.5"}, {"sp": "N", "t": "ἀλλ’ οὐχ οἷόν τε ταῦθ’ οὕτως ἔχειν, ἐὰν βούλησθε τῷ δικαίῳ χρῆσθαι· καὶ γὰρ ἔτι προσγέγραπται ἐν ταῖς συνθήκαις πολέμιον εἶναι τὸν ἐκεῖν’ ἅπερ Ἀλέξανδρος ποιοῦντα ἅπασι τοῖς τῆς εἰρήνης κοινωνοῦσι, καὶ τὴν χώραν αὐτοῦ, καὶ στρατεύεσθαι ἐπ’ αὐτὸν ἅπαντας. οὐκοῦν ἐὰν ποιῶμεν τὰ συγκείμενα, πολεμίῳ χρησόμεθα τῷ καταγαγόντι.", "st": "17.6"}, {"sp": "N", "t": "ἀλλὰ γὰρ εἴποιεν ἂν οἱ τυραννίζοντες οὗτοι, ὅτι πρὶν τὰς συνθήκας γενέσθαι ἐτυράννουν Μεσσηνίων οἱ Φιλιάδου παῖδες· διὸ καὶ καταγαγεῖν τὸν Ἀλέξανδρον αὐτούς. ἀλλὰ καταγέλαστος ὁ λόγος, τοὺς μὲν ἐκ Λέσβου τυράννους, οἷον ἐξ Ἀντίσσης καὶ Ἐρέσου, ἐκβαλεῖν ὡς ἀδικήματος ὄντος τοῦ πολιτεύματος, τοὺς πρὸ τῶν ὁμολογιῶν τυραννήσαντας, ἐν δὲ Μεσσήνῃ μηδὲν οἴεσθαι διαφέρειν, τῆς αὐτῆς δυσχερείας ὑπαρχούσης.", "st": "17.7"}, {"sp": "N", "t": "ἔπειτα καὶ ἐπιτάττει ἡ συνθήκη εὐθὺς ἐν ἀρχῇ ἐλευθέρους εἶναι καὶ αὐτονόμους τοὺς Ἕλληνας. διὸ καὶ πῶς οὐχ ὑπεράτοπον, ἡγεῖσθαι μὲν τῶν συνθηκῶν τὸ αὐτονόμους εἶναι καὶ ἐλευθέρους, τὸν δ’ εἰς δουλείαν ἀγαγόντα μὴ οἴεσθαι τἀναντία ταῖς κοιναῖς ὁμολογίαις διαπεπρᾶχθαι; οὐκοῦν ἀναγκαῖόν ἐστιν ἡμῖν, ὦ ἄνδρες Ἀθηναῖοι, εἴπερ ταῖς συνθήκαις καὶ τοῖς ὅρκοις ἐμμενοῦμεν καὶ τὰ δίκαια ποιήσομεν, ἐφ’ ἃ ὑμᾶς παρακαλοῦσι, καθάπερ ἄρτι εἶπον, λαβοῦσι τὰ ὅπλα στρατεύεσθαι ἐπὶ τοὺς παραβεβηκότας μετὰ τῶν βουλομένων.", "st": "17.8"}, {"sp": "N", "t": "ἢ νομίζετε τὸν μὲν καιρόν ποτ’ ἰσχύειν καὶ ἄνευ τοῦ δικαίου τὸ συμφέρον πράττειν· νυνὶ δ’, ὅτ’ εἰς ταὐτὸν τὸ δίκαιον ἅμα καὶ ὁ καιρὸς καὶ τὸ συμφέρον συνδεδράμηκεν, ἄλλον ἄρα τινὰ χρόνον ἀναμενεῖτε τῆς ἰδίας ἐλευθερίας ἅμα καὶ τῆς τῶν ἄλλων Ἑλλήνων ἀντιλαβέσθαι;", "st": "17.9"}, {"sp": "N", "t": "ἐπ’ ἄλλο δὲ δίκαιον ἔρχομαι τῶν κατὰ τὰς συνθήκας. ἔστι γὰρ γεγραμμένον, ἐάν τινες τὰς πολιτείας τὰς παρ’ ἑκάστοις οὔσας, ὅτε τοὺς ὅρκους τοὺς περὶ τῆς εἰρήνης ὤμνυσαν, καταλύωσι, πολεμίους εἶναι πᾶσι τοῖς τῆς εἰρήνης μετέχουσιν. σκέψασθε δ’, ὦ ἄνδρες Ἀθηναῖοι, ὅτι Ἀχαιοὶ μὲν οἱ ἐν Πελοποννήσῳ ἐδημοκρατοῦντο, τούτων δ’ ἐν Πελλήνῃ νῦν καταλέλυκε τὸν δῆμον ὁ Μακεδὼν ἐκβαλὼν τῶν πολιτῶν τοὺς πλείστους, τὰ δ’ ἐκείνων τοῖς οἰκέταις δέδωκε, Χαίρωνα δὲ τὸν παλαιστὴν τύραννον ἐγκατέστησεν.", "st": "17.10"}, {"sp": "N", "t": "ἡμεῖς δὲ τῆς εἰρήνης μετέχομεν τῆς προσταττούσης πολεμίους ἡγεῖσθαι τοὺς ταῦτα πράττοντας. ἐκ δὴ τούτων πότερα πειθόμεθα τοῖς κοινοῖς προστάγμασι πολεμίοις αὐτοῖς χρώμενοι, ἢ βδελυρεύσεταί τις οὐ φάσκων, τούτων τῶν μισθοφορούντων παρὰ τοῦ Μακεδόνος, τῶν καθ’ ὑμῶν πεπλουτηκότων;", "st": "17.11"}, {"sp": "N", "t": "οὐ γὰρ δὴ λέληθέ γ’ αὐτοὺς οὐδὲν τούτων· ἀλλ’ εἰς τοῦθ’ ὕβρεως ἥκουσιν ὥστε δορυφορούμενοι τοῖς τοῦ τυράννου στρατοπέδοις ἐν μὲν τοῖς παραβεβασμένοις ὅρκοις ἐμμένειν ὑμῖν διακελεύονται, ὡς καὶ τῆς ἐπιορκίας αὐτοκράτορος ὄντος ἐκείνου, τοὺς δ’ ἰδίους ὑμᾶς νόμους ἀναγκάζουσι λύειν, τοὺς μὲν κεκριμένους ἐν τοῖς δικαστηρίοις ἀφιέντες, ἕτερα δὲ παμπληθῆ τοιαῦτα βιαζόμενοι παρανομεῖν.", "st": "17.12"}, {"sp": "N", "t": "εἰκότως· τοῖς γὰρ πεπρακόσιν ἑαυτοὺς εἰς τἀναντία τοῖς τῇ πατρίδι συμφέρουσιν οὐκ ἔνι μέλειν νόμων οὐδ’ ὅρκων· τοῖς δ’ ὀνόμασι μόνον αὐτῶν ἀποχρώμενοι παρακρούονται τοὺς παρέργως ἐνταυθὶ ἀλλ’ οὐκ ἐξεταστικῶς ἐκκλησιάζοντας, καὶ νομίζοντας τὴν παραυτίχ’ ἡσυχίαν οὐκ ἔσεσθαί ποτ’ αἰτίαν ταραχῆς ἀτόπου [μεγάλης].", "st": "17.13"}, {"sp": "N", "t": "κελεύω δ’ ἔγωγε, καθάπερ ἐν ἀρχῇ προεῖπον, πείθεσθαι τούτοις τοῖς φάσκουσι δεῖν ἐν ταῖς κοιναῖς ὁμολογίαις ἐμμένειν, εἰ μὴ ἐκεῖνο νομίζουσιν, ὅταν μὲν λέγωσιν ὡς ἐμμενετέον τοῖς ὅρκοις, οὐ λέγειν αὐτοὺς τὸ μηδὲν ἀδικεῖσθαι, οὐδένα δ’ οἴονται αἰσθήσεσθαι, τυραννίδων ἀντὶ δημοκρατιῶν καθισταμένων καὶ τῶν πολιτειῶν καταλυομένων.", "st": "17.14"}, {"sp": "N", "t": "τὸ δ’ ἔτι καταγελαστότερον· ἔστι γὰρ ἐν ταῖς συνθήκαις ἐπιμελεῖσθαι τοὺς συνεδρεύοντας καὶ τοὺς ἐπὶ τῇ κοινῇ φυλακῇ τεταγμένους ὅπως ἐν ταῖς κοινωνούσαις πόλεσι τῆς εἰρήνης μὴ γίγνωνται θάνατοι καὶ φυγαὶ παρὰ τοὺς κειμένους ταῖς πόλεσι νόμους, μηδὲ χρημάτων δημεύσεις, μηδὲ γῆς ἀναδασμοί, μηδὲ χρεῶν ἀποκοπαί, μηδὲ δούλων ἀπελευθερώσεις ἐπὶ νεωτερισμῷ. οἱ δὲ τοσούτου δέουσι τούτων τι κωλύειν ὥστε καὶ συγκατασκευάζουσιν· οὓς πῶς οὐ προσήκει ἀπολωλέναι; οἳ τηλικαύτας συμφορὰς παρασκευάζουσιν ἐν ταῖς πόλεσιν, ἃς διὰ τὸ μέγεθος αὐτοῖς τοσούτοις οὖσι μὴ περιορᾶν ἐπέταξαν.", "st": "17.15"}, {"sp": "N", "t": "ἔτι δ’ ἕτερον δείξω τὸ λελυκὸς τὰς συνθήκας. ἔστι γὰρ γεγραμμένον, ἐκ τῶν πόλεων τῶν κοινωνουσῶν τῆς εἰρήνης μὴ ἐξεῖναι φυγάδας ὁρμήσαντας ὅπλ’ ἐπιφέρειν ἐπὶ πολέμῳ ἐπὶ μηδεμίαν πόλιν τῶν μετεχουσῶν τῆς εἰρήνης· εἰ δὲ μή, ἔκσπονδον εἶναι τὴν πόλιν ἐξ ἧς ἂν ὁρμήσωσιν. οὕτω τοίνυν ῥᾳδίως ἐπήνεγκε τὰ ὅπλ’ ὁ Μακεδὼν ὥστ’ οὐδὲ κατέθετο πώποτε, ἀλλ’ ἔτι καὶ νῦν ἔχων περιέρχεται καθ’ ὅσον δύναται, καὶ τοσούτῳ νῦν μᾶλλον ἢ πρότερον, ὅσῳ ἐκ προστάγματος ἄλλους θ’ ἑτέρωσε καὶ τὸν παιδοτρίβην εἰς Σικυῶνα κατήγαγεν.", "st": "17.16"}, {"sp": "N", "t": "οὐκοῦν εἰ δεῖ πείθεσθαι ταῖς κοιναῖς ὁμολογίαις, καθάπερ οὗτοί φασιν, ἔκσπονδοι ἡμῖν εἰσιν αὗται αἱ πόλεις αἱ ταῦτα διαπεπραγμέναι. εἰ μὲν οὖν δεῖ ἐπικρύπτεσθαι τἀληθῆ, οὐδὲν δεῖ λέγειν ὅτι εἰσὶν αἱ Μακεδονικαί· εἰ δ’ οὐκ ἀνιᾶσιν οἱ καθ’ ὑμῶν τῷ Μακεδόνι ὑπηρέται προστάττοντες πράττειν τὰ ἐν ταῖς κοιναῖς ὁμολογίαις, πεισθῶμεν αὐτοῖς, ἐπειδὴ τὰ δίκαια λέγουσι, καί, καθάπερ κελεύει ὁ ὅρκος, ἐκσπόνδους αὐτοὺς ποιήσαντες βουλευσώμεθα πῶς δεῖ χρῆσθαι τοῖς δεσποτικῶς καὶ ἀσελγῶς διακειμένοις καὶ διὰ τέλους τὰ μὲν ἐπιβουλεύουσι, τὰ δ’ ἐπιτάττουσι, καὶ καταγελῶσι τῆς κοινῆς εἰρήνης.", "st": "17.17"}, {"sp": "N", "t": "διὰ τί γὰρ οὐ φήσουσιν οὗτοι δεῖν ταῦθ’ οὕτως ἔχειν; ἢ ὁμολογίαν τὴν μὲν κατὰ τῆς πόλεως οὖσαν βεβαίαν ἀξιοῦσιν εἶναι, τὴν δὲ σῴζουσαν οὐ συγχωρήσουσιν; ἆρα δίκαιον ταῦτα γίγνεσθαι; κἂν μέν τι ᾖ πρὸς τῶν ἐχθρῶν κατὰ τῆς πόλεως ἐν τοῖς ὅρκοις, τοῦτο μὲν ἰσχυρὸν ἀεὶ ποιήσουσιν· ἐὰν δέ τι ἡμέτερον ᾖ κατ’ ἐκείνων ἅμα δίκαιον καὶ συμφέρον, πρὸς τοῦτο δὲ μαχομένους οὐδέποτε παύσασθαι οἰήσονται δεῖν ἑαυτούς;", "st": "17.18"}, {"sp": "N", "t": "ἵνα δ’ εἰδῆτ’ ἔτι σαφέστερον ὅτι οὐδεὶς ὑμῖν ἐγκαλεῖ ποτε τῶν Ἑλλήνων ὡς ἄρα παρέβητέ τι τῶν κοινῇ ὁμολογηθέντων, ἀλλὰ καὶ χάριν ἕξουσιν ὅτι μόνοι ἐξηλέγξατε τοὺς ταῦτα ποιοῦντας, μικρὰ ἐπιδραμοῦμαι περὶ αὐτῶν πολλῶν ὄντων. ἔστι γὰρ δήπου ἐν ταῖς συνθήκαις τὴν θάλατταν πλεῖν τοὺς μετέχοντας τῆς εἰρήνης, καὶ μηδένα κωλύειν αὐτοὺς μηδὲ κατάγειν πλοῖον μηδενὸς τούτων· ἐὰν δέ τις παρὰ ταῦτα ποιῇ, πολέμιον εἶναι πᾶσι τοῖς τῆς εἰρήνης μετέχουσιν.", "st": "17.19"}, {"sp": "N", "t": "οὐκοῦν, ὦ ἄνδρες Ἀθηναῖοι, ἐναργέστατα ἑοράκατε τοῦθ’ ὑπὸ τῶν Μακεδόνων γεγενημένον· εἰς τοῦτο γὰρ ὑπεροψίας ἦλθον ὥστε εἰς Τένεδον ἅπαντα τὰ ἐκ τοῦ Πόντου πλοῖα κατήγαγον, καὶ σκευωρούμενοι περὶ αὐτὰ οὐ πρότερον ἀνεῖσαν, πρὶν ὑμεῖς ἐψηφίσασθε τριήρεις ἑκατὸν πληροῦν καὶ καθέλκειν εὐθὺς τότε, καὶ στρατηγὸν ἐπ’ αὐταῖς ἐτάξατε Μενεσθέα.", "st": "17.20"}, {"sp": "N", "t": "πῶς οὖν οὐκ ἄτοπον τοσαῦτα μὲν εἶναι καὶ τηλικαῦτα τὰ ἡμαρτημέν’ ἑτέροις, τοὺς δ’ ἐνταῦθα φίλους αὐτῶν μὴ ἐκείνους ἀποτρέπειν τοὺς παραβαίνοντας, ἀλλ’ ὑμῖν συμβουλεύειν ἐμμένειν τοῖς οὕτως ὠλιγωρημένοις; ὥσπερ καὶ τούτου προσγεγραμμένου, τοῖς μὲν ἐξεῖναι πλημμελεῖν, τοῖς δὲ μηδ’ ἀμύνεσθαι.", "st": "17.21"}, {"sp": "N", "t": "πῶς δ’ οὐχ ἅμα τε παρενόμουν ἐκεῖνοι καὶ ἀναίσθητοι ἦσαν, οἵ γε τηλικοῦτον παρέβησαν τῶν ὅρκων, ὃ παρ’ ἐλάχιστον ἐποίησεν αὐτοὺς ἀφαιρεθῆναι δικαίως τὴν κατὰ θάλατταν ἡγεμονίαν; καὶ νῦν ἔτι παραδεδώκασι τοῦτο τὸ δίκαιον ἀνεγκλήτως ἡμῖν, ὅταν βουληθῶμεν πράττειν· οὐ γὰρ ὅτι ἐπαύσαντ’ ἐξαμαρτάνοντες, ἧττόν τι δήπου παραβεβήκασι τὰς κοινὰς ὁμολογίας.", "st": "17.22"}, {"sp": "N", "t": "ἀλλ’ εὐτυχοῦσιν, ὅτι ἐναποχρῶνται τῇ ὑμετέρᾳ ῥᾳθυμίᾳ τῇ οὐδὲ τῶν δικαίων ἀπολαύειν προαιρουμένῃ. ὃ καὶ ὑβριστικώτατον συμβέβηκεν, εἰ οἱ μὲν ἄλλοι Ἕλληνες καὶ βάρβαροι ἅπαντες τὴν πρὸς ὑμᾶς ἔχθραν φοβοῦνται, οὗτοι δ’ οἱ νεόπλουτοι μόνοι καταφρονεῖν ὑμᾶς ὑμῶν αὐτῶν ἀναγκάζουσι, τὰ μὲν πείθοντες, τὰ δὲ βιαζόμενοι, ὥσπερ ἐν Ἀβδηρίταις ἢ Μαρωνείταις, ἀλλ’ οὐκ ἐν Ἀθηναίοις πολιτευόμενοι.", "st": "17.23"}, {"sp": "N", "t": "καὶ ἅμα μικρὰ μὲν τὰ ὑμέτερα ποιοῦσι, τὰ δὲ τῶν ἐχθρῶν ἰσχυρά, ἅμα δὲ λανθάνουσιν ἑαυτοὺς ἀνυπόστατον τὴν πόλιν ὁμολογοῦντες εἶναι, διακελευόμενοι τὸ δίκαιον οὐ δικαίως διαφυλάττειν, ὡς τῷ συμφέροντί γε προελομένην χρῆσθαι κρατεῖν ἂν τῶν πολεμίων ῥᾳδίως δυνηθεῖσαν.", "st": "17.24"}, {"sp": "N", "t": "εἰκότως δ’ αὐτὸ πεπόνθασιν· ἕως γὰρ ἂν ἐξῇ τῶν κατὰ θάλατταν καὶ μόνοις ἀναμφισβητήτως εἶναι κυρίοις, τοῖς γε κατὰ γῆν πρὸς τῇ ὑπαρχούσῃ δυνάμει ἔστι προβολὰς ἑτέρας ἰσχυροτέρας εὑρέσθαι, ἄλλως τε καὶ πεπαυμένων ὑπὸ τῆς τύχης τῶν δορυφορουμένων ὑπὸ τῶν τυραννικῶν στρατοπέδων, καὶ τῶν μὲν ἐφθαρμένων, τῶν δὲ ἐξεληλεγμένων οὐδενὸς ἀξίων ὄντων.", "st": "17.25"}, {"sp": "N", "t": "τὸ μὲν οὖν περὶ τὰ πλοῖα πρὸς τοῖς ἄλλοις τοῖς προειρημένοις ὁ Μακεδὼν τηλικοῦτον παρέβη· τὸ δὲ ὑβριστικώτατον καὶ ὑπεροπτικώτατον τῶν Μακεδόνων τὸ πρώην γεγενημένον ἐστί, τὸ τολμῆσαι εἰσπλεῦσαι εἰς τὸν Πειραιᾶ παρὰ τὰς κοινὰς ἡμῖν πρὸς αὐτοὺς ὁμολογίας. καὶ τοῦτ’, ὦ ἄνδρες Ἀθηναῖοι, οὐχ ὅτι μία τριήρης ἦν, μικρὸν ὑποληπτέον, ἀλλ’ ὅτι ἀπόπειρα ἐγένετο, εἰ περιοψόμεθα, ἵνα μετὰ πλειόνων αὐτοῖς ἐγγένηται τοῦτο πράττειν, καὶ ὅτι οὐκ ἐφρόντισαν τῶν κοινῶν δογμάτων, καθάπερ οὐδὲ τῶν προειρημένων.", "st": "17.26"}, {"sp": "N", "t": "ἐπεὶ ὅτι γε τοῦτο παράδυσις ἦν κατὰ μικρὸν καὶ ἐθισμὸς τοῦ ἀνέχεσθαι ἡμᾶς τοὺς τοιούτους εἴσπλους, κἀκεῖθεν δῆλον· τῷ γὰρ τὸν τότε ἐπὶ τῆς νεὼς εἰσπλεύσαντα, ὃν ἔδει εὐθὺς μετὰ τῆς τριήρους ὑφ’ ὑμῶν ἀπολωλέναι, αἰτεῖσθαι ναυπηγήσασθαι μικρὰ πλοῖα ἐν τοῖς ἡμετέροις λιμέσι πῶς οὐ καταφανὲς ὅτι ἀντὶ τοῦ εἰσπλεῖν τὸ εὐθὺς ἔνδον εἶναι ἐμηχανῶντο; καὶ εἰ λεπτὰ πλοῖα ὑπομενοῦμεν, ὀλίγον ὕστερον καὶ τριήρεις· καὶ εἰ τὸ πρῶτον ὀλίγας, μικρῷ ὕστερον πολλάς.", "st": "17.27"}, {"sp": "N", "t": "οὐ γὰρ δὴ ἔστι γ’ εἰπεῖν ὡς Ἀθήνησι μὲν ἀφθόνων ὄντων τῶν ναυπηγησίμων ξύλων, τῶν μόγις καὶ πόρρωθεν εἰσκομιζομένων, ἐν δὲ τῇ Μακεδονίᾳ ἐπιλελοιπότων, τῇ καὶ τοῖς ἄλλοις τοῖς βουλομένοις εὐτελέστατα καθισταμένῃ, ἀλλ’ ᾤονθ’ ἅμα τε ναυπηγήσεσθαι ἐνταῦθα καὶ πληρώσεσθαι ἐν τῷ λιμένι [τῷ προειρημένῳ], ἐν ταῖς κοιναῖς ὁμολογίαις διειρημένον μηδὲν τοιοῦτον εἰσδέχεσθαι, καὶ τοῦτ’ ἐξέσεσθαι ἐπὶ πλέον ἀεὶ ποιεῖν.", "st": "17.28"}, {"sp": "N", "t": "οὕτω πανταχόθεν καταπεφρονηκότως ἐκεῖνοι τῇ πόλει χρῶνται διὰ τοὺς ἐντεῦθεν διδασκάλους τοὺς ὑπαγορεύοντας αὐτοῖς ἃ δεῖ ποιεῖν· οὕτω δὲ κατεγνώκασι μετὰ τούτων ἀδιήγητόν τινα τῆς πόλεως ἔκλυσιν καὶ μαλακίαν, καὶ οὔτε πρόνοιαν περὶ τῶν μελλόντων εἶναι, οὔτε λογισμὸν οὐδένα παραγίγνεσθαι τίνα τρόπον χρῆται ὁ τύραννος ταῖς κοιναῖς ὁμολογίαις.", "st": "17.29"}, {"sp": "N", "t": "αἷς ἐγὼ διακελεύομαι, ὦ ἄνδρες Ἀθηναῖοι, πείθεσθαι, καθάπερ ἐδίδαξα, καὶ διαβεβαιωσαίμην ἄν, ὡς τοῦθ’ ἡλικίας ἔχων, ἅμα καὶ τῷ δικαίῳ ἡμᾶς ἀνεγκλήτως καὶ τοῖς καιροῖς ἀσφαλέστατα χρήσεσθαι τοῖς ἐπὶ τὸ συμφέρον κατεπείγουσιν. καὶ γὰρ ἔτι προσγέγραπται ⟨ἐν⟩ ταῖς συνθήκαις, “ἐὰν βουλώμεθα τῆς κοινῆς εἰρήνης μετέχειν”· τὸ δ’ “ἐὰν βουλώμεθα” ἐστὶν ἅμα καὶ τοὐναντίον, εἰ ἄρα ποτὲ δεῖ παύσασθαι αἰσχρῶς ἑτέροις ἀκολουθοῦντας, ἢ μηδ’ ἀναμνησθῆναι μηδεμιᾶς φιλοτιμίας τῶν ἐξ ἀρχαιοτάτου καὶ πλείστων καὶ μάλιστα πάντων ἀνθρώπων ἡμῖν ὑπαρχουσῶν. ἐὰν οὖν κελεύητ’, ὦ ἄνδρες Ἀθηναῖοι, γράψω, καθάπερ αἱ συνθῆκαι κελεύουσι, πολεμεῖν τοῖς παραβεβηκόσιν.", "st": "17.30"}, {"sp": "HDR", "t": "Περὶ τῆς Ἀτελείας πρὸς Λεπτίνην", "st": "20"}, {"sp": "N", "t": "ἄνδρες δικασταί, μάλιστα μὲν εἵνεκα τοῦ νομίζειν συμφέρειν τῇ πόλει λελύσθαι τὸν νόμον, εἶτα καὶ τοῦ παιδὸς εἵνεκα τοῦ Χαβρίου ὡμολόγησα τούτοις, ὡς ἂν οἷός τ’ ὦ, συνερεῖν. ἔστι δ’ οὐκ ἄδηλον, ὦ ἄνδρες Ἀθηναῖοι, τοῦθ’, ὅτι Λεπτίνης, κἄν τις ἄλλος ὑπὲρ τοῦ νόμου λέγῃ, δίκαιον μὲν οὐδὲν ἐρεῖ περὶ αὐτοῦ, φήσει δ’ ἀναξίους τινὰς ἀνθρώπους εὑρομένους ἀτέλειαν ἐκδεδυκέναι τὰς λῃτουργίας, καὶ τούτῳ πλείστῳ χρήσεται τῷ λόγῳ.", "st": "20.1"}, {"sp": "N", "t": "ἐγὼ δ’ ὅτι μὲν τινῶν κατηγοροῦντα πάντας ἀφαιρεῖσθαι τὴν δωρειὰν τῶν ἀδίκων ἐστίν, ἐάσω· καὶ γὰρ εἴρηται τρόπον τινὰ καὶ ὑφ’ ὑμῶν ἴσως γιγνώσκεται· ἀλλ’ ἐκεῖν’ ἂν ἐροίμην ἡδέως αὐτόν, τίνος εἵνεκα, εἰ τὰ μάλιστα μὴ τινὲς ἀλλὰ πάντες ἦσαν ἀνάξιοι, τῶν αὐτῶν ἠξίωσεν ὑμᾶς τε καὶ τούτους. ἐν μὲν γὰρ τῷ γράψαι “μηδέν’ εἶναι ἀτελῆ,” τοὺς ἔχοντας ἀφείλετο τὴν ἀτέλειαν, ἐν δὲ τῷ προσγράψαι “μηδὲ τὸ λοιπὸν ἐξεῖναι δοῦναι,” ὑμᾶς τὸ δοῦναι ὑμῖν ἐξεῖναι. οὐ γὰρ ἐκεῖνό γ’ ἔνεστιν εἰπεῖν, ὡς τὸν αὐτὸν τρόπον, ὅνπερ τοὺς ἔχοντας [ἀφείλετο] τὴν δωρειὰν ἀναξίους ἐνόμιζεν, οὕτω καὶ τὸν δῆμον ἀνάξιον ἡγεῖτο κύριον εἶναι τοῦ δοῦναι, ἐάν τῳ βούληται.", "st": "20.2"}, {"sp": "N", "t": "ἀλλὰ νὴ Δι’ ἐκεῖν’ ἂν ἴσως εἴποι πρὸς ταῦτα, ὅτι διὰ τὸ ῥᾳδίως ἐξαπατᾶσθαι τὸν δῆμον, διὰ τοῦθ’ οὕτως ἔθηκε τὸν νόμον. τί οὖν κωλύει πάντ’ ἀφῃρῆσθαι καὶ ὅλως τὴν πολιτείαν ὑμᾶς κατὰ τοῦτον τὸν λόγον; οὐ γὰρ ἔστ’ ἐφ’ ὅτου τοῦτ’ οὐ πεπόνθατε τῶν πάντων, ἀλλὰ καὶ ψηφίσματα πολλὰ πολλάκις ἐξαπατηθέντες κεχειροτονήκατε, καὶ συμμάχους ἤδη τινὰς ἥττους ἀντὶ κρειττόνων ἐπείσθηθ’ ἑλέσθαι, καὶ ὅλως ἐν οἶμαι πολλοῖς οἷς πράττετε καὶ τοιοῦτόν τι συμβαίνειν ἀνάγκη.", "st": "20.3"}, {"sp": "N", "t": "ἆρ’ οὖν θησόμεθα νόμον διὰ ταῦτα “μηδὲ τὸ λοιπὸν ἐξεῖναι τῇ βουλῇ μηδὲ τῷ δήμῳ μήτε προβουλεύειν μήτε χειροτονεῖν μηδέν;” ἐγὼ μὲν οὐκ οἶμαι· οὐ γάρ ἐσμεν ἀφαιρεθῆναι δίκαιοι περὶ ὧν ἂν ἐξαπατηθῶμεν, ἀλλὰ διδαχθῆναι πῶς τοῦτο μὴ πεισόμεθα, καὶ θέσθαι νόμον οὐχ ὃς ἀφαιρήσεται τὸ κυρίους ἡμᾶς εἶναι, ἀλλὰ δι’ οὗ τὸν ἐξαπατῶντα τιμωρησόμεθα.", "st": "20.4"}, {"sp": "N", "t": "εἰ τοίνυν τις ἐάσας ταῦτ’ αὐτὸ καθ’ αὕτ’ ἐξετάσειεν, πότερόν ποτε λυσιτελέστερόν ἐστι κυρίους μὲν ὑμᾶς εἶναι τῆς δωρειᾶς, ἐξαπατηθέντας δέ τι καὶ φαύλῳ τινὶ δοῦναι, ἢ διὰ τοῦ παντελῶς ἀκύρους γενέσθαι μηδ’ ἂν ἄξιόν τιν’ εἰδῆτ’ ἐξεῖναι τιμῆσαι, εὕροιτ’ ἂν μᾶλλον ἐκεῖνο λυσιτελοῦν. διὰ τί; ὅτι ἐκ μὲν τοῦ πλείονας ἢ προσήκει τιμᾶν πολλοὺς εὖ ποιεῖν προκαλεῖσθ’ ὑμᾶς, ἐκ δὲ τοῦ μηδενὶ μηδέν, μηδ’ ἂν ἄξιος ᾖ, διδόναι, πάντας ἀπείρξετε τοῦ φιλοτιμεῖσθαι.", "st": "20.5"}, {"sp": "N", "t": "πρὸς δὲ τούτῳ καὶ δι’ ἐκεῖνο, ὅτι οἱ μὲν ἀνάξιόν τινα τιμήσαντες εὐηθείας τινὰ δόξαν ἔχοιεν ἄν, οἱ δὲ τοὺς ἀγαθόν τι ποιοῦντας ἑαυτοὺς μὴ τοῖς ὁμοίοις ἀμειβόμενοι, κακίας. ὅσῳ δὴ κρεῖττον εὐήθη δοκεῖν ἢ πονηρὸν εἶναι, τοσούτῳ λῦσαι τὸν νόμον κάλλιον ἢ θέσθαι.", "st": "20.6"}, {"sp": "N", "t": "οὐ τοίνυν ἔμοιγ’ οὐδ’ ἐκεῖν’ εὔλογον, ὦ ἄνδρες Ἀθηναῖοι, σκοπουμένῳ φαίνεται, καταμεμφόμενόν τινας ἐπὶ ταῖς ὑπαρχούσαις δωρειαῖς τοὺς χρησίμους ὄντας τῶν τιμῶν ἀποστερεῖν. εἰ γὰρ ὑπαρχουσῶν τούτων φαῦλοι καὶ ἀνάξιοί τινες κατὰ τὸν τούτων λόγον εἰσίν, τί χρὴ προσδοκᾶν ἔσεσθαι τότε, ὅταν παντελῶς μηδὲ πλέον μέλλῃ μηδὲν εἶναι τοῖς χρηστοῖς οὖσιν;", "st": "20.7"}, {"sp": "N", "t": "ἔτι τοίνυν ὑμᾶς κἀκεῖν’ ἐνθυμεῖσθαι δεῖ, ὅτι ἐκ τῶν νῦν ὑπαρχόντων νόμων καὶ πάλαι κυρίων, οὓς οὐδ’ ἂν αὐτὸς οὗτος ἀντείποι μὴ οὐχὶ καλῶς ἔχειν, ἐνιαυτὸν διαλιπὼν ἕκαστος λῃτουργεῖ, ὥστε τὸν ἥμισύν ἐστ’ ἀτελὴς τοῦ χρόνου. εἶθ’ ἧς πᾶσι μέτεστι τὸ ἥμισυ καὶ τοῖς μηδ’ ὁτιοῦν ἀγαθὸν πεποιηκόσιν ὑμᾶς, ταύτης τοὺς εὖ ποιήσαντας, ὃ προστεθείκαμεν αὐτοῖς, τοῦτ’ ἀφελώμεθα; μηδαμῶς· οὔτε γὰρ ἄλλως καλὸν οὔθ’ ὑμῖν πρέπον.", "st": "20.8"}, {"sp": "N", "t": "πῶς γὰρ οὐκ αἰσχρόν, ὦ ἄνδρες Ἀθηναῖοι, κατὰ μὲν τὴν ἀγορὰν ἀψευδεῖν νόμον γεγράφθαι, ἐφ’ οἷς οὐδέν ἐστι δημοσίᾳ βλάβος εἴ τις ψεύδεται, ἐν δὲ τῷ κοινῷ μὴ χρῆσθαι τῷ νόμῳ τούτῳ τὴν πόλιν τὴν αὐτὴν ἐπιτάξασαν τοῖς ἰδιώταις, ἀλλὰ τοὺς ἀγαθόν τι πεποιηκότας ἐξαπατῆσαι, καὶ ταῦτ’ οὐ μικρὰν ζημίαν ὀφλήσειν μέλλουσαν;", "st": "20.9"}, {"sp": "N", "t": "οὐ γὰρ εἰ μὴ χρήματ’ ἀπόλλυτε μόνον σκεπτέον, ἀλλ’ εἰ καὶ δόξαν χρηστήν, περὶ ἧς μᾶλλον σπουδάζετ’ ἢ περὶ χρημάτων, καὶ οὐ μόνον ὑμεῖς, ἀλλὰ καὶ οἱ πρόγονοι. τεκμήριον δέ· χρήματα μὲν γὰρ πλεῖστά ποτε κτησάμενοι πάνθ’ ὑπὲρ φιλοτιμίας ἀνήλωσαν, ὑπὲρ δὲ δόξης οὐδένα πώποτε κίνδυνον ἐξέστησαν, ἀλλὰ καὶ τὰς ἰδίας οὐσίας προσαναλίσκοντες διετέλουν. νῦν τοίνυν οὗτος ὁ νόμος ταύτην ἀντὶ καλῆς αἰσχρὰν τῇ πόλει περιάπτει, καὶ οὔτε τῶν προγόνων οὔθ’ ὑμῶν ἀξίαν. τρία γὰρ τὰ μέγιστ’ ὀνείδη κτᾶται, φθονεροὺς ἀπίστους ἀχαρίστους εἶναι δοκεῖν.", "st": "20.10"}, {"sp": "N", "t": "ὅτι τοίνυν οὐδ’ ἐστὶν ὅλως, ὦ ἄνδρες Ἀθηναῖοι, τοῦ ἤθους τοῦ ὑμετέρου κύριον ποιῆσαι τοιοῦτον νόμον, καὶ τοῦτο πειράσομαι δεῖξαι διὰ βραχέων, ἕν τι τῶν πρότερον πεπραγμένων τῇ πόλει διεξελθών. λέγονται χρήμαθ’ οἱ τριάκοντα δανείσασθαι παρὰ Λακεδαιμονίων ἐπὶ τοὺς ἐν Πειραιεῖ. ἐπειδὴ δ’ ἡ πόλις εἰς ἓν ἦλθεν καὶ τὰ πράγματ’ ἐκεῖνα κατέστη, πρέσβεις πέμψαντες οἱ Λακεδαιμόνιοι τὰ χρήματα ταῦτ’ ἀπῄτουν.", "st": "20.11"}, {"sp": "N", "t": "λόγων δὲ γιγνομένων καὶ τῶν μὲν τοὺς δανεισαμένους ἀποδοῦναι κελευόντων, τοὺς ἐξ ἄστεως, τῶν δὲ τοῦτο πρῶτον ὑπάρξαι τῆς ὁμονοίας σημεῖον ἀξιούντων, κοινῇ διαλῦσαι τὰ χρήματα, φασὶ τὸν δῆμον ἑλέσθαι συνεισενεγκεῖν αὐτὸν καὶ μετασχεῖν τῆς δαπάνης, ὥστε μὴ λῦσαι τῶν ὡμολογημένων μηδέν. πῶς οὖν οὐ δεινόν, ὦ ἄνδρες Ἀθηναῖοι, εἰ τότε μὲν τοῖς ἠδικηκόσιν ὑμᾶς ὑπὲρ τοῦ μὴ ψεύσασθαι τὰ χρήματ’ εἰσφέρειν ἠθελήσατε, νῦν δ’ ἐξὸν ὑμῖν ἄνευ δαπάνης τὰ δίκαια ποιῆσαι τοῖς εὐεργέταις, λύσασι τὸν νόμον, ψεύδεσθαι μᾶλλον αἱρήσεσθε; ἐγὼ μὲν οὐκ ἀξιῶ.", "st": "20.12"}, {"sp": "N", "t": "τὸ μὲν τοίνυν τῆς πόλεως ἦθος, ὦ ἄνδρες Ἀθηναῖοι, καὶ ἐπ’ ἄλλων πολλῶν καὶ ἐφ’ ὧν εἶπον ἴδοι τις ἂν τοιοῦτον, ἀψευδὲς καὶ χρηστόν, οὐ τὸ λυσιτελέστατον πρὸς ἀργύριον σκοποῦν, ἀλλὰ τί καὶ καλὸν πρᾶξαι. τὸ δὲ τοῦ θέντος τὸν νόμον, τὰ μὲν ἄλλ’ ἔγωγ’ οὐκ οἶδα, οὐδὲ λέγω φλαῦρον οὐδὲν οὐδὲ σύνοιδα, ἐκ δὲ τοῦ νόμου σκοπῶν εὑρίσκω πολὺ τούτου κεχωρισμένον.", "st": "20.13"}, {"sp": "N", "t": "φημὶ τοίνυν ἐγὼ κάλλιον εἶναι τοῦτον ὑμῖν ἀκολουθῆσαι περὶ τοῦ λῦσαι τὸν νόμον ἢ ὑμᾶς τούτῳ περὶ τοῦ θέσθαι, καὶ λυσιτελέστερον εἶναι καὶ ὑμῖν καὶ τούτῳ τὴν πόλιν πεπεικέναι Λεπτίνην ὅμοιον αὐτῇ γενέσθαι δοκεῖν ἢ αὐτὴν ὑπὸ τούτου πεπεῖσθαι ὁμοίαν εἶναι τούτῳ· οὐδὲ γὰρ εἰ πάνυ χρηστός ἐσθ’, ὡς ἐμοῦ γ’ ἕνεκ’ ἔστω, βελτίων ἐστὶ τῆς πόλεως τὸ ἦθος.", "st": "20.14"}, {"sp": "N", "t": "νομίζω τοίνυν ὑμᾶς, ὦ ἄνδρες δικασταί, ἄμεινον ἂν περὶ τοῦ παρόντος βουλεύσασθαι, εἰ κἀκεῖνο μάθοιτε, ὅτι ᾧ μόνῳ μείζους εἰσὶν αἱ παρὰ τῶν δήμων δωρειαὶ τῶν παρὰ τῶν ἄλλων πολιτειῶν [διδομένων], καὶ τοῦτ’ ἀφαιρεῖται νῦν τῷ νόμῳ. τῇ μὲν γὰρ χρείᾳ τῇ τῶν εὑρισκομένων τὰς δωρειὰς οἱ τύραννοι καὶ οἱ τὰς ὀλιγαρχίας ἔχοντες μάλιστα δύνανται [τιμᾶν]· πλούσιον γὰρ ὃν ἂν βούλωνται παραχρῆμ’ ἐποίησαν· τῇ δὲ τιμῇ καὶ τῇ βεβαιότητι τὰς παρὰ τῶν δήμων δωρειὰς εὑρήσετ’ οὔσας βελτίους.", "st": "20.15"}, {"sp": "N", "t": "τό τε γὰρ μὴ μετ’ αἰσχύνης ὡς κολακεύοντα λαμβάνειν, ἀλλ’ ἐν ἰσηγορίᾳ δοκοῦντ’ ἄξιόν τινος εἶναι τιμᾶσθαι τῶν καλῶν ἐστι, τό θ’ ὑπὸ τῶν ὁμοίων ἑκόντων θαυμάζεσθαι τοῦ παρὰ τοῦ δεσπότου λαμβάνειν ὁτιοῦν κρεῖττον εἶναι δοκεῖ. παρὰ μὲν γὰρ ἐκείνοις μείζων ἐστὶν ὁ τοῦ μέλλοντος φόβος τῆς παρούσης χάριτος, παρὰ δ’ ὑμῖν ἀδεῶς ἃν λάβῃ τις ἔχειν ὑπῆρχε τὸν γοῦν ἄλλον χρόνον.", "st": "20.16"}, {"sp": "N", "t": "ὁ τοίνυν τὴν πίστιν ἀφαιρῶν τῶν δωρειῶν νόμος, οὗτος, ᾧ μόνῳ κρείττους εἰσὶν αἱ παρ’ ὑμῶν δωρειαί, τοῦτ’ ἀφαιρεῖται. καίτοι τῶν ἁπασῶν ἧς ἄν τινος πολιτείας τὸ κομίζεσθαι τοὺς εὔνους τοῖς καθεστῶσιν χάριν ἐξέλῃς, οὐ μικρὰν φυλακὴν αὐτῶν ταύτην ἀφῃρηκὼς ἔσει.", "st": "20.17"}, {"sp": "N", "t": "τάχα τοίνυν ἴσως ἐκεῖνο λέγειν ἂν ἐπιχειρήσειε Λεπτίνης, ἀπάγων ὑμᾶς ἀπὸ τούτων, ὡς αἱ λῃτουργίαι νῦν μὲν εἰς πένητας ἀνθρώπους ἔρχονται, ἐκ δὲ τοῦ νόμου τούτου λῃτουργήσουσιν οἱ πλουσιώτατοι. ἔστι δὲ τοῦθ’ οὑτωσὶ μὲν ἀκοῦσαι λόγον τιν’ ἔχον· εἰ δέ τις αὔτ’ ἀκριβῶς ἐξετάσειε, ψεῦδος ἂν φανείη. εἰσὶ γὰρ δήπου παρ’ ἡμῖν αἵ τε τῶν μετοίκων λῃτουργίαι καὶ αἱ πολιτικαί, ὧν ἑκατέρων ἐστὶ τοῖς εὑρημένοις ἡ ἀτέλεια ἣν οὗτος ἀφαιρεῖται. τῶν γὰρ εἰς τὸν πόλεμον καὶ τὴν σωτηρίαν τῆς πόλεως εἰσφορῶν καὶ τριηραρχιῶν ὀρθῶς καὶ δικαίως οὐδείς ἐστ’ ἀτελὴς ἐκ τῶν παλαιῶν νόμων, οὐδ’ οὓς οὗτος ἔγραψε, τοὺς ἀφ’ Ἁρμοδίου καὶ Ἀριστογείτονος.", "st": "20.18"}, {"sp": "N", "t": "σκεψώμεθα δὴ τίνας ἡμῖν εἰσποιεῖ χορηγοὺς εἰς ἐκείνας τὰς λῃτουργίας, καὶ πόσους, ἐὰν μὴ τούτῳ προσέχωμεν, ἀφήσει. οἱ μὲν τοίνυν πλουσιώτατοι τριηραρχοῦντες ἀεὶ τῶν χορηγιῶν ἀτελεῖς ὑπάρχουσιν, οἱ δ’ ἐλάττω τῶν ἱκανῶν κεκτημένοι, τὴν ἀναγκαίαν ἀτέλειαν ἔχοντες, ἔξω τοῦ τέλους εἰσὶ τούτου· οὐκοῦν τούτων μὲν οὐδετέρων οὐδεὶς διὰ τὸν νόμον ἡμῖν προσέσται χορηγός.", "st": "20.19"}, {"sp": "N", "t": "ἀλλὰ νὴ Δί’ εἰς τὰς τῶν μετοίκων λῃτουργίας εἰσποιεῖ πολλούς. ἀλλ’ ἐὰν δείξῃ πέντε, ἐγὼ ληρεῖν ὁμολογῶ. θήσω τοίνυν ἐγὼ μὴ τοιοῦτον εἶναι τοῦτο, ἀλλὰ καὶ τῶν μετοίκων πλείονας ἢ τοσούτους, ἐὰν ὁ νόμος τεθῇ, τοὺς λῃτουργοῦντας ἔσεσθαι, καὶ τῶν πολιτῶν μηδέν’ ἐκ τριηραρχίας ὑπάρξειν ἀτελῆ. σκεψώμεθα δὴ τί τοῦτο τῇ πόλει, ἐὰν ἅπαντες οὗτοι λῃτουργῶσιν· φανήσεται γὰρ οὐδὲ πολλοῦ δεῖ τῆς γενησομένης ἄξιον αἰσχύνης.", "st": "20.20"}, {"sp": "N", "t": "ὅρα δ’ οὑτωσί. εἰσὶ τῶν ξένων ἀτελεῖς—δέκα θήσω· καὶ μὰ τοὺς θεούς, ὅπερ εἶπον ἀρτίως, οὐκ οἶμαι πέντ’ εἶναι. καὶ μὴν τῶν γε πολιτῶν οὐκ εἰσὶ ⟨πλείους ἢ⟩ πέντ’ ἢ ἕξ. οὐκοῦν ἀμφοτέρων ἑκκαίδεκα. ποιήσωμεν αὐτοὺς εἴκοσιν, εἰ δὲ βούλεσθε, τριάκοντα. πόσοι δή ποτ’ εἰσὶν οἱ κατ’ ἐνιαυτὸν τὰς ἐγκυκλίους λῃτουργίας λῃτουργοῦντες, χορηγοὶ καὶ γυμνασίαρχοι καὶ ἑστιάτορες; ἑξήκοντ’ ἴσως ἢ μικρῷ πλείους σύμπαντες οὗτοι.", "st": "20.21"}, {"sp": "N", "t": "ἵν’ οὖν τριάκοντ’ ἄνθρωποι πλείους παρὰ πάντα τὸν χρόνον λῃτουργήσωσιν ἡμῖν, τοὺς ἅπαντας ἀπίστως πρὸς ἡμᾶς αὐτοὺς διαθῶμεν; ἀλλ’ ἴσμεν ἐκεῖνο δήπου, ὅτι λῃτουργήσουσιν μέν, ἄνπερ ἡ πόλις ᾖ, πολλοὶ καὶ οὐκ ἐπιλείψουσιν, εὖ δὲ ποιεῖν ἡμᾶς οὐδεὶς ἐθελήσει, τοὺς πρότερον ποιήσαντας ἐὰν ἠδικημένους ἴδῃ.", "st": "20.22"}, {"sp": "N", "t": "εἶεν. εἰ δὲ δὴ τὰ μάλιστ’ ἐπέλειπον οἱ χορηγεῖν οἷοί τε, πρὸς Διὸς πότερον κρεῖττον ἦν εἰς συντέλειαν ἀγαγεῖν τὰς χορηγίας ὥσπερ τὰς τριηραρχίας, ἢ τοὺς εὐεργέτας ἀφελέσθαι τὰ δοθέντα; ἐγὼ μὲν ἐκεῖν’ οἶμαι. νῦν μέν γε τὸν χρόνον, ὃν ἂν τούτων ἕκαστος λῃτουργῇ, δίδωσι τὴν ἀνάπαυσιν αὐτοῖς μόνον, μετὰ ταῦτα δ’ οὐδὲν ἔλαττον ἕκαστος αὐτῶν ἀναλώσει· τότε δ’ ἄν, μικρᾶς συντελείας ἀπὸ τῶν ὑπαρχόντων ἑκάστῳ γιγνομένης, οὐδὲν ἔπασχε δεινὸν οὐδείς, οὐδ’ εἰ πάνυ μικρὰ κεκτημένος ἦν.", "st": "20.23"}, {"sp": "N", "t": "οὕτω τοίνυν τινές, ὦ ἄνδρες Ἀθηναῖοι, σφόδρ’ ἔχουσ’ ἀλογίστως ὥστ’ ἐπιχειροῦσι λέγειν πρὸς μὲν ταῦτ’ οὐδέν, ἄλλα δὲ τοιαδί, ὡς ἄρα δεινόν, εἰ ἐν κοινῷ μὲν μηδ’ ὁτιοῦν ὑπάρχει τῇ πόλει, ἰδίᾳ δέ τινες πλουτήσουσ’ ἀτελείας ἐπειλημμένοι. ἔστι δὲ ταῦτ’ ἀμφότερ’ οὐχὶ δίκαιον λέγειν. εἰ μὲν γάρ τις ἔχει πολλὰ μηδὲν ὑμᾶς ἀδικῶν, οὐχὶ δεῖ δήπου τούτῳ βασκαίνειν· εἰ δ’ ὑφῃρημένον φήσουσιν ἤ τιν’ ἄλλον οὐχ ὃν προσήκει τρόπον, εἰσὶ νόμοι καθ’ οὓς προσήκει κολάζειν. ὅτε δὲ τοῦτο μὴ ποιοῦσιν, οὐδὲ τὸν λόγον αὐτοῖς τοῦτον λεκτέον.", "st": "20.24"}, {"sp": "N", "t": "καὶ μὴν περὶ τοῦ γε μὴ εἶναι χρήματα κοινὰ τῇ πόλει, ἐκεῖν’ ὑμᾶς δεῖ σκοπεῖν, ὅτι οὐδὲν ἔσεσθ’ εὐπορώτεροι, τὰς ἀτελείας ἐὰν ἀφέλησθε· οὐ γὰρ κοινωνεῖ ταῖς δημοσίαις προσόδοις καὶ περιουσίαις ταῦτα τἀναλώματ’ οὐδέν. χωρὶς δὲ τούτων νυνὶ τῇ πόλει, δυοῖν ἀγαθοῖν ὄντοιν, πλούτου καὶ τοῦ πρὸς ἅπαντας πιστεύεσθαι, ἐστὶ τὸ τῆς πίστεως ὑπάρχον. εἰ δέ τις οἴεται δεῖν, ὅτι χρήματ’ οὐκ ἔχομεν, μηδὲ δόξαν ἔχειν ἡμᾶς χρηστήν, οὐ καλῶς φρονεῖ. ἐγὼ μὲν γὰρ εὔχομαι τοῖς θεοῖς, μάλιστα μὲν ἡμῖν καὶ χρήματα πολλὰ γενέσθαι, εἰ δὲ μή, τό γε πιστοῖς εἶναι καὶ βεβαίοις δοκεῖν διαμεῖναι.", "st": "20.25"}, {"sp": "N", "t": "φέρε δὴ καὶ τὰς εὐπορίας, ἃς ἀναπαυομένους τινὰς εὐπορήσειν οὗτοι φήσουσιν, εἰς δέον ὑμῖν γιγνομένας δείξω. ἴστε γὰρ δήπου τοῦθ’ ὅτι τῶν τριηραρχιῶν οὐδείς ἐστ’ ἀτελὴς οὐδὲ τῶν εἰσφορῶν τῶν εἰς τὸν πόλεμον. οὔκουν ὁ πολλὰ κεκτημένος, οὗτος, ὅστις ἂν ᾖ, πόλλ’ εἰς ταῦτα συντελεῖ; πᾶσ’ ἀνάγκη. καὶ μὴν ὅτι δεῖ τὴν εὐπορίαν εἰς ταῦθ’ ὑπάρχειν πλείστην τῇ πόλει, πάντες ἂν ὁμολογήσειαν· παρὰ μὲν γὰρ τὰς ἐπὶ τῶν χορηγιῶν δαπάνας ἡμέρας μέρος μικρὸν ἡ χάρις τοῖς θεωμένοις ἡμῶν, παρὰ δὲ τὰς τῶν εἰς τὸν πόλεμον παρασκευῶν ἀφθονίας πάντα τὸν χρόνον ἡ σωτηρία πάσῃ τῇ πόλει.", "st": "20.26"}, {"sp": "N", "t": "ὥσθ’ ὅσον ἐνθάδ’ ἀφίετε, ἐκεῖ κομίζεσθε, καὶ δίδοτ’ ἐν τιμῆς μέρει ταῦθ’ ἃ καὶ μὴ λαβοῦσιν ἔστιν ἔχειν τοῖς τοῦ τριηραρχεῖν ἄξια κεκτημένοις. ἀλλὰ μὴν ὅτι τῶν τριηραρχιῶν οὐδείς ἐστ’ ἀτελής, οἶμαι μὲν ὑμᾶς εἰδέναι πάντας, ὅμως δὲ καὶ τὸν νόμον ὑμῖν αὐτὸν ἀναγνώσεται. λαβὲ τὸν περὶ τῶν τριηραρχιῶν νόμον καὶ λέγε τοῦτ’ αὐτό.", "st": "20.27"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "20.27"}, {"sp": "N", "t": "ἀτελῆ δὲ μηδένα εἶναι τριηραρχίας πλὴν τῶν ἐννέα ἀρχόντων.", "st": "20.27"}, {"sp": "N", "t": "ὁρᾶθ’ ὡς σαφῶς, ὦ ἄνδρες Ἀθηναῖοι, μηδέν’ εἶναι τριηραρχίας ἀτελῆ διείρηκεν ὁ νόμος πλὴν τῶν ἐννέ’ ἀρχόντων. οὐκοῦν οἱ μὲν ἐλάττω κεκτημένοι τοῦ τριηραρχίας ἄξι’ ἔχειν ἐν ταῖς εἰσφοραῖς συντελοῦσιν εἰς τὸν πόλεμον, οἱ δ’ ἐφικνούμενοι τοῦ τριηραρχεῖν εἰς ἀμφότερ’ ὑμῖν ὑπάρξουσι χρήσιμοι, καὶ τριηραρχεῖν καὶ εἰσφέρειν. τίν’ οὖν ῥᾳστώνην τοῖς πολλοῖς ὁ σός, ὦ Λεπτίνη, ποιεῖ νόμος, εἰ μιᾶς ἢ δυοῖν φυλαῖν ἕνα χορηγὸν καθίστησιν, ὃς ἀνθ’ ἑνὸς ἄλλου τοῦθ’ ἅπαξ ποιήσας ἀπηλλάξεται; ἐγὼ μὲν οὐχ ὁρῶ. τῆς δέ γ’ αἰσχύνης ὅλην ἀναπίμπλησι τὴν πόλιν καὶ τῆς ἀπιστίας. οὔκουν ὅτε πολλῷ μείζονα βλάψει τῶν ὠφελειῶν ὧν ἔχει, προσήκει λελύσθαι παρὰ τοῖσδ’ αὐτόν; ἔγωγ’ ἂν φαίην.", "st": "20.28"}, {"sp": "N", "t": "ἔτι δ’, ὦ ἄνδρες δικασταί, διὰ τὸ γεγράφθαι ἐν τῷ νόμῳ διαρρήδην αὐτοῦ “μηδένα μήτε τῶν πολιτῶν μήτε τῶν ἰσοτελῶν μήτε τῶν ξένων εἶναι ἀτελῆ,” μὴ διῃρῆσθαι δ’ ὅτου ἀτελῆ, χορηγίας ἤ τινος ἄλλου τέλους, ἀλλ’ ἁπλῶς “ἀτελῆ μηδένα πλὴν τῶν ἀφ’ Ἁρμοδίου καὶ Ἀριστογείτονος,” καὶ ἐν μὲν τῷ “μηδένα” πάντας περιλαμβάνειν τοὺς ἄλλους, ἐν δὲ τῷ “τῶν ξένων” μὴ διορίζειν τῶν οἰκούντων Ἀθήνησιν, ἀφαιρεῖται καὶ Λεύκωνα τὸν ἄρχοντα Βοσπόρου καὶ τοὺς παῖδας αὐτοῦ τὴν δωρειὰν ἣν ὑμεῖς ἔδοτ’ αὐτοῖς.", "st": "20.29"}, {"sp": "N", "t": "ἔστι γὰρ γένει μὲν δήπου ὁ Λεύκων ξένος, τῇ δὲ παρ’ ὑμῶν ποιήσει πολίτης· κατ’ οὐδέτερον δ’ αὐτῷ τὴν ἀτέλειαν ἔστιν ἔχειν ἐκ τούτου τοῦ νόμου. καίτοι τῶν μὲν ἄλλων εὐεργετῶν χρόνον τιν’ ἕκαστος ἡμῖν χρήσιμον αὑτὸν παρέσχεν, οὗτος δέ, ἂν σκοπῆτε, φανήσεται συνεχῶς ἡμᾶς εὖ ποιῶν, καὶ ταῦθ’ ὧν μάλισθ’ ἡμῶν ἡ πόλις δεῖται.", "st": "20.30"}, {"sp": "N", "t": "ἴστε γὰρ δήπου τοῦθ’, ὅτι πλείστῳ τῶν πάντων ἀνθρώπων ἡμεῖς ἐπεισάκτῳ σίτῳ χρώμεθα. πρὸς τοίνυν ἅπαντα τὸν ἐκ τῶν ἄλλων ἐμπορίων ἀφικνούμενον ὁ ἐκ τοῦ Πόντου σῖτος εἰσπλέων ἐστίν. εἰκότως· οὐ γὰρ μόνον διὰ τὸ τὸν τόπον τοῦτον σῖτον ἔχειν πλεῖστον τοῦτο γίγνεται, ἀλλὰ διὰ τὸ κύριον ὄντα τὸν Λεύκων’ αὐτοῦ τοῖς ἄγουσιν Ἀθήναζε ἀτέλειαν δεδωκέναι, καὶ κηρύττειν πρώτους γεμίζεσθαι τοὺς ὡς ὑμᾶς πλέοντας. ἔχων γὰρ ἐκεῖνος ἑαυτῷ καὶ τοῖς παισὶ τὴν ἀτέλειαν ἅπασι δέδωκεν ὑμῖν.", "st": "20.31"}, {"sp": "N", "t": "τοῦτο δ’ ἡλίκον ἐστὶ θεωρήσατε. ἐκεῖνος πράττεται τοὺς παρ’ αὑτοῦ σῖτον ἐξάγοντας τριακοστήν. αἱ τοίνυν παρ’ ἐκείνου δεῦρ’ ἀφικνούμεναι σίτου μυριάδες περὶ τετταράκοντ’ εἰσί· καὶ τοῦτ’ ἐκ τῆς παρὰ τοῖς σιτοφύλαξιν ἀπογραφῆς ἄν τις ἴδοι. οὐκοῦν παρὰ μὲν τὰς τριάκοντα μυριάδας μυρίους δίδωσι μεδίμνους ἡμῖν, παρὰ δὲ τὰς δέκα ὡσπερανεὶ τρισχιλίους.", "st": "20.32"}, {"sp": "N", "t": "τοσούτου τοίνυν δεῖ ταύτην ἀποστερῆσαι τὴν δωρειὰν τὴν πόλιν, ὥστε προσκατασκευάσας ἐμπόριον Θευδοσίαν, ὅ φασιν οἱ πλέοντες οὐδ’ ὁτιοῦν χεῖρον εἶναι τοῦ Βοσπόρου, κἀνταῦθ’ ἔδωκε τὴν ἀτέλειαν ἡμῖν. καὶ τὰ μὲν ἄλλα σιωπῶ, πόλλ’ ἂν ἔχων εἰπεῖν, ὅσ’ εὐεργέτηκεν ὑμᾶς οὗτος ἁνὴρ καὶ αὐτὸς καὶ οἱ πρόγονοι· ἀλλὰ πρωπέρυσιν σιτοδείας παρὰ πᾶσιν ἀνθρώποις γενομένης οὐ μόνον ὑμῖν ἱκανὸν σῖτον ἀπέστειλεν, ἀλλὰ τοσοῦτον ὥστε πεντεκαίδεκ’ ἀργυρίου τάλαντα, ἃ Καλλισθένης διῴκησε, προσπεριγενέσθαι.", "st": "20.33"}, {"sp": "N", "t": "τί οὖν οἴεσθ’, ὦ ἄνδρες Ἀθηναῖοι, τοῦτον τὸν τοιοῦτον περὶ ὑμᾶς γεγενημένον, ἐὰν ἀκούσῃ νόμῳ τὴν ἀτέλειαν ὑμᾶς ἀφῃρημένους αὐτὸν καὶ μηδ’ ἂν μεταδόξῃ ποτὲ ψηφισαμένους ἐξεῖναι δοῦναι; ἆρ’ ἀγνοεῖθ’ ὅτι ὁ αὐτὸς νόμος οὗτος ἐκεῖνόν τ’ ἀφαιρήσεται τὴν ἀτέλειαν, κύριος ἂν γένηται, καὶ ὑμῶν τοὺς παρ’ ἐκείνου σιτηγοῦντας;", "st": "20.34"}, {"sp": "N", "t": "οὐ γὰρ δήπου τοῦτό γ’ ὑπείληφεν οὐδείς, ὡς ἐκεῖνος ὑπομενεῖ ἑαυτῷ μὲν ἀκύρους εἶναι τὰς παρ’ ὑμῶν δωρειάς, ὑμῖν δὲ μένειν τὰς παρ’ ἑαυτοῦ. οὐκοῦν πρὸς πολλοῖς οἷς βλάψειν ὑμᾶς ὁ νόμος φαίνεται, καὶ προσαφαιρεῖταί τι τῶν ὑπαρχόντων ἤδη. εἶθ’ ὑμεῖς ἔτι σκοπεῖτ’ εἰ χρὴ τοῦτον ἐξαλεῖψαι, καὶ οὐ πάλαι βεβούλευσθε; ἀνάγνωθι λαβὼν αὐτοῖς τὰ ψηφίσματα τὰ περὶ τοῦΛεύκωνος.", "st": "20.35"}, {"sp": "N", "t": "ΨΗΦΙΣΜΑΤΑ.", "st": "20.35"}, {"sp": "N", "t": "ὡς μὲν εἰκότως καὶ δικαίως τετύχηκεν τῆς ἀτελείας παρ’ ὑμῶν ὁ Λεύκων, ἀκηκόατ’ ἐκ τῶν ψηφισμάτων, ὦ ἄνδρες δικασταί. τούτων δ’ ἁπάντων στήλας ἀντιγράφους ἐστήσαθ’ ὑμεῖς κἀκεῖνος, τὴν μὲν ἐν Βοσπόρῳ, τὴν δ’ ἐν Πειραιεῖ, τὴν δ’ ἐφ’ Ἱερῷ. σκοπεῖτε δὴ πρὸς ὅσης κακίας ὑπερβολὴν ὑμᾶς ὁ νόμος προάγει, ὃς ἀπιστότερον τὸν δῆμον καθίστησ’ ἑνὸς ἀνδρός.", "st": "20.36"}, {"sp": "N", "t": "μὴ γὰρ οἴεσθ’ ὑμῖν ἄλλο τι τὰς στήλας ἑστάναι ταύτας ἢ τούτων πάντων ὧν ἔχετ’ ἢ δεδώκατε συνθήκας, αἷς ὁ μὲν Λεύκων ἐμμένων φανεῖται καὶ ποιεῖν ἀεί τι προθυμούμενος ὑμᾶς εὖ, ὑμεῖς δ’ ἑστώσας ἀκύρους πεποιηκότες, ὃ πολὺ δεινότερον τοῦ καθελεῖν· αὗται γὰρ οὑτωσὶ τοῖς βουλομένοις κατὰ τῆς πόλεως βλασφημεῖν τεκμήριον ὡς ἀληθῆ λέγουσιν ἑστήξουσιν.", "st": "20.37"}, {"sp": "N", "t": "φέρ’, ἐὰν δὲ δὴ πέμψας ὡς ἡμᾶς ὁ Λεύκων ἐρωτᾷ, τί ἔχοντες ἐγκαλέσαι καὶ τί μεμφόμενοι τὴν ἀτέλειαν αὐτὸν ἀφῄρησθε, τί πρὸς θεῶν ἐροῦμεν ἢ τί γράψει ποθ’ ὁ τὸ ψήφισμ’ ὑπὲρ ἡμῶν γράφων;", "st": "20.38"}, {"sp": "N", "t": "ὅτι νὴ Δί’ ἦσάν τινες τῶν εὑρημένων ἀνάξιοι. ἐὰν οὖν εἴπῃ πρὸς ταῦτ’ ἐκεῖνος “καὶ γὰρ Ἀθηναίων τινὲς ἴσως φαῦλοι, καὶ οὐ διὰ ταῦτ’ ἐγὼ τοὺς χρηστοὺς ἀφειλόμην, ἀλλὰ τὸν δῆμον νομίζων χρηστὸν πάντας ἔχειν ἐῶ,” οὐ δικαιότερ’ ἡμῶν ἐρεῖ; ἐμοὶ γοῦν δοκεῖ. παρὰ πᾶσι γὰρ ἀνθρώποις μᾶλλόν ἐστιν ἔθος διὰ τοὺς εὐεργέτας καὶ ἄλλους τινὰς εὖ ποιεῖν τῶν μὴ χρηστῶν ἢ διὰ τοὺς φαύλους τοὺς ὁμολογουμένως ἀξίους χάριτος τὰ δοθέντ’ ἀφαιρεῖσθαι.", "st": "20.39"}, {"sp": "N", "t": "καὶ μὴν οὐδ’ ὅπως οὐκ ἀντιδώσει τῷ Λεύκωνί τις, ἂν βούληται, δύναμαι σκοπούμενος εὑρεῖν. χρήματα μὲν γάρ ἐστιν ἀεὶ παρ’ ὑμῖν αὐτοῦ, κατὰ δὲ τὸν νόμον τοῦτον, ἐάν τις ἐπ’ αὔτ’ ἔλθῃ, ἢ στερήσεται τούτων ἢ λῃτουργεῖν ἀναγκασθήσεται. ἔστι δ’ οὐ τὸ τῆς δαπάνης μέγιστον ἐκείνῳ, ἀλλ’ ὅτι τὴν δωρειὰν ὑμᾶς αὐτὸν ἀφῃρῆσθαι νομιεῖ.", "st": "20.40"}, {"sp": "N", "t": "οὐ τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, μὴ Λεύκων ἀδικηθῇ μόνον δεῖ σκοπεῖν, ᾧ φιλοτιμίας ἕνεχ’ ἡ περὶ τῆς δωρειᾶς σπουδὴ γένοιτ’ ἄν, οὐ χρείας, ἀλλὰ καὶ εἴ τις ἄλλος εὖ μὲν ἐποίησεν ὑμᾶς εὖ πράττων, εἰς δέον δὲ νῦν γέγον’ αὐτῷ τὸ λαβεῖν παρ’ ὑμῶν τὴν ἀτέλειαν. τίς οὖν οὗτός ἐστιν; Ἐπικέρδης ὁ Κυρηναῖος, ὅς, εἴπερ τις ἄλλος τῶν εἰληφότων, δικαίως ἠξιώθη ταύτης τῆς τιμῆς, οὐ τῷ μεγάλ’ ἢ θαυμάσι’ ἡλίκα δοῦναι, ἀλλὰ τῷ παρὰ τοιοῦτον καιρὸν ἐν ᾧ καὶ τῶν εὖ πεπονθότων ἔργον ἦν εὑρεῖν ἐθέλοντά τινα ὧν εὐεργέτητο μεμνῆσθαι.", "st": "20.41"}, {"sp": "N", "t": "οὗτος γὰρ ἁνήρ, ὡς τὸ ψήφισμα τοῦτο δηλοῖ τὸ τότ’ αὐτῷ γραφέν, τοῖς ἁλοῦσι τότ’ ἐν Σικελίᾳ τῶν πολιτῶν, ἐν τοιαύτῃ συμφορᾷ καθεστηκόσιν, ἔδωκε μνᾶς ἑκατὸν καὶ τοῦ μὴ τῷ λιμῷ πάντας αὐτοὺς ἀποθανεῖν αἰτιώτατος ἐγένετο. καὶ μετὰ ταῦτα, δοθείσης ἀτελείας αὐτῷ διὰ ταῦτα παρ’ ὑμῶν, ὁρῶν ἐν τῷ πολέμῳ [πρὸ τῶν τριάκοντα μικρὸν] σπανίζοντα τὸν δῆμον χρημάτων, τάλαντον ἔδωκεν αὐτὸς ἐπαγγειλάμενος.", "st": "20.42"}, {"sp": "N", "t": "σκέψασθε δὴ πρὸς Διὸς καὶ θεῶν, ἄνδρες Ἀθηναῖοι, πῶς ἂν ἄνθρωπος μᾶλλον φανερὸς γένοιτ’ εὔνους ὢν ὑμῖν, ἢ πῶς ἧττον ἄξιος ἀδικηθῆναι, ἢ πρῶτον μὲν εἰ παρὼν τῷ τῆς πόλεως ἀτυχήματι μᾶλλον ἕλοιτο τοὺς ἀτυχοῦντας καὶ τὴν παρὰ τούτων χάριν, ἥτις ποτ’ ἔμελλεν ἔσεσθαι, ἢ τοὺς ἐν ἐκείνῳ τῷ χρόνῳ κεκρατηκότας καὶ παρ’ οἷς ἦν, δεύτερον δέ, ἑτέραν χρείαν ἰδών, εἰ φαίνοιτο διδοὺς καὶ μὴ πῶς ἰδίᾳ τὰ ὄντα σώσει προνοούμενος, ἀλλ’ ὅπως τῶν ὑμετέρων μηδὲν ἐνδεῶς ἕξει τὸ καθ’ αὑτόν.", "st": "20.43"}, {"sp": "N", "t": "τοῦτον μέντοι τὸν τῷ μὲν ἔργῳ παρὰ τοὺς μεγίστους καιροὺς οὑτωσὶ κοινὰ τὰ ὄντα τῷ δήμῳ κεκτημένον, τῷ δὲ ῥήματι καὶ τῇ τιμῇ τὴν ἀτέλειαν ἔχοντα, οὐχὶ τὴν ἀτέλειαν ἀφαιρήσεσθε (οὐδὲ γὰρ οὔσῃ χρώμενος φαίνεται), ἀλλὰ τὸ πιστεύειν ὑμῖν, οὗ τί γένοιτ’ ἂν αἴσχιον; τὸ τοίνυν ψήφισμ’ ὑμῖν αὔτ’ ἀναγνώσεται τὸ τότε ψηφισθὲν τῷ ἀνδρί. καὶ θεωρεῖτ’, ὦ ἄνδρες Ἀθηναῖοι, ὅσα ψηφίσματ’ ἄκυρα ποιεῖ ὁ νόμος, καὶ οἵους ἀνθρώπους ἀδικεῖ, καὶ ἐν ὁποίοις καιροῖς χρησίμους ὑμῖν παρασχόντας ἑαυτούς· εὑρήσετε γὰρ τούτους, οὓς ἥκιστα προσῆκεν, ἀδικοῦντα. λέγε.", "st": "20.44"}, {"sp": "N", "t": "ΨΗΦΙΣΜΑ.", "st": "20.44"}, {"sp": "N", "t": "τὰς μὲν εὐεργεσίας ἀνθ’ ὧν εὕρετο τὴν ἀτέλειαν ὁ Ἐπικέρδης ἀκηκόατ’ ἐκ τῶν ψηφισμάτων, ὦ ἄνδρες δικασταί. σκοπεῖτε δὲ μὴ τοῦτο, εἰ μνᾶς ἑκατὸν καὶ πάλιν τάλαντον ἔδωκεν (οὐδὲ γὰρ τοὺς λαβόντας ἔγωγ’ ἡγοῦμαι τὸ πλῆθος τῶν χρημάτων θαυμάσαι), ἀλλὰ τὴν προθυμίαν καὶ τὸ αὐτὸν ἐπαγγειλάμενον ποιεῖν καὶ τοὺς καιροὺς ἐν οἷς.", "st": "20.45"}, {"sp": "N", "t": "πάντες μὲν γάρ εἰσιν ἴσως ἄξιοι χάριν ἀνταπολαμβάνειν οἱ προϋπάρχοντες τῷ ποιεῖν εὖ, μάλιστα δ’ οἱ παρὰ τὰς χρείας, ὧν εἷς οὗτος ἁνὴρ ὢν φαίνεται. εἶτ’ οὐκ αἰσχυνόμεθ’, ὦ ἄνδρες Ἀθηναῖοι, τοὺς τοῦ τοιούτου παῖδας εἰ μηδεμίαν ποιησάμενοι τούτων μηδενὸς μνείαν ἀφῃρημένοι φανούμεθα τὴν δωρειάν, μηδὲν ἔχοντες ἐγκαλέσαι;", "st": "20.46"}, {"sp": "N", "t": "οὐ γὰρ εἰ ἕτεροι μὲν ἦσαν οἱ τότε σωθέντες ὑπ’ αὐτοῦ καὶ δόντες τὴν ἀτέλειαν, ἕτεροι δ’ ὑμεῖς οἱ νῦν ἀφαιρούμενοι, ἀπολύει τοῦτο τὴν αἰσχύνην, ἀλλ’ αὐτὸ δὴ τοῦτο καὶ τὸ δεινόν ἐστιν. εἰ γὰρ οἱ μὲν εἰδότες καὶ παθόντες ἄξια τούτων ἐνόμιζον εὖ πάσχειν, ἡμεῖς δ’ οἱ λόγῳ ταῦτ’ ἀκούοντες ὡς ἀναξίων ἀφαιρησόμεθα, πῶς οὐχ ὑπέρδεινον ποιήσομεν;", "st": "20.47"}, {"sp": "N", "t": "ὁ αὐτὸς τοίνυν ἐστί μοι λόγος οὗτος καὶ περὶ τῶν τοὺς τετρακοσίους καταλυσάντων, καὶ περὶ τῶν ὅτ’ ἔφευγεν ὁ δῆμος χρησίμους αὑτοὺς παρασχόντων· πάντας γὰρ αὐτοὺς ἡγοῦμαι δεινότατ’ ἂν παθεῖν, εἴ τι τῶν τότε ψηφισθέντων αὐτοῖς λυθείη.", "st": "20.48"}, {"sp": "N", "t": "εἰ τοίνυν τις ὑμῶν ἐκεῖνο πέπεισται, πολὺ τοῦ δεηθῆναί τινος τοιούτου νῦν ἀπέχειν τὴν πόλιν, ταῦτα μὲν εὐχέσθω τοῖς θεοῖς, κἀγὼ συνεύχομαι, λογιζέσθω δὲ πρῶτον μὲν ὅτι περὶ νόμου μέλλει φέρειν τὴν ψῆφον ᾧ μὴ λυθέντι δεήσει χρῆσθαι, δεύτερον δ’ ὅτι βλάπτουσιν οἱ πονηροὶ νόμοι καὶ τὰς ἀσφαλῶς οἰκεῖν οἰομένας πόλεις. οὐ γὰρ ἂν μετέπιπτε τὰ πράγματ’ ἐπ’ ἀμφότερα, εἰ μὴ τοὺς μὲν ἐν κινδύνῳ καθεστηκότας καὶ πράξεις χρησταὶ καὶ νόμοι καὶ ἄνδρες χρηστοὶ καὶ πάντ’ ἐξητασμέν’ ἐπὶ τὸ βέλτιον προῆγε, τοὺς δ’ ἐν ἁπάσῃ καθεστάναι δοκοῦντας εὐδαιμονίᾳ πάντα ταῦτ’ ἀμελούμεν’ ὑπέρρει κατὰ μικρόν.", "st": "20.49"}, {"sp": "N", "t": "τῶν γὰρ ἀνθρώπων οἱ πλεῖστοι κτῶνται μὲν τἀγαθὰ τῷ καλῶς βουλεύεσθαι καὶ μηδενὸς καταφρονεῖν, φυλάττειν δ’ οὐκ ἐθέλουσι τοῖς αὐτοῖς τούτοις. ὃ μὴ πάθητε νῦν ὑμεῖς, μηδ’ οἴεσθε νόμον τοιοῦτον θέσθαι δεῖν, ὃς καλῶς τε πράττουσαν τὴν πόλιν ἡμῶν πονηρᾶς δόξης ἀναπλήσει, ἐάν τέ τι συμβῇ ποτέ, ἔρημον τῶν ἐθελησόντων ἀγαθόν τι ποιεῖν καταστήσει.", "st": "20.50"}, {"sp": "N", "t": "οὐ τοίνυν μόνον, ὦ ἄνδρες Ἀθηναῖοι, τοὺς ἰδίᾳ γνόντας εὖ ποιεῖν ὑμᾶς καὶ παρασχόντας χρησίμους αὑτοὺς ἐπὶ τηλικούτων καὶ τοιούτων καιρῶν, οἵων μικρῷ πρότερον Φορμίων διεξελήλυθε κἀγὼ νῦν εἴρηκα, ἄξιόν ἐστιν εὐλαβηθῆναι ἀδικῆσαι, ἀλλὰ καὶ πολλοὺς ἄλλους, οἳ πόλεις ὅλας, τὰς ἑαυτῶν πατρίδας, συμμάχους ὑμῖν ἐπὶ τοῦ πρὸς Λακεδαιμονίους πολέμου παρέσχον, καὶ λέγοντες ἃ συμφέρει τῇ πόλει τῇ ὑμετέρᾳ καὶ πράττοντες·", "st": "20.51"}, {"sp": "N", "t": "ὧν ἔνιοι διὰ τὴν πρὸς ὑμᾶς εὔνοιαν στέρονται τῆς πατρίδος. ὧν ἐπέρχεταί μοι πρώτους ἐξετάσαι τοὺς ἐκ Κορίνθου φεύγοντας. ἀναγκάζομαι δὲ λέγειν πρὸς ὑμᾶς ταῦθ’ ἃ παρ’ ὑμῶν τῶν πρεσβυτέρων αὐτὸς ἀκήκοα. τὰ μὲν οὖν ἄλλ’ ὅσα χρησίμους ὑμῖν ἑαυτοὺς ἐκεῖνοι παρέσχον, ἐάσω· ἀλλ’ ὅθ’ ἡ μεγάλη μάχη πρὸς Λακεδαιμονίους ἐγένεθ’ ἡ ἐν Κορίνθῳ, τῶν ἐν τῇ πόλει βουλευσαμένων μετὰ τὴν μάχην μὴ δέχεσθαι τῷ τείχει τοὺς στρατιώτας, ἀλλὰ πρὸς Λακεδαιμονίους ἐπικηρυκεύεσθαι,", "st": "20.52"}, {"sp": "N", "t": "ὁρῶντες ἠτυχηκυῖαν τὴν πόλιν καὶ τῆς παρόδου κρατοῦντας Λακεδαιμονίους, οὐχὶ προὔδωκαν οὐδ’ ἐβουλεύσαντ’ ἰδίᾳ περὶ τῆς αὑτῶν σωτηρίας, ἀλλὰ πλησίον ὄντων μεθ’ ὅπλων ἁπάντων Πελοποννησίων ἀνέῳξαν τὰς πύλας ὑμῖν βίᾳ τῶν πολλῶν, καὶ μᾶλλον εἵλοντο μεθ’ ὑμῶν τῶν τότε στρατευσαμένων, εἴ τι δέοι, πάσχειν ἢ χωρὶς ὑμῶν ἀκινδύνως σεσῶσθαι, καὶ εἰσέφρουν τὸ στράτευμα, καὶ διέσωσαν καὶ ὑμᾶς καὶ τοὺς συμμάχους.", "st": "20.53"}, {"sp": "N", "t": "ἐπειδὴ δ’ ἡ πρὸς Λακεδαιμονίους εἰρήνη μετὰ ταῦτ’ ἐγένετο, ἡ ἐπ’ Ἀνταλκίδου, ἀντὶ τῶν ἔργων τούτων ὑπὸ Λακεδαιμονίων ἐξέπεσον. ὑποδεξάμενοι δ’ ὑμεῖς αὐτοὺς ἐποιήσατ’ ἔργον ἀνθρώπων καλῶν κἀγαθῶν· ἐψηφίσασθε γὰρ αὐτοῖς ἅπανθ’ ὧν ἐδέοντο. εἶτα ταῦτα νῦν εἰ χρὴ κύρι’ εἶναι σκοποῦμεν; ἀλλ’ ὁ λόγος πρῶτον αἰσχρὸς [τοῖς σκοπουμένοις], εἴ τις ἀκούσειεν ὡς Ἀθηναῖοι σκοποῦσιν εἰ χρὴ τοὺς εὐεργέτας ἐᾶν τὰ δοθέντ’ ἔχειν· πάλαι γὰρ ἐσκέφθαι ταῦτα καὶ ἐγνῶσθαι προσῆκεν. ἀνάγνωθι καὶ τοῦτο τὸ ψήφισμ’ αὐτοῖς.", "st": "20.54"}, {"sp": "N", "t": "ΨΗΦΙΣΜΑ.", "st": "20.54"}, {"sp": "N", "t": "ἃ μὲν ἐψηφίσασθε τοῖς φεύγουσιν δι’ ὑμᾶς Κορινθίων ταῦτ’ ἐστίν, ὦ ἄνδρες δικασταί. ὅρα δέ, εἴ τις ἐκείνους τοὺς καιροὺς εἰδὼς [ἢ παρὼν] ἤ τινος εἰδότος διεξιόντος ἀκούσας, ἀκούσαι τοῦ νόμου τούτου τὰς τότε δωρειὰς δοθείσας ἀφαιρουμένου, ὅσην ἂν κακίαν τῶν θεμένων τὸν νόμον καταγνοίη, οἳ παρὰ μὲν τὰς χρείας οὕτω φιλάνθρωποι καὶ πάντα ποιοῦντες, ἐπειδὴ δ’ ἐπράξαμεν πάνθ’ ὅσ’ ἂν εὐξαίμεθα, οὕτως ἀχάριστοι καὶ κακοί, ὥστε τούς τ’ ἔχοντας ἀφῃρήμεθα καὶ τὸ λοιπὸν μηδενὶ δοῦναι ταῦτ’ ἐξεῖναι νόμον τεθήκαμεν.", "st": "20.55"}, {"sp": "N", "t": "νὴ Δί’ ἀνάξιοι γάρ τινες τῶν εὑρημένων ταῦτ’ ἦσαν· τουτὶ γὰρ παρὰ πάντ’ ἔσται τὸν λόγον αὐτοῖς. ἔπειτ’ ἐκεῖν’ ἀγνοεῖν φήσομεν, ὅτι τὴν ἀξίαν, ὅταν διδῶμεν, δεῖ σκοπεῖν, οὐ μετὰ ταῦθ’ ὕστερον χρόνῳ παμπληθεῖ; τὸ μὲν γὰρ ἐξ ἀρχῆς τι μὴ δοῦναι γνώμῃ χρησαμένων ἔργον ἀνθρώπων ἐστί· τὸ δὲ τοὺς ἔχοντας ἀφαιρεῖσθαι φθονούντων, τοῦτο δ’ οὐ δεῖ δοκεῖν ὑμᾶς πεπονθέναι.", "st": "20.56"}, {"sp": "N", "t": "καὶ μὴν οὐδ’ ἐκεῖν’ ὀκνήσω περὶ τῆς ἀξίας αὐτῆς πρὸς ὑμᾶς εἰπεῖν. ἐγὼ γὰρ οὐ τὸν αὐτὸν τρόπον νομίζω πόλει τὸν ἄξιον ἐξεταστέον εἶναι καὶ ἰδιώτῃ· οὐδὲ γὰρ περὶ τῶν αὐτῶν ἡ σκέψις. ἰδίᾳ μὲν γὰρ ἕκαστος ἡμῶν σκοπεῖ τίς ἄξιός ἐστιν ἑκάστου κηδεστὴς ἢ τῶν τοιούτων τι γίγνεσθαι, ταῦτα δὲ καὶ νόμοις τισὶ καὶ δόξαις διώρισται· κοινῇ δ’ ἡ πόλις καὶ ὁ δῆμος, ὅστις ἂν αὐτὸν εὖ ποιῇ καὶ σῴζῃ, τοῦτο δ’ οὐ γένει καὶ δόξῃ κρινόμενον ἴδοι τις ἄν, ἀλλ’ ἔργῳ. ὅταν μὲν οὖν εὖ πάσχειν δέῃ, τὸν βουλόμενον εὖ ποιεῖν ἡμᾶς ἐάσομεν, ἐπειδὰν δὲ πάθωμεν, τότε τὴν ἀξίαν τοῦ ποιήσαντος σκεψόμεθα; οὐκ ἄρ’ ὀρθῶς βουλευσόμεθα.", "st": "20.57"}, {"sp": "N", "t": "ἀλλὰ νὴ Δί’ οὗτοι μόνοι τοῦτο πείσονται, καὶ περὶ τούτων μόνων ποιοῦμαι λόγον τοσοῦτον. πολλοῦ γε καὶ δέω. ἀλλὰ πάντας μὲν οὐδ’ ἂν ἐγχειρήσαιμ’ ἐξετάζειν ὅσοι πεποιηκότες ὑμᾶς εὖ διὰ τὸν νόμον, εἰ μὴ λυθήσεται, τὰ δοθέντ’ ἀφαιρεθήσονται· ἓν δ’ ἢ δύο δείξας ἔτι ψηφίσματ’ ἀπαλλάττομαι τοῦ περὶ τούτων λέγειν.", "st": "20.58"}, {"sp": "N", "t": "τοῦτο μὲν τοίνυν Θασίους τοὺς μετ’ Ἐκφάντου πῶς οὐκ ἀδικήσετε, ἐὰν ἀφαιρῆσθε τὴν ἀτέλειαν, οἳ παραδόντες ὑμῖν Θάσον καὶ τὴν Λακεδαιμονίων φρουρὰν μεθ’ ὅπλων ἐκβαλόντες καὶ Θρασύβουλον εἰσαγαγόντες καὶ παρασχόντες φίλην ὑμῖν τὴν αὑτῶν πατρίδα αἴτιοι τοῦ γενέσθαι σύμμαχον τὸν περὶ Θρᾴκην τόπον ὑμῖν ἐγένοντο;", "st": "20.59"}, {"sp": "N", "t": "τοῦτο δ’ Ἀρχέβιον καὶ Ἡρακλείδην, οἳ Βυζάντιον παραδόντες Θρασυβούλῳ κυρίους ὑμᾶς ἐποίησαν τοῦ Ἑλλησπόντου, ὥστε τὴν δεκάτην ἀποδόσθαι καὶ χρημάτων εὐπορήσαντας Λακεδαιμονίους ἀναγκάσαι τοιαύτην, οἵαν ὑμῖν ἐδόκει, ποιήσασθαι τὴν εἰρήνην; ὧν, ὦ ἄνδρες Ἀθηναῖοι, μετὰ ταῦτ’ ἐκπεσόντων ἐψηφίσασθ’ ἅπερ, οἶμαι, φεύγουσιν εὐεργέταις δι’ ὑμᾶς προσῆκε, προξενίαν, εὐεργεσίαν, ἀτέλειαν ἁπάντων. εἶτα τοὺς δι’ ὑμᾶς φεύγοντας καὶ δικαίως τι παρ’ ὑμῶν εὑρομένους ἐάσωμεν ἀφαιρεθῆναι ταῦτα, μηδὲν ἔχοντες ἐγκαλέσαι; ἀλλ’ αἰσχρὸν ἂν εἴη.", "st": "20.60"}, {"sp": "N", "t": "μάθοιτε δὲ τοῦτο μάλιστ’ ἄν, ἐκείνως εἰ λογίσαισθε πρὸς ὑμᾶς αὐτούς· εἴ τινες νυνὶ τῶν ἐχόντων Πύδναν ἢ Ποτείδαιαν ἤ τι τῶν ἄλλων χωρίων, ἃ Φιλίππῳ μέν ἐστιν ὑπήκοα, ὑμῖν δ’ ἐχθρά, τὸν αὐτὸν τρόπον ὅνπερ ἡ Θάσος ἦν τότε καὶ τὸ Βυζάντιον Λακεδαιμονίοις μὲν οἰκεῖα, ὑμῖν δ’ ἀλλότρια, παραδώσειν ταῦτ’ ἐπαγγείλαιντο, ἂν αὐτοῖς τὰς αὐτὰς δῶτε δωρειὰς ὥσπερ Ἐκφάντῳ τῷ Θασίῳ καὶ Ἀρχεβίῳ τῷ Βυζαντίῳ, καί τινες τούτων ἀντιλέγοιεν αὐτοῖς ταῦτα λέγοντες,", "st": "20.61"}, {"sp": "N", "t": "ὡς δεινὸν εἴ τινες μόνοι τῶν ἄλλων μετοίκων μὴ χορηγοῖεν, πῶς ποτ’ ἂν ἔχοιτε πρὸς τοὺς ταῦτα λέγοντας; ἢ δῆλον ὅτι φωνὴν οὐκ ἂν ἀνάσχοισθ’ ὡς συκοφαντούντων; οὔκουν αἰσχρὸν εἰ μέλλοντες μὲν εὖ πάσχειν συκοφάντην ἂν τὸν ταῦτα λέγονθ’ ἡγοῖσθε, ἐπὶ τῷ δ’ ἀφελέσθαι τὰς τῶν προτέρων εὐεργετῶν δωρειὰς ταῦτα λεγόντων ἀκούσεσθε;", "st": "20.62"}, {"sp": "N", "t": "φέρε δὴ κἀκεῖν’ ἐξετάσωμεν. οἱ προδόντες τὴν Πύδναν καὶ τἄλλα χωρία τῷ Φιλίππῳ τῷ ποτ’ ἐπαρθέντες ἡμᾶς ἠδίκουν; ἢ πᾶσι πρόδηλον τοῦτο, ὅτι ταῖς παρ’ ἐκείνου δωρειαῖς, ἃς διὰ ταῦτ’ ἔσεσθαι σφίσιν ἡγοῦντο; πότερον οὖν μᾶλλον ἔδει σ’, ὦ Λεπτίνη, τοὺς ἐχθρούς, εἰ δύνασαι, πεῖσαι τοὺς ἐπὶ τοῖς πρὸς ἡμᾶς ἀδικήμασι γιγνομένους ἐκείνων εὐεργέτας μὴ τιμᾶν, ἢ θεῖναι νόμον ἡμῖν ὃς τῶν τοῖς ἡμετέροις εὐεργέταις ὑπαρχουσῶν δωρειῶν ἀφαιρεῖταί τι; ἐγὼ μὲν ἐκεῖν’ οἶμαι. ἀλλ’ ἵνα μὴ πόρρω τοῦ παρόντος γένωμαι, λαβὲ τὰ ψηφίσμαθ’ ἃ τοῖς Θασίοις καὶ Βυζαντίοις ἐγράφη. λέγε.", "st": "20.63"}, {"sp": "N", "t": "ΨΗΦΙΣΜΑΤΑ.", "st": "20.63"}, {"sp": "N", "t": "ἠκούσατε μὲν τῶν ψηφισμάτων, ὦ ἄνδρες δικασταί. τούτων δ’ ἴσως ἔνιοι τῶν ἀνδρῶν οὐκέτ’ εἰσίν. ἀλλὰ τὰ ἔργα τὰ πραχθέντ’ ἔστιν, ἐπειδήπερ ἅπαξ ἐπράχθη. προσήκει τοίνυν τὰς στήλας ταύτας κυρίας ἐᾶν τὸν πάντα χρόνον, ἵν’, ἕως μὲν ἄν τινες ζῶσι, μηδὲν ὑφ’ ὑμῶν ἀδικῶνται, ἐπειδὰν δὲ τελευτήσωσιν, ἐκεῖναι τοῦ τῆς πόλεως ἤθους μνημεῖον ὦσι, καὶ παραδείγμαθ’ ἑστῶσι τοῖς βουλομένοις τι ποιεῖν ὑμᾶς ἀγαθόν, ὅσους εὖ ποιήσαντας ἡ πόλις ἀντ’ εὖ πεποίηκεν.", "st": "20.64"}, {"sp": "N", "t": "καὶ μὴν μηδ’ ἐκεῖν’ ὑμᾶς, ὦ ἄνδρες Ἀθηναῖοι, λανθανέτω, ὅτι τῶν αἰσχίστων ἐστὶν πάντας ἀνθρώπους ἰδεῖν καὶ ἀκοῦσαι τὰς μὲν συμφοράς, αἷς δι’ ὑμᾶς ἐχρήσανθ’ οἱ ἄνδρες οὗτοι, πάντα τὸν χρόνον κυρίας αὐτοῖς γεγενημένας, τὰς δὲ δωρειάς, ἃς ἀντὶ τούτων ἔλαβον παρ’ ὑμῶν, καὶ δὴ λελυμένας.", "st": "20.65"}, {"sp": "N", "t": "πολὺ γὰρ μᾶλλον ἥρμοττεν τὰ δοθέντ’ ἐῶντας τῶν ἀτυχημάτων ἀφαιρεῖν ἢ τούτων μενόντων τὰς δωρειὰς ἀφαιρεῖσθαι. φέρε γὰρ πρὸς Διός, τίς ἔστιν ὅστις εὖ ποιεῖν ὑμᾶς βουλήσεται, μέλλων, ἂν μὲν ἀποτύχῃ, παραχρῆμα δίκην δώσειν τοῖς ἐχθροῖς, ἂν δὲ κατορθώσῃ, τὰς χάριτας παρ’ ὑμῶν ἀπίστους ἕξειν;", "st": "20.66"}, {"sp": "N", "t": "πάνυ τοίνυν ἀχθοίμην ἄν, ὦ ἄνδρες δικασταί, εἰ τοῦτο μόνον δόξαιμι δίκαιον κατηγορεῖν τοῦ νόμου, ὅτι πολλοὺς ξένους εὐεργέτας ἀφαιρεῖται τὴν ἀτέλειαν, τῶν δὲ πολιτῶν μηδέν’ ἄξιον δοκοίην ἔχειν δεῖξαι τῶν εὑρημένων ταύτην τὴν τιμήν. καὶ γὰρ τἄλλ’ ἀγάθ’ εὐξαίμην ἂν ἔγωγε παρ’ ἡμῖν εἶναι πλεῖστα, καὶ ἄνδρας ἀρίστους καὶ πλείστους εὐεργέτας τῆς πόλεως πολίτας εἶναι.", "st": "20.67"}, {"sp": "N", "t": "πρῶτον μὲν τοίνυν Κόνωνα σκοπεῖτε, εἰ ἄρ’ ἄξιον, καταμεμψαμένους ἢ τὸν ἄνδρα ἢ τὰ πεπραγμένα, ἄκυρόν τι ποιῆσαι τῶν ἐκείνῳ δοθέντων. οὗτος γάρ, ὡς ὑμῶν τινῶν ἔστιν ἀκοῦσαι τῶν κατὰ τὴν αὐτὴν ἡλικίαν ὄντων, μετὰ τὴν τοῦ δήμου κάθοδον τὴν ἐκ Πειραιῶς ἀσθενοῦς ἡμῶν τῆς πόλεως οὔσης καὶ ναῦν οὐδεμίαν κεκτημένης, στρατηγῶν βασιλεῖ, παρ’ ὑμῶν οὐδ’ ἡντινοῦν ἀφορμὴν λαβών, κατεναυμάχησεν Λακεδαιμονίους, καὶ πρότερον τοῖς ἄλλοις ἐπιτάττοντας εἴθισ’ ἀκούειν ὑμῶν, καὶ τοὺς ἁρμοστὰς ἐξήλασεν ἐκ τῶν νήσων, καὶ μετὰ ταῦτα δεῦρ’ ἐλθὼν ἀνέστησε τὰ τείχη, καὶ πρῶτος πάλιν περὶ τῆς ἡγεμονίας ἐποίησε τῇ πόλει τὸν λόγον πρὸς Λακεδαιμονίους εἶναι.", "st": "20.68"}, {"sp": "N", "t": "καὶ γάρ τοι μόνῳ τῶν πάντων αὐτῷ τοῦτ’ ἐν τῇ στήλῃ γέγραπται· “ἐπειδὴ [Κόνων]” φησὶν “ἠλευθέρωσε τοὺς Ἀθηναίων συμμάχους.” ἔστιν δὲ τοῦτο τὸ γράμμ’, ὦ ἄνδρες δικασταί, ἐκείνῳ μὲν φιλοτιμία πρὸς ὑμᾶς αὐτούς, ὑμῖν δὲ πρὸς πάντας τοὺς Ἕλληνας· ὅτου γὰρ ἄν τις παρ’ ὑμῶν ἀγαθοῦ τοῖς ἄλλοις αἴτιος γένηται, τούτου τὴν δόξαν τὸ τῆς πόλεως ὄνομα καρποῦται.", "st": "20.69"}, {"sp": "N", "t": "διόπερ οὐ μόνον αὐτῷ τὴν ἀτέλειαν ἔδωκαν οἱ τότε, ἀλλὰ καὶ χαλκῆν εἰκόνα, ὥσπερ Ἁρμοδίου καὶ Ἀριστογείτονος, ἔστησαν πρώτου· ἡγοῦντο γὰρ οὐ μικρὰν τυραννίδα καὶ τοῦτον τὴν Λακεδαιμονίων ἀρχὴν καταλύσαντα πεπαυκέναι. ἵν’ οὖν μᾶλλον οἷς λέγω προσέχητε, τὰ ψηφίσμαθ’ ὑμῖν αὔτ’ ἀναγνώσεται τὰ τότε ψηφισθέντα τῷ Κόνωνι. λέγε.", "st": "20.70"}, {"sp": "N", "t": "ΨΗΦΙΣΜΑΤΑ.", "st": "20.70"}, {"sp": "N", "t": "οὐ τοίνυν ὑφ’ ὑμῶν μόνον ὁ Κόνων, ὦ ἄνδρες Ἀθηναῖοι, τότ’ ἐτιμήθη πράξας ἃ διεξῆλθον ἐγώ, ἀλλὰ καὶ ὑπ’ ἄλλων πολλῶν, οἳ δικαίως ὧν εὐεργέτηντο χάριν ᾤοντο δεῖν ἀποδιδόναι. οὔκουν αἰσχρόν, ὦ ἄνδρες Ἀθηναῖοι, εἰ αἱ μὲν παρὰ τοῖς ἄλλοις δωρειαὶ βέβαιοι μένουσιν αὐτῷ, τῆς δὲ παρ’ ὑμῶν μόνης τοῦτ’ ἀφαιρήσεται;", "st": "20.71"}, {"sp": "N", "t": "καὶ μὴν οὐδ’ ἐκεῖνο καλόν, ζῶντα μὲν αὐτὸν οὕτω τιμᾶν ὥστε τοσούτων ὅσων ἀκηκόατ’ ἀξιοῦν, ἐπειδὴ δὲ τετελεύτηκεν, [μηδεμίαν ποιησαμένους τούτων μνείαν] ἀφελέσθαι τι τῶν δοθέντων τότε. πολλὰ μὲν γάρ ἐστιν, ὦ ἄνδρες Ἀθηναῖοι, τῶν ὑπ’ ἐκείνου πραχθέντων ἄξι’ ἐπαίνου, δι’ ἃ πάντα προσήκει μὴ λύειν τὰς ἐπὶ τούτοις δοθείσας δωρειάς, κάλλιστον δὲ πάντων ἡ τῶν τειχῶν ἀνάστασις.", "st": "20.72"}, {"sp": "N", "t": "γνοίη δ’ ἄν τις εἰ παραθείη πῶς Θεμιστοκλῆς, ὁ τῶν καθ’ ἑαυτὸν ἁπάντων ἀνδρῶν ἐνδοξότατος, ταὐτὸ τοῦτ’ ἐποίησεν. λέγεται τοίνυν ἐκεῖνος, τειχίζειν εἰπὼν τοῖς πολίταις, κἂν ἀφικνῆταί τις ἐκ Λακεδαίμονος, κατέχειν κελεύσας, οἴχεσθαι πρεσβεύων αὐτὸς ὡς τοὺς Λακεδαιμονίους, λόγων δὲ γιγνομένων ἐκεῖ καί τινων ἀπαγγελλόντων ὡς Ἀθηναῖοι τειχίζουσιν, ἀρνεῖσθαι καὶ πρέσβεις πέμπειν σκεψομένους κελεύειν, ἐπειδὴ δ’ οὐχ ἧκον οὗτοι, πέμπειν ἑτέρους παραινεῖν. καὶ πάντες ἴσως ἀκηκόαθ’ ὃν τρόπον ἐξαπατῆσαι λέγεται.", "st": "20.73"}, {"sp": "N", "t": "φημὶ τοίνυν ἐγώ (καὶ πρὸς Διός, ἄνδρες Ἀθηναῖοι, μηδεὶς φθόνῳ τὸ μέλλον ἀκούσῃ, ἀλλ’ ἂν ἀληθὲς ᾖ σκοπείτω), ὅσῳ τὸ φανερῶς τοῦ λάθρᾳ κρεῖττον, καὶ τὸ νικῶντας τοῦ παρακρουσαμένους πράττειν ὁτιοῦν ἐντιμότερον, τοσούτῳ κάλλιον Κόνωνα τὰ τείχη στῆσαι Θεμιστοκλέους· ὁ μὲν γὰρ λαθών, ὁ δὲ νικήσας τοὺς κωλύσοντας αὔτ’ ἐποίησεν. οὐ τοίνυν ἄξιον τὸν τοιοῦτον ὑφ’ ὑμῶν ἀδικηθῆναι, οὐδ’ ἔλαττον σχεῖν τῶν ῥητόρων τῶν διδαξόντων ὡς ἀφελέσθαι τι χρὴ τῶν ἐκείνῳ δοθέντων.", "st": "20.74"}, {"sp": "N", "t": "εἶεν. ἀλλὰ νὴ Δία τὸν παῖδα τὸν Χαβρίου περιίδωμεν ἀφαιρεθέντα τὴν ἀτέλειαν, ἣν ὁ πατὴρ αὐτῷ δικαίως παρ’ ὑμῶν λαβὼν κατέλιπεν. ἀλλ’ οὐδέν’ ἀνθρώπων εὖ φρονοῦντ’ οἶμαι ταῦτ’ ἂν φῆσαι καλῶς ἔχειν. ἴστε μὲν οὖν ἴσως, καὶ ἄνευ τοῦ παρ’ ἐμοῦ λόγου, ὅτι σπουδαῖος Χαβρίας ἦν ἀνήρ, οὐ μὴν κωλύει γ’ οὐδὲν κἀμὲ διὰ βραχέων ἐπιμνησθῆναι τῶν πεπραγμένων αὐτῷ.", "st": "20.75"}, {"sp": "N", "t": "ὃν μὲν οὖν τρόπον ὑμᾶς ἔχων πρὸς ἅπαντας Πελοποννησίους παρετάξατ’ ἐν Θήβαις, καὶ ὡς Γοργώπαν ἀπέκτεινεν ἐν Αἰγίνῃ, καὶ ὅσ’ ἐν Κύπρῳ τρόπαι’ ἔστησεν καὶ μετὰ ταῦτ’ ἐν Αἰγύπτῳ, καὶ ὅτι πᾶσαν ἐπελθὼν ὀλίγου δέω λέγειν χώραν οὐδαμοῦ τὸ τῆς πόλεως ὄνομ’ οὐδ’ αὑτὸν κατῄσχυνεν, οὔτε πάνυ ῥᾴδιον κατὰ τὴν ἀξίαν εἰπεῖν, πολλή τ’ αἰσχύνη λέγοντος ἐμοῦ ταῦτ’ ἐλάττω φανῆναι τῆς ἐν ἑκάστῳ νῦν περὶ αὐτοῦ δόξης ὑπαρχούσης· ἃ δ’ οὐδαμῶς ἂν εἰπὼν οἴομαι μικρὰ ποιῆσαι, ταῦθ’ ὑπομνῆσαι πειράσομαι.", "st": "20.76"}, {"sp": "N", "t": "ἐνίκησεν μὲν τοίνυν Λακεδαιμονίους ναυμαχίᾳ καὶ πεντήκοντα μιᾶς δεούσας ἔλαβ’ αἰχμαλώτους τριήρεις, εἷλε δὲ τῶν νήσων τούτων τὰς πολλὰς καὶ παρέδωκεν ὑμῖν καὶ φιλίας ἐποίησεν ἐχθρῶς ἐχούσας πρότερον, τρισχίλια δ’ αἰχμάλωτα σώματα δεῦρ’ ἤγαγεν, καὶ πλεῖν ἢ δέκα καὶ ἑκατὸν τάλαντ’ ἀπέφην’ ἀπὸ τῶν πολεμίων. καὶ τούτων πάντων ὑμῶν τινὲς οἱ πρεσβύτατοι μάρτυρές εἰσί μοι. πρὸς δὲ τούτοις ἄλλας τριήρεις πλεῖν ἢ εἴκοσιν εἷλε, κατὰ μίαν καὶ δύο λαμβάνων, ἃς ἁπάσας εἰς τοὺς ὑμετέρους λιμένας κατήγαγεν.", "st": "20.77"}, {"sp": "N", "t": "ἑνὶ δὲ κεφαλαίῳ μόνος τῶν πάντων στρατηγῶν οὐ πόλιν, οὐ φρούριον, οὐ ναῦν, οὐ στρατιώτην ἀπώλεσεν οὐδέν’ ἡγούμενος ὑμῶν, οὐδ’ ἔστιν οὐδενὶ τῶν ὑμετέρων ἐχθρῶν τρόπαιον οὐδὲν ἀφ’ ὑμῶν τε κἀκείνου, ὑμῖν δ’ ἀπὸ πολλῶν πόλλ’ ἐκείνου στρατηγοῦντος. ἵνα δὲ μὴ λέγων παραλίπω τι τῶν πεπραγμένων αὐτῷ, ἀναγνώσεται γεγραμμένας ὑμῖν τάς τε ναῦς ὅσας ἔλαβεν καὶ οὗ ἑκάστην, καὶ τῶν πόλεων τὸν ἀριθμὸν καὶ τῶν χρημάτων τὸ πλῆθος, καὶ τῶν τροπαίων οὗ ἕκαστον. λέγε.", "st": "20.78"}, {"sp": "N", "t": "ΠΡΑΞΕΙΣ ΧΑΒΡΟΥ.", "st": "20.78"}, {"sp": "N", "t": "δοκεῖ τισὶν ὑμῶν, ὦ ἄνδρες δικασταί, οὗτος ὃ τοσαύτας πόλεις λαβὼν καὶ τριήρεις τῶν πολεμίων ναυμαχίᾳ νικήσας, καὶ τοσούτων καλῶν αἴτιος ὤν, αἰσχροῦ δ’ οὐδενὸς τῇ πόλει, ἄξιος εἶναι ἀποστερηθῆναι τὴν ἀτέλειαν ἣν εὕρετο παρ’ ὑμῶν καὶ τῷ υἱεῖ κατέλιπεν; ἐγὼ μὲν οὐκ οἴομαι. καὶ γὰρ ἂν ἄλογον εἴη· μίαν μὲν πόλιν εἰ ἀπώλεσεν ἢ ναῦς δέκα μόνας, περὶ προδοσίας ἂν αὐτὸν εἰσήγγελλον οὗτοι, καὶ εἰ ἑάλω, τὸν ἅπαντ’ ἂν ἀπωλώλει χρόνον·", "st": "20.79"}, {"sp": "N", "t": "ἐπειδὴ δὲ τοὐναντίον ἑπτακαίδεκα μὲν πόλεις εἷλεν, ἑβδομήκοντα δὲ ναῦς ἔλαβεν, τρισχιλίους δ’ αἰχμαλώτους, δέκα δὲ καὶ ἑκατὸν τάλαντ’ ἀπέφηνεν, τοσαῦτα δ’ ἔστησε τρόπαια, τηνικαῦτα δ’ οὐκ ἔσται κύρι’ αὐτῷ τὰ δοθέντ’ ἐπὶ τούτοις; καὶ μήν, ὦ ἄνδρες Ἀθηναῖοι, καὶ ζῶν πάνθ’ ὑπὲρ ὑμῶν φανήσεται πράξας Χαβρίας, καὶ τὴν τελευτὴν αὐτὴν τοῦ βίου πεποιημένος οὐχ ὑπὲρ ἄλλου τινός, ὥστε δικαίως ἂν οὐ μόνον διὰ τὰ ζῶντι πεπραγμένα φαίνοισθ’ εὐνοϊκῶς διακείμενοι πρὸς τὸν υἱὸν αὐτοῦ, ἀλλὰ καὶ διὰ ταύτην.", "st": "20.80"}, {"sp": "N", "t": "ἄξιον τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, κἀκεῖνο σκοπεῖν, ὅπως μὴ φανούμεθα φαυλότεροι Χίων περὶ τοὺς εὐεργέτας γεγενημένοι. εἰ γὰρ ἐκεῖνοι μέν, ἐφ’ οὓς μεθ’ ὅπλων ἦλθεν ἐν ἐχθροῦ τάξει, μηδὲν ὧν ἔδοσαν πρότερον νῦν ἀφῄρηνται, ἀλλὰ τὰς πάλαι χάριτας μείζους τῶν καινῶν ἐγκλημάτων πεποίηνται, ὑμεῖς δέ, ὑπὲρ ὧν ἐπ’ ἐκείνους ἐλθὼν ἐτελεύτησεν, ἀντὶ τοῦ διὰ ταῦτ’ ἔτι μᾶλλον αὐτὸν τιμᾶν καὶ τῶν ἐπὶ ταῖς πρότερον εὐεργεσίαις τι δοθέντων ἀφῃρημένοι φανήσεσθε, πῶς οὐκ εἰκότως αἰσχύνην ἕξετε;", "st": "20.81"}, {"sp": "N", "t": "καὶ μὴν καὶ κατ’ ἐκεῖν’ ἀνάξι’ ἂν εἴη πεπονθὼς ὁ παῖς εἴ ⟨τι⟩ τῆς δωρειᾶς ἀφαιρεθείη, καθ’ ὃ πολλάκις ὑμῶν στρατηγήσαντος Χαβρίου οὐδενὸς πώποθ’ υἱὸς ὀρφανὸς δι’ ἐκεῖνον ἐγένετο, αὐτὸς δ’ ἐν ὀρφανίᾳ τέθραπται διὰ τὴν πρὸς ὑμᾶς φιλοτιμίαν τοῦ πατρός. οὕτω γὰρ ὡς ἀληθῶς ἔμοιγε φαίνεται βεβαίως πως ἐκεῖνος φιλόπολις, ὥστε δοκῶν καὶ ὢν ἀσφαλέστατος στρατηγὸς ἁπάντων, ὑπὲρ μὲν ὑμῶν, ὁπόθ’ ἡγοῖτο, ἐχρῆτο τούτῳ, ὑπὲρ αὑτοῦ δέ, ἐπειδὴ τὸ καθ’ αὑτὸν ἐτάχθη κινδυνεύειν, παρεῖδε, καὶ μᾶλλον εἵλετο μὴ ζῆν ἢ καταισχῦναι τὰς παρ’ ὑμῶν ὑπαρχούσας αὐτῷ τιμάς.", "st": "20.82"}, {"sp": "N", "t": "εἶθ’ ὑπὲρ ὧν ἐκεῖνος ᾤετο δεῖν ἀποθνῄσκειν ἢ νικᾶν, ταῦθ’ ἡμεῖς ἀφελώμεθα τὸν υἱὸν αὐτοῦ; καὶ τί φήσομεν, ὦ ἄνδρες Ἀθηναῖοι, ὅταν τὰ μὲν τρόπαι’ ἑστήκῃ δῆλα πᾶσιν ἀνθρώποις, ἃ ὑπὲρ ὑμῶν στρατηγῶν ἐκεῖνος ἔστησε, τῶν δ’ ἐπὶ τούτοις δωρειῶν ἀφῃρημένον τι φαίνηται; οὐ σκέψεσθ’, ὦ ἄνδρες Ἀθηναῖοι, καὶ λογιεῖσθε, ὅτι νῦν οὐχ ὁ νόμος κρίνεται πότερον ἔστ’ ἐπιτήδειος ἢ οὔ, ἀλλ’ ὑμεῖς δοκιμάζεσθ’ εἴτ’ ἐπιτήδειοι πάσχειν ἔστ’ εὖ τὸν λοιπὸν χρόνον εἴτε μή;", "st": "20.83"}, {"sp": "N", "t": "λαβὲ δὴ καὶ τὸ τῷ Χαβρίᾳ ψήφισμα ψηφισθέν. ὅρα δὴ καὶ σκόπει· δεῖ γὰρ αὔτ’ ἐνταῦθ’ εἶναί που.", "st": "20.84"}, {"sp": "N", "t": "ἐγὼ δ’ ἔτι τοῦτ’ εἰπεῖν ὑπὲρ Χαβρίου βούλομαι. ὑμεῖς, ὦ ἄνδρες Ἀθηναῖοι, τιμῶντές ποτ’ Ἰφικράτην, οὐ μόνον αὐτὸν ἐτιμήσατε, ἀλλὰ καὶ δι’ ἐκεῖνον Στράβακα καὶ Πολύστρατον· καὶ πάλιν, Τιμοθέῳ διδόντες τὴν δωρειάν, δι’ ἐκεῖνον ἐδώκατε καὶ Κλεάρχῳ καί τισιν ἄλλοις πολιτείαν· Χαβρίας δ’ αὐτὸς ἐτιμήθη παρ’ ὑμῖν μόνος.", "st": "20.84"}, {"sp": "N", "t": "εἰ δὴ τόθ’, ὅθ’ εὑρίσκετο τὴν δωρειάν, ἠξίωσεν ὑμᾶς, ὥσπερ δι’ Ἰφικράτην καὶ Τιμόθεον εὖ τινὰς πεποιήκατε, οὕτω καὶ δι’ αὑτὸν εὖ ποιῆσαι τούτων τινὰς τῶν εὑρημένων τὴν ἀτέλειαν, οὓς νῦν οὗτοι μεμφόμενοι πάντας ἀφαιρεῖσθαι κελεύουσιν ὁμοίως, οὐκ ἂν ἐδώκατε ταύτην αὐτῷ τὴν χάριν; ἔγωγ’ ἡγοῦμαι.", "st": "20.85"}, {"sp": "N", "t": "εἶθ’ οἷς δι’ ἐκεῖνον ἂν τότ’ ἐδώκατε δωρειάν, διὰ τούτους νῦν αὐτὸν ἐκεῖνον ἀφαιρήσεσθε τὴν ἀτέλειαν; ἀλλ’ ἄλογον. οὐδὲ γὰρ ὑμῖν ἁρμόττει δοκεῖν παρὰ μὲν τὰς εὐεργεσίας οὕτω προχείρως ἔχειν ὥστε μὴ μόνους αὐτοὺς τοὺς εὐεργέτας τιμᾶν, ἀλλὰ καὶ τοὺς ἐκείνων φίλους, ἐπειδὰν δὲ χρόνος διέλθῃ βραχύς, καὶ ὅσ’ αὐτοῖς δεδώκατε, ταῦτ’ ἀφαιρεῖσθαι.", "st": "20.86"}, {"sp": "N", "t": "ΨΗΦΙΣΜΑΤΑ ΤΩΝ ΧΑΒΡΙΟΥ ΤΙΜΩΝ.", "st": "20.86"}, {"sp": "N", "t": "οὓς μὲν τοίνυν ἀδικήσετε, εἰ μὴ λύσετε τὸν νόμον, πρὸς πολλοῖς ἄλλοις, οὓς ἀκηκόατε, εἰσίν, ὦ ἄνδρες δικασταί. σκοπεῖτε δὴ καὶ λογίσασθ’ ἐν ὑμῖν αὐτοῖς, εἴ τινες τούτων τῶν τετελευτηκότων λάβοιεν τρόπῳ τινὶ τοῦ νυνὶ γιγνομένου πράγματος αἴσθησιν, ὡς ἂν εἰκότως ἀγανακτήσειαν. εἰ γὰρ ὧν ἔργῳ πεποίηκεν ἕκαστος αὐτῶν ὑμᾶς εὖ, τούτων ἐκ λόγου κρίσις γίγνεται, καὶ τὰ καλῶς πραχθένθ’ ὑπ’ ἐκείνων, ἂν ὑφ’ ἡμῶν μὴ καλῶς ῥηθῇ τῷ λόγῳ, μάτην τοῖς πονήσασιν εἴργασται, πῶς οὐ δεινὰ πάσχουσιν;", "st": "20.87"}, {"sp": "N", "t": "ἵνα τοίνυν εἰδῆτ’, ὦ ἄνδρες Ἀθηναῖοι, ὅτι ὡς ἀληθῶς ἐπὶ πᾶσι δικαίοις ποιούμεθα τοὺς λόγους πάντας οὓς λέγομεν πρὸς ὑμᾶς, καὶ οὐδὲν ἔσθ’ ὅ τι τοῦ παρακρούσασθαι καὶ φενακίσαι λέγεται παρ’ ἡμῶν ἕνεκα, ἀναγνώσεται τὸν νόμον ὑμῖν ὃν παρεισφέρομεν γράψαντες ἀντὶ τοῦδε, ὃν οὐκ ἐπιτήδειον εἶναί φαμεν. γνώσεσθε γὰρ ἐκ τούτου πρόνοιάν τιν’ ἔχοντας ἡμᾶς καὶ ὅπως ὑμεῖς μηδὲν αἰσχρὸν ποιῆσαι δόξετε, καὶ ὅπως, εἴ τινά τις καταμέμφεται τῶν εὑρημένων τὰς δωρειάς, ἂν δίκαιον ᾖ, κρίνας παρ’ ὑμῖν ἀφαιρήσεται, καὶ ὅπως, οὓς οὐδεὶς ἂν ἀντείποι μὴ οὐ δεῖν ἔχειν, ἕξουσιν τὰ δοθέντα.", "st": "20.88"}, {"sp": "N", "t": "καὶ τούτων πάντων οὐδὲν ἔσθ’ ἡμέτερον οὐδὲ καινὸν εὕρημα, ἀλλ’ ὁ παλαιός, ὃν οὗτος παρέβη, νόμος οὕτω κελεύει νομοθετεῖν, γράφεσθαι μέν, ἄν τίς τινα τῶν ὑπαρχόντων νόμων μὴ καλῶς ἔχειν ἡγῆται, παρεισφέρειν δ’ αὐτὸν ἄλλον, ὃν ἂν τιθῇ λύων ἐκεῖνον, ὑμᾶς δ’ ἀκούσαντες ἑλέσθαι τὸν κρείττω.", "st": "20.89"}, {"sp": "N", "t": "οὐ γὰρ ᾤετο δεῖν ὁ Σόλων, ὁ τοῦτον τὸν τρόπον προστάξας νομοθετεῖν, τοὺς μὲν θεσμοθέτας τοὺς ἐπὶ τοὺς νόμους κληρουμένους δὶς δοκιμασθέντας ἄρχειν, ἔν τε τῇ βουλῇ καὶ παρ’ ὑμῖν ἐν τῷ δικαστηρίῳ, τοὺς δὲ νόμους αὐτούς, καθ’ οὓς καὶ τούτοις ἄρχειν καὶ πᾶσι τοῖς ἄλλοις πολιτεύεσθαι προσήκει, ἐπὶ καιροῦ τεθέντας, ὅπως ἔτυχον, μὴ δοκιμασθέντας κυρίους εἶναι.", "st": "20.90"}, {"sp": "N", "t": "καὶ γάρ τοι τότε μέν, τέως τὸν τρόπον τοῦτον ἐνομοθέτουν, τοῖς μὲν ὑπάρχουσι νόμοις ἐχρῶντο, καινοὺς δ’ οὐκ ἐτίθεσαν· ἐπειδὴ δὲ τῶν πολιτευομένων τινὲς δυνηθέντες, ὡς ἐγὼ πυνθάνομαι, κατεσκεύασαν αὑτοῖς ἐξεῖναι νομοθετεῖν, ὅταν τις βούληται καὶ ὃν ἂν τύχῃ τρόπον, τοσοῦτοι μὲν οἱ ἐναντίοι σφίσιν αὑτοῖς εἰσὶ νόμοι, ὥστε χειροτονεῖθ’ ὑμεῖς τοὺς διαλέξοντας τοὺς ἐναντίους ἐπὶ πάμπολυν ἤδη χρόνον,", "st": "20.91"}, {"sp": "N", "t": "καὶ τὸ πρᾶγμ’ οὐδὲν μᾶλλον δύναται πέρας ἔχειν· ψηφισμάτων δ’ οὐδ’ ὁτιοῦν διαφέρουσιν οἱ νόμοι, ἀλλὰ νεώτεροι οἱ νόμοι, καθ’ οὓς τὰ ψηφίσματα δεῖ γράφεσθαι, τῶν ψηφισμάτων αὐτῶν ὑμῖν εἰσίν. ἵν’ οὖν μὴ λόγον λέγω μόνον, ἀλλὰ καὶ τὸν νόμον αὐτὸν ὅν φημι δείξω, λαβέ μοι τὸν νόμον καθ’ ὃν ἦσαν οἱ πρότερον νομοθέται. λέγε.", "st": "20.92"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "20.92"}, {"sp": "N", "t": "συνίεθ’ ὃν τρόπον, ὦ ἄνδρες Ἀθηναῖοι, ὁ Σόλων τοὺς νόμους ὡς καλῶς κελεύει τιθέναι, πρῶτον μὲν παρ’ ὑμῖν, ἐν τοῖς ὀμωμοκόσιν, παρ’ οἷσπερ καὶ τἄλλα κυροῦται, ἔπειτα λύοντα τοὺς ἐναντίους, ἵν’ εἷς ᾖ περὶ τῶν ὄντων ἑκάστου νόμος, καὶ μὴ τοὺς ἰδιώτας αὐτὸ τοῦτο ταράττῃ καὶ ποιῇ τῶν ἅπαντας εἰδότων τοὺς νόμους ἔλαττον ἔχειν, ἀλλὰ πᾶσιν ᾖ ταὔτ’ ἀναγνῶναι καὶ μαθεῖν ἁπλᾶ καὶ σαφῆ τὰ δίκαια.", "st": "20.93"}, {"sp": "N", "t": "καὶ πρὸ τούτων γ’ ἐπέταξεν ἐκθεῖναι πρόσθε τῶν ἐπωνύμων καὶ τῷ γραμματεῖ παραδοῦναι, τοῦτον δ’ ἐν ταῖς ἐκκλησίαις ἀναγιγνώσκειν, ἵν’ ἕκαστος ὑμῶν ἀκούσας πολλάκις καὶ κατὰ σχολὴν σκεψάμενος, ἃν ᾖ καὶ δίκαια καὶ συμφέροντα, ταῦτα νομοθετῇ. τούτων τοίνυν τοσούτων ὄντων [δικαίων] τὸ πλῆθος, οὑτοσὶ μὲν οὐδ’ ὁτιοῦν ἐποίησε [Λεπτίνης]· οὐδὲ γὰρ ἂν ὑμεῖς ποτ’ ἐπείσθητε, ὡς ἐγὼ νομίζω, θέσθαι τὸν νόμον· ἡμεῖς δ’, ὦ ἄνδρες Ἀθηναῖοι, πάντα, καὶ παρεισφέρομεν πολλῷ καὶ κρείττω καὶ δικαιότερον τοῦ τούτου νόμον.", "st": "20.94"}, {"sp": "N", "t": "γνώσεσθε δ’ ἀκούοντες. λαβὲ καὶ λέγε πρῶτον μὲν ἃ τοῦ τούτου νόμου γεγράμμεθα, εἶθ’ ἅ φαμεν δεῖν ἀντὶ τούτων τεθῆναι. λέγε.", "st": "20.95"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "20.95"}, {"sp": "N", "t": "ταῦτα μέν ἐσθ’ ἃ τοῦ τούτου νόμου διώκομεν ὡς οὐκ ἐπιτήδεια. τὰ δ’ ἑξῆς λέγε, ἃ τούτων εἶναι βελτίω φαμέν. προσέχετ’, ἄνδρες δικασταί, τούτοις ἀναγιγνωσκομένοις τὸν νοῦν. λέγε.", "st": "20.95"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "20.95"}, {"sp": "N", "t": "ἐπίσχες. τοῦτο μέν ἐστιν ἐν τοῖς οὖσι νόμοις κυρίοις ὑπάρχον καλόν, ὦ ἄνδρες Ἀθηναῖοι, καὶ σαφές, “τὰς δωρειὰς ὅσας ὁ δῆμος ἔδωκε κυρίας εἶναι·” δίκαιον, ὦ γῆ καὶ θεοί. χρῆν τοίνυν Λεπτίνην μὴ πρότερον τιθέναι τὸν ἑαυτοῦ νόμον πρὶν τοῦτον ἔλυσε γραψάμενος. νῦν δὲ μαρτυρίαν καθ’ ἑαυτοῦ καταλείπων ὅτι παρανομεῖ τουτονὶ τὸν νόμον, ὅμως ἐνομοθέτει, καὶ ταῦθ’ ἑτέρου κελεύοντος νόμου καὶ κατ’ αὐτὸ τοῦτ’ ἔνοχον εἶναι τῇ γραφῇ, ἐὰν ἐναντίος ᾖ τοῖς πρότερον κειμένοις νόμοις. λαβὲ δ’ αὐτὸν τὸν νόμον.", "st": "20.96"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "20.96"}, {"sp": "N", "t": "οὔκουν ἐναντίον, ὦ ἄνδρες Ἀθηναῖοι, τῷ “κυρίας εἶναι τὰς δωρειάς, ὅσας ὁ δῆμος ἔδωκε,” τὸ “μηδέν’ εἶναι ἀτελῆ” τούτων οἷς ὁ δῆμος ἔδωκεν; σαφῶς γ’ οὑτωσί. ἀλλ’ οὐκ ἐν ᾧ νῦν ὅδ’ ἀντεισφέρει νόμῳ, ἀλλ’ ἅ τ’ ἐδώκατε, κύρια, καὶ πρόφασις δικαία κατὰ τῶν ἢ παρακρουσαμένων ἢ μετὰ ταῦτ’ ἀδικούντων ἢ ὅλως ἀναξίων, δι’ ἣν ὃν ἂν ὑμῖν δοκῇ κωλύσετ’ ἔχειν τὴν δωρειάν. λέγε τὸν νόμον.", "st": "20.97"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "20.97"}, {"sp": "N", "t": "ἀκούετ’, ὦ ἄνδρες Ἀθηναῖοι, καὶ καταμανθάνετε, ὅτι ἐνταῦθ’ ἔνι καὶ τοὺς ἀξίους ἔχειν τὰ δοθέντα καὶ τοὺς μὴ τοιούτους κριθέντας, ἐὰν ἀδίκως τι λάβωσιν, ἀφαιρεθῆναι, καὶ τὸ λοιπὸν ἐφ’ ὑμῖν εἶναι πάνθ’, ὥσπερ ἐστὶ δίκαιον, καὶ δοῦναι καὶ μή. ὡς μὲν τοίνυν οὐχὶ καλῶς οὗτος ἔχει καὶ δικαίως ὁ νόμος, οὔτ’ ἐρεῖν οἴομαι Λεπτίνην οὔτ’, ἐὰν λέγῃ, δεῖξαι δυνήσεσθαι· ἃ δὲ πρὸς τοῖς θεσμοθέταις ἔλεγεν, ταῦτ’ ἴσως λέγων παράγειν ὑμᾶς ζητήσει. ἔφη γὰρ ἐξαπάτης εἵνεκα παραγεγράφθαι τοῦτον τὸν νόμον, ἐὰν δ’ ὃν αὐτὸς ἔθηκεν λυθῇ, τοῦτον οὐ τεθήσεσθαι.", "st": "20.98"}, {"sp": "N", "t": "ἐγὼ δ’, ὅτι μὲν τῇ ὑμετέρᾳ ψήφῳ τοῦ τούτου νόμου λυθέντος τὸν παρεισενεχθέντα κύριον εἶναι σαφῶς ὁ παλαιὸς κελεύει νόμος, καθ’ ὃν οἱ θεσμοθέται τοῦτον ὑμῖν παρέγραψαν, ἐάσω, ἵνα μὴ περὶ τούτου τις ἀντιλέγῃ μοι, ἀλλ’ ἐπ’ ἐκεῖν’ εἶμι. ὅταν ταῦτα λέγῃ δήπου, ὁμολογεῖ μὲν εἶναι βελτίω καὶ δικαιότερον τόνδε τὸν νόμον οὗ τέθεικεν αὐτός, ὑπὲρ δὲ τοῦ πῶς τεθήσεται ποιεῖται τὸν λόγον.", "st": "20.99"}, {"sp": "N", "t": "πρῶτον μὲν τοίνυν εἰσὶν αὐτῷ κατὰ τοῦ παρεισφέροντος πολλοὶ τρόποι, δι’ ὧν, ἂν βούληται, θεῖναι τὸν νόμον αὐτὸν ἀναγκάσει. ἔπειτ’ ἐγγυώμεθ’ ἡμεῖς, ἐγώ, Φορμίων, ἄλλον εἴ τινα βούλεται, θήσειν τὸν νόμον. ἔστι δὲ δήπου νόμος ὑμῖν, ἐάν τις ὑποσχόμενός τι τὸν δῆμον ἢ τὴν βουλὴν ἢ δικαστήριον ἐξαπατήσῃ, τὰ ἔσχατα πάσχειν. ἐγγυώμεθα, ὑπισχνούμεθα· οἱ θεσμοθέται ταῦτα γραφόντων, ἐπὶ τούτοις τὸ πρᾶγμα γιγνέσθω.", "st": "20.100"}, {"sp": "N", "t": "μήθ’ ὑμεῖς ποιήσητε μηδὲν ἀνάξιον ὑμῶν αὐτῶν, μήτε, εἴ τις φαῦλός ἐστι τῶν εὑρημένων τὴν δωρειάν, ἐχέτω, ἀλλ’ ἰδίᾳ κατὰ τόνδε κριθήτω τὸν νόμον. εἰ δὲ ταῦτα λόγους καὶ φλυαρίας εἶναι φήσει, ἐκεῖνό γ’ οὐ λόγος· αὐτὸς θέτω, καὶ μὴ λεγέτω τοῦθ’, ὡς οὐ θήσομεν ἡμεῖς. κάλλιον δὲ δήπου τὸν ὑφ’ ὑμῶν κριθέντα καλῶς ἔχειν νόμον εἰσφέρειν ἢ ὃν νῦν ἀφ’ αὑτοῦ τίθησιν.", "st": "20.101"}, {"sp": "N", "t": "ἐμοὶ δ’, ὦ ἄνδρες Ἀθηναῖοι, δοκεῖ Λεπτίνης (καί μοι μηδὲν ὀργισθῇς· οὐδὲν γὰρ φλαῦρον ἐρῶ σε) ἢ οὐκ ἀνεγνωκέναι τοὺς Σόλωνος νόμους ἢ οὐ συνιέναι. εἰ γὰρ ὁ μὲν Σόλων ἔθηκεν νόμον ἐξεῖναι δοῦναι τὰ ἑαυτοῦ ᾧ ἄν τις βούληται, ἐὰν μὴ παῖδες ὦσι γνήσιοι, οὐχ ἵν’ ἀποστερήσῃ τοὺς ἐγγυτάτω γένει τῆς ἀγχιστείας, ἀλλ’ ἵν’ εἰς τὸ μέσον καταθεὶς τὴν ὠφέλειαν ἐφάμιλλον ποιήσῃ τὸ ποιεῖν ἀλλήλους εὖ,", "st": "20.102"}, {"sp": "N", "t": "σὺ δὲ τοὐναντίον εἰσενήνοχας μὴ ἐξεῖναι τῷ δήμῳ τῶν αὑτοῦ δοῦναι μηδενὶ μηδέν, πῶς σέ τις φήσει τοὺς Σόλωνος ἀνεγνωκέναι νόμους ἢ συνιέναι; ὃς ἔρημον ποιεῖς τὸν δῆμον τῶν φιλοτιμησομένων, προλέγων καὶ δεικνὺς ὅτι τοῖς ἀγαθόν τι ποιοῦσιν οὐδ’ ὁτιοῦν ἔσται πλέον.", "st": "20.103"}, {"sp": "N", "t": "καὶ μὴν κἀκεῖνος τῶν καλῶς δοκούντων ἔχειν νόμων Σόλωνός ἐστι, μὴ λέγειν κακῶς τὸν τεθνεῶτα, μηδ’ ἂν ὑπὸ τῶν ἐκείνου τις ἀκούῃ παίδων αὐτός· σὺ δὲ ποιεῖς, οὐ λέγεις κακῶς τοὺς τετελευτηκότας τῶν εὐεργετῶν, τῷ δεῖνι μεμφόμενος καὶ τὸν δεῖν’ ἀνάξιον εἶναι φάσκων, ὧν οὐδὲν ἐκείνοις προσῆκεν. ἆρ’ οὐ πολὺ τοῦ Σόλωνος ἀποστατεῖς τῇ γνώμῃ;", "st": "20.104"}, {"sp": "N", "t": "πάνυ τοίνυν σπουδῇ τις ἀπήγγελλέ μοι περὶ τοῦ μηδενὶ δεῖν μηδὲν διδόναι, μηδ’ ἂν ὁτιοῦν πράξῃ, τοιοῦτόν τι λέγειν αὐτοὺς παρεσκευάσθαι, ὡς ἄρ’ οἱ Λακεδαιμόνιοι καλῶς πολιτευόμενοι καὶ Θηβαῖοι οὐδενὶ τῶν παρ’ ἑαυτοῖς διδόασι τοιαύτην οὐδεμίαν τιμήν· καίτοι καὶ παρ’ ἐκείνοις τινές εἰσιν ἴσως ἀγαθοί. ἐμοὶ δὲ δοκοῦσιν, ὦ ἄνδρες Ἀθηναῖοι, πάντες οἱ τοιοῦτοι λόγοι παροξυντικοὶ μὲν εἶναι πρὸς τὸ τὰς ἀτελείας ὑμᾶς ἀφελέσθαι πεῖσαι, οὐ μέντοι δίκαιοί γ’ οὐδαμῇ. οὐ γὰρ ἀγνοῶ τοῦθ’ ὅτι Θηβαῖοι καὶ Λακεδαιμόνιοι καὶ ἡμεῖς οὔτε νόμοις οὔτ’ ἔθεσιν χρώμεθα τοῖς αὐτοῖς οὔτε πολιτείᾳ.", "st": "20.105"}, {"sp": "N", "t": "αὐτὸ γὰρ τοῦτο πρῶτον, ὃ νῦν οὗτοι ποιήσουσιν, ἐὰν ταῦτα λέγωσιν, οὐκ ἔξεστι ποιεῖν παρὰ τοῖς Λακεδαιμονίοις, τὰ τῶν Ἀθηναίων ἐπαινεῖν νόμιμα οὐδὲ τὰ τῶν δείνων, πολλοῦ γε καὶ δεῖ, ἀλλ’ ἃ τῇ παρ’ ἐκείνοις πολιτείᾳ συμφέρει, ταῦτ’ ἐπαινεῖν ἀνάγκη [καὶ ποιεῖν]. εἶτα καὶ Λακεδαιμόνιοι τῶν μὲν τοιούτων ἀφεστᾶσιν, ἄλλαι δέ τινες παρ’ ἐκείνοις εἰσὶ τιμαί, ἃς ἀπεύξαιτ’ ἂν ἅπας ὁ δῆμος ἐνταυθοῖ γενέσθαι.", "st": "20.106"}, {"sp": "N", "t": "τίνες οὖν εἰσιν αὗται; τὰς μὲν καθ’ ἕκαστον ἐάσω, μίαν δ’ ἣ συλλαβοῦσα τὰς ἄλλας ἔχει, δίειμι. ἐπειδάν τις εἰς τὴν καλουμένην γερουσίαν ἐγκριθῇ παρασχὼν αὑτὸν οἷον χρή, δεσπότης ἐστὶ τῶν πολλῶν. ἐκεῖ μὲν γάρ ἐστι τῆς ἀρετῆς ἆθλον τῆς πολιτείας κυρίῳ γενέσθαι μετὰ τῶν ὁμοίων, παρὰ δ’ ἡμῖν ταύτης μὲν ὁ δῆμος κύριος, καὶ ἀραὶ καὶ νόμοι καὶ φυλακαὶ ὅπως μηδεὶς ἄλλος κύριος γενήσεται, στέφανοι δὲ καὶ ἀτέλειαι καὶ σιτήσεις καὶ τοιαῦτ’ ἐστίν, ὧν ἄν τις ἀνὴρ ἀγαθὸς ὢν τύχοι.", "st": "20.107"}, {"sp": "N", "t": "καὶ ταῦτ’ ἀμφότερ’ ὀρθῶς ἔχει, καὶ τἀκεῖ καὶ τὰ παρ’ ἡμῖν. διὰ τί; ὅτι τὰς μὲν διὰ τῶν ὀλίγων πολιτείας τὸ πάντας ἔχειν ἴσον ἀλλήλοις τοὺς τῶν κοινῶν κυρίους ὁμονοεῖν ποιεῖ, τὴν δὲ τῶν δήμων ἐλευθερίαν ἡ τῶν ἀγαθῶν ἀνδρῶν ἅμιλλα, ἣν ἐπὶ ταῖς παρὰ τοῦ δήμου δωρειαῖς πρὸς αὑτοὺς ποιοῦνται, φυλάττει.", "st": "20.108"}, {"sp": "N", "t": "καὶ μὴν περὶ τοῦ γε μηδὲ Θηβαίους μηδένα τιμᾶν, ἐκεῖν’ ἂν ἔχειν εἰπεῖν ἀληθὲς οἴομαι. μεῖζον, ὦ ἄνδρες Ἀθηναῖοι, Θηβαῖοι φρονοῦσιν ἐπ’ ὠμότητι καὶ πονηρίᾳ ἢ ὑμεῖς ἐπὶ φιλανθρωπίᾳ καὶ τῷ τὰ δίκαια βούλεσθαι. μήτ’ οὖν ἐκεῖνοί ποτε παύσαιντο, εἰ ἄρ’ εὔξασθαι δεῖ, τοὺς μὲν ἑαυτοὺς ἀγαθόν τι ποιοῦντας μήτε τιμῶντες μήτε θαυμάζοντες, τοὺς δὲ συγγενεῖς (ἴστε γὰρ ὃν τρόπον Ὀρχομενὸν διέθηκαν) οὕτω μεταχειριζόμενοι, μήθ’ ὑμεῖς τἀναντία τούτοις τοὺς μὲν εὐεργέτας τιμῶντες, παρὰ δὲ τῶν πολιτῶν λόγῳ μετὰ τῶν νόμων τὰ δίκαια λαμβάνοντες.", "st": "20.109"}, {"sp": "N", "t": "ὅλως δ’ οἶμαι τότε δεῖν τοὺς ἑτέρων ἐπαινεῖν τρόπους καὶ ἔθη τοῖς ὑμετέροις ἐπιτιμῶντας, ὅταν ᾖ δεῖξαι βέλτιον ἐκείνους πράττοντας ὑμῶν. ὅτε δ’ ὑμεῖς, καλῶς ποιοῦντες, καὶ κατὰ τὰς κοινὰς πράξεις καὶ κατὰ τὴν ὁμόνοιαν καὶ κατὰ τἄλλα πάντ’ ἄμεινον ἐκείνων πράττετε, τοῦ χάριν ἂν τῶν ὑμετέρων αὐτῶν ἐθῶν ὀλιγωροῦντες ἐκεῖνα διώκοιτε; εἰ γὰρ καὶ κατὰ τὸν λογισμὸν ἐκεῖνα φανείη βελτίω, τῆς γε τύχης ἕνεχ’ ᾗ παρὰ ταῦτ’ ἀγαθῇ κέχρησθε, ἐπὶ τούτων ἄξιον μεῖναι.", "st": "20.110"}, {"sp": "N", "t": "εἰ δὲ δεῖ παρὰ πάντα ταῦτ’ εἰπεῖν ὃ δίκαιον ἡγοῦμαι, ἐκεῖν’ ἂν ἔγωγ’ εἴποιμι. οὐκ ἔστι δίκαιον, ὦ ἄνδρες Ἀθηναῖοι, τοὺς Λακεδαιμονίων νόμους οὐδὲ τοὺς Θηβαίων λέγειν ἐπὶ τῷ τοὺς ἐνθάδε λυμαίνεσθαι, οὐδὲ δι’ ὧν μὲν ἐκεῖνοι μεγάλοι [τῆς ὀλιγαρχίας καὶ δεσποτείας εἰσί], κἂν ἀποκτεῖναι βούλεσθαι τὸν παρ’ ἡμῖν τούτων τι κατασκευάσαντα, διὰ δ’ ὧν ὁ παρ’ ἡμῖν δῆμος εὐδαίμων, ταῦθ’ ὡς ἀνελεῖν δεῖ λεγόντων τινῶν ἐθέλειν ἀκούειν.", "st": "20.111"}, {"sp": "N", "t": "ἔστι τοίνυν τις πρόχειρος λόγος, ὡς ἄρα καὶ παρ’ ἡμῖν ἐπὶ τῶν προγόνων πόλλ’ ἀγάθ’ εἰργασμένοι τινὲς οὐδενὸς ἠξιοῦντο τοιούτου, ἀλλ’ ἀγαπητῶς ἐπιγράμματος ἐν τοῖς Ἑρμαῖς ἔτυχον· καὶ ἴσως τοῦθ’ ὑμῖν ἀναγνώσεται τοὐπίγραμμα. ἐγὼ δ’ ἡγοῦμαι τοῦτον τὸν λόγον, ὦ ἄνδρες Ἀθηναῖοι, κατὰ πόλλ’ ἀσύμφορον εἶναι τῇ πόλει λέγεσθαι, πρὸς δὲ καὶ οὐδὲ δίκαιον.", "st": "20.112"}, {"sp": "N", "t": "εἰ μὲν γὰρ ἀναξίους εἶναί τις φήσει κἀκείνους τιμᾶσθαι, τίς ἄξιος, εἰπάτω, εἰ μήτε τῶν προτέρων μηδεὶς μήτε τῶν ὑστέρων· εἰ δὲ μηδένα φήσει, συναχθεσθείην ἂν ἔγωγε τῇ πόλει, εἰ μηδεὶς ἐν ἅπαντι τῷ χρόνῳ γέγον’ ἄξιος εὖ παθεῖν. καὶ μὴν εἴ γ’ ὁμολογῶν ἐκείνους εἶναι σπουδαίους μὴ τετυχηκότας δείξει μηδενός, τῆς πόλεως ὡς ἀχαρίστου δήπου κατηγορεῖ. ἔστι δ’ οὐχ οὕτω ταῦτ’ ἔχοντα, οὐδ’ ὀλίγου δεῖ· ἀλλ’ ἐπειδάν τις οἶμαι κακουργῶν ἐπὶ μὴ προσήκοντα πράγματα τοὺς λόγους μεταφέρῃ, δυσχερεῖς ἀνάγκη φαίνεσθαι.", "st": "20.113"}, {"sp": "N", "t": "ὡς δὲ τἀληθές τ’ ἔχει καὶ δίκαιόν ἐστι λέγειν, ἐγὼ πρὸς ὑμᾶς ἐρῶ. ἦσαν, ὦ ἄνδρες Ἀθηναῖοι, πολλοὶ τῶν πρότερον σπουδαῖοι, καὶ ἡ πόλις ἡμῶν ἐτίμα καὶ τότε τοὺς ἀγαθούς· αἱ μέντοι τιμαὶ καὶ τἄλλα πάντα τὰ μὲν τότ’ ἦν ἐπὶ τοῖς τότ’ ἔθεσιν, τὰ δὲ νῦν ἐπὶ τοῖς νῦν. πρὸς οὖν τί τοῦτο λέγω; ὅτι φήσαιμ’ ἂν ἔγωγ’ ἐκείνους οὐκ ἔσθ’ ὅτου παρὰ τῆς πόλεως οὐ τυχεῖν ὧν ἐβουλήθησαν.", "st": "20.114"}, {"sp": "N", "t": "τίνι χρώμενος τεκμηρίῳ; ὅτι Λυσιμάχῳ δωρειάν, ἑνὶ τῶν τότε χρησίμων, ἑκατὸν μὲν ἐν Εὐβοίᾳ πλέθρα γῆς πεφυτευμένης ἔδοσαν, ἑκατὸν δὲ ψιλῆς, ἔτι δ’ ἀργυρίου μνᾶς ἑκατόν, καὶ τέτταρας τῆς ἡμέρας δραχμάς. καὶ τούτων ψήφισμ’ ἔστιν Ἀλκιβιάδου, ἐν ᾧ ταῦτα γέγραπται. τότε μὲν γὰρ ἡ πόλις ἡμῶν καὶ γῆς ηὐπόρει καὶ χρημάτων, νῦν δ’ εὐπορήσει· δεῖ γὰρ οὕτω λέγειν καὶ μὴ βλασφημεῖν. καίτοι τίν’ οὐκ ἂν οἴεσθε νῦν τὸ τρίτον μέρος τούτων ἀντὶ τῆς ἀτελείας ἑλέσθαι; ὅτι τοίνυν ἀληθῆ λέγω, λαβέ μοι τὸ ψήφισμα τουτί.", "st": "20.115"}, {"sp": "N", "t": "ΨΗΦΙΣΜΑ.", "st": "20.115"}, {"sp": "N", "t": "ὅτι μὲν τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, καὶ τοῖς προγόνοις ὑμῶν ἔθος ἦν τοὺς χρηστοὺς τιμᾶν, δηλοῖ τὸ ψήφισμα τουτί· εἰ δὲ μὴ τοῖς αὐτοῖς οἷσπερ ἡμεῖς νῦν, ἕτερόν τι τοῦτ’ ἂν εἴη. εἰ τοίνυν μήτε Λυσίμαχον μήτ’ ἄλλον μηδένα μηδὲν εὑρῆσθαι παρὰ τῶν προγόνων ἡμῶν συγχωρήσαιμεν, τί μᾶλλον, οἷς ἔδομεν νῦν ἡμεῖς, διὰ τοῦτο δικαίως ἂν ἀφαιρεθεῖεν;", "st": "20.116"}, {"sp": "N", "t": "οὐ γὰρ οἱ μὴ δόντες ἃ μὴ ’δόκει δεινόν εἰσιν οὐδὲν εἰργασμένοι, ἀλλ’ οἱ δόντες μέν, πάλιν δ’ ὕστερον μηδὲν ἐγκαλοῦντες ἀφαιρούμενοι. εἰ μὲν γάρ τις ἔχει δεῖξαι κἀκείνους ὧν ἔδοσάν τῴ τι, τοῦτ’ ἀφῃρημένους, συγχωρῶ καὶ ὑμᾶς ταὐτὸ τοῦτο ποιῆσαι, καίτοι τοῦτό γ’ αἰσχρὸν ὁμοίως· εἰ δὲ μηδ’ ἂν εἷς ἐν ἅπαντι τῷ χρόνῳ τοῦτ’ ἔχοι δεῖξαι γεγονός, τίνος εἵνεκ’ ἐφ’ ἡμῶν πρώτων καταδειχθῇ τοιοῦτον ἔργον;", "st": "20.117"}, {"sp": "N", "t": "χρὴ τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, κἀκεῖν’ ἐνθυμεῖσθαι καὶ ὁρᾶν, ὅτι νῦν ὀμωμοκότες κατὰ τοὺς νόμους δικάσειν ἥκετε, οὐχὶ τοὺς Λακεδαιμονίων οὐδὲ Θηβαίων, οὐδ’ οἷς ποτ’ ἐχρήσανθ’ οἱ πρῶτοι τῶν προγόνων, ἀλλὰ καθ’ οὓς ἔλαβον τὰς ἀτελείας οὓς ἀφαιρεῖται νῦν οὗτος τῷ νόμῳ, καὶ περὶ ὧν ἂν νόμοι μὴ ὦσι, γνώμῃ τῇ δικαιοτάτῃ κρινεῖν. καλῶς. τὸ τοίνυν τῆς γνώμης πρὸς ἅπαντ’ ἀνενέγκατε τὸν νόμον.", "st": "20.118"}, {"sp": "N", "t": "ἆρ’ οὖν δίκαιον, ὦ ἄνδρες Ἀθηναῖοι, τοὺς εὐεργέτας τιμᾶν; δίκαιον. τί δέ; ὅσ’ ἂν δῷ τις ἅπαξ, δίκαιον ἔχειν ἐᾶν; δίκαιον. ταῦτα τοίνυν αὐτοί τε ποιεῖτε, ἵν’ εὐορκῆτε, καὶ τοὺς προγόνους ὀργίζεσθ’ ἂν μή τις φῇ ποιεῖν, καὶ τοὺς τὰ τοιαῦτα λέγοντας παραδείγματα, ὡς ἄρ’ ἐκεῖνοι μεγάλ’ εὖ παθόντες οὐδέν’ ἐτίμησαν, καὶ πονηροὺς καὶ ἀπαιδεύτους ἡγεῖσθ’ εἶναι, πονηροὺς μὲν διότι καταψεύδονται τῶν προγόνων ὑμῶν ὡς ἀχαρίστων, ἀμαθεῖς δὲ διότι ἐκεῖν’ ἀγνοοῦσιν, ὅτι εἰ τὰ μάλιστα ταῦθ’ οὕτως εἶχεν, ἀρνεῖσθαι μᾶλλον ἢ λέγειν αὐτοῖς προσῆκεν.", "st": "20.119"}, {"sp": "N", "t": "οἴομαι τοίνυν καὶ τοῦτον τὸν λόγον Λεπτίνην ἐρεῖν, ὡς τὰς εἰκόνας καὶ τὴν σίτησιν οὐκ ἀφαιρεῖται τῶν εἰληφότων ὁ νόμος, οὐδὲ τῆς πόλεως τὸ τιμᾶν τοὺς ὄντας ἀξίους, ἀλλ’ ἔσται χαλκοῦς ἱστάναι καὶ σίτησιν διδόναι καὶ ἄλλ’ ὅ τι ἂν βούλησθε, πλὴν τούτου. ἐγὼ δ’ ὑπὲρ ὧν μὲν τῇ πόλει καταλείπειν φήσει, τοσοῦτο λέγω· ὅταν ὧν ἐδώκατέ τῳ πρότερόν τι, τοῦτ’ ἀφέλησθε, καὶ τὰς ὑπολοίπους ἀπίστους ποιήσετε πάσας δωρειάς. τί γὰρ ἔσται πιστότερον τὸ τῆς εἰκόνος ἢ τῆς σιτήσεως ἢ τὸ τῆς ἀτελείας, ἣν πρότερόν τισι δόντες ἀφῃρημένοι φανεῖσθε;", "st": "20.120"}, {"sp": "N", "t": "ἔτι δ’ εἰ μηδὲν ἔμελλε τοῦτ’ ἔσεσθαι δυσχερές, οὐδ’ ἐκεῖνο καλῶς ἔχειν ἡγοῦμαι, εἰς τοιαύτην ἄγειν ἀνάγκην τὴν πόλιν δι’ ἧς ἅπαντας ἐξ ἴσου τῶν αὐτῶν ἀξιώσει τοῖς τὰ μέγιστ’ εὐεργετοῦσιν, ἢ μὴ τοῦτο ποιοῦσα χάριν τισὶν οὐκ ἀποδώσει. μεγάλων μὲν οὖν εὐεργεσιῶν οὔθ’ ὑμῖν συμφέρει συμβαίνειν πολλάκις καιρόν, οὔτ’ ἴσως ῥᾴδιον αἰτίῳ γενέσθαι·", "st": "20.121"}, {"sp": "N", "t": "μετρίων δὲ καὶ ὧν ἂν ἐν εἰρήνῃ τις καὶ πολιτείᾳ δύναιτ’ ἐφικέσθαι, εὐνοίας, δικαιοσύνης, ἐπιμελείας, τῶν τοιούτων, καὶ συμφέρειν ἔμοιγε δοκεῖ καὶ χρῆναι διδόναι τὰς τιμάς. δεῖ τοίνυν μεμερίσθαι καὶ τὰ τῶν δωρειῶν, ἵν’ ἧς ἂν ἄξιος ὢν ἕκαστος φαίνηται, ταύτην παρὰ τοῦ δήμου λαμβάνῃ τὴν δωρειάν.", "st": "20.122"}, {"sp": "N", "t": "ἀλλὰ μὴν ὑπὲρ ὧν γε τοῖς εὑρημένοις τὰς τιμὰς καταλείπειν φήσει, οἱ μὲν ἁπλᾶ πάνυ καὶ δίκαι’ ἂν εἴποιεν, πάνθ’ ὅσα τῶν αὐτῶν ἕνεκ’ αὐτοῖς ἔδοτ’ εὐεργεσιῶν ἀξιοῦντες ἔχειν, οἱ δὲ φενακίζειν τὸν ὡς καταλείπεται λέγοντά τι αὐτοῖς. ὁ γὰρ ἄξια τῆς ἀτελείας εὖ πεποιηκέναι δόξας καὶ ταύτην παρ’ ὑμῶν λαβὼν τὴν τιμὴν μόνην, ἢ ξένος ἢ καί τις πολίτης, ἐπειδὰν ἀφαιρεθῇ ταύτην, τίν’ ἔχει λοιπὴν δωρειάν, Λεπτίνη; οὐδεμίαν δήπου. μὴ τοίνυν διὰ μὲν τοῦ τῶνδε κατηγορεῖν ὡς φαύλων ἐκείνους ἀφαιροῦ, δι’ ἃ δ’ αὖ καταλείπειν ἐκείνοις φήσεις, τούσδ’ ὃ μόνον λαβόντες ἔχουσι, τοῦτ’ ἀφέλῃ.", "st": "20.123"}, {"sp": "N", "t": "ὡς δ’ ἁπλῶς εἰπεῖν, οὐκ, εἰ τῶν πάντων ἀδικήσομέν τιν’ ἢ μείζον’ ἢ ἐλάττονα, δεινόν ἐστιν, ἀλλ’ εἰ τὰς τιμάς, αἷς ἂν ἀντ’ εὖ ποιήσωμέν τινας, ἀπίστους καταστήσομεν· οὐδ’ ὁ πλεῖστος ἔμοιγε λόγος περὶ τῆς ἀτελείας ἐστίν, ἀλλ’ ὑπὲρ τοῦ πονηρὸν ἔθος τὸν νόμον εἰσάγειν καὶ τοιοῦτον δι’ οὗ πάντ’ ἄπισθ’ ὅσ’ ὁ δῆμος δίδωσιν ἔσται.", "st": "20.124"}, {"sp": "N", "t": "ὃν τοίνυν κακουργότατον οἴονται λόγον εὑρηκέναι πρὸς τὸ τὰς ἀτελείας ὑμᾶς ἀφελέσθαι πεῖσαι, βέλτιόν ἐστι προειπεῖν, ἵνα μὴ λάθητ’ ἐξαπατηθέντες. ἐροῦσ’ ὅτι ταῦθ’ ἱερῶν ἐστιν ἅπαντα τἀναλώματα [αἱ χορηγίαι καὶ αἱ γυμνασιαρχίαι]· δεινὸν οὖν, εἰ τῶν ἱερῶν ἀτελής τις ἀφεθήσεται. ἐγὼ δὲ τὸ μέν τινας, οἷς ὁ δῆμος ἔδωκεν, ἀτελεῖς εἶναι τούτων δίκαιον ἡγοῦμαι, ὃ δὲ νῦν οὗτοι ποιήσουσιν, ἐὰν ἄρα ταῦτα λέγωσι, τοῦτ’ εἶναι δεινὸν νομίζω.", "st": "20.125"}, {"sp": "N", "t": "εἰ γὰρ ἃ [κατὰ] μηδέν’ ἄλλον ἔχουσι τρόπον δεῖξαι δίκαιον ὑμᾶς ἀφελέσθαι, ταῦτ’ ἐπὶ τῷ τῶν θεῶν ὀνόματι ποιεῖν ζητήσουσιν, πῶς οὐκ ἀσεβέστατον ἔργον καὶ δεινότατον πράξουσιν; χρὴ γάρ, ὡς γοῦν ἐμοὶ δοκεῖ, ὅσα τις πράττει τοὺς θεοὺς ἐπιφημίζων, τοιαῦτα φαίνεσθαι οἷα μηδ’ ἂν ἐπ’ ἀνθρώπου πραχθέντα πονηρὰ φανείη. ὅτι δ’ οὐκ ἔστι ταὐτὸν ἱερῶν ἀτέλειαν ἔχειν καὶ λῃτουργιῶν, ἀλλ’ οὗτοι τὸ τῶν λῃτουργιῶν ὄνομ’ ἐπὶ τὸ τῶν ἱερῶν μεταφέροντες ἐξαπατᾶν ζητοῦσι, Λεπτίνην ὑμῖν αὐτὸν ἐγὼ παρασχήσομαι μάρτυρα.", "st": "20.126"}, {"sp": "N", "t": "γράφων γὰρ ἀρχὴν τοῦ νόμου “Λεπτίνης εἶπεν” φησίν, “ὅπως ἂν οἱ πλουσιώτατοι λῃτουργῶσιν, ἀτελῆ μηδέν’ εἶναι πλὴν τῶν ἀφ’ Ἁρμοδίου καὶ Ἀριστογείτονος.” καίτοι εἰ ἦν ἱερῶν ἀτέλειαν ἔχειν ταὐτὸ καὶ λῃτουργιῶν, τί τοῦτο μαθὼν προσέγραψεν; οὐδὲ γὰρ τούτοις ἀτέλεια τῶν γ’ ἱερῶν ἐστιν δεδομένη. ἵνα δ’ εἰδῆθ’ ὅτι ταῦτα τοῦτον ἔχει τὸν τρόπον, λαβέ μοι πρῶτον μὲν τῆς στήλης τἀντίγραφα, εἶτα τὴν ἀρχὴν τοῦ νόμου τοῦ Λεπτίνου. λέγε.", "st": "20.127"}, {"sp": "N", "t": "ΑΝΤΙΓΡΑΦΑ ΣΤΗΛΗΣ.", "st": "20.127"}, {"sp": "N", "t": "ἀκούετε τῶν ἀντιγράφων τῆς στήλης, ὦ ἄνδρες Ἀθηναῖοι, ἀτελεῖς αὐτοὺς εἶναι κελευόντων πλὴν ἱερῶν. λέγε δὴ τὴν ἀρχὴν τοῦ νόμου τοῦ Λεπτίνου.", "st": "20.128"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "20.128"}, {"sp": "N", "t": "καλῶς· κατάθες. γράψας “ὅπως ἂν οἱ πλουσιώτατοι λῃτουργῶσι,” “μηδέν’ εἶναι” προσέγραψεν “ἀτελῆ πλὴν τῶν ἀφ’ Ἁρμοδίου καὶ Ἀριστογείτονος.” τίνος ἕνεκα, εἴ γε τὸ τῶν ἱερῶν τέλος ἐστὶ λῃτουργεῖν; αὐτὸς γὰρ οὑτωσὶ τἀναντία τῇ στήλῃ γεγραφώς, ἂν τοῦτο λέγῃ, φανήσεται.", "st": "20.128"}, {"sp": "N", "t": "ἡδέως δ’ ἂν ἔγωγ’ ἐροίμην Λεπτίνην· τίνος αὐτοῖς τὴν ἀτέλειαν ἢ σὺ νῦν καταλείπειν φήσεις ἢ ἐκείνους τότε δοῦναι, τὰς λῃτουργίας ὅταν εἶναι φῇς ἱερῶν; τῶν μὲν γὰρ εἰς τὸν πόλεμον πασῶν εἰσφορῶν καὶ τριηραρχιῶν ἐκ τῶν παλαιῶν νόμων οὐκ εἴσ’ ἀτελεῖς· τῶν δὲ λῃτουργιῶν, εἴπερ εἴσ’ ἱερῶν, οὐδ’ ἔχουσιν.", "st": "20.129"}, {"sp": "N", "t": "ἀλλὰ μὴν γέγραπταί γ’ ἀτελεῖς αὐτοὺς εἶναι. τίνος; ἢ τοῦ μετοικίου; τοῦτο γὰρ λοιπόν. οὐ δήπου, ἀλλὰ τῶν ἐγκυκλίων λῃτουργιῶν, ὡς ἥ τε στήλη δηλοῖ καὶ σὺ προσδιώρισας ἐν τῷ νόμῳ καὶ μαρτυρεῖ πᾶς ὁ πρὸ τοῦ χρόνος γεγονώς, ἐν ᾧ τοσούτῳ τὸ πλῆθος ὄντι οὔτε φυλὴ πώποτ’ ἐνεγκεῖν ἐτόλμησεν οὐδεμί’ οὐδένα τῶν ἀπ’ ἐκείνων χορηγόν, οὔτ’ ἐνεχθεὶς αὐτοῖς ἄλλος οὐδεὶς ἀντιδοῦναι. οἷς οὐκ ἀκουστέον ἂν ἐναντία τολμᾷ λέγειν.", "st": "20.130"}, {"sp": "N", "t": "ἔτι τοίνυν ἴσως ἐπισύροντες ἐροῦσιν ὡς Μεγαρεῖς καὶ Μεσσήνιοί τινες εἶναι φάσκοντες, ἔπειτ’ ἀτελεῖς εἰσιν, ἁθρόοι παμπληθεῖς ἄνθρωποι, καί τινες ἄλλοι δοῦλοι καὶ μαστιγίαι, Λυκίδας καὶ Διονύσιος, καὶ τοιούτους τινὰς ἐξειλεγμένοι. ὑπὲρ δὴ τούτων ὡδὶ ποιήσαθ’ ὅταν ταῦτα λέγωσι· κελεύετ’, εἴπερ ἀληθῆ λέγουσι πρὸς ὑμᾶς, τὰ ψηφίσματ’ ἐν οἷς ἀτελεῖς εἰσιν οὗτοι δεῖξαι. οὐ γάρ ἐστ’ οὐδεὶς ἀτελὴς παρ’ ὑμῖν ὅτῳ μὴ ψήφισμ’ ἢ νόμος δέδωκε τὴν ἀτέλειαν.", "st": "20.131"}, {"sp": "N", "t": "πρόξενοι μέντοι πολλοὶ διὰ τῶν πολιτευομένων γεγόνασι παρ’ ὑμῖν τοιοῦτοι, ὧν εἷς ἐστιν ὁ Λυκίδας. ἀλλ’ ἕτερον πρόξενόν ἐστ’ εἶναι καὶ ἀτέλειαν εὑρῆσθαι. μὴ δὴ παραγόντων ὑμᾶς, μηδ’, ὅτι δοῦλος ὢν ὁ Λυκίδας καὶ Διονύσιος καί τις ἴσως ἄλλος διὰ τοὺς μισθοῦ τὰ τοιαῦτα γράφοντας ἑτοίμως πρόξενοι γεγόνασι, διὰ τοῦθ’ ἑτέρους ἀξίους καὶ ἐλευθέρους καὶ πολλῶν ἀγαθῶν αἰτίους, ἃς ἔλαβον δικαίως παρ’ ὑμῶν δωρειὰς ἀφελέσθαι ζητούντων.", "st": "20.132"}, {"sp": "N", "t": "πῶς γὰρ οὐχὶ καὶ κατὰ τοῦτο δεινότατ’ ἂν πεπονθὼς ὁ Χαβρίας φανείη, εἰ μὴ μόνον ἐξαρκέσει τοῖς τὰ τοιαῦτα πολιτευομένοις τὸν ἐκείνου δοῦλον Λυκίδαν πρόξενον ὑμέτερον πεποιηκέναι, ἀλλ’ εἰ διὰ τοῦτον πάλιν καὶ τῶν ἐκείνῳ τι δοθέντων ἀφέλοιντο, καὶ ταῦτ’ αἰτίαν λέγοντες ψευδῆ; οὐ γάρ ἐστιν οὔθ’ οὗτος οὔτ’ ἄλλος οὐδεὶς πρόξενος ὢν ἀτελής, ὅτῳ μὴ διαρρήδην ἀτέλειαν ἔδωκεν ὁ δῆμος. τούτοις δ’ οὐ δέδωκεν, οὐδ’ ἕξουσιν οὗτοι δεικνύναι, λόγῳ δ’ ἂν ἀναισχυντῶσιν, οὐχὶ καλῶς ποιήσουσιν.", "st": "20.133"}, {"sp": "N", "t": "ὃ τοίνυν μάλιστα πάντων οἶμαι δεῖν ὑμᾶς, ὦ ἄνδρες Ἀθηναῖοι, φυλάξασθαι, τοῦτ’ εἰπεῖν ἔτι βούλομαι. εἰ γάρ τις πάνθ’ ὅσα Λεπτίνης ἐρεῖ περὶ τοῦ νόμου διδάσκων ὑμᾶς ὡς καλῶς κεῖται, συγχωρήσειεν ἀληθῆ λέγειν αὐτόν, ἕν γ’ αἰσχρὸν οὐδ’ ἂν εἴ τι γένοιτ’ ἀναιρεθείη, ὃ συμβήσεται διὰ τοῦ νόμου κυρίου γενομένου τῇ πόλει. τί οὖν τοῦτ’ ἔστιν;", "st": "20.134"}, {"sp": "N", "t": "τὸ δοκεῖν ἐξηπατηκέναι τοὺς ἀγαθόν τι ποιήσαντας. ὅτι μὲν τοίνυν τοῦθ’ ἕν τι τῶν αἰσχρῶν ἐστιν πάντας ἂν ἡγοῦμαι φῆσαι, ὅσῳ δ’ ὑμῖν αἴσχιον τῶν ἄλλων, ἀκούσατέ μου. ἔστιν ὑμῖν νόμος ἀρχαῖος, τῶν καλῶς δοκούντων ἔχειν, ἄν τις ὑποσχόμενός τι τὸν δῆμον ἐξαπατήσῃ, κρίνειν, κἂν ἁλῷ, θανάτῳ ζημιοῦν. εἶτ’ οὐκ αἰσχύνεσθ’, ὦ ἄνδρες Ἀθηναῖοι, εἰ ἐφ’ ᾧ τοῖς ἄλλοις θάνατον ζημίαν ἐτάξατε, τοῦτ’ αὐτοὶ ποιοῦντες φανήσεσθε; καὶ μὴν πάντα μὲν εὐλαβεῖσθαι δεῖ ποιεῖν τὰ δοκοῦντα καὶ ὄντ’ αἰσχρά, μάλιστα δὲ ταῦτ’ ἐφ’ οἷς τοῖς ἄλλοις χαλεπῶς τις ἔχων ὁρᾶται· οὐδὲ γὰρ ἀμφισβήτησις καταλείπεται τὸ μὴ ταῦτα ποιεῖν ἃ πονήρ’ αὐτὸς ἔκρινεν εἶναι πρότερον.", "st": "20.135"}, {"sp": "N", "t": "ἔτι τοίνυν ὑμᾶς κἀκεῖν’ εὐλαβεῖσθαι δεῖ, ὅπως μηδὲν ὧν ἰδίᾳ φυλάξαισθ’ ἄν, τοῦτο δημοσίᾳ ποιοῦντες φανήσεσθε. ὑμῶν τοίνυν οὐδ’ ἂν εἷς οὐδὲν ὧν ἰδίᾳ τινὶ δοίη, τοῦτ’ ἀφέλοιτο πάλιν, ἀλλ’ οὐδ’ ἐπιχειρήσειεν ἄν. μὴ τοίνυν μηδὲ δημοσίᾳ τοῦτο ποιήσητε, ἀλλὰ κελεύετε τούτους τοὺς ἐροῦντας ὑπὲρ τοῦ νόμου,", "st": "20.136"}, {"sp": "N", "t": "εἴ τινα τῶν εὑρημένων τὴν δωρειὰν ἀνάξιον εἶναί φασιν ἢ μὴ πεποιηκότ’ ἐφ’ οἷς εὕρετ’ ἔχειν, ἢ ἄλλ’ ὁτιοῦν ἐγκαλοῦσίν τινι, γράφεσθαι κατὰ τὸν νόμον ὃν παρεισφέρομεν νῦν ἡμεῖς, ἢ θέντων ἡμῶν, ὥσπερ ἐγγυώμεθα καὶ φαμὲν θήσειν, ἢ θέντας αὐτούς, ὅταν πρῶτον γένωνται νομοθέται. ἔστι δ’ ἑκάστῳ τις αὐτῶν, ὡς ἔοικεν, ἐχθρός, τῷ μὲν Διόφαντος, τῷ δ’ Εὔβουλος, τῷ δ’ ἴσως ἄλλος τις.", "st": "20.137"}, {"sp": "N", "t": "εἰ δὲ τοῦτο φεύξονται καὶ μὴ ’θελήσουσι ποιεῖν, σκοπεῖτ’, ὦ ἄνδρες Ἀθηναῖοι, εἰ καλῶς ὑμῖν ἔχει, ἃ τούτων ἕκαστος ὀκνεῖ τοὺς ἐχθροὺς ἀφαιρούμενος ὀφθῆναι, ταῦθ’ ὑμᾶς τοὺς εὐεργέτας ἀφῃρημένους φαίνεσθαι, καὶ τοὺς εὖ τι πεποιηκότας ὑμᾶς, οἷς οὐδεὶς ἂν ἐγκαλέσαι, νόμῳ τὰ δοθέντ’ ἀπολωλεκέναι δι’ ὑμῶν ἁθρόους, παρόν, εἴ τις ἄρ’ ἐστὶν ἀνάξιος, εἷς ἢ δύ’ ἢ πλείους, γραφῇ διὰ τούτων ταὐτὸ τοῦτο παθεῖν κατ’ ἄνδρα κριθέντας. ἐγὼ μὲν γὰρ οὐχ ὑπολαμβάνω ταῦτα καλῶς ἔχειν οὐδέ γ’ ἀξίως ὑμῶν.", "st": "20.138"}, {"sp": "N", "t": "[Σκοπῶ δὲ καὶ τοῦτο.] Καὶ μὴν οὐδ’ ἐκείνου γ’ ἀποστατέον τοῦ λόγου, ὅτι τῆς μὲν ἀξίας, ὅτ’ ἐδώκαμεν, ἦν δίκαιον τὴν ἐξέτασιν λαμβάνειν, ὅτε τούτων οὐδεὶς ἀντεῖπεν, μετὰ ταῦτα δ’ ἐᾶν, εἴ τι μὴ πεπόνθαθ’ ὑπ’ αὐτῶν ὕστερον κακόν. εἰ δ’ οὗτοι τοῦτο φήσουσι (δεῖξαι μὲν γὰρ οὐκ ἔχουσιν), δεῖ κεκολασμένους αὐτοὺς παρ’ αὐτὰ τἀδικήματα φαίνεσθαι. εἰ δὲ μηδενὸς ὄντος τοιούτου τὸν νόμον ποιήσετε κύριον, δόξετε φθονήσαντες, οὐχὶ πονηροὺς λαβόντες ἀφῃρῆσθαι.", "st": "20.139"}, {"sp": "N", "t": "ἔστι δὲ πάντα μὲν ὡς ἔπος εἰπεῖν ὀνείδη φευκτέον, τοῦτο δὲ πάντων μάλιστ’, ὦ ἄνδρες Ἀθηναῖοι. διὰ τί; ὅτι παντάπασι φύσεως κακίας σημεῖόν ἐστιν ὁ φθόνος, καὶ οὐκ ἔχει πρόφασιν δι’ ἣν ἂν τύχοι συγγνώμης ὁ τοῦτο πεπονθώς. εἶτα καὶ οὐδ’ ἔστιν ὄνειδος ὅτου πορρώτερόν ἐσθ’ ἡμῶν ἡ πόλις ἢ τοῦ φθονερὰ δοκεῖν εἶναι, ἁπάντων ἀπέχουσα τῶν αἰσχρῶν.", "st": "20.140"}, {"sp": "N", "t": "τεκμήρια δ’ ἡλίκα τούτου θεωρήσατε. πρῶτον μὲν μόνοι τῶν πάντων ἀνθρώπων ἐπὶ τοῖς τελευτήσασι δημοσίᾳ [καὶ ταῖς ταφαῖς ταῖς δημοσίαις] ποιεῖτε λόγους ἐπιταφίους, ἐν οἷς κοσμεῖτε τὰ τῶν ἀγαθῶν ἀνδρῶν ἔργα. καίτοι τοῦτ’ ἔστι τοὐπιτήδευμα ζηλούντων ἀρετήν, οὐ τοῖς ἐπὶ ταύτῃ τιμωμένοις φθονούντων. εἶτα μεγίστας δίδοτ’ ἐκ παντὸς τοῦ χρόνου δωρειὰς τοῖς τοὺς γυμνικοὺς νικῶσιν ἀγῶνας τοὺς στεφανίτας, καὶ οὐχ, ὅτι τῇ φύσει τούτων ὀλίγοις μέτεστιν, ἐφθονήσατε τοῖς ἔχουσιν, οὐδ’ ἐλάττους ἐνείματε τὰς τιμὰς διὰ ταῦτα. πρὸς δὲ τούτοις τοιούτοις οὖσιν οὐδεὶς πώποτε τὴν πόλιν ἡμῶν εὖ ποιῶν δοκεῖ νικῆσαι· τοσαύτας ὑπερβολὰς τῶν δωρειῶν αἷς ἀντ’ εὖ ποιεῖ, παρέσχηται.", "st": "20.141"}, {"sp": "N", "t": "ἔστι τοίνυν πάντα ταῦτ’, ὦ ἄνδρες Ἀθηναῖοι, δικαιοσύνης, ἀρετῆς, μεγαλοψυχίας ἐπιδείγματα. μὴ τοίνυν δι’ ἃ πάλαι παρὰ πάντα τὸν χρόνον ἡ πόλις εὐδοξεῖ, ταῦτ’ ἀνέλητε νῦν· μηδ’ ἵνα Λεπτίνης ἰδίᾳ τισίν, οἷς ἀηδῶς ἔχει, ἐπηρεάσῃ, τῆς πόλεως ἀφέλησθε καὶ ὑμῶν αὐτῶν ἣν διὰ παντὸς ἀεὶ τοῦ χρόνου δόξαν κέκτησθε καλήν· μηδ’ ὑπολαμβάνετ’ εἶναι τὸν ἀγῶνα τόνδ’ ὑπὲρ ἄλλου τινὸς ἢ τοῦ τῆς πόλεως ἀξιώματος, πότερον αὐτὸ δεῖ σῶν εἶναι καὶ ὅμοιον τῷ προτέρῳ, ἢ μεθεστάναι καὶ λελυμάνθαι.", "st": "20.142"}, {"sp": "N", "t": "πολλὰ δὲ θαυμάζων Λεπτίνου κατὰ τὸν νόμον, ἓν μάλιστα τεθαύμακα πάντων, εἰ ἐκεῖν’ ἠγνόηκεν, ὅτι ὥσπερ ἂν εἴ τις μεγάλας τὰς τιμωρίας τῶν ἀδικημάτων τάττοι, οὐκ ἂν αὐτός γ’ ἀδικεῖν παρεσκευάσθαι δόξαι, οὕτως, ἄν τις ἀναιρῇ τὰς τιμὰς τῶν εὐεργεσιῶν, οὐδὲν αὐτὸς ποιεῖν ἀγαθὸν παρεσκευάσθαι δόξει. εἰ μὲν τοίνυν ἠγνόησε ταῦτα (γένοιτο γὰρ ἂν καὶ τοῦτο), αὐτίκα δηλώσει· συγχωρήσεται γὰρ ὑμῖν λῦσαι περὶ ὧν αὐτὸς ἥμαρτεν. εἰ δὲ φανήσεται σπουδάζων καὶ διατεινόμενος κύριον ποιεῖν τὸν νόμον, ἐγὼ μὲν οὐκ ἔχω πῶς ἐπαινέσω, ψέγειν δ’ οὐ βούλομαι.", "st": "20.143"}, {"sp": "N", "t": "μηδὲν οὖν φιλονίκει, Λεπτίνη, μηδὲ βιάζου τοιοῦτον δι’ οὗ μήτ’ αὐτὸς δόξεις βελτίων εἶναι μήθ’ οἱ πεισθέντες σοι, ἄλλως τε καὶ γεγενημένου σοι τοῦ ἀγῶνος ἀκινδύνου. διὰ γὰρ τὸ τελευτῆσαι Βάθιππον τὸν τουτουὶ πατέρ’ Ἀψεφίωνος, ὃς αὐτὸν ἔτ’ ὄνθ’ ὑπεύθυνον ἐγράψατο, ἐξῆλθον οἱ χρόνοι, καὶ νυνὶ περὶ αὐτοῦ τοῦ νόμου πᾶς ἐσθ’ ὁ λόγος, τούτῳ δ’ οὐδείς ἐστι κίνδυνος.", "st": "20.144"}, {"sp": "N", "t": "καίτοι καὶ τοῦτ’ ἀκούω σε λέγειν, ὡς ἄρα τρεῖς σέ τινες γραψάμενοι πρότεροι τοῦδε οὐκ ἐπεξῆλθον. εἰ μὲν τοίνυν ἐγκαλῶν αὐτοῖς λέγεις ὅτι σ’ οὐ κατέστησαν εἰς κίνδυνον, φιλοκινδυνότατος πάντων ἀνθρώπων εἶ· εἰ δὲ τεκμήριον ποιεῖ τοῦ τὰ δίκαι’ εἰρηκέναι, λίαν εὔηθες ποιεῖς. τί γὰρ εἵνεκα τούτου βελτίων ἔσθ’ ὁ νόμος, εἴ τις ἢ τετελεύτηκε τῶν γραψαμένων πρὶν εἰσελθεῖν, ἢ πεισθεὶς ὑπὸ σοῦ διεγράψατο, ἢ καὶ ὅλως ὑπὸ σοῦ παρεσκευάσθη; ἀλλὰ ταῦτα μὲν οὐδὲ λέγειν καλόν.", "st": "20.145"}, {"sp": "N", "t": "ᾕρηνται δὲ τῷ νόμῳ σύνδικοι καὶ μάλισθ’ οἱ δεινοὶ λέγειν ἄνδρες, Λεωδάμας Ἀχαρνεὺς καὶ Ἀριστοφῶν Ἁζηνιεὺς καὶ Κηφισόδοτος ἐκ Κεραμέων καὶ Δεινίας Ἑρχιεύς. ἃ δὴ πρὸς τούτους ὑπολαμβάνοιτ’ ἂν εἰκότως, ἀκούσατε, καὶ σκοπεῖτ’ ἂν ὑμῖν δίκαια φαίνηται. πρῶτον μὲν πρὸς Λεωδάμαντα. οὗτος ἐγράψατο τὴν Χαβρίου δωρειάν, ἐν ᾗ τοῦτ’ ἔνεστιν τὸ τῆς ἀτελείας τῶν ἐκείνῳ τι δοθέντων, καὶ πρὸς ὑμᾶς εἰσελθὼν ἡττήθη·", "st": "20.146"}, {"sp": "N", "t": "οἱ νόμοι δ’ οὐκ ἐῶσι δὶς πρὸς τὸν αὐτὸν περὶ τῶν αὐτῶν οὔτε δίκας οὔτ’ εὐθύνας οὔτε διαδικασίαν οὔτ’ ἄλλο τοιοῦτ’ οὐδὲν εἶναι. χωρὶς δὲ τούτων ἀτοπώτατον ἂν πάντων συμβαίη, εἰ τότε μὲν τὰ Χαβρίου παρ’ ὑμῖν ἔργα μεῖζον ἴσχυε τῶν Λεωδάμαντος λόγων, ἐπειδὴ δὲ ταῦτά θ’ ὑπάρχει καὶ τὰ τῶν ἄλλων εὐεργετῶν προσγέγονεν, τηνικαῦτα σύμπαντα ταῦτ’ ἀσθενέστερα τῶν τούτου λόγων γένοιτο.", "st": "20.147"}, {"sp": "N", "t": "καὶ μὴν πρός γ’ Ἀριστοφῶντα πολλὰ καὶ δίκαι’ ἂν ἔχειν εἰπεῖν οἶμαι. οὗτος εὕρετο τὴν δωρειὰν παρ’ ὑμῖν, ἐν ᾗ τοῦτ’ ἐνῆν. καὶ οὐ τοῦτ’ ἐπιτιμῶ· δεῖ γὰρ ἐφ’ ὑμῖν εἶναι διδόναι τὰ ὑμέτερ’ αὐτῶν οἷς ἂν βούλησθε. ἀλλ’ ἐκεῖνό γ’ οὐχὶ δίκαιον εἶναί φημι, τὸ ὅτε μὲν τούτῳ ταῦτ’ ἔμελλεν ὑπάρχειν λαβόντι, μηδὲν ἡγεῖσθαι δεινόν, ἐπειδὴ δ’ ἑτέροις δέδοται, τηνικαῦτ’ ἀγανακτεῖν καὶ πείθειν ὑμᾶς ἀφελέσθαι.", "st": "20.148"}, {"sp": "N", "t": "καὶ μὴν καὶ Γελάρχῳ πέντε τάλαντ’ ἀποδοῦναι γέγραφ’ οὗτος ὡς παρασχόντι τοῖς ἐν Πειραιεῖ τοῦ δήμου, καὶ καλῶς ἐποίει. μὴ τοίνυν ἃ μὲν ἦν ἀμάρτυρα, ταῦτ’ ἐπὶ τῇ τοῦ δήμου προφάσει διὰ σοῦ δεδόσθω, ὧν δ’ αὐτὸς ὁ δῆμος μαρτυρίας ἔστησεν ἐν τοῖς ἱεροῖς ἀναγράψας καὶ πάντες συνίσασιν, ταῦτ’ ἀφελέσθαι παραίνει· μηδ’ αὑτὸς φαίνου τά τ’ ὀφειλόμεν’ ὡς ἀποδοῦναι δεῖ γράφων, καὶ ἅ τις παρὰ τοῦ δήμου κεκόμισται, ταῦτ’ ἀφελέσθαι παραινῶν.", "st": "20.149"}, {"sp": "N", "t": "καὶ μὴν πρός γε Κηφισόδοτον τοσοῦτ’ ἂν εἴποιμι. οὗτός ἐστιν οὐδενὸς ἧττον, ὦ ἄνδρες Ἀθηναῖοι, τῶν λεγόντων δεινὸς εἰπεῖν. πολὺ τοίνυν κάλλιον τῇ δεινότητι ταύτῃ χρῆσθαι ἐπὶ τὸ τοὺς ἀδικοῦντας ὑμᾶς κολάζειν ἢ τοὺς ἀγαθοῦ τινὸς αἰτίους ἀδικεῖν. εἰ γὰρ ἀπεχθάνεσθαί τισι δεῖ, τοῖς ἀδικοῦσι τὸν δῆμον, οὐ τοῖς ἀγαθόν τι ποιοῦσιν ἔγωγε νομίζω δεῖν.", "st": "20.150"}, {"sp": "N", "t": "πρὸς τοίνυν Δεινίαν· οὗτος ἴσως ἐρεῖ τριηραρχίας αὑτοῦ καὶ λῃτουργίας. ἐγὼ δ’, εἰ πολλοῦ τῇ πόλει Δεινίας ἄξιον αὑτὸν παρέσχηκεν, ὡς ἔμοιγε δοκεῖ νὴ τοὺς θεούς, μᾶλλον ἂν παραινέσαιμ’ αὑτῷ τινὰ τιμὴν ὑμᾶς ἀξιοῦν δοῦναι ἢ τὰς ἑτέροις πρότερον δοθείσας ἀφελέσθαι κελεύειν· πολὺ γὰρ βελτίονος ἀνδρός ἐστιν ἐφ’ οἷς αὐτὸς εὖ πεποίηκεν ἀξιοῦν τιμᾶσθαι ἢ ἐφ’ οἷς ἕτεροι ποιήσαντες ἐτιμήθησαν φθονεῖν.", "st": "20.151"}, {"sp": "N", "t": "ὃ δὲ δὴ μέγιστον ἁπάντων καὶ κοινὸν ὑπάρχει κατὰ πάντων τῶν συνδίκων· τούτων πολλάκις εἷς ἕκαστος πρότερόν τισι πράγμασι σύνδικος γέγονεν. ἔστι δὲ καὶ μάλ’ ἔχων νόμος ὑμῖν καλῶς, οὐκ ἐπὶ τούτοις τεθείς, ἀλλ’ ἵνα μὴ τὸ πρᾶγμ’ ὥσπερ ἐργασία τισὶν ᾖ καὶ συκοφαντία, μὴ ἐξεῖναι ὑπὸ τοῦ δήμου χειροτονηθέντα πλεῖν ἢ ἅπαξ συνδικῆσαι.", "st": "20.152"}, {"sp": "N", "t": "τοὺς δὴ συνεροῦντας νόμῳ καὶ διδάξοντας ὑμᾶς ὡς ἐπιτήδειός ἐστιν, αὐτοὺς τοῖς ὑπάρχουσι νόμοις δεῖ πειθομένους φαίνεσθαι· εἰ δὲ μή, γελοῖον νόμῳ μὲν συνδικεῖν, νόμον δ’ αὐτοὺς παραβαίνειν ἕτερον. ἀνάγνωθι λαβὼν τὸν νόμον αὐτοῖς ὃν λέγω.", "st": "20.153"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "20.153"}, {"sp": "N", "t": "οὗτος, ὦ ἄνδρες Ἀθηναῖοι, καὶ παλαιός ἐσθ’ ὁ νόμος καὶ καλῶς ἔχων, ὃν ἐὰν σωφρονῶσι φυλάξονται παραβαίνειν οὗτοι.", "st": "20.153"}, {"sp": "N", "t": "ἐγὼ δ’ ἔτι μικρὰ πρὸς ὑμᾶς εἰπὼν καταβήσομαι. ἔστι γάρ, ὦ ἄνδρες Ἀθηναῖοι, πάντας μὲν τοὺς νόμους ὑμῖν, ὡς ἐγὼ νομίζω, σπουδαστέον ὡς κάλλιστ’ ἔχειν, μάλιστα δὲ τούτους δι’ ὧν ἢ μικρὰν ἢ μεγάλην ἔστ’ εἶναι τὴν πόλιν. εἰσὶ δ’ οὗτοι τίνες; οἵ τε τοῖς ἀγαθόν τι ποιοῦσι τὰς τιμὰς διδόντες καὶ οἱ τοῖς τἀναντία πράττουσι τὰς τιμωρίας. εἰ γὰρ ἅπαντες ὡς ἀληθῶς τὰς ἐν τοῖς νόμοις ζημίας φοβούμενοι τοῦ κακόν τι ποιεῖν ἀποσταῖεν, καὶ πάντες τὰς ἐπὶ ταῖς εὐεργεσίαις δωρειὰς ζηλώσαντες ἃ χρὴ πράττειν προέλοιντο, τί κωλύει μεγίστην εἶναι τὴν πόλιν καὶ πάντας χρηστοὺς καὶ μηδέν’ εἶναι πονηρόν;", "st": "20.154"}, {"sp": "N", "t": "ὁ τοίνυν νόμος οὗτος ὁ Λεπτίνου, οὐ μόνον, ὦ ἄνδρες Ἀθηναῖοι, τοῦτ’ ἀδικεῖ, ὅτι τὰς τιμὰς ἀναιρῶν τῶν εὐεργεσιῶν ἀχρεῖον τὴν ἐπιείκειαν τοῖς φιλοτιμεῖσθαι βουλομένοις καθίστησιν, ἀλλ’ ὅτι καὶ παρανομίας δόξαν αἰσχίστην τῇ πόλει καταλείπει. ἴστε γὰρ δήπου τοῦθ’ ὅτι τῶν τὰ δεινόταθ’ ἡμᾶς ἀδικούντων ἓν ἑκάστῳ τίμημ’ ὑπάρχει διὰ τὸν νόμον, ὃς διαρρήδην λέγει “μηδὲ [ὡς χρὴ] τίμημ’ ὑπάρχειν ἐπὶ κρίσει πλέον ἢ ἕν, ὁπότερον ἂν τὸ δικαστήριον τιμήσῃ, παθεῖν ἢ ἀποτεῖσαι· ἀμφότερα δὲ μὴ ἐξέστω.”", "st": "20.155"}, {"sp": "N", "t": "ἀλλ’ οὐχ οὗτος ἐχρήσατο τούτῳ τῷ μέτρῳ, ἀλλ’ ἐάν τις ἀπαιτήσῃ χάριν ὑμᾶς, “ἄτιμος ἔστω” φησὶ “καὶ ἡ οὐσία δημοσία ἔστω.” δύο τιμήματα ταῦτα. “εἶναι δὲ καὶ ἐνδείξεις καὶ ἀπαγωγάς· ἐὰν δ’ ἁλῷ, ἔνοχος ἔστω τῷ νόμῳ ὃς κεῖται, ἐάν τις ὀφείλων ἄρχῃ τῷ δημοσίῳ.” θάνατον λέγει· τοῦτο γάρ ἐστ’ ἐπ’ ἐκείνῳ τοὐπιτίμιον. οὐκοῦν τρία τιμήματα ταῦτα. πῶς οὖν οὐ σχέτλιον καὶ δεινόν, ὦ ἄνδρες Ἀθηναῖοι, εἰ χαλεπώτερον εἶναι παρ’ ὑμῖν δόξει χάριν εὖ ποιήσαντ’ ἀπαιτεῖν ἢ τὰ δεινότατ’ ἐργαζόμενον ληφθῆναι;", "st": "20.156"}, {"sp": "N", "t": "αἰσχρός, ὦ ἄνδρες Ἀθηναῖοι, καὶ κακῶς ἔχων ὁ νόμος, καὶ ὅμοιος φθόνῳ τινὶ καὶ φιλονικίᾳ καὶ—τὸ λοιπὸν ἐῶ· τοιούτοις δέ τισιν προσέοιχ’ ὁ γράφων χρῆσθαι. ὑμῖν δ’ οὐχὶ πρέπει τὰ τοιαῦτα μιμεῖσθαι, οὐδ’ ἀνάξια φαίνεσθαι φρονοῦντας ὑμῶν αὐτῶν. φέρε γὰρ πρὸς Διός, τί μάλιστ’ ἂν ἀπευξαίμεθα πάντες, καὶ τί μάλιστ’ ἐν ἅπασι διεσπούδασται τοῖς νόμοις; ὅπως μὴ γενήσονται οἱ περὶ ἀλλήλους φόνοι, περὶ ὧν ἐξαίρετος ἡ βουλὴ φύλαξ ἡ ἐν Ἀρείῳ πάγῳ τέτακται.", "st": "20.157"}, {"sp": "N", "t": "ἐν τοίνυν τοῖς περὶ τούτων νόμοις ὁ Δράκων φοβερὸν κατασκευάζων καὶ δεινὸν τό τιν’ αὐτόχειρ’ ἄλλον ἄλλου γίγνεσθαι, καὶ γράφων χέρνιβος εἴργεσθαι τὸν ἀνδροφόνον, σπονδῶν, κρατήρων, ἱερῶν, ἀγορᾶς, πάντα τἄλλα διελθὼν οἷς μάλιστ’ ἄν τινας ᾤετ’ ἐπισχεῖν τοῦ τοιοῦτόν τι ποιεῖν, ὅμως οὐκ ἀφείλετο τὴν τοῦ δικαίου τάξιν, ἀλλ’ ἔθηκεν ἐφ’ οἷς ἐξεῖναι ἀποκτιννύναι, κἂν οὕτω τις δράσῃ, καθαρὸν διώρισεν εἶναι. εἶτ’ ἀποκτεῖναι μὲν δικαίως ἔν γε τοῖς παρ’ ὑμῖν νόμοις ἐξέσται, χάριν δ’ ἀπαιτεῖν οὔτε δικαίως οὔθ’ ὁπωσοῦν διὰ τὸν τούτου νόμον;", "st": "20.158"}, {"sp": "N", "t": "μηδαμῶς, ὦ ἄνδρες Ἀθηναῖοι· μὴ βούλεσθε δοκεῖν πλείω πεποιῆσθαι σπουδὴν ὅπως μηδενὶ τῶν εὖ τι ποιούντων ὑμᾶς χάριν ἐξέσται κομίσασθαι ἢ ὅπως μηδεὶς φόνος ἐν τῇ πόλει γενήσεται· ἀλλ’ ἀναμνησθέντες τῶν καιρῶν, παρ’ οὓς εὖ πεπονθότες εὖ πεποιήκατε τοὺς εὑρομένους, καὶ τῆς Δημοφάντου στήλης περὶ ἧς εἶπε Φορμίων, ἐν ᾗ γέγραπται καὶ ὀμώμοται, ἄν τις ἀμύνων τι πάθῃ τῇ δημοκρατίᾳ, τὰς αὐτὰς δώσειν δωρειὰς ἅσπερ Ἁρμοδίῳ καὶ Ἀριστογείτονι, καταψηφίσασθε τοῦ νόμου. οὐ γὰρ ἔνεστ’ εὐορκεῖν, εἰ μὴ τοῦτο ποιήσετε.", "st": "20.159"}, {"sp": "N", "t": "παρὰ πάντα δὲ ταῦτ’ ἐκεῖν’ ἔτ’ ἀκούσατέ μου. οὐκ ἔνι τοῦτον ἔχειν καλῶς τὸν νόμον, ὃς περὶ τῶν παρεληλυθότων καὶ τῶν μελλόντων ταὐτὰ λέγει. “μηδέν’ εἶναί” φησιν “ἀτελῆ πλὴν τῶν ἀφ’ Ἁρμοδίου καὶ Ἀριστογείτονος.” καλῶς. “μηδὲ τὸ λοιπὸν ἐξεῖναι δοῦναι.” μηδ’ ἂν τοιοῦτοί τινες γένωνται, Λεπτίνη; εἰ τὰ πρὸ τοῦ κατεμέμφου, τί; μὴ καὶ τὰ μέλλοντ’ ᾔδεις;", "st": "20.160"}, {"sp": "N", "t": "ὅτι νὴ Δία πόρρω τοῦ τι τοιοῦτον νῦν ἐλπίζειν ἐσμέν. καὶ εἴημέν γ’, ὦ ἄνδρες Ἀθηναῖοι· ἀλλὰ χρή γ’ ἀνθρώπους ὄντας τοιαῦτα καὶ λέγειν καὶ νομοθετεῖν οἷς μηδεὶς ἂν νεμεσήσαι, καὶ τἀγαθὰ μὲν προσδοκᾶν καὶ τοῖς θεοῖς εὔχεσθαι διδόναι, πάντα δ’ ἀνθρώπιν’ ἡγεῖσθαι. οὐδὲ γὰρ ἂν Λακεδαιμόνιοί ποτ’ ἤλπισαν εἰς τοιαῦτα πράγματ’ ἀφίξεσθαι, οὐδέ γ’ ἴσως Συρακόσιοι, τὸ πάλαι δημοκρατούμενοι καὶ φόρους Καρχηδονίους πραττόμενοι καὶ πάντων τῶν περὶ αὑτοὺς ἄρχοντες καὶ ναυμαχίᾳ νενικηκότες ἡμᾶς, ὑφ’ ἑνὸς γραμματέως, ὃς ὑπηρέτης ἦν, ὥς φασι, τυραννήσεσθαι.", "st": "20.161"}, {"sp": "N", "t": "οὐδέ γ’ ὁ νῦν ὢν Διονύσιος ἤλπισεν ἄν ποτ’ ἴσως πλοίῳ στρογγύλῳ καὶ στρατιώταις ὀλίγοις Δίων’ ἐλθόντ’ ἐφ’ αὑτὸν ἐκβαλεῖν τὸν τριήρεις πολλὰς καὶ ξένους καὶ πόλεις κεκτημένον. ἀλλ’, οἶμαι, τὸ μέλλον ἄδηλον πᾶσιν ἀνθρώποις, καὶ μικροὶ καιροὶ μεγάλων πραγμάτων αἴτιοι γίγνονται. διὸ δεῖ μετριάζειν ἐν ταῖς εὐπραξίαις καὶ προορωμένους τὸ μέλλον φαίνεσθαι.", "st": "20.162"}, {"sp": "N", "t": "πολλὰ δ’ ἄν τις ἔχοι λέγειν ἔτι καὶ διεξιέναι περὶ τοῦ μηδαμῇ μηδὲ καθ’ ἓν τοῦτον ἔχειν καλῶς τὸν νόμον μηδὲ συμφέρειν ὑμῖν· ἀλλ’ ἵν’ ἐν κεφαλαίῳ τοῦτο μάθητε κἀγὼ παύσωμαι λέγων, τάδε ποιήσατε· σκέψασθε παρ’ ἄλληλα καὶ λογίσασθε πρὸς ὑμᾶς αὐτοὺς τί συμβήσεται καταψηφισαμένοις ὑμῖν τοῦ νόμου καὶ τί μή· εἶτα φυλάττετε καὶ μέμνησθ’ ἃν ὑμῖν ἐξ ἑκατέρου φανῇ, ἵν’ ἕλησθε τὰ κρείττω.", "st": "20.163"}, {"sp": "N", "t": "ἂν μὲν τοίνυν καταψηφίσησθε, ὥσπερ ἡμεῖς κελεύομεν, οἱ μὲν ἄξιοι παρ’ ὑμῶν τὰ δίκαι’ ἕξουσιν, εἰ δέ τις ἔστ’ ἀνάξιος, ὡς ἔστω, πρὸς τῷ τὴν δωρειὰν ἀφαιρεθῆναι δίκην ἣν ἂν ὑμῖν δοκῇ δώσει κατὰ τὸν παρεισενηνεγμένον νόμον· ἡ δὲ πόλις πιστή, δικαία, πρὸς ἅπαντας ἀψευδὴς φανήσεται. ἐὰν δ’ ἀποψηφίσησθε, ὃ μὴ ποιήσαιτε, οἱ μὲν χρηστοὶ διὰ τοὺς φαύλους ἀδικήσονται, οἱ δ’ ἀνάξιοι συμφορᾶς ἑτέροις αἴτιοι γενήσονται, δίκην δ’ οὐδ’ ἡντινοῦν αὐτοὶ δώσουσιν, ἡ δὲ πόλις τἀναντί’ ὧν εἶπον ἀρτίως, δόξει ἄπιστος, φθονερά, φαύλη παρὰ πᾶσιν εἶναι.", "st": "20.164"}, {"sp": "N", "t": "οὔκουν ἄξιον, ὦ ἄνδρες Ἀθηναῖοι, τοσαύτην βλασφημίαν ἀντὶ καλῶν καὶ προσηκόντων ὑμῖν ἀγαθῶν ἑλέσθαι. καὶ γὰρ ἕκαστος ὑμῶν ἰδίᾳ μεθέξει τῆς δόξης τῶν κοινῇ γνωσθέντων. οὐ γὰρ ἀγνοεῖ τοῦτ’ οὐδεὶς οὔτε τῶν περιεστηκότων οὔτε τῶν ἄλλων, ὅτι ἐν μὲν τῷ δικαστηρίῳ Λεπτίνης πρὸς ἡμᾶς ἀγωνίζεται, ἐν δὲ τῇ τῶν καθημένων ὑμῶν ἑνὸς ἑκάστου γνώμῃ φιλανθρωπία πρὸς φθόνον καὶ δικαιοσύνη πρὸς κακίαν καὶ πάντα τὰ χρηστὰ πρὸς τὰ πονηρότατ’ ἀντιτάττεται.", "st": "20.165"}, {"sp": "N", "t": "ὧν τοῖς βελτίοσι πειθόμενοι καὶ κατὰ ταὔθ’ ἡμῖν θέμενοι τὴν ψῆφον, αὐτοί θ’ ἃ προσήκει δόξετ’ ἐγνωκέναι, καὶ τῇ πόλει τὰ κράτιστ’ ἔσεσθ’ ἐψηφισμένοι, κἄν τις ἄρ’ ἔλθῃ ποτὲ καιρός, οὐκ ἀπορήσετε τῶν ἐθελησόντων ὑπὲρ ὑμῶν κινδυνεύειν. ὑπὲρ οὖν τούτων ἁπάντων οἶμαι δεῖν ὑμᾶς σπουδάζειν καὶ προσέχειν τὸν νοῦν, ὅπως μὴ βιασθῆθ’ ἁμαρτάνειν. πολλὰ γὰρ ὑμεῖς, ὦ ἄνδρες Ἀθηναῖοι, πολλάκις οὐκ ἐδιδάχθηθ’ ὡς ἔστι δίκαια, ἀλλ’ ἀφῃρέθηθ’ ὑπὸ τῆς τῶν λεγόντων κραυγῆς καὶ βίας καὶ ἀναισχυντίας.", "st": "20.166"}, {"sp": "N", "t": "ὃ μὴ πάθητε νῦν· οὐ γὰρ ἄξιον. ἀλλ’ ἃ δίκαι’ ἐγνώκατε, ταῦτα φυλάξατε καὶ μνημονεύετε, ἕως ἂν ψηφίσησθε, ἵν’ εὔορκον θῆσθε τὴν ψῆφον κατὰ τῶν τὰ πονηρὰ συμβουλευόντων. θαυμάζω δ’ ἔγωγε, εἰ τοῖς μὲν τὸ νόμισμα διαφθείρουσιν θάνατος παρ’ ὑμῖν ἐστιν ἡ ζημία, τοῖς δ’ ὅλην τὴν πόλιν κίβδηλον καὶ ἄπιστον ποιοῦσι λόγον δώσετε. οὐ δή πού γ’, ὦ Ζεῦ καὶ θεοί.", "st": "20.167"}, {"sp": "N", "t": "οὐκ οἶδ’ ὅ τι δεῖ πλείω λέγειν· οἶμαι γὰρ ὑμᾶς οὐδὲν ἀγνοεῖν τῶν εἰρημένων.", "st": "20.167"}], []);})();
